  GeneralRecipe(id: "Sa-0", title: "Çoban salata", category: "Salatalar", ingredients: ["2 domates", "1 salatalık", "1 yeşil biber", "Yarım küçük soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Domates, salatalık ve biberi yıkayın.", "Domatesleri ve salatalığı küçük küp, biberi ince halka doğrayın.", "Soğanı ince piyazlık doğrayıp bir tutam tuzla ovun, durulayıp süzün; acılığı azalır.", "Tüm sebzeleri geniş bir kâseye alın.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Sosu servis etmeden hemen önce dökün ve nazikçe harmanlayın; erken eklerseniz sebzeler su salar."], minutes: 15),
  GeneralRecipe(id: "Sa-1", title: "Narlı roka salatası", category: "Salatalar", ingredients: ["1 demet roka", "Yarım su bardağı nar tanesi", "2 yemek kaşığı ceviz", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Yeşillikleri bol suda yıkayıp süzgeçte iyice süzdürün; kâğıt havluyla kurulayın.", "Rokanın kalın saplarını kesip iri parçalara ayırın.", "Cevizi kuru tavada 2 dakika hafifçe kavurup iri kırın.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Rokayı servis tabağına yayın, nar ve cevizi üzerine serpin.", "Sosu servis etmeden hemen önce dökün ve nazikçe harmanlayın; erken eklerseniz sebzeler su salar."], minutes: 15),
  GeneralRecipe(id: "Sa-2", title: "Maydanozlu nohut salatası", category: "Salatalar", ingredients: ["1,5 su bardağı haşlanmış nohut", "Yarım demet maydanoz", "1 salatalık", "1 küçük kırmızı soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Nohutları süzüp soğuk suyla durulayın.", "Salatalığı küçük küp doğrayın.", "Soğanı ince piyazlık doğrayıp bir tutam tuzla ovun, durulayıp süzün; acılığı azalır.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Tüm malzemeleri bir kâsede birleştirin.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Sosu servis etmeden hemen önce dökün ve nazikçe harmanlayın; erken eklerseniz sebzeler su salar."], minutes: 20),
  GeneralRecipe(id: "Sa-3", title: "Limonlu yeşil mercimek salatası", category: "Salatalar", ingredients: ["1 su bardağı yeşil mercimek", "Yarım demet maydanoz", "1 kapya biber", "2 yemek kaşığı zeytinyağı", "2 yemek kaşığı limon suyu"], steps: ["Yeşil mercimeği yıkayıp bol suda, dağılmadan diri kalacak şekilde 20–25 dakika haşlayın; süzüp soğutun.", "Kapya biberi küçük küp doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Mercimek, biber ve maydanozu bir kâsede birleştirin.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Sosu servis etmeden hemen önce dökün ve nazikçe harmanlayın; erken eklerseniz sebzeler su salar.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 50),
  GeneralRecipe(id: "Sa-4", title: "Salatalıklı kinoa salatası", category: "Diyet ve sağlıklı tarifler", ingredients: ["Yarım su bardağı kinoa", "1 su bardağı su", "1 salatalık", "6 cherry domates", "Yarım demet maydanoz", "2 yemek kaşığı limon suyu", "1 yemek kaşığı zeytinyağı"], steps: ["Kinoayı iyice yıkayıp suyla 15 dakika pişirin ve soğutun.", "Salatalık, domates ve maydanozu doğrayın.", "Kinoayı sebzelerle birleştirin.", "Limon ve zeytinyağıyla harmanlayın."], minutes: 30),
  GeneralRecipe(id: "Sa-5", title: "Mısırlı ton balıklı salata", category: "Salatalar", ingredients: ["1 kutu suda ton balığı", "Yarım su bardağı haşlanmış mısır", "1 salatalık", "6 cherry domates", "4 yaprak marul", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Yeşillikleri bol suda yıkayıp süzgeçte iyice süzdürün; kâğıt havluyla kurulayın.", "Marulu şerit, salatalığı yarım ay doğrayın; domatesleri ikiye kesin.", "Ton balığının suyunu süzüp çatalla iri parçalara ayırın.", "Mısırı süzün.", "Sebzeleri servis kâsesine yerleştirin, ton balığı ve mısırı üzerine ekleyin.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Sosu servis etmeden hemen önce dökün ve nazikçe harmanlayın; erken eklerseniz sebzeler su salar."], minutes: 15),
  GeneralRecipe(id: "Sa-6", title: "Naneli bulgur salatası", category: "Salatalar", ingredients: ["1 su bardağı ince bulgur", "1 su bardağı sıcak su", "2 domates", "1 salatalık", "Yarım demet taze nane", "2 yemek kaşığı limon suyu", "2 yemek kaşığı zeytinyağı"], steps: ["Bulguru geniş bir kâseye alıp sıcak suyu ekleyin; üzerini kapatıp 15 dakika şişmeye bırakın.", "Domates ve salatalığı çok küçük küp doğrayın.", "Naneyi yıkayıp ince kıyın.", "Bulguru çatalla havalandırıp sebzeleri ve naneyi ekleyin.", "Limon suyu, zeytinyağı ve tuzu ekleyip karıştırın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 40),
  GeneralRecipe(id: "Sa-7", title: "Pancar, yoğurt", category: "Salatalar", ingredients: ["2 orta boy pancar", "4 yemek kaşığı süzme yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı ceviz"], steps: ["Pancarları kabuklarıyla, üzerini geçecek kadar suda bıçak kolayca batana kadar 40–45 dakika haşlayın.", "Ilıyınca kabuklarını soyup küçük küp doğrayın ya da rendeleyin; elleriniz boyanmasın diye eldiven kullanabilirsiniz.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Cevizi kuru tavada 2 dakika hafifçe kavurup iri kırın.", "Pancarı yoğurtla karıştırın.", "Üzerine zeytinyağı gezdirip cevizi serpin.", "Soğuk servis edin."], minutes: 57),
  GeneralRecipe(id: "Sa-8", title: "Havuç, lahana", category: "Salatalar", ingredients: ["2 havuç", "2 su bardağı ince doğranmış beyaz lahana", "2 yemek kaşığı yoğurt", "1 yemek kaşığı limon suyu", "1 yemek kaşığı zeytinyağı"], steps: ["Havuçları soyup ince rendeleyin.", "Lahanayı çok ince doğrayıp bir tutam tuzla 1 dakika ovun; suyunu sıkın.", "Yoğurt, limon suyu ve zeytinyağını çırpın.", "Havuç ve lahanayı sosla harmanlayın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 26),
  GeneralRecipe(id: "Sa-9", title: "Semizotu, yoğurt", category: "Salatalar", ingredients: ["1 demet semizotu", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Semizotunun kalın saplarını ayıklayın; yapraklarını bol suda birkaç kez yıkayıp süzün ve iri doğrayın.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Semizotunu sarımsaklı yoğurtla harmanlayın.", "Servis tabağına alıp üzerine zeytinyağı gezdirin.", "Soğuk servis edin."], minutes: 15),
  GeneralRecipe(id: "Se-0", title: "Zeytinyağlı taze fasulye", category: "Sebze yemekleri", ingredients: ["500 g taze fasulye", "1 soğan", "2 domates", "3 yemek kaşığı zeytinyağı", "Yarım su bardağı sıcak su"], steps: ["Fasulyelerin uçlarını ve kenar liflerini ayıklayın; yıkayıp 3–4 cm boyunda doğrayın.", "Soğanı yarım ay, domatesleri kabuğunu soyup küp doğrayın.", "Tencerede zeytinyağını ısıtıp soğanı 3–4 dakika yumuşatın.", "Fasulyeleri ekleyip 5 dakika çevirin; rengi canlanınca domatesleri ilave edin.", "Sıcak suyu ve tuzu ekleyin; kapağı kapalı kısık ateşte fasulyeler yumuşayana kadar 35–40 dakika pişirin.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 59),
  GeneralRecipe(id: "Se-1", title: "Kabak yemeği", category: "Sebze yemekleri", ingredients: ["3 kabak", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı pirinç", "1 su bardağı su"], steps: ["Kabakları yarım ay, soğanı yemeklik doğrayın; domatesleri rendeleyin.", "Pirinci suyu berraklaşana kadar yıkayıp süzün.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Domatesi ekleyip 3 dakika pişirin.", "Kabakları, pirinci ve suyu ekleyin; kapağı kapalı kısık ateşte kabak ve pirinç yumuşayana kadar 25 dakika pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 42),
  GeneralRecipe(id: "Se-2", title: "Patlıcan musakka", category: "Sebze yemekleri", ingredients: ["2 patlıcan", "200 g kıyma", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Patlıcanları alacalı soyup doğrayın; tuzlu suda 15 dakika bekletip acısını alın, sıkıp kurulayın.", "Soğanı ince doğrayın, domatesleri küp kesin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Domatesleri ve patlıcanları ekleyip 3 dakika çevirin; suyu ilave edin.", "Kapağı kapalı kısık ateşte patlıcanlar yumuşayana kadar 25 dakika pişirin.", "Sıcak servis edin."], minutes: 65),
  GeneralRecipe(id: "Se-3", title: "Karnabahar fırın", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "3 yemek kaşığı yoğurt", "1 yumurta", "3 yemek kaşığı rendelenmiş kaşar", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Karnabaharı çiçeklerine ayırıp yıkayın.", "Karnabaharı buharda 8 dakika, hafif yumuşayana kadar ön pişirin.", "Yoğurt, yumurta ve zeytinyağını çırpıp karnabaharlarla harmanlayın; kaba yayın.", "Üzerine kaşar serpip 20 dakika, yumurta tamamen pişip üzeri kızarana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 43),
  GeneralRecipe(id: "Se-4", title: "Ispanak yemeği", category: "Sebze yemekleri", ingredients: ["500 g ıspanak", "1 soğan", "2 yemek kaşığı zeytinyağı", "2 yemek kaşığı pirinç", "Yarım su bardağı su"], steps: ["Ispanağı bol suda 2–3 kez yıkayıp toprağını iyice giderin; süzüp iri doğrayın.", "Soğanı ince doğrayın.", "Pirinci suyu berraklaşana kadar yıkayıp süzün.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Ispanağı avuç avuç ekleyip sönmesini bekleyin; pirinç ve suyu ilave edin.", "Kapağı kapalı kısık ateşte pirinç yumuşayana kadar 20 dakika pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sarımsaklı yoğurtla servis edebilirsiniz."], minutes: 34),
  GeneralRecipe(id: "Se-5", title: "Bamya yemeği", category: "Sebze yemekleri", ingredients: ["400 g bamya", "2 domates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "Yarım su bardağı su"], steps: ["Bamyaların saplarını koni biçiminde, içlerini açmadan ayıklayın; yıkayıp süzün.", "Bamyaları limon suyuyla harmanlayıp 10 dakika bekletin; salyalanmaları azalır.", "Soğanı ince doğrayın, domatesleri rendeleyin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Domatesi ekleyip 4 dakika pişirin.", "Bamyaları ve suyu ekleyin; karıştırmadan, tencereyi hafifçe sallayarak kapağı kapalı 25–30 dakika pişirin.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 58),
  GeneralRecipe(id: "Se-6", title: "Pırasa yemeği", category: "Sebze yemekleri", ingredients: ["4 pırasa", "2 havuç", "3 yemek kaşığı zeytinyağı", "2 yemek kaşığı pirinç", "1 su bardağı su", "Yarım limon"], steps: ["Pırasaların kök ve sert yeşil uçlarını kesin; boyuna yarıp katların arasındaki toprağı bol suyla yıkayın.", "Pırasaları 2 cm halka, havuçları yarım ay doğrayın.", "Pirinci suyu berraklaşana kadar yıkayıp süzün.", "Tencerede zeytinyağını ısıtıp havuçları 3 dakika soteleyin.", "Pırasaları ekleyip 5 dakika, hacmi azalana kadar çevirin.", "Pirinci ve suyu ekleyip kapağı kapalı kısık ateşte 25–30 dakika pişirin.", "Limonu sıkıp karıştırın; ılık servis edin."], minutes: 48),
  GeneralRecipe(id: "Se-7", title: "Zeytinyağlı enginar ve bezelye", category: "Sebze yemekleri", ingredients: ["4 enginar çanağı", "1 su bardağı bezelye", "1 havuç", "1 küçük soğan", "3 yemek kaşığı zeytinyağı", "1 limonun suyu", "1 su bardağı su"], steps: ["Enginar çanaklarını kararmamaları için limonlu suda bekletin.", "Soğanı yemeklik, havucu küp doğrayın.", "Tencerede zeytinyağını ısıtıp soğan ve havucu 4 dakika soteleyin.", "Bezelyeyi ekleyip 2 dakika çevirin; enginarları çanak yukarı bakacak şekilde dizin.", "Limon suyunu suyla karıştırıp dökün; kapağı kapalı kısık ateşte enginarlar yumuşayana kadar 25–30 dakika pişirin.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 46),
  GeneralRecipe(id: "Se-8", title: "Zeytinyağlı bezelye ve havuç", category: "Sebze yemekleri", ingredients: ["2 su bardağı bezelye", "2 havuç", "1 patates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Soğanı ince doğrayın, havuç ve patatesi küp kesin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Havucu ekleyip 3 dakika çevirin; patates ve bezelyeyi ilave edin.", "Sıcak suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı kapalı 25–30 dakika, sebzeler yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 47),
  GeneralRecipe(id: "Se-9", title: "Fırında kök sebzeler", category: "Sebze yemekleri", ingredients: ["2 havuç", "2 patates", "1 tatlı patates", "1 pancar", "3 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Sebzeleri soyup eşit kalınlıkta dilimleyin; pancarı ayrı tutun ki diğerlerini boyamasın.", "Sebzeleri zeytinyağı ve kekikle harmanlayın.", "Tepsiye tek kat, birbirine değmeyecek şekilde dizin.", "30–40 dakika pişirin.", "Pişirmenin yarısında sebzeleri spatulayla çevirin ki her yüzü eşit kızarsın.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir."], minutes: 50),
  GeneralRecipe(id: "Ba-0", title: "Kuru fasulye", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı kuru fasulye", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "4 su bardağı sıcak su"], steps: ["Bakliyatı ayıklayıp yıkayın; bol suda en az 8 saat ya da bir gece ıslatın.", "Islatma suyunu dökün ve bakliyatı durulayın; bu, sindirimi kolaylaştırır.", "Fasulyeleri taze suda kaynatıp köpüğünü alın; 20 dakika ön haşlayıp süzün.", "Soğanı yemeklik doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Salçayı ekleyip kokusu çıkana kadar 1 dakika kavurun.", "Fasulyeleri ve sıcak suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı kapalı 45–60 dakika, fasulyeler parmak arasında kolayca ezilene kadar pişirin.", "Tuzu bakliyat yumuşadıktan sonra ekleyin; erken eklenirse kabukları sertleşebilir.", "Ocaktan alıp 10 dakika dinlendirin; kıvamı oturur."], minutes: 105),
  GeneralRecipe(id: "Ba-1", title: "Nohut yemeği", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı kuru nohut", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "4 su bardağı sıcak su"], steps: ["Bakliyatı ayıklayıp yıkayın; bol suda en az 8 saat ya da bir gece ıslatın.", "Islatma suyunu dökün ve bakliyatı durulayın; bu, sindirimi kolaylaştırır.", "Nohutları taze suda kaynatıp köpüğünü alın; 20 dakika ön haşlayıp süzün.", "Soğanı yemeklik doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Salçayı ekleyip kokusu çıkana kadar 1 dakika kavurun.", "Nohutları ve sıcak suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı kapalı 50–70 dakika, nohutlar tamamen yumuşayana kadar pişirin.", "Tuzu bakliyat yumuşadıktan sonra ekleyin; erken eklenirse kabukları sertleşebilir.", "Ocaktan alıp 10 dakika dinlendirin; kıvamı oturur."], minutes: 115),
  GeneralRecipe(id: "Ba-2", title: "Yeşil mercimek yemeği", category: "Bakliyat yemekleri", ingredients: ["1,5 su bardağı yeşil mercimek", "1 soğan", "1 havuç", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Mercimeği ayıklayıp suyu berraklaşana kadar birkaç kez yıkayın.", "Mercimeği kaynar suda 10 dakika ön haşlayıp süzün.", "Soğanı ince, havucu küp doğrayın.", "Tencerede yağı ısıtıp soğan ve havucu 4–5 dakika soteleyin.", "Salçayı ekleyip kokusu çıkana kadar 1 dakika kavurun.", "Mercimeği ve suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı aralık 25–30 dakika, mercimek yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 56),
  GeneralRecipe(id: "Ba-3", title: "Barbunya pilaki", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış barbunya", "1 havuç", "1 patates", "1 soğan", "3 yemek kaşığı zeytinyağı", "1 domates", "1 su bardağı su"], steps: ["Soğanı yemeklik, havuç ve patatesi küp doğrayın; domatesi rendeleyin.", "Tencerede zeytinyağını ısıtıp soğanı 4 dakika yumuşatın.", "Havuç ve patatesi ekleyip 5 dakika soteleyin.", "Haşlanmış bakliyatı süzgeçte durulayıp suyunu iyice süzdürün.", "Domates, barbunya ve suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı kapalı 25 dakika, sebzeler yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Ocaktan alıp ılımaya bırakın; pilakiler ılık ya da soğuk servis edilir."], minutes: 44),
  GeneralRecipe(id: "Ba-4", title: "Kırmızı mercimek köftesi", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı kırmızı mercimek", "1 su bardağı ince bulgur", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı biber salçası", "3 dal taze soğan", "Yarım limon"], steps: ["Mercimeği ayıklayıp suyu berraklaşana kadar birkaç kez yıkayın.", "Mercimeği 2,5 su bardağı suyla kaynatın; kısık ateşte ara ara karıştırarak 20 dakika, dağılana kadar pişirin.", "Ocaktan alıp bulguru ekleyin, karıştırın ve kapağı kapalı 20 dakika dinlendirin.", "Soğanı ince doğrayın; tavada yağda 5 dakika kavurup biber salçasını ekleyin ve 1 dakika çevirin.", "Soğanlı karışımı mercimeğe katın; elinizi yakmayacak kadar ılıyınca 5 dakika yoğurun.", "Taze soğanı ince kıyın; limon suyu ve az tuzla birlikte karışıma ekleyip yoğurun.", "Islak elle avuç içinde sıkarak parmak izli köfteler şekillendirin.", "Marul yaprağı ve limonla servis edin."], minutes: 60),
  GeneralRecipe(id: "Ba-5", title: "Börülce salatası", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış börülce", "1 kırmızı biber", "3 dal taze soğan", "Yarım demet maydanoz", "2 yemek kaşığı zeytinyağı", "1 limonun suyu"], steps: ["Haşlanmış bakliyatı süzgeçte durulayıp suyunu iyice süzdürün.", "Biberi küçük küp, taze soğanı ince halka doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Zeytinyağı, limon suyu ve az tuzu küçük bir kâsede çırpın.", "Börülce, biber, taze soğan ve maydanozu geniş kapta birleştirin.", "Sosu dökün ve nazikçe harmanlayın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 25),
  GeneralRecipe(id: "Ba-6", title: "Nohutlu ıspanak", category: "Bakliyat yemekleri", ingredients: ["400 g ıspanak", "1,5 su bardağı haşlanmış nohut", "1 soğan", "1 domates", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı su"], steps: ["Ispanağı bol suda 2–3 kez yıkayıp toprağını iyice giderin; süzüp iri doğrayın.", "Soğanı ince doğrayın, domatesi küp kesin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Domatesi ekleyip 3 dakika pişirin.", "Haşlanmış bakliyatı süzgeçte durulayıp suyunu iyice süzdürün.", "Nohut ve ıspanağı ekleyip ıspanak sönene kadar karıştırın.", "Suyu ekleyin; kapağı kapalı 15–20 dakika, ıspanak yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 37),
  GeneralRecipe(id: "Ba-7", title: "Fasulye piyazı", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış kuru fasulye", "1 kırmızı soğan", "1 domates", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "1 limonun suyu"], steps: ["Haşlanmış bakliyatı süzgeçte durulayıp suyunu iyice süzdürün.", "Soğanı ince piyazlık doğrayıp bir tutam tuzla ovun, durulayıp süzün; acılığı azalır.", "Domatesi küp doğrayın; maydanozu ince kıyın.", "Zeytinyağı, limon suyu ve az tuzu küçük bir kâsede çırpın.", "Fasulye, soğan, domates ve maydanozu birleştirin.", "Sosu dökün ve nazikçe harmanlayın.", "Soğuk ya da oda sıcaklığında servis edin."], minutes: 15),
  GeneralRecipe(id: "Ba-8", title: "Mercimekli bulgur pilavı", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı pilavlık bulgur", "Yarım su bardağı yeşil mercimek", "1 soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Mercimeği ayıklayıp suyu berraklaşana kadar birkaç kez yıkayın.", "Mercimeği kaynar suda 15–20 dakika, hafif diri kalacak şekilde haşlayıp süzün.", "Bulguru bir kez yıkayıp süzün.", "Soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Bulgur ve mercimeği ekleyip 2 dakika karıştırın.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısıp kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Kapağın altına temiz bir bez koyup 10 dakika demlendirin; çatalla havalandırın.", "Yoğurtla servis edin."], minutes: 61),
  GeneralRecipe(id: "Ba-9", title: "Nohutlu kabak yemeği", category: "Bakliyat yemekleri", ingredients: ["3 kabak", "1 su bardağı haşlanmış nohut", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı su"], steps: ["Soğanı ince doğrayın; kabakları yarım ay kesin, domatesleri rendeleyin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Domatesi ekleyip 3 dakika pişirin.", "Haşlanmış bakliyatı süzgeçte durulayıp suyunu iyice süzdürün.", "Kabak ve nohudu ekleyip 2 dakika çevirin.", "Suyu ekleyin; kapağı kapalı 20–25 dakika, kabaklar yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 44),
  GeneralRecipe(id: "Ma-0", title: "Domatesli makarna", category: "Makarnalar", ingredients: ["250 g makarna", "3 domates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru fesleğen"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Domatesleri rendeleyin, sarımsağı ezin.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Geniş tavada zeytinyağını orta ateşte ısıtıp ezilmiş sarımsağı 30 saniye, yakmadan çevirin.", "Rendelenmiş domatesi ve az tuzu ekleyin; ara ara karıştırarak 10 dakika, sos koyulaşana kadar pişirin.", "Fesleğeni ekleyip 1 dakika daha pişirin.", "Makarnayı sosa ekleyin; kıvam koyuysa ayırdığınız sudan katarak 1 dakika harmanlayın.", "Sıcak servis edin."], minutes: 25),
  GeneralRecipe(id: "Ma-1", title: "Fesleğenli makarna", category: "Makarnalar", ingredients: ["250 g makarna", "1 demet fesleğen", "2 yemek kaşığı zeytinyağı", "2 yemek kaşığı ceviz", "1 diş sarımsak", "2 yemek kaşığı rendelenmiş peynir"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Fesleğen yapraklarını yıkayıp iyice kurulayın.", "Fesleğen, ceviz, sarımsak, yağ ve bir tutam tuzu mutfak robotunda koyu bir sos olana kadar çekin.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Sosu geniş bir kâseye alıp 2–3 kaşık sıcak makarna suyuyla açın.", "Makarnayı sosla harmanlayın; peyniri serpip hemen servis edin.", "Gebelikte pastörize sütten yapılmış peynir kullanın."], minutes: 25),
  GeneralRecipe(id: "Ma-2", title: "Mantarlı makarna", category: "Makarnalar", ingredients: ["250 g makarna", "250 g mantar", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "1 diş sarımsak", "Yarım çay bardağı makarna suyu"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Mantarları nemli bezle silip dilimleyin; suya yatırmayın.", "Soğanı ince doğrayın, sarımsağı ezin.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Geniş tavada yağı ısıtıp soğanı 3 dakika yumuşatın.", "Mantarları ekleyip yüksek ateşte suyunu salıp çekene kadar 6–8 dakika soteleyin.", "Sarımsağı ekleyip 1 dakika karıştırın; tuzunu ayarlayın.", "Makarnayı ve ayırdığınız makarna suyunu ekleyip 1 dakika harmanlayın.", "Sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "Ma-3", title: "Sebzeli erişte", category: "Makarnalar", ingredients: ["250 g erişte", "1 kabak", "1 havuç", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı"], steps: ["Erişteyi tuzlu kaynar suda paketteki süre kadar, yumuşayana dek haşlayıp süzün.", "Havuç, kabak ve biberi ince şeritler halinde doğrayın.", "Geniş tavada yağı ısıtıp önce havucu 3 dakika soteleyin.", "Biber ve kabağı ekleyip 5–7 dakika, sebzeler yumuşayana kadar soteleyin.", "Erişteyi ve az tuzu ekleyip 2 dakika karıştırın.", "Sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "Ma-4", title: "Bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "1 soğan", "1 domates", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Bulguru bir kez yıkayıp süzün.", "Soğanı ince doğrayın, domatesi rendeleyin.", "Tencerede yağları ısıtıp soğanı 3–4 dakika pembeleştirin.", "Domatesi ekleyip 3 dakika pişirin.", "Bulguru ekleyip yağa bulanması için 1–2 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 44),
  GeneralRecipe(id: "Ma-5", title: "Pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "1,5 su bardağı sıcak su", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı", "Yarım çay kaşığı tuz"], steps: ["Pirinci ılık tuzlu suda 20 dakika bekletin; suyu berraklaşana kadar yıkayıp süzün.", "Tencerede tereyağı ve zeytinyağını ısıtın.", "Pirinci ekleyip taneler şeffaflaşana kadar 2–3 dakika kavurun.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi en kısığa alın ve kapağı kapalı 12–15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 58),
  GeneralRecipe(id: "Ma-6", title: "Kinoalı sebze pilavı", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı kinoa", "1 havuç", "1 kabak", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı", "2 su bardağı su"], steps: ["Kinoayı ince süzgeçte bol suyla yıkayın.", "Doğranmış sebzeleri yağda 5 dakika soteleyin.", "Kinoayı ve suyu ekleyip kaynatın.", "Kapağı kapalı kısık ateşte 15 dakika pişirip 5 dakika dinlendirin."], minutes: 35),
  GeneralRecipe(id: "Ma-7", title: "Karabuğday pilavı", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı karabuğday", "1 küçük soğan", "1 havuç", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Karabuğdayı yıkayıp süzün.", "Doğranmış soğan ve havucu yağda soteleyin.", "Karabuğdayı ve sıcak suyu ekleyin.", "Kısık ateşte taneler yumuşayıp suyu çekene kadar 15-20 dakika pişirin."], minutes: 35),
  GeneralRecipe(id: "Ma-8", title: "Fırın makarna", category: "Makarnalar", ingredients: ["250 g fırın makarna", "2 su bardağı süt", "2 yemek kaşığı un", "2 yemek kaşığı tereyağı", "1 su bardağı rendelenmiş kaşar"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını yağlayın.", "Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Makarnayı paketteki süreden 2 dakika kısa, hafif diri haşlayıp süzün; fırında pişmeye devam eder.", "Küçük tencerede tereyağını eritip unu 1–2 dakika kavurun; soğuk sütü azar azar ekleyip topak kalmayana kadar çırparak koyulaştırın.", "Kaşarın yarısını sosa ekleyip eritin.", "Makarnayı sosla harmanlayıp fırın kabına yayın.", "Kalan kaşarı serpip 20–25 dakika, üzeri kızarana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 50),
  GeneralRecipe(id: "Ma-9", title: "Nohutlu kuskus", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "1 su bardağı haşlanmış nohut", "1 kırmızı biber", "1 yemek kaşığı zeytinyağı", "2 su bardağı su", "Yarım limon"], steps: ["Kuskusu kaynar suda paket süresine göre haşlayıp süzün.", "Biberi küçük doğrayıp yağda 5 dakika soteleyin.", "Nohudu ekleyip ısıtın.", "Kuskusla karıştırıp limon suyu ekleyerek servis edin."], minutes: 25),
  GeneralRecipe(id: "Ta-0", title: "Fırında tavuk, patates", category: "Tavuk yemekleri", ingredients: ["600 g tavuk baget", "3 patates", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik", "1 çay kaşığı kırmızı toz biber"], steps: ["Fırını 200°C’ye ısıtın.", "Patatesleri yıkayıp kabuklu ya da soyulmuş iri dilimleyin.", "Tavuk bagetlerin fazla yağlı derisini kesip kâğıt havluyla kurulayın.", "Bagetleri ve patatesleri yağ, kekik, toz biber ve az tuzla harmanlayın.", "Tepsiye tek kat, birbirine değmeyecek şekilde dizin.", "45–55 dakika pişirin.", "Pişirmenin yarısında tavukları ve sebzeleri çevirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Ocaktan ya da fırından alıp 3–5 dakika dinlendirin; suyu içine çekilir ve daha sulu olur."], minutes: 70),
  GeneralRecipe(id: "Ta-1", title: "Sebzeli tavuk sote", category: "Tavuk yemekleri", ingredients: ["400 g tavuk göğsü", "1 kabak", "1 kırmızı biber", "1 soğan", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu ince şeritler halinde doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Soğanı piyazlık, kabak ve biberi tavukla aynı boyda doğrayın.", "Geniş tavada yağı ısıtıp tavuğu yüksek ateşte renk alana kadar 5–6 dakika çevirin.", "Soğan ve biberi ekleyip 5 dakika soteleyin.", "Kabağı ekleyip 6–8 dakika daha, kabak diriliğini koruyarak pişirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "Ta-2", title: "Limonlu tavuk", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü", "1 limonun suyu", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik"], steps: ["Limon suyu, ezilmiş sarımsak, zeytinyağı, kekik ve az tuzu karıştırın.", "Tavuk göğsünü kalın yerinden ikiye açarak eşit kalınlığa getirin.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Tavuğu sosa iyice bulayın; kapalı kapta buzdolabında en az 20 dakika bekletin.", "Tavayı orta ateşte ısıtın; tavuğu yerleştirip 6–8 dakika dokunmadan pişirin.", "Çevirip diğer yüzünü de 6–8 dakika pişirin; kalan sosu son 2 dakikada tavaya ekleyin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Ocaktan ya da fırından alıp 3–5 dakika dinlendirin; suyu içine çekilir ve daha sulu olur."], minutes: 51),
  GeneralRecipe(id: "Ta-3", title: "Tavuklu pilav", category: "Tavuk yemekleri", ingredients: ["300 g tavuk göğsü", "1 su bardağı pirinç", "1,5 su bardağı tavuk suyu", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı"], steps: ["Tavuğu 3 su bardağı suyla tencereye alıp kaynatın; köpüğünü alın.", "Kısık ateşte 20–25 dakika, içi tamamen beyazlayana kadar haşlayın.", "Tavuğu çıkarıp didikleyin; haşlama suyunu süzüp 1,5 su bardağını ayırın.", "Pirinci suyu berraklaşana kadar yıkayıp süzün.", "Tencerede tereyağı ve zeytinyağını ısıtıp pirinci 3 dakika kavurun.", "Sıcak tavuk suyunu ekleyin; kaynayınca ateşi en kısığa alın ve kapağı kapalı 12–15 dakika pişirin.", "Didiklenmiş tavuğu üzerine yayın; kapağın altına bez koyup 10 dakika demlendirin.", "Çatalla havalandırarak sıcak servis edin."], minutes: 63),
  GeneralRecipe(id: "Ta-4", title: "Tavuklu makarna", category: "Tavuk yemekleri", ingredients: ["300 g tavuk göğsü", "250 g makarna", "2 domates", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu küçük küp doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Makarnayı tuzlu kaynar suda paketteki süre kadar haşlayın; bir kepçe suyunu ayırıp süzün.", "Tavada yağı ısıtıp tavuğu 6–7 dakika, her tarafı beyazlayana kadar soteleyin.", "Ezilmiş sarımsağı ekleyip 30 saniye çevirin.", "Rendelenmiş domatesi ekleyip 8 dakika kaynatın.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Makarnayı sosa ekleyin; kıvam koyuysa ayırdığınız sudan katarak harmanlayın.", "Sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "Ta-5", title: "Tavuk şiş", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü", "1 kırmızı biber", "1 yeşil biber", "2 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik"], steps: ["Tavuğu 3 cm küp, biberleri benzer büyüklükte doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Yoğurt, yağ, kekik ve az tuzu karıştırıp tavuğa bulayın; buzdolabında 30 dakika bekletin.", "Tahta şiş kullanacaksanız 20 dakika suda bekletin; fırında yanmaz.", "Fırını 200°C’ye ısıtın. Tepsiye yağlı kâğıt serin.", "Tavuk ve biberleri şişlere sırayla, çok sıkıştırmadan dizin.", "20–25 dakika pişirin; yarısında şişleri çevirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 85),
  GeneralRecipe(id: "Ta-6", title: "Yoğurtlu tavuk", category: "Tavuk yemekleri", ingredients: ["400 g tavuk göğsü", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı kırmızı biber"], steps: ["Tavuğu küçük küp doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Tavada yağın yarısını ısıtıp tavuğu 8–10 dakika, tamamen pişene kadar soteleyin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Yoğurdu ezilmiş sarımsak ve az tuzla çırpın.", "Tavuğu 3 dakika dinlendirip servis tabağına alın ve yoğurdu üzerine dökün.", "Kalan yağı küçük tavada ısıtıp kırmızı biberi 10 saniye çevirin; yakmadan yoğurdun üzerine gezdirin."], minutes: 30),
  GeneralRecipe(id: "Ta-7", title: "Tavuklu sebze güveç", category: "Tavuk yemekleri", ingredients: ["500 g tavuk but kuşbaşı", "2 patates", "1 patlıcan", "2 domates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Fırını 190°C’ye ısıtın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Patlıcanı alacalı soyup küp doğrayın; tuzlu suda 15 dakika bekletip sıkın.", "Patates, domates ve soğanı tavukla eş boyda doğrayın.", "Tavuk ve sebzeleri güveç kabına alın; yağ, az tuz ve sıcak suyu ekleyip karıştırın.", "Kapağı ya da folyosu kapalı 40 dakika pişirin.", "Kapağı açıp 15 dakika daha, üzeri hafif kızarana kadar pişirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Ocaktan ya da fırından alıp 3–5 dakika dinlendirin; suyu içine çekilir ve daha sulu olur."], minutes: 85),
  GeneralRecipe(id: "Ta-8", title: "Tavuk köftesi", category: "Tavuk yemekleri", ingredients: ["500 g tavuk kıyması", "1 küçük soğan", "1 yumurta", "3 yemek kaşığı galeta unu", "1 yemek kaşığı zeytinyağı", "Yarım demet maydanoz"], steps: ["Fırını 200°C’ye ısıtın. Tepsiye yağlı kâğıt serin.", "Soğanı rendeleyip suyunu sıkın; maydanozu ince kıyın.", "Tavuk kıyması, yumurta, galeta unu, soğan, maydanoz ve az tuzu 2–3 dakika yoğurun.", "Karışımı buzdolabında 15 dakika dinlendirin; şekil vermesi kolaylaşır.", "Islak elle ceviz büyüklüğünde köfteler şekillendirip tepsiye aralıklı dizin.", "Üzerlerine fırçayla az yağ sürün.", "20–25 dakika pişirin.", "Pişirmenin yarısında köfteleri çevirin ki iki yüzü de kızarsın.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı."], minutes: 53),
  GeneralRecipe(id: "Ta-9", title: "Tavuklu dürüm", category: "Tavuk yemekleri", ingredients: ["350 g tavuk göğsü", "4 lavaş", "1 kırmızı biber", "1 küçük soğan", "2 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı"], steps: ["Tavuğu ince şeritler halinde doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Soğan ve biberi ince şerit doğrayın.", "Tavada yağı ısıtıp tavuğu yüksek ateşte 6–7 dakika soteleyin.", "Soğan ve biberi ekleyip 4–5 dakika daha pişirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Lavaşları kuru tavada her yüzü 20 saniye ısıtın.", "Lavaşlara yoğurt sürüp tavuklu karışımı koyun; kenarları içe katlayıp sıkıca sarın."], minutes: 30),
  GeneralRecipe(id: "Et-0", title: "Izgara köfte", category: "Et yemekleri", ingredients: ["500 g orta yağlı dana kıyma", "1 küçük soğan", "2 yemek kaşığı galeta unu", "1 yumurta", "1 çay kaşığı kimyon"], steps: ["Soğanı rendeleyip suyunu iyice sıkın.", "Kıyma, soğan, yumurta, galeta unu ve kimyonu, az tuzla birlikte 3–4 dakika, macun kıvamına gelene kadar yoğurun.", "Harcı buzdolabında 20 dakika dinlendirin; şekil vermesi kolaylaşır ve pişerken dağılmaz.", "Islak elle köfteleri 1,5 cm kalınlığında yassı şekillendirin.", "Izgarayı ya da döküm tavayı orta-yüksek ateşte iyice ısıtıp hafifçe yağlayın.", "Köfteleri her yüzü 4–5 dakika, alevi çok yüksek tutmadan pişirin.", "Bir köfteyi ortadan bölüp kontrol edin: içi pembe kalmamalı; termometre varsa en az 71°C olmalı.", "Sıcak servis edin."], minutes: 45),
  GeneralRecipe(id: "Et-1", title: "Fırında köfte", category: "Et yemekleri", ingredients: ["500 g dana kıyma", "1 soğan", "1 yumurta", "3 yemek kaşığı galeta unu", "2 patates", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 200°C’ye ısıtın.", "Patatesleri elma dilim kesip yağ ve az tuzla harmanlayın.", "Soğanı rendeleyip suyunu iyice sıkın.", "Kıyma, soğan, yumurta, galeta unu ve az tuzu 3–4 dakika, macun kıvamına gelene kadar yoğurun.", "Islak elle eşit büyüklükte köfteler şekillendirin.", "Köfte ve patatesleri tepsiye birbirine değmeyecek şekilde yerleştirin.", "30–35 dakika pişirin.", "Pişirmenin yarısında köfteleri çevirin ki iki yüzü de kızarsın.", "Bir köfteyi ortadan bölüp kontrol edin: içi pembe kalmamalı; termometre varsa en az 71°C olmalı."], minutes: 50),
  GeneralRecipe(id: "Et-2", title: "Etli türlü", category: "Et yemekleri", ingredients: ["400 g dana kuşbaşı", "1 patlıcan", "1 kabak", "2 patates", "2 domates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Eti kâğıt havluyla kurulayın; kuru et daha iyi renk alır.", "Tencereyi yüksek ateşte iyice ısıtıp yağı ekleyin; eti kalabalık etmeden, her yüzü renk alana kadar 5–6 dakika mühürleyin.", "Soğanı ekleyip 4 dakika yumuşatın.", "Sıcak suyu ekleyin; kapağı kapalı kısık ateşte 35–45 dakika pişirin.", "Patlıcanları alacalı soyup doğrayın; tuzlu suda 15 dakika bekletip acısını alın, sıkıp kurulayın.", "Patates, kabak ve domatesi etle aynı boyda doğrayın.", "Sebzeleri ekleyin; gerekirse yarım su bardağı sıcak su daha ilave edin.", "Kapağı kapalı 25 dakika, sebzeler ve et tamamen yumuşayana kadar pişirin.", "Bir parça eti çatalla kontrol edin: kolayca dağılıyorsa yumuşamıştır; sertse 10’ar dakika daha pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 105),
  GeneralRecipe(id: "Et-3", title: "Et sote", category: "Et yemekleri", ingredients: ["500 g dana kuşbaşı", "1 soğan", "2 sivri biber", "2 domates", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı sıcak su"], steps: ["Eti kâğıt havluyla kurulayın; kuru et daha iyi renk alır.", "Tencereyi yüksek ateşte iyice ısıtıp yağı ekleyin; eti kalabalık etmeden, her yüzü renk alana kadar 5–6 dakika mühürleyin.", "Soğanı piyazlık, biberleri halka doğrayın; domatesleri rendeleyin.", "Soğan ve biberleri ekleyip 5 dakika soteleyin.", "Domates ve sıcak suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı kapalı 35–50 dakika, et yumuşayana kadar pişirin.", "Bir parça eti çatalla kontrol edin: kolayca dağılıyorsa yumuşamıştır; sertse 10’ar dakika daha pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 71),
  GeneralRecipe(id: "Et-4", title: "Etli nohut", category: "Et yemekleri", ingredients: ["300 g dana kuşbaşı", "2 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Eti kâğıt havluyla kurulayın; kuru et daha iyi renk alır.", "Tencereyi yüksek ateşte iyice ısıtıp yağı ekleyin; eti kalabalık etmeden, her yüzü renk alana kadar 5–6 dakika mühürleyin.", "Soğanı ince doğrayıp ekleyin ve 4 dakika kavurun.", "Salçayı ekleyip 1 dakika karıştırın; sıcak suyu ilave edin.", "Kapağı kapalı kısık ateşte 35–45 dakika, et yumuşayana kadar pişirin.", "Bir parça eti çatalla kontrol edin: kolayca dağılıyorsa yumuşamıştır; sertse 10’ar dakika daha pişirin.", "Haşlanmış nohudu ekleyip 15 dakika daha kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 81),
  GeneralRecipe(id: "Et-5", title: "Kıymalı kabak", category: "Et yemekleri", ingredients: ["300 g dana kıyma", "3 kabak", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı sıcak su"], steps: ["Soğanı ince doğrayın, domatesleri rendeleyin; kabakları yarım ay kesin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Domatesi ekleyip 3 dakika pişirin.", "Kabakları ve sıcak suyu ekleyin.", "Kapağı kapalı kısık ateşte 20–25 dakika, kabaklar yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 50),
  GeneralRecipe(id: "Et-6", title: "Kıymalı ıspanak", category: "Et yemekleri", ingredients: ["300 g dana kıyma", "500 g ıspanak", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı su"], steps: ["Ispanağı bol suda 2–3 kez yıkayıp toprağını iyice giderin; süzüp iri doğrayın.", "Soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Salçayı ekleyip 1 dakika kavurun.", "Ispanağı avuç avuç ekleyip hacmi azalana kadar karıştırın.", "Suyu ekleyip kapağı kapalı 12–15 dakika pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Yoğurtla sıcak servis edin."], minutes: 38),
  GeneralRecipe(id: "Et-7", title: "Mantarlı et sote", category: "Et yemekleri", ingredients: ["400 g dana kuşbaşı", "300 g mantar", "1 soğan", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı sıcak su"], steps: ["Eti kâğıt havluyla kurulayın; kuru et daha iyi renk alır.", "Tencereyi yüksek ateşte iyice ısıtıp yağı ekleyin; eti kalabalık etmeden, her yüzü renk alana kadar 5–6 dakika mühürleyin.", "Sıcak suyu ekleyin; kapağı kapalı kısık ateşte 40–45 dakika, et yumuşayana kadar pişirin.", "Bir parça eti çatalla kontrol edin: kolayca dağılıyorsa yumuşamıştır; sertse 10’ar dakika daha pişirin.", "Mantarları nemli bezle silip dilimleyin; soğanı piyazlık, biberi şerit doğrayın.", "Soğan ve biberi ekleyip 4 dakika çevirin.", "Mantarları ekleyip kapağı açık, yüksek ateşte suyu çekilene kadar 10–12 dakika soteleyin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 77),
  GeneralRecipe(id: "Et-8", title: "Fırında kıymalı patlıcan", category: "Et yemekleri", ingredients: ["400 g dana kıyma", "2 patlıcan", "2 domates", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 200°C’ye ısıtın.", "Patlıcanları alacalı soyup küp doğrayın; tuzlu suda 15 dakika bekletip acısını alın, sıkıp kurulayın.", "Patlıcanları yağın yarısıyla harmanlayıp tepside 20 dakika yumuşatın.", "Soğanı ince doğrayın, domatesleri rendeleyin.", "Tavada kalan yağı ısıtıp soğanı 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Salça ve domatesi ekleyip 10 dakika kaynatın.", "Patlıcanları fırın kabına alıp kıymalı sosla harmanlayın.", "Fırını 190°C’ye düşürüp 10 dakika daha pişirin.", "Sıcak servis edin."], minutes: 77),
  GeneralRecipe(id: "Et-9", title: "Patatesli havuçlu et yemeği", category: "Et yemekleri", ingredients: ["500 g dana kuşbaşı", "2 patates", "2 havuç", "1 soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Eti kâğıt havluyla kurulayın; kuru et daha iyi renk alır.", "Tencereyi yüksek ateşte iyice ısıtıp yağı ekleyin; eti kalabalık etmeden, her yüzü renk alana kadar 5–6 dakika mühürleyin.", "Soğanı doğrayıp ekleyin ve 4 dakika kavurun.", "Sıcak suyu ilave edin; kapağı kapalı kısık ateşte 35–45 dakika pişirin.", "Patates ve havucu küp doğrayın.", "Sebzeleri ekleyip 20–25 dakika, sebzeler ve et tamamen yumuşayana kadar pişirin.", "Bir parça eti çatalla kontrol edin: kolayca dağılıyorsa yumuşamıştır; sertse 10’ar dakika daha pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 90),
  GeneralRecipe(id: "Ba-0-unique-1", title: "Fırında somon", category: "Balık ve deniz ürünleri", ingredients: ["4 dilim somon fileto (her biri yaklaşık 150 g)", "2 yemek kaşığı zeytinyağı", "1 limon (suyu ve rendelenmiş kabuğu)", "2 diş sarımsak (ince kıyılmış)", "1 çay kaşığı kuru kekik", "Yarım demet dereotu (ince kıyılmış)", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Fırını 200 °C'ye (fanlı 190 °C) ısıtın ve fırın tepsisine pişirme kâğıdı serin.", "Somonları soğuk suyla durulayıp kâğıt havluyla iyice kurulayın; derili tarafı alta gelecek şekilde tepsiye dizin.", "Küçük bir kasede zeytinyağı, limon suyu, limon kabuğu, sarımsak, kekik, tuz ve karabiberi karıştırın.", "Sosu fırça yardımıyla somonların üzerine eşit şekilde sürün ve 10 dakika dinlendirin.", "Somonları fırının orta rafında 15–18 dakika, eti çatalla kolayca ayrılana ve iç sıcaklığı 63 °C olana kadar pişirin.", "Fırından çıkarınca üzerine dereotu serpin ve 2 dakika dinlendirip servis edin."], minutes: 28, servings: 4, prepMinutes: 10, cookMinutes: 18, difficulty: "Kolay", ovenCelsius: 200, tips: ["Kalın filetolar için süreyi 3–4 dakika uzatın; ince filetolar 12 dakikada pişer.", "Somonu pişirmeden 15 dakika önce buzdolabından çıkarırsanız daha eşit pişer."], serving: "Fırında sebze, bulgur pilavı veya roka salatası ile sıcak servis edin.", storage: "Buzdolabında kapalı kapta en fazla 1 gün saklayın; soğuk olarak salataya da eklenebilir."),
  GeneralRecipe(id: "Ba-1-unique-2", title: "Izgara levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 adet porsiyonluk levrek (temizlenmiş, her biri 350–400 g)", "3 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "3 dal taze kekik veya 1 çay kaşığı kuru kekik", "1 küçük kırmızı soğan (garnitür için)", "Yarım demet roka (garnitür için)"], steps: ["Levrekleri iç ve dış yüzeyleriyle yıkayıp kâğıt havluyla kurulayın; derisine her iki yüzden 3'er çapraz çizik atın.", "Balığın içini ve dışını tuz, karabiber ve 2 yemek kaşığı zeytinyağı ile ovun; karnına 2 dilim limon ve kekik dallarını yerleştirin.", "Izgara tavasını veya mangal ızgarasını yüksek ateşte iyice kızdırın, ızgarayı kalan yağla yağlayın.", "Levrekleri ızgaraya koyup ilk 5–6 dakika hiç oynatmadan pişirin; derisi kolayca ayrılınca geniş spatulayla çevirin.", "Diğer yüzünü de 5–6 dakika pişirin; sırt kısmındaki et kılçıktan kolayca ayrılıyorsa balık pişmiştir.", "Halka doğranmış kırmızı soğan ve roka ile servis tabağına alın, üzerine limon sıkın."], minutes: 27, servings: 2, prepMinutes: 15, cookMinutes: 12, difficulty: "Orta", tips: ["Izgara yeterince kızgın değilse deri yapışır; balığı koymadan önce ızgaranın tütmeye başlamasını bekleyin.", "Balığı çevirirken iki spatula kullanmak dağılmasını önler."], serving: "Roka-soğan salatası, közlenmiş biber ve limon dilimleriyle hemen servis edin.", storage: "Izgara balık bekletilmez; artarsa kılçığını ayıklayıp buzdolabında 1 gün saklayın."),
  GeneralRecipe(id: "Ba-2-unique-3", title: "Fırında çipura", category: "Balık ve deniz ürünleri", ingredients: ["2 adet porsiyonluk çipura (temizlenmiş)", "2 orta boy patates (ince halka)", "1 kırmızı soğan (ince halka)", "1 domates (halka)", "3 yemek kaşığı zeytinyağı", "1 limon", "2 diş sarımsak (dilimlenmiş)", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "Yarım demet maydanoz"], steps: ["Fırını 200 °C'ye ısıtın.", "Patates ve soğan halkalarını fırın kabına yayın, 1 yemek kaşığı zeytinyağı ve bir tutam tuzla harmanlayıp fırında 10 dakika ön pişirin.", "Bu sırada çipuraları kurulayıp her iki yüzüne 2'şer çizik atın; içini ve dışını tuz, karabiber ve kalan zeytinyağıyla ovun.", "Balıkların karnına sarımsak dilimleri, maydanoz sapları ve 2 dilim limon yerleştirin.", "Ön pişmiş patateslerin üzerine domates halkalarını, onların üzerine çipuraları yerleştirin.", "Fırında 20–25 dakika, sırt kısmındaki et kemikten kolayca ayrılana kadar pişirin; üzerine kıyılmış maydanoz serpip servis edin."], minutes: 40, servings: 2, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Patatesleri önceden pişirmek, balık kurumadan patateslerin yumuşamasını sağlar.", "Balığın gözü beyazlaşıp dışarı çıkıyorsa pişmiştir."], serving: "Altındaki patates ve domateslerle birlikte, yanında yeşil salata ile servis edin.", storage: "Buzdolabında kapalı kapta en fazla 1 gün saklayın."),
  GeneralRecipe(id: "Ba-3-unique-4", title: "Sebzeli alabalık", category: "Balık ve deniz ürünleri", ingredients: ["2 adet alabalık (temizlenmiş)", "1 havuç (jülyen doğranmış)", "1 kabak (jülyen doğranmış)", "1 kırmızı kapya biber (ince şerit)", "1 küçük soğan (ince piyaz)", "3 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "1 çay kaşığı kuru kekik"], steps: ["Fırını 190 °C'ye ısıtın; iki ayrı büyük parça yağlı kâğıt hazırlayın.", "Havuç, kabak, biber ve soğanı 1 yemek kaşığı zeytinyağı, kekik ve yarım çay kaşığı tuzla harmanlayın.", "Sebzelerin yarısını her kâğıdın ortasına yayın; alabalıkları tuz ve karabiberle ovup sebzelerin üzerine koyun.", "Balıkların üzerine kalan zeytinyağını gezdirin, 2'şer dilim limon yerleştirin.", "Kâğıtların kenarlarını katlayarak kapalı paketler hâline getirin, tepsiye dizin.", "Fırında 22–25 dakika pişirin; paketi dikkatle açın, buhar çıkarken yüzünüzü yaklaştırmayın ve servis edin."], minutes: 40, servings: 2, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 190, tips: ["Kâğıt içinde pişirme balığın kendi buharında pişmesini sağlar, kurumasını önler.", "Sebzeleri ince doğrayın ki balıkla aynı sürede pişsin."], serving: "Paketi tabakta açarak, yanında haşlanmış patates veya bulgur pilavı ile servis edin.", storage: "Buzdolabında 1 gün saklayın; ısıtmak yerine soğuk tüketmek daha iyidir."),
  GeneralRecipe(id: "Ba-4-unique-5", title: "Limonlu mezgit", category: "Balık ve deniz ürünleri", ingredients: ["500 g mezgit fileto", "4 yemek kaşığı un", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı tereyağı", "1 limon (suyu)", "1 diş sarımsak (ezilmiş)", "2 yemek kaşığı kıyılmış maydanoz", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Mezgit filetolarını kâğıt havluyla kurulayın, tuz ve karabiberle tatlandırın.", "Filetoları una bulayıp fazla ununu silkeleyin.", "Geniş bir tavada zeytinyağını orta-yüksek ateşte ısıtın; filetoları tek kat hâlinde dizip her yüzünü 2–3 dakika altın rengi olana kadar pişirin ve tabağa alın.", "Ateşi kısıp tavaya tereyağı ve sarımsağı ekleyin, 30 saniye kokusu çıkana kadar karıştırın.", "Limon suyunu ekleyip tavanın dibini sıyırarak 1 dakika kaynatın, maydanozu ilave edin.", "Limonlu sosu balıkların üzerine gezdirip hemen servis edin."], minutes: 22, servings: 3, prepMinutes: 10, cookMinutes: 12, difficulty: "Kolay", tips: ["Mezgit çok yumuşak bir balıktır; tavada yalnızca bir kez çevirin.", "Tava kalabalık olursa balık kızarmaz, haşlanır; gerekirse iki partide pişirin."], serving: "Patates püresi veya mevsim salatası ile sıcak servis edin.", storage: "Aynı gün tüketilmesi önerilir; buzdolabında en fazla 1 gün saklayın."),
  GeneralRecipe(id: "Ba-5-unique-6", title: "Balık köftesi", category: "Balık ve deniz ürünleri", ingredients: ["400 g pişmiş ve kılçığı ayıklanmış beyaz balık (mezgit, levrek veya hamsi)", "1 orta boy haşlanmış patates", "1 yumurta", "1 küçük soğan (rendelenmiş, suyu sıkılmış)", "Yarım demet maydanoz (ince kıyılmış)", "Yarım demet dereotu (ince kıyılmış)", "4 yemek kaşığı galeta unu", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "Yarım çay kaşığı kimyon", "4 yemek kaşığı ayçiçek yağı (kızartmak için)"], steps: ["Pişmiş balığı geniş bir kaba alıp parmaklarınızla ufalayın, kalan kılçık olmadığından emin olun.", "Patatesi çatalla ezip balığa ekleyin; yumurta, soğan, maydanoz, dereotu, tuz, karabiber ve kimyonu ilave edin.", "Karışımı yoğurun; 2 yemek kaşığı galeta ununu ekleyip ele yapışmayan bir kıvam elde edin.", "Ceviz büyüklüğünde parçalar alıp yassı köfteler şekillendirin, kalan galeta ununa bulayın ve 15 dakika buzdolabında dinlendirin.", "Yağı tavada orta ateşte ısıtın; köfteleri her yüzü 3–4 dakika altın rengi olana kadar pişirin.", "Fazla yağını kâğıt havluda alıp sıcak servis edin."], minutes: 40, servings: 4, prepMinutes: 25, cookMinutes: 15, difficulty: "Orta", tips: ["Buzdolabında dinlendirmek köftelerin pişerken dağılmasını önler.", "Daha hafif bir seçenek için köfteleri 200 °C fırında, yağlı kâğıt üzerinde 18–20 dakika pişirebilirsiniz."], serving: "Yoğurtlu dereotlu sos ve yeşil salata ile servis edin.", storage: "Pişmiş köfteler buzdolabında 1 gün saklanır; çiğ köfteler dondurucuda 1 ay saklanabilir."),
  GeneralRecipe(id: "Ba-6-unique-7", title: "Fırında uskumru", category: "Balık ve deniz ürünleri", ingredients: ["2 adet uskumru (temizlenmiş, kelebek açılmış)", "1 kırmızı soğan (ince halka)", "1 domates (küp doğranmış)", "2 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı pul biber", "1 çay kaşığı tuz", "Yarım demet maydanoz"], steps: ["Fırını 200 °C'ye ısıtın, tepsiye yağlı kâğıt serin.", "Uskumruları açık hâlde, derisi alta gelecek şekilde tepsiye yerleştirin; tuz ve pul biber serpin.", "Soğan halkalarını ve domates küplerini balıkların üzerine dağıtın.", "Zeytinyağını gezdirin ve yarım limonun suyunu sıkın.", "Fırında 18–20 dakika, et matlaşıp kolayca ayrılana kadar pişirin.", "Kıyılmış maydanoz ve kalan limon dilimleriyle servis edin."], minutes: 30, servings: 2, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 200, tips: ["Uskumru yağlı bir balıktır; ekstra yağ eklemeyin.", "Kılçıkları pişirmeden önce cımbızla almak servis sırasında kolaylık sağlar."], serving: "Ekmek arasında veya roka salatası ile servis edin.", storage: "Buzdolabında en fazla 1 gün saklayın."),
  GeneralRecipe(id: "Ba-7-unique-8", title: "Somonlu makarna", category: "Balık ve deniz ürünleri", ingredients: ["300 g penne makarna", "250 g somon fileto (derisiz, küp doğranmış)", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı tereyağı", "2 diş sarımsak (ince kıyılmış)", "200 ml sıvı krema (veya 1 su bardağı süt + 1 yemek kaşığı un)", "Yarım limonun rendelenmiş kabuğu", "Yarım demet dereotu", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Makarnayı bol tuzlu kaynar suda paketteki süreden 1 dakika eksik haşlayın; süzmeden önce 1 çay bardağı haşlama suyu ayırın.", "Geniş bir tavada zeytinyağı ve tereyağını ısıtın; sarımsağı 30 saniye kavurun.", "Somon küplerini ekleyip 3–4 dakika, tüm yüzleri açık renge dönene kadar nazikçe çevirin.", "Kremayı ve limon kabuğunu ekleyin; tuz ve karabiberle tatlandırıp 2 dakika kısık ateşte kaynatın.", "Süzülmüş makarnayı tavaya alın, sos kıvamını ayırdığınız haşlama suyuyla ayarlayarak 1 dakika karıştırın.", "Ocaktan alıp kıyılmış dereotunu ekleyin ve hemen servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Somonu fazla karıştırmayın; parçalar bütün kalırsa daha güzel görünür.", "Kremayı kaynatmadan, hafif fokurdayacak şekilde ısıtın."], serving: "Üzerine taze çekilmiş karabiber ve limon dilimiyle servis edin.", storage: "Buzdolabında 1 gün saklanır; ısıtırken bir kaşık süt ekleyin."),
  GeneralRecipe(id: "Ba-8-unique-9", title: "Balıklı sebze güveç", category: "Balık ve deniz ürünleri", ingredients: ["600 g beyaz balık fileto (levrek, mezgit veya hamsi dışı bir balık; iri parçalar)", "2 patates (küp)", "1 kabak (yarım ay)", "1 kırmızı kapya biber (şerit)", "2 yeşil biber (halka)", "1 soğan (piyaz)", "2 domates (rendelenmiş)", "1 yemek kaşığı domates salçası", "3 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "1 çay kaşığı tuz", "1 çay kaşığı kekik", "Yarım çay kaşığı karabiber"], steps: ["Fırını 190 °C'ye ısıtın.", "Tavada zeytinyağıyla soğanı 3 dakika yumuşatın, salçayı ekleyip 1 dakika kavurun; rendelenmiş domatesi ve sıcak suyu ilave edip 3 dakika kaynatın.", "Patates, kabak ve biberleri güveç kabına yayın, tuz ve kekik serpin; domatesli sosun yarısını üzerine dökün.", "Güveci folyoyla kapatıp fırında 20 dakika, patatesler yarı yumuşayana kadar pişirin.", "Balık parçalarını tuz ve karabiberle tatlandırıp sebzelerin arasına yerleştirin, kalan sosu üzerine gezdirin.", "Folyosuz olarak 12–15 dakika daha, balık beyazlaşıp kolayca dağılana kadar pişirin ve 5 dakika dinlendirip servis edin."], minutes: 55, servings: 4, prepMinutes: 20, cookMinutes: 35, difficulty: "Orta", ovenCelsius: 190, tips: ["Balığı sebzelerle birlikte başta koyarsanız fazla pişip dağılır; son 15 dakikada ekleyin.", "Toprak güveç kullanıyorsanız soğuk fırına koyup birlikte ısıtın, aksi hâlde çatlayabilir."], serving: "Güvecin içinde, yanında taze ekmekle sıcak servis edin.", storage: "Buzdolabında kapalı kapta 1 gün saklayın; bir kez ısıtın."),
  GeneralRecipe(id: "Ba-9-unique-10", title: "Ton balıklı makarna", category: "Balık ve deniz ürünleri", ingredients: ["300 g spagetti veya burgu makarna", "2 kutu suda ton balığı (süzülmüş, toplam yaklaşık 300 g)", "2 yemek kaşığı zeytinyağı", "2 diş sarımsak (ince kıyılmış)", "400 g doğranmış konserve domates veya 3 rendelenmiş domates", "10 adet siyah zeytin (halka)", "1 yemek kaşığı kapari (isteğe bağlı)", "Yarım çay kaşığı pul biber", "Yarım çay kaşığı tuz", "Yarım demet maydanoz"], steps: ["Makarnayı bol tuzlu suda paket süresine göre haşlayıp süzün.", "Bu sırada tavada zeytinyağıyla sarımsak ve pul biberi 30 saniye kavurun.", "Domatesi ekleyip orta ateşte 8 dakika, sos koyulaşana kadar pişirin; tuzu ayarlayın.", "Ton balığı, zeytin ve kapariyi ekleyip 2 dakika daha ısıtın; ton balığını çok ezmeden karıştırın.", "Süzülmüş makarnayı sosa ekleyip 1 dakika harmanlayın.", "Kıyılmış maydanoz serpip servis edin."], minutes: 20, servings: 4, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", tips: ["Kapari ve zeytin tuzlu olduğundan sosun tuzunu en sonda kontrol edin.", "Yağlı ton balığı kullanırsanız zeytinyağını yarıya indirin."], serving: "Sıcak olarak, yanında yeşil salata ile servis edin.", storage: "Buzdolabında 2 gün saklanır; soğuk makarna salatası olarak da tüketilebilir."),
  GeneralRecipe(id: "Fı-0", title: "Patates graten", category: "Sebze yemekleri", ingredients: ["800 g patates (2–3 mm ince dilim)", "1 yemek kaşığı tereyağı", "1 yemek kaşığı un", "2 su bardağı süt", "1 diş sarımsak (ezilmiş)", "100 g rendelenmiş kaşar peyniri", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "1 tutam muskat"], steps: ["Fırını 180 °C'ye ısıtın, orta boy bir fırın kabını tereyağıyla yağlayın.", "Tencerede tereyağını eritip unu 1 dakika kavurun; sütü çırparak ekleyin ve kaynayıp hafif koyulaşana kadar 4 dakika karıştırın.", "Sarımsak, tuz, karabiber ve muskatı sosa ekleyin.", "Patates dilimlerini kaba kat kat dizin; her katın üzerine biraz sos ve az miktarda kaşar serpin.", "En üste kalan sosu döküp kabı folyoyla kapatın ve 35 dakika pişirin.", "Folyoyu kaldırıp kalan kaşarı serpin, 15 dakika daha üzeri kızarana ve patatesler bıçakla kolayca delinene kadar pişirin; 10 dakika dinlendirip dilimleyin."], minutes: 70, servings: 4, prepMinutes: 20, cookMinutes: 50, difficulty: "Orta", ovenCelsius: 180, tips: ["Patatesleri ince ve eşit dilimlemek için rende veya mandolin kullanın.", "Dilimledikten sonra patatesleri yıkamayın; nişastası sosu bağlar."], serving: "Izgara et, tavuk veya yeşil salata yanında servis edin.", storage: "Buzdolabında 3 gün saklanır; fırında ısıtın."),
  GeneralRecipe(id: "Fı-1", title: "Sebzeli tepsi böreği", category: "Hamur işleri", ingredients: ["4 adet yufka", "1 kabak, 1 havuç, 1 kırmızı biber (rendelenmiş/küp)", "1 orta boy soğan", "200 g beyaz peynir", "2 yumurta", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "1 tatlı kaşığı tuz, karabiber", "1 yemek kaşığı çörek otu"], steps: ["Fırını 180 °C'ye ısıtın, 30×40 cm tepsiyi yağlayın.", "Soğanı 2 yemek kaşığı yağda 3 dakika kavurun; sebzeleri ekleyip suyunu çekene kadar 6 dakika soteleyin, soğutup peynirle karıştırın.", "Yumurta, süt, kalan yağ, tuz ve karabiberi çırparak sos hazırlayın.", "Yufkaları tepsiye serip her katı sosla ıslatın; iki yufkanın üzerine harcı yayın, kalan yufkaları da sosla ıslatarak kapatın.", "Dilimleyip üzerine kalan sosu ve çörek otunu sürün, 30 dakika dinlendirin.", "40 dakika, üstü kızarana kadar pişirin."], minutes: 65, servings: 8, prepMinutes: 25, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 180, tips: ["Dinlendirmek yufkanın sosu emmesini ve börek içinin yumuşak olmasını sağlar."], serving: "Ilık olarak ayran veya çayla servis edin.", storage: "Buzdolabında 3 gün; dondurulabilir."),
  GeneralRecipe(id: "Fı-2", title: "Ispanaklı kol böreği", category: "Hamur işleri", ingredients: ["3 adet yufka", "500 g ıspanak", "1 orta boy soğan", "150 g lor peyniri", "1 yumurta (sarısı üzerine)", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "1 tatlı kaşığı tuz", "1 tatlı kaşığı pul biber"], steps: ["Fırını 190 °C'ye ısıtın.", "Ispanağı yıkayıp ince doğrayın; soğanı 2 yemek kaşığı yağda kavurup ıspanağı ekleyin, suyunu çekene kadar 5 dakika pişirin, soğutup lor, tuz ve pul biberle karıştırın.", "Süt ve kalan yağı karıştırın.", "Her yufkayı ikiye kesin; yarım yufkayı sosla ıslatıp kenarına harç koyun, rulo yapıp yuvarlak tepsiye spiral dizin.", "Yumurta sarısı sürüp 35 dakika kızarana kadar pişirin."], minutes: 60, servings: 6, prepMinutes: 25, cookMinutes: 35, difficulty: "Orta", ovenCelsius: 190, tips: ["Ispanağın suyunu iyice uçurun; yoksa börek hamurlaşır."], serving: "Ilık servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "Fı-3", title: "Peynirli yumuşak poğaça", category: "Hamur işleri", ingredients: ["1 su bardağı yoğurt", "1 su bardağı sıvı yağ", "1 yumurta (sarısı üzerine)", "1 paket kabartma tozu", "1 tatlı kaşığı tuz", "Yaklaşık 4 su bardağı un", "200 g beyaz peynir", "Yarım demet maydanoz", "Üzeri için 1 tatlı kaşığı çörek otu ve 1 tatlı kaşığı susam"], steps: ["Fırını 180 °C'ye ısıtın, tepsiye pişirme kâğıdı serin.", "Yoğurt, yağ, yumurta beyazı, tuz ve kabartma tozunu karıştırın.", "Unu azar azar ekleyip ele yapışmayan yumuşak bir hamur yoğurun.", "Peyniri ezip kıyılmış maydanozla karıştırın.", "Hamurdan ceviz büyüklüğünde parçalar alıp açın, ortasına harç koyup kapatın ve tepsiye dizin.", "Üzerine yumurta sarısı sürüp çörek otu serpin; 25 dakika kızarana kadar pişirin."], minutes: 50, servings: 16, prepMinutes: 25, cookMinutes: 25, difficulty: "Orta", ovenCelsius: 180, tips: ["Hamuru fazla yoğurmayın; poğaçalar sertleşir."], serving: "Sıcak veya ılık çayla servis edin.", storage: "Hava almayan kapta 2 gün; dondurulabilir."),
  GeneralRecipe(id: "Fı-4", title: "Tam buğday ev pizzası", category: "Dünya mutfağı", ingredients: ["2 su bardağı tam buğday unu", "1 su bardağı beyaz un", "1 paket instant maya", "1 tatlı kaşığı şeker", "1 tatlı kaşığı tuz", "1 su bardağı ılık su", "3 yemek kaşığı zeytinyağı", "Sos için 1 su bardağı rendelenmiş domates, 1 diş sarımsak, 1 tatlı kaşığı kekik", "200 g rendelenmiş mozzarella", "Üzeri için 4 mantar, 1 biber, 8 zeytin"], steps: ["Unları, maya, şeker ve tuzu karıştırın; su ve 2 yemek kaşığı zeytinyağıyla 8 dakika yoğurun.", "Hamuru örtüp ılık yerde 1 saat, iki katına çıkana kadar mayalandırın.", "Domates, ezilmiş sarımsak ve kekiği 5 dakika kaynatıp koyulaştırın.", "Fırını 230 °C'ye ısıtın; hamuru ikiye bölüp yağlı kâğıt üzerinde ince açın.", "Sosu sürün, mozzarella ve malzemeleri dizin, kalan zeytinyağını gezdirin.", "12–15 dakika, kenarlar kızarıp peynir eriyene kadar pişirin."], minutes: 105, servings: 4, prepMinutes: 90, cookMinutes: 15, difficulty: "Orta", ovenCelsius: 230, tips: ["Fırın taşı veya ters çevrilmiş tepsiyi önceden ısıtmak tabanı çıtır yapar."], serving: "Dilimleyip roka ile sıcak servis edin.", storage: "Buzdolabında 2 gün; tavada ısıtın."),
  GeneralRecipe(id: "Fı-5", title: "Sebzeli kiş", category: "Dünya mutfağı", ingredients: ["1,5 su bardağı un", "100 g soğuk tereyağı", "1 yumurta (hamur için)", "2–3 yemek kaşığı soğuk su", "Yarım çay kaşığı tuz", "Dolgu: 3 yumurta, 1 su bardağı krema veya süt", "1 su bardağı sotelenmiş sebze (ıspanak, mantar, pırasa)", "1 su bardağı rendelenmiş kaşar", "Yarım çay kaşığı karabiber, 1 tutam muskat"], steps: ["Un, tuz ve küp tereyağını parmak uçlarıyla ovalayın; yumurta ve suyu ekleyip toparlayın, 30 dakika buzdolabında dinlendirin.", "Fırını 180 °C'ye ısıtın; hamuru açıp 24 cm tart kalıbına yerleştirin, çatalla delin.", "Hamurun üzerine kâğıt ve fasulye koyup 12 dakika ön pişirin, ağırlığı kaldırın.", "Yumurta, krema, karabiber ve muskatı çırpın.", "Sebze ve kaşarı tabana yayın, sıvı karışımı dökün.", "35 dakika, ortası sallanmayana kadar pişirin; 10 dakika dinlendirip dilimleyin."], minutes: 65, servings: 6, prepMinutes: 30, cookMinutes: 35, difficulty: "Orta", ovenCelsius: 180, tips: ["Ön pişirme tabanın hamur kalmasını önler."], serving: "Ilık ya da oda sıcaklığında yeşil salatayla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "Fı-6", title: "Fırın mücver", category: "Sebze yemekleri", ingredients: ["3 orta boy kabak (rendelenmiş)", "1 havuç (rendelenmiş)", "3 yumurta", "100 g beyaz peynir (ufalanmış)", "5 yemek kaşığı un", "1 çay kaşığı kabartma tozu", "3 dal taze soğan", "Yarım demet dereotu", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "Yarım çay kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Rendelenmiş kabağa bir tutam tuz serpip 10 dakika bekletin, ardından suyunu avucunuzla iyice sıkın.", "Fırını 180 °C'ye ısıtın, 20x30 cm tepsiyi yağlı kâğıtla kaplayın.", "Yumurtaları çırpıp kabak, havuç, peynir, ince kıyılmış yeşillikler, zeytinyağı, tuz ve karabiberi ekleyin.", "Un ve kabartma tozunu ekleyip pürüzsüz bir harç elde edene kadar karıştırın.", "Harcı tepsiye eşit yayın ve 30–35 dakika, üzeri altın rengi olana ve kürdan kuru çıkana kadar pişirin.", "10 dakika ılıdıktan sonra kare dilimleyin."], minutes: 55, servings: 4, prepMinutes: 20, cookMinutes: 35, difficulty: "Kolay", ovenCelsius: 180, tips: ["Kabağın suyunu iyice sıkmazsanız mücver hamurlu kalır."], serving: "Sarımsaklı yoğurtla ılık veya soğuk servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "Fı-7", title: "Fırında kaşarlı mantar", category: "Sebze yemekleri", ingredients: ["500 g büyük boy kültür mantarı", "2 yemek kaşığı tereyağı (eritilmiş)", "2 diş sarımsak (ince kıyılmış)", "Yarım demet maydanoz (ince kıyılmış)", "80 g rendelenmiş kaşar", "Yarım çay kaşığı tuz", "Yarım çay kaşığı karabiber", "Yarım çay kaşığı kekik"], steps: ["Fırını 200 °C'ye ısıtın.", "Mantarları nemli bir bezle silin, saplarını çıkarıp ince kıyın.", "Kıyılmış sapları tereyağının yarısı ve sarımsakla tavada 4 dakika soteleyin; maydanoz, tuz, karabiber ve kekiği ekleyin.", "Mantar şapkalarını ters çevirip fırın kabına dizin, içlerine kalan tereyağını sürün.", "Sapli harcı şapkalara paylaştırıp üzerlerine kaşar serpin.", "Fırında 15–18 dakika, mantarlar suyunu salıp kaşar kızarana kadar pişirin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 200, tips: ["Mantarları yıkamayın; su çekip lastik gibi olurlar."], serving: "Sıcak olarak başlangıç veya garnitür olarak servis edin.", storage: "Buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "Fı-8", title: "Kabak graten", category: "Sebze yemekleri", ingredients: ["4 orta boy kabak (yarım ay)", "1 yemek kaşığı tereyağı", "1 yemek kaşığı un", "1,5 su bardağı süt", "2 yumurta sarısı", "100 g rendelenmiş kaşar", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "Yarım demet dereotu"], steps: ["Kabakları tavada az zeytinyağıyla 5 dakika diri kalacak şekilde soteleyin ve süzerek fazla suyunu atın.", "Fırını 190 °C'ye ısıtın.", "Tereyağında unu 1 dakika kavurun, sütü çırparak ekleyip 3 dakika koyulaşana kadar pişirin.", "Ocaktan aldığınız sosa yumurta sarılarını hızla çırparak ekleyin; tuz, karabiber, dereotu ve kaşarın yarısını ilave edin.", "Kabakları fırın kabına yayıp sosu üzerine dökün, kalan kaşarı serpin.", "Fırında 25–30 dakika üzeri kızarana kadar pişirin."], minutes: 50, servings: 4, prepMinutes: 15, cookMinutes: 35, difficulty: "Kolay", ovenCelsius: 190, tips: ["Kabakların suyunu atmazsanız graten sulanır."], serving: "Ana yemeğin yanında garnitür olarak sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "Fı-9", title: "Fırın karnabahar", category: "Sebze yemekleri", ingredients: ["1 orta boy karnabahar (çiçeklerine ayrılmış)", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tatlı toz biber", "1 çay kaşığı kimyon", "1 diş sarımsak (rendelenmiş)", "1 çay kaşığı tuz", "1 su bardağı süzme yoğurt", "Yarım limonun suyu", "Yarım demet maydanoz"], steps: ["Fırını 220 °C'ye ısıtın, tepsiye yağlı kâğıt serin.", "Karnabaharları zeytinyağı, toz biber, kimyon ve tuzla iyice harmanlayın.", "Tepsiye üst üste gelmeyecek şekilde yayın.", "Fırında 25–30 dakika, yarısında bir kez çevirerek kenarları koyu altın rengi olana kadar pişirin.", "Bu sırada yoğurt, sarımsak ve limon suyunu karıştırın.", "Karnabaharları yoğurtlu sosun üzerine alıp kıyılmış maydanozla servis edin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 220, tips: ["Yüksek ısı ve tek kat dizmek karnabaharın haşlanmak yerine kavrulmasını sağlar."], serving: "Ilık olarak yoğurtlu sosla meze veya garnitür olarak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "Ta-0-unique-11", title: "Sütlaç", category: "Tatlılar", ingredients: ["Yarım su bardağı pirinç", "1,5 su bardağı su", "1 litre süt", "1 su bardağı şeker", "2 yemek kaşığı pirinç unu", "Yarım su bardağı soğuk süt (pirinç unu için)", "1 paket vanilin", "1 çay kaşığı tarçın"], steps: ["Pirinci yıkayıp suyla, suyunu çekene kadar 15 dakika pişirin.", "Sütü ekleyip kaynayınca kısık ateşte ara ara karıştırarak 15 dakika pişirin.", "Şekeri ekleyip 5 dakika daha pişirin.", "Pirinç ununu soğuk sütte açıp karıştırarak ekleyin; 5 dakika koyulaşana kadar pişirin.", "Vanilini ekleyip kaselere paylaştırın, soğuyunca tarçın serpin."], minutes: 50, servings: 6, prepMinutes: 10, cookMinutes: 40, difficulty: "Kolay", tips: ["Dibi tutmaması için ahşap kaşıkla sürekli karıştırın."], serving: "Soğuk servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "Ta-1-unique-12", title: "Muhallebi", category: "Tatlılar", ingredients: ["1 litre süt", "1 su bardağı şeker", "3 yemek kaşığı pirinç unu", "2 yemek kaşığı buğday nişastası", "1 yemek kaşığı tereyağı", "1 paket vanilin", "Üzeri için 2 yemek kaşığı Antep fıstığı veya hindistan cevizi"], steps: ["Sütü, şekeri, pirinç unu ve nişastayı tencerede soğukken çırpın.", "Orta ateşte sürekli karıştırarak kaynamaya getirin.", "Kaynadıktan sonra 5 dakika daha, kaşığın arkasını kaplayacak kıvama gelene kadar pişirin.", "Ocaktan alıp tereyağı ve vanilini ekleyin.", "Kaselere paylaştırıp soğutun, üzerini süsleyin."], minutes: 20, servings: 6, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", tips: ["Kaseleri ıslatmak, muhallebinin kolay çıkmasını sağlar."], serving: "Soğuk servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "Ta-2-unique-13", title: "Muzlu yulaf kurabiyesi", category: "Kek ve kurabiyeler", ingredients: ["2 olgun muz", "1,5 su bardağı yulaf", "Yarım su bardağı kuru üzüm veya damla çikolata", "2 yemek kaşığı fıstık ezmesi", "1 tatlı kaşığı tarçın", "1 tutam tuz"], steps: ["Fırını 180 °C'ye ısıtın, tepsiye kâğıt serin.", "Muzları çatalla ezin, fıstık ezmesiyle karıştırın.", "Yulaf, tarçın, tuz ve üzümü ekleyip 5 dakika bekletin.", "Kaşıkla tepsiye yassı yuvarlaklar bırakın.", "15 dakika, kenarları kızarana kadar pişirin; tepside soğutun."], minutes: 25, servings: 16, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 180, tips: ["Kurabiyeler sıcakken yumuşaktır, soğuyunca toparlanır."], serving: "Çay veya sütle.", storage: "Hava almayan kapta 4 gün."),
  GeneralRecipe(id: "Ta-3-unique-14", title: "Elmalı crumble", category: "Dünya mutfağı", ingredients: ["5 elma", "1 yemek kaşığı limon suyu", "3 yemek kaşığı esmer şeker", "1 tatlı kaşığı tarçın", "1 su bardağı un", "100 g soğuk tereyağı", "Yarım su bardağı şeker", "Yarım su bardağı yulaf"], steps: ["Fırını 180 °C'ye ısıtın.", "Elmaları soyup dilimleyin; limon suyu, esmer şeker ve tarçınla karıştırıp fırın kabına yayın.", "Un, şeker ve yulafı karıştırın, soğuk tereyağını ekleyip kum kıvamına gelene kadar ovalayın.", "Kırıntıları elmaların üzerine eşit serpin.", "35 dakika, üstü altın rengi olana kadar pişirin."], minutes: 55, servings: 6, prepMinutes: 20, cookMinutes: 35, difficulty: "Kolay", ovenCelsius: 180, tips: ["Ekşimsi elmalar (Granny Smith) daha dengeli bir tat verir."], serving: "Ilık, vanilyalı dondurmayla servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "Ta-4-unique-15", title: "Fırında cevizli armut", category: "Tatlılar", ingredients: ["4 armut", "4 yemek kaşığı ceviz içi", "2 yemek kaşığı bal", "1 tatlı kaşığı tarçın", "1 yemek kaşığı tereyağı", "Yarım su bardağı su"], steps: ["Fırını 180 °C'ye ısıtın.", "Armutları soyup ikiye kesin, çekirdek yatağını oyun.", "Fırın kabına dizip oyuklara ceviz koyun.", "Bal, tarçın ve eritilmiş tereyağını karıştırıp üzerine gezdirin; suyu kabın dibine dökün.", "30 dakika, armutlar yumuşayana kadar pişirin; ara ara suyunu üzerine kaşıklayın."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 180, tips: ["Az olgun armut fırında dağılmadan kalır."], serving: "Ilık, kaymak veya yoğurtla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "Ta-5-unique-16", title: "Ballı cevizli yoğurt kasesi", category: "Tatlılar", ingredients: ["1,5 su bardağı süzme yoğurt", "1 su bardağı karışık meyve", "2 yemek kaşığı bal", "3 yemek kaşığı granola veya yulaf", "2 yemek kaşığı ceviz", "1 çay kaşığı tarçın"], steps: ["Meyveleri yıkayıp küçük doğrayın.", "Yoğurdu bal ve tarçınla çırpın.", "Kaselere yoğurdu paylaştırın.", "Üzerine meyve, granola ve cevizi dizin.", "Hemen servis edin."], minutes: 10, servings: 2, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Granolayı en son ekleyin ki yumuşamasın."], serving: "Kahvaltı veya ara öğün olarak.", storage: "Hemen tüketin."),
  GeneralRecipe(id: "Ta-6-unique-17", title: "İrmik helvası", category: "Tatlılar", ingredients: ["2 su bardağı irmik", "125 g tereyağı", "3 yemek kaşığı çam fıstığı", "2 su bardağı süt", "1 su bardağı su", "1,5 su bardağı şeker"], steps: ["Süt, su ve şekeri ayrı bir tencerede kaynatıp ocağın kenarında sıcak tutun.", "Tereyağını geniş tencerede eritin; irmik ve fıstığı ekleyip kısık ateşte sürekli karıştırarak 15–18 dakika, açık kahve rengi olana kadar kavurun.", "Sıcak şerbeti dikkatle irmiğe ekleyin; sıçrayabilir.", "Karıştırarak suyunu çekene kadar pişirin, kapağın altına kâğıt havlu koyup 10 dakika demlendirin.", "Kalıplayarak servis edin."], minutes: 30, servings: 6, prepMinutes: 5, cookMinutes: 25, difficulty: "Orta", tips: ["Şerbet ve irmik ikisi de sıcak olmalı; aksi hâlde helva topaklanır."], serving: "Ilık, dondurmayla.", storage: "Oda sıcaklığında 2 gün."),
  GeneralRecipe(id: "Ta-7-unique-18", title: "Fırın sütlaç", category: "Tatlılar", ingredients: ["Yarım su bardağı pirinç", "1 su bardağı su", "1 litre süt", "1 su bardağı şeker", "2 yemek kaşığı pirinç unu", "1 yumurta sarısı", "Yarım su bardağı soğuk süt"], steps: ["Pirinci suyla suyunu çekene kadar pişirin, sütü ekleyip 15 dakika kaynatın.", "Şekeri ekleyin; pirinç unu, yumurta sarısı ve soğuk sütü çırpıp karıştırarak ekleyin, 5 dakika pişirin.", "Fırına dayanıklı kaselere paylaştırın.", "Kaseleri su dolu tepsiye dizip fırının üst rafında 200 °C'de 15–20 dakika, üstleri kızarana kadar pişirin.", "Soğutup buzdolabında dinlendirin."], minutes: 55, servings: 6, prepMinutes: 10, cookMinutes: 45, difficulty: "Orta", ovenCelsius: 200, tips: ["Su banyosu sütlacın kesilmesini önler."], serving: "Soğuk, tarçınla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "Ta-8-unique-19", title: "Havuçlu cevizli kek", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "Yarım su bardağı sıvı yağ", "2 su bardağı rendelenmiş havuç", "2 su bardağı un", "1 paket kabartma tozu", "1 tatlı kaşığı tarçın", "Yarım su bardağı ceviz"], steps: ["Fırını 175 °C'ye ısıtın, kek kalıbını yağlayıp unlayın.", "Yumurta ve şekeri 4 dakika köpürene kadar çırpın, yağı ekleyin.", "Havucu ekleyip karıştırın.", "Un, kabartma tozu ve tarçını eleyerek ekleyin; cevizi un serpip ilave edin.", "Kalıba döküp 40 dakika, kürdan temiz çıkana kadar pişirin."], minutes: 60, servings: 10, prepMinutes: 20, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 175, tips: ["İlk 25 dakika fırın kapağını açmayın."], serving: "Soğuyunca dilimleyin.", storage: "Hava almayan kapta 3 gün."),
  GeneralRecipe(id: "Ta-9-unique-20", title: "Kakaolu puding", category: "Tatlılar", ingredients: ["3 su bardağı süt", "Yarım su bardağı şeker", "3 yemek kaşığı kakao", "3 yemek kaşığı mısır nişastası", "1 yemek kaşığı tereyağı", "50 g bitter çikolata"], steps: ["Süt, şeker, kakao ve nişastayı soğukken çırpın.", "Orta ateşte sürekli karıştırarak kaynatın.", "Koyulaşınca 2 dakika daha pişirip ocaktan alın.", "Tereyağı ve doğranmış çikolatayı ekleyip eriyene kadar karıştırın.", "Kaselere döküp üzerini streçle kapatarak soğutun."], minutes: 17, servings: 4, prepMinutes: 5, cookMinutes: 12, difficulty: "Kolay", tips: ["Streç filmi pudingin yüzeyine değdirin; kabuk tutmaz."], serving: "Soğuk, üzerine çikolata rendesiyle.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "At-0", title: "Humus", category: "Pratik tarifler", ingredients: ["2 su bardağı haşlanmış nohut", "4 yemek kaşığı tahin", "1 limon suyu", "1 diş sarımsak", "4 yemek kaşığı buzlu su", "1 tatlı kaşığı kimyon", "1 tatlı kaşığı tuz", "Üzeri için 1 yemek kaşığı zeytinyağı ve 1 çay kaşığı pul biber"], steps: ["Nohutların kabuklarını mümkün olduğunca ayıklayın.", "Tahin ve limon suyunu robotta 1 dakika çırpın.", "Nohut, sarımsak, kimyon ve tuzu ekleyip çekin.", "Buzlu suyu azar azar ekleyerek pürüzsüz ve kabarık kıvam alın.", "Tabağa yayıp zeytinyağı ve pul biber gezdirin."], minutes: 15, servings: 6, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Kabukları ayıklanmış nohut daha pürüzsüz humus verir."], serving: "Lavaş veya sebze çubuklarıyla.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "At-1", title: "Yoğurtlu naneli dip sos", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı süzme yoğurt", "1 salatalık", "1 diş sarımsak", "1 tatlı kaşığı kuru nane", "1 yemek kaşığı zeytinyağı", "Yarım çay kaşığı tuz"], steps: ["Salatalığı rendeleyip suyunu iyice sıkın.", "Sarımsağı ezin.", "Yoğurdu salatalık, sarımsak, nane ve tuzla karıştırın.", "Üzerine zeytinyağı gezdirin.", "15 dakika buzdolabında dinlendirin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Salatalığın suyunu sıkmak sosu koyu tutar."], serving: "Sebze çubuklarıyla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "At-2", title: "Fırında baharatlı nohut", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 su bardağı haşlanmış nohut", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kimyon", "1 tatlı kaşığı tatlı toz biber", "Yarım çay kaşığı tuz"], steps: ["Fırını 200 °C'ye ısıtın.", "Nohutları süzüp kâğıt havluyla iyice kurulayın, gevşeyen kabukları ayıklayın.", "Zeytinyağı ve baharatla harmanlayın.", "Tepsiye tek kat yayıp 30 dakika, iki kez sallayarak çıtırlaşana kadar pişirin.", "Fırında kapağı aralık soğutun."], minutes: 35, servings: 4, prepMinutes: 5, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 200, tips: ["Tamamen kuru nohut çıtır olur."], serving: "Ara öğünde.", storage: "Açık kapta 2 gün."),
  GeneralRecipe(id: "At-3", title: "Sebze çubukları ve tahinli dip", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 havuç", "1 salatalık", "1 kırmızı biber", "2 sap kereviz", "3 yemek kaşığı tahin", "2 yemek kaşığı limon suyu", "3 yemek kaşığı su", "1 diş sarımsak", "1 tatlı kaşığı tuz"], steps: ["Sebzeleri yıkayıp parmak kalınlığında çubuklar hâlinde kesin.", "Tahin ve limon suyunu çırpın; koyulaşınca suyu azar azar ekleyin.", "Ezilmiş sarımsak ve tuzu ekleyin.", "Sebzeleri bardaklara dizin.", "Sosu yanında servis edin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Çubukları soğuk suda bekletmek çıtırlığı korur."], serving: "Ara öğünde.", storage: "Sebzeler buzdolabında 2 gün."),
  GeneralRecipe(id: "At-4", title: "Ev yapımı peynirli kraker", category: "Pratik tarifler", ingredients: ["1 su bardağı un", "100 g rendelenmiş kaşar", "50 g soğuk tereyağı", "3 yemek kaşığı süt", "Yarım çay kaşığı tuz", "1 tatlı kaşığı susam"], steps: ["Fırını 190 °C'ye ısıtın.", "Un, tuz ve tereyağını ovalayın, kaşarı ekleyin.", "Sütle toparlayıp hamuru 3 mm inceliğinde açın.", "Küçük kareler kesip çatalla delin, susam serpin.", "15 dakika kızarana kadar pişirin."], minutes: 30, servings: 30, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 190, tips: ["İnce açılan hamur daha çıtır olur."], serving: "Ara öğünde.", storage: "Kapalı kutuda 5 gün."),
  GeneralRecipe(id: "At-5", title: "Hurmalı yulaf bar", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 su bardağı yulaf", "10 çekirdeksiz hurma", "3 yemek kaşığı fıstık ezmesi", "2 yemek kaşığı bal", "Yarım su bardağı kuru meyve", "2 yemek kaşığı keten tohumu"], steps: ["Fırını 175 °C'ye ısıtın, 20×20 cm kabı kâğıtla kaplayın.", "Hurmaları sıcak suda 10 dakika bekletip ezin.", "Fıstık ezmesi ve balla karıştırın.", "Yulaf, kuru meyve ve keten tohumunu ekleyip kaba bastırın.", "25 dakika pişirin, tamamen soğuyunca dilimleyin."], minutes: 40, servings: 12, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 175, tips: ["Soğumadan kesilirse dağılır."], serving: "Ara öğünde.", storage: "Kapalı kapta 5 gün."),
  GeneralRecipe(id: "At-6", title: "Meyveli kefir kasesi", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 su bardağı sade kefir", "1 muz", "1 su bardağı çilek", "2 yemek kaşığı yulaf", "1 yemek kaşığı chia tohumu", "1 tatlı kaşığı bal"], steps: ["Chia tohumunu kefirle karıştırıp 10 dakika bekletin.", "Meyveleri doğrayın.", "Kefiri kaselere paylaştırın.", "Meyve ve yulafı ekleyin.", "Balı gezdirip servis edin."], minutes: 10, servings: 2, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Chia beklerken kefiri hafif koyulaştırır."], serving: "Kahvaltıda.", storage: "Hemen tüketin."),
  GeneralRecipe(id: "At-7", title: "Avokado ezmesi (guacamole)", category: "Pratik tarifler", ingredients: ["2 olgun avokado", "1 küçük domates", "Yarım kırmızı soğan", "1 limon suyu", "Yarım demet maydanoz veya kişniş", "Yarım çay kaşığı tuz", "1 tutam pul biber"], steps: ["Avokadoları ikiye kesip çekirdeğini çıkarın, içini kaşıkla alın.", "Çatalla kaba ezin, limon suyunu hemen ekleyin.", "Domates ve soğanı küçük küp doğrayın.", "Yeşillik, tuz ve pul biberle karıştırın.", "Hemen servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Limon suyu avokadonun kararmasını geciktirir."], serving: "Tam buğday ekmeği veya cips ile.", storage: "Yüzeyine streç değdirerek buzdolabında 1 gün."),
  GeneralRecipe(id: "At-8", title: "Fırında baharatlı patates dilimleri", category: "Pratik tarifler", ingredients: ["4 orta boy patates", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tatlı toz biber", "1 tatlı kaşığı kekik", "1 çay kaşığı sarımsak tozu", "1 tatlı kaşığı tuz"], steps: ["Fırını 220 °C'ye ısıtın.", "Patatesleri kabuklu olarak iyice yıkayıp elma dilimi şeklinde kesin.", "10 dakika soğuk suda bekletip kurulayın.", "Zeytinyağı ve baharatlarla harmanlayıp tek kat dizin.", "30 dakika, yarısında çevirerek kızarana kadar pişirin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 220, tips: ["Kurulamak çıtırlığın anahtarıdır."], serving: "Yoğurtlu sosla sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "At-9", title: "Lorlu sebzeli sandviç", category: "Pratik tarifler", ingredients: ["4 dilim tam buğday ekmeği", "150 g lor peyniri", "1 salatalık", "1 domates", "3–4 yaprak marul", "1 yemek kaşığı zeytinyağı", "Yarım demet dereotu, 1 tutam karabiber"], steps: ["Loru zeytinyağı, kıyılmış dereotu ve karabiberle ezin.", "Salatalık ve domatesi ince dilimleyin.", "Ekmeklere lor karışımını sürün.", "Marul, salatalık ve domatesi dizip kapatın.", "Çapraz kesip servis edin."], minutes: 10, servings: 2, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Domatesi en son koyun; ekmek ıslanmaz."], serving: "Hemen veya beslenme çantasında.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "master33-0", title: "Mercimek çorbası", category: "Çorbalar", ingredients: ["1 su bardağı kırmızı mercimek", "1 küçük soğan", "1 havuç", "1 yemek kaşığı zeytinyağı", "5 su bardağı su"], steps: ["Mercimeği suyu berraklaşana kadar birkaç kez yıkayıp süzün.", "Soğanı ince, havucu küçük küp doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Havucu ekleyip 2 dakika çevirin.", "Mercimeği ve suyu ekleyip kaynatın; köpüğünü alın.", "Kapağı aralık bırakıp kısık ateşte, ara ara karıştırarak mercimek dağılana kadar 25 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 41),
  GeneralRecipe(id: "master33-1", title: "Domates çorbası", category: "Çorbalar", ingredients: ["5 olgun domates", "1 yemek kaşığı un", "1 yemek kaşığı zeytinyağı", "3 su bardağı su"], steps: ["Domatesleri rendeleyin.", "Tencerede zeytinyağını ısıtıp unu kokusu çıkana kadar 1–2 dakika kavurun.", "Rendelenmiş domatesi ekleyip 5 dakika pişirin.", "Suyu azar azar ekleyerek topak kalmayacak şekilde karıştırın.", "Kaynayınca kısık ateşte 15 dakika pişirin.", "Kıvamı koyu gelirse sıcak su ekleyip 2 dakika daha kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 34),
  GeneralRecipe(id: "master33-2", title: "Sebzeli bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "1 kabak", "1 kırmızı biber", "1 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Bulguru bir kez yıkayıp süzün.", "Kabak ve biberi küçük küp doğrayın.", "Tencerede yağı ısıtıp sebzeleri 4 dakika soteleyin.", "Bulguru ekleyip yağa bulanması için 1–2 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 41),
  GeneralRecipe(id: "master33-5", title: "Fırında tavuk ve patates", category: "Tavuk yemekleri", ingredients: ["400 g kemiksiz tavuk", "3 patates", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200°C’ye ısıtın.", "Tavuğu iri parçalara, patatesleri 1 cm dilimlere kesin.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Tavuk ve patatesleri fırın kabına alın; yağ, kekik ve az tuzla harmanlayın.", "Tek kat yayın.", "35–45 dakika pişirin.", "Pişirmenin yarısında tavukları ve sebzeleri çevirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Ocaktan ya da fırından alıp 3–5 dakika dinlendirin; suyu içine çekilir ve daha sulu olur."], minutes: 60),
  GeneralRecipe(id: "master33-8", title: "Muzlu yulaf pankeki", category: "Kahvaltılıklar", ingredients: ["1 olgun muz", "1 yumurta", "4 yemek kaşığı ince yulaf", "1 tatlı kaşığı zeytinyağı"], steps: ["Muzu çatalla ezin.", "Yumurta ve yulafı ekleyip karıştırın; 5 dakika dinlendirin.", "Yapışmaz tavayı kısık-orta ateşte ısıtıp çok az yağla yağlayın.", "Tavaya kaşıkla küçük porsiyonlar dökün; yüzeyde kabarcıklar oluşunca çevirip diğer yüzünü de 1–2 dakika pişirin.", "Ilık servis edin."], minutes: 20),
  GeneralRecipe(id: "master33-10", title: "Yoğurtlu semizotu", category: "Salatalar", ingredients: ["1 demet semizotu", "1 su bardağı yoğurt", "1 küçük diş sarımsak", "1 tatlı kaşığı zeytinyağı"], steps: ["Semizotunun kalın saplarını ayıklayın; yapraklarını bol suda birkaç kez yıkayıp süzün ve iri doğrayın.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Semizotunu sarımsaklı yoğurtla harmanlayın.", "Servis tabağına alıp üzerine zeytinyağı gezdirin.", "Soğuk servis edin."], minutes: 10),
  GeneralRecipe(id: "master33-11", title: "Kabak mücveri", category: "Sebze yemekleri", ingredients: ["2 kabak", "2 yumurta", "4 yemek kaşığı un", "Yarım demet dereotu", "1 yemek kaşığı zeytinyağı"], steps: ["Kabakları rendeleyip bir tutam tuzla 5 dakika bekletin; sonra avucunuzla suyunu iyice sıkın.", "Dereotunu ince kıyın.", "Kabak, yumurta, un ve dereotunu karıştırın; kıvamı kaşıktan akmayacak yoğunlukta olmalı.", "Yapışmaz tavayı az yağla orta ateşte ısıtın; karışımı kaşıkla küçük porsiyonlar halinde koyup bastırın.", "Her yüzünü 3–4 dakika, içi tamamen pişip altı kızarana kadar pişirin.", "Kâğıt havluya alıp fazla yağını süzdürün; yoğurtla servis edin."], minutes: 30),
  GeneralRecipe(id: "master33-12", title: "Fırında karnabahar", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı toz kırmızı biber"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Karnabaharı çiçeklere ayırıp yıkayın ve iyice kurulayın; ıslak kalırsa kızarmaz.", "Yağ, toz kırmızı biber ve az tuzla harmanlayın.", "Tepsiye tek kat yayın.", "25–30 dakika pişirin.", "Pişirmenin yarısında sebzeleri spatulayla çevirin ki her yüzü eşit kızarsın.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir."], minutes: 40),
  GeneralRecipe(id: "master33-13", title: "Kıymalı kabak dolması", category: "Et yemekleri", ingredients: ["4 orta boy kabak", "200 g kıyma", "Yarım su bardağı pirinç", "1 soğan", "1 yemek kaşığı salça", "2 su bardağı su"], steps: ["Kabakların uçlarını kesip içlerini oyacakla, kabuğu delmeden oyun.", "Pirinci suyu berraklaşana kadar yıkayıp süzün.", "Kıyma, pirinç, ince doğranmış soğan, salça ve az tuzu yoğurun.", "İç harcı kabaklara pirinç şişeceği için dörtte üçüne kadar gevşekçe doldurun.", "Dolmaları tencereye dik ve sık dizin ki pişerken dağılmasın; üzerine ters bir tabak kapatın.", "Suyu ekleyin; kaynayınca ateşi kısıp 40–45 dakika pişirin.", "Bir dolmayı ortadan kesip kontrol edin: pirinç yumuşak ve kıyma tamamen pişmiş olmalı.", "Yoğurtla sıcak servis edin."], minutes: 60),
  GeneralRecipe(id: "master33-15", title: "Elmalı tarçınlı yulaf", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 elma", "4 yemek kaşığı yulaf", "1 su bardağı süt", "Yarım çay kaşığı tarçın"], steps: ["Elmayı yıkayıp rendeleyin.", "Süt ve yulafı küçük tencerede 5 dakika pişirin.", "Elmayı ekleyip 3 dakika daha karıştırın.", "Tarçın serperek ılık servis edin."], minutes: 15),
  GeneralRecipe(id: "master33-17", title: "Sebzeli makarna", category: "Makarnalar", ingredients: ["200 g makarna", "1 kabak", "1 havuç", "2 yemek kaşığı zeytinyağı", "1 küçük domates"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Kabak ve havucu küçük küp, domatesi rendeleyin.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Tavada yağı ısıtıp havucu 3 dakika, ardından kabağı ekleyip 4 dakika soteleyin.", "Domatesi ekleyip 5 dakika pişirin; tuzunu ayarlayın.", "Makarnayı sosa ekleyin; kıvam koyuysa ayırdığınız sudan katarak 1 dakika harmanlayın.", "Sıcak servis edin."], minutes: 25),
  GeneralRecipe(id: "master33-18", title: "Mercimek köftesi", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı kırmızı mercimek", "Yarım su bardağı ince bulgur", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı salça", "3 su bardağı su"], steps: ["Mercimeği ayıklayıp suyu berraklaşana kadar birkaç kez yıkayın.", "Mercimeği suyla kaynatın; kısık ateşte ara ara karıştırarak 20 dakika, dağılana kadar pişirin.", "Ocağı kapatıp bulguru ekleyin; kapağı kapalı 15 dakika bekletin.", "Soğanı ince doğrayın; tavada yağda 5 dakika kavurup salçayı ekleyin ve 1 dakika çevirin.", "Soğanlı karışımı mercimeğe katın; ılıyınca 5 dakika yoğurun.", "Islak elle avuç içinde sıkarak köfteler şekillendirin.", "Pişmiş tahıl içerdiği için oda sıcaklığında 2 saatten fazla bekletmeyin; kalanını kapalı kapta buzdolabında 2 gün saklayın."], minutes: 55),
  GeneralRecipe(id: "master34-0", title: "Fırında sebzeli omlet", category: "Kahvaltılıklar", ingredients: ["3 yumurta", "1 küçük kabak", "1 kırmızı biber", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Fırını 180°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabağı rendeleyip suyunu sıkın; biberi küçük doğrayın.", "Yumurtaları sütle birlikte çatalla iyice çırpın.", "Sebzeleri yumurtaya ekleyip karıştırın ve kaba dökün.", "Fırında 20 dakika, ortası tamamen pişip kabarana kadar pişirin.", "Dilimleyip sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "master34-1", title: "Kırmızı pancarlı yoğurt salatası", category: "Salatalar", ingredients: ["2 küçük pancar", "1 su bardağı yoğurt", "1 diş sarımsak", "1 tatlı kaşığı zeytinyağı"], steps: ["Pancarları kabuklarıyla, üzerini geçecek kadar suda bıçak kolayca batana kadar 40–45 dakika haşlayın.", "Ilıyınca kabuklarını soyup küçük küp doğrayın ya da rendeleyin; elleriniz boyanmasın diye eldiven kullanabilirsiniz.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Pancarı yoğurtla karıştırın.", "Servis tabağına alıp üzerine zeytinyağı gezdirin.", "Soğuk servis edin."], minutes: 55),
  GeneralRecipe(id: "master34-2", title: "Zeytinyağlı pırasa", category: "Sebze yemekleri", ingredients: ["4 pırasa", "1 havuç", "2 yemek kaşığı pirinç", "3 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Pırasaların kök ve sert yeşil uçlarını kesin; boyuna yarıp katların arasındaki toprağı bol suyla yıkayın.", "Pırasaları dilimleyin, havucu doğrayın.", "Pirinci suyu berraklaşana kadar yıkayıp süzün.", "Tencerede yağ ile havucu 3 dakika çevirin.", "Pırasayı ekleyip 5 dakika soteleyin; pirinç ve suyu ilave edin.", "Kapağı kapalı kısık ateşte yaklaşık 30 dakika, yumuşayana kadar pişirin.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 48),
  GeneralRecipe(id: "master34-4", title: "Limonlu fırın levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş levrek fileto", "1 limon", "1 yemek kaşığı zeytinyağı", "2 dal maydanoz"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Balığı soğuk suyla durulayıp kâğıt havluyla iyice kurulayın.", "Filetoların üzerinde parmaklarınızı gezdirip kalan kılçıkları cımbızla çekin; çocuklar için özellikle önemlidir.", "Filetoları derili yüzü alta gelecek şekilde kaba yerleştirin; yağ, limon suyu ve az tuz ekleyin.", "18–22 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Maydanozu kıyıp üzerine serpin.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 35),
  GeneralRecipe(id: "master34-5", title: "Tavuklu sebze sote", category: "Tavuk yemekleri", ingredients: ["350 g tavuk göğsü", "1 kabak", "1 kırmızı biber", "1 küçük soğan", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu küçük kuşbaşı doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Kabak, biber ve soğanı ayrı tahtada küçük doğrayın.", "Tavada yağı ısıtıp tavuğu yüksek ateşte 5–6 dakika, renk alana kadar soteleyin.", "Soğan ve biberi ekleyip 4 dakika çevirin.", "Kabağı ekleyip 5–6 dakika, sebzeler yumuşayana kadar pişirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "master34-6", title: "Mantarlı arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1 su bardağı arpa şehriye", "200 g mantar", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Soğanı ince doğrayın.", "Tencerede yağı ısıtıp arpa şehriyeyi sürekli karıştırarak açık kahverengi olana kadar 3–4 dakika kavurun.", "Soğanı ekleyip 2 dakika çevirin.", "Mantarları dilimleyip ekleyin; suyunu salıp çekene kadar 5–6 dakika soteleyin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca kısık ateşte kapağı kapalı 12–15 dakika pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 47),
  GeneralRecipe(id: "master34-7", title: "Yeşil mercimekli bulgur salatası", category: "Salatalar", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "Yarım su bardağı ince bulgur", "1 salatalık", "Yarım demet maydanoz", "1 limon", "1 yemek kaşığı zeytinyağı"], steps: ["Bulguru geniş bir kâseye alıp 1 su bardağı sıcak suyla ıslatın; üzerini kapatıp 15 dakika bekletin.", "Salatalığı küçük küp doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Mercimeği süzüp bulgura ekleyin.", "Salatalık ve maydanozu ekleyin.", "Limonun suyunu sıkıp zeytinyağı ve tuzla birlikte ekleyin; karıştırın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 40),
  GeneralRecipe(id: "master34-8", title: "Fırında kabak graten", category: "Sebze yemekleri", ingredients: ["3 kabak", "1 su bardağı süt", "1 yemek kaşığı un", "1 yemek kaşığı tereyağı", "Yarım su bardağı rendelenmiş kaşar"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabakları 0,5 cm kalınlığında ince dilimleyin.", "Kabakları fırın kabına hafifçe üst üste gelecek şekilde dizin.", "Küçük tencerede tereyağını eritip unu 1–2 dakika kavurun; soğuk sütü azar azar ekleyip topak kalmayana kadar çırparak koyulaştırın.", "Sosu kabakların üzerine dökün ve kaşarı serpin.", "30 dakika, kabaklar yumuşayıp üzeri kızarana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 47),
  GeneralRecipe(id: "master34-9", title: "Kuru fasulye piyazı", category: "Salatalar", ingredients: ["2 su bardağı haşlanmış kuru fasulye", "1 kırmızı soğan", "1 domates", "Yarım demet maydanoz", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Fasulyeleri süzüp soğuk suyla durulayın.", "Soğanı ince piyazlık doğrayıp bir tutam tuzla ovun, durulayıp süzün; acılığı azalır.", "Domatesi küçük küp doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Limonun suyunu sıkıp zeytinyağı ve tuzla çırpın.", "Fasulye, soğan, domates ve maydanozu sosla harmanlayın.", "15 dakika dinlendirip servis edin."], minutes: 25),
  GeneralRecipe(id: "master34-10", title: "Fırında elmalı crumble", category: "Dünya mutfağı", ingredients: ["3 elma", "Yarım su bardağı yulaf", "3 yemek kaşığı un", "2 yemek kaşığı tereyağı", "1 çay kaşığı tarçın"], steps: ["Fırını 180 °C ısıtın.", "Elmaları doğrayıp tarçınla karıştırarak kaba alın.", "Yulaf, un ve soğuk tereyağını ufalanan kıvama gelene dek karıştırın.", "Üstüne serpip elmalar yumuşayana dek 25–30 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "master34-11", title: "Yoğurtlu köz patlıcan", category: "Mezeler", ingredients: ["2 patlıcan", "1 su bardağı yoğurt", "1 diş sarımsak", "1 tatlı kaşığı zeytinyağı"], steps: ["Patlıcanları fırında 220 °C’de kabukları kararıncaya dek közleyin.", "Soğutup kabuklarını soyun ve içini ince kıyın.", "Yoğurt ve ezilmiş sarımsağı karıştırın.", "Patlıcanı ekleyip zeytinyağıyla servis edin."], minutes: 35),
  GeneralRecipe(id: "master34-12", title: "Sebzeli mercimek güveci", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı yeşil mercimek", "1 havuç", "1 patates", "1 soğan", "1 yemek kaşığı salça", "3 su bardağı su"], steps: ["Mercimeği ayıklayıp suyu berraklaşana kadar birkaç kez yıkayın.", "Mercimeği kaynar suda 15 dakika ön haşlayıp süzün.", "Soğanı ince, havuç ve patatesi küp doğrayın.", "Tencerede salçayı 2–3 kaşık suyla açıp soğanla 3 dakika çevirin.", "Havuç, patates, mercimek ve suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı kapalı 25–30 dakika, mercimek ve sebzeler yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 58),
  GeneralRecipe(id: "master34-13", title: "Fırında kıymalı patates", category: "Et yemekleri", ingredients: ["300 g kıyma", "3 patates", "1 soğan", "2 domates", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 200°C’ye ısıtın.", "Patatesleri 0,5 cm ince dilimleyin; domatesleri halka kesin.", "Soğanı ince doğrayın.", "Tavada yağı ısıtıp soğanı 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Fırın kabına patates, kıyma ve domatesi kat kat dizin; en üstte patates kalsın.", "Yarım su bardağı sıcak su ekleyip folyoyla kapatın.", "25 dakika pişirin; folyoyu açıp 10–15 dakika daha, patatesler yumuşayana kadar fırınlayın.", "Fırından alıp 5 dakika dinlendirin."], minutes: 55),
  GeneralRecipe(id: "master34-14", title: "Tarçınlı armut kompostosu", category: "İçecekler", ingredients: ["3 armut", "4 su bardağı su", "1 çubuk tarçın", "1 tatlı kaşığı limon suyu"], steps: ["Armutları yıkayıp çekirdeklerini çıkararak dilimleyin.", "Su ve tarçını tencereye alın; kaynatın.", "Armutları ekleyip yumuşayana dek 12–15 dakika pişirin.", "Limon suyunu ekleyip soğutarak servis edin.", "Armutlar tatlı olduğundan şeker gerekmez; isterseniz 1 tatlı kaşığı pekmez ekleyin.", "Oda sıcaklığına gelince buzdolabında soğutun; kapalı şişede 2 gün saklayabilirsiniz."], minutes: 25),
  GeneralRecipe(id: "paket39-g-002", title: "Karnıyarık", category: "Et yemekleri", ingredients: ["4 patlıcan", "250 g kıyma", "1 soğan", "2 domates", "2 yeşil biber", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 200°C’ye ısıtın.", "Patlıcanları alacalı soyup tuzlu suda 15 dakika bekletin; kurulayıp az yağ sürün.", "Tepside 20–25 dakika, yumuşayana kadar pişirin.", "Soğanı ve biberi ince doğrayın, domatesleri küp kesin.", "Tavada yağı ısıtıp soğan ve biberi 4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Domatesin yarısını ekleyip 5 dakika pişirin; tuzunu ayarlayın.", "Patlıcanları boyuna yarıp içlerini kaşıkla açın ve harçla doldurun; kalan domatesi üstlerine koyun.", "Dibine yarım su bardağı su ekleyip 190°C fırında 20 dakika pişirin.", "Sıcak servis edin."], minutes: 87),
  GeneralRecipe(id: "paket39-g-003", title: "İmam bayıldı", category: "Sebze yemekleri", ingredients: ["4 patlıcan", "2 soğan", "3 domates", "3 diş sarımsak", "4 yemek kaşığı zeytinyağı"], steps: ["Fırını 200°C’ye ısıtın.", "Patlıcanları alacalı soyup çatalla birkaç yerinden delin; tepside 20 dakika, yumuşayana kadar pişirin.", "Soğanı piyazlık doğrayın, sarımsağı ince kıyın, domatesleri küp kesin.", "Tavada zeytinyağının yarısıyla soğanı 6–7 dakika yumuşatın; sarımsağı ekleyip 1 dakika çevirin.", "Domatesi ekleyip 5 dakika pişirin; tuzunu ayarlayın.", "Patlıcanları boyuna yarıp içlerini kaşıkla açın ve harçla doldurun.", "Fırını 180°C’ye düşürün; kalan yağı gezdirip yarım su bardağı su ekleyerek 25 dakika pişirin.", "Ilıtarak servis edin."], minutes: 67),
  GeneralRecipe(id: "paket39-g-005", title: "Nohutlu bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "1 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı salça", "2 su bardağı sıcak su"], steps: ["Bulguru bir kez yıkayıp süzün.", "Soğanı ince doğrayın.", "Tencerede biraz yağ ya da 2–3 kaşık su ile soğanı 3–4 dakika yumuşatın.", "Salçayı ekleyip 1 dakika kavurun.", "Nohut ve bulguru ekleyip 1 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 41),
  GeneralRecipe(id: "paket39-g-006", title: "Fırında sebzeli somon", category: "Balık ve deniz ürünleri", ingredients: ["2 somon fileto", "1 kabak", "1 havuç", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabak ve havucu ince dilimleyip yağın yarısı ve az tuzla harmanlayın; tepsiye yayın.", "Sebzeleri 10 dakika ön pişirin; havuç geç pişer.", "Balığı soğuk suyla durulayıp kâğıt havluyla iyice kurulayın.", "Filetoların üzerinde parmaklarınızı gezdirip kalan kılçıkları cımbızla çekin; çocuklar için özellikle önemlidir.", "Somonu sebzelerin üzerine koyup kalan yağı ve limon suyunu ekleyin.", "18–22 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 42),
  GeneralRecipe(id: "paket39-g-007", title: "Tavuklu mantar sote", category: "Tavuk yemekleri", ingredients: ["350 g kemiksiz tavuk", "250 g mantar", "1 soğan", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu küçük parçalara kesin.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Mantarları nemli bezle silip dilimleyin; soğanı ve biberi doğrayın.", "Tavada yağı ısıtıp soğan ve biberi 4 dakika soteleyin.", "Tavuğu ekleyip 6–7 dakika, her tarafı beyazlayana kadar pişirin.", "Mantarları ekleyip yüksek ateşte suyunu salıp çekene kadar 6–8 dakika pişirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "paket39-g-008", title: "Fırında patatesli köfte", category: "Et yemekleri", ingredients: ["300 g kıyma", "3 patates", "1 soğan", "1 yumurta", "2 yemek kaşığı galeta unu", "1 yemek kaşığı salça"], steps: ["Fırını 200°C’ye ısıtın.", "Soğanı rendeleyip suyunu iyice sıkın.", "Kıyma, soğan, yumurta, galeta unu ve az tuzu 3–4 dakika, macun kıvamına gelene kadar yoğurun.", "Islak elle eşit büyüklükte köfteler şekillendirin.", "Patatesleri soyup 1 cm dilimleyin.", "Köfte ve patatesleri fırın kabına sırayla dizin.", "Salçayı 1 su bardağı sıcak suyla açıp kaba dökün.", "Yaklaşık 35 dakika, patatesler yumuşayana kadar pişirin.", "Bir köfteyi ortadan bölüp kontrol edin: içi pembe kalmamalı; termometre varsa en az 71°C olmalı."], minutes: 50),
  GeneralRecipe(id: "paket39-g-009", title: "Yoğurtlu semizotu salatası", category: "Salatalar", ingredients: ["1 demet semizotu", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Semizotunun kalın saplarını ayıklayın; yapraklarını bol suda birkaç kez yıkayıp süzün ve iri doğrayın.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Semizotunu sarımsaklı yoğurtla harmanlayın.", "Servis tabağına alıp üzerine zeytinyağı gezdirin.", "Soğuk servis edin."], minutes: 15),
  GeneralRecipe(id: "paket39-g-011", title: "Şakşuka", category: "Mezeler", ingredients: ["2 patlıcan", "2 kabak", "2 patates", "3 domates", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı"], steps: ["Sebzeleri küp doğrayıp ayrı ayrı fırında yumuşatın.", "Domates ve sarımsağı tavada sos kıvamına gelene dek pişirin.", "Sebzeleri karıştırıp servis tabağına alın.", "Üzerine domates sosunu dökün."], minutes: 40),
  GeneralRecipe(id: "paket39-g-012", title: "Peynirli gözleme", category: "Kahvaltılıklar", ingredients: ["2 su bardağı un", "Yarım su bardağı su", "150 g beyaz peynir", "Yarım demet maydanoz", "1 yemek kaşığı zeytinyağı"], steps: ["Un, su, zeytinyağı ve bir tutam tuzu yoğurup yumuşak bir hamur yapın; 20 dakika dinlendirin.", "Maydanozu ince kıyıp ufalanmış peynirle karıştırın.", "Hamuru 4 parçaya bölüp ince açın.", "Yarısına harç yayıp diğer yarısını kapatın, kenarlarını bastırın.", "Kızgın tavada her yüzü 3–4 dakika, kahverengi benekler oluşana kadar pişirin.", "Sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "paket39-g-013", title: "Domatesli şehriye çorbası", category: "Çorbalar", ingredients: ["3 domates", "Yarım su bardağı tel şehriye", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Domatesleri rendeleyin.", "Tencerede zeytinyağını ısıtıp domatesi 5 dakika pişirin.", "Suyu ekleyip kaynatın.", "Şehriyeyi ekleyip kısık ateşte, şehriye yumuşayana kadar 8–10 dakika pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Ocaktan alıp 5 dakika dinlendirin; sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "paket39-g-017", title: "Kabak dolması", category: "Sebze yemekleri", ingredients: ["4 kabak", "150 g kıyma", "Yarım su bardağı pirinç", "1 soğan", "1 domates", "1 yemek kaşığı salça"], steps: ["Kabakların uçlarını kesip içlerini oyacakla, kabuğu delmeden oyun.", "Pirinci suyu berraklaşana kadar yıkayıp süzün.", "Pirinç, kıyma, ince kıyılmış soğan, rendelenmiş domates, salça ve az tuzu yoğurun.", "İç harcı kabaklara pirinç şişeceği için dörtte üçüne kadar gevşekçe doldurun.", "Dolmaları tencereye dik ve sık dizin ki pişerken dağılmasın; üzerine ters bir tabak kapatın.", "Yarısına gelecek kadar sıcak su ekleyin; kaynayınca ateşi kısıp 35–40 dakika pişirin.", "Bir dolmayı ortadan kesip kontrol edin: pirinç yumuşak ve kıyma tamamen pişmiş olmalı.", "Yoğurtla sıcak servis edin."], minutes: 55),
  GeneralRecipe(id: "paket39-g-018", title: "Fırında tavuk baget", category: "Tavuk yemekleri", ingredients: ["6 tavuk baget", "2 patates", "2 havuç", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200°C’ye ısıtın.", "Bagetleri kâğıt havluyla kurulayın.", "Patates ve havucu iri doğrayın.", "Bagetleri ve sebzeleri yağ, kekik ve az tuzla harmanlayın.", "Fırın kabına tek kat yayın.", "40–45 dakika pişirin.", "Pişirmenin yarısında tavukları ve sebzeleri çevirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Ocaktan ya da fırından alıp 3–5 dakika dinlendirin; suyu içine çekilir ve daha sulu olur."], minutes: 60),
  GeneralRecipe(id: "paket39-g-022", title: "Şehriyeli pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "2 yemek kaşığı arpa şehriye", "1 yemek kaşığı tereyağı", "1,5 su bardağı sıcak su"], steps: ["Pirinci ılık tuzlu suda 20 dakika bekletin; suyu berraklaşana kadar yıkayıp süzün.", "Tencerede tereyağını eritip şehriyeyi açık kahverengi olana kadar kavurun.", "Pirinci ekleyip taneler şeffaflaşana kadar 2–3 dakika kavurun.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi en kısığa alın ve kapağı kapalı 12–15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 58),
  GeneralRecipe(id: "paket39-g-023", title: "Fırında mücver", category: "Sebze yemekleri", ingredients: ["2 kabak", "2 yumurta", "4 yemek kaşığı un", "Yarım demet dereotu", "100 g beyaz peynir"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabakları rendeleyip bir tutam tuzla 5 dakika bekletin; sonra avucunuzla suyunu iyice sıkın.", "Dereotunu kıyın, peyniri ufalayın.", "Kabak, yumurta, un, dereotu ve peyniri karıştırın.", "Yağlı kâğıt serili tepsiye 2 cm kalınlığında yayın.", "25–30 dakika, üzeri kızarana kadar pişirin.", "Ortasına kürdan batırın: kuru çıkıyorsa ve yumurta tamamen pişmişse hazırdır.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 50),
  GeneralRecipe(id: "paket39-g-024", title: "Kıymalı patates oturtma", category: "Et yemekleri", ingredients: ["4 patates", "250 g kıyma", "1 soğan", "2 domates", "1 yemek kaşığı salça", "1 su bardağı su"], steps: ["Fırını 190°C’ye ısıtın.", "Patatesleri soyup ince dilimleyin ve fırın kabına dizin.", "Soğanı ince doğrayın, domatesleri rendeleyin.", "Tavada soğanı az yağda 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Domates ve salçayı ekleyip 5 dakika kaynatın.", "Kıymalı sosu patateslerin üzerine yayın ve suyu ekleyin.", "35 dakika, patatesler yumuşayana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin."], minutes: 67),
  GeneralRecipe(id: "paket39-g-025", title: "Etli sebze güveç", category: "Et yemekleri", ingredients: ["400 g kuşbaşı dana eti", "1 patlıcan", "2 patates", "2 domates", "1 biber", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 180°C’ye ısıtın.", "Eti kâğıt havluyla kurulayın; kuru et daha iyi renk alır.", "Tavada yağı ısıtıp eti yüksek ateşte her yüzü renk alana kadar mühürleyin.", "Patlıcanları alacalı soyup doğrayın; tuzlu suda 15 dakika bekletip acısını alın, sıkıp kurulayın.", "Patates, domates ve biberi etle aynı boyda doğrayın.", "Et ve sebzeleri güveç kabına alın; az tuz ve yarım su bardağı su ekleyip karıştırın.", "Kapağı kapalı 65–75 dakika, et yumuşayana kadar pişirin.", "Bir parça eti çatalla kontrol edin: kolayca dağılıyorsa yumuşamıştır; sertse 10’ar dakika daha pişirin.", "Fırından alıp 5 dakika dinlendirin."], minutes: 105),
  GeneralRecipe(id: "paket39-g-027", title: "Fırında beşamel soslu karnabahar", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "2 su bardağı süt", "2 yemek kaşığı un", "2 yemek kaşığı tereyağı", "Yarım su bardağı rendelenmiş kaşar"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Karnabaharı çiçeklerine ayırıp kaynar tuzlu suda 8 dakika haşlayın; süzün.", "Küçük tencerede tereyağını eritip unu 1–2 dakika kavurun; soğuk sütü azar azar ekleyip topak kalmayana kadar çırparak koyulaştırın.", "Karnabaharı fırın kabına yayıp sosu üzerine dökün.", "Kaşarı serpip 20 dakika, üzeri kızarana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 50),
  GeneralRecipe(id: "paket39-g-028", title: "Kırmızı mercimek çorbası", category: "Çorbalar", ingredients: ["1 su bardağı kırmızı mercimek", "1 havuç", "1 soğan", "1 patates", "5 su bardağı su"], steps: ["Mercimeği suyu berraklaşana kadar birkaç kez yıkayıp süzün.", "Soğanı ince, havucu ve patatesi küçük küp doğrayın.", "Tüm sebzeleri, mercimeği ve suyu tencereye alıp kaynatın; köpüğünü alın.", "Kapağı aralık bırakıp kısık ateşte, ara ara karıştırarak mercimek dağılana kadar 25 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Kıvamı koyu gelirse sıcak su ekleyip 2 dakika daha kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 37),
  GeneralRecipe(id: "paket39-g-029", title: "Yayla çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı pirinç", "1 su bardağı yoğurt", "1 yumurta sarısı", "1 yemek kaşığı un", "5 su bardağı su", "1 tatlı kaşığı kuru nane"], steps: ["Pirinci yıkayıp suyla tencereye alın; kaynayınca kısık ateşte 15 dakika, pirinç yumuşayana kadar pişirin.", "Terbiye için yoğurt, yumurta sarısı ve unu bir kâsede pürüzsüz olana kadar çırpın.", "Kaynayan çorbadan birkaç kepçe alıp terbiyeye azar azar ekleyerek ılıştırın; sonra terbiyeyi sürekli karıştırarak tencereye dökün.", "Sürekli karıştırarak bir taşım kaynatın ve ocağı kapatın; terbiyenin kesilmemesi için yüksek ateşte bırakmayın.", "Kuru naneyi ekleyip karıştırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 35),
  GeneralRecipe(id: "paket39-g-031", title: "Fırında levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş levrek", "1 limon", "1 soğan", "2 yemek kaşığı zeytinyağı", "2 dal maydanoz"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Balıkların içini ve pullarını kontrol edin; soğuk suyla durulayıp kurulayın.", "Sırtlarına bıçakla 2–3 çizik atın; ısı eşit işler.", "Soğanı halka, limonun yarısını dilimleyin; tepsiye yayıp balıkları üzerine yerleştirin.", "Balıkların içine maydanoz ve birer limon dilimi koyun; yağ gezdirip az tuz serpin.", "25–30 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Servis ederken kılçıkları ayırın; çocuk porsiyonunu kılçıksız hazırlayın.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 40),
  GeneralRecipe(id: "paket39-g-032", title: "Ton balıklı makarna salatası", category: "Salatalar", ingredients: ["200 g makarna", "1 kutu ton balığı", "1 salatalık", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı", "1 limon"], steps: ["Makarnayı tuzlu kaynar suda paketteki süre kadar haşlayın; süzüp soğuk suyla durulayın.", "Ton balığının suyunu süzüp iri parçalara ayırın.", "Salatalık ve kırmızı biberi küçük küp doğrayın.", "Limonun suyunu sıkıp zeytinyağı ve tuzla çırpın.", "Makarna, ton balığı ve sebzeleri sosla harmanlayın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 25),
  GeneralRecipe(id: "paket39-g-033", title: "Patates salatası", category: "Salatalar", ingredients: ["4 patates", "3 taze soğan", "Yarım demet maydanoz", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Patatesleri kabuklarıyla, bıçak kolayca batana kadar 20–25 dakika haşlayın.", "Ilıyınca soyup orta büyüklükte küp doğrayın.", "Taze soğanı ince doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Limonun suyunu sıkıp zeytinyağı ve tuzla çırpın.", "Patatesler ılıkken sosla harmanlayın; sosu daha iyi çeker.", "Yeşillikleri ekleyip karıştırın ve servis edin."], minutes: 35),
  GeneralRecipe(id: "paket39-g-034", title: "Kısır", category: "Salatalar", ingredients: ["1 su bardağı ince bulgur", "1 su bardağı sıcak su", "1 yemek kaşığı biber salçası", "3 taze soğan", "Yarım demet maydanoz", "1 limon"], steps: ["Bulguru geniş bir kâseye alıp sıcak suyu ekleyin; üzerini kapatıp 15 dakika şişmeye bırakın.", "Biber salçasını ekleyip bulgurla iyice yoğurun.", "Taze soğanı ince doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Yeşillikleri bulgura ekleyin.", "Limonun suyunu sıkıp tuzla birlikte ekleyin; karıştırın.", "Buzdolabında 20 dakika dinlendirip marul yapraklarıyla servis edin."], minutes: 45),
  GeneralRecipe(id: "paket39-g-035", title: "Peynirli börek", category: "Hamur işleri", ingredients: ["3 yufka", "200 g beyaz peynir", "Yarım demet maydanoz", "1 yumurta", "Yarım su bardağı süt", "3 yemek kaşığı sıvı yağ"], steps: ["Fırını 180°C’ye ısıtın; tepsiyi hafifçe yağlayın.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Peyniri ufalayıp ince kıyılmış maydanozla karıştırın.", "Yumurta, süt ve yağı çırpın; 2–3 kaşığını üzerine sürmek için ayırın.", "Bir yufkayı tepsiye serip sosla ıslatın; ikinci yufkayı katlayarak yayıp yine soslayın.", "Peynirli harcı yayın; kalan yufkayı katlayarak üzerine kapatıp soslayın.", "Ayırdığınız sosu üstüne sürüp kare dilimler halinde kesin.", "30–35 dakika, üzeri kızarıp içi pişene kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 55),
  GeneralRecipe(id: "paket39-g-037", title: "Sebzeli omlet", category: "Kahvaltılıklar", ingredients: ["2 yumurta", "Yarım kırmızı biber", "1 küçük domates", "1 yemek kaşığı zeytinyağı"], steps: ["Biberi ve domatesi küçük doğrayın.", "Yumurtaları çırpın.", "Tavada zeytinyağını ısıtıp biber ve domatesi 4 dakika pişirin.", "Yumurtayı ekleyip tavayı çevirerek yayın.", "Kenarları pişmeye başlayınca spatulayla ortaya doğru itip çiğ kısmın alta akmasını sağlayın.", "Üstü tamamen pişince ikiye katlayıp tabağa alın."], minutes: 15),
  GeneralRecipe(id: "paket39-g-040", title: "Zeytinyağlı enginar", category: "Sebze yemekleri", ingredients: ["4 enginar çanağı", "1 havuç", "1 patates", "1 su bardağı bezelye", "1 limon", "3 yemek kaşığı zeytinyağı"], steps: ["Enginar çanaklarını kararmamaları için limonlu suda bekletin.", "Havuç ve patatesi küçük küp doğrayın.", "Enginarları tencereye çanak yukarı bakacak şekilde dizin; içlerine havuç, patates ve bezelyeyi yerleştirin.", "Zeytinyağı, kalan limonun suyu, az tuz ve 1 su bardağı su ekleyin.", "Üzerine yağlı kâğıt kapatıp kapağı kapalı kısık ateşte 30–35 dakika, enginarlar yumuşayana kadar pişirin.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 45),
  GeneralRecipe(id: "paket39-g-041", title: "Kabak sandal", category: "Sebze yemekleri", ingredients: ["3 kabak", "200 g kıyma", "1 soğan", "1 domates", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı rendelenmiş kaşar"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabakları boyuna ikiye kesip içlerini kaşıkla, kenarlarda 0,5 cm bırakarak oyun.", "Soğanı ince doğrayın, domatesi küp kesin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Domatesi ve oyduğunuz kabak içini ekleyip 4 dakika pişirin.", "Harcı kabaklara paylaştırıp tepsiye dizin; dibine yarım su bardağı su ekleyin.", "25 dakika pişirin; kaşarı serpip 8–10 dakika daha, kabaklar yumuşayıp peynir kızarana kadar fırınlayın."], minutes: 51),
  GeneralRecipe(id: "paket39-g-042", title: "Köz patlıcan salatası", category: "Salatalar", ingredients: ["3 patlıcan", "2 kırmızı biber", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limon"], steps: ["Patlıcanları ocak ateşinde ya da fırında kabukları kararıp içleri yumuşayana kadar 15–20 dakika közleyin.", "Kırmızı biberleri de aynı şekilde 10–15 dakika közleyin.", "Ilıyınca kabuklarını soyup içlerini bıçakla ince kıyın; acı suyunu süzdürün.", "Biberlerin kabuğunu ve çekirdeklerini ayıklayıp küçük doğrayın.", "Sarımsağı ezin.", "Patlıcan, biber ve sarımsağı birleştirin.", "Limonun suyunu sıkıp zeytinyağı ve tuzla ekleyin; karıştırın.", "Soğuk servis edin."], minutes: 45),
  GeneralRecipe(id: "paket39-g-043", title: "Yeşil mercimek salatası", category: "Salatalar", ingredients: ["1 su bardağı yeşil mercimek", "3 dal taze soğan", "Yarım demet maydanoz", "1 kırmızı biber", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Yeşil mercimeği yıkayıp bol suda, dağılmadan diri kalacak şekilde 20–25 dakika haşlayın; süzüp soğutun.", "Taze soğanı ve kırmızı biberi ince doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Mercimek ve sebzeleri bir kâsede birleştirin.", "Limonun suyunu sıkıp zeytinyağı ve tuzla çırpın.", "Sosu servis etmeden hemen önce dökün ve nazikçe harmanlayın; erken eklerseniz sebzeler su salar.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 50),
  GeneralRecipe(id: "paket39-g-044", title: "Mayalı açma", category: "Hamur işleri", ingredients: ["4 su bardağı un", "1 su bardağı ılık süt", "Yarım su bardağı sıvı yağ", "1 yemek kaşığı kuru maya", "1 yemek kaşığı şeker", "1 yumurta"], steps: ["Süt elinizi yakmayacak kadar ılık olsun; sıcak süt mayayı öldürür.", "Ilık süt, maya ve şekeri karıştırıp 10 dakika, köpürene kadar bekletin.", "Yumurtanın beyazını hamura, sarısını üzerine sürmek için ayırın.", "Un, yağ, yumurta beyazı ve bir tutam tuzu ekleyip 8–10 dakika, ele yapışmayan yumuşak bir hamur olana kadar yoğurun.", "Üzerini örtüp ılık yerde 45 dakika, iki katına çıkana kadar mayalandırın.", "Hamuru bezelere ayırıp şeritler halinde uzatın; burarak ya da halka yaparak şekillendirip tepsiye dizin.", "15 dakika daha dinlendirin; bu arada fırını 190°C’ye ısıtın.", "Üzerlerine yumurta sarısı sürüp 20–25 dakika, altın rengi olana kadar pişirin."], minutes: 115),
  GeneralRecipe(id: "paket39-g-045", title: "Domatesli arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1 su bardağı arpa şehriye", "2 domates", "1 yemek kaşığı tereyağı", "1,5 su bardağı sıcak su"], steps: ["Domatesleri rendeleyin.", "Tencerede tereyağını eritip arpa şehriyeyi açık kahverengi olana kadar 3–4 dakika kavurun.", "Domatesi ekleyip 3 dakika pişirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca kısık ateşte kapağı kapalı 12–15 dakika pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 42),
  GeneralRecipe(id: "paket39-g-046", title: "Mantarlı bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "200 g mantar", "1 soğan", "1 yemek kaşığı tereyağı", "2 su bardağı sıcak su"], steps: ["Bulguru bir kez yıkayıp süzün.", "Soğanı ince doğrayın.", "Tencerede tereyağını eritip soğanı 3 dakika yumuşatın.", "Mantarları dilimleyip ekleyin; suyunu salıp çekene kadar 5–6 dakika soteleyin.", "Bulguru ekleyip yağa bulanması için 1–2 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 46),
  GeneralRecipe(id: "paket39-g-047", title: "Tavuklu erişte", category: "Makarnalar", ingredients: ["250 g erişte", "200 g tavuk göğsü", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Tavuğu küçük küp doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Tencerede yağı ısıtıp tavuğu 6–7 dakika, her tarafı beyazlayana kadar soteleyin.", "Biberi küçük doğrayıp ekleyin; 3 dakika yumuşatın.", "Erişteyi ekleyip 2 dakika çevirin.", "Sıcak suyu ve az tuzu ekleyin; kapağı kapalı kısık ateşte 10–12 dakika, erişte yumuşayıp suyunu çekene kadar pişirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "5 dakika dinlendirip servis edin."], minutes: 39),
  GeneralRecipe(id: "paket39-g-048", title: "Fesleğenli domates makarna", category: "Makarnalar", ingredients: ["250 g makarna", "3 domates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "6 yaprak fesleğen"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Domatesleri rendeleyin, sarımsağı ezin.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Geniş tavada zeytinyağını orta ateşte ısıtıp ezilmiş sarımsağı 30 saniye, yakmadan çevirin.", "Rendelenmiş domatesi ve az tuzu ekleyin; ara ara karıştırarak 10 dakika, sos koyulaşana kadar pişirin.", "Makarnayı sosa ekleyin; kıvam koyuysa ayırdığınız sudan katarak 1 dakika harmanlayın.", "Fesleğeni elle koparıp ekleyin ve servis edin."], minutes: 25),
  GeneralRecipe(id: "paket39-g-049", title: "Karides güveç", category: "Balık ve deniz ürünleri", ingredients: ["300 g temizlenmiş karides", "2 domates", "2 yeşil biber", "2 diş sarımsak", "1 yemek kaşığı tereyağı", "Yarım su bardağı kaşar"], steps: ["Donmuş karidesi buzdolabında bir gece ya da soğuk su altında çözdürün; süzüp kurulayın.", "Fırını 200°C’ye ısıtın.", "Biberi ince doğrayın, sarımsağı ezin, domatesleri rendeleyin.", "Tavada tereyağını eritip biberi 3 dakika, sarımsağı 30 saniye çevirin.", "Domatesi ekleyip 6–8 dakika, sos kıvamına gelene kadar pişirin; tuzunu ayarlayın.", "Karidesleri ekleyip 2–3 dakika çevirin.", "Karidesler pembeleşip C şeklini alınca pişmiştir; fazla pişirirseniz sertleşir.", "Güveç kaplarına paylaştırıp kaşar serpin; 8–10 dakika, peynir kızarana kadar fırınlayın."], minutes: 34),
  GeneralRecipe(id: "paket39-g-050", title: "Fırında köri soslu tavuk", category: "Dünya mutfağı", ingredients: ["400 g tavuk göğsü", "1 su bardağı yoğurt", "1 tatlı kaşığı köri", "2 yemek kaşığı zeytinyağı", "1 kırmızı biber"], steps: ["Yoğurt, köri ve yağı karıştırın.", "Tavukları sosla kaplayıp 20 dakika buzdolabında bekletin.", "Biberlerle birlikte fırın kabına alın.", "190 °C fırında tavuk tamamen pişene kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "paket39-g-051", title: "Tavuklu sebze çorbası", category: "Çorbalar", ingredients: ["200 g tavuk göğsü", "1 havuç", "1 patates", "1 küçük kabak", "5 su bardağı su"], steps: ["Tavuğu suyla tencereye alıp kaynatın; köpüğünü alıp kısık ateşte 25 dakika, içi tamamen beyazlayana kadar haşlayın.", "Tavuğu çıkarıp didikleyin; haşlama suyunu süzerek tencerede bırakın.", "Havuç, patates ve kabağı küçük küp doğrayın.", "Havuç ve patatesi haşlama suyuna ekleyip 10 dakika pişirin.", "Kabağı ekleyip sebzeler yumuşayana kadar 8 dakika daha pişirin.", "Tavuğu geri ekleyip 2 dakika kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 55),
  GeneralRecipe(id: "paket39-g-052", title: "Kremasız mantar çorbası", category: "Çorbalar", ingredients: ["300 g mantar", "1 soğan", "2 yemek kaşığı un", "2 yemek kaşığı zeytinyağı", "4 su bardağı su", "1 su bardağı süt"], steps: ["Mantarları silip ince dilimleyin; soğanı ince doğrayın.", "Tencerede zeytinyağını ısıtıp soğanı 3 dakika yumuşatın.", "Mantarları ekleyip suyunu çekene kadar 6–7 dakika soteleyin.", "Unu ekleyip 1 dakika kavurun.", "Suyu azar azar ekleyip topak kalmayacak şekilde karıştırın; kaynayınca 10 dakika pişirin.", "Sütü ekleyip 3 dakika daha kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 34),
  GeneralRecipe(id: "paket39-g-053", title: "Balkabağı çorbası", category: "Çorbalar", ingredients: ["400 g balkabağı", "1 patates", "1 havuç", "1 soğan", "4 su bardağı su", "2 yemek kaşığı zeytinyağı"], steps: ["Balkabağı, patates ve havucu soyup küp doğrayın; soğanı doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Sebzeleri ekleyip 3 dakika çevirin.", "Suyu ekleyip kaynatın.", "Kapağı aralık bırakıp kısık ateşte, sebzeler çatalla kolayca ezilene kadar 20 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Kıvamı koyu gelirse sıcak su ekleyip 2 dakika daha kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 39),
  GeneralRecipe(id: "paket39-g-054", title: "Tahinli kabak tatlısı", category: "Tatlılar", ingredients: ["600 g balkabağı", "1 su bardağı şeker", "Yarım su bardağı su", "3 yemek kaşığı tahin", "3 yemek kaşığı dövülmüş ceviz"], steps: ["Balkabağını soyup çekirdeklerini ayıklayın; 4–5 cm iri küpler halinde doğrayın.", "Kabakları tencereye dizip şekeri üzerine serpin; 1 saat bekletip suyunu salmasını sağlayın.", "Suyu ekleyin; kapağı kapalı kısık ateşte 30–40 dakika, kabak yumuşayıp şerbetini çekene kadar pişirin.", "Bıçak ucuyla kontrol edin: kolayca batıyorsa meyve yumuşamıştır.", "Tencerede soğumaya bırakın; sıcakken taşırsanız dağılır.", "Kabakları servis tabağına alın.", "Servis ederken üzerine tahin ve dövülmüş ceviz gezdirin."], minutes: 60),
  GeneralRecipe(id: "paket39-g-055", title: "Portakallı kek", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "2 su bardağı un", "1 paket kabartma tozu", "1 portakal kabuğu rendesi"], steps: ["Yumurta ve şekeri köpürene kadar çırpın.", "Süt, yağ ve portakal kabuğunu ekleyin.", "Un ve kabartma tozunu karıştırıp kalıba dökün.", "175 °C fırında ortası pişene kadar yaklaşık 35 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "paket39-g-056", title: "Fırında sütlü irmik tatlısı", category: "Tatlılar", ingredients: ["1 litre süt", "8 yemek kaşığı irmik", "6 yemek kaşığı şeker", "1 paket vanilin", "1 yemek kaşığı tereyağı"], steps: ["Fırını 200°C’ye ısıtın.", "Süt, irmik ve şekeri tencerede soğukken çırparak karıştırın; topaklanmaz.", "Orta ateşte, dibi tutmasın diye sürekli karıştırarak 8–10 dakika, kaşıktan yavaş akacak kıvama gelene kadar pişirin.", "Ocaktan alıp vanilin ve tereyağını ekleyip karıştırın.", "Karışımı fırın kabına ya da kaselere dökün.", "Fırının üst rafında 10–15 dakika, üzeri hafif renk alana kadar pişirin.", "Oda sıcaklığına gelince üzerini kapatıp buzdolabında en az 1 saat soğutun."], minutes: 45),
  GeneralRecipe(id: "paket39-g-057", title: "Kahvaltılık patatesli yumurta", category: "Kahvaltılıklar", ingredients: ["2 patates", "3 yumurta", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kırmızı toz biber"], steps: ["Patatesleri soyup küçük küp doğrayın.", "Tavada zeytinyağını ısıtıp patatesleri kapağı kapalı, ara ara çevirerek 12–15 dakika yumuşayana ve kızarana kadar pişirin.", "Toz biberi ekleyip karıştırın.", "Yumurtaları üzerine kırın ve hafifçe karıştırın.", "Yumurtalar tamamen pişene, akışkan kısım kalmayana kadar pişirin; gebelikte ve çocuklarda bu özellikle önemlidir.", "Sıcak servis edin."], minutes: 25),
  GeneralRecipe(id: "paket39-g-058", title: "Sebzeli kinoa kasesi", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı kinoa", "1 salatalık", "1 kırmızı biber", "1 avokado", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Kinoayı bol suda yıkayıp iki ölçü suda yumuşayana kadar pişirin.", "Salatalık, biber ve avokadoyu doğrayın.", "Soğuyan kinoayla sebzeleri birleştirin.", "Limon suyu ve zeytinyağı ekleyerek karıştırın."], minutes: 35),
  GeneralRecipe(id: "paket39-g-059", title: "Fırında baharatlı patates", category: "Sebze yemekleri", ingredients: ["4 patates", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik", "1 çay kaşığı tatlı toz biber"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Patatesleri iyice fırçalayıp yıkayın; kabuklu ya da soyulmuş elma dilim doğrayın.", "Patatesleri 10 dakika soğuk suda bekletip nişastasını alın; iyice kurulayın.", "Yağ, kekik, toz biber ve az tuzla harmanlayın.", "Tepsiye tek kat dizin.", "35–40 dakika pişirin.", "Pişirmenin yarısında sebzeleri spatulayla çevirin ki her yüzü eşit kızarsın.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir."], minutes: 60),
  GeneralRecipe(id: "p39a4_001", title: "Sebzeli arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1 su bardağı arpa şehriye", "1 küçük havuç", "1 yeşil biber", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Havucu küçük küp, biberi ince doğrayın.", "Tencerede yağı ısıtıp arpa şehriyeyi sürekli karıştırarak açık kahverengi olana kadar 3–4 dakika kavurun.", "Sebzeleri ekleyip 3 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca kısık ateşte kapağı kapalı 12–15 dakika pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 42),
  GeneralRecipe(id: "p39a4_003", title: "Yoğurtlu pancar salatası", category: "Salatalar", ingredients: ["2 orta boy pancar", "4 yemek kaşığı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Pancarları kabuklarıyla, üzerini geçecek kadar suda bıçak kolayca batana kadar 40–45 dakika haşlayın.", "Ilıyınca kabuklarını soyup küçük küp doğrayın ya da rendeleyin; elleriniz boyanmasın diye eldiven kullanabilirsiniz.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Pancarı yoğurtla karıştırın.", "Servis tabağına alıp üzerine zeytinyağı gezdirin.", "Soğuk servis edin."], minutes: 55),
  GeneralRecipe(id: "p39a4_004", title: "Limonlu tavuk baget", category: "Tavuk yemekleri", ingredients: ["6 tavuk baget", "1 limonun suyu", "2 yemek kaşığı zeytinyağı", "2 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Fırını 190°C’ye ısıtın.", "Limon suyu, yağ, ezilmiş sarımsak, kekik ve az tuzu karıştırın.", "Bagetleri kâğıt havluyla kurulayıp birkaç yerinden bıçakla çizin; sos içe işler.", "Tavuğu sosa iyice bulayın; kapalı kapta buzdolabında en az 20 dakika bekletin.", "Bagetleri fırın kabına dizip kalan sosu üzerine dökün.", "40–45 dakika pişirin; yarısında çevirip tepsideki suyla yağlayın.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Ocaktan ya da fırından alıp 3–5 dakika dinlendirin; suyu içine çekilir ve daha sulu olur."], minutes: 80),
  GeneralRecipe(id: "p39a4_006", title: "Fırında kabak dilimleri", category: "Sebze yemekleri", ingredients: ["2 kabak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru nane", "1 çay kaşığı kırmızı biber"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Kabakları 1 cm kalınlığında eşit dilimleyin; kâğıt havluyla suyunu alın.", "Yağ, kuru nane, kırmızı biber ve az tuzla harmanlayın.", "Tepsiye tek kat dizin.", "20–25 dakika, kenarları kızarıp içleri yumuşayana kadar fırınlayın.", "Pişirmenin yarısında sebzeleri spatulayla çevirin ki her yüzü eşit kızarsın.", "Yoğurtla servis edebilirsiniz."], minutes: 35),
  GeneralRecipe(id: "p39a4_009", title: "Domatesli peynirli makarna", category: "Makarnalar", ingredients: ["250 g makarna", "2 domates", "100 g beyaz peynir", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı fesleğen"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Domatesleri rendeleyin; peyniri ufalayın.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Tavada yağı ısıtıp domatesi 6–7 dakika, suyunu biraz çekene kadar pişirin.", "Makarnayı sosa ekleyin; kıvam koyuysa ayırdığınız sudan katarak 1 dakika harmanlayın.", "Ufalanmış peynir ve fesleğenle servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a4_010", title: "Köz biberli yoğurt mezesi", category: "Mezeler", ingredients: ["3 kırmızı kapya biber", "5 yemek kaşığı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Biberleri fırında veya tavada közleyin.", "Kapalı kapta dinlendirip kabuklarını soyun.", "Küçük doğrayıp yoğurt ve sarımsakla karıştırın.", "Üzerine zeytinyağı gezdirin."], minutes: 20),
  GeneralRecipe(id: "p39a4_011", title: "Patatesli pırasa", category: "Sebze yemekleri", ingredients: ["3 pırasa", "2 patates", "1 havuç", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Pırasaların kök ve sert yeşil uçlarını kesin; boyuna yarıp katların arasındaki toprağı bol suyla yıkayın.", "Pırasaları halka, patates ve havucu küp doğrayın.", "Tencerede zeytinyağını ısıtıp havucu 3 dakika çevirin.", "Pırasa ve patatesi ekleyip 5 dakika soteleyin.", "Sıcak suyu ekleyin; kapağı kapalı kısık ateşte 25 dakika, sebzeler yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 43),
  GeneralRecipe(id: "p39a4_012", title: "Portakallı havuç salatası", category: "Salatalar", ingredients: ["3 havuç", "1 portakal", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı limon suyu"], steps: ["Havuçları soyup ince rendeleyin.", "Portakalın kabuğunu soyup dilimlerini zarlarından ayırın ve küçük doğrayın.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Havuç ve portakalı sosla harmanlayın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a4_013", title: "Fırında peynirli mantar", category: "Sebze yemekleri", ingredients: ["12 büyük mantar", "100 g rendelenmiş kaşar", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Mantarları nemli bezle silin; suya yatırmayın. Saplarını çıkarıp ince kıyın.", "Mantar çanaklarını tepsiye ters dizin ve 8 dakika pişirip suyunu dökün.", "Çanakları çevirip içlerine kıyılmış sap, az yağ, kekik ve peynir koyun.", "12–15 dakika, mantarlar yumuşayıp peynir eriyip kızarana kadar pişirin.", "Sıcak servis edin."], minutes: 33),
  GeneralRecipe(id: "p39a4_014", title: "Sebzeli kuskus", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "1 küçük kabak", "1 havuç", "2 yemek kaşığı zeytinyağı", "2 su bardağı su"], steps: ["Kuskusu paket talimatına göre haşlayın.", "Kabak ve havucu küçük küpler hâlinde doğrayın.", "Sebzeleri zeytinyağında yumuşayana kadar soteleyin.", "Süzülen kuskusla birleştirip sıcak servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a4_015", title: "Limonlu mercimek salatası", category: "Salatalar", ingredients: ["1 su bardağı yeşil mercimek", "2 dal taze soğan", "Yarım demet maydanoz", "2 yemek kaşığı limon suyu", "2 yemek kaşığı zeytinyağı"], steps: ["Yeşil mercimeği yıkayıp bol suda, dağılmadan diri kalacak şekilde 20–25 dakika haşlayın; süzüp soğutun.", "Taze soğanı ince doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Mercimek ve yeşillikleri birleştirin.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Sosu servis etmeden hemen önce dökün ve nazikçe harmanlayın; erken eklerseniz sebzeler su salar.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 50),
  GeneralRecipe(id: "p39a4_016", title: "Fırında armut tatlısı", category: "Tatlılar", ingredients: ["3 olgun armut", "1 çay kaşığı tarçın", "2 yemek kaşığı iri çekilmiş ceviz", "2 yemek kaşığı su"], steps: ["Fırını 180°C’ye ısıtın.", "Armutları yıkayıp ikiye bölün; çekirdek yuvalarını kaşıkla çıkarın.", "Kesik yüzleri yukarı bakacak şekilde fırın kabına dizin.", "Tarçın serpin; kabın dibine suyu ekleyin.", "25–30 dakika pişirin.", "Bıçak ucuyla kontrol edin: kolayca batıyorsa meyve yumuşamıştır.", "Ilıtıp cevizle servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a4_017", title: "Sebzeli yumurta muffin", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "Yarım kırmızı biber", "1 küçük kabak", "50 g beyaz peynir", "1 tatlı kaşığı zeytinyağı"], steps: ["Fırını 180 dereceye ısıtın ve muffin kalıplarını yağlayın.", "Sebzeleri küçük doğrayıp kabağı hafifçe sıkın.", "Yumurta, sebze ve ufalanmış peyniri karıştırın.", "Kalıplara paylaştırıp yumurta tamamen pişene kadar fırınlayın."], minutes: 30),
  GeneralRecipe(id: "p39a4_018", title: "Zeytinyağlı kereviz", category: "Sebze yemekleri", ingredients: ["2 kereviz", "1 havuç", "1 patates", "1 portakalın suyu", "3 yemek kaşığı zeytinyağı"], steps: ["Kereviz, havuç ve patatesi soyup eşit büyüklükte doğrayın; kereviz kararmasın diye limonlu suda tutun.", "Tencereye önce kerevizleri, üzerine havuç ve patatesi yerleştirin.", "Zeytinyağı, portakal suyu, az tuz ve sebzeleri yarıya kadar örtecek kadar su ekleyin.", "Kaynayınca kapağı kapalı kısık ateşte 30–35 dakika, kereviz yumuşayana kadar pişirin.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 45),
  GeneralRecipe(id: "p39a5_001", title: "Fırında sebzeli köfte", category: "Et yemekleri", ingredients: ["350 g kıyma", "1 küçük soğan", "1 yumurta", "3 yemek kaşığı galeta unu", "2 patates", "1 havuç", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın.", "Soğanı rendeleyip suyunu iyice sıkın.", "Kıyma, soğan, yumurta, galeta unu ve az tuzu 3–4 dakika, macun kıvamına gelene kadar yoğurun.", "Harçtan ceviz büyüklüğünde köfteler hazırlayın.", "Patates ve havucu ince dilimleyip yağ ve az tuzla harmanlayın.", "Köfte ve sebzeleri tepsiye tek kat yerleştirin.", "Yaklaşık 30 dakika pişirin.", "Pişirmenin yarısında köfteleri çevirin ki iki yüzü de kızarsın.", "Bir köfteyi ortadan bölüp kontrol edin: içi pembe kalmamalı; termometre varsa en az 71°C olmalı."], minutes: 45),
  GeneralRecipe(id: "p39a5_003", title: "Fırında karnabahar graten", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "1 su bardağı süt", "1 yemek kaşığı un", "1 yemek kaşığı tereyağı", "Yarım su bardağı rendelenmiş kaşar"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Karnabaharı çiçeklerine ayırıp kaynar tuzlu suda 6–8 dakika, hafif yumuşayana kadar haşlayın; süzün.", "Küçük tencerede tereyağını eritip unu 1–2 dakika kavurun; soğuk sütü azar azar ekleyip topak kalmayana kadar çırparak koyulaştırın.", "Karnabaharı fırın kabına alıp sosu üzerine dökün.", "Peyniri serpip 20 dakika, üzeri kızarana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 45),
  GeneralRecipe(id: "p39a5_006", title: "Tavuklu sebzeli noodle", category: "Dünya mutfağı", ingredients: ["250 g tavuk göğsü", "200 g noodle", "1 havuç", "1 kırmızı biber", "2 yemek kaşığı soya sosu", "1 yemek kaşığı sıvı yağ"], steps: ["Noodleı paket talimatına göre haşlayın.", "Tavuğu ince şeritler hâlinde kesip tavada tamamen pişirin.", "İnce doğranmış sebzeleri ekleyip diri kalacak şekilde soteleyin.", "Noodle ve soya sosunu ekleyip karıştırarak sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a5_008", title: "Ispanaklı peynirli börek", category: "Hamur işleri", ingredients: ["3 yufka", "300 g ıspanak", "150 g beyaz peynir", "1 yumurta", "Yarım su bardağı yoğurt", "3 yemek kaşığı sıvı yağ"], steps: ["Fırını 190°C’ye ısıtın; tepsiyi hafifçe yağlayın.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Ispanağı bol suda yıkayıp ince doğrayın; tavada 3 dakika suyunu çektirip soğutun.", "Ispanağı ufalanmış peynirle karıştırın.", "Yoğurt, yumurta ve yağı çırpın.", "Yufkaları ikiye kesin; her parçaya sos sürüp kenarına harç koyun ve rulo yapın.", "Rulo böreği yağlanmış tepsiye, ek yeri alta gelecek şekilde dizin.", "Kalan sosu üstüne sürüp 30–35 dakika, kızarana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 58),
  GeneralRecipe(id: "p39a5_010", title: "Portakallı kereviz", category: "Sebze yemekleri", ingredients: ["2 kereviz", "1 havuç", "1 patates", "1 portakalın suyu", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı su"], steps: ["Kereviz, havuç ve patatesi soyup küp doğrayın; kereviz kararmasın diye limonlu suda tutun.", "Tencerede zeytinyağını ısıtıp sebzeleri 4 dakika çevirin.", "Portakal suyu, su ve az tuzu ekleyin.", "Kapağı kapalı kısık ateşte 30 dakika, sebzeler yumuşayana kadar pişirin.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 50),
  GeneralRecipe(id: "p39a5_011", title: "Fırında yoğurtlu tavuk", category: "Tavuk yemekleri", ingredients: ["500 g tavuk but", "4 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı", "1 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Yoğurt, yağ, ezilmiş sarımsak, kekik ve az tuzu karıştırın.", "Tavuk butların fazla yağlarını alıp kurulayın.", "Tavuğu sosa iyice bulayın; kapalı kapta buzdolabında en az 20 dakika bekletin.", "Fırını 200°C’ye ısıtın; tavukları fırın kabına aralıklı yerleştirin.", "35–40 dakika pişirin; yarısında çevirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Ocaktan ya da fırından alıp 3–5 dakika dinlendirin; suyu içine çekilir ve daha sulu olur."], minutes: 75),
  GeneralRecipe(id: "p39a5_012", title: "Mantar sote", category: "Sebze yemekleri", ingredients: ["400 g kültür mantarı", "1 soğan", "1 yeşil biber", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Mantarları nemli bezle silip dilimleyin; suya yatırmayın.", "Soğanı piyazlık, biberi ince doğrayın.", "Geniş tavada yağı ısıtıp soğan ve biberi 4 dakika yumuşatın.", "Mantarları ekleyip yüksek ateşte, suyunu salıp çekene kadar 6–8 dakika soteleyin.", "Kekik ve tuzu ekleyip 1 dakika çevirin.", "Sıcak servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a5_013", title: "Elmalı tarçınlı kek", category: "Kek ve kurabiyeler", ingredients: ["2 elma", "3 yumurta", "1 su bardağı şeker", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "2 su bardağı un", "1 paket kabartma tozu", "1 çay kaşığı tarçın"], steps: ["Yumurta ve şekeri köpürene kadar çırpın.", "Süt ve yağı ekleyin; un, kabartma tozu ve tarçını karıştırın.", "Küp doğranmış elmaları hamura katıp kalıba dökün.", "175°C fırında ortasına batırılan kürdan temiz çıkana kadar pişirin."], minutes: 60),
  GeneralRecipe(id: "p39a5_014", title: "Nohutlu bulgur salatası", category: "Salatalar", ingredients: ["1 su bardağı ince bulgur", "1 su bardağı haşlanmış nohut", "1 salatalık", "2 domates", "Yarım demet maydanoz", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Bulguru geniş bir kâseye alıp sıcak suyu ekleyin; üzerini kapatıp 15 dakika şişmeye bırakın.", "Nohutları süzüp durulayın.", "Salatalık ve domatesleri küçük küp doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Bulguru çatalla havalandırıp tüm malzemeleri ekleyin.", "Limonun suyunu sıkıp zeytinyağı ve tuzla ekleyin; karıştırın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a5_015", title: "Fesleğenli domatesli makarna", category: "Makarnalar", ingredients: ["250 g makarna", "3 domates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "6 yaprak taze fesleğen"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Domatesleri küp doğrayın, sarımsağı ezin.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Geniş tavada zeytinyağını orta ateşte ısıtıp ezilmiş sarımsağı 30 saniye, yakmadan çevirin.", "Domatesleri ve az tuzu ekleyip 8–10 dakika, yumuşayıp sos olana kadar pişirin.", "Makarnayı sosa ekleyin; kıvam koyuysa ayırdığınız sudan katarak 1 dakika harmanlayın.", "Kıyılmış fesleğeni ekleyip servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a5_016", title: "Sebzeli fırın mücver", category: "Sebze yemekleri", ingredients: ["2 kabak", "1 havuç", "2 yumurta", "4 yemek kaşığı un", "Yarım demet dereotu", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabak ve havucu rendeleyin; bir tutam tuzla 5 dakika bekletip suyunu iyice sıkın.", "Dereotunu kıyın.", "Sebzeleri yumurta, un, dereotu ve yağla karıştırın.", "Yağlı kâğıt serili küçük bir kaba 2 cm kalınlığında yayın.", "25–30 dakika, üzeri kızarana kadar pişirin.", "Ortasına kürdan batırın: kuru çıkıyorsa ve yumurta tamamen pişmişse hazırdır.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 50),
  GeneralRecipe(id: "p39a5_018", title: "Tahinli cevizli kurabiye", category: "Kek ve kurabiyeler", ingredients: ["1 su bardağı tahin", "Yarım su bardağı pudra şekeri", "1,5 su bardağı un", "Yarım su bardağı çekilmiş ceviz", "1 çay kaşığı kabartma tozu"], steps: ["Tahin ve şekeri karıştırın.", "Un, ceviz ve kabartma tozunu ekleyip yumuşak hamur elde edin.", "Hamurdan küçük parçalar alıp tepsiye dizin.", "175°C fırında kenarları hafif renk alana kadar pişirip soğutun."], minutes: 35),
  GeneralRecipe(id: "p39a5_019", title: "Peynirli köz biber salatası", category: "Salatalar", ingredients: ["3 kırmızı biber", "100 g beyaz peynir", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "Bir tutam maydanoz"], steps: ["Biberleri ocak ateşinde ya da fırında kabukları kararana kadar 10–15 dakika közleyin; kapalı bir kapta 10 dakika terletin.", "Kabuklarını soyup çekirdeklerini ayıklayın ve şerit doğrayın.", "Beyaz peyniri ufalayın.", "Maydanozu ince kıyın.", "Biberleri tabağa dizip peyniri üzerine serpin.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Sosu gezdirip maydanozla süsleyin."], minutes: 25),
  GeneralRecipe(id: "p39a5_020", title: "Fırında sebzeli levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş levrek fileto", "1 kabak", "1 havuç", "1 limon", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabak ve havucu ince dilimleyip yağın yarısı ve az tuzla harmanlayın.", "Sebzeleri kaba yayıp 10 dakika ön pişirin.", "Balığı soğuk suyla durulayıp kâğıt havluyla iyice kurulayın.", "Filetoların üzerinde parmaklarınızı gezdirip kalan kılçıkları cımbızla çekin; çocuklar için özellikle önemlidir.", "Balıkları sebzelerin üzerine yerleştirin; limon dilimleri, kekik ve kalan yağı ekleyin.", "18–22 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 45),
  GeneralRecipe(id: "p39a6_001", title: "Terbiyeli tavuk çorbası", category: "Çorbalar", ingredients: ["250 g tavuk göğsü", "1 havuç", "3 yemek kaşığı yoğurt", "1 yumurta sarısı", "1 yemek kaşığı un", "5 su bardağı su"], steps: ["Tavuğu suyla tencereye alıp kaynatın; köpüğünü alıp kısık ateşte 25 dakika, içi tamamen beyazlayana kadar haşlayın.", "Tavuğu çıkarıp didikleyin; haşlama suyunu süzerek tencerede bırakın.", "Havucu rendeleyip haşlama suyuna ekleyin; 10 dakika pişirin.", "Terbiye için yoğurt, yumurta sarısı ve unu bir kâsede pürüzsüz olana kadar çırpın.", "Kaynayan çorbadan birkaç kepçe alıp terbiyeye azar azar ekleyerek ılıştırın; sonra terbiyeyi sürekli karıştırarak tencereye dökün.", "Sürekli karıştırarak bir taşım kaynatın ve ocağı kapatın; terbiyenin kesilmemesi için yüksek ateşte bırakmayın.", "Didiklenmiş tavuğu ekleyip karıştırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 45),
  GeneralRecipe(id: "p39a6_002", title: "Köz patlıcan çorbası", category: "Çorbalar", ingredients: ["2 patlıcan", "1 soğan", "1 yemek kaşığı tereyağı", "1 yemek kaşığı un", "3 su bardağı su", "1 su bardağı süt"], steps: ["Patlıcanları ocak ateşinde ya da fırında kabukları kararıp içleri yumuşayana kadar 15–20 dakika közleyin.", "Ilıyınca kabuklarını soyup içlerini bıçakla ince kıyın.", "Tencerede tereyağını eritip doğranmış soğanı 3 dakika yumuşatın; unu ekleyip 1 dakika kavurun.", "Suyu azar azar ekleyip topak kalmayacak şekilde karıştırın.", "Patlıcanı ekleyip kaynayınca kısık ateşte 10 dakika pişirin.", "Sütü ekleyip 3 dakika kaynatın.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 46),
  GeneralRecipe(id: "p39a6_003", title: "Kıymalı kabak yemeği", category: "Et yemekleri", ingredients: ["3 kabak", "200 g kıyma", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "1 çay bardağı su"], steps: ["Soğanı ince doğrayın, domatesleri küp kesin; kabakları yarım ay doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Domatesleri ekleyip 3 dakika pişirin.", "Kabakları ve suyu ekleyin.", "Kapağı kapalı kısık ateşte 20 dakika, kabaklar yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 45),
  GeneralRecipe(id: "p39a6_004", title: "Fırında kaşarlı tavuk", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü", "2 domates", "1 yeşil biber", "100 g kaşar peyniri", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın.", "Tavuğu kuşbaşı doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Tavada yağı ısıtıp tavuğu yüksek ateşte 3–4 dakika, dışı renk alana kadar mühürleyin.", "Domatesleri küp, biberi halka doğrayın.", "Tavuk, domates ve biberi fırın kabına alıp az tuzla karıştırın.", "20–25 dakika, tavuk tamamen pişene kadar pişirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Rendelenmiş kaşarı serpip 5 dakika daha, eriyene kadar fırınlayın."], minutes: 45),
  GeneralRecipe(id: "p39a6_006", title: "Fırında somon ve kuşkonmaz", category: "Balık ve deniz ürünleri", ingredients: ["2 somon fileto", "200 g kuşkonmaz", "1 limon", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kuşkonmazların sert alt uçlarını kırarak ayıklayın; yıkayıp kurulayın.", "Kuşkonmazları yağın yarısı, kekik ve az tuzla harmanlayın.", "Balığı soğuk suyla durulayıp kâğıt havluyla iyice kurulayın.", "Filetoların üzerinde parmaklarınızı gezdirip kalan kılçıkları cımbızla çekin; çocuklar için özellikle önemlidir.", "Somonları kuşkonmazlarla tepsiye koyun; kalan yağı gezdirip limon sıkın.", "15–20 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 30),
  GeneralRecipe(id: "p39a6_008", title: "Peynirli kabak mücveri", category: "Sebze yemekleri", ingredients: ["2 kabak", "2 yumurta", "100 g beyaz peynir", "4 yemek kaşığı un", "Yarım demet dereotu", "2 yemek kaşığı zeytinyağı"], steps: ["Kabakları rendeleyip bir tutam tuzla 5 dakika bekletin; sonra avucunuzla suyunu iyice sıkın.", "Peyniri ufalayın, dereotunu kıyın.", "Kabak, yumurta, peynir, un ve dereotunu karıştırın.", "Yapışmaz tavayı az yağla orta ateşte ısıtın; karışımı kaşıkla küçük porsiyonlar halinde koyup bastırın.", "Her yüzünü 3–4 dakika, içi tamamen pişip altı kızarana kadar pişirin.", "Kâğıt havluya alıp fazla yağını süzdürün; yoğurtla servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a6_009", title: "Fırında brokoli köftesi", category: "Sebze yemekleri", ingredients: ["1 küçük brokoli", "1 yumurta", "4 yemek kaşığı galeta unu", "80 g kaşar peyniri", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Brokoliyi çiçeklerine ayırıp buharda 6–7 dakika yumuşatın; soğutup ince kıyın.", "Peyniri rendeleyin; brokoli, yumurta, galeta unu ve peyniri yoğurun.", "Islak elle ceviz büyüklüğünde köfteler şekillendirip tepsiye dizin ve üzerlerine yağ sürün.", "20 dakika pişirin; çevirip 5 dakika daha, iki yüzü kızarana kadar fırınlayın.", "Sıcak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a6_010", title: "Nohutlu pazı yemeği", category: "Sebze yemekleri", ingredients: ["1 bağ pazı", "1 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Pazıyı yaprak yaprak bol suda yıkayın; sapları ince, yaprakları iri doğrayın.", "Soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Salçayı ekleyip 1 dakika kavurun.", "Önce pazı saplarını ekleyip 3 dakika çevirin; ardından yaprakları ve nohudu ilave edin.", "Suyu ekleyin; kapağı kapalı kısık ateşte pazı yumuşayana kadar 15 dakika pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a6_012", title: "Sebzeli karabuğday pilavı", category: "Pilavlar", ingredients: ["1 su bardağı karabuğday", "1 havuç", "1 kabak", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı su"], steps: ["Karabuğdayı yıkayıp süzün.", "Havuç, kabak ve soğanı küçük küp doğrayın.", "Tencerede yağı ısıtıp soğanı 3–4 dakika pembeleştirin.", "Havuç ve kabağı ekleyip 4 dakika çevirin.", "Karabuğdayı ekleyip 1 dakika kavurun.", "Suyu ve tuzu ekleyin; kaynayınca kısık ateşte kapağı kapalı 15–18 dakika pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 47),
  GeneralRecipe(id: "p39a6_013", title: "Kremasız mantarlı makarna", category: "Makarnalar", ingredients: ["250 g makarna", "250 g mantar", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı", "3 yemek kaşığı yoğurt"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Mantarları nemli bezle silip dilimleyin; suya yatırmayın.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Geniş tavada yağı ısıtıp mantarları ekleyin; yüksek ateşte suyunu salıp çekene kadar 6–8 dakika soteleyin.", "Ezilmiş sarımsağı ekleyip 30 saniye çevirin; tuzunu ayarlayın.", "Yoğurdu oda sıcaklığına getirip 2 kaşık makarna suyuyla çırpın; kesilmez.", "Ocağı kapatın; makarnayı ve yoğurdu ekleyip hızlıca harmanlayın.", "Sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a6_014", title: "Ispanaklı lazanya", category: "Dünya mutfağı", ingredients: ["8 lazanya yaprağı", "400 g ıspanak", "200 g lor peyniri", "2 su bardağı süt", "2 yemek kaşığı un", "1 yemek kaşığı tereyağı", "100 g kaşar"], steps: ["Ispanağı yıkayıp doğrayın ve tavada suyunu çektirin.", "Tereyağı, un ve sütle beşamel sos hazırlayın.", "Fırın kabında lazanya, ıspanak, lor ve sosu kat kat dizin.", "Üzerine kaşar serpip 180°C fırında yapraklar yumuşayana kadar pişirin."], minutes: 65),
  GeneralRecipe(id: "p39a6_015", title: "Tavuklu Sezar salata", category: "Salatalar", ingredients: ["250 g tavuk göğsü", "1 küçük marul", "2 dilim tam buğday ekmeği", "3 yemek kaşığı yoğurt", "1 tatlı kaşığı hardal", "1 yemek kaşığı limon suyu"], steps: ["Tavuğu ince dilimleyip ızgara tavasında her yüzü 5–6 dakika, içi tamamen beyazlayana kadar pişirin.", "Ekmekleri küp doğrayıp kuru tavada 5 dakika çıtırlaşana kadar kızartın.", "Yeşillikleri bol suda yıkayıp süzgeçte iyice süzdürün; kâğıt havluyla kurulayın.", "Marulu iri parçalara ayırın.", "Yoğurt, hardal ve limon suyunu çırpıp sos yapın; tuzunu ayarlayın.", "Marulu sosla harmanlayıp tavuk ve ekmekleri üzerine dizin."], minutes: 30),
  GeneralRecipe(id: "p39a6_016", title: "Pancarlı cevizli salata", category: "Salatalar", ingredients: ["2 orta boy pancar", "1 avuç ceviz", "50 g beyaz peynir", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Pancarları kabuklarıyla, üzerini geçecek kadar suda bıçak kolayca batana kadar 40–45 dakika haşlayın.", "Ilıyınca kabuklarını soyup küçük küp doğrayın ya da rendeleyin; elleriniz boyanmasın diye eldiven kullanabilirsiniz.", "Cevizi kuru tavada 2 dakika hafifçe kavurup iri kırın.", "Beyaz peyniri ufalayın.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Pancarı sosla harmanlayıp ceviz ve peyniri üzerine serpin."], minutes: 57),
  GeneralRecipe(id: "p39a6_017", title: "Kuru domatesli roka salatası", category: "Salatalar", ingredients: ["1 bağ roka", "6 kuru domates", "50 g tulum peyniri", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Yeşillikleri bol suda yıkayıp süzgeçte iyice süzdürün; kâğıt havluyla kurulayın.", "Kuru domatesleri 10 dakika ılık suda bekletip süzün ve şerit doğrayın.", "Tulum peynirini ufalayın.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Rokayı tabağa yayıp domates ve peyniri üzerine dağıtın.", "Sosu servis etmeden hemen önce dökün ve nazikçe harmanlayın; erken eklerseniz sebzeler su salar."], minutes: 20),
  GeneralRecipe(id: "p39a6_018", title: "Fırında sütlaç", category: "Tatlılar", ingredients: ["1 çay bardağı pirinç", "1 litre süt", "1 su bardağı şeker", "2 yemek kaşığı nişasta", "2 su bardağı su"], steps: ["Pirinci yıkayıp suyla tencereye alın; kısık ateşte 15–20 dakika, suyunu çekip iyice yumuşayana kadar haşlayın.", "Sütü ekleyin; dibi tutmasın diye karıştırarak kaynatın.", "Şekeri ekleyip 10 dakika kısık ateşte pişirin.", "Nişastayı yarım su bardağı soğuk su ya da sütle açın; karıştırarak tencereye ekleyin.", "Sürekli karıştırarak 5 dakika, koyulaşana kadar pişirin.", "Fırına dayanıklı kaselere paylaştırın; kaseleri içine su dökülmüş tepsiye dizin.", "Fırının üst ızgarasında 220°C’de 10–15 dakika, üzeri kızarana kadar gözünüzü ayırmadan pişirin.", "Oda sıcaklığına gelince üzerini kapatıp buzdolabında en az 1 saat soğutun."], minutes: 65),
  GeneralRecipe(id: "p39a6_021", title: "Peynirli dereotlu poğaça", category: "Hamur işleri", ingredients: ["2 su bardağı un", "1 yumurta", "Yarım su bardağı yoğurt", "Yarım çay bardağı sıvı yağ", "1 paket kabartma tozu", "100 g beyaz peynir", "Yarım demet dereotu"], steps: ["Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Yumurtayı kırıp sarısını üzerine sürmek için ayırın.", "Un ve kabartma tozunu karıştırın.", "Yumurta beyazı, yoğurt ve yağı ekleyip ele yapışmayan yumuşak bir hamur yoğurun; fazla yoğurmayın.", "Peyniri ufalayıp ince kıyılmış dereotuyla karıştırın.", "Hamurdan ceviz büyüklüğünde parçalar alıp açın; ortasına harç koyup kapatın.", "Tepsiye dizip yumurta sarısı sürün; 20–25 dakika, üzerleri kızarana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a6_022", title: "Patatesli gözleme", category: "Hamur işleri", ingredients: ["2 su bardağı un", "Yarım su bardağı su", "2 haşlanmış patates", "1 küçük soğan", "1 yemek kaşığı zeytinyağı"], steps: ["Un, su ve bir tutam tuzla ele yapışmayan yumuşak bir hamur yoğurun; üzerini örtüp 20 dakika dinlendirin.", "Soğanı ince doğrayıp yağda 4 dakika yumuşatın.", "Haşlanmış patatesleri ezip soğanla karıştırın; tuzunu ayarlayın.", "Hamuru 4 bezeye ayırıp merdaneyle ince açın.", "Bir yarısına harç yayıp diğer yarısını kapatın; kenarlarını bastırın.", "Kuru ya da çok az yağlı tavada orta ateşte her yüzünü 3–4 dakika, kızarana kadar pişirin.", "Sıcak servis edin."], minutes: 55),
  GeneralRecipe(id: "p39a6_024", title: "Haydari", category: "Mezeler", ingredients: ["1 su bardağı süzme yoğurt", "50 g beyaz peynir", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kuru nane"], steps: ["Beyaz peyniri çatalla ezin.", "Yoğurt ve ezilmiş sarımsakla karıştırın.", "Naneyi ve zeytinyağını ekleyin.", "Soğuk olarak servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a6_025", title: "Acılı ezme", category: "Mezeler", ingredients: ["3 domates", "2 yeşil biber", "1 küçük soğan", "Yarım demet maydanoz", "1 yemek kaşığı nar ekşisi", "1 yemek kaşığı zeytinyağı"], steps: ["Domates, biber ve soğanı çok ince doğrayın.", "Maydanozu yıkayıp kıyın.", "Sebzelerin fazla suyunu süzün.", "Nar ekşisi ve zeytinyağıyla harmanlayıp servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a7_001", title: "Terbiyeli kereviz çorbası", category: "Çorbalar", ingredients: ["1 kereviz", "1 havuç", "1 patates", "1 yumurta sarısı", "3 yemek kaşığı yoğurt", "1 yemek kaşığı limon suyu"], steps: ["Kereviz, havuç ve patatesi soyup küçük küp doğrayın; kerevizin kararmaması için limon suyunun yarısıyla harmanlayın.", "Sebzeleri 5 su bardağı suyla kaynatın; kısık ateşte 25 dakika, kereviz yumuşayana kadar pişirin.", "Yoğurt, yumurta sarısı ve kalan limon suyunu çırpın.", "Kaynayan çorbadan birkaç kepçe alıp terbiyeye azar azar ekleyerek ılıştırın; sonra terbiyeyi sürekli karıştırarak tencereye dökün.", "Sürekli karıştırarak bir taşım kaynatın ve ocağı kapatın; terbiyenin kesilmemesi için yüksek ateşte bırakmayın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 40),
  GeneralRecipe(id: "p39a7_002", title: "Köz biberli domates çorbası", category: "Çorbalar", ingredients: ["4 domates", "2 közlenmiş kırmızı biber", "1 soğan", "1 yemek kaşığı un", "2 yemek kaşığı zeytinyağı", "3 su bardağı su"], steps: ["Domatesleri rendeleyin; közlenmiş biberlerin kabuğunu ve çekirdeklerini ayıklayıp doğrayın.", "Soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Unu ekleyip 1 dakika kavurun.", "Domates ve biberi ekleyip 5 dakika pişirin.", "Suyu ekleyip kaynatın; kısık ateşte 15 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 35),
  GeneralRecipe(id: "p39a7_003", title: "Arpa şehriyeli yoğurt çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı arpa şehriye", "1 su bardağı yoğurt", "1 yumurta sarısı", "1 yemek kaşığı un", "4 su bardağı su", "1 tatlı kaşığı kuru nane"], steps: ["Arpa şehriyeyi suyla tencereye alıp kaynatın; kısık ateşte 12–15 dakika, yumuşayana kadar pişirin.", "Terbiye için yoğurt, yumurta sarısı ve unu bir kâsede pürüzsüz olana kadar çırpın.", "Kaynayan çorbadan birkaç kepçe alıp terbiyeye azar azar ekleyerek ılıştırın; sonra terbiyeyi sürekli karıştırarak tencereye dökün.", "Sürekli karıştırarak bir taşım kaynatın ve ocağı kapatın; terbiyenin kesilmemesi için yüksek ateşte bırakmayın.", "Kuru naneyi ekleyip karıştırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 30),
  GeneralRecipe(id: "p39a7_004", title: "Tavuklu nohutlu çorba", category: "Çorbalar", ingredients: ["200 g tavuk göğsü", "1 su bardağı haşlanmış nohut", "1 havuç", "1 küçük soğan", "4 su bardağı su", "1 yemek kaşığı zeytinyağı"], steps: ["Tavuğu suyla tencereye alıp kaynatın; köpüğünü alıp kısık ateşte 25 dakika, içi tamamen beyazlayana kadar haşlayın.", "Tavuğu çıkarıp didikleyin; haşlama suyunu süzerek tencerede bırakın.", "Soğanı ve havucu küçük doğrayın.", "Küçük bir tavada zeytinyağında soğan ve havucu 4 dakika soteleyip haşlama suyuna ekleyin.", "Nohudu ekleyip kısık ateşte 15 dakika pişirin.", "Tavuğu geri ekleyip 2 dakika kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 56),
  GeneralRecipe(id: "p39a7_005", title: "Fırında patlıcan musakka", category: "Sebze yemekleri", ingredients: ["3 patlıcan", "300 g kıyma", "1 soğan", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Fırını 200°C’ye ısıtın.", "Patlıcanları alacalı soyup 1 cm dilimleyin; tuzlu suda 15 dakika bekletip acısını alın, sıkıp kurulayın.", "Patlıcanları hafifçe yağlayıp tepside 15–20 dakika, yumuşayana kadar pişirin.", "Soğanı ince doğrayın, domatesleri küp kesin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Salça ve domatesi ekleyip 5 dakika pişirin.", "Fırın kabına patlıcan ve kıymalı harcı kat kat yerleştirin; suyu ekleyin.", "Fırını 190°C’ye düşürüp 25 dakika pişirin.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 92),
  GeneralRecipe(id: "p39a7_006", title: "Etli kuru bamya", category: "Et yemekleri", ingredients: ["200 g kuru bamya", "250 g kuşbaşı dana eti", "1 soğan", "2 domates", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Kuru bamyaları ılık suda 10 dakika bekletip yumuşatın.", "Limonun yarısını sıktığınız kaynar suda bamyaları 5 dakika haşlayıp süzün.", "Eti kâğıt havluyla kurulayın; kuru et daha iyi renk alır.", "Tencereyi yüksek ateşte iyice ısıtıp yağı ekleyin; eti kalabalık etmeden, her yüzü renk alana kadar 5–6 dakika mühürleyin.", "Soğanı ince doğrayıp ekleyin ve 4 dakika kavurun.", "Rendelenmiş domatesi ve üzerini örtecek kadar sıcak suyu ilave edin.", "Kapağı kapalı kısık ateşte 40 dakika, et yumuşayana kadar pişirin.", "Bamyaları ve kalan limon suyunu ekleyin; karıştırmadan, tencereyi sallayarak 15–20 dakika pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 95),
  GeneralRecipe(id: "p39a7_008", title: "Fırında sebzeli hindi köfte", category: "Tavuk yemekleri", ingredients: ["400 g hindi kıyma", "1 küçük kabak", "1 havuç", "1 yumurta", "3 yemek kaşığı galeta unu", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Tepsiye yağlı kâğıt serin.", "Sebzeleri ince rendeleyip avucunuzla suyunu iyice sıkın; köfte dağılmaz.", "Hindi kıyması, sebzeler, yumurta, galeta unu ve az tuzu yoğurun.", "Islak elle ceviz büyüklüğünde köfteler şekillendirip tepsiye aralıklı dizin.", "Üzerlerine fırçayla az yağ sürün.", "Yaklaşık 25 dakika pişirin.", "Pişirmenin yarısında köfteleri çevirin ki iki yüzü de kızarsın.", "Bir köfteyi ortadan bölüp kontrol edin: içi pembe kalmamalı; termometre varsa en az 74°C olmalı."], minutes: 45),
  GeneralRecipe(id: "p39a7_010", title: "Fırında karnabahar ve nohut", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "1 su bardağı haşlanmış nohut", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kimyon", "1 çay kaşığı toz kırmızı biber"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Karnabaharı küçük çiçeklere ayırıp yıkayın ve iyice kurulayın.", "Nohutları süzüp kâğıt havluyla kurulayın; kuru olursa çıtır olur.", "Karnabahar ve nohudu yağ, kimyon, toz biber ve az tuzla harmanlayın.", "Tepsiye tek kat yayın; 25–30 dakika pişirin.", "Pişirmenin yarısında sebzeleri spatulayla çevirin ki her yüzü eşit kızarsın.", "Yoğurt ya da limonla servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a7_011", title: "Yoğurtlu semizotu yemeği", category: "Sebze yemekleri", ingredients: ["1 bağ semizotu", "1 küçük soğan", "1 yemek kaşığı pirinç", "2 yemek kaşığı zeytinyağı", "1 su bardağı yoğurt", "1 diş sarımsak"], steps: ["Semizotunun kalın saplarını ayıklayın; yapraklarını bol suda birkaç kez yıkayıp süzün ve iri doğrayın.", "Soğanı ince doğrayın.", "Pirinci suyu berraklaşana kadar yıkayıp süzün.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Semizotu ve pirinci ekleyip 2 dakika çevirin; yarım su bardağı sıcak su ilave edin.", "Kapağı kapalı kısık ateşte pirinç pişene kadar 15 dakika pişirin.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Ilıyan yemeği sarımsaklı yoğurtla servis edin."], minutes: 31),
  GeneralRecipe(id: "p39a7_012", title: "Bulgurlu kabak dolması", category: "Sebze yemekleri", ingredients: ["4 kabak", "1 su bardağı ince bulgur", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı domates salçası"], steps: ["Kabakları ikiye bölüp içlerini kabuğu delmeden oyun.", "Soğanı ince kıyın, domatesleri rendeleyin.", "Bulgur, soğan, domatesin yarısı, salça, zeytinyağı ve az tuzu yoğurarak iç harcı hazırlayın.", "Kabakları bulgur şişeceği için fazla sıkıştırmadan doldurun.", "Dolmaları tencereye dik ve sık dizin ki pişerken dağılmasın; üzerine ters bir tabak kapatın.", "Kalan domatesi sıcak suyla karıştırıp dolmaların yarısına kadar dökün.", "Kaynayınca ateşi kısıp 30–35 dakika, kabak ve bulgur yumuşayana kadar pişirin.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 60),
  GeneralRecipe(id: "p39a7_013", title: "Limonlu fırın çipura", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş çipura", "1 limon", "1 soğan", "2 yemek kaşığı zeytinyağı", "3 dal maydanoz"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Balıkların içini ve pullarını kontrol edin; soğuk suyla durulayıp kâğıt havluyla kurulayın.", "Sırtlarına bıçakla 2–3 çizik atın.", "Soğan ve limonu dilimleyip fırın kabına yerleştirin.", "Balıkları yağlayıp az tuz serpin; içlerine maydanoz koyup soğanların üzerine yerleştirin.", "25–30 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Servis ederken kılçıkları ayırın; çocuk porsiyonunu kılçıksız hazırlayın.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 40),
  GeneralRecipe(id: "p39a7_014", title: "Sebzeli karides güveç", category: "Balık ve deniz ürünleri", ingredients: ["400 g ayıklanmış karides", "2 domates", "1 yeşil biber", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "80 g kaşar"], steps: ["Donmuş karidesi buzdolabında bir gece ya da soğuk su altında çözdürün; süzüp kurulayın.", "Fırını 190°C’ye ısıtın.", "Biberi ince doğrayın, sarımsağı ezin, domatesleri küp kesin.", "Tavada yağı ısıtıp biberi 3 dakika, sarımsağı 30 saniye soteleyin.", "Domatesi ekleyip 5–6 dakika, suyunu hafif çekene kadar pişirin; tuzunu ayarlayın.", "Karidesleri ekleyip 2–3 dakika pişirin.", "Karidesler pembeleşip C şeklini alınca pişmiştir; fazla pişirirseniz sertleşir.", "Güveç kaplarına paylaştırıp kaşar serpin; 8–10 dakika, üstü kızarana kadar fırınlayın."], minutes: 35),
  GeneralRecipe(id: "p39a7_016", title: "Dereotlu limonlu pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "1,5 su bardağı sıcak su", "1 yemek kaşığı tereyağı", "Yarım demet dereotu", "1 tatlı kaşığı limon suyu"], steps: ["Pirinci ılık tuzlu suda 20 dakika bekletin; suyu berraklaşana kadar yıkayıp süzün.", "Tencerede tereyağını eritin.", "Pirinci ekleyip taneler şeffaflaşana kadar 2–3 dakika kavurun.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi en kısığa alın ve kapağı kapalı 12–15 dakika, suyunu çekene kadar pişirin.", "Dereotunu ince kıyın.", "Demlenen pilava dereotu ve limon suyunu ekleyip çatalla karıştırın."], minutes: 48),
  GeneralRecipe(id: "p39a7_018", title: "Fırında peynirli erişte", category: "Makarnalar", ingredients: ["250 g erişte", "1 su bardağı süt", "1 yumurta", "100 g beyaz peynir", "80 g kaşar peyniri", "1 yemek kaşığı tereyağı"], steps: ["Fırını 180°C’ye ısıtın. Fırın kabını yağlayın.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Erişteyi paketteki süreden 2 dakika kısa, hafif diri haşlayıp süzün.", "Süt, yumurta ve ufalanmış beyaz peyniri çırpın.", "Erişteyi kaba alıp sosla harmanlayın; tereyağını küçük parçalar halinde üzerine dağıtın.", "Rendelenmiş kaşarı serpin.", "25–30 dakika, yumurtalı sos tamamen pişip üstü kızarana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin."], minutes: 47),
  GeneralRecipe(id: "p39a7_020", title: "Yeşil mercimekli pancar salatası", category: "Salatalar", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "2 haşlanmış pancar", "3 dal taze soğan", "Yarım demet maydanoz", "2 yemek kaşığı zeytinyağı", "1 limon"], steps: ["Haşlanmış pancarları küçük küp doğrayın.", "Taze soğanı ince doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Mercimeği süzüp pancar ve yeşilliklerle birleştirin.", "Limonun suyunu sıkıp zeytinyağı ve tuzla çırpın.", "Sosu servis etmeden hemen önce dökün ve nazikçe harmanlayın; erken eklerseniz sebzeler su salar.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a7_021", title: "Fırında ayva tatlısı", category: "Tatlılar", ingredients: ["2 ayva", "4 yemek kaşığı şeker", "1 çubuk tarçın", "3 karanfil", "1 su bardağı su"], steps: ["Fırını 180°C’ye ısıtın.", "Ayvaları yıkayıp tüylerini silin; kabuklarıyla ikiye bölün.", "Çekirdek yuvalarını kaşıkla çıkarın; çekirdekleri atmayın, renk için kabın dibine koyabilirsiniz.", "Ayvaları kesik yüzleri yukarı bakacak şekilde kaba dizip şekeri paylaştırın.", "Su, tarçın ve karanfili ekleyin; üzerini folyoyla kapatın.", "45–60 dakika pişirin; folyoyu açıp 10 dakika daha, şerbeti koyulaşana kadar pişirin.", "Bıçak ucuyla kontrol edin: kolayca batıyorsa meyve yumuşamıştır.", "Ilık servis edin."], minutes: 70),
  GeneralRecipe(id: "p39a7_022", title: "Elmalı tarçınlı crumble", category: "Dünya mutfağı", ingredients: ["3 elma", "1 çay kaşığı tarçın", "Yarım su bardağı un", "3 yemek kaşığı tereyağı", "3 yemek kaşığı esmer şeker", "3 yemek kaşığı yulaf"], steps: ["Elmaları küp doğrayıp tarçınla karıştırarak fırın kabına yayın.", "Un, tereyağı, şeker ve yulafı parmak uçlarıyla kırıntı kıvamına getirin.", "Kırıntıları elmaların üzerine dağıtın.", "180°C fırında elmalar yumuşayıp üstü kızarana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a7_023", title: "Ispanaklı lorlu krep", category: "Kahvaltılıklar", ingredients: ["2 yumurta", "1 su bardağı süt", "1 su bardağı un", "150 g ıspanak", "100 g lor", "1 yemek kaşığı zeytinyağı"], steps: ["Ispanağı yıkayıp ince doğrayın ve tavada 2 dakika söndürüp suyunu süzün.", "Lor peyniriyle ıspanağı karıştırın.", "Yumurta, süt ve unu topak kalmayana kadar çırpın; hamuru 10 dakika dinlendirin.", "Yapışmaz tavayı az yağla yağlayıp orta ateşte ısıtın; bir kepçe hamur döküp tavayı çevirerek ince yayın.", "Kenarları kalkınca çevirin; her yüzü 1–2 dakika pişirin.", "Kreplerin ortasına harç koyup rulo yapın ve sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a7_024", title: "Fırında yulaflı muzlu pankek", category: "Kahvaltılıklar", ingredients: ["2 olgun muz", "2 yumurta", "1 su bardağı yulaf unu", "Yarım su bardağı süt", "1 çay kaşığı kabartma tozu"], steps: ["Fırını 180°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Muzları ezin; yumurta ve sütü ekleyip çırpın.", "Yulaf unu ve kabartma tozunu ekleyip karıştırın.", "Karışımı kaba yayın.", "Fırında 20–25 dakika, üstü kızarıp kürdan kuru çıkana kadar pişirin.", "Dilimleyip ılık servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a7_025", title: "Zeytinli kekikli mini ekmek", category: "Hamur işleri", ingredients: ["2 su bardağı un", "1 paket instant maya", "Yarım su bardağı ılık su", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı çekirdeksiz zeytin", "1 tatlı kaşığı kekik"], steps: ["Un, maya ve bir tutam tuzu karıştırın; ılık suyu ve zeytinyağını ekleyip 8–10 dakika yumuşak bir hamur yoğurun.", "Zeytinleri çekirdeksizse doğrayın; kekikle birlikte hamura yedirin.", "Üzerini örtüp ılık yerde 45 dakika, iki katına çıkana kadar dinlendirin.", "Hamuru 8 parçaya ayırıp küçük ekmekler şekillendirin ve yağlı kâğıtlı tepsiye dizin.", "15 dakika daha dinlendirin; bu arada fırını 190°C’ye ısıtın.", "20–25 dakika, kabukları kızarana kadar pişirin.", "Ekmeğin altına parmağınızla vurun: boş ses geliyorsa içi pişmiştir.", "Tel ızgarada soğutun."], minutes: 105),
  GeneralRecipe(id: "p39a8_001", title: "Cevizli sarımsaklı semizotu cacığı", category: "Salatalar", ingredients: ["1 demet semizotu", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı ceviz"], steps: ["Semizotunun kalın saplarını ayıklayın; yapraklarını bol suda birkaç kez yıkayıp süzün ve iri doğrayın.", "Cevizi kuru tavada 2 dakika hafifçe kavurup iri kırın.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Semizotu ve cevizin çoğunu yoğurtla harmanlayın.", "Servis kâsesine alıp kalan ceviz ve zeytinyağıyla süsleyin.", "Soğuk servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a8_002", title: "Fırında kabak mücver", category: "Sebze yemekleri", ingredients: ["3 kabak", "2 yumurta", "4 yemek kaşığı un", "100 g beyaz peynir", "Yarım demet dereotu", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 180°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabakları rendeleyip bir tutam tuzla 5 dakika bekletin; sonra avucunuzla suyunu iyice sıkın.", "Peyniri ufalayın, dereotunu kıyın.", "Kabak, yumurta, un, peynir ve dereotunu karıştırın.", "Karışımı yağlanmış fırın kabına yayıp üzerine zeytinyağı gezdirin.", "Yaklaşık 30 dakika, içi pişip üstü kızarana kadar pişirin.", "Ortasına kürdan batırın: kuru çıkıyorsa ve yumurta tamamen pişmişse hazırdır.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 50),
  GeneralRecipe(id: "p39a8_003", title: "Közlenmiş patlıcanlı bulgur salatası", category: "Salatalar", ingredients: ["2 patlıcan", "1 su bardağı ince bulgur", "1,5 su bardağı sıcak su", "2 domates", "Yarım demet maydanoz", "2 yemek kaşığı zeytinyağı", "1 limon"], steps: ["Patlıcanları ocak ateşinde ya da fırında kabukları kararıp içleri yumuşayana kadar 15–20 dakika közleyin.", "Ilıyınca kabuklarını soyup içlerini bıçakla ince kıyın; acı suyunu süzdürün.", "Bulguru geniş bir kâseye alıp sıcak suyu ekleyin; üzerini kapatıp 15 dakika bekletin.", "Domatesleri küçük küp doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Bulgura patlıcan, domates ve maydanozu ekleyin.", "Limonun suyunu sıkıp zeytinyağı ve tuzla ekleyin; karıştırın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 60),
  GeneralRecipe(id: "p39a8_004", title: "Terbiyeli sulu köfte", category: "Et yemekleri", ingredients: ["300 g kıyma", "3 yemek kaşığı pirinç", "1 soğan", "1 havuç", "1 yumurta sarısı", "1 limon", "2 yemek kaşığı yoğurt", "5 su bardağı su"], steps: ["Pirinci yıkayıp süzün; soğanı rendeleyip suyunu sıkın.", "Kıyma, pirinç, soğan ve az tuzu yoğurun; nohut büyüklüğünde köfteler yapıp unlu tepside çevirin.", "Havucu küp doğrayıp suyla tencereye alın ve kaynatın.", "Köfteleri ekleyin; kısık ateşte 25–30 dakika, köfteler ve pirinç tamamen pişene kadar pişirin.", "Yoğurt, yumurta sarısı ve limon suyunu bir kâsede pürüzsüz olana kadar çırpın.", "Kaynayan çorbadan birkaç kepçe alıp terbiyeye azar azar ekleyerek ılıştırın; sonra terbiyeyi sürekli karıştırarak tencereye dökün.", "Sürekli karıştırarak bir taşım kaynatın ve ocağı kapatın; terbiyenin kesilmemesi için yüksek ateşte bırakmayın.", "Sıcak servis edin."], minutes: 55),
  GeneralRecipe(id: "p39a8_005", title: "Fırında mantarlı köfte", category: "Et yemekleri", ingredients: ["400 g kıyma", "250 g mantar", "1 soğan", "1 yumurta", "3 yemek kaşığı galeta unu", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 190°C’ye ısıtın.", "Soğanı rendeleyip suyunu iyice sıkın.", "Kıyma, soğan, yumurta, galeta unu ve az tuzu 3–4 dakika, macun kıvamına gelene kadar yoğurun.", "Islak elle eşit büyüklükte köfteler şekillendirin.", "Köfteleri fırın kabına aralıklı dizin.", "Mantarları nemli bezle silip dilimleyin; yağ ve kekikle harmanlayıp köftelerin arasına yayın.", "25–30 dakika pişirin.", "Pişirmenin yarısında köfteleri çevirin ki iki yüzü de kızarsın.", "Bir köfteyi ortadan bölüp kontrol edin: içi pembe kalmamalı; termometre varsa en az 71°C olmalı."], minutes: 50),
  GeneralRecipe(id: "p39a8_006", title: "Domates soslu nohutlu pazı", category: "Sebze yemekleri", ingredients: ["1 demet pazı", "1 su bardağı haşlanmış nohut", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Pazıyı yaprak yaprak bol suda yıkayın; sapları ince, yaprakları iri doğrayın.", "Soğanı ince doğrayın, domatesleri rendeleyin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Domatesi ekleyip 4 dakika pişirin.", "Pazı sapları, yaprakları, nohut ve suyu ekleyin.", "Kapağı kapalı kısık ateşte pazı yumuşayana kadar 15 dakika pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a8_007", title: "Fırında limonlu hindi", category: "Et yemekleri", ingredients: ["500 g hindi göğüs", "1 limon", "2 yemek kaşığı zeytinyağı", "2 diş sarımsak", "1 çay kaşığı kekik", "2 havuç"], steps: ["Fırını 190°C’ye ısıtın.", "Hindi etini 2 cm kalınlığında eşit dilimleyin.", "Çiğ eti ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Limon suyu, yağ, ezilmiş sarımsak, kekik ve az tuzu karıştırıp hindiyle harmanlayın; 15 dakika bekletin.", "Havuçları dilimleyip hindiyle birlikte fırın kabına yerleştirin.", "Üzerini folyoyla kapatıp 25 dakika pişirin; folyoyu açıp 10 dakika daha pişirin.", "Hindinin en kalın parçasını kesip kontrol edin: içi pembe kalmamalı; termometre varsa en az 74°C olmalı.", "Fırından alıp 5 dakika dinlendirin."], minutes: 55),
  GeneralRecipe(id: "p39a8_008", title: "Kırmızı mercimekli sebze köftesi", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı kırmızı mercimek", "1 havuç", "1 küçük kabak", "3 yemek kaşığı yulaf unu", "1 yumurta", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Mercimeği ayıklayıp suyu berraklaşana kadar birkaç kez yıkayın.", "Mercimeği kaynar suda 12–15 dakika yumuşayana kadar haşlayıp iyice süzün ve soğutun.", "Havuç ve kabağı ince rendeleyip suyunu iyice sıkın.", "Mercimek, sebzeler, yumurta, yulaf unu ve az tuzu karıştırın; kıvam yumuşaksa 1 kaşık yulaf unu ekleyin.", "Islak elle ceviz büyüklüğünde köfteler şekillendirip tepsiye dizin.", "Üzerlerine fırçayla yağ sürüp 15 dakika pişirin.", "Çevirip 8–10 dakika daha, iki yüzü kızarana kadar pişirin."], minutes: 50),
  GeneralRecipe(id: "p39a8_009", title: "Fırında domatesli barbunya", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış barbunya", "3 domates", "1 soğan", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay bardağı su"], steps: ["Fırını 180°C’ye ısıtın.", "Soğanı ince doğrayın, sarımsağı ezin; domatesleri rendeleyin.", "Tavada yağı ısıtıp soğanı 4 dakika yumuşatın; sarımsağı ekleyip 30 saniye çevirin.", "Domatesleri ekleyip 10 dakika pişirin.", "Haşlanmış bakliyatı süzgeçte durulayıp suyunu iyice süzdürün.", "Barbunyayı sos ve suyla fırın kabında karıştırın; tuzunu ayarlayın.", "Yaklaşık 25 dakika, sos koyulaşana kadar pişirin.", "Sıcak servis edin."], minutes: 55),
  GeneralRecipe(id: "p39a8_010", title: "Peynirli brokoli çorbası", category: "Çorbalar", ingredients: ["1 küçük brokoli", "1 patates", "1 soğan", "4 su bardağı su", "Yarım su bardağı süt", "60 g rendelenmiş kaşar"], steps: ["Patatesi soyup küp doğrayın; brokoliyi çiçeklerine ayırın, soğanı doğrayın.", "Soğan, patates ve suyu tencereye alıp kaynatın; 10 dakika pişirin.", "Brokoliyi ekleyip 10 dakika daha, yumuşayana kadar pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Sütü ekleyip kısık ateşte ısıtın; kaynatmadan kaşarı ekleyip eriyene kadar karıştırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 35),
  GeneralRecipe(id: "p39a8_011", title: "Şehriyeli domatesli tavuk çorbası", category: "Çorbalar", ingredients: ["200 g tavuk göğüs", "2 domates", "Yarım su bardağı arpa şehriye", "5 su bardağı su", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Tavuğu suyla tencereye alıp kaynatın; köpüğünü alıp kısık ateşte 25 dakika, içi tamamen beyazlayana kadar haşlayın.", "Tavuğu çıkarıp didikleyin; haşlama suyunu süzerek tencerede bırakın.", "Domatesleri rendeleyip zeytinyağında 5 dakika pişirin ve haşlama suyuna ekleyin.", "Arpa şehriyeyi ekleyip kısık ateşte 15 dakika pişirin.", "Tavuğu geri ekleyip 2 dakika kaynatın.", "Ocaktan alıp limon suyunu ekleyin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 57),
  GeneralRecipe(id: "p39a8_012", title: "Kabaklı yoğurtlu erişte", category: "Makarnalar", ingredients: ["250 g erişte", "2 kabak", "1 su bardağı yoğurt", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kuru nane"], steps: ["Erişteyi tuzlu kaynar suda paketteki süre kadar, yumuşayana dek haşlayıp süzün.", "Kabakları rendeleyip suyunu hafifçe sıkın.", "Tavada yağı ısıtıp kabağı 6–7 dakika, suyunu çekene kadar pişirin; tuzunu ayarlayın.", "Yoğurdu ezilmiş sarımsak ve az tuzla pürüzsüz olana kadar çırpın; oda sıcaklığına gelsin, sıcak makarnada kesilmez.", "Erişteyi kabakla harmanlayıp servis tabağına alın.", "Yoğurdu üzerine dökün.", "Kuru naneyi az yağda 10 saniye kızdırıp gezdirin."], minutes: 30),
  GeneralRecipe(id: "p39a8_013", title: "Fırında sebzeli kuskus", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "1 kabak", "1 kırmızı biber", "1 havuç", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Sebzeleri küçük küpler halinde doğrayın", "Sebzeleri yağla karıştırıp 190°C fırında yumuşatın", "Kuskusu sıcak suda paket talimatına göre pişirin", "Pişmiş kuskusu fırın sebzeleriyle harmanlayın."], minutes: 40),
  GeneralRecipe(id: "p39a8_014", title: "Karamelize soğanlı mercimek pilavı", category: "Pilavlar", ingredients: ["1 su bardağı yeşil mercimek", "1 su bardağı bulgur", "2 soğan", "3 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Mercimeği yıkayıp bol suda 15 dakika, diri kalacak şekilde haşlayıp süzün.", "Soğanları ince piyazlık doğrayın.", "Zeytinyağının yarısında soğanları kısık ateşte, sık sık karıştırarak koyu altın rengi olana kadar 15–20 dakika pişirin; yarısını süslemek için ayırın.", "Kalan soğanın üzerine mercimek ve bulguru ekleyip 2 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin.", "Ayırdığınız soğanı üzerine yayarak servis edin."], minutes: 72),
  GeneralRecipe(id: "p39a8_015", title: "Fırında elmalı yulaf", category: "Kahvaltılıklar", ingredients: ["2 elma", "1 su bardağı yulaf ezmesi", "1 su bardağı süt", "1 yumurta", "1 çay kaşığı tarçın", "2 yemek kaşığı ceviz"], steps: ["Fırını 180°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Elmaları küçük küp doğrayın, cevizi kırın.", "Yulaf, süt, yumurta ve tarçını karıştırın.", "Elmayı ekleyip karışımı kaba yayın ve cevizi serpin.", "Fırında 25 dakika, üstü kızarana kadar pişirin.", "Ilık servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a8_016", title: "Lor peynirli biber dolması", category: "Kahvaltılıklar", ingredients: ["4 küçük kapya biber", "150 g lor peyniri", "1 yumurta", "Yarım demet maydanoz", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Biberlerin tepesini kesip çekirdeklerini temizleyin.", "Lor, yumurta ve ince kıyılmış maydanozu karıştırın.", "Harcı biberlere doldurup kaba dizin; zeytinyağı gezdirin.", "Fırında 20–25 dakika, biberler yumuşayıp harç tamamen pişene kadar pişirin.", "Ilık servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a8_017", title: "Portakallı irmik tatlısı", category: "Tatlılar", ingredients: ["1 su bardağı irmik", "3 su bardağı süt", "Yarım su bardağı şeker", "1 portakalın kabuğu", "1 yemek kaşığı tereyağı"], steps: ["Portakal kabuğunu beyaz kısmına gelmeden ince rendeleyin.", "Süt, irmik ve şekeri tencerede soğukken çırparak karıştırın; topaklanmaz.", "Orta ateşte, dibi tutmasın diye sürekli karıştırarak 8–10 dakika, kaşıktan yavaş akacak kıvama gelene kadar pişirin.", "Ocaktan alıp portakal kabuğu ve tereyağını ekleyip karıştırın.", "Kaselere paylaştırın.", "Oda sıcaklığına gelince üzerini kapatıp buzdolabında en az 1 saat soğutun."], minutes: 30),
  GeneralRecipe(id: "p39a8_018", title: "Kıyır tahinli ceviz kurabiyesi", category: "Kek ve kurabiyeler", ingredients: ["1 su bardağı tahin", "Yarım su bardağı pudra şekeri", "2 su bardağı un", "Yarım su bardağı ceviz", "1 çay kaşığı kabartma tozu"], steps: ["Tahin ve pudra şekerini karıştırın", "Un, kabartma tozu ve ince kıyılmış cevizi ekleyip hamur yapın", "Küçük toplar şekillendirip tepsiye dizin", "170°C fırında hafif renk alana kadar pişirip soğutun."], minutes: 35),
  GeneralRecipe(id: "p39a8_019", title: "Fırında peynirli karnabahar topları", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 küçük karnabahar", "1 yumurta", "100 g rendelenmiş kaşar", "4 yemek kaşığı galeta unu", "1 yemek kaşığı zeytinyağı"], steps: ["Karnabaharı buharda yumuşatıp iyice süzün", "Çatalla ezip yumurta, peynir ve galeta unuyla karıştırın", "Küçük toplar hazırlayıp yağlı kağıda dizin", "190°C fırında her tarafı kızarana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a8_020", title: "Köz biberli humus", category: "Mezeler", ingredients: ["2 su bardağı haşlanmış nohut", "2 közlenmiş kırmızı biber", "2 yemek kaşığı tahin", "1 limon", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı"], steps: ["Nohutları iyice haşlayıp süzün", "Közlenmiş biberlerin kabuklarını soyun", "Nohut, biber, tahin, limon ve sarımsağı pürüzsüz olana kadar çekin", "Kıvamı suyla ayarlayıp zeytinyağıyla servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a9_001", title: "Fırında sebzeli tavuk şiş", category: "Et yemekleri", ingredients: ["500 g tavuk göğsü", "1 kabak", "1 kırmızı biber", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200°C’ye ısıtın. Tepsiye yağlı kâğıt serin.", "Tavuğu 3 cm küp, kabak, biber ve soğanı benzer büyüklükte doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Tavuk ve sebzeleri zeytinyağı, kekik ve az tuzla harmanlayın.", "Tahta şiş kullanacaksanız 20 dakika suda bekletin; fırında yanmaz.", "Malzemeleri sırayla şişlere dizip tepsiye yerleştirin.", "Yaklaşık 25 dakika pişirin; yarısında şişleri çevirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı."], minutes: 55),
  GeneralRecipe(id: "p39a9_002", title: "Cevizli yoğurtlu pancar salatası", category: "Salatalar", ingredients: ["2 orta boy pancar", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı ceviz"], steps: ["Pancarları kabuklarıyla, üzerini geçecek kadar suda bıçak kolayca batana kadar 40–45 dakika haşlayın.", "Ilıyınca kabuklarını soyup küçük küp doğrayın ya da rendeleyin; elleriniz boyanmasın diye eldiven kullanabilirsiniz.", "Cevizi kuru tavada 2 dakika hafifçe kavurup iri kırın.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Pancar ve cevizin çoğunu yoğurtla karıştırın.", "Kalan ceviz ve zeytinyağıyla süsleyip soğuk servis edin."], minutes: 57),
  GeneralRecipe(id: "p39a9_004", title: "Fırında ıspanaklı patates", category: "Sebze yemekleri", ingredients: ["3 patates", "250 g ıspanak", "1 soğan", "2 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Patatesleri soyup ince dilimleyin; kaynar tuzlu suda 8 dakika haşlayıp süzün.", "Ispanağı bol suda 2–3 kez yıkayıp toprağını iyice giderin; süzüp iri doğrayın.", "Soğanı ince doğrayıp tavada yağda 3 dakika yumuşatın; ıspanağı ekleyip suyunu çekene kadar 5 dakika pişirin.", "Patates ve ıspanağı fırın kabına kat kat yerleştirin.", "Yumurtaları sütle çırpıp üzerine dökün.", "25 dakika, yumurta tamamen pişip üzeri kızarana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 53),
  GeneralRecipe(id: "p39a9_005", title: "Nohutlu karnabahar yemeği", category: "Bakliyat yemekleri", ingredients: ["1 küçük karnabahar", "1 su bardağı haşlanmış nohut", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Karnabaharı küçük çiçeklere ayırıp yıkayın.", "Soğanı ince doğrayın, domatesleri rendeleyin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Domatesi ekleyip 3 dakika pişirin.", "Haşlanmış bakliyatı süzgeçte durulayıp suyunu iyice süzdürün.", "Karnabahar, nohut ve suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı kapalı 20–25 dakika, karnabahar yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 42),
  GeneralRecipe(id: "p39a9_006", title: "Limonlu dereotlu somon", category: "Balık ve deniz ürünleri", ingredients: ["2 somon fileto", "1 limon", "2 yemek kaşığı zeytinyağı", "Yarım demet dereotu", "1 diş sarımsak"], steps: ["Fırını 180°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Balığı soğuk suyla durulayıp kâğıt havluyla iyice kurulayın.", "Filetoların üzerinde parmaklarınızı gezdirip kalan kılçıkları cımbızla çekin; çocuklar için özellikle önemlidir.", "Somon filetoları fırın kabına yerleştirin.", "Limon suyu, yağ, ezilmiş sarımsak ve az tuzu karıştırıp üzerine sürün.", "18–20 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Kıyılmış dereotuyla servis edin.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 35),
  GeneralRecipe(id: "p39a9_007", title: "Tavuklu arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1 su bardağı arpa şehriye", "200 g tavuk göğsü", "1 havuç", "2 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu küçük küp doğrayıp yağda, rengi tamamen beyazlayana kadar 6–7 dakika soteleyin.", "Havucu küçük küp doğrayıp ekleyin; 3 dakika çevirin.", "Arpa şehriyeyi ekleyip 3 dakika kavurun.", "Sıcak suyu ve tuzu ekleyin; kaynayınca kısık ateşte kapağı kapalı 12–15 dakika pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 48),
  GeneralRecipe(id: "p39a9_008", title: "Fırında yoğurtlu kabak", category: "Sebze yemekleri", ingredients: ["3 kabak", "1 su bardağı yoğurt", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kuru nane"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Kabakları 1 cm halka dilimleyin; kâğıt havluyla suyunu alın.", "Yağla harmanlayıp tepsiye tek kat dizin.", "20–25 dakika, yumuşayana kadar pişirin.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Ilıyan kabakları servis tabağına alın; üzerine yoğurt dökün.", "Kuru naneyi serpip servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a9_009", title: "Peynirli pırasalı börek", category: "Hamur işleri", ingredients: ["3 yufka", "2 pırasa", "150 g beyaz peynir", "1 yumurta", "Yarım çay bardağı süt", "3 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; tepsiyi hafifçe yağlayın.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Pırasaları boyuna yarıp katlarını iyice yıkayın; ince doğrayın.", "Tavada yağın yarısıyla pırasayı 8 dakika yumuşatın ve soğutun.", "Soğuyan pırasayı ufalanmış peynirle karıştırın.", "Yumurtayı sütle çırpın; yarısını yufkalara sürmek, yarısını üstüne sürmek için ayırın.", "Yufkaları ikiye kesip sosla hafifçe ıslatın; harcı paylaştırıp rulo yapın.", "Rulo böreği yağlanmış tepsiye, ek yeri alta gelecek şekilde dizin.", "Kalan sosu üstüne sürüp 30 dakika, kızarana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı."], minutes: 50),
  GeneralRecipe(id: "p39a9_010", title: "Bulgurlu yeşil mercimek salatası", category: "Salatalar", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "Yarım su bardağı ince bulgur", "1 salatalık", "1 kırmızı biber", "Yarım demet maydanoz", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Bulguru geniş bir kâseye alıp 1 su bardağı sıcak suyla ıslatın; üzerini kapatıp 15 dakika bekletin.", "Salatalık ve kırmızı biberi küçük küp doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Mercimeği süzüp bulgura ekleyin.", "Sebzeleri ve maydanozu ekleyin.", "Limonun suyunu sıkıp zeytinyağı ve tuzla ekleyin; karıştırın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a9_011", title: "Fırında ballı tarçınlı armut", category: "Tatlılar", ingredients: ["3 armut", "2 yemek kaşığı bal", "1 çay kaşığı tarçın", "3 yemek kaşığı ceviz"], steps: ["Fırını 180°C’ye ısıtın.", "Armutları yıkayıp ikiye kesin; çekirdek yuvalarını kaşıkla çıkarın.", "Kesik yüzleri yukarı bakacak şekilde fırın kabına dizin; dibine 2 kaşık su ekleyin.", "Tarçın serpip 25–30 dakika pişirin.", "Bıçak ucuyla kontrol edin: kolayca batıyorsa meyve yumuşamıştır.", "Ilıdıktan sonra bal gezdirip cevizi serpin.", "Bal 1 yaşından küçük bebeklere verilmez; bebek porsiyonunu balsız ayırın."], minutes: 40),
  GeneralRecipe(id: "p39a9_012", title: "Domatesli fesleğenli bulgur", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "2 domates", "1 soğan", "2 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı", "5 yaprak fesleğen"], steps: ["Bulguru bir kez yıkayıp süzün.", "Soğanı ince doğrayın, domatesleri rendeleyin.", "Tencerede yağı ısıtıp soğanı 3–4 dakika pembeleştirin.", "Domatesi ekleyip 4 dakika pişirin.", "Bulguru ekleyip yağa bulanması için 1–2 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Fesleğeni yırtarak ekleyin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 45),
  GeneralRecipe(id: "p39a9_013", title: "Fırında nohut köftesi", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış nohut", "1 küçük soğan", "1 yumurta", "3 yemek kaşığı galeta unu", "1 çay kaşığı kimyon", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Haşlanmış bakliyatı süzgeçte durulayıp suyunu iyice süzdürün.", "Nohudu çatalla ezin ya da rondoda kısa süre çekin; tamamen püre yapmayın.", "Soğanı rendeleyip suyunu sıkın.", "Nohut, soğan, yumurta, galeta unu, kimyon ve az tuzu yoğurun.", "Islak elle ceviz büyüklüğünde köfteler şekillendirip tepsiye dizin.", "Üzerlerine fırçayla yağ sürüp 15 dakika pişirin.", "Çevirip 8–10 dakika daha, iki yüzü kızarana kadar pişirin.", "Yoğurt ya da limonla servis edin."], minutes: 45),
  GeneralRecipe(id: "p39a9_014", title: "Sütlü kabak çorbası", category: "Çorbalar", ingredients: ["2 kabak", "1 patates", "1 soğan", "3 su bardağı su", "1 su bardağı süt", "1 yemek kaşığı zeytinyağı"], steps: ["Kabak ve patatesi soyup küp doğrayın; soğanı doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Kabak, patates ve suyu ekleyip kaynatın.", "Kapağı aralık bırakıp kısık ateşte, sebzeler çatalla kolayca ezilene kadar 20 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Sütü ekleyip 3 dakika kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 37),
  GeneralRecipe(id: "p39a9_015", title: "Fırında patatesli alabalık", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş alabalık", "2 patates", "1 limon", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Patatesleri ince dilimleyip yağın yarısı ve az tuzla harmanlayın; kaba yayın.", "Patatesleri 15 dakika ön pişirin; balık daha çabuk pişer.", "Alabalıkların içini kontrol edip durulayın ve kurulayın.", "Alabalıkları patateslerin üzerine yerleştirin; limon suyu, kalan yağ ve kekik ekleyin.", "20–25 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Patateslerin de çatalla kolayca delindiğini kontrol edin.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 50),
  GeneralRecipe(id: "p39a9_016", title: "Yoğurtlu havuçlu makarna", category: "Makarnalar", ingredients: ["250 g makarna", "2 havuç", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Havucu rendeleyin.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Tavada yağı ısıtıp havucu 4–5 dakika yumuşatın; tuzunu ayarlayın.", "Yoğurdu ezilmiş sarımsak ve az tuzla pürüzsüz olana kadar çırpın; oda sıcaklığına gelsin, sıcak makarnada kesilmez.", "Ilık makarnayı havuçla harmanlayın; yoğurdu ekleyip karıştırın.", "Ilık servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a9_017", title: "Fırında peynirli domates", category: "Kahvaltılıklar", ingredients: ["4 domates", "120 g lor peyniri", "1 yumurta", "Yarım demet maydanoz", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Domateslerin tepesini kesip içlerini kaşıkla oyun.", "Lor, yumurta ve kıyılmış maydanozu karıştırın.", "Harcı domateslere doldurup kaba dizin; zeytinyağı gezdirin.", "Fırında 20 dakika, harç tamamen pişene kadar pişirin.", "Ilık servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a9_018", title: "Portakallı havuçlu kek", category: "Kek ve kurabiyeler", ingredients: ["2 havuç", "2 yumurta", "1 su bardağı un", "Yarım su bardağı şeker", "Yarım su bardağı sıvı yağ", "1 portakalın kabuğu", "1 paket kabartma tozu"], steps: ["Yumurta ve şekeri çırpıp yağı ekleyin.", "Rendelenmiş havuç ve portakal kabuğunu karıştırın.", "Un ve kabartma tozunu ekleyip kalıba dökün.", "175°C fırında kürdan temiz çıkana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a9_019", title: "Köz patlıcanlı yoğurt mezesi", category: "Mezeler", ingredients: ["2 patlıcan", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı limon suyu"], steps: ["Patlıcanları ocakta veya fırında tamamen yumuşayana kadar közleyin.", "Kabuklarını soyup içini ince doğrayın.", "Yoğurt, sarımsak ve limonla karıştırın.", "Zeytinyağı gezdirerek soğuk servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a9_020", title: "Sebzeli yumurtalı pirinç", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "2 yumurta", "1 havuç", "Yarım su bardağı bezelye", "2 yemek kaşığı zeytinyağı", "1,5 su bardağı sıcak su"], steps: ["Pirinci ılık tuzlu suda 20 dakika bekletin; suyu berraklaşana kadar yıkayıp süzün.", "Havucu küçük küp doğrayın.", "Tencerede yağın yarısını ısıtıp havuç ve bezelyeyi 4 dakika soteleyin.", "Pirinci ekleyip taneler şeffaflaşana kadar 2–3 dakika kavurun.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi en kısığa alın ve kapağı kapalı 12–15 dakika, suyunu çekene kadar pişirin.", "Ayrı tavada kalan yağla yumurtaları karıştırarak, tamamen pişene kadar 2–3 dakika pişirin.", "Yumurtayı pilava ekleyip çatalla karıştırın ve servis edin."], minutes: 55),
  GeneralRecipe(id: "p39a10_001", title: "Fırında sebzeli tavuk güveç", category: "Tavuk yemekleri", ingredients: ["400 g kuşbaşı tavuk", "1 kabak", "1 patlıcan", "2 domates", "1 kapya biber", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın.", "Tavuğu kuşbaşı doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Patlıcanı alacalı soyup küp doğrayın; tuzlu suda 15 dakika bekletip sıkın.", "Kabak, domates ve kapya biberi küp doğrayın.", "Tavuk ve sebzeleri fırın kabına alın; zeytinyağı, az tuz ve yarım çay bardağı su ekleyip karıştırın.", "Üzerini folyoyla kapatıp 30 dakika pişirin.", "Folyoyu açıp 10 dakika daha pişirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı."], minutes: 65),
  GeneralRecipe(id: "p39a10_002", title: "Cevizli yoğurtlu semizotu kasesi", category: "Salatalar", ingredients: ["1 demet semizotu", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Semizotunun kalın saplarını ayıklayın; yapraklarını bol suda birkaç kez yıkayıp süzün ve iri doğrayın.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Semizotunu sarımsaklı yoğurtla harmanlayın.", "Servis tabağına alıp üzerine zeytinyağı gezdirin.", "Soğuk servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a10_005", title: "Kırmızı mercimekli kabak çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı kırmızı mercimek", "2 kabak", "1 soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Mercimeği suyu berraklaşana kadar birkaç kez yıkayıp süzün.", "Kabakları küp, soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Kabakları ekleyip 3 dakika çevirin.", "Mercimeği ve suyu ekleyip kaynatın; köpüğünü alın.", "Kapağı aralık bırakıp kısık ateşte, ara ara karıştırarak mercimek dağılana kadar 25 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 42),
  GeneralRecipe(id: "p39a10_006", title: "Domatesli barbunya pilaki", category: "Sebze yemekleri", ingredients: ["2 su bardağı haşlanmış barbunya", "2 domates", "1 havuç", "1 soğan", "3 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Soğanı yemeklik, havucu küp doğrayın; domatesleri rendeleyin.", "Tencerede zeytinyağını ısıtıp soğan ve havucu 5 dakika yumuşatın.", "Domatesleri ekleyip 5 dakika pişirin.", "Haşlanmış barbunya ve suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı aralık 20 dakika, suyu biraz azalana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 40),
  GeneralRecipe(id: "p39a10_007", title: "Fırında peynirli kabak ruloları", category: "Sebze yemekleri", ingredients: ["2 kabak", "100 g lor peyniri", "2 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı", "1 tutam dereotu"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabakları soyacakla ya da keskin bıçakla uzunlamasına ince dilimleyin.", "Dilimleri yağlayıp tepsiye dizin; 10 dakika, kıvrılabilecek kadar yumuşatın.", "Dereotunu kıyın; lor, yoğurt ve dereotunu karıştırın.", "Her dilimin ucuna bir kaşık harç koyup sarın; kapanan yüzü alta gelecek şekilde dizin.", "10 dakika daha fırınlayın.", "Ilık servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a10_008", title: "Bulgurlu yeşil mercimek çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı yeşil mercimek", "3 yemek kaşığı bulgur", "1 soğan", "1 yemek kaşığı domates salçası", "5 su bardağı su"], steps: ["Yeşil mercimeği yıkayıp suyla tencereye alın; kaynayınca kısık ateşte 20 dakika pişirin.", "Soğanı ince doğrayıp ayrı bir tavada yağsız ya da birkaç kaşık suyla 4 dakika yumuşatın; salçayı ekleyip 1 dakika çevirin.", "Soğanlı salçayı ve bulguru mercimeğe ekleyin.", "Kısık ateşte, ara ara karıştırarak bulgur ve mercimek yumuşayana kadar 15–20 dakika pişirin.", "Kıvamı koyu gelirse sıcak su ekleyip 2 dakika daha kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 56),
  GeneralRecipe(id: "p39a10_009", title: "Tahinli havuç salatası", category: "Salatalar", ingredients: ["3 havuç", "2 yemek kaşığı tahin", "2 yemek kaşığı yoğurt", "1 yemek kaşığı limon suyu", "1 yemek kaşığı zeytinyağı"], steps: ["Havuçları soyup ince rendeleyin.", "Zeytinyağında havucu 3 dakika soteleyip soğutun; tatlılığı artar.", "Tahin, yoğurt ve limon suyunu pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Havucu sosla harmanlayın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 28),
  GeneralRecipe(id: "p39a10_010", title: "Fırında domatesli köfte", category: "Et yemekleri", ingredients: ["400 g kıyma", "1 küçük soğan", "2 yemek kaşığı galeta unu", "3 domates", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın.", "Soğanı rendeleyip suyunu iyice sıkın.", "Kıyma, soğan, galeta unu ve az tuzu macun kıvamına gelene kadar yoğurun.", "Islak elle eşit büyüklükte köfteler şekillendirin.", "Domatesleri halka dilimleyin; köftelerle sırayla fırın kabına dizin.", "Üzerine zeytinyağı gezdirin.", "Yaklaşık 30 dakika pişirin.", "Bir köfteyi ortadan bölüp kontrol edin: içi pembe kalmamalı; termometre varsa en az 71°C olmalı."], minutes: 45),
  GeneralRecipe(id: "p39a10_011", title: "Portakallı kereviz salatası", category: "Salatalar", ingredients: ["1 küçük kereviz", "1 portakal", "1 havuç", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Kerevizi ve havucu soyup ince rendeleyin; kerevizin kararmaması için hemen limon suyuyla harmanlayın.", "Portakalın kabuğunu soyup dilimlerini zarlarından ayırın ve küçük doğrayın.", "Zeytinyağı ve tuzu ekleyip karıştırın.", "Portakalı ekleyip nazikçe harmanlayın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a10_013", title: "Kabaklı bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "1 kabak", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Bulguru bir kez yıkayıp süzün.", "Kabağı küçük küp, soğanı ince doğrayın.", "Tencerede yağı ısıtıp soğanı 3–4 dakika pembeleştirin.", "Kabağı ekleyip 3 dakika çevirin.", "Bulguru ekleyip yağa bulanması için 1–2 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 44),
  GeneralRecipe(id: "p39a10_014", title: "Elmalı tarçınlı fırın yulaf", category: "Kahvaltılıklar", ingredients: ["1 su bardağı yulaf", "1 elma", "1 yumurta", "Yarım su bardağı süt", "1 çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Elmayı rendeleyin.", "Yulaf, elma, yumurta, süt ve tarçını karıştırın.", "Kaba yayın ve fırında 20–25 dakika, ortası sertleşene kadar pişirin.", "Dilimleyip ılık servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a10_015", title: "Fırında nohutlu patlıcan", category: "Sebze yemekleri", ingredients: ["2 patlıcan", "1 su bardağı haşlanmış nohut", "2 domates", "1 soğan", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın.", "Patlıcanları alacalı soyup doğrayın; tuzlu suda 15 dakika bekletip acısını alın, sıkıp kurulayın.", "Patlıcanları az yağla harmanlayıp tepside 15 dakika yumuşatın.", "Soğanı ince doğrayın, domatesleri rendeleyin.", "Tavada kalan yağla soğanı 4 dakika soteleyip domatesi ekleyin ve 5 dakika pişirin.", "Nohudu, patlıcanları ve sosu fırın kabında harmanlayın.", "20 dakika daha pişirin.", "Sıcak servis edin."], minutes: 65),
  GeneralRecipe(id: "p39a10_016", title: "Limonlu ıspanak salatası", category: "Salatalar", ingredients: ["150 g bebek ıspanak", "1 salatalık", "1 avuç ceviz", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Yeşillikleri bol suda yıkayıp süzgeçte iyice süzdürün; kâğıt havluyla kurulayın.", "Salatalığı ince yarım ay doğrayın.", "Cevizi kuru tavada 2 dakika hafifçe kavurup iri kırın.", "Zeytinyağı ve limon suyunu küçük bir kâsede çırpıp sos hazırlayın; tuzunu ayarlayın.", "Ispanak ve salatalığı tabağa yayıp cevizi serpin.", "Sosu servis etmeden hemen önce dökün ve nazikçe harmanlayın; erken eklerseniz sebzeler su salar."], minutes: 15),
  GeneralRecipe(id: "p39a10_017", title: "Peynirli mısır unlu muffin", category: "Kek ve kurabiyeler", ingredients: ["1 su bardağı mısır unu", "Yarım su bardağı yoğurt", "2 yumurta", "80 g beyaz peynir", "1 paket kabartma tozu", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 180°C ısıtın.", "Yumurta, yoğurt ve yağı çırpın.", "Mısır unu, kabartma tozu ve ufalanmış peyniri ekleyin.", "Muffin kalıplarında içleri tamamen pişene kadar 20-25 dakika fırınlayın."], minutes: 35),
  GeneralRecipe(id: "p39a10_018", title: "Fırında armutlu crumble", category: "Dünya mutfağı", ingredients: ["3 armut", "Yarım su bardağı yulaf", "2 yemek kaşığı un", "2 yemek kaşığı tereyağı", "1 çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın.", "Armutları dilimleyip küçük fırın kabına yerleştirin.", "Yulaf, un, tereyağı ve tarçını ufalanan bir karışım yapın.", "Armutların üzerine serpip 25 dakika pişirin."], minutes: 35),
  GeneralRecipe(id: "p39a10_019", title: "Sarımsaklı fırın brokoli", category: "Sebze yemekleri", ingredients: ["1 küçük brokoli", "2 yemek kaşığı zeytinyağı", "2 diş sarımsak", "1 yemek kaşığı limon suyu"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Brokoliyi küçük çiçeklere ayırın, kalın sapını soyup ince dilimleyin; yıkayıp iyice kurulayın.", "Sarımsağı ezip yağ ve az tuzla karıştırın; brokoliyi bu sosla harmanlayın.", "Tepsiye tek kat yayın.", "18–20 dakika, kenarları hafif kızarana kadar pişirin.", "Limon suyunu gezdirip ılık servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a10_020", title: "Tavuklu sebzeli kuskus", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "200 g tavuk göğsü", "1 havuç", "1 küçük kabak", "2 yemek kaşığı zeytinyağı"], steps: ["Kuskusu paket talimatına göre haşlayıp süzün.", "Tavuğu küçük doğrayıp tavada tamamen pişirin.", "Havuç ve kabağı ekleyip yumuşayana kadar soteleyin.", "Kuskusu ekleyip karıştırarak sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a11_001", title: "Zerdeçallı mercimek çorbası", category: "Çorbalar", ingredients: ["1 su bardağı kırmızı mercimek", "1 havuç", "1 küçük soğan", "1 çay kaşığı zerdeçal", "1 yemek kaşığı zeytinyağı", "5 su bardağı su"], steps: ["Mercimeği suyu berraklaşana kadar birkaç kez yıkayıp süzün.", "Soğanı ince, havucu küçük küp doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Havucu ve zerdeçalı ekleyip 1 dakika çevirin.", "Mercimeği ve suyu ekleyip kaynatın; köpüğünü alın.", "Kapağı aralık bırakıp kısık ateşte, ara ara karıştırarak mercimek dağılana kadar 25 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 40),
  GeneralRecipe(id: "p39a11_002", title: "Fırında yoğurtlu karnabahar", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "1 su bardağı yoğurt", "1 yumurta", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tatlı toz biber"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Karnabaharı çiçeklere ayırın.", "Kaynar suda 5 dakika ön haşlayıp süzün.", "Yoğurt, yumurta, yağ, toz biber ve az tuzu çırpın.", "Karnabaharı sosla karıştırıp fırın kabına yayın.", "25 dakika, yumurta tamamen pişip üzeri kızarana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 45),
  GeneralRecipe(id: "p39a11_003", title: "Tavuklu nohut yemeği", category: "Tavuk yemekleri", ingredients: ["300 g kuşbaşı tavuk", "1,5 su bardağı haşlanmış nohut", "1 soğan", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu kuşbaşı doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Soğanı ince doğrayın, domatesleri rendeleyin.", "Tencerede yağı ısıtıp soğanı 3–4 dakika kavurun.", "Tavuğu ekleyip dışı beyazlayana kadar 5 dakika çevirin.", "Salçayı ekleyip 1 dakika kavurun; domatesi ilave edip 3 dakika pişirin.", "Nohudu ve 1 su bardağı sıcak suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı kapalı 20 dakika pişirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 42),
  GeneralRecipe(id: "p39a11_004", title: "Köz patlıcanlı bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "2 patlıcan", "1 soğan", "1 domates", "2 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı"], steps: ["Bulguru bir kez yıkayıp süzün.", "Patlıcanları közleyip kabuklarını soyun ve iri doğrayın.", "Soğanı ince doğrayın, domatesi rendeleyin.", "Tencerede yağı ısıtıp soğanı 3–4 dakika pembeleştirin.", "Domatesi ekleyip 3 dakika pişirin.", "Bulguru ekleyip yağa bulanması için 1–2 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Patlıcanı ekleyip karıştırın.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 45),
  GeneralRecipe(id: "p39a11_005", title: "Fırında hardallı somon", category: "Balık ve deniz ürünleri", ingredients: ["2 dilim somon fileto", "1 tatlı kaşığı hardal", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "1 diş sarımsak"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Balığı soğuk suyla durulayıp kâğıt havluyla iyice kurulayın.", "Filetoların üzerinde parmaklarınızı gezdirip kalan kılçıkları cımbızla çekin; çocuklar için özellikle önemlidir.", "Hardal, yağ, limon suyu ve ezilmiş sarımsağı karıştırın.", "Sosu somonların üzerine sürüp fırın kabına yerleştirin.", "15–20 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 30),
  GeneralRecipe(id: "p39a11_006", title: "Beşamel soslu ıspanaklı patates", category: "Sebze yemekleri", ingredients: ["3 patates", "250 g ıspanak", "1 soğan", "1 su bardağı süt", "1 yemek kaşığı un", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Patatesleri soyup ince dilimleyin; kaynar tuzlu suda 8 dakika haşlayıp süzün.", "Ispanağı bol suda 2–3 kez yıkayıp toprağını iyice giderin; süzüp iri doğrayın.", "Soğanı ince doğrayıp yağda 3 dakika yumuşatın; ıspanağı ekleyip suyunu çekene kadar soteleyin.", "Küçük tencerede soğuk süt ve unu çırpın; orta ateşte sürekli karıştırarak 4–5 dakika koyulaştırın.", "Patates ve ıspanağı fırın kabına dizip sosu dökün.", "25 dakika, üzeri kızarana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 56),
  GeneralRecipe(id: "p39a11_007", title: "Kuru domatesli makarna", category: "Makarnalar", ingredients: ["250 g makarna", "8 adet kuru domates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 avuç fesleğen"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Kuru domatesleri sıcak suda 10 dakika bekletip yumuşatın; süzüp ince doğrayın.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Geniş tavada zeytinyağını orta ateşte ısıtıp ezilmiş sarımsağı 30 saniye, yakmadan çevirin.", "Kuru domatesleri ekleyip 2 dakika çevirin.", "Makarnayı ve 3–4 kaşık haşlama suyunu ekleyip harmanlayın; kuru domates tuzlu olduğundan tuzu azaltın.", "Fesleğeni ekleyip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a11_008", title: "Cevizli yoğurtlu semizotu salatası", category: "Salatalar", ingredients: ["1 bağ semizotu", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı ceviz"], steps: ["Semizotunun kalın saplarını ayıklayın; yapraklarını bol suda birkaç kez yıkayıp süzün ve iri doğrayın.", "Cevizi kuru tavada 2 dakika hafifçe kavurup iri kırın.", "Sarımsağı ezip yoğurtla pürüzsüz olana kadar çırpın; tuzunu ayarlayın.", "Semizotu ve cevizin çoğunu yoğurtla harmanlayın.", "Servis kâsesine alıp kalan ceviz ve zeytinyağıyla süsleyin.", "Soğuk servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a11_009", title: "Soğanlı mantarlı arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1 su bardağı arpa şehriye", "200 g mantar", "1 küçük soğan", "2 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı"], steps: ["Soğanı ince doğrayın.", "Tencerede yağı ısıtıp arpa şehriyeyi sürekli karıştırarak açık kahverengi olana kadar 3–4 dakika kavurun.", "Soğanı ekleyip 2 dakika çevirin.", "Mantarları dilimleyip ekleyin; suyunu salıp çekene kadar 5–6 dakika soteleyin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca kısık ateşte kapağı kapalı 12–15 dakika pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 47),
  GeneralRecipe(id: "p39a11_010", title: "Portakallı zeytinyağlı pırasa", category: "Sebze yemekleri", ingredients: ["4 pırasa", "1 havuç", "1 portakalın suyu", "2 yemek kaşığı pirinç", "3 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Pırasaların kök ve sert yeşil uçlarını kesin; boyuna yarıp katların arasındaki toprağı bol suyla yıkayın.", "Pırasaları ve havucu verev doğrayın.", "Pirinci suyu berraklaşana kadar yıkayıp süzün.", "Tencerede zeytinyağını ısıtıp sebzeleri 4 dakika çevirin.", "Pirinç, portakal suyu, su ve az tuzu ekleyin.", "Kapağı kapalı kısık ateşte sebzeler yumuşayana kadar 25 dakika pişirin.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 40),
  GeneralRecipe(id: "p39a11_011", title: "Kıymalı karnabahar yemeği", category: "Et yemekleri", ingredients: ["250 g az yağlı kıyma", "1 küçük karnabahar", "1 soğan", "2 domates", "1 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Soğanı ince doğrayın, domatesleri küp kesin; karnabaharı küçük çiçeklere ayırıp yıkayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Domatesleri ekleyip 3 dakika pişirin.", "Karnabaharı ve suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı kapalı 25 dakika, karnabahar yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 50),
  GeneralRecipe(id: "p39a11_012", title: "Fırında peynirli kabak dilimleri", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 kabak", "60 g rendelenmiş kaşar", "1 yumurta", "3 yemek kaşığı galeta unu", "1 tatlı kaşığı zeytinyağı"], steps: ["Fırını 200°C ısıtın ve kabakları kalın halkalar halinde dilimleyin.", "Yumurtayı çırpıp kaşar ve galeta ununu ayrı kapta karıştırın.", "Kabakları önce yumurtaya sonra peynirli karışıma bulayın.", "Yağlı kâğıt serili tepside 20-25 dakika kızartın."], minutes: 35),
  GeneralRecipe(id: "p39a11_013", title: "Tarçınlı kabak tatlısı", category: "Tatlılar", ingredients: ["600 g bal kabağı", "3 yemek kaşığı toz şeker", "Yarım su bardağı su", "1 çay kaşığı tarçın", "2 yemek kaşığı ceviz"], steps: ["Kabağı soyup çekirdeklerini ayıklayın; iri küpler halinde doğrayın.", "Tencereye kabak, şeker ve suyu alın.", "Kapağı kapalı kısık ateşte 25 dakika, kabak yumuşayana kadar pişirin.", "Bıçak ucuyla kontrol edin: kolayca batıyorsa meyve yumuşamıştır.", "Tencerede soğumaya bırakın; sıcakken taşırsanız dağılır.", "Tarçın ve cevizle servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a11_014", title: "Sebzeli fırın mücver topları", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 kabak", "1 havuç", "2 yumurta", "4 yemek kaşığı un", "Yarım demet dereotu", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C ısıtın.", "Kabak ve havucu rendeleyip fazla suyunu iyice sıkın.", "Yumurta, un, dereotu ve yağı karıştırın.", "Kaşıkla küçük porsiyonlar koyup 25 dakika, içleri pişene kadar fırınlayın."], minutes: 35),
  GeneralRecipe(id: "p39a11_015", title: "Limonlu tavuklu pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "200 g tavuk göğsü", "1,5 su bardağı sıcak tavuk suyu", "1 yemek kaşığı tereyağı", "1 yemek kaşığı limon suyu"], steps: ["Pirinci ılık tuzlu suda 20 dakika bekletin; suyu berraklaşana kadar yıkayıp süzün.", "Tencerede tereyağını eritip küp doğranmış tavuğu, rengi tamamen beyazlayana kadar 6–7 dakika soteleyin.", "Pirinci ekleyip taneler şeffaflaşana kadar 2–3 dakika kavurun.", "Sıcak tavuk suyunu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 12–15 dakika pişirin.", "Limon suyunu ekleyin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 65),
  GeneralRecipe(id: "p39a11_016", title: "Brokolili peynirli krep", category: "Kahvaltılıklar", ingredients: ["1 yumurta", "Yarım su bardağı süt", "Yarım su bardağı un", "1 su bardağı küçük brokoli çiçeği", "50 g beyaz peynir"], steps: ["Brokoliyi buharda 5 dakika yumuşatıp küçük doğrayın.", "Peyniri ufalayın.", "Yumurta, süt ve unu topak kalmayana kadar çırpın; hamuru 10 dakika dinlendirin.", "Brokoli ve peyniri hamura ekleyin.", "Yapışmaz tavayı az yağla yağlayıp orta ateşte ısıtın; bir kepçe hamur döküp tavayı çevirerek ince yayın.", "Kenarları kalkınca çevirin; her yüzü 1–2 dakika pişirin.", "Sıcak servis edin."], minutes: 27),
  GeneralRecipe(id: "p39a11_017", title: "Fırında limonlu levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş levrek fileto", "1 limon", "1 küçük kırmızı soğan", "2 yemek kaşığı zeytinyağı", "3 dal maydanoz"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Soğan ve limonu ince dilimleyip fırın kabına yerleştirin.", "Balığı soğuk suyla durulayıp kâğıt havluyla iyice kurulayın.", "Filetoların üzerinde parmaklarınızı gezdirip kalan kılçıkları cımbızla çekin; çocuklar için özellikle önemlidir.", "Levrekleri soğanların üzerine koyup yağ gezdirin; az tuz serpin.", "18–22 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Kıyılmış maydanozla servis edin.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 32),
  GeneralRecipe(id: "p39a11_018", title: "Elmalı yoğurtlu kup", category: "Tatlılar", ingredients: ["1 elma", "1 su bardağı yoğurt", "3 yemek kaşığı yulaf", "1 çay kaşığı tarçın", "1 tatlı kaşığı bal"], steps: ["Elmayı yıkayıp küçük doğrayın.", "Tavada 2 kaşık suyla 3–4 dakika yumuşatın; tarçının yarısını ekleyip soğutun.", "Yoğurdu balla karıştırın.", "Bal 1 yaşından küçük bebeklere verilmez; bebek porsiyonunu balsız ayırın.", "Bardağa yoğurt, yulaf ve elmayı kat kat yerleştirin.", "Kalan tarçını serpip bekletmeden servis edin; yulaf yumuşamaz."], minutes: 15),
  GeneralRecipe(id: "p39a11_019", title: "Domatesli yeşil mercimek güveci", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı yeşil mercimek", "2 domates", "1 soğan", "1 havuç", "2 yemek kaşığı zeytinyağı", "2 su bardağı su"], steps: ["Mercimeği ayıklayıp suyu berraklaşana kadar birkaç kez yıkayın.", "Mercimeği kaynar suda 15 dakika ön haşlayıp süzün.", "Soğanı ince, havucu küp doğrayın; domatesleri rendeleyin.", "Tencerede yağı ısıtıp soğan ve havucu 5 dakika yumuşatın.", "Domatesi ekleyip 3 dakika pişirin.", "Mercimeği ve suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı aralık 20–25 dakika, mercimek yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 58),
  GeneralRecipe(id: "p39a11_020", title: "Yoğurtlu dereotlu peynir poğaçası", category: "Hamur işleri", ingredients: ["2 su bardağı un", "1 su bardağı yoğurt", "1 yumurta", "Yarım çay bardağı zeytinyağı", "1 paket kabartma tozu", "100 g beyaz peynir", "Yarım demet dereotu"], steps: ["Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Yumurtayı kırıp sarısını üzerine sürmek için ayırın.", "Yoğurt, yumurta beyazı ve yağı karıştırın; un ve kabartma tozunu azar azar ekleyin.", "Ufalanmış peynir ve ince kıyılmış dereotunu katıp ele yapışmayan yumuşak bir hamur yapın; fazla yoğurmayın.", "Ceviz büyüklüğünde parçalar alıp yuvarlayın ve tepsiye aralıklı dizin.", "Üzerlerine yumurta sarısı sürün.", "25–30 dakika, içleri pişip üzerleri kızarana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a12_001", title: "Fırında yoğurt soslu patates", category: "Sebze yemekleri", ingredients: ["3 patates", "3 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Patatesleri yıkayıp elma dilim doğrayın ve kurulayın.", "Yoğurt, yağ, kekik ve az tuzu çırpıp patateslere iyice yedirin.", "Patatesleri tepsiye tek kat dizin.", "25–30 dakika pişirin.", "Pişirmenin yarısında sebzeleri spatulayla çevirin ki her yüzü eşit kızarsın.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir."], minutes: 40),
  GeneralRecipe(id: "p39a12_002", title: "Tahinli limonlu nohut salatası", category: "Salatalar", ingredients: ["2 su bardağı haşlanmış nohut", "1 salatalık", "1 kapya biber", "2 yemek kaşığı tahin", "2 yemek kaşığı limon suyu"], steps: ["Nohutları süzüp durulayın.", "Salatalık ve kapya biberi küçük küp doğrayın.", "Tahin ve limon suyunu çırpın; koyu gelirse 2–3 yemek kaşığı su ekleyin ve tuzunu ayarlayın.", "Nohut ve sebzeleri sosla harmanlayın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a12_003", title: "Kıymalı yeşil mercimek yemeği", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı yeşil mercimek", "200 g kıyma", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "3 su bardağı su"], steps: ["Mercimeği ayıklayıp suyu berraklaşana kadar birkaç kez yıkayın.", "Mercimeği kaynar suda 15 dakika ön haşlayıp süzün.", "Soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Salçayı ekleyip kokusu çıkana kadar 1 dakika kavurun.", "Mercimeği ve suyu ekleyin; kaynayınca ateşi kısın.", "Kapağı aralık 20–25 dakika, mercimek yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 63),
  GeneralRecipe(id: "p39a12_004", title: "Köz biberli lorlu omlet", category: "Kahvaltılıklar", ingredients: ["2 yumurta", "1 közlenmiş kapya biber", "3 yemek kaşığı lor", "1 tatlı kaşığı zeytinyağı"], steps: ["Közlenmiş biberi kabuğundan ayırıp şerit doğrayın.", "Yumurtaları çırpıp loru ekleyin.", "Tavada yağı ısıtıp biberi 1 dakika çevirin.", "Yumurtalı karışımı dökün.", "Kenarları pişmeye başlayınca spatulayla ortaya doğru itip çiğ kısmın alta akmasını sağlayın.", "Üstü tamamen pişince ikiye katlayıp tabağa alın."], minutes: 15),
  GeneralRecipe(id: "p39a12_005", title: "Fırında kekikli barbunya güveci", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış barbunya", "3 domates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 çay bardağı sıcak su"], steps: ["Fırını 190°C’ye ısıtın.", "Soğanı ince doğrayın, domatesleri küp kesin.", "Tavada yağı ısıtıp soğanı 4 dakika soteleyin; domatesleri ekleyip 5 dakika pişirin.", "Haşlanmış bakliyatı süzgeçte durulayıp suyunu iyice süzdürün.", "Barbunya, sos, sıcak su, kekik ve az tuzu fırın kabında karıştırın.", "25 dakika, sos koyulaşana kadar pişirin.", "Sıcak servis edin."], minutes: 45),
  GeneralRecipe(id: "p39a12_006", title: "Limonlu taze naneli pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "1,5 su bardağı sıcak su", "1 yemek kaşığı tereyağı", "Yarım demet dereotu", "1 yemek kaşığı limon suyu"], steps: ["Pirinci ılık tuzlu suda 20 dakika bekletin; suyu berraklaşana kadar yıkayıp süzün.", "Tencerede tereyağını eritin.", "Pirinci ekleyip taneler şeffaflaşana kadar 2–3 dakika kavurun.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi en kısığa alın ve kapağı kapalı 12–15 dakika, suyunu çekene kadar pişirin.", "Dereotunu ince kıyın.", "Demlenen pilava dereotu ve limon suyunu ekleyip çatalla karıştırın."], minutes: 48),
  GeneralRecipe(id: "p39a12_007", title: "Fırında kabaklı tavuk köftesi", category: "Tavuk yemekleri", ingredients: ["300 g tavuk kıyması", "1 küçük kabak", "1 yumurta", "3 yemek kaşığı galeta unu", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Tepsiye yağlı kâğıt serin.", "Kabağı ince rendeleyip suyunu iyice sıkın.", "Tavuk kıyması, kabak, yumurta, galeta unu ve az tuzu yoğurun.", "Islak elle ceviz büyüklüğünde köfteler şekillendirip tepsiye aralıklı dizin.", "Üzerlerine fırçayla zeytinyağı sürün.", "25–30 dakika pişirin.", "Pişirmenin yarısında köfteleri çevirin ki iki yüzü de kızarsın.", "Bir köfteyi ortadan bölüp kontrol edin: içi pembe kalmamalı; termometre varsa en az 74°C olmalı."], minutes: 40),
  GeneralRecipe(id: "p39a12_008", title: "Ispanaklı nohut sote", category: "Sebze yemekleri", ingredients: ["300 g ıspanak", "1,5 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı zeytinyağı", "1 domates"], steps: ["Ispanağı bol suda 2–3 kez yıkayıp toprağını iyice giderin; süzüp iri doğrayın.", "Soğanı ince doğrayın, domatesi küp kesin.", "Tavada yağı ısıtıp soğanı 3–4 dakika soteleyin.", "Domatesi ekleyip 4 dakika pişirin.", "Nohut ve ıspanağı ekleyin; ıspanak tamamen sönüp yumuşayana kadar 10–12 dakika pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a12_009", title: "Portakallı havuç çorbası", category: "Çorbalar", ingredients: ["4 havuç", "1 küçük patates", "1 soğan", "3 su bardağı su", "Yarım su bardağı portakal suyu", "1 yemek kaşığı zeytinyağı"], steps: ["Havuçları ve patatesi soyup küp doğrayın; soğanı doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Havuç ve patatesi ekleyip 3 dakika çevirin.", "Suyu ekleyip kaynatın.", "Kapağı aralık bırakıp kısık ateşte, sebzeler çatalla kolayca ezilene kadar 20 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Portakal suyunu ekleyip kaynatmadan ısıtın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 37),
  GeneralRecipe(id: "p39a12_010", title: "Yoğurtlu fırın patlıcan", category: "Mezeler", ingredients: ["2 patlıcan", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 210°C ısıtın.", "Patlıcanları birkaç yerinden delip 25-30 dakika yumuşayana kadar közleyin.", "Soğuyunca kabuklarını soyup içini doğrayın.", "Sarımsaklı yoğurtla karıştırıp üzerine yağ gezdirin."], minutes: 40),
  GeneralRecipe(id: "p39a12_011", title: "Tavuklu bezelyeli bulgur", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "200 g tavuk göğsü", "1 su bardağı bezelye", "1 küçük soğan", "2 su bardağı sıcak su", "1 yemek kaşığı zeytinyağı"], steps: ["Bulguru bir kez yıkayıp süzün.", "Soğanı ince doğrayın.", "Tavuğu küçük küp doğrayıp yağda, rengi tamamen beyazlayana kadar 6–7 dakika soteleyin.", "Soğanı ekleyip 3 dakika çevirin.", "Bezelye ve bulguru ekleyip 1 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 46),
  GeneralRecipe(id: "p39a12_012", title: "Fırında tahinli karnabahar", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "2 yemek kaşığı tahin", "1 yemek kaşığı limon suyu", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı su"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Karnabaharı çiçeklerine ayırıp yıkayın ve kurulayın.", "Tahin, limon suyu, yağ, su ve az tuzu pürüzsüz olana kadar çırpın.", "Karnabaharı sosun yarısıyla harmanlayıp tepsiye tek kat yayın.", "25–30 dakika pişirin.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Kalan sosu üzerine gezdirerek servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a12_013", title: "Peynirli ıspanaklı mini börek", category: "Hamur işleri", ingredients: ["3 yufka", "250 g ıspanak", "100 g beyaz peynir", "1 yumurta", "2 yemek kaşığı yoğurt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Ispanağı yıkayıp ince kıyın; tavada 3 dakika suyunu çektirip soğutun.", "Ispanağı ufalanmış peynirle karıştırın.", "Yumurta, yoğurt ve yağı çırpın.", "Yufkaları üçgen ya da şerit parçalara ayırıp sos sürün; harç koyup küçük rulolar yapın.", "Rulo böreği yağlanmış tepsiye, ek yeri alta gelecek şekilde dizin.", "Kalan sosu üstüne sürüp 25 dakika, kızarana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı."], minutes: 40),
  GeneralRecipe(id: "p39a12_014", title: "Narlı yoğurtlu havuç mezesi", category: "Mezeler", ingredients: ["3 havuç", "1 su bardağı yoğurt", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı nar tanesi", "1 diş sarımsak"], steps: ["Havuçları rendeleyip yağda 5-6 dakika yumuşatın.", "Havuçları tamamen soğutun.", "Yoğurdu sarımsakla karıştırıp havuçları ekleyin.", "Nar taneleriyle süsleyerek servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a12_015", title: "Fırında elmalı irmik kup", category: "Tatlılar", ingredients: ["2 elma", "4 yemek kaşığı irmik", "2 su bardağı süt", "2 yemek kaşığı şeker", "1 çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın.", "Süt, irmik ve şekeri tencerede soğukken çırparak karıştırın; topaklanmaz.", "Orta ateşte, dibi tutmasın diye sürekli karıştırarak 8–10 dakika, kaşıktan yavaş akacak kıvama gelene kadar pişirin.", "Elmaları soyup rendeleyin; kararmaması için hemen tarçınla karıştırın.", "Küçük fırın kaplarına irmik ve elmayı kat kat koyun; en üstte elma olsun.", "15 dakika fırınlayın.", "Fırından alıp 10 dakika ılıtın; içi çok sıcak olur."], minutes: 45),
  GeneralRecipe(id: "p39a12_016", title: "Limonlu sarımsaklı fırın alabalık", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş alabalık", "1 limon", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "3 dal maydanoz"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Alabalıkların içini kontrol edip soğuk suyla durulayın ve kâğıt havluyla kurulayın.", "Limon suyu, ezilmiş sarımsak, yağ ve az tuzu karıştırın.", "Karışımı balıkların içine ve dışına sürün; kaba yerleştirin.", "20–25 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Kıyılmış maydanozla servis edin; çocuk porsiyonunu kılçıksız hazırlayın.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 35),
  GeneralRecipe(id: "p39a12_017", title: "Mantarlı yeşil mercimek makarnası", category: "Makarnalar", ingredients: ["200 g makarna", "1 su bardağı haşlanmış yeşil mercimek", "200 g mantar", "1 soğan", "2 yemek kaşığı zeytinyağı"], steps: ["Büyük bir tencerede bol suyu kaynatıp tuzlayın; makarnayı ekleyip ilk 1 dakika yapışmasın diye karıştırın.", "Mantarları nemli bezle silip dilimleyin; suya yatırmayın.", "Soğanı ince doğrayın.", "Paketteki süreden 1 dakika önce tadına bakın; hafif diri olunca bir kepçe haşlama suyunu ayırıp süzün.", "Tavada yağı ısıtıp soğanı 3 dakika soteleyin.", "Mantarları ekleyip yüksek ateşte suyunu salıp çekene kadar 6–8 dakika soteleyin.", "Haşlanmış mercimeği ekleyip 3 dakika ısıtın; tuzunu ayarlayın.", "Makarnayı sosa ekleyin; kıvam koyuysa ayırdığınız sudan katarak 1 dakika harmanlayın.", "Sıcak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a12_018", title: "Domatesli peynirli fırın kabak", category: "Sebze yemekleri", ingredients: ["3 kabak", "2 domates", "100 g beyaz peynir", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabak ve domatesleri 0,5 cm halka dilimleyin.", "Fırın kabına kabak ve domatesi sırayla, dik ve sık dizin.", "Üzerine yağ ve kekik gezdirin.", "20 dakika pişirin.", "Ufalanmış peyniri serpip 8–10 dakika daha, kabaklar yumuşayana kadar pişirin.", "Sıcak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a12_019", title: "Zencefilli balkabağı çorbası", category: "Çorbalar", ingredients: ["400 g balkabağı", "1 havuç", "1 soğan", "3 su bardağı su", "1 çay kaşığı rendelenmiş taze zencefil", "1 yemek kaşığı zeytinyağı"], steps: ["Balkabağı ve havucu soyup küp doğrayın; soğanı doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Zencefili ekleyip 30 saniye çevirin.", "Balkabağı, havuç ve suyu ekleyip kaynatın.", "Kapağı aralık bırakıp kısık ateşte, sebzeler çatalla kolayca ezilene kadar 20 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Kıvamı koyu gelirse sıcak su ekleyip 2 dakika daha kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 36),
  GeneralRecipe(id: "p39a12_020", title: "Cevizli muzlu yulaf kurabiyesi", category: "Kek ve kurabiyeler", ingredients: ["2 olgun muz", "1,5 su bardağı yulaf ezmesi", "3 yemek kaşığı ceviz", "1 çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın.", "Muzları ezip yulaf, ceviz ve tarçınla karıştırın.", "Karışımdan kaşıkla porsiyonlar alıp tepsiye dizin.", "18-20 dakika kurabiyeler toparlanana kadar pişirip soğutun."], minutes: 30),
  GeneralRecipe(id: "p39a13_001", title: "Fırında havuçlu kabaklı hindi köfte", category: "Tavuk yemekleri", ingredients: ["350 g hindi kıyması", "1 küçük kabak", "1 havuç", "1 yumurta", "3 yemek kaşığı galeta unu"], steps: ["Fırını 190°C’ye ısıtın. Tepsiye yağlı kâğıt serin.", "Sebzeleri ince rendeleyip avucunuzla suyunu iyice sıkın; köfte dağılmaz.", "Hindi kıyması, sebzeler, yumurta, galeta unu ve az tuzu yoğurun.", "Islak elle ceviz büyüklüğünde köfteler şekillendirip tepsiye aralıklı dizin.", "Yaklaşık 25 dakika pişirin.", "Pişirmenin yarısında köfteleri çevirin ki iki yüzü de kızarsın.", "Bir köfteyi ortadan bölüp kontrol edin: içi pembe kalmamalı; termometre varsa en az 74°C olmalı."], minutes: 40),
  GeneralRecipe(id: "p39a13_002", title: "Közlenmiş domatesli bulgur çorbası", category: "Çorbalar", ingredients: ["3 domates", "Yarım çay bardağı ince bulgur", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Domatesleri fırında ya da tavada kabukları kararana kadar 10–12 dakika közleyin; soyup doğrayın.", "Soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Domatesleri ekleyip 3 dakika pişirin.", "Suyu ekleyip kaynatın.", "Bulguru ekleyip kısık ateşte, bulgur yumuşayana kadar 15 dakika pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 44),
  GeneralRecipe(id: "p39a13_003", title: "Fırında sarımsaklı brokoli patates", category: "Sebze yemekleri", ingredients: ["1 küçük brokoli", "2 patates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Patatesleri ince dilimleyin, brokoliyi çiçeklerine ayırın.", "Sarımsağı ezip yağ, kekik ve az tuzla karıştırın.", "Patatesleri sosun yarısıyla harmanlayıp tepsiye yayın ve 15 dakika pişirin.", "Brokoliyi kalan sosla harmanlayıp tepsiye ekleyin.", "15 dakika daha, patatesler yumuşayana kadar fırınlayın.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir."], minutes: 40),
  GeneralRecipe(id: "p39a13_004", title: "Tavuklu kabaklı pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "200 g tavuk göğsü", "1 küçük kabak", "1,5 su bardağı sıcak su", "1 yemek kaşığı tereyağı"], steps: ["Pirinci ılık tuzlu suda 20 dakika bekletin; suyu berraklaşana kadar yıkayıp süzün.", "Kabağı küçük küp doğrayın.", "Tencerede tereyağını eritip küp doğranmış tavuğu, rengi tamamen beyazlayana kadar 6–7 dakika soteleyin.", "Kabağı ekleyip 2 dakika çevirin.", "Pirinci ekleyip taneler şeffaflaşana kadar 2–3 dakika kavurun.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi en kısığa alın ve kapağı kapalı 12–15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 67),
  GeneralRecipe(id: "p39a13_005", title: "Yoğurtlu kırmızı lahana mezesi", category: "Mezeler", ingredients: ["Yarım küçük kırmızı lahana", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Lahanayı ince doğrayıp limonla ovun.", "Zeytinyağında 5 dakika yumuşatıp soğutun.", "Yoğurdu ezilmiş sarımsakla karıştırın.", "Soğuyan lahanayı yoğurtla birleştirip servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a13_006", title: "Domatesli nohutlu pazı yemeği", category: "Sebze yemekleri", ingredients: ["1 demet pazı", "1,5 su bardağı haşlanmış nohut", "1 soğan", "1 domates", "2 yemek kaşığı zeytinyağı"], steps: ["Pazıyı yaprak yaprak bol suda yıkayın; sapları ince, yaprakları iri doğrayın.", "Soğanı ince doğrayın, domatesi rendeleyin.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Domatesi ekleyip 3 dakika pişirin.", "Pazı sapları, yaprakları ve nohudu tencereye alın.", "Yarım çay bardağı su ekleyip kapağı kapalı 15 dakika, pazı yumuşayana kadar pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a13_007", title: "Fırında limonlu tavuk kanat", category: "Tavuk yemekleri", ingredients: ["600 g tavuk kanat", "1 limonun suyu", "2 yemek kaşığı zeytinyağı", "2 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Fırını 200°C’ye ısıtın. Tepsiye yağlı kâğıt serin.", "Kanatları kâğıt havluyla iyice kurulayın; kuru deri daha çıtır olur.", "Limon suyu, yağ, ezilmiş sarımsak, kekik ve az tuzu karıştırın.", "Tavuğu sosa iyice bulayın; kapalı kapta buzdolabında en az 20 dakika bekletin.", "Kanatları tepsiye tek kat dizin.", "40–45 dakika pişirin; 15 dakikada bir çevirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 75),
  GeneralRecipe(id: "p39a13_008", title: "Fırında mantarlı peynirli polenta", category: "Dünya mutfağı", ingredients: ["1 su bardağı mısır irmiği", "4 su bardağı su", "250 g mantar", "100 g kaşar peyniri", "1 yemek kaşığı tereyağı"], steps: ["Mısır irmiğini kaynar suya yavaşça döküp sürekli karıştırarak koyulaştırın.", "Mantarları dilimleyip tereyağında suyunu çekene kadar soteleyin.", "Polentayı fırın kabına yayın, mantarları ve rendelenmiş peyniri ekleyin.", "190°C fırında peynir eriyip kızarana kadar 15 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a13_009", title: "Portakallı pancar salatası", category: "Salatalar", ingredients: ["2 haşlanmış pancar", "1 portakal", "1 avuç roka", "2 yemek kaşığı ceviz", "1 yemek kaşığı zeytinyağı"], steps: ["Haşlanmış pancarları küçük küp doğrayın.", "Portakalın kabuğunu soyup dilimlerini zarlarından ayırın.", "Yeşillikleri bol suda yıkayıp süzgeçte iyice süzdürün; kâğıt havluyla kurulayın.", "Cevizi kuru tavada 2 dakika hafifçe kavurup iri kırın.", "Rokayı tabağa yayıp pancar ve portakalı yerleştirin.", "Zeytinyağı ve tuzu gezdirip cevizi serpin."], minutes: 20),
  GeneralRecipe(id: "p39a13_010", title: "Ispanaklı lorlu fırın makarna", category: "Makarnalar", ingredients: ["250 g makarna", "200 g ıspanak", "150 g lor peyniri", "1 su bardağı süt", "1 yumurta"], steps: ["Fırını 190°C ısıtın.", "Makarnayı paket süresinden 2 dakika kısa haşlayın.", "Ispanağı yıkayıp doğrayın ve tavada suyunu çektirin.", "Makarna, ıspanak ve loru karıştırıp fırın kabına alın.", "Süt ve yumurtayı çırpıp üzerine dökün; 20 dakika fırınlayın."], minutes: 45),
  GeneralRecipe(id: "p39a13_011", title: "Kabaklı mercimek mücveri", category: "Sebze yemekleri", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "2 kabak", "1 yumurta", "3 yemek kaşığı un", "Yarım demet dereotu"], steps: ["Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Kabakları rendeleyip bir tutam tuzla 5 dakika bekletin; sonra avucunuzla suyunu iyice sıkın.", "Mercimeği süzüp çatalla hafifçe ezin; dereotunu kıyın.", "Kabak, mercimek, yumurta, un ve dereotunu karıştırın.", "Kaşıkla küçük parçalar halinde tepsiye koyup hafifçe bastırın.", "20 dakika pişirin; çevirip 5 dakika daha fırınlayın.", "Ortasına kürdan batırın: kuru çıkıyorsa ve yumurta tamamen pişmişse hazırdır."], minutes: 35),
  GeneralRecipe(id: "p39a13_012", title: "Fırında elmalı tarçınlı kek", category: "Kek ve kurabiyeler", ingredients: ["2 elma", "2 yumurta", "1 su bardağı süt", "1,5 su bardağı un", "Yarım su bardağı şeker", "1 paket kabartma tozu", "1 çay kaşığı tarçın"], steps: ["Fırını 175°C ısıtın.", "Yumurta ve şekeri çırpıp sütü ekleyin.", "Un, kabartma tozu ve tarçını karışıma katın.", "Küp doğranmış elmaları ekleyip kalıba dökün.", "Kürdan temiz çıkana kadar yaklaşık 35-40 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a13_013", title: "Naneli yoğurtlu buğday salatası", category: "Salatalar", ingredients: ["1,5 su bardağı haşlanmış aşurelik buğday", "1 su bardağı yoğurt", "1 salatalık", "Yarım demet taze nane", "1 yemek kaşığı zeytinyağı"], steps: ["Buğdayı süzüp soğumaya bırakın.", "Salatalığı küçük küp doğrayın, naneyi ince kıyın.", "Yoğurdu tuzla çırpın.", "Buğday, salatalık ve naneyi yoğurtla harmanlayın.", "Servis tabağına alıp üzerine zeytinyağı gezdirin.", "Soğuk servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a13_014", title: "Domatesli fırın barbunya köftesi", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış barbunya", "1 küçük soğan", "1 yumurta", "4 yemek kaşığı galeta unu", "2 domates"], steps: ["Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Haşlanmış bakliyatı süzgeçte durulayıp suyunu iyice süzdürün.", "Barbunyayı çatalla ezin.", "Soğanı rendeleyip suyunu sıkın.", "Barbunya, soğan, yumurta, galeta unu ve az tuzu yoğurun.", "Islak elle ceviz büyüklüğünde köfteler şekillendirip tepsiye dizin.", "Domatesleri rendeleyip az tuzla karıştırın ve köftelerin üzerine gezdirin.", "25 dakika, köfteler sıkılaşana kadar pişirin.", "Sıcak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a13_015", title: "Limonlu dereotlu karnabahar salatası", category: "Salatalar", ingredients: ["1 küçük karnabahar", "Yarım demet dereotu", "1 limonun suyu", "2 yemek kaşığı zeytinyağı", "1 küçük kırmızı soğan"], steps: ["Karnabaharı çiçeklerine ayırıp tuzlu kaynar suda diri kalacak şekilde 6–7 dakika haşlayın.", "Süzüp hemen soğuk suya alın, renginin korunması için 2 dakika bekletin ve süzün.", "Soğanı ince piyazlık doğrayıp bir tutam tuzla ovun, durulayıp süzün; acılığı azalır.", "Dereotunu yıkayıp kurulayın ve ince kıyın.", "Limon suyu, zeytinyağı ve tuzu çırpın.", "Karnabahar, soğan ve dereotunu sosla harmanlayın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 34),
  GeneralRecipe(id: "p39a13_016", title: "Fırında mantarlı hindi sote", category: "Tavuk yemekleri", ingredients: ["350 g hindi göğsü", "250 g mantar", "1 kapya biber", "1 soğan", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 200°C ısıtın.", "Hindi etini küçük parçalar halinde doğrayın.", "Mantar, biber ve soğanı dilimleyin.", "Tüm malzemeleri yağla harmanlayıp geniş fırın kabına yayın.", "Hindi tamamen pişene kadar 25-30 dakika fırınlayın."], minutes: 40),
  GeneralRecipe(id: "p39a13_017", title: "Fırında muzlu yulaf bar", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 olgun muz", "2 su bardağı yulaf ezmesi", "3 yemek kaşığı fıstık ezmesi", "2 yemek kaşığı kuru üzüm", "1 çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın.", "Muzları ezip fıstık ezmesiyle karıştırın.", "Yulaf, kuru üzüm ve tarçını ekleyin.", "Karışımı küçük kalıba bastırarak yayın.", "20-25 dakika pişirip tamamen soğuduktan sonra dilimleyin."], minutes: 35),
  GeneralRecipe(id: "p39a13_018", title: "Köz biberli bulgur kısırı", category: "Salatalar", ingredients: ["1 su bardağı ince bulgur", "1 su bardağı sıcak su", "2 közlenmiş kapya biber", "2 dal taze soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Bulguru geniş bir kâseye alıp sıcak suyu ekleyin; üzerini kapatıp 15 dakika şişmeye bırakın.", "Közlenmiş biberlerin kabuğunu ve çekirdeklerini ayıklayıp küçük doğrayın.", "Taze soğanı ince doğrayın.", "Bulguru çatalla havalandırıp biber ve soğanı ekleyin.", "Limon suyu, zeytinyağı ve tuzu ekleyip karıştırın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a13_019", title: "Patatesli pırasalı omlet", category: "Kahvaltılıklar", ingredients: ["2 yumurta", "1 küçük pırasa", "1 küçük patates", "2 yemek kaşığı süt", "1 yemek kaşığı zeytinyağı"], steps: ["Pırasayı iyice yıkayıp ince doğrayın; patatesi küçük küp doğrayın.", "Tavada yağı ısıtıp patatesi kapağı kapalı 8 dakika pişirin.", "Pırasayı ekleyip 4 dakika daha pişirin.", "Yumurtaları sütle birlikte çatalla iyice çırpın.", "Yumurtayı sebzelerin üzerine dökün.", "Yumurtalar tamamen pişene, akışkan kısım kalmayana kadar pişirin; gebelikte ve çocuklarda bu özellikle önemlidir."], minutes: 30),
  GeneralRecipe(id: "p39a13_020", title: "Tarçınlı armutlu sütlü irmik", category: "Tatlılar", ingredients: ["2 su bardağı süt", "4 yemek kaşığı irmik", "1 armut", "2 yemek kaşığı şeker", "Yarım çay kaşığı tarçın"], steps: ["Süt, irmik ve şekeri tencerede soğukken çırparak karıştırın; topaklanmaz.", "Orta ateşte, dibi tutmasın diye sürekli karıştırarak 8–10 dakika, kaşıktan yavaş akacak kıvama gelene kadar pişirin.", "Armudu soyup küçük doğrayın ve tarçınla karıştırın.", "İrmik tatlısını kaselere paylaştırın.", "Armutla süsleyin.", "Oda sıcaklığına gelince üzerini kapatıp buzdolabında en az 1 saat soğutun."], minutes: 25),
  GeneralRecipe(id: "p39a14_001", title: "Fırında yoğurtlu kabak dilimleri", category: "Sebze yemekleri", ingredients: ["3 kabak", "4 yemek kaşığı yoğurt", "1 yumurta", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru nane"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabakları 1 cm halka dilimleyin; kâğıt havluyla suyunu alın.", "Yoğurt, yumurta, yağ, nane ve az tuzu çırpın.", "Kabakları sosla harmanlayıp kaba tek sıra dizin; kalan sosu üzerine dökün.", "20–25 dakika, yumurta tamamen pişip kabaklar yumuşayana kadar pişirin.", "Fırından alıp 5 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 40),
  GeneralRecipe(id: "p39a14_002", title: "Kırmızı mercimekli domates çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı kırmızı mercimek", "3 domates", "1 soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Mercimeği suyu berraklaşana kadar birkaç kez yıkayıp süzün.", "Domatesleri rendeleyin, soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Domatesi ekleyip 5 dakika pişirin.", "Mercimeği ve suyu ekleyip kaynatın; köpüğünü alın.", "Kapağı aralık bırakıp kısık ateşte, ara ara karıştırarak mercimek dağılana kadar 25 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 44),
  GeneralRecipe(id: "p39a14_003", title: "Kekikli fırın tavuk but", category: "Tavuk yemekleri", ingredients: ["4 tavuk but", "2 patates", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik", "1 diş sarımsak"], steps: ["Fırını 200°C’ye ısıtın.", "Butları kâğıt havluyla kurulayın; patatesleri iri dilimleyin.", "Yağ, kekik, ezilmiş sarımsak ve az tuzu karıştırın.", "Butları ve patatesleri bu karışımla harmanlayıp tepsiye tek kat dizin.", "40–45 dakika pişirin.", "Pişirmenin yarısında tavukları ve sebzeleri çevirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Ocaktan ya da fırından alıp 3–5 dakika dinlendirin; suyu içine çekilir ve daha sulu olur."], minutes: 60),
  GeneralRecipe(id: "p39a14_004", title: "Nohutlu pazı kavurması", category: "Sebze yemekleri", ingredients: ["1 demet pazı", "1 su bardağı haşlanmış nohut", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı domates salçası"], steps: ["Pazıyı yaprak yaprak bol suda yıkayın; sapları ince, yaprakları iri doğrayın.", "Soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Salçayı ekleyip 1 dakika kavurun.", "Pazı sapları ve nohudu ekleyip 3 dakika çevirin; yaprakları ilave edin.", "Kapağı kapalı kısık ateşte pazı yumuşayana kadar 12–15 dakika pişirin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın.", "Sıcak servis edin."], minutes: 33),
  GeneralRecipe(id: "p39a14_005", title: "Limonlu havuçlu kuskus", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "1 havuç", "1 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su", "1 yemek kaşığı limon suyu"], steps: ["Havucu rendeleyip yağda 3 dakika soteleyin.", "Kuskusu ekleyip 1 dakika karıştırın.", "Sıcak suyu ekleyip suyunu çekene kadar pişirin.", "Limon suyunu karıştırıp 5 dakika dinlendirin."], minutes: 25),
  GeneralRecipe(id: "p39a14_006", title: "Fırında lorlu patlıcan ruloları", category: "Sebze yemekleri", ingredients: ["2 patlıcan", "150 g lor peyniri", "1 domates", "2 yemek kaşığı zeytinyağı", "2 dal maydanoz"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Patlıcanları uzunlamasına 0,5 cm dilimleyin; tuzlu suda 15 dakika bekletip kurulayın.", "Dilimleri yağlayıp tepsiye dizin; 15 dakika, kıvrılabilecek kadar yumuşatın.", "Maydanozu kıyıp lorla karıştırın.", "Her dilime bir kaşık harç koyup sarın; kapanan yüzü alta gelecek şekilde dizin.", "Üzerlerine rendelenmiş domates koyup 15 dakika daha fırınlayın.", "Ilık servis edin."], minutes: 55),
  GeneralRecipe(id: "p39a14_007", title: "Tahinli elmalı yulaf kasesi", category: "Kahvaltılıklar", ingredients: ["5 yemek kaşığı yulaf", "1 su bardağı süt", "1 elma", "1 tatlı kaşığı tahin", "Yarım çay kaşığı tarçın"], steps: ["Elmayı küçük küp doğrayın.", "Yulaf ve sütü küçük bir tencereye alıp orta ateşte, sürekli karıştırarak koyulaşana kadar 5–6 dakika pişirin.", "Elma ve tarçını ekleyip 2 dakika daha pişirin.", "Kaseye alıp üzerine tahin gezdirerek servis edin.", "Koyulaşırsa 2–3 kaşık sıcak süt ekleyip karıştırın.", "Sıcak servis edin."], minutes: 18),
  GeneralRecipe(id: "p39a14_008", title: "Köz patlıcanlı tahinli yoğurt mezesi", category: "Mezeler", ingredients: ["2 patlıcan", "1 su bardağı süzme yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı limon suyu"], steps: ["Patlıcanları ocakta veya fırında közleyip soğutun.", "Kabuklarını soyup içlerini ince kıyın.", "Yoğurt, ezilmiş sarımsak ve limonla karıştırın.", "Zeytinyağı gezdirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a14_009", title: "Mantarlı ıspanaklı bulgur", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "150 g mantar", "2 avuç ıspanak", "1 soğan", "2 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı"], steps: ["Bulguru bir kez yıkayıp süzün.", "Soğanı ince doğrayın, ıspanağı yıkayıp doğrayın.", "Tencerede yağı ısıtıp soğanı 3–4 dakika pembeleştirin.", "Mantarları dilimleyip ekleyin; suyunu salıp çekene kadar 5–6 dakika soteleyin.", "Ispanağı ekleyip söndürün.", "Bulguru ekleyip yağa bulanması için 1–2 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika, suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 47),
  GeneralRecipe(id: "p39a14_010", title: "Portakallı fırın havuç", category: "Sebze yemekleri", ingredients: ["5 havuç", "1 portakalın suyu", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kimyon", "1 yemek kaşığı susam"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Havuçları soyup uzunlamasına, eşit kalınlıkta dilimleyin.", "Portakal suyu, yağ, kimyon ve az tuzla harmanlayıp tepsiye yayın.", "25 dakika pişirin.", "Pişirmenin yarısında sebzeleri spatulayla çevirin ki her yüzü eşit kızarsın.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Susamı kuru tavada 1–2 dakika kavurup üzerine serperek servis edin."], minutes: 37),
  GeneralRecipe(id: "p39a14_011", title: "Domatesli mercimekli erişte", category: "Makarnalar", ingredients: ["1 su bardağı erişte", "Yarım su bardağı haşlanmış yeşil mercimek", "2 domates", "1 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Domatesleri rendeleyin.", "Tencerede yağı ısıtıp domatesi 5 dakika pişirin.", "Erişte ve haşlanmış mercimeği ekleyip karıştırın.", "Sıcak suyu ve az tuzu ekleyin; kapağı kapalı kısık ateşte 12–15 dakika, erişte yumuşayana kadar pişirin.", "Ocaktan alıp 5 dakika dinlendirin.", "Sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a14_012", title: "Fırında limonlu çipura ve rezene", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş çipura", "1 rezene kökü", "1 limon", "2 yemek kaşığı zeytinyağı", "2 dal dereotu"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Rezenenin sert dış yapraklarını ayıklayıp ince dilimleyin.", "Rezeneyi yağın yarısı ve az tuzla harmanlayıp tepsiye yayın; 10 dakika ön pişirin.", "Balıkların içini ve pullarını kontrol edip durulayın ve kurulayın; sırtlarına 2–3 çizik atın.", "Balıkları rezenenin üzerine yerleştirin; limon dilimleri, dereotu ve kalan yağı ekleyin.", "25–30 dakika pişirin.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Servis ederken kılçıkları ayırın; çocuk porsiyonunu kılçıksız hazırlayın.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 50),
  GeneralRecipe(id: "p39a14_013", title: "Cevizli pancarlı kinoa", category: "Diyet ve sağlıklı tarifler", ingredients: ["Yarım su bardağı kinoa", "1 haşlanmış pancar", "2 yemek kaşığı ceviz", "1 yemek kaşığı limon suyu", "1 yemek kaşığı zeytinyağı"], steps: ["Kinoayı yıkayıp bir su bardağı suda 15 dakika pişirin.", "Kinoayı soğutup pancarı küçük küpler halinde doğrayın.", "Cevizi iri kırın.", "Tüm malzemeleri limon ve yağla karıştırın."], minutes: 35),
  GeneralRecipe(id: "p39a14_014", title: "Peynirli kabaklı mini pankek", category: "Kahvaltılıklar", ingredients: ["1 küçük kabak", "1 yumurta", "3 yemek kaşığı un", "3 yemek kaşığı beyaz peynir", "1 tatlı kaşığı zeytinyağı"], steps: ["Kabağı rendeleyip suyunu iyice sıkın.", "Peyniri ufalayın.", "Kabak, yumurta, un ve peyniri karıştırın.", "Yapışmaz tavayı kısık-orta ateşte ısıtıp çok az yağla yağlayın.", "Tavaya kaşıkla küçük porsiyonlar dökün; yüzeyde kabarcıklar oluşunca çevirip diğer yüzünü de 1–2 dakika pişirin.", "Sıcak servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a14_015", title: "Fırında tarçınlı elmalı irmik kup", category: "Tatlılar", ingredients: ["2 elma", "3 yemek kaşığı irmik", "2 su bardağı süt", "2 yemek kaşığı şeker", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın.", "Süt, irmik ve şekeri tencerede soğukken çırparak karıştırın; topaklanmaz.", "Orta ateşte, dibi tutmasın diye sürekli karıştırarak 8–10 dakika, kaşıktan yavaş akacak kıvama gelene kadar pişirin.", "Elmaları soyup rendeleyin; kararmaması için hemen tarçınla harmanlayın.", "Kaselere irmik ve elmayı kat kat yerleştirin.", "10 dakika fırınlayın.", "Ilık servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a14_016", title: "Yoğurtlu naneli buğday çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı aşurelik buğday", "1 su bardağı yoğurt", "1 yumurta sarısı", "1 yemek kaşığı un", "4 su bardağı su", "1 tatlı kaşığı kuru nane"], steps: ["Buğdayı bir gece önceden ıslatın; süzüp suyla tencereye alın.", "Kaynayınca kısık ateşte, buğday yumuşayana kadar 40–45 dakika pişirin; gerekirse sıcak su ekleyin.", "Terbiye için yoğurt, yumurta sarısı ve unu bir kâsede pürüzsüz olana kadar çırpın.", "Kaynayan çorbadan birkaç kepçe alıp terbiyeye azar azar ekleyerek ılıştırın; sonra terbiyeyi sürekli karıştırarak tencereye dökün.", "Sürekli karıştırarak bir taşım kaynatın ve ocağı kapatın; terbiyenin kesilmemesi için yüksek ateşte bırakmayın.", "Kuru naneyi ekleyip karıştırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 55),
  GeneralRecipe(id: "p39a14_017", title: "Kıymalı fırın karnabahar", category: "Et yemekleri", ingredients: ["1 küçük karnabahar", "250 g kıyma", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın.", "Karnabaharı çiçeklerine ayırıp buharda 8 dakika pişirin.", "Soğanı ince doğrayın, domatesleri rendeleyin.", "Tavada yağı ısıtıp soğanı 3–4 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Domatesi ekleyip 5 dakika kaynatın.", "Karnabahar ve kıymalı sosu fırın kabında birleştirin.", "20 dakika pişirin.", "Sıcak servis edin."], minutes: 55),
  GeneralRecipe(id: "p39a14_018", title: "Biberli nohutlu makarna salatası", category: "Salatalar", ingredients: ["1 su bardağı kısa makarna", "1 su bardağı haşlanmış nohut", "1 kapya biber", "Yarım demet maydanoz", "2 yemek kaşığı limon suyu", "1 yemek kaşığı zeytinyağı"], steps: ["Makarnayı tuzlu kaynar suda paketteki süre kadar haşlayın; süzüp soğuk suyla durulayın.", "Nohutları süzüp durulayın.", "Kapya biberi küçük küp doğrayın.", "Maydanozu yıkayıp kurulayın ve ince kıyın.", "Tüm malzemeleri bir kâsede birleştirin.", "Limon suyu, zeytinyağı ve tuzu ekleyip karıştırın.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a14_019", title: "Fırında tarçınlı muzlu ekmek", category: "Kek ve kurabiyeler", ingredients: ["2 olgun muz", "2 yumurta", "1,5 su bardağı un", "Yarım su bardağı süt", "1 paket kabartma tozu", "1 çay kaşığı tarçın"], steps: ["Fırını 175°C ısıtın.", "Muzları ezip yumurta ve sütle çırpın.", "Un, kabartma tozu ve tarçını ekleyip karıştırın.", "Yağlanmış kalıba döküp ortası tamamen pişene kadar 35-40 dakika fırınlayın."], minutes: 55),
  GeneralRecipe(id: "p39a14_020", title: "Tavuklu sebzeli karabuğday", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı karabuğday", "250 g tavuk göğsü", "1 havuç", "1 küçük kabak", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Tavuğu küçük doğrayıp yağda tamamen pişene kadar soteleyin.", "Küp doğranmış havuç ve kabağı ekleyip 5 dakika pişirin.", "Yıkanmış karabuğdayı ve sıcak suyu ilave edin.", "Kapağı kapalı şekilde suyunu çekene kadar 15-20 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a15_001", title: "Fırında sebzeli hindi rosto", category: "Tavuk yemekleri", ingredients: ["500 g hindi göğüs", "2 havuç", "1 kabak", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik"], steps: ["Fırını 190°C’ye ısıtın.", "Hindi etini 4–5 cm iri parçalara bölün.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Havuç, kabak ve soğanı iri doğrayın.", "Hindi ve sebzeleri yağ, kekik ve az tuzla harmanlayın.", "Fırın kabına yayıp üzerini yağlı kâğıtla örtün.", "35 dakika pişirin.", "Kâğıdı açıp 10–15 dakika daha, hafif kızarana kadar pişirin.", "Hindinin en kalın parçasını kesip kontrol edin: içi pembe kalmamalı; termometre varsa en az 74°C olmalı.", "Ocaktan ya da fırından alıp 3–5 dakika dinlendirin; suyu içine çekilir ve daha sulu olur."], minutes: 65),
  GeneralRecipe(id: "p39a15_002", title: "Kremasız pırasa patates çorbası", category: "Çorbalar", ingredients: ["2 pırasa", "2 patates", "1 soğan", "1 yemek kaşığı zeytinyağı", "5 su bardağı sebze suyu"], steps: ["Pırasaları ikiye yarıp aralarındaki toprağı akan suda iyice yıkayın; ince doğrayın.", "Patatesleri soyup küp, soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Pırasayı ekleyip 5 dakika, sönene kadar çevirin.", "Patatesi ve sebze suyunu ekleyip kaynatın.", "Kapağı aralık bırakıp kısık ateşte, sebzeler çatalla kolayca ezilene kadar 20 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 39),
  GeneralRecipe(id: "p39a15_003", title: "Fırında domates soslu kabak kayıkları", category: "Sebze yemekleri", ingredients: ["3 kabak", "2 domates", "1 soğan", "1 su bardağı haşlanmış yeşil mercimek", "2 yemek kaşığı zeytinyağı", "3 yemek kaşığı rendelenmiş kaşar"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Kabakları boyuna ikiye bölüp içlerini kaşıkla, kenarlarda 0,5 cm bırakarak oyun.", "Soğanı ince, domatesleri küp doğrayın.", "Tavada yağı ısıtıp soğanı 4 dakika soteleyin; domatesi ekleyip 4 dakika pişirin.", "Mercimeği ve az tuzu ekleyip karıştırın.", "İç harcı kabaklara paylaştırıp tepsiye dizin; dibine yarım su bardağı su ekleyin.", "Kaşarı serpip 25–30 dakika, kabaklar yumuşayana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a15_004", title: "Nohutlu köz biberli kinoa pilavı", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı kinoa", "1 su bardağı haşlanmış nohut", "2 közlenmiş kapya biber", "2 su bardağı su", "1 yemek kaşığı zeytinyağı", "Yarım limonun suyu"], steps: ["Kinoayı bol suyla yıkayıp süzün.", "Kinoayı suyla 15 dakika pişirip 5 dakika dinlendirin.", "Köz biberleri doğrayıp nohutla birlikte kinoaya ekleyin.", "Zeytinyağı ve limon suyuyla karıştırarak servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a15_005", title: "Dereotlu fırın mezgit", category: "Balık ve deniz ürünleri", ingredients: ["500 g mezgit fileto", "1 limon", "2 yemek kaşığı zeytinyağı", "Yarım demet dereotu", "1 diş sarımsak"], steps: ["Fırını 190°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Balığı soğuk suyla durulayıp kâğıt havluyla iyice kurulayın.", "Filetoların üzerinde parmaklarınızı gezdirip kalan kılçıkları cımbızla çekin; çocuklar için özellikle önemlidir.", "Balıkları fırın kabına dizin.", "Limon suyu, yağ, ezilmiş sarımsak ve az tuzu karıştırın.", "Sosu balıkların üzerine döküp kıyılmış dereotunu serpin.", "18–22 dakika pişirin; mezgit ince olduğundan 15. dakikada kontrol etmeye başlayın.", "En kalın yerinden çatalla kontrol edin: et opaklaşmış, kolayca lif lif ayrılıyor olmalı; termometre varsa en az 63°C.", "Gebelikte balığı tamamen pişmiş yiyin; levrek, çipura, somon, alabalık ve mezgit cıvası düşük, haftada 2 porsiyon için uygundur."], minutes: 32),
  GeneralRecipe(id: "p39a15_006", title: "Fırında mantarlı ıspanaklı yumurta", category: "Kahvaltılıklar", ingredients: ["3 yumurta", "150 g mantar", "2 avuç ıspanak", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Fırını 180°C’ye ısıtın; fırın kabını hafifçe yağlayın.", "Mantarları dilimleyip tavada zeytinyağıyla suyunu çekene kadar 5 dakika soteleyin.", "Ispanağı ekleyip söndürün.", "Yumurtaları sütle birlikte çatalla iyice çırpın.", "Sebzeleri kaba yayıp yumurtayı üzerine dökün.", "Fırında 15–18 dakika, yumurta tamamen pişene kadar pişirin.", "Sıcak servis edin."], minutes: 33),
  GeneralRecipe(id: "p39a15_007", title: "Köz havuçlu mercimek salatası", category: "Salatalar", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "3 havuç", "1 avuç roka", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "1 tatlı kaşığı kimyon"], steps: ["Fırını 200°C’ye ısıtın.", "Havuçları soyup parmak kalınlığında doğrayın; zeytinyağının yarısı ve kimyonla harmanlayın.", "Tepsiye yayıp 20–25 dakika, kenarları kızarana kadar fırınlayın.", "Yeşillikleri bol suda yıkayıp süzgeçte iyice süzdürün; kâğıt havluyla kurulayın.", "Mercimeği süzüp rokayla birleştirin.", "Havuçları ekleyin; kalan zeytinyağı, limon suyu ve tuzla harmanlayın."], minutes: 35),
  GeneralRecipe(id: "p39a15_008", title: "Yoğurtlu dereotlu patates salatası", category: "Salatalar", ingredients: ["3 orta boy patates", "4 yemek kaşığı yoğurt", "Yarım demet dereotu", "1 tatlı kaşığı hardal", "1 yemek kaşığı limon suyu"], steps: ["Patatesleri kabuklarıyla, bıçak kolayca batana kadar 20–25 dakika haşlayın.", "Ilıyınca soyup küp doğrayın.", "Dereotunu yıkayıp kurulayın ve ince kıyın.", "Yoğurt, hardal ve limon suyunu çırpın; tuzunu ayarlayın.", "Patatesleri sosla nazikçe harmanlayın ve dereotunu ekleyin.", "Buzdolabında 15 dakika dinlendirip soğuk servis edin."], minutes: 50),
  GeneralRecipe(id: "p39a15_009", title: "Fırında kıymalı mantar dolması", category: "Et yemekleri", ingredients: ["10 büyük kültür mantarı", "200 g kıyma", "1 küçük soğan", "1 domates", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı kaşar"], steps: ["Fırını 190°C’ye ısıtın.", "Mantarları nemli bezle silin; saplarını çıkarıp ince kıyın.", "Soğanı ince doğrayın, domatesi küp kesin.", "Tavada yağı ısıtıp soğanı 3 dakika kavurun.", "Kıymayı ekleyip suyunu salıp çekene ve rengi tamamen dönene kadar 7–8 dakika kavurun.", "Mantar saplarını ve domatesi ekleyip 5 dakika pişirin; tuzunu ayarlayın.", "Mantar çanaklarını harçla doldurup fırın kabına dizin; kaşar serpin.", "20 dakika, mantarlar yumuşayıp peynir kızarana kadar pişirin.", "Sıcak servis edin."], minutes: 46),
  GeneralRecipe(id: "p39a15_010", title: "Portakallı zeytinyağlı pancar", category: "Sebze yemekleri", ingredients: ["3 küçük pancar", "1 portakalın suyu", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı su"], steps: ["Eldiven takıp pancarları soyun ve ince yarım ay dilimleyin.", "Soğanı ince doğrayın.", "Tencerede yağı ısıtıp soğanı 3 dakika yumuşatın.", "Pancar, portakal suyu, su ve az tuzu ekleyin.", "Kapağı kapalı kısık ateşte pancarlar yumuşayana kadar 30–35 dakika pişirin.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Ocaktan alıp kapağı kapalı ılımaya bırakın; zeytinyağlılar ılık ya da oda sıcaklığında daha lezzetlidir."], minutes: 48),
  GeneralRecipe(id: "p39a15_011", title: "Tavuklu limonlu arpa şehriye", category: "Makarnalar", ingredients: ["1 su bardağı arpa şehriye", "250 g tavuk göğsü", "1 havuç", "2 su bardağı sıcak su", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Tavuğu küçük küp doğrayın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Tencerede yağı ısıtıp tavuğu 6–7 dakika, her tarafı beyazlayana kadar soteleyin.", "Havucu rendeleyin; arpa şehriyeyle birlikte ekleyip 3 dakika kavurun.", "Sıcak suyu ve az tuzu ekleyin; kapağı kapalı kısık ateşte 12–15 dakika, suyunu çekene kadar pişirin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Limon suyunu ekleyip ocaktan alın; kapağı kapalı 5 dakika dinlendirin."], minutes: 40),
  GeneralRecipe(id: "p39a15_012", title: "Fırında peynirli karnabahar dilimleri", category: "Sebze yemekleri", ingredients: ["1 büyük karnabahar", "3 yemek kaşığı yoğurt", "1 yumurta", "4 yemek kaşığı rendelenmiş kaşar", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Karnabaharı sapından geçecek şekilde 2 cm kalın dilimler halinde kesin.", "Dilimleri tepsiye dizip 15 dakika ön pişirin.", "Yoğurt, yumurta ve yağı çırpıp dilimlere sürün; kaşar serpin.", "15 dakika daha, yumurta tamamen pişip üzeri kızarana kadar pişirin.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Sıcak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a15_013", title: "Bulgurlu mantarlı sebze çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı ince bulgur", "150 g mantar", "1 havuç", "1 küçük soğan", "5 su bardağı su", "1 yemek kaşığı zeytinyağı"], steps: ["Mantarları dilimleyin; havucu küçük küp, soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Mantar ve havucu ekleyip mantarlar suyunu çekene kadar 6 dakika soteleyin.", "Suyu ekleyip kaynatın.", "Bulguru ekleyip kısık ateşte, bulgur yumuşayana kadar 15 dakika pişirin.", "Kıvamı koyu gelirse sıcak su ekleyip 2 dakika daha kaynatın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 37),
  GeneralRecipe(id: "p39a15_014", title: "Elmalı cevizli yoğurt tatlısı", category: "Tatlılar", ingredients: ["2 elma", "1 su bardağı yoğurt", "2 yemek kaşığı ceviz", "1 tatlı kaşığı bal", "Yarım çay kaşığı tarçın"], steps: ["Elmaları soyup küp doğrayın.", "Tavada 2–3 kaşık suyla 5–6 dakika yumuşatın; tarçını ekleyin.", "Yoğurdu kaselere paylaştırın.", "Ilık elmaları yoğurdun üzerine koyun.", "Ceviz ve balı ekleyip servis edin.", "Bal 1 yaşından küçük bebeklere verilmez; bebek porsiyonunu balsız ayırın."], minutes: 16),
  GeneralRecipe(id: "p39a15_015", title: "Tahinli kakolu yulaf topları", category: "Tatlılar", ingredients: ["1 su bardağı yulaf ezmesi", "2 yemek kaşığı tahin", "2 yemek kaşığı kakao", "1 olgun muz", "2 yemek kaşığı Hindistan cevizi"], steps: ["Muzu çatalla pürüzsüz olana kadar ezin.", "Yulaf, tahin ve kakaoyu ekleyip yoğurun; kıvam yumuşaksa 1–2 kaşık yulaf daha ekleyin.", "Karışımı 10 dakika buzdolabında bekletin; şekil vermesi kolaylaşır.", "Islak elle ceviz büyüklüğünde toplar yuvarlayın.", "Hindistan cevizine bulayın.", "Buzdolabında 20 dakika dinlendirin.", "Kapalı kapta buzdolabında 3 gün saklayabilirsiniz."], minutes: 40),
  GeneralRecipe(id: "p39a15_016", title: "Fırında ıspanaklı nohut köftesi", category: "Sebze yemekleri", ingredients: ["1,5 su bardağı haşlanmış nohut", "2 avuç ıspanak", "1 yumurta", "3 yemek kaşığı yulaf unu", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Nohudu süzüp çatalla ezin; ıspanağı yıkayıp ince kıyın.", "Nohut, ıspanak, yumurta, yulaf unu ve az tuzu yoğurun; kıvam yumuşaksa 1 kaşık yulaf unu daha ekleyin.", "Islak elle küçük köfteler şekillendirip tepsiye dizin ve üzerlerine yağ sürün.", "15 dakika pişirin; çevirip 8–10 dakika daha, iki tarafı kızarana kadar fırınlayın.", "Sıcak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a15_017", title: "Domatesli fasulyeli kuskus salatası", category: "Dünya mutfağı", ingredients: ["1 su bardağı haşlanmış kuskus", "1 su bardağı haşlanmış kuru fasulye", "2 domates", "1 salatalık", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Kuskusu haşlayıp süzün ve soğutun.", "Domates ve salatalığı küçük küpler halinde doğrayın.", "Kuskus ve fasulyeyi sebzelerle karıştırın.", "Zeytinyağı ve limonla harmanlayarak servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a15_018", title: "Fırında patatesli pırasa böreği", category: "Hamur işleri", ingredients: ["3 yufka", "2 pırasa", "2 patates", "1 yumurta", "Yarım su bardağı süt", "3 yemek kaşığı zeytinyağı"], steps: ["Fırını 180°C’ye ısıtın; tepsiyi hafifçe yağlayın.", "Patatesleri haşlayıp ezin.", "Pırasaları boyuna yarıp katlarını iyice yıkayın; ince doğrayın.", "Tavada yağın yarısıyla pırasayı 8 dakika yumuşatın.", "Pırasa ve patatesi karıştırıp az tuzla tatlandırın; soğutun.", "Süt, yumurta ve kalan yağı çırpın.", "Yufkaları ikiye kesip sosla ıslatın; harcı sarıp rulo yapın.", "Rulo böreği yağlanmış tepsiye, ek yeri alta gelecek şekilde dizin.", "Kalan sosu üstüne sürüp 30–35 dakika, kızarana kadar pişirin.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 63),
  GeneralRecipe(id: "p39a15_019", title: "Kabaklı dereotlu mercimek mücveri", category: "Sebze yemekleri", ingredients: ["2 kabak", "1 su bardağı haşlanmış kırmızı mercimek", "1 yumurta", "3 yemek kaşığı un", "Yarım demet dereotu", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.", "Kabakları rendeleyip bir tutam tuzla 5 dakika bekletin; sonra avucunuzla suyunu iyice sıkın.", "Mercimeği süzüp ezin; dereotunu kıyın.", "Kabak, mercimek, yumurta, un ve dereotunu karıştırın.", "Kaşıkla porsiyonlar alıp tepsiye dizin ve üzerlerine yağ sürün.", "20 dakika pişirin; çevirip 5 dakika daha fırınlayın.", "Ortasına kürdan batırın: kuru çıkıyorsa ve yumurta tamamen pişmişse hazırdır."], minutes: 40),
  GeneralRecipe(id: "p39a15_020", title: "Fırında armutlu yulaf kup", category: "Tatlılar", ingredients: ["2 armut", "Yarım su bardağı yulaf ezmesi", "Yarım su bardağı süt", "1 yemek kaşığı ceviz", "1 tatlı kaşığı bal", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın.", "Armutları yıkayıp küçük doğrayın; fırın kaplarına paylaştırın.", "Yulaf, süt, tarçın ve cevizi karıştırın.", "Karışımı armutların üzerine yayın.", "20–25 dakika, üstü hafif kızarana kadar pişirin.", "Ilıkken bal gezdirin.", "Bal 1 yaşından küçük bebeklere verilmez; bebek porsiyonunu balsız ayırın."], minutes: 35),
  GeneralRecipe(id: "p39a16_001", title: "Kabaklı beyaz fasulye çorbası", category: "Çorbalar", ingredients: ["2 orta boy kabak (küp doğranmış)", "1 su bardağı haşlanmış beyaz fasulye", "1 küçük kuru soğan (ince doğranmış)", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı tereyağı", "4 su bardağı sıcak su veya sebze suyu", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "1 çay kaşığı kuru nane"], steps: ["Tencerede zeytinyağını ısıtıp soğanı orta ateşte 4 dakika pembeleşene kadar kavurun, sarımsağı ekleyip 30 saniye çevirin.", "Kabak küplerini ekleyin ve 5 dakika ara ara karıştırarak soteleyin.", "Beyaz fasulyenin üçte ikisini ve sıcak suyu ekleyin; kaynayınca kısık ateşte kapağı kapalı 15 dakika, kabaklar iyice yumuşayana kadar pişirin.", "Tencereyi ocaktan alıp 5 dakika ılıtın, el blenderıyla pürüzsüz hâle getirin.", "Kalan bütün fasulyeleri ekleyin, tuz ve karabiberle tatlandırıp 3 dakika daha kaynatın; kıvam koyuysa biraz sıcak su ekleyin.", "Küçük tavada tereyağını eritip naneyi 10 saniye çevirin ve servis sırasında çorbanın üzerine gezdirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Fasulyenin bir kısmını bütün bırakmak çorbaya doku kazandırır.", "Konserve fasulye kullanıyorsanız iyice yıkayıp süzün; tuzu azaltın."], serving: "Limon dilimi ve kızarmış ekmekle sıcak servis edin.", storage: "Buzdolabında kapalı kapta 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_002", title: "Kerevizli havuç çorbası", category: "Çorbalar", ingredients: ["1 orta boy kereviz kökü (yaklaşık 400 g, soyulup küp doğranmış)", "2 havuç (halka)", "1 küçük kuru soğan", "1 küçük patates", "1 yemek kaşığı zeytinyağı", "4 su bardağı sıcak su", "Yarım su bardağı süt", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "1 tutam muskat (isteğe bağlı)"], steps: ["Kerevizi soyduktan sonra kararmaması için limonlu suda bekletin.", "Tencerede zeytinyağıyla doğranmış soğanı 3 dakika kavurun.", "Kereviz, havuç ve patatesi ekleyip 4 dakika çevirin.", "Sıcak suyu ilave edin; kaynayınca kısık ateşte kapağı kapalı 20 dakika, sebzeler çatalla kolayca ezilene kadar pişirin.", "Ocaktan alıp hafifçe ılıtın ve blenderdan geçirin.", "Sütü, tuzu, karabiberi ve muskatı ekleyip kaynamaya başlayana kadar ısıtın ve servis edin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Patates çorbaya krema eklemeden kadifemsi kıvam verir.", "Süt ekledikten sonra çorbayı kaynatmayın, kesilebilir."], serving: "Üzerine birkaç damla zeytinyağı ve kıyılmış maydanozla servis edin.", storage: "Buzdolabında 3 gün saklanır; sütsüz hâlde dondurulabilir."),
  GeneralRecipe(id: "p39a16_003", title: "Balkabaklı kırmızı mercimek çorbası", category: "Çorbalar", ingredients: ["300 g balkabağı (soyulup küp doğranmış)", "Yarım su bardağı kırmızı mercimek (yıkanmış)", "1 küçük kuru soğan", "1 havuç", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tereyağı", "5 su bardağı sıcak su", "1 çay kaşığı tuz", "Yarım çay kaşığı kimyon", "Yarım çay kaşığı pul biber", "Yarım limon"], steps: ["Mercimeği süzgeçte suyu berraklaşana kadar yıkayın.", "Tencerede zeytinyağıyla soğan ve havucu 4 dakika kavurun.", "Balkabağını ve mercimeği ekleyip 2 dakika karıştırın.", "Sıcak suyu ekleyin; kaynayınca köpüğünü alıp kısık ateşte 25 dakika, mercimek dağılana kadar pişirin.", "Blenderdan geçirip tuz ve kimyonla tatlandırın; kıvam koyuysa sıcak su ekleyin.", "Tereyağında pul biberi kızdırıp servis sırasında çorbanın üzerine gezdirin, limonla servis edin."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Balkabağının tatlılığı limonla dengelenir; servis sırasında mutlaka limon sıkın.", "Mercimek pişerken dibi tutabilir; ara ara karıştırın."], serving: "Limon ve kıtır ekmekle sıcak servis edin.", storage: "Buzdolabında 3 gün, dondurucuda 2 ay saklanır."),
  GeneralRecipe(id: "p39a16_004", title: "Brokolili patates çorbası", category: "Çorbalar", ingredients: ["1 küçük brokoli (yaklaşık 350 g, çiçeklerine ayrılmış)", "1 orta boy patates (küp)", "1 küçük kuru soğan", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "4 su bardağı sıcak su", "Yarım su bardağı süt", "2 yemek kaşığı rendelenmiş kaşar peyniri (isteğe bağlı)", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Brokoliyi çiçeklerine ayırın, sapını soyup küçük doğrayın; ayrı bir kâsede birkaç küçük çiçeği süsleme için ayırın.", "Tencerede zeytinyağıyla soğan ve sarımsağı 3 dakika kavurun.", "Patates ve brokoli sapını ekleyip sıcak suyu ilave edin; 10 dakika pişirin.", "Brokoli çiçeklerini ekleyip 8 dakika daha, brokoli yumuşayana ama rengi solmadan pişirin.", "Blenderdan geçirin; süt, tuz ve karabiberi ekleyip kaynamadan ısıtın.", "Ayırdığınız brokoli çiçeklerini 2 dakika haşlayın; çorbayı bunlar ve kaşar peyniriyle servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Brokoliyi uzun pişirmek rengini ve aromasını bozar; çiçekleri sonradan ekleyin."], serving: "Üzerine kaşar ve haşlanmış brokoli çiçekleriyle sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_005", title: "Karnabaharlı pırasa çorbası", category: "Çorbalar", ingredients: ["300 g karnabahar", "1 pırasa (sadece beyaz ve açık yeşil kısmı, halka)", "1 küçük patates", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı", "4 su bardağı sıcak su veya tavuk suyu", "Yarım su bardağı süt", "1 çay kaşığı tuz", "Yarım çay kaşığı beyaz biber", "1 yemek kaşığı kıyılmış frenk soğanı veya maydanoz"], steps: ["Pırasa halkalarını bol suda yıkayıp toprağını iyice temizleyin.", "Tencerede tereyağı ve zeytinyağını eritip pırasayı kısık ateşte 6 dakika, rengi koyulaşmadan yumuşatın.", "Karnabahar çiçeklerini ve küp patatesi ekleyip 2 dakika çevirin.", "Sıcak suyu ekleyip kaynatın; kısık ateşte 18 dakika sebzeler yumuşayana kadar pişirin.", "Blenderdan geçirin; süt, tuz ve beyaz biberi ekleyip kaynamaya yakın ısıtın.", "Frenk soğanı serperek servis edin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Pırasayı kavururken renk almaması çorbanın beyaz ve zarif görünmesini sağlar."], serving: "Kızarmış ekmek küpleriyle sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_006", title: "Naneli bezelye çorbası", category: "Çorbalar", ingredients: ["2 su bardağı bezelye (taze veya dondurulmuş)", "1 küçük kuru soğan", "1 küçük patates", "1 yemek kaşığı zeytinyağı", "4 su bardağı sıcak su", "1 tatlı kaşığı kuru nane veya 6 yaprak taze nane", "3 yemek kaşığı süzme yoğurt", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Tencerede zeytinyağıyla doğranmış soğanı 3 dakika yumuşatın.", "Küp patatesi ve sıcak suyu ekleyip 10 dakika pişirin.", "Bezelyeyi ekleyin; dondurulmuşsa çözdürmeden kullanın ve 6–7 dakika, bezelye yumuşayana kadar pişirin.", "Naneyi ekleyip blenderdan geçirin; tuz ve karabiberle tatlandırın.", "Kıvamı çok koyuysa sıcak su ekleyerek 1 dakika daha kaynatın.", "Servis kâselerine alıp her birinin ortasına bir kaşık süzme yoğurt koyun."], minutes: 25, servings: 4, prepMinutes: 5, cookMinutes: 20, difficulty: "Kolay", tips: ["Bezelyeyi fazla pişirmeyin; rengi canlı yeşil kalmalıdır."], serving: "Yoğurt ve birkaç taze nane yaprağıyla sıcak veya ılık servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_007", title: "Ispanaklı pirinç çorbası", category: "Çorbalar", ingredients: ["200 g ıspanak (yıkanıp doğranmış)", "3 yemek kaşığı pirinç (yıkanmış)", "1 küçük kuru soğan", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı un", "5 su bardağı sıcak su", "1 su bardağı yoğurt", "1 yumurta sarısı", "1 çay kaşığı tuz", "1 çay kaşığı kuru nane"], steps: ["Tencerede zeytinyağıyla soğanı 3 dakika kavurun, unu ekleyip 1 dakika daha kavurun.", "Sıcak suyu çırparak ekleyin, pirinci ilave edip kısık ateşte 12 dakika pişirin.", "Ispanağı ekleyin, 5 dakika daha pişirin.", "Ayrı bir kâsede yoğurt ve yumurta sarısını çırpın; çorbadan birkaç kepçe alıp yoğurda azar azar ekleyerek ılıştırın.", "Ilıştırılmış yoğurdu çorbaya sürekli karıştırarak ekleyin ve kaynamaya başlayınca ocaktan alın; tuzunu ayarlayın.", "Servis sırasında üzerine nane serpin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Yoğurdu ılıştırmadan doğrudan eklerseniz çorba kesilir."], serving: "Sıcak olarak, limon sıkarak servis edin.", storage: "Buzdolabında 2 gün saklanır; ısıtırken kaynatmayın."),
  GeneralRecipe(id: "p39a16_008", title: "Mantarlı arpa şehriye çorbası", category: "Çorbalar", ingredients: ["250 g kültür mantarı (dilimlenmiş)", "Yarım çay bardağı arpa şehriye", "1 küçük kuru soğan", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı domates salçası", "5 su bardağı sıcak su veya tavuk suyu", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "1 çay kaşığı kekik"], steps: ["Tencerede tereyağı ve zeytinyağını ısıtın; mantarları yüksek ateşte suyunu salıp çekene kadar 6 dakika soteleyin.", "Doğranmış soğanı ekleyip 3 dakika kavurun.", "Arpa şehriyeyi ekleyip 1 dakika çevirin, salçayı ilave edip 1 dakika daha kavurun.", "Sıcak suyu ekleyin; kaynayınca kısık ateşte 10 dakika, şehriye yumuşayana kadar pişirin.", "Tuz, karabiber ve kekikle tatlandırın.", "5 dakika dinlendirip servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Mantarları kalabalık olmayan geniş tencerede pişirin; aksi hâlde kızarmaz, haşlanır."], serving: "Limon ve kıyılmış maydanozla sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır; şehriye zamanla şişeceği için ısıtırken su ekleyin."),
  GeneralRecipe(id: "p39a16_009", title: "Nohutlu domates çorbası", category: "Çorbalar", ingredients: ["4 olgun domates (rendelenmiş) veya 400 g konserve domates", "1 su bardağı haşlanmış nohut", "1 küçük kuru soğan", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı domates salçası", "4 su bardağı sıcak su", "1 çay kaşığı tuz", "Yarım çay kaşığı kimyon", "1 tutam şeker (domates ekşiyse)"], steps: ["Tencerede zeytinyağıyla soğanı 4 dakika kavurun, sarımsağı ekleyip 30 saniye çevirin.", "Salçayı ekleyip 1 dakika kavurun, ardından rendelenmiş domatesi ilave edip 5 dakika pişirin.", "Nohudun yarısını ve sıcak suyu ekleyin; 12 dakika kaynatın.", "Blenderdan geçirip pürüzsüz hâle getirin.", "Kalan bütün nohutları ekleyin; tuz, kimyon ve gerekiyorsa şekerle tatlandırıp 3 dakika daha pişirin.", "Sıcak servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Domates ekşiliğini dengelemek için bir tutam şeker yeterlidir."], serving: "Üzerine rendelenmiş peynir veya yoğurtla servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_010", title: "Zencefilli havuç çorbası", category: "Çorbalar", ingredients: ["5 havuç (yaklaşık 500 g, halka)", "1 tatlı kaşığı rendelenmiş taze zencefil", "1 küçük kuru soğan", "1 küçük patates", "1 yemek kaşığı zeytinyağı", "4 su bardağı sıcak su", "Yarım portakalın suyu", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "2 yemek kaşığı yoğurt"], steps: ["Tencerede zeytinyağıyla soğanı 3 dakika kavurun, zencefili ekleyip 30 saniye çevirin.", "Havuç ve patatesi ekleyip 3 dakika soteleyin.", "Sıcak suyu ilave edin; kaynayınca kısık ateşte 20 dakika, havuçlar tamamen yumuşayana kadar pişirin.", "Ocaktan alıp ılıtın ve blenderdan geçirin.", "Portakal suyu, tuz ve karabiberi ekleyip 2 dakika ısıtın.", "Kâselere alıp ortasına yoğurt koyarak servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Zencefil acılığı kişiden kişiye değişir; önce az koyup tadına bakın."], serving: "Yoğurt ve kavrulmuş kabak çekirdeğiyle servis edin.", storage: "Buzdolabında 3 gün, dondurucuda 2 ay saklanır."),
  GeneralRecipe(id: "p39a16_011", title: "Tatlı patatesli mercimek çorbası", category: "Çorbalar", ingredients: ["1 orta boy tatlı patates (küp)", "Yarım su bardağı kırmızı mercimek", "1 küçük kuru soğan", "1 havuç", "1 yemek kaşığı zeytinyağı", "5 su bardağı sıcak su", "1 çay kaşığı tuz", "Yarım çay kaşığı köri veya zerdeçal", "Yarım limon"], steps: ["Mercimeği yıkayıp süzün.", "Tencerede zeytinyağıyla soğan ve havucu 4 dakika kavurun; köriyi ekleyip 30 saniye çevirin.", "Tatlı patates ve mercimeği ekleyin, sıcak suyu ilave edin.", "Kaynayınca köpüğünü alıp kısık ateşte 25 dakika pişirin.", "Blenderdan geçirip tuzunu ayarlayın.", "Limon sıkarak servis edin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", tips: ["Tatlı patates çorbaya doğal tatlılık verir; tuzu sonradan ayarlayın."], serving: "Kavrulmuş susam ve limonla servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_012", title: "Pazılı bulgur çorbası", category: "Çorbalar", ingredients: ["1 demet pazı (yaklaşık 300 g, ince doğranmış)", "3 yemek kaşığı ince bulgur", "2 yemek kaşığı kırmızı mercimek", "1 küçük kuru soğan", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı biber salçası", "5 su bardağı sıcak su", "1 çay kaşığı tuz", "1 çay kaşığı kuru nane", "Yarım limon"], steps: ["Pazının saplarını ince, yapraklarını şerit hâlinde doğrayıp yıkayın.", "Tencerede zeytinyağıyla soğanı 3 dakika kavurun, salçayı ekleyip 1 dakika daha çevirin.", "Pazı saplarını ekleyip 3 dakika soteleyin.", "Bulgur, mercimek ve sıcak suyu ekleyin; kaynayınca 15 dakika pişirin.", "Pazı yapraklarını ekleyip 5 dakika daha pişirin; tuzunu ve naneyi ekleyin.", "Limon sıkarak sıcak servis edin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Pazının sapları yapraklarından geç piştiği için önce saplarını pişirin."], serving: "Limon ve pul biberle sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_014", title: "Zeytinyağlı havuçlu pırasa", category: "Sebze yemekleri", ingredients: ["4 pırasa (3 cm doğranmış)", "2 havuç (halka)", "2 yemek kaşığı pirinç (yıkanmış)", "1 kuru soğan", "4 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "1 çay kaşığı şeker", "1 çay kaşığı tuz", "Yarım limonun suyu"], steps: ["Pırasaları bol suda yıkayıp katmanlarındaki toprağı temizleyin.", "Tencerede zeytinyağıyla soğanı 3 dakika kavurun, havucu ekleyip 3 dakika daha çevirin.", "Pırasaları ekleyip 5 dakika kavurun.", "Pirinç, şeker, tuz ve sıcak suyu ekleyin; kapağı kapalı kısık ateşte 25 dakika pişirin.", "Limon suyunu ekleyip ocağı kapatın.", "Tencerede oda sıcaklığına kadar soğutup servis edin."], minutes: 50, servings: 4, prepMinutes: 15, cookMinutes: 35, difficulty: "Kolay", tips: ["Zeytinyağlılar tencerede soğutulursa sebzeler kararmaz ve şeklini korur."], serving: "Soğuk olarak limon dilimiyle servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_015", title: "Yeşil mercimekli patlıcan yemeği", category: "Sebze yemekleri", ingredients: ["2 patlıcan (küp)", "1 su bardağı haşlanmış yeşil mercimek", "1 kuru soğan", "2 yeşil biber", "2 domates (rendelenmiş)", "1 tatlı kaşığı biber salçası", "3 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "1 çay kaşığı tuz", "Yarım çay kaşığı pul biber"], steps: ["Patlıcanları tuzlu suda 15 dakika bekletip süzün ve kurulayın.", "Tavada 2 yemek kaşığı zeytinyağıyla patlıcanları orta ateşte 8 dakika, her yüzü hafif kızarana kadar soteleyin.", "Tencerede kalan yağla soğan ve biberi 4 dakika kavurun, salçayı ekleyip 1 dakika çevirin.", "Domatesi ekleyip 3 dakika pişirin; mercimek, patlıcan, tuz, pul biber ve sıcak suyu ilave edin.", "Kapağı kapalı kısık ateşte 15 dakika pişirin.", "Ilıdıktan sonra servis edin."], minutes: 50, servings: 4, prepMinutes: 20, cookMinutes: 30, difficulty: "Kolay", tips: ["Patlıcanı önceden sotelemek pişerken dağılmasını önler."], serving: "Bulgur pilavı ve yoğurtla servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_016", title: "Bezelyeli karnabahar yemeği", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar (çiçeklerine ayrılmış)", "1 su bardağı bezelye", "1 kuru soğan", "1 havuç (küp)", "1 tatlı kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Tencerede zeytinyağıyla soğanı 3 dakika kavurun.", "Havucu ve salçayı ekleyip 2 dakika çevirin.", "Karnabahar ve bezelyeyi ekleyin, 2 dakika karıştırın.", "Sıcak su, tuz ve karabiberi ilave edin; kapağı kapalı kısık ateşte 18 dakika pişirin.", "Karnabaharlar çatalla kolayca delinince ocaktan alın.", "Ilık servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Karnabaharı fazla pişirmeyin; dağılıp lapa olur."], serving: "Yoğurt ve pilavla servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_017", title: "Zeytinyağlı bamya", category: "Sebze yemekleri", ingredients: ["500 g taze bamya", "1 kuru soğan", "3 domates (rendelenmiş)", "4 yemek kaşığı zeytinyağı", "1 limonun suyu", "1 su bardağı sıcak su", "1 çay kaşığı şeker", "1 çay kaşığı tuz"], steps: ["Bamyaların şapkalarını konik şekilde, iç kısmı açılmadan kalemtıraş gibi açın.", "Bamyaları geniş bir kapta limon suyu ve tuzla harmanlayıp 15 dakika bekletin, ardından yıkayıp süzün.", "Tencerede zeytinyağıyla soğanı 3 dakika kavurun, domatesi ekleyip 4 dakika pişirin.", "Bamyaları ekleyin; şeker ve sıcak suyu ilave edin, bamyalar dağılmasın diye karıştırmadan tencereyi sallayın.", "Kapağı kapalı kısık ateşte 25 dakika pişirin.", "Tencerede soğutup servis edin."], minutes: 50, servings: 4, prepMinutes: 20, cookMinutes: 30, difficulty: "Orta", tips: ["Limonlu suda bekletmek bamyanın salyalanmasını azaltır.", "Bamyayı kaşıkla karıştırmayın; tencereyi sallayın."], serving: "Soğuk veya ılık, limonla servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_018", title: "Patatesli taze fasulye", category: "Sebze yemekleri", ingredients: ["500 g taze fasulye (ayıklanıp ikiye bölünmüş)", "2 patates (iri küp)", "1 kuru soğan", "2 domates (rendelenmiş)", "1 tatlı kaşığı domates salçası", "4 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "1 çay kaşığı şeker", "1 çay kaşığı tuz"], steps: ["Fasulyelerin uç ve kılçıklarını ayıklayıp yıkayın.", "Tencerede zeytinyağıyla soğanı 4 dakika kavurun, salçayı ekleyip 1 dakika çevirin.", "Fasulyeleri ekleyip kapağı kapalı 10 dakika kendi suyunda pişirin.", "Domates, patates, şeker, tuz ve sıcak suyu ekleyin.", "Kapağı kapalı kısık ateşte 25–30 dakika, fasulye ve patates yumuşayana kadar pişirin.", "Tencerede ılıtıp servis edin."], minutes: 55, servings: 4, prepMinutes: 15, cookMinutes: 40, difficulty: "Kolay", tips: ["Fasulyeyi önce kendi suyunda pişirmek rengini ve aromasını korur."], serving: "Ilık veya soğuk, yoğurt ve ekmekle servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_020", title: "Barbunyalı pazı yemeği", category: "Sebze yemekleri", ingredients: ["1 demet pazı (yaklaşık 400 g)", "1 su bardağı haşlanmış barbunya", "1 kuru soğan", "2 yemek kaşığı pirinç", "1 tatlı kaşığı biber salçası", "3 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "1 çay kaşığı tuz", "Yarım limon"], steps: ["Pazının saplarını ince, yapraklarını iri doğrayıp yıkayın.", "Tencerede zeytinyağıyla soğan ve pazı saplarını 5 dakika kavurun.", "Salçayı ekleyip 1 dakika çevirin, pirinci ekleyin.", "Barbunya, pazı yaprakları, tuz ve sıcak suyu ilave edin.", "Kapağı kapalı kısık ateşte 18 dakika, pirinç pişene kadar pişirin.", "Limon sıkarak ılık servis edin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Pazının saplarını atmayın; önce pişirerek yemeğe lezzet katın."], serving: "Yoğurtla ılık servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_021", title: "Portakallı zeytinyağlı kereviz", category: "Sebze yemekleri", ingredients: ["2 orta boy kereviz kökü", "1 havuç (küp)", "1 küçük patates (küp)", "1 kuru soğan", "2 portakalın suyu", "1 limonun suyu", "4 yemek kaşığı zeytinyağı", "Yarım su bardağı su", "1 çay kaşığı şeker", "1 çay kaşığı tuz", "Yarım demet dereotu"], steps: ["Kerevizleri soyup 1,5 cm kalınlığında dilimleyin ve kararmaması için limonlu suda bekletin.", "Tencerede zeytinyağıyla soğanı 3 dakika kavurun.", "Havuç ve patatesi ekleyip 3 dakika çevirin.", "Kereviz dilimlerini tencereye dizin; portakal suyu, su, şeker ve tuzu ekleyin.", "Kapağı kapalı kısık ateşte 25–30 dakika, kerevizler yumuşayana kadar pişirin.", "Tencerede soğutup üzerine dereotu serperek servis edin."], minutes: 50, servings: 4, prepMinutes: 20, cookMinutes: 30, difficulty: "Orta", tips: ["Portakal kabuğundan biraz rendelemek aromayı güçlendirir."], serving: "Soğuk olarak, dereotuyla servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_022", title: "Havuçlu Brüksel lahanası", category: "Sebze yemekleri", ingredients: ["400 g Brüksel lahanası (ikiye kesilmiş)", "2 havuç (halka)", "1 kuru soğan", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı domates salçası", "Yarım su bardağı sıcak su", "1 çay kaşığı tuz", "Yarım limonun suyu"], steps: ["Brüksel lahanalarının sarı dış yapraklarını ayıklayıp yıkayın ve ikiye kesin.", "Kaynar tuzlu suda 5 dakika haşlayıp süzün; acılığı azalır.", "Tencerede zeytinyağıyla soğanı 3 dakika kavurun, salçayı ekleyip 1 dakika çevirin.", "Havuçları ekleyip 4 dakika soteleyin.", "Brüksel lahanası ve sıcak suyu ekleyin; kapağı kapalı 10 dakika pişirin.", "Tuz ve limon suyunu ekleyip ılık servis edin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Kısa haşlamak Brüksel lahanasının acımsı tadını yumuşatır."], serving: "Yoğurtla ılık servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_023", title: "Mantarlı kabak sote", category: "Sebze yemekleri", ingredients: ["300 g kültür mantarı (dilim)", "2 kabak (yarım ay)", "1 kuru soğan", "1 kırmızı kapya biber", "2 yemek kaşığı zeytinyağı", "1 diş sarımsak", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "1 çay kaşığı kekik"], steps: ["Geniş tavada zeytinyağını yüksek ateşte ısıtın, mantarları 5 dakika suyunu çekene kadar soteleyin.", "Soğan ve biberi ekleyip 3 dakika çevirin.", "Kabakları ve sarımsağı ekleyin.", "5 dakika, kabaklar diri kalacak şekilde soteleyin.", "Tuz, karabiber ve kekikle tatlandırın.", "Hemen servis edin."], minutes: 25, servings: 3, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Tuzu en sonda ekleyin; erken eklenirse sebzeler su salar."], serving: "Pilav veya makarna yanında sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_024", title: "Zeytinyağlı bezelyeli enginar", category: "Sebze yemekleri", ingredients: ["6 enginar çanağı", "1 su bardağı bezelye", "1 havuç (küp)", "1 küçük patates (küp)", "1 kuru soğan", "5 yemek kaşığı zeytinyağı", "1 limonun suyu", "1 tatlı kaşığı un", "1 su bardağı sıcak su", "1 çay kaşığı şeker", "1 çay kaşığı tuz", "Yarım demet dereotu"], steps: ["Enginar çanaklarını limonlu ve unlu suda bekleterek kararmalarını önleyin.", "Tencerede zeytinyağıyla soğanı 3 dakika kavurun; havuç, patates ve bezelyeyi ekleyip 3 dakika çevirin.", "Enginarları tencereye dizin, sebzeli karışımı çanakların içine ve aralarına paylaştırın.", "Sıcak su, limon suyunun yarısı, şeker ve tuzu ekleyin.", "Üzerine yağlı kâğıt kapatıp kapağı kapalı kısık ateşte 30 dakika pişirin.", "Tencerede soğutup kalan limon suyu ve dereotuyla servis edin."], minutes: 50, servings: 4, prepMinutes: 20, cookMinutes: 30, difficulty: "Orta", tips: ["Enginarın üzerine yağlı kâğıt kapatmak eşit pişmesini ve rengini korumasını sağlar."], serving: "Soğuk olarak, dereotu ve limonla servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_025", title: "Roka ve armut salatası", category: "Salatalar", ingredients: ["1 demet roka", "2 armut", "Yarım su bardağı ceviz", "80 g beyaz peynir veya keçi peyniri", "3 yemek kaşığı zeytinyağı", "1 yemek kaşığı bal", "1 yemek kaşığı balzamik sirke", "1 tatlı kaşığı tuz"], steps: ["Rokayı yıkayıp kurulayın.", "Armutları ince dilimleyin.", "Cevizi kuru tavada 2 dakika kavurun.", "Zeytinyağı, bal, sirke ve tuzu çırpın.", "Roka, armut, ceviz ve ufalanmış peyniri sosla harmanlayın."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Armudu son anda dilimleyin; kararmaz."], serving: "Soğuk servis edin.", storage: "Sossuz hâli buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "p39a16_026", title: "Pancar ve portakal salatası", category: "Salatalar", ingredients: ["3 haşlanmış pancar", "2 portakal", "1 küçük kırmızı soğan", "4–5 dal nane", "3 yemek kaşığı zeytinyağı", "1 yemek kaşığı nar ekşisi", "1 tatlı kaşığı tuz"], steps: ["Pancarı çiğse kabuğuyla 40 dakika haşlayıp soyun; dilimleyin.", "Portakalları kabuğundan ve beyaz zarından ayırıp dilimleyin.", "Soğanı ince halka doğrayın.", "Zeytinyağı, nar ekşisi ve tuzu çırpın.", "Tabağa dizip sosu ve naneyi ekleyin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Pancar suyu ellerinizi boyar; eldiven kullanın."], serving: "Soğuk servis edin.", storage: "Sossuz hâli buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "p39a16_027", title: "Bulgur ve nar salatası", category: "Salatalar", ingredients: ["1 su bardağı ince bulgur", "1 su bardağı sıcak su", "1 nar", "4 dal taze soğan", "Yarım demet maydanoz ve nane", "2 yemek kaşığı nar ekşisi", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, pul biber"], steps: ["Bulguru sıcak suyla ıslatıp üzeri kapalı 15 dakika şişirin.", "Narı taneleyin.", "Yeşillikleri ve taze soğanı ince doğrayın.", "Bulguru nar ekşisi, zeytinyağı, tuz ve pul biberle yoğurun.", "Yeşillik ve nar tanelerini ekleyip karıştırın."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Bulgur soğuyunca yeşillikleri ekleyin; solmaz."], serving: "Soğuk servis edin.", storage: "Sossuz hâli buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "p39a16_028", title: "Kinoalı avokado salatası", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı kinoa", "2 su bardağı su", "1 avokado", "1 su bardağı çeri domates", "1 salatalık", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "1 limon suyu", "1 tatlı kaşığı tuz"], steps: ["Kinoayı ince süzgeçte yıkayın; suyla 15 dakika pişirip soğutun.", "Avokado ve salatalığı küp, domatesleri ikiye kesin.", "Zeytinyağı, limon ve tuzu çırpın.", "Malzemeleri sosla harmanlayın.", "Hemen servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Kinoayı yıkamak acımsı tadı giderir."], serving: "Ana öğün salatası olarak.", storage: "Avokadosuz hâli 2 gün."),
  GeneralRecipe(id: "p39a16_029", title: "Nohut ve salatalık salatası", category: "Salatalar", ingredients: ["2 su bardağı haşlanmış nohut", "2 salatalık", "1 kırmızı biber", "Yarım kırmızı soğan", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "1 limon suyu", "1 tatlı kaşığı kimyon, tuz"], steps: ["Nohutları süzün.", "Salatalık ve biberi küp doğrayın.", "Soğanı ince kıyın.", "Zeytinyağı, limon, kimyon ve tuzla sos hazırlayın.", "Hepsini harmanlayıp 10 dakika dinlendirin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Kimyon nohudun sindirimini kolaylaştırır."], serving: "Soğuk servis edin.", storage: "Sossuz hâli buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "p39a16_030", title: "Yeşil mercimekli köz biber salatası", category: "Salatalar", ingredients: ["1 su bardağı yeşil mercimek", "3 köz kırmızı biber", "Yarım demet maydanoz", "2 dal taze soğan", "2 yemek kaşığı nar ekşisi", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, 1 çay kaşığı kimyon"], steps: ["Mercimeği 20 dakika diri kalacak şekilde haşlayıp süzün.", "Köz biberlerin kabuğunu soyup şerit doğrayın.", "Yeşillikleri kıyın.", "Sos malzemelerini çırpın.", "Hepsini karıştırıp servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Biberleri sıcakken poşete koyarsanız kabuğu kolay soyulur."], serving: "Soğuk servis edin.", storage: "Sossuz hâli buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "p39a16_031", title: "Semizotu ve çilek salatası", category: "Salatalar", ingredients: ["1 demet semizotu", "1 su bardağı çilek", "Yarım su bardağı lor", "2 yemek kaşığı ceviz", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "1 tatlı kaşığı bal", "1 tatlı kaşığı tuz"], steps: ["Semizotunun kalın saplarını ayıklayıp yıkayın.", "Çilekleri dörde bölün.", "Zeytinyağı, limon, bal ve tuzu çırpın.", "Semizotu ve çileği sosla harmanlayın.", "Lor ve cevizi üzerine serpin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Semizotunu iyice kurulayın; sos tutunur."], serving: "Soğuk servis edin.", storage: "Sossuz hâli buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "p39a16_032", title: "Karabuğdaylı domates salatası", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı karabuğday", "2 su bardağı su", "3 domates", "1 kırmızı soğan", "Yarım demet nane ve maydanoz", "2 yemek kaşığı nar ekşisi", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, 1 çay kaşığı pul biber"], steps: ["Karabuğdayı yıkayıp suyla 12–15 dakika, diri kalacak şekilde pişirip süzün ve soğutun.", "Domates ve soğanı küçük doğrayın.", "Yeşillikleri kıyın.", "Nar ekşisi, zeytinyağı, tuz ve pul biberle sos hazırlayın.", "Hepsini karıştırıp servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Fazla pişen karabuğday yapışır; diri bırakın."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a16_033", title: "Beyaz fasulye ve dereotu salatası", category: "Salatalar", ingredients: ["2 su bardağı haşlanmış kuru fasulye", "1 kırmızı soğan", "Yarım demet dereotu", "1 domates", "3 yemek kaşığı zeytinyağı", "2 yemek kaşığı limon suyu", "1 haşlanmış yumurta", "1 tatlı kaşığı tuz, 1 tatlı kaşığı sumak"], steps: ["Fasulyeyi süzün.", "Soğanı piyazlık doğrayıp sumak ve tuzla ovun.", "Domates ve dereotunu doğrayın.", "Zeytinyağı ve limonla sos hazırlayıp malzemeleri karıştırın.", "Üzerine dilimlenmiş yumurta koyun."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Sumakla ovulan soğanın acılığı azalır."], serving: "Soğuk servis edin.", storage: "Sossuz hâli buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "p39a16_034", title: "Kuskuslu mısır salatası", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "1 su bardağı kaynar su", "1 su bardağı haşlanmış mısır", "1 kırmızı biber, 1 salatalık (küp)", "Yarım demet maydanoz ve nane", "3 yemek kaşığı zeytinyağı", "2 yemek kaşığı limon suyu", "1 tatlı kaşığı tuz", "1 çay kaşığı kimyon"], steps: ["Kuskusu kaseye alın, tuz ve 1 yemek kaşığı zeytinyağı ekleyip kaynar suyu dökün; üzerini kapatıp 5 dakika bekletin.", "Çatalla taneleri ayırıp soğutun.", "Sebzeleri küçük küp, yeşillikleri ince doğrayın.", "Zeytinyağı, limon suyu ve kimyonu çırpın.", "Hepsini karıştırıp 15 dakika buzdolabında bekletin."], minutes: 20, servings: 4, prepMinutes: 15, cookMinutes: 5, difficulty: "Kolay", tips: ["Kuskus sıcakken sos eklenirse lapalaşır; soğumasını bekleyin."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a16_035", title: "Mor lahana ve elma salatası", category: "Salatalar", ingredients: ["Yarım küçük mor lahana", "1 yeşil elma", "1 havuç", "3 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "1 tatlı kaşığı tuz", "2 yemek kaşığı ceviz"], steps: ["Lahanayı çok ince doğrayıp tuzla ovun, 10 dakika bekletip suyunu sıkın.", "Elma ve havucu jülyen doğrayın.", "Yoğurt, zeytinyağı ve limonu çırpın.", "Hepsini harmanlayın.", "Cevizle süsleyin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Tuzla ovmak lahanayı yumuşatır."], serving: "Soğuk servis edin.", storage: "Sossuz hâli buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "p39a16_036", title: "Brokoli ve ceviz salatası", category: "Salatalar", ingredients: ["1 brokoli", "Yarım su bardağı ceviz", "2 yemek kaşığı kuru üzüm", "1 küçük kırmızı soğan", "3 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "1 tatlı kaşığı tuz"], steps: ["Brokoliyi küçük çiçeklere ayırıp 3 dakika haşlayın ve soğuk suya alın.", "Soğanı ince doğrayın.", "Yoğurt, zeytinyağı, limon ve tuzla sos hazırlayın.", "Brokoli, üzüm ve soğanı sosla karıştırın.", "Cevizi ekleyip servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Soğuk suya almak brokolinin rengini korur."], serving: "Soğuk servis edin.", storage: "Sossuz hâli buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "p39a16_049", title: "Mantarlı karabuğday pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı karabuğday", "250 g mantar", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı tereyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz, karabiber"], steps: ["Karabuğdayı yıkayıp süzün.", "Soğanı ve dilimlenmiş mantarı yağda suyunu çekene kadar 8 dakika soteleyin.", "Karabuğdayı ekleyip 2 dakika kavurun.", "Sıcak su ve tuzu ekleyip kısık ateşte 15 dakika pişirin.", "Tereyağını ekleyip 10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Karabuğday glutensizdir."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_050", title: "Nohutlu esmer pirinç pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı esmer pirinç", "1 su bardağı haşlanmış nohut", "2 yemek kaşığı tereyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Esmer pirinci 1 saat ılık suda bekletip süzün.", "Tereyağında pirinci 3 dakika kavurun.", "Nohut, sıcak su ve tuzu ekleyin.", "Kaynayınca kısık ateşte kapağı kapalı 35 dakika pişirin.", "10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Esmer pirinç beyazdan uzun pişer; ıslatmak süreyi kısaltır."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_051", title: "Biberli bulgur pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı pilavlık bulgur", "2 sivri biber, 1 kırmızı biber", "1 soğan", "1 yemek kaşığı biber salçası", "2 yemek kaşığı zeytinyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Soğan ve biberleri yağda 5 dakika kavurun.", "Salçayı ekleyip 1 dakika çevirin.", "Bulguru ekleyip 2 dakika kavurun.", "Su ve tuzu ekleyip 15 dakika pişirin.", "10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Bulguru yıkamayın; pilav lapa olur."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_052", title: "Bezelyeli pirinç pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı baldo pirinç", "1 su bardağı bezelye", "2 yemek kaşığı tereyağı", "1 yemek kaşığı sıvı yağ", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Pirinci 20 dakika sıcak tuzlu suda bekletip nişastası gidene kadar yıkayın.", "Yağlarda pirinci 4 dakika kavurun.", "Bezelye, su ve tuzu ekleyin.", "Kısık ateşte 15 dakika pişirin.", "15 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Pirinci iyice yıkamak tane tane pilav verir."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_053", title: "Domatesli kinoa pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı kinoa", "2 domates (rendelenmiş)", "1 soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su", "1 tatlı kaşığı tuz, 1 çay kaşığı kekik"], steps: ["Kinoayı ince süzgeçte iyice yıkayın.", "Soğanı yağda kavurun, domatesi ekleyip 5 dakika pişirin.", "Kinoayı ekleyip 1 dakika çevirin.", "Su, tuz ve kekiği ekleyip 15 dakika pişirin.", "5 dakika demlendirip çatalla kabartın."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Kinoa piştiğinde taneler etrafında beyaz halka görünür."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_054", title: "Havuçlu arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı arpa şehriye", "1 havuç (rendelenmiş)", "2 yemek kaşığı tereyağı", "2,5 su bardağı sıcak tavuk suyu veya su", "1 tatlı kaşığı tuz"], steps: ["Tereyağında şehriyeyi pembeleşene kadar 4 dakika kavurun.", "Havucu ekleyip 2 dakika çevirin.", "Sıcak su ve tuzu ekleyin.", "Kısık ateşte 12 dakika pişirin.", "10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Şehriyeyi kavururken sürekli karıştırın; çabuk yanar."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_055", title: "Ispanaklı bulgur pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı bulgur", "300 g ıspanak", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz, 1 çay kaşığı pul biber"], steps: ["Soğanı yağda kavurup salçayı ekleyin.", "Bulguru ekleyip 2 dakika çevirin.", "Su ve tuzu ekleyip 10 dakika pişirin.", "Doğranmış ıspanağı üstüne yayıp kapağı kapatın, 5 dakika daha pişirin.", "Karıştırıp 10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Ispanak son 5 dakikada eklenince rengini korur."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_056", title: "Mısırlı kuskus pilavı", category: "Dünya mutfağı", ingredients: ["1,5 su bardağı kuskus", "1 su bardağı mısır", "1 küçük soğan", "1 havuç (küp)", "2 yemek kaşığı tereyağı", "1,5 su bardağı sıcak tavuk suyu veya su", "1 tatlı kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Tereyağında soğanı 3 dakika, havucu 4 dakika soteleyin.", "Mısırı ekleyip 2 dakika çevirin.", "Kuskusu ekleyip 1 dakika kavurun.", "Sıcak su, tuz ve karabiberi ekleyin, ocağı kapatıp kapağı kapalı 10 dakika demlendirin.", "Çatalla kabartıp servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Kuskus pişirilmez, demlenir; ocağı kapatmayı unutmayın."], serving: "Tavuk veya köfte yanında sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a16_057", title: "Patlıcanlı bulgur pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı bulgur", "2 patlıcan", "1 soğan", "2 domates", "3 yemek kaşığı zeytinyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Patlıcanları küp doğrayıp tuzlu suda 15 dakika bekletin, kurulayın.", "Patlıcanları 2 yemek kaşığı yağda kızartıp alın.", "Kalan yağda soğan ve domatesi pişirin, bulguru ekleyin.", "Su ve tuzu ekleyip 12 dakika pişirin, patlıcanı ekleyin.", "10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Patlıcanı tuzlu suda bekletmek acılığı ve yağ çekmesini azaltır."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_058", title: "Mercimekli karabuğday pilavı", category: "Pilavlar", ingredients: ["1 su bardağı karabuğday", "Yarım su bardağı yeşil mercimek", "1 soğan", "2 yemek kaşığı zeytinyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz, 1 çay kaşığı kimyon"], steps: ["Mercimeği 15 dakika ön haşlayıp süzün.", "Soğanı yağda kavurun.", "Karabuğday ve mercimeği ekleyip 2 dakika çevirin.", "Su, tuz ve kimyonu ekleyip 15 dakika pişirin.", "10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Bitkisel protein açısından zengin bir pilavdır."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_059", title: "Kabaklı pirinç pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı pirinç", "1 kabak (küp)", "2 yemek kaşığı tereyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz", "Yarım demet dereotu"], steps: ["Pirinci ıslatıp yıkayın.", "Tereyağında kabağı 3 dakika soteleyin.", "Pirinci ekleyip 3 dakika kavurun.", "Su ve tuzla 15 dakika pişirin.", "Dereotunu ekleyip demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Kabağı fazla pişirmeyin; dağılır."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_060", title: "Pırasalı bulgur pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı bulgur", "2 pırasa", "1 havuç", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı biber salçası", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Pırasayı ince halka, havucu küp doğrayın.", "Yağda 6 dakika soteleyin, salçayı ekleyin.", "Bulguru ekleyip 2 dakika kavurun.", "Su ve tuzla 15 dakika pişirin.", "10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Pırasanın arasındaki toprağı bol suda yıkayın."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a16_061", title: "Mantarlı tavuk sote", category: "Tavuk yemekleri", ingredients: ["400 g tavuk göğsü (kuşbaşı doğranmış)", "250 g kültür mantarı (dilimlenmiş)", "1 kuru soğan (piyaz)", "1 yeşil biber (halka)", "1 domates (küp)", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı biber salçası", "Yarım çay bardağı sıcak su", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "1 çay kaşığı kekik"], steps: ["Geniş bir tavada 1 yemek kaşığı zeytinyağını yüksek ateşte ısıtın; tavukları ekleyip suyunu salıp tekrar çekene ve hafif kızarana kadar 6–7 dakika soteleyin, tabağa alın.", "Aynı tavaya kalan yağı ekleyip mantarları yüksek ateşte 5 dakika, suyunu çekip kızarana kadar pişirin.", "Soğan ve biberi ekleyip 3 dakika daha soteleyin.", "Salçayı ekleyip 1 dakika kavurun, domatesi ve sıcak suyu ilave edin.", "Tavukları tavaya geri alın; tuz, karabiber ve kekikle tatlandırıp kısık ateşte 5 dakika pişirin.", "Tavuğun içinin pembe kalmadığından emin olup sıcak servis edin."], minutes: 30, servings: 3, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Tavuğu ve mantarı ayrı pişirmek ikisinin de kızarmasını sağlar; birlikte koyarsanız haşlanırlar."], serving: "Pirinç pilavı veya bulgur pilavı ile servis edin.", storage: "Buzdolabında kapalı kapta 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_063", title: "Köri soslu tavuk sote", category: "Dünya mutfağı", ingredients: ["600 g tavuk göğsü (küp)", "1 soğan", "2 diş sarımsak", "1 tatlı kaşığı rendelenmiş zencefil", "1 yemek kaşığı köri", "1 kırmızı biber", "1 su bardağı hindistan cevizi sütü veya krema", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz"], steps: ["Tavuğu tuz ve köriyle harmanlayın.", "Yağda tavuğu yüksek ateşte 6–7 dakika mühürleyip çıkarın.", "Aynı tavada soğan, sarımsak, zencefil ve biberi 5 dakika soteleyin.", "Tavuğu geri ekleyin, hindistan cevizi sütünü dökün.", "Kısık ateşte 10 dakika, sos koyulaşıp tavuğun içi pişene kadar pişirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Orta", tips: ["Köriyi yağda 30 saniye kavurmak aromasını açar."], serving: "Basmati pilavıyla sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a16_066", title: "Brokolili kremalı tavuk", category: "Tavuk yemekleri", ingredients: ["450 g tavuk göğsü (şerit)", "300 g brokoli (küçük çiçekler)", "1 küçük soğan", "2 diş sarımsak", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı un", "1,5 su bardağı süt", "2 yemek kaşığı rendelenmiş kaşar", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Brokoliyi kaynar tuzlu suda 3 dakika haşlayıp soğuk suya alın ve süzün.", "Tavada zeytinyağıyla tavukları yüksek ateşte 6 dakika soteleyin, tabağa alın.", "Aynı tavada tereyağını eritin; soğan ve sarımsağı 3 dakika kavurun.", "Unu ekleyip 1 dakika kavurun, sütü çırparak azar azar ilave edin ve koyulaşana kadar 3 dakika karıştırın.", "Tavuk ve brokoliyi sosa ekleyin; tuz ve karabiberle tatlandırıp 3 dakika pişirin.", "Kaşarı ekleyip eriyince ocaktan alın ve servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Brokoliyi önceden kısa haşlamak rengini canlı tutar."], serving: "Makarna veya pirinç pilavı ile sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır; ısıtırken biraz süt ekleyin."),
  GeneralRecipe(id: "p39a16_067", title: "Limonlu pırasalı tavuk", category: "Tavuk yemekleri", ingredients: ["450 g tavuk göğsü (kuşbaşı)", "2 pırasa (halka)", "1 havuç (halka)", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "1 limonun suyu", "1 tatlı kaşığı un", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "Yarım demet dereotu"], steps: ["Pırasaları yıkayıp toprağını iyice temizleyin.", "Tencerede zeytinyağıyla tavukları 6 dakika soteleyin.", "Pırasa ve havucu ekleyip 5 dakika çevirin.", "Sıcak suyu, tuz ve karabiberi ekleyin; kapağı kapalı kısık ateşte 12 dakika pişirin.", "Limon suyunu unla pürüzsüz olana kadar çırpıp yemeğe ekleyin ve 2 dakika kaynatarak sosu bağlayın.", "Kıyılmış dereotunu serpip servis edin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Limonlu un karışımı sosu hafifçe koyulaştırır ve terbiye etkisi verir."], serving: "Pirinç pilavı ve yoğurtla servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_069", title: "Domatesli fesleğenli tavuk", category: "Tavuk yemekleri", ingredients: ["4 parça kemiksiz tavuk but (yaklaşık 500 g)", "4 olgun domates (rendelenmiş) veya 400 g konserve domates", "2 diş sarımsak", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "1 avuç taze fesleğen (veya 1 çay kaşığı kuru)", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber", "1 tutam şeker"], steps: ["Tavuk butlarını tuz ve karabiberle ovun.", "Geniş tavada zeytinyağını ısıtıp butları her iki yüzü altın rengi olana kadar toplam 8 dakika pişirin, tabağa alın.", "Aynı tavada soğan ve sarımsağı 3 dakika kavurun.", "Domatesi, şekeri ve fesleğenin yarısını ekleyip 5 dakika pişirin.", "Tavukları sosa yerleştirin, kapağı kapalı kısık ateşte 12 dakika, tavuğun iç sıcaklığı 74 °C olana kadar pişirin.", "Kalan taze fesleğeni üzerine serpip servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["But göğse göre daha sulu kalır; göğüs kullanırsanız süreyi 3–4 dakika kısaltın."], serving: "Makarna, patates püresi veya bulgur ile servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_071", title: "Zencefilli havuçlu tavuk", category: "Tavuk yemekleri", ingredients: ["400 g tavuk göğsü (ince şerit)", "2 havuç (jülyen)", "1 kırmızı kapya biber (şerit)", "3 dal taze soğan", "1 tatlı kaşığı rendelenmiş taze zencefil", "2 diş sarımsak", "2 yemek kaşığı soya sosu", "1 tatlı kaşığı bal", "1 tatlı kaşığı nişasta", "2 yemek kaşığı ayçiçek yağı", "1 yemek kaşığı susam"], steps: ["Soya sosu, bal, nişasta ve 3 yemek kaşığı suyu bir kâsede çırparak sosu hazırlayın.", "Geniş tava veya wokta yağı çok yüksek ateşte ısıtın; tavukları 5 dakika sürekli çevirerek pişirin, tabağa alın.", "Aynı tavada havuç ve biberi 3 dakika diri kalacak şekilde soteleyin.", "Zencefil, sarımsak ve taze soğanın beyaz kısımlarını ekleyip 1 dakika çevirin.", "Tavukları geri ekleyin, sosu döküp 1–2 dakika parlak ve koyu kıvama gelene kadar karıştırın.", "Taze soğanın yeşil kısımları ve susamla servis edin."], minutes: 30, servings: 3, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Wok yemeklerinde tüm malzemeleri önceden hazırlayın; pişirme çok hızlıdır."], serving: "Sade pirinç pilavı ile servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_073", title: "Limonlu dereotlu fırın levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 levrek fileto (toplam yaklaşık 350 g)", "Yarım demet dereotu", "2 yemek kaşığı zeytinyağı", "1 limon", "1 diş sarımsak (rendelenmiş)", "1 çay kaşığı kekik", "Yarım çay kaşığı tuz", "Çeyrek çay kaşığı karabiber", "1 yemek kaşığı tereyağı"], steps: ["Fırını 200 °C'ye ısıtın, küçük bir fırın kabını hafifçe yağlayın.", "Dereotunun yarısını ince kıyın; zeytinyağı, sarımsak, kekik, limon kabuğu rendesi, tuz ve karabiberle karıştırın.", "Filetoları kurulayıp derisi alta gelecek şekilde kaba yerleştirin ve dereotlu karışımı üzerlerine sürün.", "Her filetonun üzerine ince limon dilimleri ve küçük bir parça tereyağı koyun.", "Fırında 12–15 dakika, et opaklaşıp çatalla ayrılana kadar pişirin.", "Kalan taze dereotunu ve kaptaki sosu üzerine gezdirerek servis edin."], minutes: 25, servings: 2, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 200, tips: ["Levrek fileto ince olduğu için 15 dakikayı geçirmeyin.", "Limon dilimleri balığın üstünü nemli tutar."], serving: "Buharda sebze veya pirinç pilavı ile servis edin.", storage: "Aynı gün tüketin; buzdolabında en fazla 1 gün saklayın."),
  GeneralRecipe(id: "p39a16_077", title: "Portakallı rezeneli fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 somon fileto (her biri yaklaşık 150 g)", "1 rezene (ince dilimlenmiş)", "1 portakal (yarısı dilim, yarısının suyu)", "1 küçük kırmızı soğan (ince dilim)", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı bal", "1 çay kaşığı hardal", "Yarım çay kaşığı tuz", "Çeyrek çay kaşığı karabiber"], steps: ["Fırını 200 °C'ye ısıtın.", "Rezene ve soğan dilimlerini 1 yemek kaşığı zeytinyağı ve bir tutam tuzla harmanlayıp fırın kabına yayın; 10 dakika ön pişirin.", "Portakal suyu, bal, hardal, kalan zeytinyağı, tuz ve karabiberi çırpın.", "Somonları rezenelerin üzerine yerleştirin, sosun yarısını üzerlerine sürün ve portakal dilimlerini aralara dizin.", "Fırında 12–15 dakika, somonun iç sıcaklığı 63 °C olana kadar pişirin.", "Kalan sosu servis sırasında üzerine gezdirin."], minutes: 40, servings: 2, prepMinutes: 15, cookMinutes: 25, difficulty: "Orta", ovenCelsius: 200, tips: ["Rezenenin yeşil yapraklarını atmayın; servis sırasında üzerine serpin.", "Hardal tercih edilmiyorsa çıkarılabilir; tat daha tatlı olur."], serving: "Kinoa veya bulgur pilavı ile servis edin.", storage: "Buzdolabında en fazla 1 gün saklayın."),
  GeneralRecipe(id: "p39a16_080", title: "Pırasalı fırın çipura", category: "Balık ve deniz ürünleri", ingredients: ["2 çipura fileto", "2 pırasa (2 cm halka)", "1 havuç (ince halka)", "3 yemek kaşığı zeytinyağı", "1 limon", "1 diş sarımsak", "Yarım su bardağı sıcak su", "1 çay kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Pırasa halkalarını bol suda yıkayıp aralarındaki toprağı temizleyin.", "Tavada 2 yemek kaşığı zeytinyağıyla pırasa, havuç ve sarımsağı 5 dakika soteleyin; sıcak suyu ve yarım çay kaşığı tuzu ekleyip kapağı kapalı 8 dakika pişirin.", "Fırını 190 °C'ye ısıtın; pırasalı karışımı fırın kabına yayın.", "Çipura filetolarını tuz ve karabiberle tatlandırıp pırasaların üzerine yerleştirin, kalan zeytinyağını gezdirin.", "Fırında 15 dakika, balık beyazlaşana kadar pişirin.", "Üzerine limon sıkıp sıcak servis edin."], minutes: 45, servings: 2, prepMinutes: 15, cookMinutes: 30, difficulty: "Orta", ovenCelsius: 190, tips: ["Pırasayı önceden pişirmek, balığın kurumadan pırasanın yumuşamasını sağlar."], serving: "Kabın içindeki pırasalarla birlikte, yanında yoğurtla servis edin.", storage: "Buzdolabında 1 gün saklayın."),
  GeneralRecipe(id: "p39a16_082", title: "Mantarlı kekikli fırın balık", category: "Balık ve deniz ürünleri", ingredients: ["4 levrek veya çipura fileto", "250 g mantar", "1 soğan", "2 domates", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik", "1 limon", "1 tatlı kaşığı tuz"], steps: ["Fırını 200 °C'ye ısıtın.", "Mantarı dilimleyin, soğanı piyazlık, domatesi halka doğrayın.", "Sebzeleri zeytinyağı, kekik ve tuzun yarısıyla harmanlayıp tepsiye yayın, 10 dakika ön pişirin.", "Balıkları sebzelerin üzerine dizin, kalan tuzu ve limon suyunu ekleyin.", "15 dakika, balık opaklaşana kadar pişirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Fileto ince olduğundan fazla pişirmeyin; kurur."], serving: "Roka ve limonla.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "p39a16_086", title: "Armutlu cevizli fırın tatlısı", category: "Tatlılar", ingredients: ["2 armut", "3 yemek kaşığı iri kıyılmış ceviz", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Armutları soyup küp doğrayın; cevizleri iri kıyın.", "Armut ve cevizi karıştırın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin.", "Bıçak ucuyla kontrol edin: kolayca batıyorsa meyve yumuşamıştır.", "Buzdolabında kapalı kapta 2 gün saklayabilirsiniz."], minutes: 40),
  GeneralRecipe(id: "p39a16_090", title: "Balkabaklı cevizli fırın tatlısı", category: "Tatlılar", ingredients: ["300 g balkabağı", "3 yemek kaşığı iri kıyılmış ceviz", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Balkabağını küçük küplere doğrayıp 12 dakika buharda yumuşatın.", "Balkabağı ve cevizi karıştırın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin.", "Bıçak ucuyla kontrol edin: kolayca batıyorsa meyve yumuşamıştır.", "Buzdolabında kapalı kapta 2 gün saklayabilirsiniz."], minutes: 52),
  GeneralRecipe(id: "p39a16_091", title: "Erikli yulaflı fırın tatlısı", category: "Tatlılar", ingredients: ["8 erik", "yarım su bardağı yulaf", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Erikleri çekirdeklerinden ayırıp dörde bölün; yulafla harmanlayın.", "Erikler çok ekşiyse 1 tatlı kaşığı bal ya da pekmez ekleyebilirsiniz.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin.", "Bıçak ucuyla kontrol edin: kolayca batıyorsa meyve yumuşamıştır.", "Buzdolabında kapalı kapta 2 gün saklayabilirsiniz."], minutes: 40),
  GeneralRecipe(id: "p39a16_092", title: "Kayısılı bademli fırın tatlısı", category: "Tatlılar", ingredients: ["8 kayısı", "3 yemek kaşığı file badem", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Kayısıları ikiye bölüp çekirdeklerini çıkarın; bademleri ayırın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Bademlerin yarısını karışıma katın, yarısını kaplara paylaştırdıktan sonra üstüne serpin; fırında hafifçe kavrulur.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin.", "Bıçak ucuyla kontrol edin: kolayca batıyorsa meyve yumuşamıştır.", "Buzdolabında kapalı kapta 2 gün saklayabilirsiniz."], minutes: 40),
  GeneralRecipe(id: "p39a16_094", title: "Vişneli yulaflı fırın tatlısı", category: "Tatlılar", ingredients: ["1 su bardağı çekirdeksiz vişne", "yarım su bardağı yulaf", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Vişnelerin çekirdeklerini çıkarıp yulafla karıştırın.", "Çekirdek kalmadığını elinizle yoklayarak kontrol edin; küçük çocuklar için önemlidir.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin.", "Bıçak ucuyla kontrol edin: kolayca batıyorsa meyve yumuşamıştır.", "Buzdolabında kapalı kapta 2 gün saklayabilirsiniz."], minutes: 40),
  GeneralRecipe(id: "p39a16_096", title: "Hurmalı kakaolu fırın tatlısı", category: "Tatlılar", ingredients: ["6 çekirdeksiz hurma", "1 yemek kaşığı kakao", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın; meyveleri yıkayıp çekirdeklerini çıkarın ve doğrayın.", "Hurmalar sertse 10 dakika ılık suda bekletip yumuşatın.", "Ana malzemeleri süt, yulaf unu ve tarçınla karıştırın.", "Kakaoyu ekleyip topak kalmayana kadar karıştırın.", "Karışımı küçük fırın kaplarına paylaştırın; üzerini düzeltin.", "Yaklaşık 20-30 dakika, üstü hafif kızarıp içi sıcak olana kadar pişirin; ılıtarak servis edin.", "Buzdolabında kapalı kapta 2 gün saklayabilirsiniz."], minutes: 50),
  GeneralRecipe(id: "p39a16_097", title: "Ispanaklı lorlu makarna", category: "Makarnalar", ingredients: ["350 g kalem makarna", "300 g ıspanak", "150 g lor", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber, 1 tutam muskat"], steps: ["Makarnayı tuzlu suda haşlayın, 1 bardak suyunu ayırın.", "Sarımsağı yağda 1 dakika çevirin.", "Ispanağı ekleyip 2 dakika soldurun.", "Lor ve biraz haşlama suyuyla kremamsı sos yapın.", "Makarnayı ekleyip karıştırın."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Muskat ıspanağın tadını açar."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_098", title: "Mantarlı kekikli makarna", category: "Makarnalar", ingredients: ["350 g penne", "300 g mantar", "2 diş sarımsak", "2 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı taze kekik", "Yarım su bardağı krema (isteğe bağlı)", "Yarım su bardağı parmesan", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Makarnayı tuzlu suda haşlayın, 1 bardak suyunu ayırın.", "Tereyağı ve zeytinyağında mantarı yüksek ateşte suyunu salıp çekene kadar 6–7 dakika soteleyin.", "Sarımsak ve kekiği ekleyip 1 dakika çevirin.", "Krema ve biraz haşlama suyu ekleyip makarnayı katın.", "Parmesanla karıştırıp sıcak servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Mantarı kalabalık etmeden pişirin; haşlanmak yerine kızarsın."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a16_099", title: "Domatesli fesleğenli makarna", category: "Makarnalar", ingredients: ["350 g spagetti", "4 olgun domates", "3 diş sarımsak", "4 yemek kaşığı zeytinyağı", "1 demet fesleğen", "1 tatlı kaşığı tuz", "3 yemek kaşığı rendelenmiş parmesan"], steps: ["Domateslerin kabuğunu çizip kaynar suda 30 sn bekletin, soyup doğrayın.", "Sarımsağı yağda 1 dakika çevirin, domatesi ekleyip 10 dakika pişirin.", "Makarnayı haşlayın.", "Makarnayı sosa ekleyin.", "Fesleğen ve parmesanla servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Fesleğeni en son ekleyin; kararmaz."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_100", title: "Kabaklı limonlu makarna", category: "Makarnalar", ingredients: ["350 g penne", "2 kabak", "1 limon (kabuğu ve suyu)", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı", "3 yemek kaşığı rendelenmiş parmesan", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Makarnayı haşlayın.", "Kabağı yarım ay doğrayıp yağda yüksek ateşte 5 dakika soteleyin.", "Sarımsağı ekleyin.", "Makarna, limon kabuğu ve suyunu ekleyin.", "Parmesanla karıştırın."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Limon kabuğu ferah bir aroma verir."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_101", title: "Brokolili sarımsaklı makarna", category: "Makarnalar", ingredients: ["350 g burgu makarna", "1 brokoli", "4 diş sarımsak", "4 yemek kaşığı zeytinyağı", "1 çay kaşığı pul biber", "3 yemek kaşığı rendelenmiş parmesan", "1 tatlı kaşığı tuz"], steps: ["Makarnayı haşlarken son 4 dakikada brokoliyi ekleyin.", "Yağda dilim sarımsak ve pul biberi 1 dakika çevirin.", "Süzülen makarna ve brokoliyi ekleyin.", "Biraz haşlama suyuyla karıştırın.", "Parmesanla servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Sarımsağı yakmayın; acılaşır."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_102", title: "Köz biberli cevizli makarna", category: "Makarnalar", ingredients: ["350 g fiyonk makarna", "3 köz kırmızı biber", "Yarım su bardağı ceviz", "1 diş sarımsak", "3 yemek kaşığı zeytinyağı", "Yarım su bardağı süt", "1 tatlı kaşığı tuz"], steps: ["Makarnayı haşlayın.", "Köz biber, ceviz, sarımsak, yağ ve sütü blenderda pürüzsüz çekin.", "Sosu tavada 2 dakika ısıtın.", "Makarnayı ekleyin.", "Kalan cevizle süsleyin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Sos koyuysa haşlama suyuyla açın."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_103", title: "Bezelyeli naneli makarna", category: "Makarnalar", ingredients: ["350 g kısa makarna", "1,5 su bardağı bezelye", "1 soğan", "2 yemek kaşığı tereyağı", "Birkaç dal taze nane", "3 yemek kaşığı rendelenmiş parmesan", "1 tatlı kaşığı tuz"], steps: ["Makarnayı haşlayın.", "Tereyağında soğanı 3 dakika kavurun.", "Bezelyeyi ekleyip 5 dakika pişirin.", "Makarna ve kıyılmış naneyi ekleyin.", "Parmesanla servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Dondurulmuş bezelye de kullanılabilir."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_104", title: "Patlıcanlı domatesli makarna", category: "Makarnalar", ingredients: ["350 g penne", "2 patlıcan", "3 domates", "2 diş sarımsak", "4 yemek kaşığı zeytinyağı", "1 avuç fesleğen yaprağı", "1 tatlı kaşığı tuz"], steps: ["Patlıcanı küp doğrayıp tuzlu suda bekletip kurulayın.", "Yağda kızarana kadar soteleyin.", "Sarımsak ve domatesi ekleyip 10 dakika pişirin.", "Haşlanmış makarnayı ekleyin.", "Fesleğenle servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Patlıcanı kalabalık etmeden kızartın."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_105", title: "Pırasalı mantarlı makarna", category: "Makarnalar", ingredients: ["350 g tagliatelle", "1 pırasa", "200 g mantar", "2 yemek kaşığı tereyağı", "Yarım su bardağı krema", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Makarnayı haşlayın.", "Pırasayı ince doğrayıp tereyağında 5 dakika soteleyin.", "Mantarı ekleyip suyunu çekene kadar pişirin.", "Kremayı ekleyip 2 dakika kaynatın.", "Makarnayla karıştırın."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Krema yerine süt + 1 kaşık un kullanabilirsiniz."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_106", title: "Karnabaharlı peynirli makarna", category: "Makarnalar", ingredients: ["350 g dirsek makarna", "Yarım karnabahar", "2 yemek kaşığı tereyağı", "2 yemek kaşığı un", "2 su bardağı süt", "1 su bardağı kaşar", "1 tatlı kaşığı tuz, 1 tutam muskat"], steps: ["Makarna ve küçük karnabahar çiçeklerini birlikte haşlayın.", "Tereyağında unu kavurup sütü ekleyerek beşamel yapın.", "Kaşarı ekleyip eritin.", "Makarna ve karnabaharı sosla karıştırın.", "İsteğe göre fırında 10 dakika gratine edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Beşamel topaklanırsa telle çırpın."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_107", title: "Havuçlu zencefilli makarna", category: "Makarnalar", ingredients: ["350 g penne", "3 havuç", "1 soğan", "1 tatlı kaşığı rendelenmiş zencefil", "2 yemek kaşığı zeytinyağı", "1 su bardağı sebze suyu", "1 tatlı kaşığı tuz"], steps: ["Makarnayı haşlayın.", "Soğan ve doğranmış havucu yağda 5 dakika soteleyin.", "Zencefil ve sebze suyunu ekleyip havuç yumuşayana kadar 10 dakika pişirin.", "Blenderdan geçirip sos yapın.", "Makarnayla karıştırın."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Zencefil miktarını damak tadınıza göre ayarlayın."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_108", title: "Nohutlu ıspanaklı makarna", category: "Makarnalar", ingredients: ["350 g kısa makarna", "1 su bardağı haşlanmış nohut", "200 g ıspanak", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 çay kaşığı pul biber", "1 tatlı kaşığı tuz"], steps: ["Makarnayı haşlayın.", "Yağda sarımsak ve nohudu 4 dakika kavurun.", "Ispanağı ekleyip soldurun.", "Makarnayı ve biraz haşlama suyunu ekleyin.", "Pul biberle servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Nohut makarnaya protein katar."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a16_109", title: "Yoğurtlu pancar mezesi", category: "Mezeler", ingredients: ["2 haşlanmış pancar", "1 su bardağı süzme yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz", "Yarım demet dereotu"], steps: ["Pancarı rendeleyin.", "Sarımsağı ezin.", "Yoğurdu sarımsak ve tuzla çırpın.", "Pancarı ekleyip karıştırın.", "Zeytinyağı ve dereotuyla süsleyin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Pancarı fırında közlemek tadını yoğunlaştırır."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_110", title: "Dereotlu kabak mezesi", category: "Mezeler", ingredients: ["3 kabak", "1 su bardağı süzme yoğurt", "1 diş sarımsak", "Yarım demet dereotu", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Kabağı rendeleyin.", "Yağda suyunu çekene kadar 8 dakika soteleyip soğutun.", "Yoğurt ve sarımsağı çırpın.", "Kabak ve dereotunu ekleyin.", "Tuzunu ayarlayın."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Kabak soğumadan yoğurda eklenmesin."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_111", title: "Köz patlıcanlı tahinli meze (baba gannuş)", category: "Mezeler", ingredients: ["3 patlıcan", "3 yemek kaşığı tahin", "1 limon suyu", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, 3 yemek kaşığı nar tanesi"], steps: ["Patlıcanları ocakta veya fırında kabuğu kararana kadar közleyin.", "Kabuğunu soyup süzgeçte 10 dakika süzün.", "Bıçakla ince kıyın.", "Tahin, limon, sarımsak ve tuzla karıştırın.", "Zeytinyağı ve narla süsleyin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Süzmek mezenin sulanmasını önler."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_112", title: "Havuçlu cevizli meze", category: "Mezeler", ingredients: ["4 havuç", "1 su bardağı süzme yoğurt", "Yarım su bardağı ceviz", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Havucu rendeleyin.", "Yağda 6 dakika soteleyip soğutun.", "Cevizi iri kıyın.", "Yoğurt, sarımsak ve tuzla karıştırın.", "Ceviz ekleyip servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Havucu soteleyince tatlılığı artar."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_113", title: "Köz biberli lor mezesi", category: "Mezeler", ingredients: ["3 köz kırmızı biber", "200 g lor", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı pul biber", "Yarım demet maydanoz"], steps: ["Biberlerin kabuğunu soyup ince kıyın.", "Loru çatalla ezin.", "Sarımsak ve yağı ekleyin.", "Biberi karıştırın.", "Pul biber ve maydanozla süsleyin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Lorun tuzu azdır; tadına bakarak tuz ekleyin."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_114", title: "Kimyonlu nohut mezesi", category: "Mezeler", ingredients: ["2 su bardağı haşlanmış nohut", "1 kırmızı soğan", "2 yemek kaşığı zeytinyağı", "1 limon suyu", "1 tatlı kaşığı kimyon", "Yarım demet maydanoz", "1 tatlı kaşığı tuz"], steps: ["Nohutları süzün.", "Soğanı ince doğrayın.", "Yağ, limon, kimyon ve tuzla sos yapın.", "Nohutları sosla harmanlayın.", "Maydanozla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Biraz bekletince lezzeti oturur."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_115", title: "Yoğurtlu semizotu mezesi", category: "Mezeler", ingredients: ["1 demet semizotu", "1,5 su bardağı süzme yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Semizotunun yapraklarını ayıklayıp yıkayın.", "İri doğrayın.", "Yoğurdu sarımsak ve tuzla çırpın.", "Semizotunu ekleyin.", "Zeytinyağı gezdirin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Semizotu omega-3 açısından zengindir."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_116", title: "Sarımsaklı brokoli mezesi", category: "Mezeler", ingredients: ["1 brokoli", "1 su bardağı yoğurt", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı pul biber", "1 tatlı kaşığı tuz"], steps: ["Brokoliyi 4 dakika haşlayıp soğuk suya alın.", "İnce kıyın.", "Yoğurt, sarımsak ve tuzu çırpın.", "Brokoliyi ekleyin.", "Kızdırılmış pul biberli yağ gezdirin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Fazla haşlanan brokoli kükürt kokusu yapar."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_117", title: "Tahinli karnabahar mezesi", category: "Mezeler", ingredients: ["Yarım karnabahar", "3 yemek kaşığı tahin", "1 limon suyu", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, 1 çay kaşığı kimyon"], steps: ["Karnabaharı çiçeklerine ayırıp 220 °C fırında 25 dakika kızartın.", "Soğutup ezin.", "Tahin, limon, sarımsak ve kimyonu çırpın.", "Karnabaharla karıştırın.", "Zeytinyağıyla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Fırınlamak haşlamaktan daha lezzetli olur."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_118", title: "Yoğurtlu pazı mezesi", category: "Mezeler", ingredients: ["1 demet pazı", "1 su bardağı süzme yoğurt", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Pazıyı ince doğrayın.", "Yağda soldurup suyunu çekene kadar pişirin.", "Soğutun.", "Yoğurt ve sarımsakla karıştırın.", "Tuzunu ayarlayın."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Kalın sapları ayrı doğrayıp önce pişirin."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_119", title: "Patlıcanlı domatesli meze (közlü ezme)", category: "Mezeler", ingredients: ["3 patlıcan", "2 domates", "2 sivri biber", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 yemek kaşığı nar ekşisi", "1 tatlı kaşığı tuz"], steps: ["Patlıcan ve biberleri közleyip soyun.", "Domatesi kabuğunu soyup küçük doğrayın.", "Hepsini ince kıyın.", "Sarımsak, yağ, nar ekşisi ve tuzla karıştırın.", "Soğuk servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Közleme dumanlı tat verir."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a16_120", title: "Kereviz ve elma mezesi", category: "Mezeler", ingredients: ["1 kereviz kökü", "1 yeşil elma", "1 su bardağı yoğurt", "2 yemek kaşığı mayonez (isteğe bağlı)", "Yarım su bardağı ceviz", "1 tatlı kaşığı tuz"], steps: ["Kerevizi ve elmayı rendeleyin; kararmasın diye limon gezdirin.", "Yoğurt (ve mayonez) ile karıştırın.", "Cevizi ekleyin.", "Tuzunu ayarlayın.", "30 dakika dinlendirin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Limon kerevizin kararmasını önler."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a17_001", title: "Kremasız sebze çorbası", category: "Çorbalar", ingredients: ["3 su bardağı doğranmış sebze (kabak, havuç, brokoli, karnabahar, pırasa, kereviz veya balkabağı)", "1 orta boy patates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı tereyağı", "5 su bardağı sıcak su veya sebze suyu", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber", "Yarım su bardağı süt"], steps: ["Soğanı zeytinyağı ve tereyağında 3 dakika kavurun.", "Sebzeyi ve küp doğranmış patatesi ekleyip 5 dakika çevirin.", "Sıcak suyu ve tuzu ekleyin; kaynayınca kısık ateşte 20–25 dakika, sebzeler yumuşayana kadar pişirin.", "Blenderdan pürüzsüz geçirin, sütü ekleyip 2 dakika kaynatın.", "Karabiberle tatlandırıp sıcak servis edin."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Havuç–zencefil, karnabahar–zerdeçal, balkabağı–tarçın, kabak–dereotu uyumlu eşleşmelerdir.", "Patates, krema kullanmadan kadifemsi kıvam verir."], serving: "Kıtır ekmek ve limonla sıcak servis edin.", storage: "Buzdolabında 3 gün; dondurulabilir."),
  GeneralRecipe(id: "p39a17_013", title: "Köz biber ve domates çorbası", category: "Çorbalar", ingredients: ["3 közlenmiş kapya biber", "2 olgun domates", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Közlenmiş biberlerin kabuğunu ve çekirdeklerini ayıklayıp doğrayın; domatesleri rendeleyin.", "Soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Biber ve domatesi ekleyip 5 dakika pişirin.", "Suyu ekleyip kaynatın; kısık ateşte 15 dakika pişirin.", "Ocaktan alıp el blenderıyla pürüzsüz olana kadar çekin; sıçramaması için blenderı tencerenin dibine kadar daldırın.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 40),
  GeneralRecipe(id: "p39a17_014", title: "Nohut ve limon çorbası", category: "Çorbalar", ingredients: ["2 su bardağı haşlanmış nohut", "1 yemek kaşığı limon suyu", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Soğanı ince doğrayın.", "Tencerede yağı orta ateşte ısıtıp soğanı pembeleşene kadar 3–4 dakika kavurun.", "Nohudu ekleyip 2 dakika çevirin.", "Suyu ekleyip kaynatın; kısık ateşte 15 dakika pişirin.", "Nohutların yarısını blenderdan geçirip tencereye geri ekleyin; çorba koyulaşır.", "Ocaktan alıp limon suyunu ekleyin.", "Tuzunu damak zevkinize göre ayarlayın; bebek ve küçük çocuk porsiyonunu tuz eklemeden ayırın."], minutes: 40),
  GeneralRecipe(id: "p39a17_016", title: "Sebzeli tencere yemeği", category: "Sebze yemekleri", ingredients: ["3 su bardağı doğranmış sebze (kabak, patlıcan, pırasa, karnabahar, brokoli, ıspanak veya kereviz)", "1 su bardağı haşlanmış nohut veya yeşil mercimek", "1 soğan", "2 diş sarımsak", "1 yemek kaşığı domates salçası", "3 yemek kaşığı zeytinyağı", "1,5 su bardağı sıcak su", "1 tatlı kaşığı tuz, 1 çay kaşığı pul biber"], steps: ["Soğanı zeytinyağında 4 dakika, sarımsağı 1 dakika kavurun.", "Salçayı ekleyip kokusu çıkana kadar çevirin.", "Sert sebzeleri (kereviz, karnabahar, pırasa) önce ekleyip 5 dakika pişirin.", "Yumuşak sebzeler ile nohut veya mercimeği ekleyin, sıcak su ve tuzu ilave edin.", "Kapağı kapalı kısık ateşte 20–25 dakika pişirin; 10 dakika dinlendirin."], minutes: 55, servings: 4, prepMinutes: 20, cookMinutes: 35, difficulty: "Kolay", tips: ["Sebzeleri pişme sürelerine göre sırayla ekleyin; hepsi aynı anda yumuşar."], serving: "Yoğurt ve pilavla sıcak servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "p39a17_032", title: "Tahıllı yeşil salata", category: "Salatalar", ingredients: ["1 su bardağı pişmiş tahıl (bulgur, buğday, karabuğday veya yeşil mercimek)", "1 demet roka veya semizotu", "1 salatalık", "1 su bardağı çeri domates", "1 küçük kırmızı soğan", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "2 yemek kaşığı nar ekşisi veya limon suyu", "1 tatlı kaşığı tuz"], steps: ["Tahılı paket talimatına göre diri pişirip soğutun.", "Yeşillikleri yıkayıp kurulayın, iri doğrayın.", "Salatalık ve soğanı doğrayın, domatesleri ikiye kesin.", "Zeytinyağı, nar ekşisi ve tuzu çırpın.", "Tüm malzemeyi sosla harmanlayıp hemen servis edin."], minutes: 35, servings: 4, prepMinutes: 20, cookMinutes: 15, difficulty: "Kolay", tips: ["Pancar, armut, portakal veya ceviz eklemek salatayı ana öğüne dönüştürür."], serving: "Soğuk servis edin.", storage: "Sossuz hâli buzdolabında 1 gün."),
  GeneralRecipe(id: "p39a17_047", title: "Fırın tavasında sebzeli frittata", category: "Kahvaltılıklar", ingredients: ["6 yumurta", "4 yemek kaşığı süt", "1,5 su bardağı doğranmış sebze (kabak, mantar, patates, brokoli, domates veya ıspanak)", "1 su bardağı rendelenmiş kaşar veya ufalanmış beyaz peynir", "1 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber", "4–5 dal dereotu veya maydanoz"], steps: ["Fırını 180 °C'ye ısıtın.", "Fırına girebilen tavada tereyağını eritip sebzeleri 5–6 dakika soteleyin.", "Yumurtaları süt, tuz ve karabiberle çırpın, peynirin yarısını ekleyin.", "Karışımı sebzelerin üzerine dökün, 2 dakika ocakta kenarları tutana kadar pişirin.", "Kalan peyniri serpip fırında 12–15 dakika, ortası sertleşene kadar pişirin.", "5 dakika dinlendirip dilimleyin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 180, tips: ["Patates kullanacaksanız önce 5 dakika haşlayın."], serving: "Dilimleyip sıcak veya ılık servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a17_061", title: "Sebzeli tahıl pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı tahıl (bulgur, pirinç, kinoa, karabuğday veya arpa şehriye)", "1 su bardağı küp doğranmış sebze (havuç, bezelye, patlıcan, ıspanak veya kırmızı biber)", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı tereyağı", "Tahılın gerektirdiği kadar sıcak su (bulgur/pirinç: 2,5–3 su bardağı, kinoa: 2,5 su bardağı)", "1 tatlı kaşığı tuz"], steps: ["Pirinç kullanıyorsanız 20 dakika ılık suda bekletip yıkayın; kinoayı ovarak yıkayın.", "Soğanı zeytinyağında 3 dakika kavurun, sebzeyi ekleyip 4 dakika soteleyin.", "Tahılı ekleyip 2 dakika kavurun.", "Sıcak su ve tuzu ekleyip kısık ateşte 15 dakika pişirin.", "Tereyağını ekleyip 10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Su oranı tahıla göre değişir; paket talimatını kontrol edin."], serving: "Ana yemeğin yanında sıcak servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "p39a17_076", title: "Bol sebzeli tavuk sote", category: "Tavuk yemekleri", ingredients: ["600 g tavuk göğsü (kuşbaşı)", "2 su bardağı doğranmış sebze (kabak, mantar, havuç, brokoli, kırmızı biber, bezelye veya pırasa)", "1 soğan", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı domates salçası (isteğe bağlı)", "1 tatlı kaşığı kekik veya biberiye", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Tavuğu ayrı bir kesme tahtasında doğrayın, tuz ve karabiberle harmanlayın.", "Geniş tavada yağı kızdırıp tavuğu yüksek ateşte her yüzü kızarana kadar 6–7 dakika mühürleyin ve alın.", "Aynı tavada soğan ve sarımsağı 3 dakika, ardından sebzeleri 5–6 dakika soteleyin.", "Salça ve otları ekleyip tavuğu geri koyun, 2–3 kaşık su ekleyin.", "Kapağı kapalı 8–10 dakika, tavuğun en kalın yeri 74 °C olana ve pembe kalmayana kadar pişirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Tavuğu kalabalık etmeden mühürleyin; suyunu salıp haşlanmasın.", "Hardal, limon veya zencefil ile farklı tatlar elde edebilirsiniz."], serving: "Pilav veya bulgurla sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a17_091", title: "Fırında limonlu otlu balık", category: "Balık ve deniz ürünleri", ingredients: ["4 porsiyon balık (levrek, çipura, somon, alabalık veya mezgit; fileto ya da bütün)", "2 limon", "4 diş sarımsak", "3 yemek kaşığı zeytinyağı", "Yarım demet dereotu veya 1 tatlı kaşığı kekik", "2 domates (isteğe bağlı)", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Fırını 200 °C'ye ısıtın, tepsiye pişirme kâğıdı serin.", "Bütün balığın iki yüzüne çapraz çizikler atın; filetoyu kâğıt havluyla kurulayın.", "Zeytinyağı, limon suyu, ezilmiş sarımsak, otlar, tuz ve karabiberle sos hazırlayıp balığa sürün.", "Balığı tepsiye yerleştirin; etrafına limon ve domates dilimleri dizin.", "Fileto 12–15, bütün balık 20–25 dakika, eti opaklaşıp kılçıktan kolayca ayrılana kadar pişirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Yağlı balıklar (somon, uskumru) hardal ve dereotuyla, beyaz etli balıklar limon ve kekikle uyumludur."], serving: "Roka salatası ve limonla sıcak servis edin.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "p39a17_106", title: "Sebzeli zeytinyağlı makarna", category: "Makarnalar", ingredients: ["350 g makarna", "2 su bardağı doğranmış sebze (kabak, mantar, domates, patlıcan, bezelye veya karnabahar)", "3 diş sarımsak", "4 yemek kaşığı zeytinyağı", "1 limon kabuğu rendesi (isteğe bağlı)", "Yarım su bardağı rendelenmiş peynir", "1 tatlı kaşığı tuz, 1 çay kaşığı pul biber", "1 avuç taze ot (fesleğen, nane, kekik veya dereotu)"], steps: ["Makarnayı bol tuzlu suda haşlayın, 1 bardak suyunu ayırın.", "Zeytinyağında sarımsağı 1 dakika çevirin.", "Sebzeyi ekleyip yüksek ateşte 6–8 dakika soteleyin.", "Makarnayı, limon kabuğunu ve biraz haşlama suyunu ekleyip 1 dakika karıştırın.", "Peynir ve taze otlarla servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Haşlama suyu sosu bağlar; az az ekleyin."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a17_121", title: "Yoğurtlu meyve ve kuruyemiş kupu", category: "Tatlılar", ingredients: ["500 g süzme yoğurt", "1,5 su bardağı meyve veya pişmiş balkabağı (elma, armut, çilek, şeftali, kayısı, incir veya hurma)", "4 yemek kaşığı kuruyemiş (ceviz, badem veya fındık)", "2 yemek kaşığı bal veya pekmez", "1 çay kaşığı tarçın", "2 yemek kaşığı tahin (isteğe bağlı)"], steps: ["Meyveyi küçük doğrayın; elma ve armudu 5 dakika tavada tarçınla yumuşatıp soğutun.", "Kuruyemişi kuru tavada 2 dakika kavurup iri kıyın.", "Yoğurdu bal ile çırpın.", "Bardaklara yoğurt, meyve ve kuruyemişi kat kat yerleştirin.", "Üzerine tahin gezdirip 30 dakika soğutun."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Hurma ve incir tatlı olduğundan balı azaltabilirsiniz."], serving: "Soğuk servis edin.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "p39a17_136", title: "Yoğurtlu sebze ezmesi", category: "Mezeler", ingredients: ["500 g sebze (pancar, kabak, havuç, brokoli, karnabahar, pazı veya patlıcan)", "1,5 su bardağı süzme yoğurt", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "2 yemek kaşığı ceviz veya 2 yemek kaşığı tahin", "1 tatlı kaşığı tuz"], steps: ["Sebzeyi hazırlayın: pancarı haşlayıp rendeleyin, kabak ve havucu rendeleyip soteleyin, brokoli ve karnabaharı haşlayın, patlıcanı közleyin.", "Sebzeyi soğutup ince kıyın veya ezin.", "Yoğurdu sarımsak ve tuzla çırpın.", "Sebze ve ceviz ya da tahinle karıştırın.", "Zeytinyağı gezdirip soğuk servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Sebze tamamen soğumadan yoğurtla karıştırmayın."], serving: "Soğuk, ekmek veya lavaşla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a18_001", title: "Fırında sarımsaklı kabak", category: "Sebze yemekleri", ingredients: ["2 orta boy kabak", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Kabakları yıkayıp 1 cm kalınlığında yarım ay dilimleyin; fazla suyunu kâğıt havluyla alın.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler yumuşayıp kenarları kızarana kadar 20–30 dakika pişirin; pişirme ortasında çevirin.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Limon suyunu gezdirip ılık servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a18_002", title: "Fırında sarımsaklı patlıcan", category: "Sebze yemekleri", ingredients: ["2 orta boy patlıcan", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Patlıcanları alacalı soyup küp doğrayın; 15 dakika tuzlu suda bekletip iyice kurulayın.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler yumuşayıp kenarları kızarana kadar 20–30 dakika pişirin; pişirme ortasında çevirin.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Limon suyunu gezdirip ılık servis edin."], minutes: 55),
  GeneralRecipe(id: "p39a18_003", title: "Fırında sarımsaklı karnabahar", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Karnabaharı küçük çiçeklere ayırıp yıkayın; çok iri parçaları ikiye bölün.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler yumuşayıp kenarları kızarana kadar 20–30 dakika pişirin; pişirme ortasında çevirin.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Limon suyunu gezdirip ılık servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a18_004", title: "Fırında sarımsaklı brokoli", category: "Sebze yemekleri", ingredients: ["1 orta boy brokoli", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Brokoliyi çiçeklere ayırın, kalın saplarını ince dilimleyin ve iyice kurulayın.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler yumuşayıp kenarları kızarana kadar 20–30 dakika pişirin; pişirme ortasında çevirin.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Limon suyunu gezdirip ılık servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a18_005", title: "Fırında sarımsaklı pırasa", category: "Sebze yemekleri", ingredients: ["3 sap pırasa", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Pırasaları boyuna kesip katlarını iyice yıkayın; 3 cm parçalar hâlinde doğrayın.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler tamamen yumuşayıp kenarları kızarana kadar 30–35 dakika pişirin; gerekirse üzerini kısa süre örtün.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Limon suyunu gezdirip ılık servis edin."], minutes: 45),
  GeneralRecipe(id: "p39a18_006", title: "Fırında sarımsaklı ıspanak", category: "Sebze yemekleri", ingredients: ["350 g ıspanak", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Ispanağı bol suyla yıkayıp süzün, kalın saplarını ayırın ve iri doğrayın.", "Sarımsağı zeytinyağıyla karıştırın; yaprak ve sapları geniş fırın kabına alın.", "Sert sapları önce 190°C fırında 8 dakika pişirin; yaprakları ekleyip karıştırın.", "Yapraklar sönüp yumuşayana kadar 8–12 dakika daha pişirin; limonla servis edin.", "Kekik ve az tuz serpip karıştırın.", "Yoğurtla da servis edebilirsiniz."], minutes: 30),
  GeneralRecipe(id: "p39a18_007", title: "Fırında sarımsaklı pazı", category: "Sebze yemekleri", ingredients: ["1 demet pazı", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Pazı yapraklarını yıkayıp kurulayın; sert sapları ince, yaprakları iri doğrayın.", "Sarımsağı zeytinyağıyla karıştırın; yaprak ve sapları geniş fırın kabına alın.", "Sert sapları önce 190°C fırında 8 dakika pişirin; yaprakları ekleyip karıştırın.", "Yapraklar sönüp yumuşayana kadar 8–12 dakika daha pişirin; limonla servis edin.", "Kekik ve az tuz serpip karıştırın.", "Yoğurtla da servis edebilirsiniz."], minutes: 30),
  GeneralRecipe(id: "p39a18_008", title: "Fırında sarımsaklı kereviz", category: "Sebze yemekleri", ingredients: ["1 orta boy kereviz", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Kerevizi soyup 2 cm küpler hâlinde kesin; kararmaması için limonlu suda tutun.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler tamamen yumuşayıp kenarları kızarana kadar 30–35 dakika pişirin; gerekirse üzerini kısa süre örtün.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Limon suyunu gezdirip ılık servis edin."], minutes: 45),
  GeneralRecipe(id: "p39a18_009", title: "Fırında sarımsaklı havuç", category: "Sebze yemekleri", ingredients: ["4 orta boy havuç", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Havuçları soyup eşit kalınlıkta, yaklaşık 1 cm çubuklar hâlinde kesin.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler yumuşayıp kenarları kızarana kadar 20–30 dakika pişirin; pişirme ortasında çevirin.", "Çatalla kontrol edin: kolayca batıyorsa sebze pişmiştir.", "Limon suyunu gezdirip ılık servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a18_010", title: "Fırında sarımsaklı mantar", category: "Sebze yemekleri", ingredients: ["400 g kültür mantarı", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Mantarları nemli bezle temizleyip ikiye bölün; suya yatırmayın.", "Sarımsak, zeytinyağı ve kekiği mantarlarla harmanlayın.", "Mantarları geniş tepsiye tek kat yayın; 200°C fırında 15 dakika pişirin.", "Suyunu bırakıp kenarları kızarınca karıştırın; 5–8 dakika daha pişirip servis edin.", "Az tuz serpin.", "Limon suyunu gezdirip ılık servis edin."], minutes: 33),
  GeneralRecipe(id: "p39a18_011", title: "Yoğurtlu sebze salatası (borani usulü)", category: "Salatalar", ingredients: ["500 g sebze (kabak, patlıcan, ıspanak, pazı, pırasa, havuç veya karnabahar)", "2 su bardağı süzme yoğurt", "2 diş sarımsak (ezilmiş)", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz", "1 tatlı kaşığı pul biber", "4–5 dal dereotu"], steps: ["Sebzeyi hazırlayın: kabak ve havucu rendeleyin, ıspanak/pazı/pırasayı ince doğrayın, patlıcanı közleyip doğrayın, karnabaharı küçük çiçeklere ayırıp haşlayın.", "Zeytinyağının yarısında sebzeyi suyunu çekene kadar 6–8 dakika soteleyin; tuzunu ekleyip tamamen soğutun.", "Yoğurdu sarımsak ve dereotuyla çırpın.", "Soğumuş sebzeyi yoğurtla karıştırıp servis tabağına alın.", "Kalan zeytinyağını kızdırıp pul biberi ekleyin ve salatanın üzerine gezdirin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Sebzeler sıcakken yoğurda eklenirse yoğurt kesilir ve sulanır."], serving: "Soğuk servis edin; et ve tavuk yemeklerinin yanına yakışır.", storage: "Kapalı kapta buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a18_031", title: "Sebzeli peynirli omlet", category: "Kahvaltılıklar", ingredients: ["4 yumurta", "3 yemek kaşığı süt", "1 su bardağı ince doğranmış sebze (kabak, ıspanak, pazı, mantar, pırasa veya brokoli)", "1 yemek kaşığı tereyağı", "Yarım su bardağı rendelenmiş kaşar veya ufalanmış beyaz peynir", "Yarım çay kaşığı tuz", "1 tutam karabiber", "4–5 dal maydanoz"], steps: ["Sebzeyi ince doğrayın; brokoli ve karnabaharı küçük çiçeklere ayırıp 3 dakika haşlayın.", "Tavada tereyağını eritin, sebzeyi ekleyip suyunu çekene kadar 4–5 dakika soteleyin.", "Yumurtaları süt, tuz ve karabiberle köpürene kadar çırpın.", "Karışımı sebzelerin üzerine dökün; kısık ateşte kenarlar tutunca spatulayla ortaya doğru itin.", "Üst yüzey hafif akışkanken peyniri serpin, kapağı kapatıp 2 dakika pişirin.", "Omleti ikiye katlayıp maydanozla servis edin."], minutes: 20, servings: 2, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Sulu sebzeleri (kabak, ıspanak) önce soteleyip suyunu uçurun; omlet sulanmaz.", "Beyaz peynir kullanıyorsanız tuzu azaltın."], serving: "Domates, salatalık ve kızarmış ekmekle sıcak servis edin.", storage: "Taze tüketin; bekletmeyin."),
  GeneralRecipe(id: "p39a18_041", title: "Sebzeli nohutlu bulgur pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı pilavlık bulgur", "1 su bardağı haşlanmış nohut", "1 su bardağı küp doğranmış sebze (kabak, patlıcan, havuç, mantar, pırasa veya kereviz)", "1 orta boy soğan", "1 yemek kaşığı biber salçası", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı tereyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Soğanı zeytinyağında 3 dakika kavurun; sebzeyi ekleyip 5 dakika soteleyin.", "Salçayı ekleyip kokusu çıkana kadar 1 dakika çevirin.", "Bulgur ve nohudu ekleyip 2 dakika kavurun.", "Sıcak su ve tuzu ekleyin; kaynayınca kısık ateşte kapağı kapalı 15 dakika suyunu çekene kadar pişirin.", "Tereyağını ekleyin, kapağın altına kâğıt havlu koyup 10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Patlıcan kullanıyorsanız önce tuzlu suda 15 dakika bekletip acısını alın.", "Demlenme süresi tanelerin dağılmasını sağlar."], serving: "Cacık veya yoğurtla servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a18_051", title: "Sebze soslu tam buğday makarna", category: "Makarnalar", ingredients: ["350 g tam buğday kalem veya burgu makarna", "2 su bardağı küp doğranmış sebze (kabak, patlıcan, brokoli, mantar, ıspanak, kereviz veya havuç)", "1 orta boy soğan", "2 diş sarımsak", "2 adet rendelenmiş domates", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz", "Yarım çay kaşığı pul biber", "Yarım su bardağı rendelenmiş peynir"], steps: ["Bol tuzlu suyu kaynatın; makarnayı paketteki süre kadar haşlayın, süzmeden önce 1 su bardağı haşlama suyu ayırın.", "Bu sırada zeytinyağında soğanı 3 dakika, ardından sarımsağı 1 dakika kavurun.", "Sebzeyi ekleyip 6–8 dakika yumuşayana kadar soteleyin (ıspanak 2 dakika yeterli).", "Domatesi, tuzu ve pul biberi ekleyip 5 dakika koyulaşana kadar pişirin.", "Makarnayı sosa ekleyin; gerekirse ayırdığınız haşlama suyundan ekleyerek 1 dakika karıştırın.", "Peyniri serpip hemen servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Haşlama suyundaki nişasta sosun makarnaya tutunmasını sağlar.", "Tam buğday makarna beyaz makarnadan 1–2 dakika daha uzun pişer."], serving: "Yanına yoğurt veya yeşil salata ile sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır; ısıtırken 2 kaşık su ekleyin."),
  GeneralRecipe(id: "p39a18_062", title: "Patlıcanlı tavuk tepsi", category: "Tavuk yemekleri", ingredients: ["2 patlıcan (iri küp)", "500 g kemiksiz tavuk but (iri küp)", "2 patates (küp)", "1 soğan (iri doğranmış)", "2 yeşil biber", "2 domates (küp)", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı domates salçası", "Yarım su bardağı sıcak su", "1 tatlı kaşığı tatlı toz biber", "1 çay kaşığı kekik", "1 çay kaşığı tuz"], steps: ["Patlıcanları alacalı soyup küp doğrayın, tuzlu suda 15 dakika bekletip süzün ve kurulayın.", "Fırını 200 °C'ye ısıtın.", "Tavuk, patlıcan, patates, soğan ve biberi büyük bir kapta zeytinyağı, toz biber, kekik ve tuzla harmanlayın.", "Karışımı fırın tepsisine tek kat yayın; domatesleri aralara dağıtın.", "Salçayı sıcak suda eritip tepsiye gezdirin, folyoyla kapatıp 25 dakika pişirin.", "Folyoyu kaldırıp 15 dakika daha, üzeri kızarana ve patatesler yumuşayana kadar pişirin."], minutes: 60, servings: 4, prepMinutes: 20, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 200, tips: ["Patlıcanı tuzlu suda bekletmek acılığını alır ve daha az yağ çekmesini sağlar."], serving: "Cacık veya yoğurt ile sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a18_063", title: "Karnabaharlı baharatlı tavuk tepsi", category: "Tavuk yemekleri", ingredients: ["1 küçük karnabahar (çiçeklerine ayrılmış)", "500 g kemiksiz tavuk but", "1 kırmızı soğan (dilim)", "3 yemek kaşığı zeytinyağı", "3 yemek kaşığı yoğurt", "1 tatlı kaşığı tatlı toz biber", "1 çay kaşığı kimyon", "Yarım çay kaşığı zerdeçal", "1 diş sarımsak (rendelenmiş)", "1 çay kaşığı tuz", "Yarım limon"], steps: ["Yoğurt, 1 yemek kaşığı zeytinyağı, toz biber, kimyon, zerdeçal, sarımsak ve yarım çay kaşığı tuzu karıştırıp tavukları bu karışımla 20 dakika marine edin.", "Fırını 210 °C'ye ısıtın.", "Karnabahar ve soğanı kalan zeytinyağı ve tuzla harmanlayıp tepsiye yayın.", "Tavukları karnabaharların arasına yerleştirin.", "Fırında 30–35 dakika, karnabaharların kenarları kızarana ve tavuk tamamen pişene kadar pişirin.", "Üzerine limon sıkıp servis edin."], minutes: 50, servings: 4, prepMinutes: 15, cookMinutes: 35, difficulty: "Kolay", ovenCelsius: 210, tips: ["Yoğurtlu marinasyon tavuğu yumuşatır; buzdolabında 4 saate kadar bekletebilirsiniz."], serving: "Bulgur pilavı veya lavaş ile servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a18_073", title: "Sebze yatağında fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["4 dilim somon", "3 su bardağı doğranmış sebze (karnabahar, brokoli, pırasa, kereviz veya havuç)", "3 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı kekik", "1 tatlı kaşığı tuz"], steps: ["Fırını 200 °C'ye ısıtın.", "Sebzeyi 2 yemek kaşığı zeytinyağı, kekik ve tuzun yarısıyla harmanlayın.", "Tepsiye yayıp 12 dakika ön pişirin.", "Somonları sebzelerin üzerine yerleştirin, kalan yağ, tuz ve limon suyunu sürün.", "12–14 dakika, somon opaklaşana kadar pişirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Sebzeyi önceden pişirmek somonun kurumadan hazır olmasını sağlar."], serving: "Limon dilimleriyle sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "p39a18_081", title: "Tahinli köz sebze mezesi", category: "Mezeler", ingredients: ["500 g sebze (patlıcan, kabak, karnabahar, kereviz, havuç veya brokoli)", "3 yemek kaşığı tahin", "4 yemek kaşığı süzme yoğurt", "1 diş sarımsak (ezilmiş)", "1 yemek kaşığı limon suyu", "2 yemek kaşığı zeytinyağı", "Yarım çay kaşığı tuz", "4–5 dal maydanoz"], steps: ["Fırını 220 °C'ye ısıtın. Patlıcanı bütün olarak çatalla delin; diğer sebzeleri iri doğrayın.", "Sebzeleri 1 yemek kaşığı zeytinyağıyla harmanlayıp tepsiye yayın.", "25–30 dakika, kenarları kararıp içleri yumuşayana kadar közleyin; patlıcanın kabuğunu soyun.", "Sebzeleri bıçakla ince kıyın veya çatalla ezin ve soğumaya bırakın.", "Tahin, yoğurt, sarımsak, limon suyu ve tuzu çırpın; sebzelerle karıştırın.", "Tabağa yayıp kalan zeytinyağı ve kıyılmış maydanozla süsleyin."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 220, tips: ["Tahin koyulaşırsa 1–2 kaşık soğuk suyla açın.", "Sebzeler tamamen soğumadan yoğurt eklerseniz meze sulanır."], serving: "Soğuk servis edin; lavaş veya kızarmış ekmekle sunun.", storage: "Kapalı kapta buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a18_091", title: "Meyveli yulaflı fırın tatlısı", category: "Tatlılar", ingredients: ["4 su bardağı dilimlenmiş meyve (elma, armut, şeftali, kayısı, erik, vişne, böğürtlen veya yaban mersini)", "1 yemek kaşığı limon suyu", "2 yemek kaşığı esmer şeker", "1 tatlı kaşığı tarçın", "1 su bardağı yulaf ezmesi", "Yarım su bardağı tam buğday unu", "4 yemek kaşığı soğuk tereyağı", "3 yemek kaşığı bal", "Yarım su bardağı iri kıyılmış ceviz"], steps: ["Fırını 180 °C'ye ısıtın; 20×25 cm fırın kabını tereyağıyla yağlayın.", "Meyveleri limon suyu, esmer şeker ve tarçının yarısıyla harmanlayıp kaba yayın.", "Yulaf, un ve kalan tarçını karıştırın; soğuk tereyağını ekleyip parmak uçlarınızla iri kum kıvamına gelene kadar ovalayın.", "Bal ve cevizi ekleyip karıştırın; bu kırıntıları meyvelerin üzerine eşit serpin.", "35 dakika, üstü altın rengi olup kenarlarda meyve suyu fokurdayana kadar pişirin.", "15 dakika dinlendirip servis edin."], minutes: 50, servings: 6, prepMinutes: 15, cookMinutes: 35, difficulty: "Kolay", ovenCelsius: 180, tips: ["Sulu meyvelerde (vişne, böğürtlen) meyveye 1 yemek kaşığı nişasta karıştırın; tatlı daha toplu olur.", "Tereyağı soğuk olmalı; aksi hâlde kırıntılar çıtırlaşmaz."], serving: "Ilık olarak bir top dondurma veya bir kaşık süzme yoğurtla servis edin.", storage: "Oda sıcaklığında 1 gün, buzdolabında 3 gün saklanır; fırında 10 dakika ısıtın."),
  GeneralRecipe(id: "p39a18_101", title: "Meyveli yoğurtlu soğuk kup", category: "Tatlılar", ingredients: ["500 g süzme yoğurt", "2 su bardağı mevsim meyvesi (elma, armut, muz, şeftali, kayısı, çilek, vişne veya yaban mersini)", "4 yemek kaşığı yulaf ezmesi", "2 yemek kaşığı bal veya pekmez", "1 çay kaşığı tarçın", "2 yemek kaşığı iri kıyılmış ceviz"], steps: ["Meyveleri yıkayın; elma ve armudu küp küp, muzu halka, çileği dörde doğrayın. Vişnenin çekirdeklerini çıkarın.", "Sert meyveleri (elma, armut, ayva) tavada 2 yemek kaşığı su ve tarçınla 5 dakika yumuşatıp soğutun.", "Yoğurdu bal veya pekmezle pürüzsüz olana kadar çırpın.", "Yulafı kuru tavada 2–3 dakika hafifçe kavurup soğutun.", "4 bardağın dibine birer kaşık yulaf, üzerine yoğurt, sonra meyve koyun; katları bir kez daha tekrarlayın.", "Üzerine ceviz serpip en az 1 saat buzdolabında bekletin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Sulu meyveler (çilek, şeftali) yoğurdu sulandırmasın diye süzme yoğurt kullanın.", "Yulafı servisten hemen önce eklerseniz çıtır kalır."], serving: "Soğuk servis edin; üzerine taze nane yaprağı yakışır.", storage: "Buzdolabında kapalı olarak 1 gün saklanır."),
  GeneralRecipe(id: "p39a18_111", title: "Yeşil mercimekli sıcak sebze salatası", category: "Salatalar", ingredients: ["1 su bardağı yeşil mercimek", "2 su bardağı doğranmış sebze (kabak, patlıcan, karnabahar, brokoli, havuç veya mantar)", "1 kırmızı soğan", "3 yemek kaşığı zeytinyağı", "2 yemek kaşığı nar ekşisi", "1 tatlı kaşığı kimyon", "1 tatlı kaşığı tuz", "Yarım demet maydanoz"], steps: ["Mercimeği yıkayıp bol suda 20–25 dakika, diri kalacak şekilde haşlayın ve süzün.", "Sebzeyi 1 yemek kaşığı zeytinyağıyla tavada orta-yüksek ateşte 8–10 dakika, kenarları kızarana kadar soteleyin.", "Kırmızı soğanı ince piyazlık doğrayın.", "Kalan zeytinyağı, nar ekşisi, kimyon ve tuzu çırparak sos hazırlayın.", "Sıcak mercimek, sebze, soğan ve kıyılmış maydanozu sosla harmanlayın."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Mercimeği fazla haşlamayın; salata lapa olmasın.", "Sos sıcak mercimeğe daha iyi işler."], serving: "Ilık servis edin; üzerine ufalanmış beyaz peynir eklenebilir.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a18_121", title: "Pirinçli zeytinyağlı sebze", category: "Sebze yemekleri", ingredients: ["3 su bardağı doğranmış sebze (kabak, patlıcan, karnabahar, brokoli, pırasa, kereviz veya havuç)", "3 yemek kaşığı pirinç", "1 soğan", "1 domates", "4 yemek kaşığı zeytinyağı", "1,5 su bardağı sıcak su", "1 tatlı kaşığı tuz, 1 çay kaşığı şeker", "Yarım limon"], steps: ["Soğanı zeytinyağında 4 dakika kavurun.", "Sebzeyi ekleyip 5 dakika çevirin.", "Doğranmış domates, yıkanmış pirinç, tuz ve şekeri ekleyin.", "Sıcak suyu ilave edip kısık ateşte 25 dakika pişirin.", "Limon sıkıp tencerede soğumaya bırakın."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Zeytinyağlılar ılık veya soğuk servis edilir."], serving: "Yoğurtla soğuk servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "p39a18_141", title: "Kabaklı patatesli tepsi köftesi", category: "Et yemekleri", ingredients: ["500 g dana kıyma", "2 kabak (kalın halka)", "2 orta boy patates (halka)", "1 küçük soğan (rendelenmiş)", "3 yemek kaşığı galeta unu", "1 yumurta", "2 domates", "2 yeşil biber", "1 yemek kaşığı domates salçası", "1 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı", "1,5 çay kaşığı tuz", "1 çay kaşığı kimyon", "Yarım çay kaşığı karabiber"], steps: ["Kıyma, rendelenmiş soğan, galeta unu, yumurta, 1 çay kaşığı tuz, kimyon ve karabiberi 3 dakika yoğurun; 20 dakika buzdolabında dinlendirin.", "Fırını 200 °C'ye ısıtın; patates halkalarını zeytinyağı ve kalan tuzla harmanlayın.", "Harçtan ceviz büyüklüğünde parçalar alıp yassı köfteler yapın.", "Tepsiye köfte, patates ve kabak halkalarını sırayla dik olarak dizin; aralara domates dilimleri ve biber yerleştirin.", "Salçayı sıcak suda eritip tepsiye gezdirin; folyoyla kapatıp 25 dakika pişirin.", "Folyoyu kaldırıp 15 dakika daha, köfteler kızarana kadar pişirin."], minutes: 65, servings: 4, prepMinutes: 25, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 200, tips: ["Patatesler kabaktan geç piştiği için ince, kabakları kalın doğrayın."], serving: "Pirinç pilavı ve yoğurtla sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a18_142", title: "Patlıcanlı tepsi köftesi", category: "Et yemekleri", ingredients: ["500 g dana kıyma", "3 patlıcan (kalın halka)", "1 küçük soğan (rendelenmiş)", "1 dilim bayat ekmek içi", "1 yumurta", "3 domates", "4 sivri biber", "1 yemek kaşığı biber salçası", "1 su bardağı sıcak su", "3 yemek kaşığı zeytinyağı", "1,5 çay kaşığı tuz", "1 çay kaşığı kimyon", "Yarım çay kaşığı karabiber"], steps: ["Patlıcanları alacalı soyup 2 cm halka doğrayın; tuzlu suda 15 dakika bekletip kurulayın, 2 yemek kaşığı zeytinyağıyla harmanlayıp 200 °C fırında 15 dakika ön pişirin.", "Kıyma, soğan, ıslatıp sıktığınız ekmek içi, yumurta, tuz, kimyon ve karabiberi yoğurun.", "Harçtan patlıcan büyüklüğünde yassı köfteler yapın.", "Tepsiye bir patlıcan bir köfte olacak şekilde dik dizin; aralara domates dilimleri ve biber yerleştirin.", "Salçayı sıcak suda eritip kalan zeytinyağıyla tepsiye gezdirin; 200 °C fırında 25 dakika pişirin.", "Üzeri kızarınca 5 dakika dinlendirip servis edin."], minutes: 70, servings: 4, prepMinutes: 30, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 200, tips: ["Patlıcanı önceden fırınlamak kızartmaya göre daha hafif bir sonuç verir."], serving: "Pirinç pilavı ile sıcak servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "p39a19_002", title: "Köz kırmızı biberli mercimek çorbası", category: "Çorbalar", ingredients: ["1 su bardağı kırmızı mercimek", "2 köz kırmızı biber", "1 soğan", "1 havuç", "2 yemek kaşığı zeytinyağı", "6 su bardağı sıcak su", "1 tatlı kaşığı tuz, 1 çay kaşığı kimyon"], steps: ["Soğan ve havucu yağda 5 dakika kavurun.", "Mercimek ve biberi ekleyin.", "Su ve tuzla 25 dakika pişirin.", "Blenderdan geçirin.", "Kimyonla servis edin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", tips: ["Köz biber çorbaya dumanlı bir tat verir."], serving: "Limon ve kıtır ekmekle.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "p39a19_003", title: "Kabaklı dereotlu çorba", category: "Çorbalar", ingredients: ["4 kabak", "1 patates", "1 soğan", "2 yemek kaşığı tereyağı", "5 su bardağı sıcak su veya tavuk suyu", "Yarım demet dereotu", "Yarım su bardağı süt", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Soğanı tereyağında 3 dakika kavurun.", "Küp doğranmış kabak ve patatesi ekleyip 5 dakika çevirin.", "Sıcak suyu ve tuzu ekleyip 20 dakika pişirin.", "Blenderdan geçirip sütü ekleyin, 2 dakika kaynatın.", "Kıyılmış dereotuyla servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Patates çorbaya un kullanmadan kıvam verir."], serving: "Sıcak, limonla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a19_012", title: "Zeytinyağlı kabak ve havuç", category: "Sebze yemekleri", ingredients: ["4 kabak", "2 havuç", "1 soğan", "1 domates", "4 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "1 tatlı kaşığı tuz, yarım demet dereotu"], steps: ["Soğanı yağda kavurun.", "Havucu ekleyip 5 dakika pişirin.", "Kabak ve domatesi ekleyin.", "Su ve tuzla kısık ateşte 20 dakika pişirin.", "Dereotuyla soğumaya bırakın."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Zeytinyağlılar tencerede soğutulur."], serving: "Ilık veya soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "p39a19_013", title: "Zeytinyağlı pırasa ve kereviz", category: "Sebze yemekleri", ingredients: ["2 pırasa", "1 kereviz kökü", "1 havuç", "1 soğan", "4 yemek kaşığı zeytinyağı", "1 limon suyu", "1 su bardağı sıcak su", "1 tatlı kaşığı şeker, tuz"], steps: ["Kerevizi küp doğrayıp limonlu suda bekletin.", "Soğanı yağda kavurun, havuç ve kerevizi ekleyip 5 dakika çevirin.", "Pırasayı ekleyin.", "Su, limon, şeker ve tuzla kısık ateşte 25 dakika pişirin.", "Tencerede soğutun."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Limonlu su kerevizin kararmasını önler."], serving: "Soğuk servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "p39a19_021", title: "Mantarlı kekikli tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "200 g mantar", "1 çay kaşığı kekik", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu 2–3 cm kuşbaşı doğrayın; soğanı ince kıyın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Mantarları nemli bezle silip dilimleyin.", "Geniş tavada yağı ısıtıp soğanı 2 dakika çevirin.", "Tavuğu ekleyip yüksek ateşte, her tarafı renk alana kadar 5–6 dakika soteleyin.", "Mantarları ekleyip suyunu salana kadar 3 dakika çevirin.", "Sıcak suyu ekleyin; kapağı kapalı orta-kısık ateşte 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Kekiği son 1–2 dakikada ekleyip harmanlayın.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 38),
  GeneralRecipe(id: "p39a19_022", title: "Kabaklı limonlu tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "1 orta boy kabak", "Yarım limonun suyu", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu 2–3 cm kuşbaşı doğrayın; soğanı ince kıyın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Kabağı yarım ay doğrayın.", "Geniş tavada yağı ısıtıp soğanı 2 dakika çevirin.", "Tavuğu ekleyip yüksek ateşte, her tarafı renk alana kadar 5–6 dakika soteleyin.", "Kabağı ekleyip 2 dakika çevirin.", "Sıcak suyu ekleyin; kapağı kapalı orta-kısık ateşte 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Limon suyunu ocaktan almadan hemen önce ekleyip karıştırın.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_023", title: "Kapya biberli fesleğenli tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "1 büyük kapya biber", "5 yaprak fesleğen", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu 2–3 cm kuşbaşı doğrayın; soğanı ince kıyın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Kapya biberi şerit doğrayın.", "Geniş tavada yağı ısıtıp soğanı 2 dakika çevirin.", "Tavuğu ekleyip yüksek ateşte, her tarafı renk alana kadar 5–6 dakika soteleyin.", "Biberi ekleyip 2 dakika çevirin.", "Sıcak suyu ekleyin; kapağı kapalı orta-kısık ateşte 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Fesleğen yapraklarını elle koparıp ocağı kapattıktan sonra ekleyin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_024", title: "Ispanaklı sarımsaklı tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "200 g ıspanak", "2 diş sarımsak", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu 2–3 cm kuşbaşı doğrayın; soğanı ince kıyın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Ispanağı bol suda yıkayıp iri doğrayın; sarımsağı ezin.", "Geniş tavada yağı ısıtıp soğanı 2 dakika çevirin.", "Tavuğu ekleyip yüksek ateşte, her tarafı renk alana kadar 5–6 dakika soteleyin.", "Ispanağı ekleyip sönene kadar 2 dakika çevirin.", "Sıcak suyu ekleyin; kapağı kapalı orta-kısık ateşte 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Sarımsağı son 1–2 dakikada ekleyip yakmadan harmanlayın.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 37),
  GeneralRecipe(id: "p39a19_025", title: "Brokolili zencefilli tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "200 g brokoli", "1 çay kaşığı taze zencefil", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu 2–3 cm kuşbaşı doğrayın; soğanı ince kıyın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Brokoliyi küçük çiçeklere ayırın; zencefili rendeleyin.", "Geniş tavada yağı ısıtıp soğanı 2 dakika çevirin.", "Tavuğu ekleyip yüksek ateşte, her tarafı renk alana kadar 5–6 dakika soteleyin.", "Brokoliyi ekleyip 2 dakika çevirin.", "Sıcak suyu ekleyin; kapağı kapalı orta-kısık ateşte 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Zencefili son 1–2 dakikada ekleyip harmanlayın.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 37),
  GeneralRecipe(id: "p39a19_026", title: "Havuçlu susamlı tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "2 havuç", "1 yemek kaşığı susam", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu 2–3 cm kuşbaşı doğrayın; soğanı ince kıyın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Havuçları ince yarım ay doğrayın.", "Geniş tavada yağı ısıtıp soğanı 2 dakika çevirin.", "Tavuğu ekleyip yüksek ateşte, her tarafı renk alana kadar 5–6 dakika soteleyin.", "Havucu ekleyip 3 dakika çevirin.", "Sıcak suyu ekleyin; kapağı kapalı orta-kısık ateşte 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Susamı kuru tavada 1–2 dakika kavurup servis ederken üzerine serpin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 38),
  GeneralRecipe(id: "p39a19_027", title: "Pırasalı hardallı tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "1 büyük pırasa", "1 tatlı kaşığı hardal", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu 2–3 cm kuşbaşı doğrayın; soğanı ince kıyın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Pırasayı boyuna yarıp katlarını iyice yıkayın; ince halka doğrayın.", "Geniş tavada yağı ısıtıp soğanı 2 dakika çevirin.", "Tavuğu ekleyip yüksek ateşte, her tarafı renk alana kadar 5–6 dakika soteleyin.", "Pırasayı ekleyip 3 dakika çevirin.", "Sıcak suyu ekleyin; kapağı kapalı orta-kısık ateşte 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Hardalı 2 kaşık pişirme suyuyla açıp son 1–2 dakikada ekleyin.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 38),
  GeneralRecipe(id: "p39a19_028", title: "Domatesli zeytinli tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "2 domates", "8 çekirdeksiz zeytin", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu 2–3 cm kuşbaşı doğrayın; soğanı ince kıyın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Domatesleri küp doğrayın; zeytinleri halka kesin.", "Geniş tavada yağı ısıtıp soğanı 2 dakika çevirin.", "Tavuğu ekleyip yüksek ateşte, her tarafı renk alana kadar 5–6 dakika soteleyin.", "Domatesi ekleyip 3 dakika çevirin.", "Sıcak suyu ekleyin; kapağı kapalı orta-kısık ateşte 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Zeytinleri son 1–2 dakikada ekleyin; zeytin tuzlu olduğundan tuzu azaltın.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 38),
  GeneralRecipe(id: "p39a19_029", title: "Patlıcanlı kimyonlu tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "1 küçük patlıcan", "Yarım çay kaşığı kimyon", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu 2–3 cm kuşbaşı doğrayın; soğanı ince kıyın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Patlıcanı alacalı soyup küp doğrayın; tuzlu suda 15 dakika bekletip sıkın.", "Geniş tavada yağı ısıtıp soğanı 2 dakika çevirin.", "Tavuğu ekleyip yüksek ateşte, her tarafı renk alana kadar 5–6 dakika soteleyin.", "Patlıcanı ekleyip 3 dakika çevirin.", "Sıcak suyu ekleyin; kapağı kapalı orta-kısık ateşte 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Kimyonu son 1–2 dakikada ekleyip harmanlayın.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 53),
  GeneralRecipe(id: "p39a19_030", title: "Bezelyeli dereotlu tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "1 su bardağı bezelye", "4 dal dereotu", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu 2–3 cm kuşbaşı doğrayın; soğanı ince kıyın.", "Çiğ tavuğu ayrı bir kesme tahtasında doğrayın; ardından tahtayı, bıçağı ve ellerinizi sıcak sabunlu suyla yıkayın.", "Dereotunu ince kıyın.", "Geniş tavada yağı ısıtıp soğanı 2 dakika çevirin.", "Tavuğu ekleyip yüksek ateşte, her tarafı renk alana kadar 5–6 dakika soteleyin.", "Bezelyeyi ekleyip 2 dakika çevirin.", "Sıcak suyu ekleyin; kapağı kapalı orta-kısık ateşte 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Dereotunu ocağı kapattıktan sonra ekleyip karıştırın.", "Tavuğun en kalın yerinden kesip kontrol edin: içi pembe kalmamalı, suyu berrak akmalı; termometre varsa iç sıcaklık en az 74°C olmalı.", "Sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_032", title: "Mantarlı kekikli bulgur pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı bulgur", "250 g mantar", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı tereyağı", "1 tatlı kaşığı kekik", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Soğan ve mantarı yağda suyunu çekene kadar soteleyin.", "Kekiği ekleyin.", "Bulguru ekleyip 2 dakika kavurun.", "Su ve tuzla 15 dakika pişirin.", "Tereyağıyla 10 dakika demlendirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Mantarı yüksek ateşte pişirin."], serving: "Yoğurtla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "p39a19_042", title: "Nohutlu avokado domates salatası", category: "Salatalar", ingredients: ["1 avokado", "1,5 su bardağı haşlanmış nohut", "1 su bardağı çeri domates", "Yarım kırmızı soğan", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "1 limon suyu", "1 tatlı kaşığı tuz"], steps: ["Avokadoyu küp doğrayıp limon gezdirin.", "Domatesleri ikiye kesin.", "Soğanı ince doğrayın.", "Zeytinyağı, limon ve tuzla sos yapın.", "Hepsini nazikçe karıştırın."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Avokadoyu en son ekleyin."], serving: "Hemen servis edin.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "p39a19_051", title: "Köz biberli ricottalı makarna", category: "Makarnalar", ingredients: ["350 g penne", "2 köz kırmızı biber", "200 g ricotta veya lor", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 avuç fesleğen yaprağı", "1 tatlı kaşığı tuz"], steps: ["Makarnayı haşlayın.", "Köz biberi şerit doğrayın.", "Sarımsağı yağda çevirip biberi ekleyin.", "Ricottayı biraz haşlama suyuyla kremamsı hâle getirin.", "Makarnayla karıştırıp fesleğenle servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Ricotta sıcakta kolay erir; ateşi kısın."], serving: "Pişer pişmez sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a19_061", title: "Ispanaklı lorlu rulo omlet", category: "Kahvaltılıklar", ingredients: ["4 yumurta", "1 su bardağı ıspanak", "100 g lor", "1 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Ispanağı tereyağında soldurun.", "Yumurtaları tuz ve karabiberle çırpın.", "Geniş tavada ince bir omlet pişirin.", "Üzerine ıspanak ve loru yayın.", "Rulo yapıp dilimleyin."], minutes: 20, servings: 2, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Kısık ateş omletin yırtılmasını önler."], serving: "Sıcak servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "p39a19_072", title: "Kekikli domatesli fırın çipura", category: "Balık ve deniz ürünleri", ingredients: ["2 adet temizlenmiş çipura", "2 domates", "4 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik", "1 limon", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Fırını 200 °C'ye ısıtın.", "Balıkların iki yüzüne çapraz çizikler atın; tuz, karabiber ve kekik sürün.", "Domatesleri ve sarımsağı tepsiye yayıp zeytinyağı gezdirin.", "Balıkları üzerine yerleştirin, içine limon dilimleri koyun.", "25 dakika, gözleri beyazlayıp eti kılçıktan kolay ayrılana kadar pişirin."], minutes: 35, servings: 2, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Çizikler balığın eşit pişmesini sağlar."], serving: "Yeşil salatayla.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "p39a19_073", title: "Zencefilli susamlı fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["4 dilim somon", "2 yemek kaşığı soya sosu", "1 yemek kaşığı bal", "1 tatlı kaşığı rendelenmiş zencefil", "1 diş sarımsak", "1 yemek kaşığı susam", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 200 °C'ye ısıtın.", "Soya sosu, bal, zencefil, sarımsak ve yağı karıştırın.", "Somonları sosla 10 dakika marine edin.", "Tepsiye dizip susam serpin.", "12–15 dakika pişirin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 200, tips: ["Soya sosu tuzludur; ayrıca tuz eklemeyin."], serving: "Pilav ve buharda sebzeyle.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "p39a19_081", title: "Mantarlı arpacık soğanlı dana güveç", category: "Et yemekleri", ingredients: ["500 g kuşbaşı dana eti", "250 g kültür mantarı (ikiye bölünmüş)", "12 arpacık soğan (soyulmuş)", "2 havuç (iri halka)", "2 domates (rendelenmiş)", "1 yemek kaşığı domates salçası", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su", "2 defne yaprağı", "1 çay kaşığı kekik", "1,5 çay kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Eti kâğıt havluyla kurulayın; tencerede zeytinyağını yüksek ateşte ısıtıp eti iki partide her yüzü kızarana kadar mühürleyin.", "Arpacık soğanları ve sarımsağı ekleyip 3 dakika çevirin; salçayı ekleyip 1 dakika kavurun.", "Rendelenmiş domates, sıcak su ve defne yaprağını ekleyin; kapağı kapalı kısık ateşte 50 dakika pişirin.", "Fırını 180 °C'ye ısıtın; eti ve suyunu güveç kabına aktarın.", "Mantar ve havucu ekleyin; tuz, karabiber ve kekikle tatlandırıp kabı kapatarak fırında 40–45 dakika, et lokum gibi olana kadar pişirin.", "Defne yapraklarını çıkarıp 10 dakika dinlendirerek servis edin."], minutes: 120, servings: 4, prepMinutes: 20, cookMinutes: 100, difficulty: "Orta", ovenCelsius: 180, tips: ["Eti tencerede kalabalık etmeyin; aksi hâlde mühürlenmez, suyunu salıp haşlanır.", "Tuzu pişirmenin ortasında ekleyin ki et sertleşmesin."], serving: "Pirinç pilavı veya fırın patates ile sıcak servis edin.", storage: "Buzdolabında 3 gün, dondurucuda 3 ay saklanır."),
  GeneralRecipe(id: "p39a19_082", title: "Patlıcanlı dana güveç", category: "Et yemekleri", ingredients: ["500 g kuşbaşı dana eti", "2 patlıcan", "2 domates", "2 biber", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Eti yağda suyunu çekene kadar kavurun.", "Soğan ve salçayı ekleyin.", "Güvece eti ve doğranmış sebzeleri yerleştirin.", "1 su bardağı sıcak su ekleyip üzerini kapatın.", "180 °C fırında 90 dakika pişirin."], minutes: 110, servings: 4, prepMinutes: 20, cookMinutes: 90, difficulty: "Orta", ovenCelsius: 180, tips: ["Güveci soğuk fırına koyun; çatlamaz."], serving: "Pilavla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "p39a19_083", title: "Bamyalı limonlu dana güveç", category: "Et yemekleri", ingredients: ["500 g kuşbaşı dana", "400 g bamya", "2 domates", "1 soğan", "1 limon suyu", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Bamyaların başını kozalak gibi yontup limonlu suda bekletin.", "Eti yağda kavurun, soğanı ekleyin.", "Güvece et, bamya ve domatesi yerleştirin.", "1 su bardağı sıcak su ve limon suyunu ekleyip kapatın.", "180 °C'de 90 dakika pişirin."], minutes: 110, servings: 4, prepMinutes: 20, cookMinutes: 90, difficulty: "Orta", ovenCelsius: 180, tips: ["Limon bamyanın salyalanmasını azaltır."], serving: "Pilavla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "p39a19_091", title: "Köz patlıcanlı yoğurtlu meze (alinazik usulü)", category: "Mezeler", ingredients: ["3 patlıcan", "1,5 su bardağı süzme yoğurt", "2 diş sarımsak", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı pul biber", "1 tatlı kaşığı tuz"], steps: ["Patlıcanları közleyip soyun ve ezin.", "Sarımsaklı yoğurdu hazırlayın.", "Patlıcanı yoğurtla karıştırın.", "Tereyağını kızdırıp pul biber ekleyin.", "Mezeye gezdirin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Ilık da servis edilebilir."], serving: "Soğuk servis edin; ekmekle sunun.", storage: "Buzdolabında 2–3 gün saklanır."),
  GeneralRecipe(id: "p39a19_111", title: "Ispanaklı lorlu börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g ıspanak", "120 g lor peyniri", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Ispanağı yıkayıp doğrayın; tavada suyunu çektirip soğutun.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 55),
  GeneralRecipe(id: "p39a19_112", title: "Pırasalı beyaz peynirli börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g pırasa", "120 g beyaz peynir", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Pırasayı ince doğrayıp yağda 6-8 dakika yumuşatın ve soğutun.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 63),
  GeneralRecipe(id: "p39a19_113", title: "Patatesli dereotlu börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g patates", "120 g beyaz peynir ve 2 yemek kaşığı dereotu", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Patatesleri haşlayıp ezin; ince kıyılmış dereotuyla karıştırın.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 55),
  GeneralRecipe(id: "p39a19_114", title: "Mantarlı kaşarlı börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g mantar", "120 g rendelenmiş kaşar", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Mantarları ince doğrayıp tavada suyunu tamamen çektirin; soğutun.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 55),
  GeneralRecipe(id: "p39a19_115", title: "Kabaklı naneli börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g kabak", "120 g lor ve 1 tatlı kaşığı kuru nane", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Kabağı rendeleyip suyunu sıkın; naneyle kısa süre soteleyip soğutun.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 55),
  GeneralRecipe(id: "p39a19_116", title: "Patlıcanlı lorlu börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g patlıcan", "120 g lor peyniri", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Patlıcanı küçük küp doğrayıp yağda yumuşayana kadar soteleyin; soğutun.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 55),
  GeneralRecipe(id: "p39a19_117", title: "Brokolili peynirli börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g brokoli", "120 g beyaz peynir", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Brokoliyi küçük doğrayıp 5 dakika buharda pişirin; süzerek soğutun.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 60),
  GeneralRecipe(id: "p39a19_118", title: "Havuçlu çökelekli börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g havuç", "120 g çökelek", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Havucu rendeleyip tavada 4 dakika soteleyin; soğutun.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 59),
  GeneralRecipe(id: "p39a19_119", title: "Köz biberli lorlu börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g közlenmiş kırmızı biber", "120 g lor peyniri", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Közlenmiş biberi süzüp ince doğrayın; fazla suyunu alın.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 55),
  GeneralRecipe(id: "p39a19_120", title: "Pazılı beyaz peynirli börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g pazı", "120 g beyaz peynir", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Pazıyı yıkayıp doğrayın; tavada suyunu çektirip soğutun.", "Gebelikte pastörize sütten yapılmış peynir kullanın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin.", "Bir dilimi kesip kontrol edin: içteki yumurtalı harç tamamen pişmiş, ıslak kısım kalmamış olmalı.", "Fırından alıp 10 dakika dinlendirin; dilimlemesi kolaylaşır."], minutes: 55),
  GeneralRecipe(id: "p39a19_121", title: "Nohutlu ıspanak yemeği", category: "Bakliyat yemekleri", ingredients: ["500 g ıspanak", "1 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Soğanı yağda kavurun, salçayı ekleyin.", "Nohudu ekleyip 2 dakika çevirin.", "Doğranmış ıspanak ve suyu ekleyin.", "15 dakika pişirin.", "Yoğurtla servis edin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Ispanağı birkaç suda yıkayın."], serving: "Yoğurtla sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a19_122", title: "Yeşil mercimekli kabak yemeği", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı yeşil mercimek", "2 kabak", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz, 1 çay kaşığı kuru nane"], steps: ["Mercimeği 15 dakika ön haşlayın.", "Soğanı yağda kavurup salçayı ekleyin.", "Mercimek ve suyu ekleyip 10 dakika pişirin.", "Küp kabakları ekleyip 10 dakika daha pişirin.", "Naneyle servis edin."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Kabağı geç ekleyin; dağılmasın."], serving: "Yoğurtla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "p39a19_131", title: "Kabaklı patatesli fırın tepsi", category: "Sebze yemekleri", ingredients: ["3 patates (iri küp)", "2 kabak (iri küp)", "1 kırmızı soğan (iri doğranmış)", "1 kırmızı kapya biber", "8 cherry domates", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik", "1 çay kaşığı tatlı toz biber", "1 çay kaşığı tuz", "2 diş sarımsak"], steps: ["Fırını 200 °C'ye ısıtın.", "Patatesleri zeytinyağının yarısı, tuz ve toz biberle harmanlayıp tepsiye yayın; 15 dakika ön pişirin.", "Kabak, soğan, biber ve sarımsağı kalan zeytinyağı ve kekikle harmanlayın.", "Ön pişmiş patateslerin arasına bu sebzeleri ve cherry domatesleri ekleyin.", "Fırında 25 dakika, sebzeler kızarana kadar, yarısında bir kez karıştırarak pişirin.", "Sıcak servis edin."], minutes: 55, servings: 4, prepMinutes: 15, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 200, tips: ["Patates kabaktan uzun piştiği için önce fırına girmelidir."], serving: "Yoğurt veya ızgara etin yanında servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "p39a19_132", title: "Patlıcanlı biberli fırın tepsi", category: "Sebze yemekleri", ingredients: ["3 patlıcan", "3 biber", "2 domates", "1 soğan", "4 diş sarımsak", "4 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, 1 çay kaşığı kekik"], steps: ["Fırını 200 °C'ye ısıtın.", "Sebzeleri iri doğrayın.", "Yağ, tuz ve kekikle harmanlayın.", "Tepsiye yayın.", "40 dakika pişirin."], minutes: 55, servings: 4, prepMinutes: 15, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 200, tips: ["Tek kat yayın; buharda pişmesin."], serving: "Yoğurtla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a19_133", title: "Karnabaharlı havuçlu fırın tepsi", category: "Sebze yemekleri", ingredients: ["1 karnabahar", "3 havuç", "1 kırmızı soğan", "4 yemek kaşığı zeytinyağı", "1 tatlı kaşığı zerdeçal", "1 tatlı kaşığı kimyon", "1 tatlı kaşığı tuz"], steps: ["Fırını 210 °C'ye ısıtın.", "Karnabaharı çiçeklere, havucu çubuklara ayırın.", "Yağ ve baharatlarla harmanlayın.", "Tek kat yayın.", "35 dakika pişirin."], minutes: 50, servings: 4, prepMinutes: 15, cookMinutes: 35, difficulty: "Kolay", ovenCelsius: 210, tips: ["Zerdeçal güzel bir renk verir."], serving: "Yoğurtla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "p39a19_141", title: "Muzlu çilekli smoothie", category: "İçecekler", ingredients: ["1 küçük muz", "5 çilek", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Çilekleri yıkayıp saplarını ayıklayın; muzu soyup dilimleyin.", "Muz, çilek ve sütü blendera alın.", "Pürüzsüz olana kadar 30–45 saniye karıştırın.", "İsterseniz buz ekleyip yeniden kısa süre karıştırın ve hemen servis edin.", "Hazırlar hazırlamaz için; bekletirseniz ayrışır ve vitamin kaybı olur.", "1 yaş altı bebeklere inek sütü ve bal içecek olarak verilmez; küçük çocuklara buzsuz verin."], minutes: 10),
  GeneralRecipe(id: "p39a19_142", title: "Yaban mersinli yoğurtlu smoothie", category: "İçecekler", ingredients: ["Yarım su bardağı yaban mersini", "1 su bardağı yoğurt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Yaban mersinlerini yıkayıp süzün.", "Yaban mersinlerini yoğurtla birlikte blendera alın.", "Kıvam pürüzsüz olana kadar karıştırın; çok koyuysa az miktarda içme suyu ekleyin.", "İsteğe bağlı buzla soğuk servis edin.", "Hazırlar hazırlamaz için; bekletirseniz ayrışır ve vitamin kaybı olur.", "1 yaş altı bebeklere inek sütü ve bal içecek olarak verilmez; küçük çocuklara buzsuz verin."], minutes: 10),
  GeneralRecipe(id: "p39a19_143", title: "Şeftalili yulaflı smoothie", category: "İçecekler", ingredients: ["1 olgun şeftali", "2 yemek kaşığı yulaf", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Şeftaliyi yıkayıp çekirdeğini çıkarın ve dilimleyin.", "Yulafı sütle birlikte blendera koyup 20 saniye karıştırın.", "Şeftaliyi ekleyip pürüzsüz olana kadar çekin.", "İsteğe bağlı buz ekleyerek hemen servis edin.", "Hazırlar hazırlamaz için; bekletirseniz ayrışır ve vitamin kaybı olur.", "1 yaş altı bebeklere inek sütü ve bal içecek olarak verilmez; küçük çocuklara buzsuz verin."], minutes: 10),
  GeneralRecipe(id: "p39a19_144", title: "Mangolu kefirli smoothie", category: "İçecekler", ingredients: ["Yarım olgun mango", "1 su bardağı kefir", "3–4 buz küpü (isteğe bağlı)"], steps: ["Mangonun kabuğunu ve çekirdeğini ayırıp meyveyi doğrayın.", "Mango parçaları ile kefiri blendera alın.", "Pürüzsüz bir kıvam elde edene kadar 30–45 saniye karıştırın.", "İsterseniz buz ekleyip soğuk servis edin.", "Hazırlar hazırlamaz için; bekletirseniz ayrışır ve vitamin kaybı olur.", "1 yaş altı bebeklere inek sütü ve bal içecek olarak verilmez; küçük çocuklara buzsuz verin."], minutes: 10),
  GeneralRecipe(id: "p39a19_145", title: "Armutlu tarçınlı smoothie", category: "İçecekler", ingredients: ["1 armut", "Yarım çay kaşığı tarçın", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Armudu yıkayın, çekirdeğini çıkarın ve küçük parçalara ayırın.", "Armut, süt ve tarçını blendera ekleyin.", "Armut tamamen parçalanana kadar karıştırın.", "İsteğe bağlı buz ekleyip bekletmeden servis edin.", "Hazırlar hazırlamaz için; bekletirseniz ayrışır ve vitamin kaybı olur.", "1 yaş altı bebeklere inek sütü ve bal içecek olarak verilmez; küçük çocuklara buzsuz verin."], minutes: 10),
  GeneralRecipe(id: "p39a19_146", title: "Elmalı yulaflı smoothie", category: "İçecekler", ingredients: ["1 elma", "2 yemek kaşığı yulaf", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Elmayı yıkayın, çekirdeğini çıkarın ve doğrayın.", "Yulafı sütle blenderda kısa süre karıştırın.", "Elma parçalarını ekleyip pürüzsüz olana kadar çekin.", "İsteğe bağlı buz ekleyin ve hemen servis edin.", "Hazırlar hazırlamaz için; bekletirseniz ayrışır ve vitamin kaybı olur.", "1 yaş altı bebeklere inek sütü ve bal içecek olarak verilmez; küçük çocuklara buzsuz verin."], minutes: 10),
  GeneralRecipe(id: "p39a19_147", title: "Ananaslı naneli smoothie", category: "İçecekler", ingredients: ["1 su bardağı doğranmış ananas", "4 yaprak nane", "1 su bardağı su", "3–4 buz küpü (isteğe bağlı)"], steps: ["Ananas parçalarını hazırlayın; taze naneyi yıkayın.", "Ananası ve suyu blenderda karıştırın.", "Nane yapraklarını ekleyip 10–15 saniye daha çekin.", "İsteğe bağlı buzla soğuk servis edin.", "Lifli kısımlar rahatsız ederse ince süzgeçten geçirin.", "Hazırlar hazırlamaz için; bekletirseniz ayrışır ve vitamin kaybı olur."], minutes: 10),
  GeneralRecipe(id: "p39a19_148", title: "Böğürtlenli muzlu smoothie", category: "İçecekler", ingredients: ["Yarım su bardağı böğürtlen", "1 küçük muz", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Böğürtlenleri yıkayıp süzün, muzu soyun.", "Böğürtlen, muz ve sütü blendera alın.", "Pürüzsüz olana kadar 30–45 saniye karıştırın.", "İsterseniz buz ekleyip hemen servis edin.", "Hazırlar hazırlamaz için; bekletirseniz ayrışır ve vitamin kaybı olur.", "1 yaş altı bebeklere inek sütü ve bal içecek olarak verilmez; küçük çocuklara buzsuz verin."], minutes: 10),
  GeneralRecipe(id: "p39a19_149", title: "Kayısılı yoğurtlu smoothie", category: "İçecekler", ingredients: ["3 olgun kayısı", "1 su bardağı yoğurt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Kayısıları yıkayın, çekirdeklerini çıkarıp doğrayın.", "Kayısı ve yoğurdu blendera alın.", "Homojen ve akışkan bir kıvam elde edene kadar karıştırın.", "İsteğe bağlı buz ekleyip soğuk servis edin.", "Hazırlar hazırlamaz için; bekletirseniz ayrışır ve vitamin kaybı olur.", "1 yaş altı bebeklere inek sütü ve bal içecek olarak verilmez; küçük çocuklara buzsuz verin."], minutes: 10),
  GeneralRecipe(id: "p39a19_150", title: "Kivili muzlu smoothie", category: "İçecekler", ingredients: ["2 kivi", "1 küçük muz", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Kivileri soyup dilimleyin, muzu soyun.", "Kivi, muz ve sütü blendera ekleyin.", "Pürüzsüz olana kadar 30–45 saniye karıştırın.", "İsteğe bağlı buzla bekletmeden servis edin.", "Hazırlar hazırlamaz için; bekletirseniz ayrışır ve vitamin kaybı olur.", "1 yaş altı bebeklere inek sütü ve bal içecek olarak verilmez; küçük çocuklara buzsuz verin."], minutes: 10),
  GeneralRecipe(id: "n01_001", title: "Menemen", category: "Pratik tarifler", ingredients: ["3 domates", "2 sivri biber", "4 yumurta", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz", "1 tutam pul biber"], steps: ["Biberleri ince doğrayıp yağda 4 dakika yumuşatın.", "Domatesi kabuğunu soyup küp doğrayın, ekleyip suyunu çekene kadar 5 dakika pişirin.", "Tuz ve pul biberi ekleyin.", "Yumurtaları kırıp hafifçe karıştırın.", "Yumurta istediğiniz kıvama gelince ocaktan alın."], minutes: 17, servings: 2, prepMinutes: 5, cookMinutes: 12, difficulty: "Kolay", tips: ["Soğanlı yapacaksanız biberle birlikte kavurun."], serving: "Sıcak ekmekle hemen.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_002", title: "Sucuklu yumurta", category: "Pratik tarifler", ingredients: ["8 dilim sucuk", "4 yumurta", "1 tatlı kaşığı tereyağı", "1 tutam karabiber"], steps: ["Sucuğun zarını soyup ince dilimleyin.", "Tavada tereyağını eritip sucukları 2 dakika çevirin.", "Yumurtaları sucukların arasına kırın.", "Kapağı kapatıp 3–4 dakika, beyazlar pişene kadar pişirin.", "Karabiber serpip servis edin."], minutes: 8, servings: 2, prepMinutes: 2, cookMinutes: 6, difficulty: "Kolay", tips: ["Sucuk yağlı olduğundan tereyağını az kullanın."], serving: "Sıcak, ekmekle.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_003", title: "Kaşarlı tost", category: "Pratik tarifler", ingredients: ["4 dilim tost ekmeği", "4 dilim kaşar peyniri", "1 domates", "1 tatlı kaşığı tereyağı", "1 çay kaşığı taze kekik yaprağı"], steps: ["Ekmeklerin dış yüzüne ince tereyağı sürün.", "İç yüzlere kaşar ve ince domates dilimleri koyup kekik serpin.", "Ekmekleri kapatın.", "Tost makinesinde veya tavada her yüzü 3 dakika kızartın.", "Çapraz kesip servis edin."], minutes: 11, servings: 2, prepMinutes: 5, cookMinutes: 6, difficulty: "Kolay", tips: ["Domatesin suyunu kâğıtla alın; tost ıslanmaz."], serving: "Çay veya ayranla.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_004", title: "Yumurtalı ekmek", category: "Pratik tarifler", ingredients: ["4 dilim bayat ekmek", "2 yumurta", "Yarım su bardağı süt", "Yarım çay kaşığı tuz", "2 yemek kaşığı sıvı yağ"], steps: ["Yumurta, süt ve tuzu çırpın.", "Ekmekleri karışıma her iki yüzü ıslanacak şekilde batırın.", "Tavada yağı kızdırın.", "Ekmekleri her yüzü 2 dakika, altın rengi olana kadar kızartın.", "Kâğıt havluya alıp servis edin."], minutes: 13, servings: 2, prepMinutes: 5, cookMinutes: 8, difficulty: "Kolay", tips: ["Bayat ekmek daha iyi emer ve dağılmaz."], serving: "Beyaz peynir ve domatesle.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_005", title: "Peynirli gözleme (tavada)", category: "Pratik tarifler", ingredients: ["2 adet yufka", "150 g beyaz peynir", "Yarım demet maydanoz", "2 yemek kaşığı tereyağı", "Yarım su bardağı ayran"], steps: ["Peyniri ezip kıyılmış maydanozla karıştırın.", "Yufkayı dörde katlanacak şekilde serip ayranla hafifçe ıslatın.", "Ortaya harcı koyup kenarlarını kapatarak zarf yapın.", "Tereyağlı tavada her yüzünü 3–4 dakika kızartın.", "Dilimleyip servis edin."], minutes: 25, servings: 2, prepMinutes: 15, cookMinutes: 10, difficulty: "Kolay", tips: ["Ayran yufkayı yumuşatır."], serving: "Sıcak, ayranla.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_006", title: "Ton balıklı sandviç", category: "Pratik tarifler", ingredients: ["1 kutu ton balığı", "2 yemek kaşığı yoğurt", "1 yemek kaşığı mısır", "1 küçük turşu salatalık", "4 dilim tam buğday ekmeği", "3–4 yaprak marul"], steps: ["Ton balığının yağını süzün.", "Yoğurt, mısır ve doğranmış turşuyla karıştırın.", "Ekmeklere marul yerleştirin.", "Ton karışımını yayıp kapatın.", "İkiye kesip servis edin."], minutes: 10, servings: 2, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Mayonez yerine yoğurt daha hafiftir."], serving: "Beslenme çantası için uygun.", storage: "Buzdolabında aynı gün."),
  GeneralRecipe(id: "n01_007", title: "Patatesli yumurta", category: "Pratik tarifler", ingredients: ["2 orta boy patates", "3 yumurta", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz", "1 tutam pul biber"], steps: ["Patatesleri küçük küp doğrayın.", "Yağda kapağı kapalı 10 dakika, yumuşayana kadar pişirin.", "Tuz ve pul biberi ekleyin.", "Yumurtaları üzerine kırıp karıştırın.", "Yumurta pişince servis edin."], minutes: 20, servings: 2, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", tips: ["Kapak patatesin buharda yumuşamasını hızlandırır."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_008", title: "Pratik mercimek çorbası (20 dakika)", category: "Pratik tarifler", ingredients: ["1 su bardağı kırmızı mercimek", "1 havuç", "1 soğan", "1 yemek kaşığı tereyağı", "5 su bardağı sıcak su", "1 tatlı kaşığı tuz", "1 çay kaşığı kimyon"], steps: ["Soğan ve havucu rendeleyin.", "Tereyağında 2 dakika kavurun.", "Yıkanmış mercimek, su ve tuzu ekleyip 18 dakika pişirin.", "Blenderdan geçirin.", "Kimyon ekleyip servis edin."], minutes: 25, servings: 4, prepMinutes: 5, cookMinutes: 20, difficulty: "Kolay", tips: ["Rendelenmiş sebzeler daha çabuk pişer."], serving: "Limonla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n01_009", title: "Fırında patates kumpir (mikrodalgasız)", category: "Pratik tarifler", ingredients: ["2 büyük patates", "2 yemek kaşığı tereyağı", "1 su bardağı rendelenmiş kaşar", "4 yemek kaşığı mısır", "4 yemek kaşığı rus salatası veya turşu", "1 çay kaşığı tuz"], steps: ["Patatesleri yıkayıp çatalla delin, folyoya sarın.", "200 °C fırında 50–55 dakika pişirin.", "Ortadan yarıp içini tereyağı, tuz ve kaşarla karıştırın.", "Mısır ve salata ile doldurun.", "Sıcak servis edin."], minutes: 65, servings: 2, prepMinutes: 10, cookMinutes: 55, difficulty: "Kolay", ovenCelsius: 200, tips: ["Şiş kolayca giriyorsa patates pişmiştir."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_010", title: "Domates çorbası (pratik)", category: "Pratik tarifler", ingredients: ["4 domates (rendelenmiş)", "1 yemek kaşığı salça", "2 yemek kaşığı un", "2 yemek kaşığı tereyağı", "4 su bardağı sıcak su", "1 su bardağı süt", "1 tatlı kaşığı tuz"], steps: ["Tereyağında unu 2 dakika kavurun.", "Salça ve domatesi ekleyip 3 dakika pişirin.", "Suyu çırparak ekleyin, 12 dakika kaynatın.", "Sütü ekleyip 2 dakika daha pişirin.", "Rendelenmiş kaşarla servis edin."], minutes: 25, servings: 4, prepMinutes: 5, cookMinutes: 20, difficulty: "Kolay", tips: ["Unu kavurmak çiğ un kokusunu giderir."], serving: "Kıtır ekmekle.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n01_011", title: "Tavada pizza ekmeği", category: "Pratik tarifler", ingredients: ["2 pide veya lavaş", "4 yemek kaşığı domates sosu", "1 su bardağı rendelenmiş kaşar", "6 dilim sucuk veya salam", "1 biber", "1 çay kaşığı kekik"], steps: ["Pideleri tavaya yerleştirin.", "Domates sosunu sürün.", "Kaşar, sucuk ve biberi dizip kekik serpin.", "Kapağı kapalı kısık ateşte 8–10 dakika peynir eriyene kadar pişirin.", "Dilimleyip servis edin."], minutes: 20, servings: 2, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Kapak peynirin fırın gibi erimesini sağlar."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_012", title: "Yoğurtlu makarna", category: "Pratik tarifler", ingredients: ["300 g burgu makarna", "1,5 su bardağı yoğurt", "2 diş sarımsak", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı pul biber", "1 tatlı kaşığı tuz"], steps: ["Makarnayı tuzlu suda haşlayıp süzün.", "Yoğurdu ezilmiş sarımsakla çırpın.", "Makarnayı tabağa alıp yoğurdu üzerine dökün.", "Tereyağını kızdırıp pul biberi ekleyin.", "Makarnanın üzerine gezdirin."], minutes: 17, servings: 4, prepMinutes: 5, cookMinutes: 12, difficulty: "Kolay", tips: ["Yoğurt oda sıcaklığında olursa makarna soğumaz."], serving: "Hemen servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_013", title: "Kıymalı pide tost", category: "Pratik tarifler", ingredients: ["2 pide", "150 g kıyma", "1 küçük soğan", "1 domates", "1 yemek kaşığı salça", "1 çay kaşığı tuz, karabiber"], steps: ["Kıymayı soğanla kavurun.", "Domates ve salçayı ekleyip suyunu çekene kadar 5 dakika pişirin.", "Pideleri ortadan açıp harcı yayın.", "Tavada üzerine ağırlık koyarak her yüzü 2 dakika kızartın.", "Dilimleyin."], minutes: 22, servings: 2, prepMinutes: 10, cookMinutes: 12, difficulty: "Kolay", tips: ["Harç sulu olmamalı."], serving: "Ayranla.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_014", title: "Peynirli bazlama tostu", category: "Pratik tarifler", ingredients: ["2 bazlama", "100 g beyaz peynir", "4 dilim kaşar", "1 domates", "Yarım demet maydanoz"], steps: ["Bazlamaları ikiye ayırın.", "Ezilmiş beyaz peynir ve maydanozu sürün.", "Kaşar ve domatesi yerleştirip kapatın.", "Tavada her yüzü 3 dakika ısıtın.", "Dilimleyip servis edin."], minutes: 13, servings: 2, prepMinutes: 5, cookMinutes: 8, difficulty: "Kolay", tips: ["Bazlamayı fazla bastırmayın; yumuşak kalsın."], serving: "Çayla.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_015", title: "Hızlı nohut salatası", category: "Pratik tarifler", ingredients: ["2 su bardağı haşlanmış nohut", "1 domates", "1 salatalık", "Yarım kırmızı soğan", "3 yemek kaşığı zeytinyağı", "1 limon suyu", "1 tatlı kaşığı tuz, kimyon"], steps: ["Nohutları süzün.", "Sebzeleri küp doğrayın.", "Zeytinyağı, limon, tuz ve kimyonla sos hazırlayın.", "Hepsini karıştırın.", "Servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Hazır haşlanmış nohutu yıkayıp kullanın."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n01_016", title: "Tavuklu dürüm (pratik)", category: "Pratik tarifler", ingredients: ["200 g tavuk göğsü (şerit)", "2 lavaş", "1 domates", "3–4 yaprak marul", "3 yemek kaşığı yoğurt", "1 çay kaşığı tuz, kekik, tatlı toz biber", "1 yemek kaşığı zeytinyağı"], steps: ["Tavuğu baharatlarla harmanlayın.", "Yağda yüksek ateşte 8 dakika pişirin.", "Lavaşı ısıtın, yoğurt sürün.", "Tavuk, marul ve domatesi yerleştirip sarın.", "İkiye kesin."], minutes: 20, servings: 2, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Tavuğu ince şerit kesmek pişme süresini kısaltır."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_017", title: "Mısır gevrekli yoğurt kasesi", category: "Pratik tarifler", ingredients: ["1 su bardağı yoğurt", "3 yemek kaşığı şekersiz mısır gevreği", "1 muz", "1 tatlı kaşığı bal", "1 yemek kaşığı ceviz"], steps: ["Yoğurdu kaseye alın.", "Muzu dilimleyin.", "Muz ve cevizi ekleyin.", "Balı gezdirin.", "Gevreği en son ekleyip hemen yiyin."], minutes: 3, servings: 1, prepMinutes: 3, cookMinutes: 0, difficulty: "Kolay", tips: ["Gevrek yumuşamasın diye en son ekleyin."], serving: "Kahvaltıda.", storage: "Hemen tüketin."),
  GeneralRecipe(id: "n01_018", title: "Fırında sosisli patates", category: "Pratik tarifler", ingredients: ["4 patates", "6 sosis", "1 soğan", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, kekik, tatlı toz biber"], steps: ["Fırını 210 °C'ye ısıtın.", "Patatesleri küp, sosisleri halka, soğanı iri doğrayın.", "Yağ ve baharatlarla harmanlayın.", "Tepsiye yayın.", "30 dakika, yarısında karıştırarak pişirin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 210, tips: ["Tek kat yayın; patatesler kızarır."], serving: "Ketçap veya yoğurtla.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n01_019", title: "Pratik sebzeli erişte", category: "Pratik tarifler", ingredients: ["300 g erişte", "1 havuç", "1 kabak", "1 biber", "2 yemek kaşığı soya sosu", "2 yemek kaşığı sıvı yağ", "1 diş sarımsak"], steps: ["Erişteyi haşlayıp süzün.", "Sebzeleri jülyen doğrayın.", "Yağda sarımsak ve sebzeleri yüksek ateşte 4 dakika çevirin.", "Erişte ve soya sosunu ekleyin.", "2 dakika karıştırıp servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Sebzeler diri kalmalı."], serving: "Sıcak.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n01_020", title: "Avokadolu yumurtalı tost", category: "Pratik tarifler", ingredients: ["1 dilim tam buğday ekmeği", "Yarım avokado", "1 yumurta", "1 tatlı kaşığı limon suyu", "1 tutam tuz, pul biber"], steps: ["Ekmeği kızartın.", "Avokadoyu limon ve tuzla ezin.", "Yumurtayı tavada 3–4 dakika pişirin.", "Ekmeğe avokadoyu sürüp yumurtayı yerleştirin.", "Pul biber serpin."], minutes: 10, servings: 1, prepMinutes: 5, cookMinutes: 5, difficulty: "Kolay", tips: ["Yumurtayı kayısı kıvamında bırakabilirsiniz."], serving: "Kahvaltıda.", storage: "Hemen tüketin."),
  GeneralRecipe(id: "n01_101", title: "Ev yapımı limonata", category: "İçecekler", ingredients: ["6 limon", "1 su bardağı şeker", "6 su bardağı soğuk su", "4–5 dal nane", "1 su bardağı buz"], steps: ["Limonların kabuğunu rendeleyin, şekerle ovun.", "Limonları sıkın.", "Şekerli kabuğa 1 bardak ılık su ekleyip şeker eriyene kadar karıştırın.", "Limon suyu ve kalan suyu ekleyin, süzün.", "Nane ve buzla servis edin."], minutes: 15, servings: 6, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Kabuğu şekerle ovmak aromayı artırır."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n01_102", title: "Ayran", category: "İçecekler", ingredients: ["2 su bardağı yoğurt", "2 su bardağı soğuk su", "1 çay kaşığı tuz"], steps: ["Yoğurdu kaba alın.", "Tuzu ekleyin.", "Suyu azar azar ekleyerek çırpın.", "Köpürene kadar 1 dakika çırpın.", "Soğuk servis edin."], minutes: 5, servings: 4, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Blender daha köpüklü yapar."], serving: "Soğuk servis edin.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n01_103", title: "Naneli limonlu soda", category: "İçecekler", ingredients: ["1 limon", "6 yaprak nane", "2 tatlı kaşığı bal", "2 şişe sade soda", "1 su bardağı buz"], steps: ["Naneyi bardakta hafifçe ezin.", "Limon suyu ve balı ekleyip karıştırın.", "Buz ekleyin.", "Sodayı yavaşça dökün.", "Limon dilimiyle süsleyin."], minutes: 5, servings: 2, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Sodayı en son ekleyin; gazı kaçmaz."], serving: "Soğuk servis edin.", storage: "Hemen tüketin; buzdolabında en fazla 12 saat."),
  GeneralRecipe(id: "n01_104", title: "Ev yapımı vişne şerbeti", category: "İçecekler", ingredients: ["2 su bardağı vişne", "1 su bardağı şeker", "5 su bardağı su", "1 çubuk tarçın"], steps: ["Vişne, şeker, tarçın ve 2 bardak suyu 10 dakika kaynatın.", "Ocaktan alıp ezin.", "Süzün.", "Kalan soğuk suyu ekleyin.", "Buzdolabında soğutup servis edin."], minutes: 10, servings: 6, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Çekirdekli vişne de kullanılabilir; süzerken ayrılır."], serving: "Soğuk servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n01_105", title: "Soğuk ıhlamur çayı (ballı)", category: "İçecekler", ingredients: ["2 yemek kaşığı ıhlamur", "4 su bardağı kaynar su", "2 yemek kaşığı bal", "1 limon dilimi", "1 su bardağı buz"], steps: ["Ihlamuru kaynar suda 10 dakika demleyin.", "Süzün.", "Ilıyınca balı ekleyin.", "Soğutun.", "Buz ve limonla servis edin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Balı kaynar suya eklemeyin; aroması kaybolur."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n01_106", title: "Ev yapımı buzlu çay (şeftalili)", category: "İçecekler", ingredients: ["2 poşet siyah çay", "4 su bardağı su", "2 şeftali", "3 yemek kaşığı şeker", "Yarım limon"], steps: ["Çayı kaynar suda 5 dakika demleyin.", "Şekeri eritip soğutun.", "Şeftaliyi blenderdan geçirip süzün.", "Çay, şeftali ve limonu karıştırın.", "Buzla servis edin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Çayı fazla demlemeyin; acılaşır."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n01_107", title: "Sıcak salep (evde)", category: "İçecekler", ingredients: ["2 su bardağı süt", "1 yemek kaşığı salep tozu", "2 yemek kaşığı şeker", "1 çay kaşığı tarçın"], steps: ["Salep ve şekeri soğuk sütte çırpın.", "Orta ateşte sürekli karıştırarak ısıtın.", "Kaynayınca 3 dakika koyulaşana kadar pişirin.", "Fincanlara alın.", "Tarçın serpip sıcak servis edin."], minutes: 10, servings: 2, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Sürekli karıştırmak topaklanmayı önler."], serving: "Soğuk servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_108", title: "Sıcak çikolata", category: "İçecekler", ingredients: ["2 su bardağı süt", "50 g bitter çikolata", "1 yemek kaşığı kakao", "1 yemek kaşığı şeker"], steps: ["Sütü ısıtın.", "Kakao ve şekeri ekleyin.", "Doğranmış çikolatayı ekleyip eriyene kadar karıştırın.", "Telle köpürtün.", "Sıcak servis edin."], minutes: 10, servings: 2, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Sütü kaynatmayın; kaymak bağlar."], serving: "Soğuk servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_109", title: "Zencefilli limonlu bitki çayı", category: "İçecekler", ingredients: ["1 parmak taze zencefil", "Yarım limon", "2 su bardağı su", "1 tatlı kaşığı bal"], steps: ["Zencefili ince dilimleyin.", "Suyla 5 dakika kaynatın.", "Ocaktan alıp 5 dakika demleyin.", "Süzüp limon sıkın.", "Ilıyınca bal ekleyin."], minutes: 10, servings: 2, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Hamilelikte bitki çaylarını doktorunuza danışarak tüketin."], serving: "Soğuk servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n01_110", title: "Ev yapımı kefir smoothie (orman meyveli)", category: "İçecekler", ingredients: ["1,5 su bardağı kefir", "1 su bardağı dondurulmuş orman meyvesi", "1 muz", "1 tatlı kaşığı bal"], steps: ["Tüm malzemeyi blendera koyun.", "30 saniye pürüzsüz çekin.", "Kıvamı koyuysa biraz süt ekleyin.", "Bardaklara paylaştırın.", "Hemen servis edin."], minutes: 5, servings: 2, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Dondurulmuş meyve buz gerektirmez."], serving: "Soğuk servis edin.", storage: "Hemen tüketin; buzdolabında en fazla 12 saat."),
  GeneralRecipe(id: "n01_111", title: "Yeşil smoothie (ıspanaklı)", category: "İçecekler", ingredients: ["1 avuç bebek ıspanak", "1 yeşil elma", "1 muz", "1 su bardağı süt veya badem sütü", "1 tatlı kaşığı bal"], steps: ["Elmanın çekirdeklerini çıkarıp doğrayın.", "Tüm malzemeyi blendera koyun.", "45 saniye çekin.", "Kıvamını ayarlayın.", "Hemen için."], minutes: 5, servings: 2, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Muz ıspanağın tadını yumuşatır."], serving: "Soğuk servis edin.", storage: "Hemen tüketin; buzdolabında en fazla 12 saat."),
  GeneralRecipe(id: "n01_112", title: "Hurmalı süt", category: "İçecekler", ingredients: ["2 su bardağı süt", "4 çekirdeksiz hurma", "1 tutam tarçın"], steps: ["Hurmaları 10 dakika sıcak suda bekletin.", "Sütle birlikte blenderdan geçirin.", "Tarçın ekleyin.", "Soğuk veya ılık servis edin.", "Hemen tüketin."], minutes: 5, servings: 2, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Şeker eklemeye gerek yoktur."], serving: "Soğuk servis edin.", storage: "Hemen tüketin; buzdolabında en fazla 12 saat."),
  GeneralRecipe(id: "n01_113", title: "Ev yapımı limonlu nane şurubu", category: "İçecekler", ingredients: ["2 demet taze nane", "4 limon", "2 su bardağı şeker", "2 su bardağı su"], steps: ["Şeker ve suyu 5 dakika kaynatın.", "Ocaktan alıp naneyi ekleyin, 15 dakika demleyin.", "Süzüp limon suyunu ekleyin.", "Cam şişeye alın.", "1 ölçü şuruba 4 ölçü soğuk su katarak servis edin."], minutes: 20, servings: 8, prepMinutes: 20, cookMinutes: 0, difficulty: "Kolay", tips: ["Şurup konsantredir; sulandırarak kullanın."], serving: "Soğuk servis edin.", storage: "Şurup buzdolabında 2 hafta."),
  GeneralRecipe(id: "n01_114", title: "Elmalı tarçınlı kompost", category: "İçecekler", ingredients: ["4 elma", "1 çubuk tarçın", "4 karanfil", "Yarım su bardağı şeker", "6 su bardağı su"], steps: ["Elmaları dilimleyin.", "Su, şeker ve baharatları kaynatın.", "Elmaları ekleyip 10 dakika pişirin.", "Soğumaya bırakın.", "Soğuk servis edin."], minutes: 25, servings: 6, prepMinutes: 25, cookMinutes: 0, difficulty: "Kolay", tips: ["Kompostu bir gece dinlendirmek tadını yoğunlaştırır."], serving: "Soğuk servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n01_115", title: "Ev yapımı ayva kompostosu", category: "İçecekler", ingredients: ["2 ayva", "Yarım su bardağı şeker", "5 su bardağı su", "1 çubuk tarçın"], steps: ["Ayvaları soyup dilimleyin.", "Su, şeker ve tarçını kaynatın.", "Ayvaları ekleyip 20 dakika pişirin.", "Ayva yumuşayınca ocaktan alın.", "Soğutup servis edin."], minutes: 30, servings: 6, prepMinutes: 30, cookMinutes: 0, difficulty: "Kolay", tips: ["Ayva çekirdeklerini tülbente bağlayıp pişirirseniz renk pembeleşir."], serving: "Soğuk servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n01_201", title: "Kakaolu mozaik pasta", category: "Kek ve kurabiyeler", ingredients: ["2 paket pötibör bisküvi", "125 g tereyağı", "1 su bardağı süt", "Yarım su bardağı şeker", "3 yemek kaşığı kakao", "Yarım su bardağı ceviz"], steps: ["Bisküvileri elle iri parçalara ayırın.", "Süt, şeker, tereyağı ve kakaoyu ısıtıp eritin; kaynatmayın.", "Ilıyınca bisküvi ve cevizle karıştırın.", "Streç filme rulo şeklinde sarın.", "En az 4 saat buzdolabında bekletip dilimleyin."], minutes: 20, servings: 10, prepMinutes: 20, cookMinutes: 0, difficulty: "Kolay", tips: ["Sos çok sıcakken bisküvileri eklerseniz hamurlaşır."], serving: "Çay veya kahveyle servis edin.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "n01_202", title: "Islak kek (brownie usulü)", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "4 yemek kaşığı kakao", "2 su bardağı un", "1 paket kabartma tozu", "Sos için 1 su bardağı süt, 2 yemek kaşığı kakao, 3 yemek kaşığı şeker"], steps: ["Fırını 180 °C'ye ısıtın.", "Yumurta ve şekeri köpürtün; süt, yağ ve kakaoyu ekleyin.", "Un ve kabartma tozunu eleyerek ekleyin.", "Yağlanmış kare kalıpta 30 dakika pişirin.", "Sos malzemelerini kaynatıp sıcak keke dökün ve soğutun."], minutes: 45, servings: 12, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 180, tips: ["Sosu kek sıcakken dökün; iyi emer."], serving: "Çay veya kahveyle servis edin.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n01_203", title: "Limonlu kek", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "1 limonun kabuğu ve suyu", "Yarım su bardağı sıvı yağ", "1 su bardağı yoğurt", "2,5 su bardağı un", "1 paket kabartma tozu"], steps: ["Fırını 175 °C'ye ısıtın.", "Yumurta ve şekeri 4 dakika çırpın.", "Limon kabuğu, suyu, yağ ve yoğurdu ekleyin.", "Un ve kabartma tozunu eleyerek karıştırın.", "Yağlanmış kalıpta 40 dakika pişirin."], minutes: 55, servings: 10, prepMinutes: 15, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 175, tips: ["Yoğurt keki nemli tutar."], serving: "Çay veya kahveyle servis edin.", storage: "Hava almayan kapta 3–4 gün saklanır."),
  GeneralRecipe(id: "n01_204", title: "Mermer kek", category: "Kek ve kurabiyeler", ingredients: ["4 yumurta", "1 su bardağı şeker", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "3 su bardağı un", "1 paket kabartma tozu", "1 paket vanilin", "2 yemek kaşığı kakao"], steps: ["Fırını 175 °C'ye ısıtın.", "Yumurta ve şekeri köpürtün, süt ve yağı ekleyin.", "Un, kabartma tozu ve vanilini ekleyin.", "Hamurun üçte birine kakao karıştırın.", "Kalıba sade ve kakaolu hamuru dönüşümlü dökün, kürdanla dalgalandırıp 40 dakika pişirin."], minutes: 55, servings: 10, prepMinutes: 15, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 175, tips: ["Fazla karıştırırsanız desen kaybolur."], serving: "Çay veya kahveyle servis edin.", storage: "Hava almayan kapta 3–4 gün saklanır."),
  GeneralRecipe(id: "n01_205", title: "Tarçınlı elmalı kurabiye", category: "Kek ve kurabiyeler", ingredients: ["125 g tereyağı", "Yarım su bardağı pudra şekeri", "1 yumurta", "2,5 su bardağı un", "1 tatlı kaşığı kabartma tozu", "İç için 2 rendelenmiş elma, 2 yemek kaşığı şeker, 1 tatlı kaşığı tarçın, yarım su bardağı ceviz"], steps: ["Elmaları şeker ve tarçınla suyunu çekene kadar pişirip cevizle soğutun.", "Tereyağı, pudra şekeri ve yumurtayı çırpın, unu ekleyip hamur yapın.", "Hamurdan parçalar alıp açın, içine elmalı harç koyup kapatın.", "180 °C fırında 20 dakika pişirin.", "Soğuyunca pudra şekeri serpin."], minutes: 40, servings: 20, prepMinutes: 20, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 180, tips: ["Harç tamamen soğuk olmalı; hamur yumuşamaz."], serving: "Çay veya kahveyle servis edin.", storage: "Hava almayan kapta 3–4 gün saklanır."),
  GeneralRecipe(id: "n01_206", title: "Un kurabiyesi", category: "Kek ve kurabiyeler", ingredients: ["250 g tereyağı (oda sıcaklığında)", "1 su bardağı pudra şekeri", "1 paket vanilin", "Yaklaşık 3 su bardağı un", "Yarım su bardağı nişasta"], steps: ["Tereyağı ve pudra şekerini krema kıvamına gelene kadar çırpın.", "Vanilin, nişasta ve unu azar azar ekleyin.", "Ele yapışmayan yumuşak hamuru ceviz büyüklüğünde yuvarlayın.", "170 °C fırında 15 dakika, rengi açık kalacak şekilde pişirin.", "Soğuyunca pudra şekeri serpin."], minutes: 30, servings: 30, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 170, tips: ["Kurabiye rengi değişmemeli; ağızda dağılan doku buradan gelir."], serving: "Çay veya kahveyle servis edin.", storage: "Kapalı kutuda 1 hafta."),
  GeneralRecipe(id: "n01_207", title: "Tuzlu kurabiye (susamlı)", category: "Kek ve kurabiyeler", ingredients: ["125 g tereyağı", "Yarım su bardağı sıvı yağ", "Yarım su bardağı yoğurt", "1 yumurta (sarısı üzerine)", "1 paket kabartma tozu", "1 tatlı kaşığı tuz", "Yaklaşık 3,5 su bardağı un", "Üzeri için 1 tatlı kaşığı susam ve 1 tatlı kaşığı çörek otu"], steps: ["Tereyağı, yağ, yoğurt, yumurta beyazı ve tuzu karıştırın.", "Kabartma tozu ve unu ekleyip yumuşak hamur yoğurun.", "Hamurdan çubuk veya yuvarlak şekiller verin.", "Yumurta sarısı sürüp susam serpin.", "180 °C fırında 20 dakika pişirin."], minutes: 35, servings: 30, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 180, tips: ["Hamuru fazla yoğurmayın."], serving: "Çay veya kahveyle servis edin.", storage: "Hava almayan kapta 3–4 gün saklanır."),
  GeneralRecipe(id: "n01_208", title: "Portakallı muffin", category: "Kek ve kurabiyeler", ingredients: ["2 yumurta", "Yarım su bardağı şeker", "1 portakalın kabuğu ve suyu", "Yarım su bardağı sıvı yağ", "Yarım su bardağı yoğurt", "2 su bardağı un", "1 paket kabartma tozu"], steps: ["Fırını 180 °C'ye ısıtın, muffin kalıbına kapsül yerleştirin.", "Yumurta ve şekeri çırpın.", "Portakal kabuğu, suyu, yağ ve yoğurdu ekleyin.", "Un ve kabartma tozunu ekleyip sadece birleşene kadar karıştırın.", "Kalıpları üçte iki doldurup 22 dakika pişirin."], minutes: 37, servings: 12, prepMinutes: 15, cookMinutes: 22, difficulty: "Kolay", ovenCelsius: 180, tips: ["Muffin hamurunu fazla karıştırmayın; içi tünel yapar."], serving: "Çay veya kahveyle servis edin.", storage: "Hava almayan kapta 3–4 gün saklanır."),
  GeneralRecipe(id: "n01_209", title: "Çikolatalı damla kurabiye", category: "Kek ve kurabiyeler", ingredients: ["125 g tereyağı", "Yarım su bardağı esmer şeker", "Yarım su bardağı toz şeker", "1 yumurta", "1 paket vanilin", "2 su bardağı un", "Yarım çay kaşığı karbonat", "1 su bardağı damla çikolata"], steps: ["Tereyağı ve şekerleri çırpın, yumurta ve vanilini ekleyin.", "Un ve karbonatı karıştırıp ekleyin.", "Damla çikolatayı katın.", "Hamuru 30 dakika buzdolabında dinlendirin.", "Ceviz büyüklüğünde toplar yapıp aralıklı dizin, 180 °C'de 12 dakika pişirin."], minutes: 27, servings: 20, prepMinutes: 15, cookMinutes: 12, difficulty: "Kolay", ovenCelsius: 180, tips: ["Ortası yumuşak görünürken çıkarın; tepside sertleşir."], serving: "Çay veya kahveyle servis edin.", storage: "Hava almayan kapta 3–4 gün saklanır."),
  GeneralRecipe(id: "n01_210", title: "Muzlu cevizli ekmek (banana bread)", category: "Kek ve kurabiyeler", ingredients: ["3 çok olgun muz", "2 yumurta", "Yarım su bardağı şeker", "Yarım su bardağı eritilmiş tereyağı", "1,5 su bardağı un", "1 tatlı kaşığı karbonat", "1 tatlı kaşığı tarçın", "Yarım su bardağı ceviz"], steps: ["Fırını 175 °C'ye ısıtın, baton kek kalıbını yağlayın.", "Muzları ezin, yumurta, şeker ve tereyağıyla karıştırın.", "Un, karbonat ve tarçını ekleyin.", "Cevizi katın.", "Kalıpta 50 dakika, kürdan temiz çıkana kadar pişirin."], minutes: 65, servings: 10, prepMinutes: 15, cookMinutes: 50, difficulty: "Kolay", ovenCelsius: 175, tips: ["Kabuğu kararmış muzlar en tatlı sonucu verir."], serving: "Çay veya kahveyle servis edin.", storage: "Hava almayan kapta 3 gün; dondurulabilir."),
  GeneralRecipe(id: "n01_211", title: "Yulaflı fıstık ezmeli kurabiye", category: "Kek ve kurabiyeler", ingredients: ["Yarım su bardağı fıstık ezmesi", "1 yumurta", "Yarım su bardağı esmer şeker", "1 su bardağı yulaf", "Yarım çay kaşığı karbonat"], steps: ["Fırını 180 °C'ye ısıtın.", "Fıstık ezmesi, yumurta ve şekeri karıştırın.", "Yulaf ve karbonatı ekleyin.", "Yuvarlayıp çatalla bastırın.", "12 dakika pişirin."], minutes: 22, servings: 16, prepMinutes: 10, cookMinutes: 12, difficulty: "Kolay", ovenCelsius: 180, tips: ["Un içermeyen pratik bir kurabiyedir; yer fıstığı alerjenine dikkat."], serving: "Çay veya kahveyle servis edin.", storage: "Hava almayan kapta 3–4 gün saklanır."),
  GeneralRecipe(id: "n01_212", title: "Revani", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "1 su bardağı yoğurt", "Yarım su bardağı sıvı yağ", "1 su bardağı irmik", "1 su bardağı un", "1 paket kabartma tozu", "Şerbet: 2,5 su bardağı şeker, 3 su bardağı su, yarım limon"], steps: ["Şerbet malzemelerini 10 dakika kaynatıp soğutun.", "Fırını 180 °C'ye ısıtın.", "Yumurta ve şekeri çırpın; yoğurt, yağ, irmik, un ve kabartma tozunu ekleyin.", "Yağlanmış tepside 35 dakika pişirin.", "Sıcak revaniye soğuk şerbeti dökün, şerbeti çekince dilimleyin."], minutes: 55, servings: 12, prepMinutes: 20, cookMinutes: 35, difficulty: "Orta", ovenCelsius: 180, tips: ["Şerbet soğuk, tatlı sıcak olmalı."], serving: "Çay veya kahveyle servis edin.", storage: "Oda sıcaklığında 2 gün, buzdolabında 4 gün."),
  GeneralRecipe(id: "n01_213", title: "Elmalı yulaflı muffin", category: "Kek ve kurabiyeler", ingredients: ["2 elma (rendelenmiş)", "1 su bardağı yulaf", "1 su bardağı tam buğday unu", "2 yumurta", "Yarım su bardağı süt", "4 yemek kaşığı sıvı yağ", "4 yemek kaşığı bal", "1 paket kabartma tozu", "1 tatlı kaşığı tarçın"], steps: ["Fırını 180 °C'ye ısıtın.", "Yumurta, süt, yağ ve balı çırpın.", "Elmayı ekleyin.", "Yulaf, un, kabartma tozu ve tarçını karıştırıp ekleyin.", "Kalıplara paylaştırıp 22 dakika pişirin."], minutes: 37, servings: 12, prepMinutes: 15, cookMinutes: 22, difficulty: "Kolay", ovenCelsius: 180, tips: ["Rafine şeker yerine bal kullanılmıştır."], serving: "Çay veya kahveyle servis edin.", storage: "Hava almayan kapta 3–4 gün saklanır."),
  GeneralRecipe(id: "n02_001", title: "Spagetti bolonez", category: "Dünya mutfağı", ingredients: ["400 g spagetti", "300 g dana kıyma", "1 soğan", "1 havuç", "2 diş sarımsak", "400 g rendelenmiş domates", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, kekik, karabiber"], steps: ["Soğan, havuç ve sarımsağı ince doğrayıp yağda 5 dakika soteleyin.", "Kıymayı ekleyip suyunu çekene kadar kavurun.", "Salça, domates ve baharatları ekleyin; kısık ateşte 30 dakika pişirin.", "Spagettiyi tuzlu suda haşlayın.", "Sosu makarnanın üzerine alıp parmesanla servis edin."], minutes: 60, servings: 4, prepMinutes: 15, cookMinutes: 45, difficulty: "Orta", tips: ["Sos ne kadar uzun pişerse o kadar lezzetli olur."], serving: "Sıcak, parmesanla.", storage: "Sos buzdolabında 3 gün, dondurucuda 3 ay."),
  GeneralRecipe(id: "n02_002", title: "Fettuccine Alfredo (hafif)", category: "Dünya mutfağı", ingredients: ["350 g fettuccine", "2 yemek kaşığı tereyağı", "2 diş sarımsak", "1 su bardağı süt", "Yarım su bardağı krema", "1 su bardağı rendelenmiş parmesan", "1 çay kaşığı tuz, karabiber, muskat"], steps: ["Makarnayı haşlayın, 1 bardak suyunu ayırın.", "Tereyağında sarımsağı 1 dakika çevirin.", "Süt ve kremayı ekleyip ısıtın; kaynatmayın.", "Parmesanı ekleyip eriyene kadar karıştırın.", "Makarnayı sosla buluşturup gerekirse haşlama suyuyla açın."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Orta", tips: ["Peyniri ocak kısıkken ekleyin; topaklanmaz."], serving: "Hemen servis edin.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n02_003", title: "Sebzeli risotto", category: "Dünya mutfağı", ingredients: ["1,5 su bardağı risotto pirinci (arborio)", "1 soğan", "1 su bardağı bezelye", "1 kabak", "5 su bardağı sıcak sebze suyu", "2 yemek kaşığı tereyağı", "Yarım su bardağı parmesan", "1 tatlı kaşığı tuz"], steps: ["Soğanı tereyağında yumuşatın, pirinci ekleyip 2 dakika kavurun.", "Sıcak suyu kepçe kepçe, her seferinde çekmesini bekleyerek ekleyin.", "15. dakikada kabak ve bezelyeyi ilave edin.", "18–20 dakika sonra pirinç dişe gelince ocaktan alın.", "Kalan tereyağı ve parmesanı ekleyip 2 dakika dinlendirin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Orta", tips: ["Sürekli karıştırmak nişastayı çıkarır ve kremamsı kıvam verir."], serving: "Hemen servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n02_004", title: "Tavuk fajita", category: "Dünya mutfağı", ingredients: ["500 g tavuk göğsü (şerit)", "2 renkli biber", "1 kırmızı soğan", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kimyon, tatlı toz biber, kekik", "1 limon", "4 tortilla", "4 yemek kaşığı yoğurt ve 4 yemek kaşığı avokado ezmesi"], steps: ["Tavuğu baharat, limon ve yarım yağla 15 dakika marine edin.", "Sebzeleri şerit doğrayın.", "Tavuğu kızgın tavada 6 dakika pişirip alın.", "Sebzeleri aynı tavada 4 dakika diri kalacak şekilde soteleyin, tavuğu geri ekleyin.", "Isıtılmış tortillalarda yoğurt ve avokadoyla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Orta", tips: ["Tavayı iyice kızdırın; sebzeler kızarsın."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_005", title: "Tavuklu sebzeli wok", category: "Dünya mutfağı", ingredients: ["400 g tavuk göğsü", "1 havuç", "1 kabak", "1 biber", "1 su bardağı brokoli", "3 yemek kaşığı soya sosu", "1 yemek kaşığı bal", "1 tatlı kaşığı rendelenmiş zencefil", "2 yemek kaşığı sıvı yağ"], steps: ["Tavuğu ince şerit, sebzeleri jülyen doğrayın.", "Wok veya geniş tavada yağı çok kızdırıp tavuğu 5 dakika çevirin.", "Sebzeleri ekleyip 4 dakika yüksek ateşte karıştırın.", "Soya, bal ve zencefili ekleyin.", "1 dakika daha çevirip pirinçle servis edin."], minutes: 27, servings: 4, prepMinutes: 15, cookMinutes: 12, difficulty: "Orta", tips: ["Malzemeleri önceden hazırlayın; wok çok hızlı pişer."], serving: "Sıcak, pilavla.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n02_006", title: "Meksika usulü fasulyeli pilav", category: "Dünya mutfağı", ingredients: ["1,5 su bardağı pirinç", "1 su bardağı haşlanmış barbunya", "1 su bardağı mısır", "1 kırmızı biber", "1 soğan", "2 yemek kaşığı salça", "2 yemek kaşığı sıvı yağ", "2,5 su bardağı sıcak su", "1 tatlı kaşığı kimyon, tuz"], steps: ["Soğan ve biberi yağda kavurun.", "Salça ve kimyonu ekleyin.", "Pirinci ekleyip 2 dakika kavurun.", "Fasulye, mısır, su ve tuzu ekleyip 15 dakika pişirin.", "10 dakika demlendirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Orta", tips: ["Kimyon bu pilavın karakteristik tadıdır."], serving: "Yoğurt veya avokadoyla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_007", title: "Falafel (fırında)", category: "Dünya mutfağı", ingredients: ["2 su bardağı bir gece ıslatılmış çiğ nohut", "1 soğan", "3 diş sarımsak", "1 demet maydanoz", "1 tatlı kaşığı kimyon, kişniş", "1 tatlı kaşığı tuz", "2 yemek kaşığı un", "3 yemek kaşığı zeytinyağı"], steps: ["Fırını 200 °C'ye ısıtın.", "Süzülmüş nohut, soğan, sarımsak, maydanoz ve baharatları robotta iri kum kıvamında çekin.", "Un ve tuzu ekleyip 15 dakika dinlendirin.", "Ceviz büyüklüğünde yassı köfteler yapıp yağlı tepsiye dizin, üzerlerine yağ sürün.", "25 dakika, yarısında çevirerek pişirin."], minutes: 45, servings: 4, prepMinutes: 20, cookMinutes: 25, difficulty: "Orta", ovenCelsius: 200, tips: ["Haşlanmış nohut kullanmayın; falafel dağılır."], serving: "Tahin sos ve lavaşla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_008", title: "Ratatouille", category: "Dünya mutfağı", ingredients: ["1 patlıcan", "2 kabak", "2 renkli biber", "1 soğan", "4 domates", "3 diş sarımsak", "4 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik, tuz"], steps: ["Tüm sebzeleri küp doğrayın.", "Soğan ve sarımsağı yağda 3 dakika kavurun.", "Patlıcan ve biberi ekleyip 8 dakika soteleyin.", "Kabak, domates, kekik ve tuzu ekleyin; kapağı kapalı 30 dakika pişirin.", "Ilık veya soğuk servis edin."], minutes: 65, servings: 4, prepMinutes: 20, cookMinutes: 45, difficulty: "Kolay", tips: ["Ertesi gün daha lezzetlidir."], serving: "Ekmekle.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n02_009", title: "Yoğurt soslu tavuklu sezar salata", category: "Dünya mutfağı", ingredients: ["300 g tavuk göğsü", "1 marul", "2 dilim bayat ekmek (küp)", "Yarım su bardağı parmesan", "Sos için 4 yemek kaşığı yoğurt, 1 tatlı kaşığı hardal, 1 diş sarımsak, 1 yemek kaşığı limon suyu, 2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu tuz ve karabiberle ızgarada veya tavada her yüzü 6 dakika pişirip dilimleyin.", "Ekmek küplerini fırında 8 dakika kızartın.", "Sos malzemelerini çırpın.", "Marulu doğrayıp sosla harmanlayın.", "Tavuk, kruton ve parmesanla servis edin."], minutes: 27, servings: 4, prepMinutes: 15, cookMinutes: 12, difficulty: "Kolay", tips: ["Yoğurtlu sos klasik sosa göre hafiftir."], serving: "Hemen.", storage: "Sossuz 1 gün."),
  GeneralRecipe(id: "n02_010", title: "Lazanya (kıymalı)", category: "Dünya mutfağı", ingredients: ["12 yaprak lazanya", "400 g kıyma", "1 soğan", "400 g domates sosu", "Beşamel: 3 yemek kaşığı tereyağı, 3 yemek kaşığı un, 3 su bardağı süt", "2 su bardağı rendelenmiş kaşar", "1 tatlı kaşığı tuz, kekik"], steps: ["Kıymayı soğanla kavurup domates sosu ve baharatla 15 dakika pişirin.", "Tereyağında unu kavurup sütü ekleyerek beşamel yapın.", "Fırın kabına sırayla sos, lazanya yaprağı, beşamel ve peynir dizin; 3 kat tekrarlayın.", "Üzerini folyoyla kapatıp 180 °C'de 30 dakika pişirin.", "Folyoyu açıp 10 dakika daha kızartın, 15 dakika dinlendirin."], minutes: 70, servings: 8, prepMinutes: 30, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 180, tips: ["Dinlendirme dilimlerin dağılmasını önler."], serving: "Yeşil salatayla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n02_011", title: "Mantarlı kremalı tavuk (stroganoff usulü)", category: "Dünya mutfağı", ingredients: ["500 g tavuk göğsü", "250 g mantar", "1 soğan", "1 su bardağı krema", "1 yemek kaşığı hardal", "1 tatlı kaşığı tatlı toz biber", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz"], steps: ["Tavuğu şerit doğrayıp tereyağında mühürleyin.", "Soğan ve mantarı ekleyip 7 dakika soteleyin.", "Biber ve hardalı ekleyin.", "Kremayı ekleyip 8 dakika kısık ateşte pişirin.", "Pilav veya makarnayla servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Orta", tips: ["Hardal sosa derinlik verir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_012", title: "Shakshuka (biber soslu yumurta)", category: "Dünya mutfağı", ingredients: ["2 renkli biber", "1 soğan", "2 diş sarımsak", "400 g domates", "4 yumurta", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kimyon, tatlı toz biber, tuz"], steps: ["Soğan ve biberi yağda 6 dakika kavurun.", "Sarımsak ve baharatları ekleyin.", "Domatesi ekleyip 10 dakika koyulaşana kadar pişirin.", "Sosta çukurlar açıp yumurtaları kırın.", "Kapağı kapalı 5–6 dakika pişirip maydanozla servis edin."], minutes: 30, servings: 2, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Yumurtaları sevdiğiniz kıvamda bırakın."], serving: "Ekmekle sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n02_013", title: "Teriyaki somon", category: "Dünya mutfağı", ingredients: ["2 dilim somon", "3 yemek kaşığı soya sosu", "1 yemek kaşığı bal", "1 tatlı kaşığı rendelenmiş zencefil", "1 diş sarımsak", "1 tatlı kaşığı nişasta", "1 yemek kaşığı susam"], steps: ["Soya, bal, zencefil, sarımsak ve nişastayı 3 yemek kaşığı suyla karıştırın.", "Somonu yapışmaz tavada derili tarafı altta 5 dakika pişirin.", "Çevirip 3 dakika daha pişirin.", "Sosu ekleyip koyulaşana kadar somonun üzerine kaşıklayın.", "Susam serpip pilavla servis edin."], minutes: 25, servings: 2, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Nişasta sosu parlak ve koyu yapar."], serving: "Sıcak.", storage: "Aynı gün."),
  GeneralRecipe(id: "n02_014", title: "Gnocchi (patatesli)", category: "Dünya mutfağı", ingredients: ["500 g unlu patates", "1 su bardağı un", "1 yumurta sarısı", "1 çay kaşığı tuz", "Sos için 3 yemek kaşığı tereyağı ve birkaç yaprak adaçayı"], steps: ["Patatesleri kabuklu haşlayıp sıcakken soyun ve ezin.", "Un, yumurta sarısı ve tuzla yumuşak hamur yapın; fazla yoğurmayın.", "Hamuru parmak kalınlığında rulo yapıp 2 cm parçalar kesin.", "Kaynar tuzlu suda yüzeye çıkınca 1 dakika daha pişirip alın.", "Tereyağında adaçayıyla çevirerek servis edin."], minutes: 40, servings: 4, prepMinutes: 30, cookMinutes: 10, difficulty: "Orta", tips: ["Fazla un gnocchiyi sertleştirir."], serving: "Parmesanla.", storage: "Pişmemiş hâli dondurulabilir."),
  GeneralRecipe(id: "n02_015", title: "Hint usulü nohut köri (chana masala)", category: "Dünya mutfağı", ingredients: ["2 su bardağı haşlanmış nohut", "1 soğan", "2 domates", "2 diş sarımsak", "1 tatlı kaşığı rendelenmiş zencefil", "1 yemek kaşığı köri", "1 tatlı kaşığı kimyon", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz"], steps: ["Soğanı yağda 5 dakika kavurun.", "Sarımsak, zencefil ve baharatları ekleyip 1 dakika çevirin.", "Domatesi ekleyip 8 dakika pişirin.", "Nohut ve 1 bardak su ekleyip 15 dakika pişirin.", "Kişniş veya maydanozla servis edin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", tips: ["Baharatları yağda kavurmak aromalarını açar."], serving: "Pilavla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n02_016", title: "Quesadilla (peynirli tavuklu)", category: "Dünya mutfağı", ingredients: ["2 tortilla", "150 g haşlanmış didiklenmiş tavuk", "1 su bardağı rendelenmiş kaşar", "Yarım su bardağı mısır", "1 kırmızı biber (küçük doğranmış)"], steps: ["Tortillanın yarısına peynir, tavuk, mısır ve biberi yayın.", "Katlayın.", "Kuru tavada her yüzünü 3–4 dakika kızartın.", "Peynir erimeli.", "Üçgen dilimleyin."], minutes: 18, servings: 2, prepMinutes: 10, cookMinutes: 8, difficulty: "Kolay", tips: ["Kuru tava çıtırlık verir."], serving: "Yoğurtlu sosla.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n02_017", title: "Paella usulü tavuklu pilav", category: "Dünya mutfağı", ingredients: ["1,5 su bardağı pirinç", "300 g tavuk but", "1 su bardağı bezelye", "1 kırmızı biber", "1 soğan", "1 domates", "1 çay kaşığı zerdeçal", "3 su bardağı sıcak tavuk suyu", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Tavuğu geniş tavada kızartıp alın.", "Soğan, biber ve domatesi 5 dakika pişirin.", "Pirinç ve zerdeçalı ekleyip 2 dakika çevirin.", "Tavuk suyu, bezelye ve tavuğu ekleyip karıştırmadan 20 dakika pişirin.", "5 dakika demlendirip limonla servis edin."], minutes: 50, servings: 4, prepMinutes: 15, cookMinutes: 35, difficulty: "Orta", tips: ["Karıştırmayın; dipte hafif kızarık tabaka oluşsun."], serving: "Limonla.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n02_018", title: "Yunan salatası (horiatiki)", category: "Dünya mutfağı", ingredients: ["3 domates", "1 salatalık", "1 yeşil biber", "1 kırmızı soğan", "150 g beyaz peynir (dilim)", "Yarım su bardağı siyah zeytin", "4 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik"], steps: ["Domatesleri iri, salatalığı yarım ay doğrayın.", "Biber ve soğanı halka kesin.", "Sebzeleri kaseye alın.", "Zeytinleri ekleyin, peyniri üzerine yerleştirin.", "Zeytinyağı ve kekik gezdirin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Peyniri parçalamadan bütün dilim bırakın."], serving: "Soğuk.", storage: "Aynı gün."),
  GeneralRecipe(id: "n02_019", title: "Tom yum usulü tavuk çorbası", category: "Dünya mutfağı", ingredients: ["300 g tavuk göğsü", "150 g mantar", "1 domates", "1 sap limon otu veya 1 limon kabuğu", "1 tatlı kaşığı rendelenmiş zencefil", "2 yemek kaşığı soya sosu", "1 limon suyu", "5 su bardağı tavuk suyu", "1 tutam pul biber"], steps: ["Tavuk suyunu zencefil ve limon otuyla 5 dakika kaynatın.", "İnce dilimlenmiş tavuğu ekleyip 8 dakika pişirin.", "Mantar ve domatesi ekleyip 5 dakika pişirin.", "Soya, limon suyu ve pul biberi ekleyin.", "Kişniş veya maydanozla servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Orta", tips: ["Limon suyunu en son ekleyin."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_020", title: "Pad thai usulü tavuklu erişte", category: "Dünya mutfağı", ingredients: ["250 g pirinç eriştesi", "300 g tavuk göğsü", "2 yumurta", "1 su bardağı fasulye filizi veya havuç jülyen", "3 dal taze soğan", "3 yemek kaşığı soya sosu", "1 yemek kaşığı esmer şeker", "1 limon", "3 yemek kaşığı yer fıstığı (kırılmış)"], steps: ["Erişteyi paket talimatına göre ılık suda yumuşatın.", "Tavuğu şerit kesip kızgın tavada pişirin, kenara itin.", "Yumurtaları tavaya kırıp karıştırarak pişirin.", "Erişte, sebze, soya ve şekeri ekleyip 3 dakika çevirin.", "Taze soğan, limon ve fıstıkla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Orta", tips: ["Yer fıstığı alerjisi varsa fıstığı çıkarın."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n02_101", title: "Fırında sebzeli tavuk göğsü (yağsız)", category: "Diyet ve sağlıklı tarifler", ingredients: ["4 tavuk göğsü", "1 kabak", "1 havuç", "1 kırmızı biber", "1 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı kekik, tuz"], steps: ["Fırını 200 °C'ye ısıtın.", "Tavukları limon, kekik ve tuzla ovun.", "Sebzeleri iri doğrayıp yağla harmanlayın.", "Tavuk ve sebzeleri tepsiye dizin.", "25 dakika, tavuğun içi 74 °C olana kadar pişirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Tavuk göğsünü inceltmek eşit pişirir."], serving: "Yeşil salatayla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_102", title: "Mercimekli kinoa köftesi", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı pişmiş kinoa", "1 su bardağı pişmiş yeşil mercimek", "1 havuç (rendelenmiş)", "1 yumurta", "3 yemek kaşığı yulaf", "1 tatlı kaşığı kimyon, tuz", "Yarım demet maydanoz"], steps: ["Fırını 190 °C'ye ısıtın.", "Mercimeği çatalla kabaca ezin.", "Tüm malzemeyi yoğurun.", "Köfte şekli verip kâğıtlı tepsiye dizin.", "25 dakika, yarısında çevirerek pişirin."], minutes: 45, servings: 4, prepMinutes: 20, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 190, tips: ["Karışım dağılıyorsa 1 kaşık daha yulaf ekleyin."], serving: "Yoğurtla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n02_103", title: "Chia puding (meyveli)", category: "Diyet ve sağlıklı tarifler", ingredients: ["4 yemek kaşığı chia tohumu", "1 su bardağı süt veya badem sütü", "1 tatlı kaşığı bal", "Yarım su bardağı meyve", "1 tutam tarçın"], steps: ["Chia, süt, bal ve tarçını karıştırın.", "5 dakika sonra tekrar karıştırın; topaklanmayı önler.", "En az 4 saat veya bir gece buzdolabında bekletin.", "Kaselere paylaştırın.", "Meyveyle servis edin."], minutes: 5, servings: 2, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Bir gece önceden hazırlayın."], serving: "Kahvaltıda soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n02_104", title: "Fırında falafel kasesi", category: "Diyet ve sağlıklı tarifler", ingredients: ["6 adet hazır fırın falafel", "1 su bardağı pişmiş bulgur", "1 salatalık", "1 domates", "Yarım su bardağı humus", "2 yemek kaşığı yoğurt", "Yarım limon"], steps: ["Bulguru kaselere paylaştırın.", "Salatalık ve domatesi doğrayıp ekleyin.", "Falafelleri ısıtıp yerleştirin.", "Humus ve yoğurdu ekleyin.", "Limon sıkıp servis edin."], minutes: 15, servings: 2, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Bitkisel proteinden zengin bir öğündür."], serving: "Ana öğün.", storage: "Bileşenler ayrı ayrı 2 gün."),
  GeneralRecipe(id: "n02_105", title: "Kabak spagetti (zoodle) domates soslu", category: "Diyet ve sağlıklı tarifler", ingredients: ["3 kabak", "2 domates", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 avuç fesleğen yaprağı", "2 yemek kaşığı rendelenmiş parmesan", "1 çay kaşığı tuz"], steps: ["Kabakları spiral kesiciyle veya soyacakla şerit yapın.", "Sarımsak ve domatesi yağda 6 dakika pişirin.", "Kabak şeritlerini ekleyip 2 dakika çevirin; fazla pişirmeyin.", "Tuz ve fesleğen ekleyin.", "Parmesanla servis edin."], minutes: 25, servings: 2, prepMinutes: 15, cookMinutes: 10, difficulty: "Kolay", tips: ["Kabak fazla pişerse sulanır."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n02_106", title: "Yulaflı protein pankek", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı yulaf", "1 muz", "2 yumurta", "3 yemek kaşığı yoğurt", "1 tatlı kaşığı kabartma tozu", "1 tutam tarçın"], steps: ["Tüm malzemeyi blenderda pürüzsüz çekin.", "5 dakika dinlendirin.", "Yapışmaz tavada küçük pankekler dökün.", "Her yüzünü 2 dakika pişirin.", "Meyve ve yoğurtla servis edin."], minutes: 15, servings: 2, prepMinutes: 5, cookMinutes: 10, difficulty: "Kolay", tips: ["Un ve şeker içermez."], serving: "Kahvaltıda.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n02_107", title: "Izgara sebze ve hellim salatası", category: "Diyet ve sağlıklı tarifler", ingredients: ["150 g hellim", "1 kabak", "1 patlıcan", "1 kırmızı biber", "1 avuç roka", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı nar ekşisi"], steps: ["Sebzeleri dilimleyip ızgara tavada her yüzü 3 dakika pişirin.", "Hellimi dilimleyip 2 dakika ızgara yapın.", "Rokayı tabağa serin.", "Sebze ve hellimi yerleştirin.", "Zeytinyağı ve nar ekşisi gezdirin."], minutes: 20, servings: 2, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Hellim tuzludur; ayrıca tuz eklemeyin."], serving: "Ilık.", storage: "Aynı gün."),
  GeneralRecipe(id: "n02_108", title: "Fırında tatlı patates ve nohut", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 tatlı patates", "1,5 su bardağı haşlanmış nohut", "1 kırmızı soğan", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kimyon, tatlı toz biber, tuz", "4 yemek kaşığı yoğurt ve 1 yemek kaşığı tahinle hazırlanmış sos"], steps: ["Fırını 210 °C'ye ısıtın.", "Tatlı patatesi küp doğrayın.", "Nohut ve soğanla birlikte yağ ve baharatla harmanlayın.", "Tepsiye yayıp 30 dakika pişirin.", "Yoğurtlu tahin sosla servis edin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 210, tips: ["Tatlı patates kabuğuyla da pişirilebilir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_109", title: "Ton balıklı kinoa salatası", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı pişmiş kinoa", "1 kutu ton balığı (suda)", "1 salatalık", "10 çeri domates", "Yarım kırmızı soğan", "2 yemek kaşığı zeytinyağı", "1 limon suyu"], steps: ["Kinoayı pişirip soğutun.", "Ton balığını süzün.", "Sebzeleri doğrayın.", "Hepsini karıştırın.", "Zeytinyağı ve limonla tatlandırın."], minutes: 25, servings: 2, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Suda ton balığı daha az yağ içerir."], serving: "Soğuk.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n02_110", title: "Buharda levrek ve sebzeler", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 levrek fileto", "1 havuç", "1 kabak", "1 su bardağı brokoli", "1 limon", "1 yemek kaşığı zeytinyağı", "Yarım demet dereotu, 1 çay kaşığı tuz"], steps: ["Sebzeleri doğrayıp buhar sepetine yerleştirin.", "5 dakika buharda pişirin.", "Fileto balıkları limon ve tuzla üzerine koyun.", "8–10 dakika buharda pişirin.", "Zeytinyağı ve dereotuyla servis edin."], minutes: 25, servings: 2, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Buharda pişirme ek yağ gerektirmez."], serving: "Sıcak.", storage: "Aynı gün."),
  GeneralRecipe(id: "n02_111", title: "Yeşil mercimek çorbası (yağsız)", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı yeşil mercimek", "1 havuç", "1 soğan", "1 domates", "6 su bardağı su", "1 tatlı kaşığı kimyon, tuz", "Yarım limon"], steps: ["Mercimeği yıkayın.", "Doğranmış sebzeler ve suyla birlikte tencereye alın.", "35 dakika, mercimek yumuşayana kadar pişirin.", "Yarısını blenderdan geçirip geri ekleyin.", "Kimyon ve limonla servis edin."], minutes: 45, servings: 4, prepMinutes: 10, cookMinutes: 35, difficulty: "Kolay", tips: ["Yarısını ezmek kıvamı yağsız koyulaştırır."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n02_112", title: "Avokadolu yumurta kasesi", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 yumurta", "Yarım avokado", "1 avuç bebek ıspanak", "5 çeri domates", "1 tatlı kaşığı zeytinyağı", "1 tutam tuz, pul biber"], steps: ["Yumurtaları 7 dakika haşlayıp soğuk suya alın.", "Avokadoyu dilimleyin.", "Ispanak ve domatesi kaseye alın.", "Yumurtaları ikiye kesip ekleyin.", "Zeytinyağı, tuz ve pul biberle servis edin."], minutes: 15, servings: 1, prepMinutes: 5, cookMinutes: 10, difficulty: "Kolay", tips: ["7 dakika haşlama sarıyı hafif kremsi bırakır."], serving: "Kahvaltıda.", storage: "Hemen tüketin."),
  GeneralRecipe(id: "n02_113", title: "Karnabahar pilavı", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 karnabahar", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "Yarım su bardağı bezelye", "1 çay kaşığı tuz, zerdeçal"], steps: ["Karnabaharı rendeleyin veya robotta pirinç tanesi büyüklüğünde çekin.", "Soğanı yağda yumuşatın.", "Karnabahar, bezelye ve baharatları ekleyin.", "Yüksek ateşte 6–7 dakika çevirin.", "Sıcak servis edin."], minutes: 20, servings: 4, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Düşük karbonhidratlı bir pilav alternatifidir."], serving: "Yanında et veya tavukla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_114", title: "Yoğurtlu yulaf (overnight oats)", category: "Diyet ve sağlıklı tarifler", ingredients: ["4 yemek kaşığı yulaf", "4 yemek kaşığı yoğurt", "4 yemek kaşığı süt", "1 tatlı kaşığı chia", "Yarım muz veya bir avuç meyve", "1 tatlı kaşığı bal"], steps: ["Yulaf, yoğurt, süt ve chiayı kavanozda karıştırın.", "Kapağını kapatıp bir gece buzdolabında bekletin.", "Sabah karıştırın.", "Meyveyi ekleyin.", "Balı gezdirip servis edin."], minutes: 5, servings: 1, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Pişirmeye gerek yoktur."], serving: "Kahvaltıda soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_115", title: "Izgara tavuklu buğday salatası", category: "Diyet ve sağlıklı tarifler", ingredients: ["300 g tavuk göğsü", "1 su bardağı haşlanmış buğday", "1 avuç roka", "1 salatalık", "10 çeri domates", "3 yemek kaşığı zeytinyağı", "2 yemek kaşığı nar ekşisi"], steps: ["Tavuğu tuz ve kekikle ızgarada pişirip dilimleyin.", "Buğdayı soğutun.", "Sebzeleri doğrayın.", "Hepsini sosla harmanlayın.", "Tavukla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Buğday tok tutar."], serving: "Ana öğün.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n02_201", title: "Sigara böreği", category: "Hamur işleri", ingredients: ["4 adet yufka", "200 g beyaz peynir", "Yarım demet maydanoz", "1 yumurta", "Kızartmak için 2 su bardağı sıvı yağ"], steps: ["Peyniri ezip maydanoz ve yumurtayla karıştırın.", "Yufkaları üst üste koyup 8 üçgene kesin.", "Geniş kenara harç koyup kenarları içe katlayarak sarın; ucunu suyla yapıştırın.", "Kızgın yağda her yüzü altın rengi olana kadar kızartın.", "Kâğıt havluya alın."], minutes: 35, servings: 6, prepMinutes: 20, cookMinutes: 15, difficulty: "Orta", tips: ["Fırında yapmak için üzerine yağ sürüp 200 °C'de 15 dakika pişirin."], serving: "Sıcak, çayla.", storage: "Pişmemiş hâli dondurulabilir."),
  GeneralRecipe(id: "n02_202", title: "Su böreği (pratik, yufkadan)", category: "Hamur işleri", ingredients: ["6 adet yufka", "300 g beyaz peynir", "1 demet maydanoz", "3 yumurta", "1 su bardağı süt", "125 g tereyağı"], steps: ["Yufkaları kaynar suda 1 dakika haşlayıp soğuk suya alın.", "Yağlı tepsiye her kat arasında eritilmiş tereyağı sürerek 3 yufka serin.", "Peynir ve maydanozu yayın.", "Kalan yufkaları aynı şekilde kapatın; yumurta ve sütü çırpıp üzerine dökün.", "200 °C fırında 35 dakika pişirin."], minutes: 65, servings: 8, prepMinutes: 30, cookMinutes: 35, difficulty: "Orta", ovenCelsius: 200, tips: ["Haşlanan yufkalar gerçek su böreği dokusu verir."], serving: "Ilık.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_203", title: "Kıymalı pide", category: "Hamur işleri", ingredients: ["3 su bardağı un", "1 paket instant maya", "1 tatlı kaşığı şeker ve tuz", "1 su bardağı ılık su", "2 yemek kaşığı zeytinyağı", "300 g kıyma", "1 soğan, 1 domates, 2 biber", "1 tatlı kaşığı tuz, karabiber"], steps: ["Un, maya, şeker, tuz, su ve yağla hamur yoğurup 1 saat mayalandırın.", "Kıymayı ince doğranmış sebzeler ve baharatlarla yoğurun (pişirmeden).", "Hamuru 4 parçaya bölüp kayık şeklinde açın.", "Harcı yayıp kenarlarını kıvırın.", "250 °C fırında 12–15 dakika pişirin."], minutes: 105, servings: 4, prepMinutes: 90, cookMinutes: 15, difficulty: "Orta", ovenCelsius: 250, tips: ["Fırını en yüksek ısıda önceden ısıtın."], serving: "Ayranla sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n02_204", title: "Lahmacun (evde)", category: "Hamur işleri", ingredients: ["3 su bardağı un", "1 paket instant maya", "1 su bardağı ılık su", "1 tatlı kaşığı tuz", "250 g kıyma", "1 soğan", "2 domates", "1 sivri biber", "1 yemek kaşığı salça", "Yarım demet maydanoz", "1 tatlı kaşığı pul biber, tuz"], steps: ["Hamuru yoğurup 1 saat mayalandırın.", "Soğan, domates, biber ve maydanozu robotta çekip kıyma, salça ve baharatlarla yoğurun.", "Hamuru 8 bezeye bölüp çok ince açın.", "Harcı ince bir tabaka hâlinde yayın.", "Önceden ısıtılmış tepside 250 °C fırında 8–10 dakika pişirin."], minutes: 100, servings: 8, prepMinutes: 90, cookMinutes: 10, difficulty: "Orta", ovenCelsius: 250, tips: ["Harç ince yayılmalı; kalın olursa pişmez."], serving: "Limon ve yeşillikle.", storage: "Pişmiş hâli dondurulabilir."),
  GeneralRecipe(id: "n02_205", title: "Patatesli gözleme (sac usulü)", category: "Hamur işleri", ingredients: ["2 su bardağı un", "1 su bardağı su", "1 çay kaşığı tuz", "3 haşlanmış patates", "1 soğan", "1 tatlı kaşığı pul biber", "2 yemek kaşığı tereyağı"], steps: ["Un, su ve tuzla yumuşak hamur yoğurup 20 dakika dinlendirin.", "Patatesi ezip kavrulmuş soğan ve pul biberle karıştırın.", "Hamuru 4 parçaya bölüp ince açın.", "Yarısına harç yayıp katlayın.", "Kuru tavada her yüzü 3 dakika pişirip tereyağı sürün."], minutes: 50, servings: 4, prepMinutes: 30, cookMinutes: 20, difficulty: "Orta", tips: ["Hamur ince olmalı."], serving: "Ayranla.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n02_206", title: "Simit", category: "Hamur işleri", ingredients: ["4 su bardağı un", "1 paket instant maya", "1 tatlı kaşığı tuz ve şeker", "1,5 su bardağı ılık su", "Yarım su bardağı pekmez", "1 su bardağı su (pekmez için)", "1,5 su bardağı susam"], steps: ["Hamuru yoğurup 1 saat mayalandırın.", "8 parçaya bölüp her birini ikiye ayırın, ince uzun çubuklar yapıp burgu şeklinde sarın ve halka hâline getirin.", "Pekmezli suya batırıp kavrulmuş susama bulayın.", "Tepside 15 dakika dinlendirin.", "220 °C fırında 18–20 dakika pişirin."], minutes: 110, servings: 8, prepMinutes: 90, cookMinutes: 20, difficulty: "Orta", ovenCelsius: 220, tips: ["Susamı önceden kavurmak aromayı artırır."], serving: "Çay ve peynirle.", storage: "Aynı gün; dondurulabilir."),
  GeneralRecipe(id: "n02_207", title: "Peynirli pişi", category: "Hamur işleri", ingredients: ["3 su bardağı un", "1 paket instant maya", "1 tatlı kaşığı şeker ve tuz", "1 su bardağı ılık süt", "Yarım su bardağı ılık su", "150 g beyaz peynir", "Kızartmak için 2 su bardağı sıvı yağ"], steps: ["Hamuru yoğurup 1 saat mayalandırın.", "Bezelere ayırıp elle açın.", "Ortasına peynir koyup kapatın ve hafifçe yassılaştırın.", "Kızgın yağda her yüzü kızarana kadar kızartın.", "Kâğıt havluya alın."], minutes: 85, servings: 6, prepMinutes: 70, cookMinutes: 15, difficulty: "Orta", tips: ["Yağ çok kızgın olmamalı; içi pişmeden dışı yanar."], serving: "Sıcak, kahvaltıda.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n02_208", title: "Mayalı açma (zeytinli)", category: "Hamur işleri", ingredients: ["4 su bardağı un", "1 paket instant maya", "1 yemek kaşığı şeker", "1 tatlı kaşığı tuz", "1 su bardağı ılık süt", "Yarım su bardağı sıvı yağ", "1 yumurta", "Yarım su bardağı doğranmış zeytin"], steps: ["Un, maya, şeker, tuz, süt, yağ ve yumurta beyazıyla yumuşak hamur yoğurun, 1 saat mayalandırın.", "12 parçaya bölüp ince açın.", "Zeytin serpip rulo yapın ve halka şeklinde birleştirin.", "Üzerine yumurta sarısı sürüp 20 dakika dinlendirin.", "180 °C fırında 25 dakika pişirin."], minutes: 125, servings: 12, prepMinutes: 100, cookMinutes: 25, difficulty: "Orta", ovenCelsius: 180, tips: ["İkinci mayalanma yumuşaklığın anahtarıdır."], serving: "Çayla.", storage: "Kapalı kapta 2 gün."),
  GeneralRecipe(id: "n02_209", title: "Kol böreği (patatesli)", category: "Hamur işleri", ingredients: ["3 adet yufka", "4 haşlanmış patates", "1 soğan", "1 tatlı kaşığı pul biber, tuz", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "1 yumurta sarısı"], steps: ["Patatesi ezip kavrulmuş soğan ve baharatla karıştırın.", "Süt ve yağı karıştırın.", "Yufkaları ikiye kesin, sosla ıslatın, harcı kenara koyup rulo yapın.", "Yuvarlak tepsiye spiral dizin, yumurta sarısı sürün.", "190 °C fırında 35 dakika pişirin."], minutes: 60, servings: 6, prepMinutes: 25, cookMinutes: 35, difficulty: "Orta", ovenCelsius: 190, tips: ["Patates harcı soğuk olmalı."], serving: "Ilık.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n02_210", title: "Bazlama", category: "Hamur işleri", ingredients: ["3 su bardağı un", "1 paket instant maya", "1 tatlı kaşığı şeker ve tuz", "Yarım su bardağı yoğurt", "1 su bardağı ılık su"], steps: ["Tüm malzemeyle yumuşak hamur yoğurup 1 saat mayalandırın.", "6 bezeye ayırıp 15 dakika dinlendirin.", "Elle 1 cm kalınlığında açın.", "Kuru, kızgın tavada her yüzü 3–4 dakika pişirin; kabarınca çevirin.", "Bezle örterek soğutun."], minutes: 85, servings: 6, prepMinutes: 70, cookMinutes: 15, difficulty: "Orta", tips: ["Bezle örtmek bazlamayı yumuşak tutar."], serving: "Kahvaltıda sıcak.", storage: "Kapalı kapta 2 gün."),
  GeneralRecipe(id: "n03_001", title: "Hünkar beğendi", category: "Et yemekleri", ingredients: ["600 g kuşbaşı dana eti", "1 soğan", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "Beğendi: 4 patlıcan, 2 yemek kaşığı tereyağı, 2 yemek kaşığı un, 1,5 su bardağı süt, yarım su bardağı rendelenmiş kaşar", "1 tatlı kaşığı tuz, karabiber"], steps: ["Eti tereyağında suyunu çekene kadar kavurun, soğan ve salçayı ekleyin.", "Domates ve 2 bardak sıcak suyla kısık ateşte 75 dakika, et yumuşayana kadar pişirin.", "Patlıcanları közleyip soyun, ince kıyın.", "Tereyağında unu kavurun, sütü ekleyip koyulaştırın; patlıcan ve kaşarı karıştırın.", "Beğendiyi tabağa yayıp eti ortasına koyun."], minutes: 110, servings: 4, prepMinutes: 20, cookMinutes: 90, difficulty: "Zor", tips: ["Patlıcanı limonlu suda bekletirseniz kararmaz."], serving: "Sıcak.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_002", title: "Orman kebabı", category: "Et yemekleri", ingredients: ["600 g kuşbaşı dana eti", "2 havuç", "2 patates", "1 su bardağı bezelye", "10 arpacık soğan", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz, kekik"], steps: ["Eti tereyağında kavurun.", "Arpacık soğanları ve salçayı ekleyin.", "2 bardak sıcak suyla 45 dakika pişirin.", "Küp havuç, patates ve bezelyeyi ekleyip 25 dakika daha pişirin.", "Kekikle servis edin."], minutes: 95, servings: 4, prepMinutes: 20, cookMinutes: 75, difficulty: "Orta", tips: ["Et yumuşamadan sebzeleri eklemeyin."], serving: "Pilavla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_003", title: "Kuzu tandır (fırında)", category: "Et yemekleri", ingredients: ["1,5 kg kuzu kol veya but", "6 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik ve biberiye", "1 tatlı kaşığı tuz, karabiber", "1 su bardağı su"], steps: ["Etin üzerine bıçakla delikler açıp sarımsakları yerleştirin.", "Yağ ve baharatlarla ovun.", "Fırın kabına su ile koyup folyoyla sıkıca kapatın.", "160 °C fırında 2,5–3 saat, kemikten ayrılacak kadar pişirin.", "Folyoyu açıp 220 °C'de 15 dakika kızartın."], minutes: 195, servings: 6, prepMinutes: 15, cookMinutes: 180, difficulty: "Zor", ovenCelsius: 160, tips: ["Düşük ısı ve uzun süre yumuşaklığın sırrıdır."], serving: "Pilav ve közlenmiş sebzeyle.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_004", title: "İzmir köfte", category: "Et yemekleri", ingredients: ["500 g kıyma", "1 soğan (rendelenmiş)", "1 yumurta", "3 yemek kaşığı galeta unu", "3 patates", "2 biber", "2 domates", "1 yemek kaşığı salça", "1 tatlı kaşığı tuz, kimyon, karabiber"], steps: ["Kıyma, soğan, yumurta, galeta unu ve baharatları yoğurup parmak köfteler yapın.", "Köfteleri ve elma dilim patatesleri fırında 200 °C'de 15 dakika ön pişirin.", "Tepsiye köfte, patates, biber ve domatesi sırayla dizin.", "Salçayı 1,5 bardak sıcak suda açıp üzerine dökün.", "180 °C'de 30 dakika pişirin."], minutes: 70, servings: 4, prepMinutes: 25, cookMinutes: 45, difficulty: "Orta", ovenCelsius: 180, tips: ["Ön pişirme köftelerin dağılmasını önler."], serving: "Pilavla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_005", title: "Tas kebabı", category: "Et yemekleri", ingredients: ["600 g kuşbaşı dana", "2 soğan", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı kekik, tuz", "2 su bardağı sıcak su"], steps: ["Eti kendi suyunu çekene kadar pişirin.", "Tereyağı ve soğanı ekleyip 5 dakika kavurun.", "Salça ve domatesi ekleyin.", "Sıcak suyla kısık ateşte 70 dakika pişirin.", "Kekikle servis edin."], minutes: 95, servings: 4, prepMinutes: 15, cookMinutes: 80, difficulty: "Orta", tips: ["Düdüklü tencerede 30 dakika yeterlidir."], serving: "Pilavla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_006", title: "Kıymalı patlıcan musakka", category: "Et yemekleri", ingredients: ["4 patlıcan", "300 g kıyma", "1 soğan", "2 biber", "2 domates", "1 yemek kaşığı salça", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, karabiber"], steps: ["Patlıcanları alacalı soyup halka kesin, tuzlu suda 15 dakika bekletip kurulayın.", "Patlıcanları fırında yağ sürüp 200 °C'de 15 dakika kızartın.", "Kıymayı soğan, biber ve salçayla kavurun.", "Fırın kabına patlıcan ve kıymayı kat kat dizin, domates dilimleri ekleyin.", "1 bardak sıcak su ekleyip 180 °C'de 25 dakika pişirin."], minutes: 65, servings: 4, prepMinutes: 25, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 180, tips: ["Patlıcanı fırınlamak kızartmadan daha hafiftir."], serving: "Pilav ve yoğurtla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_007", title: "Islama köfte", category: "Et yemekleri", ingredients: ["500 g kıyma", "1 soğan", "3 yemek kaşığı galeta unu", "1 tatlı kaşığı kimyon, tuz", "2 pide", "2 su bardağı et suyu", "1 tatlı kaşığı salça", "2 yemek kaşığı tereyağı"], steps: ["Köfte harcını yoğurup yassı köfteler yapın.", "Izgarada veya tavada her yüzü 4 dakika pişirin.", "Et suyunu salçayla kaynatın.", "Pide dilimlerini et suyuna batırıp tabağa dizin.", "Köfteleri üzerine yerleştirip tereyağı gezdirin."], minutes: 40, servings: 4, prepMinutes: 20, cookMinutes: 20, difficulty: "Orta", tips: ["Pide sıcak et suyunu kısa süre emmeli; hamurlaşmamalı."], serving: "Domates ve biberle.", storage: "Köfte buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_008", title: "Kadınbudu köfte", category: "Et yemekleri", ingredients: ["400 g kıyma", "Yarım su bardağı pirinç (haşlanmış)", "1 soğan", "1 yumurta (harca)", "2 yumurta (bulamak için)", "Yarım su bardağı un", "1 tatlı kaşığı tuz, karabiber, kimyon", "Kızartmak için 2 su bardağı sıvı yağ"], steps: ["Kıymanın yarısını soğanla kavurup soğutun.", "Kalan çiğ kıyma, pirinç, yumurta ve baharatlarla yoğurun.", "Oval yassı köfteler yapın.", "Una, sonra çırpılmış yumurtaya bulayın.", "Kızgın yağda her yüzü 3–4 dakika kızartın."], minutes: 50, servings: 4, prepMinutes: 30, cookMinutes: 20, difficulty: "Orta", tips: ["Kıymanın yarısının pişmiş olması köfteye yumuşaklık verir."], serving: "Patates püresiyle.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_009", title: "Etli kuru fasulye", category: "Et yemekleri", ingredients: ["2 su bardağı kuru fasulye (bir gece ıslatılmış)", "300 g kuşbaşı dana", "1 soğan", "2 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz, pul biber", "5 su bardağı sıcak su"], steps: ["Fasulyeyi 30 dakika ön haşlayıp süzün.", "Eti tereyağında kavurun, soğan ve salçayı ekleyin.", "Fasulye ve sıcak suyu ekleyin.", "Kısık ateşte 60 dakika, fasulyeler yumuşayana kadar pişirin.", "Tuzu son 10 dakikada ekleyin."], minutes: 105, servings: 6, prepMinutes: 15, cookMinutes: 90, difficulty: "Orta", tips: ["Tuzu erken eklemek fasulyenin yumuşamasını geciktirir."], serving: "Pilav ve turşuyla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_010", title: "Ali Nazik kebabı", category: "Et yemekleri", ingredients: ["500 g kıyma", "4 patlıcan", "1,5 su bardağı süzme yoğurt", "2 diş sarımsak", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz, kimyon, pul biber"], steps: ["Patlıcanları közleyip soyun ve ince kıyın.", "Sarımsaklı yoğurdu patlıcanla karıştırın.", "Kıymayı baharatlarla tavada topaklanmadan kavurun.", "Patlıcanlı yoğurdu tabağa yayın, kıymayı ortaya koyun.", "Pul biberli tereyağı gezdirin."], minutes: 45, servings: 4, prepMinutes: 20, cookMinutes: 25, difficulty: "Orta", tips: ["Patlıcanı süzmek yoğurdun sulanmasını önler."], serving: "Sıcak.", storage: "Kıyma buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_011", title: "Fırında kuzu pirzola", category: "Et yemekleri", ingredients: ["8 kuzu pirzola", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik, biberiye", "1 tatlı kaşığı tuz"], steps: ["Pirzolaları yağ, sarımsak ve otlarla 30 dakika marine edin.", "Izgara tavayı iyice kızdırın.", "Her yüzü 3–4 dakika pişirin.", "Tuzu pişirdikten sonra serpin.", "5 dakika dinlendirip servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Dinlendirme suyunun içte kalmasını sağlar."], serving: "Közlenmiş sebzeyle.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_012", title: "Patatesli et yemeği", category: "Et yemekleri", ingredients: ["500 g kuşbaşı dana", "3 patates", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz, karabiber", "3 su bardağı sıcak su"], steps: ["Eti suyunu çekene kadar kavurun.", "Soğan ve salçayı ekleyin.", "Sıcak suyla 45 dakika pişirin.", "Küp patatesleri ekleyip 20 dakika daha pişirin.", "Sıcak servis edin."], minutes: 85, servings: 4, prepMinutes: 15, cookMinutes: 70, difficulty: "Kolay", tips: ["Patatesi geç ekleyin; dağılmasın."], serving: "Pilavla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_013", title: "Kıymalı lahana sarması", category: "Et yemekleri", ingredients: ["1 lahana", "300 g kıyma", "Yarım su bardağı pirinç", "1 soğan", "1 yemek kaşığı salça", "1 tatlı kaşığı tuz, karabiber, nane", "2 yemek kaşığı tereyağı"], steps: ["Lahana yapraklarını haşlayıp kalın damarlarını açın.", "Kıyma, pirinç, rendelenmiş soğan ve baharatları yoğurun.", "Yapraklara harç koyup sarın.", "Tencereye dizip salçalı sıcak su ve tereyağı ekleyin.", "Üzerine tabak kapatıp kısık ateşte 45 dakika pişirin."], minutes: 90, servings: 6, prepMinutes: 40, cookMinutes: 50, difficulty: "Zor", tips: ["Tabak sarmaların açılmasını önler."], serving: "Sarımsaklı yoğurtla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_014", title: "Taze fasulyeli kuşbaşı", category: "Et yemekleri", ingredients: ["400 g kuşbaşı dana", "500 g taze fasulye", "1 soğan", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz"], steps: ["Eti kavurup soğan ve salçayı ekleyin.", "1 bardak suyla 30 dakika pişirin.", "Doğranmış fasulye ve domatesi ekleyin.", "Kısık ateşte 30 dakika pişirin.", "Tuzunu ayarlayın."], minutes: 75, servings: 4, prepMinutes: 15, cookMinutes: 60, difficulty: "Kolay", tips: ["Fasulyenin kılçıklarını ayıklayın."], serving: "Pilavla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_015", title: "Dana rosto", category: "Et yemekleri", ingredients: ["1 kg dana nuar", "4 diş sarımsak", "2 havuç", "2 soğan", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik, tuz, karabiber", "1 su bardağı et suyu"], steps: ["Eti baharatlarla ovup kızgın tencerede her yüzünü mühürleyin.", "İri doğranmış sebzeleri ve sarımsağı ekleyin.", "Et suyunu ekleyip kapağı kapatın.", "Kısık ateşte 2 saat, ara ara çevirerek pişirin.", "Dinlendirip ince dilimleyin, suyunu sos yapın."], minutes: 135, servings: 6, prepMinutes: 15, cookMinutes: 120, difficulty: "Zor", tips: ["Mühürlemek lezzeti hapseder."], serving: "Patates püresiyle.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_016", title: "Kıymalı börülce", category: "Et yemekleri", ingredients: ["2 su bardağı haşlanmış börülce", "200 g kıyma", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı sıvı yağ", "1,5 su bardağı sıcak su", "1 tatlı kaşığı tuz, pul biber"], steps: ["Kıymayı soğanla kavurun.", "Salçayı ekleyin.", "Börülce ve suyu ekleyin.", "25 dakika pişirin.", "Pul biberle servis edin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", tips: ["Börülce kuru baklagiller arasında en çabuk pişenlerdendir."], serving: "Pilavla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_017", title: "Etli enginar", category: "Et yemekleri", ingredients: ["6 enginar", "300 g kuşbaşı kuzu", "1 soğan", "1 havuç", "1 limon", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Enginarları limonlu suda bekletin.", "Eti kavurup soğan ve havucu ekleyin.", "1 bardak suyla 25 dakika pişirin.", "Enginarları ekleyip limon suyu ilave edin.", "20 dakika daha pişirin."], minutes: 65, servings: 4, prepMinutes: 20, cookMinutes: 45, difficulty: "Orta", tips: ["Limon enginarın kararmasını önler."], serving: "Sıcak.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_018", title: "Kuzu incik (fırında)", category: "Et yemekleri", ingredients: ["4 kuzu incik", "1 soğan", "2 domates", "4 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik, tuz", "2 su bardağı su"], steps: ["İncikleri tencerede mühürleyin.", "Fırın kabına soğan, domates ve sarımsakla yerleştirin.", "Su ve baharatları ekleyip folyoyla kapatın.", "170 °C'de 2,5 saat pişirin.", "Folyoyu açıp 15 dakika kızartın."], minutes: 165, servings: 4, prepMinutes: 15, cookMinutes: 150, difficulty: "Zor", ovenCelsius: 170, tips: ["Kemikten ayrılıyorsa hazırdır."], serving: "Bulgur pilavıyla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_019", title: "Sebzeli et haşlama", category: "Et yemekleri", ingredients: ["600 g kemikli dana eti", "2 patates", "2 havuç", "1 kabak", "1 soğan", "1 tatlı kaşığı tuz, karabiber", "6 su bardağı su"], steps: ["Eti suyla kaynatıp köpüğünü alın.", "Bütün soğanı ekleyip 60 dakika pişirin.", "İri doğranmış sebzeleri ekleyin.", "25 dakika daha pişirin.", "Limonla servis edin."], minutes: 105, servings: 4, prepMinutes: 15, cookMinutes: 90, difficulty: "Kolay", tips: ["Köpüğü almak suyu berrak tutar."], serving: "Sıcak.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_020", title: "Kıymalı ıspanaklı pide dürümü", category: "Et yemekleri", ingredients: ["300 g kıyma", "300 g ıspanak", "1 soğan", "4 lavaş", "1 su bardağı rendelenmiş kaşar", "1 tatlı kaşığı tuz, pul biber"], steps: ["Kıymayı soğanla kavurun.", "Ispanağı ekleyip soldurun.", "Lavaşlara harcı ve kaşarı yayıp sarın.", "Tavada her yüzü 2 dakika kızartın.", "Dilimleyin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Ispanağın suyu çekilmeli."], serving: "Ayranla.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n03_101", title: "Tavuk şiş (yoğurtlu marine)", category: "Tavuk yemekleri", ingredients: ["600 g tavuk göğsü", "3 yemek kaşığı yoğurt", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik, pul biber, tuz", "1 biber, 1 soğan"], steps: ["Tavuğu küp doğrayıp yoğurt, salça, yağ ve baharatla en az 1 saat marine edin.", "Tavuk ve sebzeleri şişlere dizin.", "Izgarada veya fırında 220 °C'de 15 dakika çevirerek pişirin.", "İç sıcaklık 74 °C olmalı.", "Lavaş ve sumaklı soğanla servis edin."], minutes: 35, servings: 4, prepMinutes: 20, cookMinutes: 15, difficulty: "Orta", ovenCelsius: 220, tips: ["Ahşap şişleri 30 dakika suda bekletin."], serving: "Pilavla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_102", title: "Tavuk sote (domatesli biberli)", category: "Tavuk yemekleri", ingredients: ["600 g tavuk göğsü", "2 biber", "2 domates", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz, kekik"], steps: ["Tavuğu yüksek ateşte mühürleyin.", "Soğan ve biberi ekleyip 5 dakika soteleyin.", "Salça ve domatesi ekleyin.", "Kısık ateşte 12 dakika pişirin.", "Kekikle servis edin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Tavuğu kalabalık etmeyin."], serving: "Pilavla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_103", title: "Fırında patatesli tavuk but", category: "Tavuk yemekleri", ingredients: ["8 tavuk baget", "4 patates", "1 soğan", "3 yemek kaşığı zeytinyağı", "1 yemek kaşığı salça", "1 tatlı kaşığı kekik, tatlı toz biber, tuz"], steps: ["Tavukları yağ, salça ve baharatla ovun.", "Patates ve soğanı iri doğrayın.", "Tepsiye dizip 1 bardak su ekleyin.", "200 °C'de 50 dakika pişirin.", "Yarısında çevirin."], minutes: 65, servings: 4, prepMinutes: 15, cookMinutes: 50, difficulty: "Kolay", ovenCelsius: 200, tips: ["Tavuk kemiğinin dibi pembe kalmamalı."], serving: "Salatayla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_104", title: "Tavuk haşlama ve sebze çorbası", category: "Tavuk yemekleri", ingredients: ["1 tavuk but ve göğüs", "2 havuç", "1 patates", "1 soğan", "Yarım su bardağı şehriye", "8 su bardağı su", "1 tatlı kaşığı tuz"], steps: ["Tavuğu suyla haşlayıp köpüğünü alın.", "45 dakika pişirip tavuğu çıkarın, didikleyin.", "Suya doğranmış sebzeleri ekleyip 15 dakika pişirin.", "Şehriye ve tavuğu ekleyip 8 dakika pişirin.", "Limonla servis edin."], minutes: 55, servings: 4, prepMinutes: 10, cookMinutes: 45, difficulty: "Kolay", tips: ["Haşlama suyu soğuyunca üstündeki yağı alın."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n03_105", title: "Tavuk tantuni", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü (ince şerit)", "2 domates", "1 soğan", "Yarım demet maydanoz", "4 lavaş", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı pul biber, kimyon, tuz"], steps: ["Tavuğu baharatlarla yüksek ateşte 8 dakika pişirin.", "Domatesi küçük doğrayıp ekleyin, 3 dakika pişirin.", "Lavaşları tavada ısıtın.", "Tavuk, sumaklı soğan ve maydanozla sarın.", "Dilimleyip servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Lavaşı tavuğun suyuna bastırarak ısıtın."], serving: "Ayranla.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n03_106", title: "Çerkez tavuğu", category: "Tavuk yemekleri", ingredients: ["1 tavuk göğsü", "2 dilim bayat ekmek", "1,5 su bardağı ceviz", "2 diş sarımsak", "1 tatlı kaşığı tatlı toz biber", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz"], steps: ["Tavuğu haşlayıp didikleyin; suyunu saklayın.", "Ekmeği haşlama suyuyla ıslatın.", "Ceviz, ekmek ve sarımsağı robotta çekip haşlama suyuyla krema kıvamına getirin.", "Tavuğun yarısını sosla karıştırın.", "Üzerine tereyağında kızdırılmış toz biber gezdirin."], minutes: 60, servings: 6, prepMinutes: 20, cookMinutes: 40, difficulty: "Orta", tips: ["Cevizi taze kullanın; acımaz."], serving: "Soğuk meze olarak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_107", title: "Tavuklu güveç", category: "Tavuk yemekleri", ingredients: ["600 g tavuk but (kemiksiz)", "2 patates", "1 patlıcan", "2 biber", "2 domates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, kekik"], steps: ["Tüm sebzeleri iri doğrayın.", "Tavukla birlikte güvece dizin.", "Yağ, tuz ve kekik ekleyin.", "1 bardak su ekleyip kapağını kapatın.", "Soğuk fırına koyup 190 °C'de 60 dakika pişirin."], minutes: 75, servings: 4, prepMinutes: 15, cookMinutes: 60, difficulty: "Kolay", ovenCelsius: 190, tips: ["Güveci soğuk fırına koymak çatlamasını önler."], serving: "Pilavla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_108", title: "Tavuk pane (fırında)", category: "Tavuk yemekleri", ingredients: ["4 tavuk göğsü (inceltilmiş)", "1 su bardağı galeta unu", "2 yumurta", "Yarım su bardağı un", "2 yemek kaşığı rendelenmiş parmesan", "1 tatlı kaşığı tuz, kekik", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 210 °C'ye ısıtın.", "Tavukları una, yumurtaya, sonra galeta-parmesan karışımına bulayın.", "Kâğıtlı tepsiye dizip üzerlerine yağ gezdirin.", "20 dakika, yarısında çevirerek pişirin.", "Limonla servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 210, tips: ["Fırında pane kızartmadan çok daha az yağ içerir."], serving: "Salatayla.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n03_109", title: "Limonlu kekikli tavuk kanat", category: "Tavuk yemekleri", ingredients: ["1 kg tavuk kanat", "2 yemek kaşığı zeytinyağı", "1 limon", "2 diş sarımsak", "1 tatlı kaşığı kekik, tuz, karabiber"], steps: ["Kanatları marine malzemeleriyle 1 saat bekletin.", "Fırını 220 °C'ye ısıtın.", "Izgara teline dizin.", "40 dakika, yarısında çevirerek pişirin.", "Limon dilimleriyle servis edin."], minutes: 50, servings: 4, prepMinutes: 10, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 220, tips: ["Izgara teli kanatların her yanının kızarmasını sağlar."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_110", title: "Bezelyeli tavuk yemeği", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü", "2 su bardağı bezelye", "1 havuç", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz"], steps: ["Tavuğu küp doğrayıp mühürleyin.", "Soğan, havuç ve salçayı ekleyin.", "Bezelye ve 1,5 bardak sıcak su ekleyin.", "25 dakika pişirin.", "Dereotuyla servis edin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", tips: ["Dondurulmuş bezelye de kullanılabilir."], serving: "Pilavla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_201", title: "Etli nohut (fırında güveçte)", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı nohut (ıslatılmış)", "300 g kuşbaşı", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "5 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Nohudu 40 dakika ön haşlayın.", "Eti tereyağında kavurup soğan ve salçayı ekleyin.", "Güvece nohut, et ve suyu alın.", "190 °C fırında 50 dakika pişirin.", "Tuzunu ayarlayın."], minutes: 105, servings: 6, prepMinutes: 15, cookMinutes: 90, difficulty: "Orta", ovenCelsius: 190, tips: ["Güveçte yavaş pişirmek nohudu kremamsı yapar."], serving: "Pilavla.", storage: "Buzdolabında kapalı kapta 3 gün; dondurucuda 3 ay."),
  GeneralRecipe(id: "n03_202", title: "Zeytinyağlı barbunya (taze)", category: "Bakliyat yemekleri", ingredients: ["500 g taze barbunya", "2 havuç", "2 patates", "1 soğan", "2 domates", "5 yemek kaşığı zeytinyağı", "1 tatlı kaşığı şeker, tuz"], steps: ["Soğanı yağda kavurun.", "Havuç ve patatesi ekleyin.", "Barbunya ve domatesi ekleyin.", "1,5 bardak sıcak suyla kısık ateşte 40 dakika pişirin.", "Tencerede soğutun."], minutes: 60, servings: 4, prepMinutes: 15, cookMinutes: 45, difficulty: "Kolay", tips: ["Taze barbunyayı kabuğundan ayıklayın."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n03_203", title: "Mercimekli kabak dolması", category: "Bakliyat yemekleri", ingredients: ["6 kabak", "1 su bardağı kırmızı mercimek", "Yarım su bardağı pirinç", "1 soğan", "1 yemek kaşığı salça", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı nane, tuz"], steps: ["Kabakların içini oyun.", "Mercimek, pirinç, rendelenmiş soğan, salça ve baharatı karıştırın.", "Kabakları doldurun.", "Tencereye dizip 2 bardak sıcak su ve yağ ekleyin.", "Kısık ateşte 40 dakika pişirin."], minutes: 65, servings: 4, prepMinutes: 25, cookMinutes: 40, difficulty: "Orta", tips: ["Kabak içini mercimekli çorbada kullanabilirsiniz."], serving: "Yoğurtla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_204", title: "Nohutlu pilav üstü yahni", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış nohut", "2 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz, karabiber", "2 su bardağı sıcak su"], steps: ["Soğanları piyazlık doğrayıp tereyağında 10 dakika yavaşça kavurun.", "Salçayı ekleyin.", "Nohut ve suyu ekleyin.", "30 dakika kısık ateşte pişirin.", "Pilavın üzerinde servis edin."], minutes: 50, servings: 4, prepMinutes: 10, cookMinutes: 40, difficulty: "Kolay", tips: ["Soğanın tatlılaşması yahninin lezzetidir."], serving: "Pilavla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n03_205", title: "Mercimek kavurması (bulgurlu)", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı yeşil mercimek", "Yarım su bardağı bulgur", "2 soğan", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı pul biber, tuz"], steps: ["Mercimeği 20 dakika haşlayın.", "Bulguru ekleyip 10 dakika daha pişirin; süzün.", "Soğanları yağda kızarana kadar kavurun.", "Mercimekli bulguru soğanla karıştırın.", "Pul biberle servis edin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", tips: ["Soğanın karamelize olması tat verir."], serving: "Yoğurtla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n03_206", title: "Humuslu sebze tabağı", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı humus", "1 kabak", "1 havuç", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı sumak"], steps: ["Sebzeleri şerit doğrayıp yağla tavada 8 dakika kızartın.", "Humusu tabağa yayın.", "Sebzeleri üzerine dizin.", "Sumak ve zeytinyağı gezdirin.", "Lavaşla servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Humus oda sıcaklığında daha lezzetlidir."], serving: "Ilık.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_207", title: "Fava (bakla ezmesi)", category: "Bakliyat yemekleri", ingredients: ["1,5 su bardağı kuru bakla", "1 soğan", "5 yemek kaşığı zeytinyağı", "1 tatlı kaşığı şeker, tuz", "Yarım demet dereotu"], steps: ["Baklayı yıkayıp soğan ve 4 bardak suyla 40 dakika, dağılana kadar pişirin.", "Blenderdan pürüzsüz geçirin.", "Zeytinyağı, şeker ve tuzu ekleyin.", "Kaba döküp soğutun.", "Dereotu ve zeytinyağıyla servis edin."], minutes: 55, servings: 6, prepMinutes: 10, cookMinutes: 45, difficulty: "Kolay", tips: ["Soğuyunca dilimlenebilir kıvama gelir."], serving: "Soğuk meze.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "n03_208", title: "Siyah fasulyeli sebze yahnisi", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış siyah fasulye", "1 tatlı patates", "1 kırmızı biber", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kimyon, tuz"], steps: ["Soğan ve biberi kavurun.", "Küp tatlı patatesi ekleyin.", "Domates, fasulye ve 1 bardak suyu ekleyin.", "25 dakika pişirin.", "Kimyonla servis edin."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Tatlı patates yahniye doğal tatlılık katar."], serving: "Pilavla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n03_209", title: "Bezelye ve nohutlu köri", category: "Bakliyat yemekleri", ingredients: ["1,5 su bardağı haşlanmış nohut", "1 su bardağı bezelye", "1 soğan", "1 su bardağı hindistan cevizi sütü", "1 yemek kaşığı köri", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz"], steps: ["Soğanı yağda kavurun, köriyi ekleyin.", "Nohut ve bezelyeyi ekleyin.", "Hindistan cevizi sütünü dökün.", "15 dakika kısık ateşte pişirin.", "Pilavla servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Hindistan cevizi sütü yerine yoğurt kullanılabilir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n03_210", title: "Mercimekli ekşili köfte", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı kırmızı mercimek", "Yarım su bardağı ince bulgur", "1 soğan", "1 yemek kaşığı salça", "1 limon", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı nane, tuz"], steps: ["Mercimeği haşlayıp bulguru ekleyin, şişirin.", "Yoğurup nohut büyüklüğünde köfteler yapın.", "Soğan ve salçayı kavurup 4 bardak suyla kaynatın.", "Köfteleri ekleyip 10 dakika pişirin.", "Limon ve nane ekleyin."], minutes: 55, servings: 4, prepMinutes: 25, cookMinutes: 30, difficulty: "Orta", tips: ["Köfteler kaynar suya atılmalı; dağılmaz."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n04_001", title: "Çılbır", category: "Kahvaltılıklar", ingredients: ["4 yumurta", "1 su bardağı süzme yoğurt", "1 diş sarımsak", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı pul biber", "1 yemek kaşığı sirke"], steps: ["Yoğurdu ezilmiş sarımsakla çırpıp oda sıcaklığına getirin.", "Su ve sirkeyi kaynatıp ateşi kısın.", "Yumurtaları tek tek kaseye kırıp suya bırakın, 3 dakika pişirin.", "Yoğurdu tabaklara alıp yumurtaları yerleştirin.", "Tereyağında pul biberi kızdırıp gezdirin."], minutes: 15, servings: 2, prepMinutes: 5, cookMinutes: 10, difficulty: "Kolay", tips: ["Sirke yumurta beyazının toplanmasını sağlar."], serving: "Sıcak, ekmekle.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n04_002", title: "Pankek (klasik)", category: "Kahvaltılıklar", ingredients: ["1,5 su bardağı un", "1 su bardağı süt", "2 yumurta", "2 yemek kaşığı şeker", "2 yemek kaşığı eritilmiş tereyağı", "1 paket kabartma tozu", "1 tutam tuz"], steps: ["Kuru malzemeleri karıştırın.", "Süt, yumurta ve tereyağını çırpın.", "İkisini birleştirin; topaklar kalabilir.", "Yapışmaz tavaya kepçeyle dökün, kabarcıklar çıkınca çevirin.", "Bal veya meyveyle servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Hamuru fazla çırpmayın; pankek yumuşak olur."], serving: "Kahvaltıda sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n04_003", title: "Kaygana (otlu)", category: "Kahvaltılıklar", ingredients: ["3 yumurta", "3 yemek kaşığı un", "Yarım su bardağı süt", "Yarım demet maydanoz ve dereotu", "1 yemek kaşığı tereyağı", "1 çay kaşığı tuz"], steps: ["Yumurta, un, süt ve tuzu çırpın.", "Kıyılmış otları ekleyin.", "Tereyağlı tavaya ince dökün.", "Her yüzü 2 dakika pişirin.", "Rulo yapıp servis edin."], minutes: 13, servings: 2, prepMinutes: 5, cookMinutes: 8, difficulty: "Kolay", tips: ["Hamur krep kıvamında olmalı."], serving: "Kahvaltıda sıcak servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n04_004", title: "Fırında yumurtalı avokado", category: "Kahvaltılıklar", ingredients: ["1 avokado", "2 küçük yumurta", "1 tutam tuz, pul biber", "1 yemek kaşığı rendelenmiş kaşar"], steps: ["Fırını 200 °C'ye ısıtın.", "Avokadoyu ikiye kesip çekirdeğini çıkarın; yuvayı biraz genişletin.", "Yumurtaları yuvalara kırın.", "Kaşar ve baharat serpin.", "15 dakika pişirin."], minutes: 20, servings: 2, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 200, tips: ["Avokadoyu sabitlemek için folyo topu kullanın."], serving: "Kahvaltıda sıcak servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n04_005", title: "Peynirli ıspanaklı muffin (tuzlu)", category: "Kahvaltılıklar", ingredients: ["2 yumurta", "1 su bardağı yoğurt", "Yarım su bardağı sıvı yağ", "2 su bardağı un", "1 paket kabartma tozu", "1 su bardağı doğranmış ıspanak", "150 g beyaz peynir"], steps: ["Fırını 180 °C'ye ısıtın.", "Yumurta, yoğurt ve yağı çırpın.", "Un ve kabartma tozunu ekleyin.", "Ispanak ve peyniri katın.", "Kalıplarda 22 dakika pişirin."], minutes: 37, servings: 12, prepMinutes: 15, cookMinutes: 22, difficulty: "Kolay", ovenCelsius: 180, tips: ["Beslenme çantası için idealdir."], serving: "Ilık.", storage: "Kapalı kapta 2 gün."),
  GeneralRecipe(id: "n04_006", title: "Sucuklu kaşarlı omlet", category: "Kahvaltılıklar", ingredients: ["4 yumurta", "8 dilim sucuk", "3 yemek kaşığı rendelenmiş kaşar", "1 yemek kaşığı süt"], steps: ["Sucukları tavada 2 dakika çevirin.", "Yumurtaları sütle çırpın.", "Sucukların üzerine dökün.", "Kenarlar tutunca kaşarı serpin.", "Katlayıp servis edin."], minutes: 13, servings: 2, prepMinutes: 5, cookMinutes: 8, difficulty: "Kolay", tips: ["Sucuk yağı yeterli; ek yağ gerekmez."], serving: "Kahvaltıda sıcak servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n04_007", title: "Haşhaşlı çörek (kahvaltılık)", category: "Kahvaltılıklar", ingredients: ["3 su bardağı un", "1 paket instant maya", "Yarım su bardağı şeker", "1 su bardağı ılık süt", "Yarım su bardağı sıvı yağ", "1 yumurta", "Yarım su bardağı haşhaş ezmesi"], steps: ["Hamuru yoğurup 1 saat mayalandırın.", "İnce açıp haşhaş ezmesini sürün.", "Rulo yapıp 8 parçaya kesin.", "Tepsiye dizip 20 dakika dinlendirin.", "180 °C'de 25 dakika pişirin."], minutes: 115, servings: 8, prepMinutes: 90, cookMinutes: 25, difficulty: "Orta", ovenCelsius: 180, tips: ["Haşhaş ezmesini biraz şekerle karıştırabilirsiniz."], serving: "Çayla.", storage: "Kapalı kapta 2 gün."),
  GeneralRecipe(id: "n04_008", title: "Kahvaltılık patates salatası", category: "Kahvaltılıklar", ingredients: ["4 patates", "3 dal taze soğan", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "1 limon suyu", "1 tatlı kaşığı pul biber, tuz"], steps: ["Patatesleri haşlayıp soyun ve küp doğrayın.", "Yeşillikleri ince kıyın.", "Zeytinyağı, limon ve baharatlarla sos yapın.", "Patatesler ılıkken sosla harmanlayın.", "Servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Ilık patates sosu daha iyi emer."], serving: "Ilık veya soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n04_009", title: "Fırında kaşarlı ekmek (bruschetta usulü)", category: "Kahvaltılıklar", ingredients: ["8 dilim ekmek", "2 domates", "1 diş sarımsak", "1 su bardağı rendelenmiş kaşar", "2 yemek kaşığı zeytinyağı", "1 avuç fesleğen yaprağı"], steps: ["Ekmekleri kızartıp sarımsakla ovun.", "Domatesi küçük doğrayıp yağ ve fesleğenle karıştırın.", "Ekmeklere yayın.", "Kaşar serpin.", "200 °C'de 6–8 dakika pişirin."], minutes: 18, servings: 4, prepMinutes: 10, cookMinutes: 8, difficulty: "Kolay", ovenCelsius: 200, tips: ["Sarımsakla ovmak hafif aroma verir."], serving: "Kahvaltıda sıcak servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n04_010", title: "Tahin pekmez ezmesi", category: "Kahvaltılıklar", ingredients: ["4 yemek kaşığı tahin", "3 yemek kaşığı üzüm pekmezi", "1 yemek kaşığı ceviz (kırılmış)"], steps: ["Tahini kaseye alın.", "Pekmezi ekleyin.", "Kıvam alana kadar karıştırın.", "Cevizi serpin.", "Ekmekle servis edin."], minutes: 5, servings: 4, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Karıştırmadan üst üste de servis edilir."], serving: "Kahvaltıda.", storage: "Kapalı kapta 1 hafta."),
  GeneralRecipe(id: "n04_011", title: "Yumurtalı kabak (kahvaltılık)", category: "Kahvaltılıklar", ingredients: ["2 kabak", "3 yumurta", "1 yemek kaşığı tereyağı", "1 çay kaşığı tuz, pul biber"], steps: ["Kabakları rendeleyip suyunu sıkın.", "Tereyağında 5 dakika soteleyin.", "Yumurtaları üzerine kırıp karıştırın.", "Pişince baharat ekleyin.", "Sıcak servis edin."], minutes: 17, servings: 2, prepMinutes: 5, cookMinutes: 12, difficulty: "Kolay", tips: ["Kabak suyunu sıkmak sulanmayı önler."], serving: "Kahvaltıda sıcak servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n04_012", title: "Mısır ekmeği (kahvaltılık)", category: "Kahvaltılıklar", ingredients: ["1,5 su bardağı mısır unu", "Yarım su bardağı un", "1 su bardağı yoğurt", "2 yumurta", "Yarım su bardağı sıvı yağ", "1 paket kabartma tozu", "1 tatlı kaşığı tuz"], steps: ["Fırını 190 °C'ye ısıtın.", "Tüm malzemeyi karıştırın.", "Yağlanmış kare kalıba dökün.", "30 dakika pişirin.", "Kare kesip servis edin."], minutes: 40, servings: 8, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 190, tips: ["Karadeniz kahvaltısının vazgeçilmezidir."], serving: "Peynir ve tereyağıyla.", storage: "Kapalı kapta 2 gün."),
  GeneralRecipe(id: "n04_013", title: "Kuymak (mıhlama)", category: "Kahvaltılıklar", ingredients: ["2 yemek kaşığı tereyağı", "2 yemek kaşığı mısır unu", "1 su bardağı su", "150 g çeçil veya tel peynir"], steps: ["Tereyağını eritin.", "Mısır ununu 2 dakika kavurun.", "Suyu ekleyip karıştırın.", "Peyniri ekleyip uzayana kadar pişirin.", "Sıcak servis edin."], minutes: 20, servings: 2, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", tips: ["Peynir tuzlu olduğundan tuz eklemeyin."], serving: "Kahvaltıda sıcak servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n04_014", title: "Fırında granola", category: "Kahvaltılıklar", ingredients: ["3 su bardağı yulaf", "1 su bardağı karışık kuruyemiş", "3 yemek kaşığı bal", "3 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tarçın", "Yarım su bardağı kuru üzüm"], steps: ["Fırını 160 °C'ye ısıtın.", "Yulaf, kuruyemiş ve tarçını karıştırın.", "Bal ve yağı ekleyip harmanlayın.", "Tepsiye yayıp 25 dakika, 2 kez karıştırarak pişirin.", "Soğuyunca üzümü ekleyin."], minutes: 35, servings: 8, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 160, tips: ["Soğurken çıtırlaşır."], serving: "Yoğurt veya sütle.", storage: "Kavanozda 2 hafta."),
  GeneralRecipe(id: "n04_015", title: "Peynirli patatesli rösti", category: "Kahvaltılıklar", ingredients: ["3 patates", "2 yemek kaşığı rendelenmiş kaşar", "1 yumurta", "2 yemek kaşığı sıvı yağ", "1 çay kaşığı tuz"], steps: ["Patatesleri rendeleyip suyunu iyice sıkın.", "Yumurta, kaşar ve tuzla karıştırın.", "Yağda yassı köfteler hâlinde dökün.", "Her yüzünü 5 dakika kızartın.", "Yoğurtla servis edin."], minutes: 25, servings: 2, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Suyu iyi sıkılan patates çıtır olur."], serving: "Kahvaltıda sıcak servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n04_101", title: "Kazandibi (tavada)", category: "Tatlılar", ingredients: ["1 litre süt", "1 su bardağı şeker", "3 yemek kaşığı pirinç unu", "2 yemek kaşığı nişasta", "2 yemek kaşığı un", "1 paket vanilin", "1 yemek kaşığı tereyağı", "Taban için 2 yemek kaşığı pudra şekeri"], steps: ["Süt, şeker, unlar ve nişastayı soğukken çırpıp kaynayana kadar karıştırarak pişirin.", "Koyulaşınca vanilin ve tereyağını ekleyin.", "Tavaya ince pudra şekeri serpip orta ateşte karamelize edin.", "Muhallebiyi tavaya dökün, tabanı 5–6 dakika yakın.", "Soğutup rulo şeklinde kesin."], minutes: 35, servings: 8, prepMinutes: 10, cookMinutes: 25, difficulty: "Orta", tips: ["Tabanı yakarken kenarlardan koku gelince ocaktan alın."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n04_102", title: "Keşkül", category: "Tatlılar", ingredients: ["1 litre süt", "1 su bardağı şeker", "1 su bardağı badem unu", "2 yemek kaşığı pirinç unu", "1 yumurta sarısı", "1 paket vanilin", "2 yemek kaşığı hindistan cevizi ve 2 yemek kaşığı Antep fıstığı"], steps: ["Süt, şeker ve badem ununu kaynatın.", "Pirinç unu ve yumurta sarısını biraz sütle açıp ekleyin.", "Koyulaşana kadar karıştırarak pişirin.", "Vanilini ekleyin.", "Kaselere alıp soğutun, süsleyin."], minutes: 30, servings: 6, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Badem unu keşküle yoğun aroma verir."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n04_103", title: "Supangle", category: "Tatlılar", ingredients: ["1 litre süt", "1 su bardağı şeker", "3 yemek kaşığı kakao", "3 yemek kaşığı un", "2 yemek kaşığı nişasta", "100 g bitter çikolata", "1 yemek kaşığı tereyağı"], steps: ["Süt, şeker, kakao, un ve nişastayı çırpın.", "Sürekli karıştırarak kaynatın.", "Koyulaşınca çikolata ve tereyağını ekleyin.", "Kaselere dökün.", "Soğutup çikolata rendesiyle servis edin."], minutes: 25, servings: 6, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Kaseye bisküvi koyarak taban yapabilirsiniz."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n04_104", title: "Aşure", category: "Tatlılar", ingredients: ["1 su bardağı aşurelik buğday", "Yarım su bardağı nohut ve yarım su bardağı kuru fasulye (haşlanmış)", "1 su bardağı şeker", "10 kuru kayısı, 10 kuru incir", "Yarım su bardağı kuru üzüm", "1 portakal kabuğu", "Yarım su bardağı ceviz, 3 yemek kaşığı nar tanesi, 1 çay kaşığı tarçın"], steps: ["Buğdayı bir gece ıslatıp 8 bardak suyla 1 saat pişirin.", "Nohut, fasulye ve doğranmış kuru meyveleri ekleyin.", "Şekeri ve portakal kabuğunu ekleyip 45 dakika pişirin.", "Kaselere paylaştırıp soğutun.", "Ceviz, nar ve tarçınla süsleyin."], minutes: 150, servings: 12, prepMinutes: 30, cookMinutes: 120, difficulty: "Zor", tips: ["Aşure soğudukça koyulaşır."], serving: "Soğuk.", storage: "Buzdolabında 5 gün."),
  GeneralRecipe(id: "n04_105", title: "Profiterol", category: "Tatlılar", ingredients: ["1 su bardağı su", "125 g tereyağı", "1 su bardağı un", "4 yumurta", "Krema: 2 su bardağı süt, 3 yemek kaşığı şeker, 2 yemek kaşığı nişasta", "Sos: 150 g bitter çikolata, yarım su bardağı süt"], steps: ["Su ve tereyağını kaynatıp unu ekleyin, hamur toplanana kadar karıştırın.", "Soğuyunca yumurtaları tek tek yedirin.", "Sıkma torbasıyla ceviz büyüklüğünde sıkıp 200 °C'de 25 dakika pişirin (ilk 15 dakika kapağı açmayın).", "Kremayı pişirip soğutun, hamurların içine doldurun.", "Eritilmiş çikolata sosunu üzerine dökün."], minutes: 60, servings: 8, prepMinutes: 30, cookMinutes: 30, difficulty: "Zor", ovenCelsius: 200, tips: ["Fırın kapağını erken açmak hamurun inmesine neden olur."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n04_106", title: "Tiramisu (yumurtasız)", category: "Tatlılar", ingredients: ["250 g mascarpone veya labne", "1 su bardağı krema", "Yarım su bardağı pudra şekeri", "1 paket kedi dili bisküvi", "1 su bardağı soğuk kahve", "2 yemek kaşığı kakao"], steps: ["Kremayı pudra şekeriyle çırpın, mascarponeyi ekleyip karıştırın.", "Bisküvileri kahveye hızlıca batırıp kaba dizin.", "Kremanın yarısını yayın.", "Bir kat daha bisküvi ve krema yapın.", "En az 4 saat buzdolabında bekletip kakao serpin."], minutes: 25, servings: 8, prepMinutes: 25, cookMinutes: 0, difficulty: "Orta", tips: ["Bisküvileri kahvede bekletmeyin; dağılır."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n04_107", title: "Elmalı turta", category: "Tatlılar", ingredients: ["250 g tereyağı", "1 su bardağı pudra şekeri", "1 yumurta", "3 su bardağı un", "İç: 5 elma, yarım su bardağı şeker, 1 tatlı kaşığı tarçın, yarım su bardağı ceviz"], steps: ["Elmaları şeker ve tarçınla suyunu çekene kadar pişirip cevizle soğutun.", "Tereyağı, pudra şekeri, yumurta ve unla hamur yapın; 30 dakika dinlendirin.", "Hamurun üçte ikisini tart kalıbına yayın, harcı koyun.", "Kalan hamurla kafes yapın.", "180 °C'de 40 dakika pişirin."], minutes: 70, servings: 8, prepMinutes: 30, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 180, tips: ["Hamuru soğuk tutun; kolay açılır."], serving: "Ilık.", storage: "Oda sıcaklığında 2 gün."),
  GeneralRecipe(id: "n04_108", title: "Cheesecake (fırında)", category: "Tatlılar", ingredients: ["200 g yulaflı bisküvi", "80 g eritilmiş tereyağı", "600 g labne", "1 su bardağı şeker", "3 yumurta", "1 su bardağı krema", "2 yemek kaşığı un", "1 limon kabuğu"], steps: ["Bisküviyi ufalayıp tereyağıyla karıştırın, kalıbın tabanına bastırın.", "Labne ve şekeri çırpın; yumurtaları tek tek ekleyin.", "Krema, un ve limon kabuğunu ekleyin.", "170 °C'de 60 dakika pişirin; fırında kapak aralık soğutun.", "En az 6 saat buzdolabında bekletin."], minutes: 90, servings: 10, prepMinutes: 30, cookMinutes: 60, difficulty: "Zor", ovenCelsius: 170, tips: ["Yavaş soğutmak yüzeyin çatlamasını önler."], serving: "Meyve sosuyla soğuk.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "n04_109", title: "Trileçe", category: "Tatlılar", ingredients: ["4 yumurta", "1 su bardağı şeker", "1 su bardağı un", "1 paket kabartma tozu", "Sütlü karışım: 1 su bardağı süt, yarım su bardağı krema, 3 yemek kaşığı şeker", "Karamel: 4 yemek kaşığı şeker, yarım su bardağı krema"], steps: ["Yumurta ve şekeri 5 dakika köpürtün, un ve kabartma tozunu ekleyin.", "Kek hamurunu 180 °C'de 30 dakika pişirin.", "Sütlü karışımı ılık kekin üzerine dökün, emmesini bekleyin.", "Şekeri karamelize edip kremayı ekleyerek sos yapın.", "Sosu üzerine yayıp soğutun."], minutes: 60, servings: 10, prepMinutes: 25, cookMinutes: 35, difficulty: "Orta", ovenCelsius: 180, tips: ["Kek tamamen soğumadan sütü dökün."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n04_110", title: "Güllaç", category: "Tatlılar", ingredients: ["10 yaprak güllaç", "1,5 litre süt", "1,5 su bardağı şeker", "1 tatlı kaşığı gül suyu", "1 su bardağı ceviz", "Yarım su bardağı nar tanesi"], steps: ["Süt ve şekeri ılık olana kadar ısıtın, gül suyunu ekleyin.", "Tepsiye bir yaprak güllaç koyup sütle ıslatın.", "Yarısına kadar her katı ıslatarak dizin, cevizi serpin.", "Kalan yaprakları aynı şekilde kapatın.", "Buzdolabında 3 saat bekletip nar ile servis edin."], minutes: 30, servings: 8, prepMinutes: 20, cookMinutes: 10, difficulty: "Orta", tips: ["Süt ılık olmalı; yapraklar kolay emer."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n04_111", title: "İrmikli portakal tatlısı (şerbetli)", category: "Tatlılar", ingredients: ["2 su bardağı irmik", "1 su bardağı yoğurt", "1 su bardağı şeker", "2 yumurta", "Yarım su bardağı sıvı yağ", "1 paket kabartma tozu", "1 portakal kabuğu", "Şerbet: 2 su bardağı şeker, 2,5 su bardağı portakal suyu"], steps: ["Şerbeti 10 dakika kaynatıp soğutun.", "Hamur malzemelerini karıştırın.", "Yağlı tepside 180 °C'de 30 dakika pişirin.", "Sıcak tatlıya soğuk şerbeti dökün.", "Şerbeti çekince dilimleyin."], minutes: 50, servings: 10, prepMinutes: 20, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 180, tips: ["Portakal suyu şerbete taze aroma verir."], serving: "Oda sıcaklığında.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n04_112", title: "Ekmek kadayıfı (pratik)", category: "Tatlılar", ingredients: ["1 paket ekmek kadayıfı", "3 su bardağı şeker", "3 su bardağı su", "Yarım limon", "200 g kaymak veya süzme yoğurt", "3 yemek kaşığı Antep fıstığı"], steps: ["Şeker ve suyu 10 dakika kaynatın, limonu ekleyin.", "Kadayıfı tepsiye koyup sıcak şerbetin yarısını dökün.", "Kısık ateşte 10 dakika şerbeti emdirin, çevirip kalan şerbeti ekleyin.", "Soğumaya bırakın.", "Kaymak ve fıstıkla servis edin."], minutes: 45, servings: 8, prepMinutes: 15, cookMinutes: 30, difficulty: "Orta", tips: ["Kadayıfın şerbeti tamamen çekmesini bekleyin."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n04_113", title: "Çikolatalı mousse (avokadolu)", category: "Tatlılar", ingredients: ["2 olgun avokado", "4 yemek kaşığı kakao", "4 yemek kaşığı bal", "4 yemek kaşığı süt", "1 tutam tuz"], steps: ["Avokadoları soyup blendera alın.", "Kakao, bal, süt ve tuzu ekleyin.", "Pürüzsüz olana kadar çekin.", "Kaselere paylaştırın.", "1 saat soğutup servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Avokado tadı kakaoyla tamamen kaybolur."], serving: "Soğuk.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n04_114", title: "Fırında elmalı tarçınlı yulaf tatlısı (kase)", category: "Tatlılar", ingredients: ["2 elma", "4 yemek kaşığı yulaf", "1 yemek kaşığı tereyağı", "1 yemek kaşığı bal", "1 tatlı kaşığı tarçın", "2 yemek kaşığı ceviz"], steps: ["Fırını 180 °C'ye ısıtın.", "Elmaları küp doğrayıp kaselere paylaştırın.", "Yulaf, tereyağı, bal, tarçın ve cevizi ovalayıp üzerine serpin.", "20 dakika pişirin.", "Ilık servis edin."], minutes: 30, servings: 2, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 180, tips: ["Tek kişilik kaselerde pratik bir tatlıdır."], serving: "Yoğurtla ılık.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n04_115", title: "Lokma (evde)", category: "Tatlılar", ingredients: ["2 su bardağı un", "1 paket instant maya", "1 tatlı kaşığı şeker", "1,5 su bardağı ılık su", "1 tutam tuz", "Şerbet: 2 su bardağı şeker, 2 su bardağı su, yarım limon", "Kızartmak için 2 su bardağı sıvı yağ"], steps: ["Şerbeti kaynatıp soğutun.", "Un, maya, şeker, tuz ve suyla akışkan hamur yapıp 1 saat mayalandırın.", "Hamuru elinizle sıkıp ıslak kaşıkla kızgın yağa bırakın.", "Altın rengi olana kadar çevirerek kızartın.", "Sıcak lokmaları soğuk şerbete atıp 1 dakika bekletin."], minutes: 90, servings: 8, prepMinutes: 70, cookMinutes: 20, difficulty: "Orta", tips: ["Yağ çok kızgın olursa içi pişmez."], serving: "Ilık.", storage: "Aynı gün."),
  GeneralRecipe(id: "n05_001", title: "Hamsi tava", category: "Balık ve deniz ürünleri", ingredients: ["1 kg hamsi (temizlenmiş)", "1 su bardağı mısır unu", "1 tatlı kaşığı tuz", "Kızartmak için 2 su bardağı sıvı yağ", "1 limon"], steps: ["Hamsileri yıkayıp süzün.", "Mısır unu ve tuzu karıştırın.", "Hamsileri una bulayıp tavaya yelpaze şeklinde dizin.", "Kızgın yağda her yüzü 2 dakika kızartın.", "Limon ve soğanla servis edin."], minutes: 30, servings: 4, prepMinutes: 20, cookMinutes: 10, difficulty: "Kolay", tips: ["Unu fazla bulaştırmayın; silkeleyin."], serving: "Sıcak, mısır ekmeğiyle.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_002", title: "Buğulama levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 levrek fileto", "1 domates", "2 sivri biber", "1 soğan", "4 mantar", "2 yemek kaşığı zeytinyağı", "Yarım limon", "1 çay kaşığı tuz, dereotu"], steps: ["Soğanı halka, sebzeleri dilim doğrayın.", "Tavaya sebzeleri yayıp balıkları üzerine koyun.", "Yağ, limon, tuz ve yarım bardak su ekleyin.", "Kapağı kapalı kısık ateşte 15–18 dakika pişirin.", "Dereotuyla servis edin."], minutes: 35, servings: 2, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Buğulama kendi buharında pişer; fazla su eklemeyin."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_003", title: "Kremalı karides sote", category: "Balık ve deniz ürünleri", ingredients: ["400 g ayıklanmış karides", "2 diş sarımsak", "1 kırmızı biber", "Yarım su bardağı krema", "2 yemek kaşığı tereyağı", "1 çay kaşığı tuz, pul biber", "Yarım demet maydanoz"], steps: ["Tereyağında sarımsak ve biberi 2 dakika çevirin.", "Karidesleri ekleyip 2 dakika, pembeleşene kadar pişirin.", "Kremayı ekleyip 2 dakika kaynatın.", "Tuz ve pul biberi ekleyin.", "Maydanozla servis edin."], minutes: 22, servings: 4, prepMinutes: 10, cookMinutes: 12, difficulty: "Kolay", tips: ["Karides pembeleşince pişmiştir; fazlası sertleştirir."], serving: "Pilav veya ekmekle sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_004", title: "Fırında palamut", category: "Balık ve deniz ürünleri", ingredients: ["4 dilim palamut", "2 soğan", "2 domates", "3 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı tuz, karabiber"], steps: ["Fırını 200 °C'ye ısıtın.", "Soğanları halka doğrayıp tepsiye yayın.", "Balıkları üzerine dizin, domates dilimleri koyun.", "Yağ, limon ve baharatları ekleyin.", "25 dakika pişirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Soğan yatağı balığın yapışmasını önler."], serving: "Roka ile.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_005", title: "Midye tava (evde)", category: "Balık ve deniz ürünleri", ingredients: ["500 g ayıklanmış midye içi", "1 su bardağı un", "1 su bardağı soğuk bira veya maden suyu", "1 çay kaşığı tuz, karbonat", "Kızartmak için 2 su bardağı sıvı yağ", "Tarator: 1 dilim ekmek, yarım su bardağı ceviz, 1 diş sarımsak, 2 yemek kaşığı yoğurt"], steps: ["Un, tuz, karbonat ve soğuk sıvıyla akışkan hamur yapın.", "Midyeleri kurulayıp hamura batırın.", "Kızgın yağda 2 dakika kızartın.", "Tarator malzemelerini robotta çekin.", "Midyeleri taratorla servis edin."], minutes: 40, servings: 4, prepMinutes: 30, cookMinutes: 10, difficulty: "Orta", tips: ["Sıvının soğuk olması hamuru çıtır yapar."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_006", title: "Somon ızgara (limon tereyağlı)", category: "Balık ve deniz ürünleri", ingredients: ["2 dilim somon", "1 yemek kaşığı tereyağı", "1 limon", "1 diş sarımsak", "1 çay kaşığı tuz, karabiber"], steps: ["Somonu tuz ve karabiberle tatlandırın.", "Izgara tavada derili tarafı altta 5 dakika pişirin.", "Çevirip 3 dakika daha pişirin.", "Tereyağında sarımsak ve limonu eritip sos yapın.", "Sosu somona gezdirin."], minutes: 15, servings: 2, prepMinutes: 5, cookMinutes: 10, difficulty: "Kolay", tips: ["Derili taraf çıtırlaşınca kendiliğinden ayrılır."], serving: "Pilav ve sebzeyle.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_007", title: "Fırında sardalya", category: "Balık ve deniz ürünleri", ingredients: ["1 kg sardalya (temizlenmiş)", "3 yemek kaşığı zeytinyağı", "2 limon", "3 diş sarımsak", "1 tatlı kaşığı kekik, tuz"], steps: ["Fırını 220 °C'ye ısıtın.", "Sardalyaları kurulayıp tepsiye dizin.", "Yağ, limon suyu, ezilmiş sarımsak, kekik ve tuzu karıştırıp üzerine dökün.", "12–15 dakika pişirin.", "Limon dilimleriyle servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 220, tips: ["Sardalya omega-3 açısından çok zengindir."], serving: "Roka ile sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_008", title: "Kalamar tava (fırında)", category: "Balık ve deniz ürünleri", ingredients: ["500 g kalamar halka", "1 su bardağı galeta unu", "2 yumurta", "Yarım su bardağı un", "1 çay kaşığı tuz", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 220 °C'ye ısıtın.", "Kalamarı kurulayın.", "Una, yumurtaya ve galeta ununa bulayın.", "Tepsiye dizip yağ gezdirin.", "12–15 dakika pişirin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Orta", ovenCelsius: 220, tips: ["Kalamar ya çok kısa ya çok uzun pişmeli; arası sert olur."], serving: "Tarator veya limonla.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_009", title: "Balık çorbası", category: "Balık ve deniz ürünleri", ingredients: ["500 g kılçıksız beyaz balık", "1 havuç", "1 patates", "1 soğan", "1 kereviz sapı", "2 yemek kaşığı zeytinyağı", "6 su bardağı su", "1 limon", "1 tatlı kaşığı tuz"], steps: ["Sebzeleri küp doğrayıp yağda 5 dakika çevirin.", "Suyu ekleyip 15 dakika pişirin.", "Balığı parçalayıp ekleyin, 8 dakika pişirin.", "Limon ve tuzla tatlandırın.", "Maydanozla servis edin."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Balığı en son ekleyin; dağılmasın."], serving: "Sıcak.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n05_010", title: "Uskumru dolması (fırında)", category: "Balık ve deniz ürünleri", ingredients: ["4 uskumru (kılçığı ayıklanmış)", "1 soğan", "2 yemek kaşığı pirinç", "2 yemek kaşığı kuş üzümü", "2 yemek kaşığı çam fıstığı", "1 tatlı kaşığı yenibahar, tuz", "2 yemek kaşığı zeytinyağı"], steps: ["Soğanı yağda kavurup pirinç, üzüm, fıstık ve baharatı ekleyin; yarım bardak suyla 10 dakika pişirin.", "Uskumruların içini harçla doldurun.", "Tepsiye dizip yağ sürün.", "190 °C'de 25 dakika pişirin.", "Limonla servis edin."], minutes: 55, servings: 4, prepMinutes: 30, cookMinutes: 25, difficulty: "Zor", ovenCelsius: 190, tips: ["Balıkçıdan kılçığını ayıklatmanız işi kolaylaştırır."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_011", title: "Levrek kağıtta (papillote)", category: "Balık ve deniz ürünleri", ingredients: ["2 levrek fileto", "1 kabak", "1 havuç", "1 limon", "2 yemek kaşığı zeytinyağı", "Yarım demet dereotu, 1 çay kaşığı tuz"], steps: ["Fırını 200 °C'ye ısıtın.", "Sebzeleri jülyen doğrayıp pişirme kâğıdına yerleştirin.", "Balığı üzerine koyup yağ, limon, dereotu ve tuz ekleyin.", "Kâğıdı paket şeklinde kapatın.", "20 dakika pişirin."], minutes: 30, servings: 2, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 200, tips: ["Paket içindeki buhar balığı nemli tutar."], serving: "Paketi masada açarak servis edin.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_012", title: "Karidesli sebzeli pilav", category: "Balık ve deniz ürünleri", ingredients: ["300 g karides", "1,5 su bardağı pirinç", "1 su bardağı bezelye", "1 kırmızı biber", "2 yemek kaşığı tereyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz, zerdeçal"], steps: ["Karidesleri tereyağında 2 dakika çevirip alın.", "Biber ve pirinci kavurun.", "Su, tuz, zerdeçal ve bezelyeyi ekleyin.", "15 dakika pişirin.", "Karidesleri ekleyip 10 dakika demlendirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Karidesi demlenme sırasında ısıtmak yeterlidir."], serving: "Sıcak.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n05_013", title: "Somonlu ıspanaklı makarna", category: "Balık ve deniz ürünleri", ingredients: ["350 g penne", "200 g somon", "200 g ıspanak", "Yarım su bardağı krema", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Makarnayı haşlayın.", "Somonu küp doğrayıp yağda 4 dakika pişirin.", "Sarımsak ve ıspanağı ekleyip soldurun.", "Kremayı ekleyin.", "Makarnayla karıştırın."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Füme somon da kullanılabilir."], serving: "Sıcak.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n05_014", title: "Alabalık ızgara (bademli)", category: "Balık ve deniz ürünleri", ingredients: ["2 alabalık", "2 yemek kaşığı tereyağı", "3 yemek kaşığı badem dilimi", "1 limon", "1 çay kaşığı tuz"], steps: ["Balıkları tuzlayıp ızgarada her yüzü 5 dakika pişirin.", "Tereyağında bademleri 2 dakika kızartın.", "Limon suyunu ekleyin.", "Balığın üzerine gezdirin.", "Servis edin."], minutes: 17, servings: 2, prepMinutes: 5, cookMinutes: 12, difficulty: "Kolay", tips: ["Bademi yakmamaya dikkat edin."], serving: "Roka ile.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_015", title: "Çipura ızgara", category: "Balık ve deniz ürünleri", ingredients: ["2 çipura", "2 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı tuz", "1 demet roka, 1 kırmızı soğan"], steps: ["Balıklara çapraz çizik atın.", "Yağ ve tuzla ovun.", "Kızgın ızgarada her yüzü 6–7 dakika pişirin.", "Limon sıkın.", "Roka ve soğanla servis edin."], minutes: 20, servings: 2, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", tips: ["Izgara iyice ısınmazsa balık yapışır."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n05_101", title: "Pancarlı humus", category: "Mezeler", ingredients: ["2 su bardağı haşlanmış nohut", "1 haşlanmış pancar", "3 yemek kaşığı tahin", "1 limon suyu", "1 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 çay kaşığı kimyon, tuz"], steps: ["Pancarı doğrayın.", "Tüm malzemeyi robota alın.", "Pürüzsüz olana kadar çekin; gerekirse buzlu su ekleyin.", "Tabağa yayın.", "Zeytinyağıyla servis edin."], minutes: 15, servings: 6, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Pancar humusa canlı renk ve tatlılık verir."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n05_102", title: "Deniz börülcesi salatası", category: "Mezeler", ingredients: ["300 g deniz börülcesi", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 limon"], steps: ["Börülceleri yıkayıp kaynar suda 4 dakika haşlayın.", "Soğuk suya alın.", "Lifli kısımlarını sıyırarak ayıklayın.", "Sarımsak, yağ ve limonla karıştırın.", "Soğuk servis edin."], minutes: 15, servings: 4, prepMinutes: 10, cookMinutes: 5, difficulty: "Kolay", tips: ["Deniz börülcesi tuzludur; tuz eklemeyin."], serving: "Soğuk, balıkla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n05_103", title: "Muhammara", category: "Mezeler", ingredients: ["3 köz kırmızı biber", "1 su bardağı ceviz", "3 yemek kaşığı galeta unu", "2 yemek kaşığı nar ekşisi", "1 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kimyon, pul biber"], steps: ["Biberleri soyun.", "Cevizi iri kıyın.", "Tüm malzemeyi robotta kısa kısa çekin.", "Kıvamı galeta unuyla ayarlayın.", "Zeytinyağıyla servis edin."], minutes: 10, servings: 6, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Dokulu kalması için fazla çekmeyin."], serving: "Soğuk.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "n05_104", title: "Kabak çiçeği dolması", category: "Mezeler", ingredients: ["16 kabak çiçeği", "1 su bardağı pirinç", "1 soğan", "Yarım demet dereotu ve nane", "4 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz, şeker"], steps: ["Çiçeklerin içindeki pistilleri dikkatle alın.", "Soğanı yağda kavurup pirinç, otlar ve baharatla harç yapın.", "Çiçekleri yarısına kadar doldurup uçlarını kıvırın.", "Tencereye dizip 1 bardak sıcak su ve yağ ekleyin.", "Kısık ateşte 30 dakika pişirip soğutun."], minutes: 60, servings: 4, prepMinutes: 30, cookMinutes: 30, difficulty: "Orta", tips: ["Pirinç şişeceğinden tam doldurmayın."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n05_105", title: "Atom (yoğurtlu kuru biber)", category: "Mezeler", ingredients: ["2 su bardağı süzme yoğurt", "4 kuru acı biber", "2 yemek kaşığı tereyağı", "1 diş sarımsak"], steps: ["Yoğurdu sarımsakla çırpıp tabağa yayın.", "Tereyağını eritin.", "Kuru biberleri 1 dakika yağda kızartın.", "Biberleri yoğurdun üzerine koyun.", "Yağı gezdirin."], minutes: 15, servings: 4, prepMinutes: 10, cookMinutes: 5, difficulty: "Kolay", tips: ["Biberler çok acıysa sayısını azaltın."], serving: "Soğuk.", storage: "Aynı gün."),
  GeneralRecipe(id: "n05_106", title: "Zeytinyağlı yaprak sarma", category: "Mezeler", ingredients: ["500 g asma yaprağı", "1,5 su bardağı pirinç", "3 soğan", "Yarım su bardağı zeytinyağı", "2 yemek kaşığı kuş üzümü ve çam fıstığı", "1 tatlı kaşığı nane, yenibahar, tarçın, tuz, şeker", "1 limon"], steps: ["Soğanları yağda kavurup fıstık, pirinç ve baharatları ekleyin; yarım bardak suyla 5 dakika pişirin.", "Yaprakları haşlayıp sap kısmını kesin.", "Harcı yapraklara koyup sıkıca sarın.", "Tencereye dizip limon ve 2 bardak sıcak su ekleyin, tabakla bastırın.", "Kısık ateşte 45 dakika pişirip tencerede soğutun."], minutes: 110, servings: 8, prepMinutes: 60, cookMinutes: 50, difficulty: "Zor", tips: ["Sıkı sarmak pişerken açılmayı önler."], serving: "Soğuk, limonla.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "n05_107", title: "Zeytinyağlı biber dolması", category: "Mezeler", ingredients: ["10 dolmalık biber", "1 su bardağı pirinç", "2 soğan", "1 domates", "Yarım su bardağı zeytinyağı", "1 tatlı kaşığı nane, tuz, şeker"], steps: ["Soğanı yağda kavurup pirinç, domates ve baharatı ekleyin.", "Yarım bardak suyla 5 dakika pişirin.", "Biberleri doldurup kapaklarını kapatın.", "Tencereye dizip 1,5 bardak sıcak su ekleyin.", "40 dakika pişirip soğutun."], minutes: 70, servings: 6, prepMinutes: 30, cookMinutes: 40, difficulty: "Orta", tips: ["İç harç yarı pişmiş olmalı; tencerede tamamlanır."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n05_108", title: "Babagannuş (közlü patlıcan)", category: "Mezeler", ingredients: ["3 patlıcan", "2 domates", "1 sivri biber", "1 diş sarımsak", "2 yemek kaşığı nar ekşisi", "2 yemek kaşığı zeytinyağı", "Yarım demet maydanoz"], steps: ["Patlıcanları közleyip soyun.", "Domates ve biberi küçük doğrayın.", "Patlıcanı bıçakla kıyın.", "Hepsini sarımsak, nar ekşisi ve yağla karıştırın.", "Maydanozla servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Antakya usulü tahinsiz yapılır."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n05_109", title: "Cevizli kereviz salatası (yoğurtlu)", category: "Mezeler", ingredients: ["1 kereviz kökü", "1 su bardağı yoğurt", "2 yemek kaşığı mayonez", "Yarım su bardağı ceviz", "1 diş sarımsak", "Yarım limon"], steps: ["Kerevizi rendeleyip limonla harmanlayın.", "Yoğurt, mayonez ve sarımsağı karıştırın.", "Kerevizi ekleyin.", "Cevizi katın.", "1 saat dinlendirin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Dinlenince kereviz yumuşar."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n05_110", title: "Fasulye pilaki (zeytinyağlı)", category: "Mezeler", ingredients: ["2 su bardağı haşlanmış kuru fasulye", "2 havuç", "1 patates", "1 soğan", "3 diş sarımsak", "4 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı şeker, tuz"], steps: ["Soğan ve sarımsağı yağda kavurun.", "Havuç ve patatesi ekleyin.", "Fasulye ve 1 bardak suyu ekleyin.", "20 dakika pişirin.", "Limon ve maydanozla soğuk servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Pilaki dinlendikçe lezzetlenir."], serving: "Soğuk.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "n05_111", title: "Girit ezmesi", category: "Mezeler", ingredients: ["200 g beyaz peynir", "100 g lor", "Yarım su bardağı ceviz", "1 diş sarımsak", "4 yemek kaşığı zeytinyağı", "Yarım demet dereotu, 4–5 dal nane, yarım demet maydanoz"], steps: ["Peynir ve loru ezin.", "Kıyılmış yeşillikleri ekleyin.", "Ceviz ve sarımsağı katın.", "Zeytinyağıyla karıştırın.", "Soğuk servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Peynirin tuzu yeterlidir."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n05_112", title: "Közlenmiş biber salatası", category: "Mezeler", ingredients: ["6 kapya biber", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 yemek kaşığı sirke", "1 çay kaşığı tuz", "Yarım demet maydanoz"], steps: ["Biberleri fırında veya ocakta közleyin.", "Poşette 10 dakika bekletip soyun.", "Şeritler hâlinde doğrayın.", "Sarımsak, yağ, sirke ve tuzla karıştırın.", "Maydanozla servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Biberler dinlendikçe lezzetlenir."], serving: "Soğuk.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "n05_113", title: "Topik", category: "Mezeler", ingredients: ["2 su bardağı haşlanmış nohut", "4 soğan", "3 yemek kaşığı tahin", "1 tatlı kaşığı tarçın, kimyon, yenibahar", "2 yemek kaşığı kuş üzümü", "2 yemek kaşığı çam fıstığı", "1 tatlı kaşığı tuz"], steps: ["Soğanları bütün hâlde 30 dakika haşlayıp ince kıyın ve suyunu sıkın.", "Nohudu ezin.", "Soğan, tahin, baharatlar, üzüm ve fıstıkla karıştırın.", "Tülbente sarıp top şekli verin.", "Buzdolabında soğutup dilimleyin."], minutes: 90, servings: 6, prepMinutes: 30, cookMinutes: 60, difficulty: "Orta", tips: ["Ermeni mutfağının klasik soğuk mezesidir."], serving: "Soğuk.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "n05_114", title: "Patlıcan söğürme", category: "Mezeler", ingredients: ["3 patlıcan", "1 kırmızı soğan", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı tuz, pul biber"], steps: ["Patlıcanları közleyip soyun.", "Soğanı ince doğrayın.", "Patlıcanı bıçakla kıyın.", "Hepsini yağ, limon ve baharatla karıştırın.", "Maydanozla servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Közün dumanlı tadı mezenin karakteridir."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n05_115", title: "Cacık", category: "Mezeler", ingredients: ["2 su bardağı yoğurt", "2 salatalık", "1 diş sarımsak", "1 su bardağı soğuk su", "1 tatlı kaşığı kuru nane", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Salatalığı küçük doğrayın veya rendeleyin.", "Yoğurdu sarımsak ve tuzla çırpın.", "Suyu ekleyip kıvamını ayarlayın.", "Salatalığı ekleyin.", "Nane ve zeytinyağıyla servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Koyu cacık için su eklemeyin."], serving: "Soğuk.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n05_201", title: "Fırın makarna (beşamelli)", category: "Makarnalar", ingredients: ["500 g kalem makarna", "Beşamel: 3 yemek kaşığı tereyağı, 3 yemek kaşığı un, 4 su bardağı süt", "2 yumurta", "1,5 su bardağı rendelenmiş kaşar", "1 çay kaşığı tuz, karabiber, muskat"], steps: ["Makarnayı haşlayıp süzün.", "Beşamel sosu hazırlayın, biraz ılıyınca yumurtaları ekleyin.", "Makarnayı sosun yarısı ve kaşarın yarısıyla karıştırıp kaba yayın.", "Kalan sos ve kaşarı üzerine dökün.", "180 °C'de 30 dakika pişirin."], minutes: 50, servings: 6, prepMinutes: 20, cookMinutes: 30, difficulty: "Orta", ovenCelsius: 180, tips: ["Yumurta fırın makarnanın dilimlenmesini sağlar."], serving: "Ilık.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n05_202", title: "Mantı (pratik, hazır yaprakla)", category: "Makarnalar", ingredients: ["300 g yufka veya gyoza yaprağı", "250 g kıyma", "1 soğan (rendelenmiş)", "1 tatlı kaşığı tuz, karabiber", "2 su bardağı sarımsaklı yoğurt", "3 yemek kaşığı tereyağı", "1 tatlı kaşığı pul biber, nane"], steps: ["Kıyma, soğan ve baharatı yoğurun.", "Yufkayı küçük karelere kesip ortasına harç koyun ve uçlarını birleştirin.", "Kaynar tuzlu suda 10 dakika haşlayın.", "Tabağa alıp sarımsaklı yoğurt dökün.", "Tereyağında pul biber ve naneyi kızdırıp gezdirin."], minutes: 55, servings: 4, prepMinutes: 40, cookMinutes: 15, difficulty: "Zor", tips: ["Mantıları dondurup sonra pişirebilirsiniz."], serving: "Sıcak.", storage: "Pişmemiş hâli dondurucuda 2 ay."),
  GeneralRecipe(id: "n05_203", title: "Kıymalı domatesli spagetti", category: "Makarnalar", ingredients: ["350 g spagetti", "250 g kıyma", "1 soğan", "400 g domates", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, kekik"], steps: ["Kıymayı soğanla kavurun.", "Salça ve domatesi ekleyip 15 dakika pişirin.", "Spagettiyi haşlayın.", "Sosla karıştırın.", "Rendelenmiş peynirle servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Haşlama suyundan bir kepçe sosa eklenebilir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n05_204", title: "Pesto soslu makarna", category: "Makarnalar", ingredients: ["350 g linguine", "2 demet fesleğen", "3 yemek kaşığı çam fıstığı veya ceviz", "1 diş sarımsak", "Yarım su bardağı parmesan", "Yarım su bardağı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Fesleğen, fıstık, sarımsak ve tuzu robotta çekin.", "Zeytinyağını yavaşça ekleyin.", "Parmesanı karıştırın.", "Haşlanmış makarnayı pestoyla harmanlayın.", "Biraz haşlama suyuyla açın."], minutes: 22, servings: 4, prepMinutes: 10, cookMinutes: 12, difficulty: "Kolay", tips: ["Pestoyu ısıtmayın; rengi kararır."], serving: "Sıcak veya ılık.", storage: "Pesto buzdolabında 4 gün."),
  GeneralRecipe(id: "n05_205", title: "Arabiata (acılı domates soslu penne)", category: "Makarnalar", ingredients: ["350 g penne", "400 g domates", "3 diş sarımsak", "1 tatlı kaşığı pul biber", "3 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz", "Yarım demet maydanoz"], steps: ["Sarımsak ve pul biberi yağda 1 dakika çevirin.", "Domatesi ekleyip 15 dakika pişirin.", "Makarnayı haşlayın.", "Sosla karıştırın.", "Maydanozla servis edin."], minutes: 25, servings: 4, prepMinutes: 5, cookMinutes: 20, difficulty: "Kolay", tips: ["Acı seviyesini pul biberle ayarlayın."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n05_206", title: "Tavuklu kremalı penne", category: "Makarnalar", ingredients: ["350 g penne", "300 g tavuk göğsü", "200 g mantar", "1 su bardağı krema", "1 diş sarımsak", "2 yemek kaşığı tereyağı", "1 çay kaşığı tuz, kekik"], steps: ["Tavuğu küp doğrayıp tereyağında pişirin.", "Mantar ve sarımsağı ekleyin.", "Kremayı ekleyip 5 dakika pişirin.", "Haşlanmış makarnayı ekleyin.", "Kekikle servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Krema yerine yarım yarım süt ve krema kullanılabilir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n05_207", title: "Ev yapımı erişte (kuru)", category: "Makarnalar", ingredients: ["4 su bardağı un", "3 yumurta", "Yarım su bardağı süt", "1 tatlı kaşığı tuz"], steps: ["Tüm malzemeyle sert bir hamur yoğurun.", "Bezelere ayırıp 20 dakika dinlendirin.", "İnce yufkalar açıp yarı kuruyana kadar bekletin.", "Şeritler hâlinde kesin.", "Tamamen kurutup kavanozda saklayın."], minutes: 60, servings: 8, prepMinutes: 60, cookMinutes: 0, difficulty: "Orta", tips: ["İyice kurumamış erişte küflenebilir."], serving: "Haşlayıp tereyağı ve cevizle.", storage: "Kuru hâli kavanozda 3 ay."),
  GeneralRecipe(id: "n05_208", title: "Cevizli erişte", category: "Makarnalar", ingredients: ["300 g erişte", "3 yemek kaşığı tereyağı", "Yarım su bardağı ceviz", "Yarım su bardağı rendelenmiş tulum veya beyaz peynir"], steps: ["Erişteyi tuzlu suda haşlayın.", "Tereyağını eritin.", "Cevizi tereyağında 1 dakika çevirin.", "Erişteyi ekleyip karıştırın.", "Peynirle servis edin."], minutes: 20, servings: 4, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", tips: ["Erişte haşlarken sık karıştırın; yapışmasın."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n05_209", title: "Mercimekli makarna (Anadolu usulü)", category: "Makarnalar", ingredients: ["250 g kısa makarna", "1 su bardağı yeşil mercimek", "1 soğan", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı pul biber, tuz"], steps: ["Mercimeği 20 dakika haşlayın.", "Makarnayı ayrı haşlayın.", "Soğanı tereyağında kızartın.", "Mercimek ve makarnayı soğanla karıştırın.", "Pul biberle servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Yoğurtla çok yakışır."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n05_210", title: "Sebzeli makarna salatası", category: "Makarnalar", ingredients: ["250 g burgu makarna", "1 salatalık", "10 çeri domates", "1 kırmızı biber", "Yarım su bardağı zeytin", "3 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı tuz, kekik"], steps: ["Makarnayı haşlayıp soğuk sudan geçirin.", "Sebzeleri küçük doğrayın.", "Zeytinyağı, limon ve baharatla sos yapın.", "Hepsini karıştırın.", "30 dakika soğutun."], minutes: 20, servings: 4, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Piknik ve beslenme çantası için idealdir."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_001", title: "Ezogelin çorbası", category: "Çorbalar", ingredients: ["1 su bardağı kırmızı mercimek", "2 yemek kaşığı pirinç", "2 yemek kaşığı ince bulgur", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "8 su bardağı sıcak su", "1 tatlı kaşığı nane, pul biber, tuz"], steps: ["Soğanı tereyağında kavurup salçayı ekleyin.", "Yıkanmış mercimek, pirinç ve bulguru ekleyin.", "Sıcak suyla 30 dakika pişirin.", "Nane ve pul biberi ekleyin.", "Limonla servis edin."], minutes: 45, servings: 6, prepMinutes: 10, cookMinutes: 35, difficulty: "Kolay", tips: ["Blenderdan geçirmeyin; taneli dokusu karakteridir."], serving: "Sıcak, limonla.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_002", title: "Tarhana çorbası", category: "Çorbalar", ingredients: ["4 yemek kaşığı tarhana", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "5 su bardağı sıcak su", "1 tatlı kaşığı nane, tuz"], steps: ["Tarhanayı 1 bardak soğuk suda 10 dakika ıslatın.", "Tereyağında salçayı kavurun.", "Tarhanayı ve kalan suyu ekleyip karıştırarak kaynatın.", "Kısık ateşte 10 dakika pişirin.", "Nane ekleyip servis edin."], minutes: 20, servings: 4, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", tips: ["Topaklanmaması için sürekli karıştırın."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_003", title: "Düğün çorbası", category: "Çorbalar", ingredients: ["300 g kemikli kuzu eti", "2 yemek kaşığı un", "1 su bardağı yoğurt", "1 yumurta sarısı", "1 limon", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı pul biber, tuz", "8 su bardağı su"], steps: ["Eti suyla 50 dakika haşlayıp didikleyin.", "Un, yoğurt, yumurta sarısı ve limonu çırpıp terbiye yapın.", "Terbiyeye sıcak et suyundan azar azar ekleyerek ılıştırın.", "Terbiyeyi tencereye ekleyip karıştırarak kaynatın, eti ekleyin.", "Pul biberli tereyağıyla servis edin."], minutes: 75, servings: 6, prepMinutes: 15, cookMinutes: 60, difficulty: "Orta", tips: ["Terbiyeyi ılıştırmak kesilmeyi önler."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_004", title: "Kekikli mantar çorbası (sütlü)", category: "Çorbalar", ingredients: ["400 g mantar", "1 soğan", "2 yemek kaşığı tereyağı", "2 yemek kaşığı un", "4 su bardağı sıcak su veya tavuk suyu", "1 su bardağı süt", "1 çay kaşığı tuz, karabiber, kekik"], steps: ["Soğan ve mantarı tereyağında suyunu çekene kadar soteleyin.", "Unu ekleyip 2 dakika kavurun.", "Suyu ekleyip 15 dakika pişirin.", "Blenderdan geçirip sütü ekleyin.", "Kekikle servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Birkaç mantar dilimini süslemek için ayırın."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_005", title: "Brokoli çorbası", category: "Çorbalar", ingredients: ["1 brokoli", "1 patates", "1 soğan", "2 yemek kaşığı zeytinyağı", "5 su bardağı su", "Yarım su bardağı süt", "1 çay kaşığı tuz"], steps: ["Soğanı yağda kavurun.", "Brokoli ve patatesi ekleyin.", "Suyla 20 dakika pişirin.", "Blenderdan geçirip sütü ekleyin.", "Sıcak servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Brokoli saplarını da kullanabilirsiniz."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_006", title: "Tavuk suyu şehriye çorbası", category: "Çorbalar", ingredients: ["5 su bardağı tavuk suyu", "Yarım su bardağı tel şehriye", "1 su bardağı didiklenmiş tavuk", "1 havuç (rendelenmiş)", "1 yemek kaşığı tereyağı", "1 çay kaşığı tuz"], steps: ["Tereyağında şehriyeyi pembeleşene kadar kavurun.", "Havucu ekleyin.", "Tavuk suyunu ekleyip 10 dakika pişirin.", "Tavuğu ekleyin.", "Limonla servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Şehriyeyi kavurmak lezzet verir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_007", title: "Patates çorbası", category: "Çorbalar", ingredients: ["4 patates", "1 soğan", "1 havuç", "2 yemek kaşığı tereyağı", "5 su bardağı su", "1 su bardağı süt", "1 çay kaşığı tuz, karabiber"], steps: ["Soğanı tereyağında kavurun.", "Patates ve havucu ekleyin.", "Suyla 20 dakika pişirin.", "Blenderdan geçirip sütü ekleyin.", "Maydanozla servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Unlu patates çorbayı kremamsı yapar."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_008", title: "Soğan çorbası (fırında peynirli)", category: "Çorbalar", ingredients: ["5 soğan", "3 yemek kaşığı tereyağı", "1 yemek kaşığı un", "5 su bardağı et suyu", "4 dilim ekmek", "1 su bardağı rendelenmiş kaşar", "1 çay kaşığı tuz, kekik"], steps: ["Soğanları ince piyazlık doğrayıp tereyağında kısık ateşte 30 dakika karamelize edin.", "Unu ekleyip 1 dakika kavurun.", "Et suyunu ekleyip 15 dakika pişirin.", "Kaselere alıp üzerine ekmek ve kaşar koyun.", "220 °C'de 5 dakika gratine edin."], minutes: 65, servings: 4, prepMinutes: 15, cookMinutes: 50, difficulty: "Orta", ovenCelsius: 220, tips: ["Soğanı aceleye getirmeyin; tatlılık zamanla gelir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_009", title: "Sütlü mısır çorbası", category: "Çorbalar", ingredients: ["2 su bardağı mısır", "1 soğan", "2 yemek kaşığı tereyağı", "1 yemek kaşığı un", "3 su bardağı su", "1 su bardağı süt", "1 çay kaşığı tuz"], steps: ["Soğanı tereyağında kavurun, unu ekleyin.", "Mısır ve suyu ekleyip 15 dakika pişirin.", "Yarısını blenderdan geçirin.", "Sütü ekleyip 2 dakika kaynatın.", "Sıcak servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Yarısını çekmek hem kıvam hem doku sağlar."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_010", title: "Lahana çorbası (Karadeniz usulü)", category: "Çorbalar", ingredients: ["Yarım karalahana demeti", "Yarım su bardağı barbunya (haşlanmış)", "2 yemek kaşığı mısır unu", "1 soğan", "2 yemek kaşığı tereyağı", "6 su bardağı su", "1 çay kaşığı tuz, pul biber"], steps: ["Karalahanayı ince doğrayın.", "Soğanı tereyağında kavurun.", "Lahana, barbunya ve suyu ekleyip 30 dakika pişirin.", "Mısır ununu suyla açıp ekleyin, 10 dakika pişirin.", "Pul biberle servis edin."], minutes: 55, servings: 4, prepMinutes: 15, cookMinutes: 40, difficulty: "Kolay", tips: ["Mısır unu çorbaya kıvam verir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_011", title: "Erişte çorbası", category: "Çorbalar", ingredients: ["1 su bardağı erişte", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "6 su bardağı sıcak su", "1 tatlı kaşığı nane, tuz"], steps: ["Soğan ve salçayı tereyağında kavurun.", "Suyu ekleyip kaynatın.", "Erişteyi ekleyip 12 dakika pişirin.", "Nane ekleyin.", "Sıcak servis edin."], minutes: 25, servings: 4, prepMinutes: 5, cookMinutes: 20, difficulty: "Kolay", tips: ["Erişte çorbayı bekledikçe koyulaştırır."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_012", title: "Toyga çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı buğday", "Yarım su bardağı haşlanmış nohut", "1 su bardağı yoğurt", "1 yumurta", "1 yemek kaşığı un", "5 su bardağı su", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı nane"], steps: ["Buğdayı 20 dakika haşlayın, nohudu ekleyin.", "Yoğurt, yumurta ve unu çırpıp ılıştırın.", "Terbiyeyi tencereye ekleyip karıştırarak kaynatın.", "5 dakika pişirin.", "Naneli tereyağıyla servis edin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Orta", tips: ["Terbiye ılıştırılmazsa kesilir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_013", title: "Havuçlu zencefilli çorba", category: "Çorbalar", ingredients: ["6 havuç", "1 soğan", "1 tatlı kaşığı rendelenmiş zencefil", "2 yemek kaşığı zeytinyağı", "5 su bardağı su", "Yarım su bardağı süt", "1 çay kaşığı tuz"], steps: ["Soğanı yağda kavurun.", "Havuç ve zencefili ekleyin.", "Suyla 20 dakika pişirin.", "Blenderdan geçirip sütü ekleyin.", "Sıcak servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Zencefil soğuk havalarda ısıtıcıdır."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_014", title: "Kremalı tavuk çorbası", category: "Çorbalar", ingredients: ["1 tavuk göğsü", "2 yemek kaşığı un", "2 yemek kaşığı tereyağı", "6 su bardağı tavuk suyu", "1 su bardağı süt", "1 limon", "1 çay kaşığı tuz, karabiber"], steps: ["Tavuğu haşlayıp didikleyin.", "Tereyağında unu kavurun.", "Tavuk suyunu çırparak ekleyin.", "Sütü ve tavuğu ekleyip 10 dakika pişirin.", "Limonla servis edin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", tips: ["Un kavurmak çorbaya kadife doku verir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_015", title: "Kırmızı biberli domates çorbası (közlü)", category: "Çorbalar", ingredients: ["4 domates", "2 köz kırmızı biber", "1 soğan", "2 yemek kaşığı zeytinyağı", "4 su bardağı su", "1 çay kaşığı tuz, kekik"], steps: ["Soğanı yağda kavurun.", "Domates ve biberi ekleyin.", "Suyla 20 dakika pişirin.", "Blenderdan geçirin.", "Kekikle servis edin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Közlü biber dumanlı bir tat katar."], serving: "Sıcak.", storage: "Buzdolabında 3 gün; ısıtırken kaynayana kadar ısıtın."),
  GeneralRecipe(id: "n06_101", title: "İç pilav", category: "Pilavlar", ingredients: ["2 su bardağı pirinç", "150 g tavuk ciğeri", "2 yemek kaşığı çam fıstığı", "2 yemek kaşığı kuş üzümü", "1 soğan", "3 yemek kaşığı tereyağı", "3 su bardağı sıcak tavuk suyu", "1 tatlı kaşığı yenibahar, tarçın, tuz, şeker"], steps: ["Pirinci ıslatıp yıkayın.", "Tereyağında fıstığı kavurun, soğanı ekleyin.", "Küçük doğranmış ciğeri ekleyip 3 dakika pişirin.", "Pirinç, üzüm ve baharatları ekleyin, suyla 15 dakika pişirin.", "Dereotu ekleyip 15 dakika demlendirin."], minutes: 50, servings: 6, prepMinutes: 20, cookMinutes: 30, difficulty: "Orta", tips: ["Ciğeri fazla pişirmeyin; sertleşir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_102", title: "Perde pilavı", category: "Pilavlar", ingredients: ["3 su bardağı pirinç", "1 tavuk (haşlanmış, didiklenmiş)", "3 yemek kaşığı badem", "Hamur: 2 su bardağı un, 1 yumurta, yarım su bardağı yoğurt, 100 g tereyağı", "4 su bardağı tavuk suyu", "1 tatlı kaşığı tuz, karabiber"], steps: ["Tavuk suyuyla pirinci yarı pişirin; tavuk, badem ve baharatla karıştırın.", "Hamur malzemelerini yoğurup açın.", "Yağlı kaba hamuru serip pilavı doldurun, kapatın.", "180 °C'de 40 dakika pişirin.", "Ters çevirip dilimleyin."], minutes: 80, servings: 8, prepMinutes: 40, cookMinutes: 40, difficulty: "Zor", ovenCelsius: 180, tips: ["Hamur pilavın buharıyla pişer, kenarlar çıtırlaşır."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_103", title: "Firik pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı firik", "1 soğan", "1 biber", "1 domates", "2 yemek kaşığı tereyağı", "3 su bardağı sıcak et suyu", "1 tatlı kaşığı tuz"], steps: ["Firiği yıkayın.", "Soğan ve biberi tereyağında kavurun.", "Domatesi ekleyin.", "Firik ve suyu ekleyip 20 dakika pişirin.", "10 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", tips: ["Firiğin is kokusu pilava karakter verir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n06_104", title: "Meyhane pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı bulgur", "1 soğan", "2 domates", "1 sivri biber", "1 yemek kaşığı biber salçası", "2 yemek kaşığı tereyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz, pul biber"], steps: ["Soğan ve biberi tereyağında kavurun.", "Salça ve domatesi ekleyip 3 dakika pişirin.", "Bulgur, su ve tuzu ekleyin.", "15 dakika pişirin.", "10 dakika demlendirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Domatesi rendelemek pilavı daha sulu yapar."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n06_105", title: "Patlıcanlı pirinç pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı pirinç", "2 patlıcan", "1 domates", "2 yemek kaşığı tereyağı", "3 yemek kaşığı zeytinyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Patlıcanları küp doğrayıp tuzlu suda bekletin, kurulayın ve zeytinyağında kızartın.", "Pirinci tereyağında kavurun.", "Domatesi ve suyu ekleyin.", "15 dakika pişirin, patlıcanları ekleyin.", "15 dakika demlendirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Patlıcanı en son eklemek dağılmasını önler."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_106", title: "Domatesli pirinç pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı pirinç", "2 domates (rendelenmiş)", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "2,5 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Pirinci yıkayın.", "Tereyağında salça ve domatesi pişirin.", "Pirinci ekleyip kavurun.", "Su ve tuzla 15 dakika pişirin.", "Demlendirin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Domates pilava hafif ekşilik katar."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_107", title: "Sebzeli esmer pirinç pilavı", category: "Pilavlar", ingredients: ["1,5 su bardağı esmer pirinç", "1 havuç", "1 su bardağı bezelye", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Esmer pirinci 1 saat ıslatın.", "Sebzeleri yağda 4 dakika soteleyin.", "Pirinci ekleyip kavurun.", "Su ve tuzla 35 dakika pişirin.", "10 dakika demlendirin."], minutes: 50, servings: 4, prepMinutes: 10, cookMinutes: 40, difficulty: "Kolay", tips: ["Esmer pirinç lif açısından zengindir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n06_108", title: "Kestaneli pilav", category: "Pilavlar", ingredients: ["2 su bardağı pirinç", "200 g haşlanmış kestane", "3 yemek kaşığı tereyağı", "3 su bardağı sıcak tavuk suyu", "1 tatlı kaşığı tuz, tarçın"], steps: ["Pirinci yıkayın.", "Tereyağında pirinci kavurun.", "Su ve tuzla 15 dakika pişirin.", "İri kıyılmış kestaneleri ekleyin.", "Tarçınla 15 dakika demlendirin."], minutes: 40, servings: 6, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Hindi veya tavukla yakışır."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_109", title: "Bulgurlu mercimekli kuskus pilavı", category: "Pilavlar", ingredients: ["1 su bardağı bulgur", "Yarım su bardağı kuskus", "Yarım su bardağı yeşil mercimek", "1 soğan", "2 yemek kaşığı tereyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Mercimeği 15 dakika ön haşlayın.", "Soğanı tereyağında kavurun.", "Bulgur ve kuskusu ekleyip kavurun.", "Mercimek, su ve tuzla 12 dakika pişirin.", "Demlendirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Kuskus pilava farklı doku katar."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n06_110", title: "Kuruyemişli safranlı pilav", category: "Pilavlar", ingredients: ["2 su bardağı basmati pirinç", "2 yemek kaşığı badem", "2 yemek kaşığı kuru üzüm", "1 tutam safran veya 1 çay kaşığı zerdeçal", "3 yemek kaşığı tereyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Safranı sıcak suda bekletin.", "Bademi tereyağında kavurun.", "Pirinci ekleyip 2 dakika çevirin.", "Safranlı su, üzüm ve tuzla 15 dakika pişirin.", "10 dakika demlendirin."], minutes: 35, servings: 6, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Safran yerine zerdeçal ekonomik alternatiftir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_111", title: "Kabaklı bulgur pilavı (taneli)", category: "Pilavlar", ingredients: ["1,5 su bardağı bulgur", "2 kabak", "1 soğan", "1 yemek kaşığı biber salçası", "2 yemek kaşığı zeytinyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz, nane"], steps: ["Soğanı kavurup salçayı ekleyin.", "Küp kabağı ekleyip 3 dakika çevirin.", "Bulgur ve suyu ekleyin.", "15 dakika pişirin.", "Nane ile demlendirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Kabağı iri doğrayın; dağılmasın."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n06_112", title: "Sade tereyağlı pirinç pilavı", category: "Pilavlar", ingredients: ["2 su bardağı baldo pirinç", "3 yemek kaşığı tereyağı", "3 su bardağı sıcak tavuk suyu veya su", "1 tatlı kaşığı tuz"], steps: ["Pirinci sıcak tuzlu suda 20 dakika bekletin, nişastası gidene kadar yıkayın.", "Tereyağında pirinci 5 dakika şeffaflaşana kadar kavurun.", "Sıcak suyu ve tuzu ekleyin.", "Kısık ateşte suyunu çekene kadar 15 dakika pişirin.", "Kâğıt havluyla 20 dakika demlendirin."], minutes: 45, servings: 4, prepMinutes: 25, cookMinutes: 20, difficulty: "Kolay", tips: ["Su pirincin 1,5 katı olmalı."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_201", title: "Türlü", category: "Sebze yemekleri", ingredients: ["1 patlıcan", "2 kabak", "2 patates", "200 g taze fasulye", "2 biber", "2 domates", "1 soğan", "1 yemek kaşığı salça", "4 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Tüm sebzeleri iri küp doğrayın.", "Soğanı kavurup salçayı ekleyin.", "Sert sebzeleri (patates, fasulye) önce ekleyin.", "Diğer sebzeleri ve 1 bardak suyu ilave edin.", "Kısık ateşte 45 dakika pişirin."], minutes: 75, servings: 6, prepMinutes: 25, cookMinutes: 50, difficulty: "Kolay", tips: ["Fırında güveçte de pişirilebilir."], serving: "Pilav ve yoğurtla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n06_202", title: "Ispanak yemeği (yumurtalı)", category: "Sebze yemekleri", ingredients: ["1 kg ıspanak", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı pirinç", "3 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz", "2 yumurta"], steps: ["Soğanı kavurup salçayı ekleyin.", "Doğranmış ıspanağı ve pirinci ekleyin.", "15 dakika pişirin.", "Yumurtaları kırıp kapağı kapatın.", "5 dakika pişirin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Ispanak suyunu bırakır; su eklemeyin."], serving: "Yoğurtla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_203", title: "Havuçlu zeytinyağlı kereviz", category: "Sebze yemekleri", ingredients: ["2 kereviz kökü", "2 havuç", "1 patates", "1 soğan", "5 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı şeker, tuz"], steps: ["Kerevizleri küp doğrayıp limonlu suda bekletin.", "Soğanı yağda kavurun.", "Havuç, patates ve kerevizi ekleyin.", "1,5 bardak su, limon, şeker ve tuzla 30 dakika pişirin.", "Dereotuyla soğutun."], minutes: 50, servings: 4, prepMinutes: 15, cookMinutes: 35, difficulty: "Kolay", tips: ["Limonlu su kerevizin rengini korur."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n06_204", title: "Fırında karnabahar mücver", category: "Sebze yemekleri", ingredients: ["Yarım karnabahar (haşlanmış)", "2 yumurta", "4 yemek kaşığı un", "100 g beyaz peynir", "Yarım demet dereotu", "1 çay kaşığı tuz"], steps: ["Fırını 200 °C'ye ısıtın.", "Karnabaharı ezin.", "Diğer malzemeleri ekleyip karıştırın.", "Kaşıkla tepsiye yassı yuvarlaklar bırakın.", "25 dakika pişirin."], minutes: 40, servings: 4, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Karnabaharın suyunu iyice süzün."], serving: "Yoğurtla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_205", title: "Kabak sinkonta (Bodrum usulü)", category: "Sebze yemekleri", ingredients: ["4 kabak", "1 soğan", "2 domates", "4 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz", "Yarım demet dereotu"], steps: ["Kabakları kabuklarını soymadan iri doğrayın.", "Soğanı yağda kavurun.", "Kabak ve rendelenmiş domatesi ekleyin.", "Kapağı kapalı 25 dakika pişirin.", "Dereotuyla soğutun."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Kabak kendi suyunda pişer; su eklemeyin."], serving: "Ilık veya soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n06_206", title: "Kıymasız patlıcan oturtma", category: "Sebze yemekleri", ingredients: ["4 patlıcan", "2 domates", "2 biber", "1 soğan", "3 diş sarımsak", "4 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Patlıcanları halka kesip fırında kızartın.", "Soğan, sarımsak, biber ve domatesle sos yapın.", "Patlıcanları kaba dizip sosu üzerine dökün.", "180 °C'de 25 dakika pişirin.", "Yoğurtla servis edin."], minutes: 55, servings: 4, prepMinutes: 20, cookMinutes: 35, difficulty: "Kolay", ovenCelsius: 180, tips: ["Vejetaryen bir ana yemektir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_207", title: "Biberli mantar sote", category: "Sebze yemekleri", ingredients: ["500 g mantar", "1 soğan", "2 sivri biber", "2 yemek kaşığı tereyağı", "1 çay kaşığı tuz, kekik, karabiber"], steps: ["Mantarları dilimleyin.", "Tereyağında soğan ve biberi kavurun.", "Mantarları ekleyip yüksek ateşte suyunu çekene kadar pişirin.", "Baharatları ekleyin.", "Sıcak servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Tuzu en son ekleyin; mantar su salmaz."], serving: "Pilavla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_208", title: "Fırında sebze graten", category: "Sebze yemekleri", ingredients: ["1 brokoli", "Yarım karnabahar", "2 havuç", "Beşamel: 2 yemek kaşığı tereyağı, 2 yemek kaşığı un, 2 su bardağı süt", "1 su bardağı rendelenmiş kaşar", "1 çay kaşığı tuz, muskat"], steps: ["Sebzeleri 5 dakika haşlayın.", "Beşamel sos yapın.", "Sebzeleri fırın kabına dizip sosu dökün.", "Kaşar serpin.", "200 °C'de 25 dakika pişirin."], minutes: 55, servings: 6, prepMinutes: 20, cookMinutes: 35, difficulty: "Kolay", ovenCelsius: 200, tips: ["Sebzeleri fazla haşlamayın."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_209", title: "Zeytinyağlı limonlu bamya", category: "Sebze yemekleri", ingredients: ["500 g bamya", "2 domates", "1 soğan", "5 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı tuz, şeker"], steps: ["Bamyaların başlarını yontup limonlu suda 30 dakika bekletin.", "Soğanı yağda kavurun.", "Domates ve bamyaları ekleyin.", "1 bardak su, limon, tuz ve şekerle 30 dakika pişirin.", "Soğutun."], minutes: 55, servings: 4, prepMinutes: 20, cookMinutes: 35, difficulty: "Kolay", tips: ["Az karıştırın; bamya salyalanmasın."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n06_210", title: "Zeytinyağlı pırasa (havuçlu pirinçli)", category: "Sebze yemekleri", ingredients: ["4 pırasa", "2 havuç", "2 yemek kaşığı pirinç", "5 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı şeker, tuz"], steps: ["Pırasayı 2 cm halka, havucu dilim doğrayın.", "Yağda 5 dakika soteleyin.", "Pirinç, limon, şeker, tuz ve 1 bardak su ekleyin.", "25 dakika pişirin.", "Soğutun."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Pırasanın arasını iyice yıkayın."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n06_211", title: "Fırında kabak dolması (kıymasız)", category: "Sebze yemekleri", ingredients: ["6 kabak", "1 su bardağı pirinç", "1 soğan", "2 domates", "4 yemek kaşığı zeytinyağı", "1 tatlı kaşığı nane, tuz"], steps: ["Kabakların içini oyun.", "Soğan, pirinç, domates ve baharatla harç yapın.", "Kabakları doldurun.", "Fırın kabına dizip 1 bardak su ekleyin.", "190 °C'de 40 dakika pişirin."], minutes: 65, servings: 4, prepMinutes: 25, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 190, tips: ["Oyduğunuz kabak içini harca katabilirsiniz."], serving: "Yoğurtla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_212", title: "Közlenmiş patlıcanlı biber kavurma", category: "Sebze yemekleri", ingredients: ["3 patlıcan", "4 sivri biber", "2 domates", "3 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Patlıcanları közleyip soyun, iri doğrayın.", "Biberleri yağda kavurun.", "Sarımsak ve domatesi ekleyin.", "Patlıcanı ekleyip 5 dakika pişirin.", "Sıcak veya ılık servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Köz patlıcan yemeğe dumanlı tat verir."], serving: "Ekmekle.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n06_213", title: "Kereviz sapı soteli havuç", category: "Sebze yemekleri", ingredients: ["4 kereviz sapı", "3 havuç", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı bal", "1 limon", "1 çay kaşığı tuz"], steps: ["Kereviz saplarını ve havucu çubuk doğrayın.", "Yağda 8 dakika soteleyin.", "Bal ve limonu ekleyin.", "2 dakika çevirin.", "Garnitür olarak servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Sebzeler diri kalmalı."], serving: "Sıcak, garnitür.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n07_001", title: "Bol limonlu çoban salatası", category: "Salatalar", ingredients: ["3 domates", "2 salatalık", "2 sivri biber", "1 kuru soğan", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı tuz"], steps: ["Domates ve salatalığı küçük küp doğrayın.", "Biber ve soğanı ince kıyın.", "Maydanozu ekleyin.", "Zeytinyağı, limon ve tuzla harmanlayın.", "Hemen servis edin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Soğanı tuzla ovmak acısını alır."], serving: "Soğuk.", storage: "Sossuz hâli buzdolabında 1 gün."),
  GeneralRecipe(id: "n07_002", title: "Gavurdağı salatası", category: "Salatalar", ingredients: ["3 domates", "1 salatalık", "1 kırmızı soğan", "Yarım su bardağı ceviz", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "2 yemek kaşığı nar ekşisi", "1 tatlı kaşığı sumak, pul biber, tuz"], steps: ["Sebzeleri çok küçük doğrayın.", "Cevizi iri kıyın.", "Nar ekşisi, yağ ve baharatla sos yapın.", "Hepsini karıştırın.", "Hemen servis edin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Domatesin çekirdeklerini çıkarmak salatayı sulandırmaz."], serving: "Soğuk, kebapla.", storage: "Sossuz hâli buzdolabında 1 gün."),
  GeneralRecipe(id: "n07_003", title: "Mevsim salatası (yeşil)", category: "Salatalar", ingredients: ["1 marul", "1 demet roka", "1 havuç", "1 salatalık", "6 turp", "3 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı tuz"], steps: ["Yeşillikleri yıkayıp kurulayın.", "Doğrayın.", "Havucu rendeleyin, turpu ve salatalığı dilimleyin.", "Sosla harmanlayın.", "Servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Yeşillikler kuru olmalı; sos tutar."], serving: "Soğuk.", storage: "Sossuz hâli buzdolabında 1 gün."),
  GeneralRecipe(id: "n07_004", title: "Patates salatası (yoğurtlu)", category: "Salatalar", ingredients: ["5 patates", "1 su bardağı yoğurt", "2 dal taze soğan", "Yarım demet dereotu", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Patatesleri haşlayıp küp doğrayın.", "Yoğurdu yağ ve tuzla çırpın.", "Taze soğan ve dereotunu kıyın.", "Hepsini karıştırın.", "Soğuk servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Patatesler soğuyunca yoğurtla karıştırın."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n07_005", title: "Rus salatası (yoğurtlu, hafif)", category: "Salatalar", ingredients: ["3 patates", "2 havuç", "1 su bardağı bezelye", "3 turşu salatalık", "1 su bardağı yoğurt", "3 yemek kaşığı mayonez", "1 çay kaşığı tuz"], steps: ["Patates ve havucu küp doğrayıp haşlayın.", "Bezelyeyi 3 dakika haşlayın.", "Turşuları küçük doğrayın.", "Yoğurt ve mayonezle karıştırın.", "Soğutup servis edin."], minutes: 35, servings: 6, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Yoğurt eklemek salatayı hafifletir."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n07_006", title: "Ton balıklı fasulye salatası", category: "Salatalar", ingredients: ["1 kutu ton balığı", "2 su bardağı haşlanmış beyaz fasulye", "1 kırmızı soğan", "10 çeri domates", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "1 limon"], steps: ["Ton balığını süzün.", "Soğanı ince doğrayın.", "Domatesleri ikiye kesin.", "Hepsini karıştırın.", "Sosla servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Protein açısından zengin bir öğün salatasıdır."], serving: "Soğuk.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n07_007", title: "Kısır (bol yeşillikli)", category: "Salatalar", ingredients: ["2 su bardağı ince bulgur", "1,5 su bardağı sıcak su", "2 yemek kaşığı domates salçası", "1 yemek kaşığı biber salçası", "4 dal taze soğan", "1 demet maydanoz", "Yarım demet nane", "4 yemek kaşığı zeytinyağı", "3 yemek kaşığı nar ekşisi", "1 tatlı kaşığı tuz, pul biber"], steps: ["Bulguru sıcak suyla 20 dakika şişirin.", "Salçaları ekleyip yoğurun.", "Zeytinyağı, nar ekşisi ve baharatı ekleyin.", "Yeşillikleri ince kıyıp ekleyin.", "Marul yaprağıyla servis edin."], minutes: 20, servings: 6, prepMinutes: 20, cookMinutes: 0, difficulty: "Kolay", tips: ["Yeşillikleri en son ekleyin."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n07_008", title: "Narlı peynirli roka salatası", category: "Salatalar", ingredients: ["2 demet roka", "1 nar", "Yarım su bardağı ceviz", "50 g beyaz peynir", "3 yemek kaşığı zeytinyağı", "1 yemek kaşığı nar ekşisi"], steps: ["Rokayı yıkayıp kurulayın.", "Narı taneleyin.", "Peyniri ufalayın.", "Hepsini birleştirin.", "Sosla servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Nar ekşisi rokayla çok uyumludur."], serving: "Soğuk.", storage: "Sossuz hâli buzdolabında 1 gün."),
  GeneralRecipe(id: "n07_009", title: "Fırınlanmış balkabağı salatası", category: "Salatalar", ingredients: ["500 g balkabağı", "1 demet roka", "50 g keçi peyniri", "3 yemek kaşığı kabak çekirdeği", "3 yemek kaşığı zeytinyağı", "1 yemek kaşığı bal", "1 çay kaşığı tuz"], steps: ["Balkabağını küp doğrayıp yağ ve tuzla 200 °C'de 25 dakika fırınlayın.", "Soğutun.", "Rokayı tabağa yayın.", "Kabak, peynir ve çekirdeği ekleyin.", "Bal ve yağla sos yapıp gezdirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Sonbahar salatası olarak idealdir."], serving: "Ilık.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n07_010", title: "Tavuklu yeşil salata", category: "Salatalar", ingredients: ["300 g tavuk göğsü", "1 marul", "1 salatalık", "10 çeri domates", "1 avokado", "3 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı tuz, kekik"], steps: ["Tavuğu baharatlayıp ızgarada pişirin, dilimleyin.", "Yeşillikleri doğrayın.", "Sebzeleri ekleyin.", "Sosla harmanlayın.", "Tavukla servis edin."], minutes: 27, servings: 4, prepMinutes: 15, cookMinutes: 12, difficulty: "Kolay", tips: ["Doyurucu bir öğle yemeğidir."], serving: "Soğuk.", storage: "Sossuz 1 gün."),
  GeneralRecipe(id: "n07_011", title: "Piyaz (Antalya usulü tahinli)", category: "Salatalar", ingredients: ["2 su bardağı haşlanmış kuru fasulye", "1 kırmızı soğan", "1 domates", "2 haşlanmış yumurta", "3 yemek kaşığı tahin", "1 limon", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz, sumak"], steps: ["Tahini limon, yağ ve biraz suyla açıp sos yapın.", "Fasulyeyi sosla karıştırın.", "Sumaklı soğan ekleyin.", "Domates ve yumurtayla süsleyin.", "Servis edin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Antalya piyazının sırrı tahinli sostur."], serving: "Soğuk, köfteyle.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n07_012", title: "Kırmızı lahana turşulu salata", category: "Salatalar", ingredients: ["Yarım kırmızı lahana", "1 havuç", "2 yemek kaşığı elma sirkesi", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı şeker, tuz"], steps: ["Lahanayı ince doğrayın.", "Tuz ve şekerle ovun.", "Havucu rendeleyin.", "Sirke ve yağla harmanlayın.", "30 dakika dinlendirin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Dinlenince lahana yumuşar."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n07_101", title: "Ev yufkasından peynirli kol böreği", category: "Hamur işleri", ingredients: ["3 yufka", "250 g beyaz peynir", "1 demet maydanoz", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "1 yumurta"], steps: ["Peyniri maydanozla karıştırın.", "Süt ve yağı karıştırın.", "Yufkaları ikiye kesip sosla ıslatın, harcı koyup rulo yapın.", "Tepsiye dizip yumurta sürün.", "190 °C'de 35 dakika pişirin."], minutes: 60, servings: 6, prepMinutes: 25, cookMinutes: 35, difficulty: "Kolay", ovenCelsius: 190, tips: ["Rulo sıkı sarılmalı."], serving: "Ilık.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n07_102", title: "Milföy peynirli börek", category: "Hamur işleri", ingredients: ["8 kare milföy", "200 g beyaz peynir", "Yarım demet maydanoz", "1 yumurta", "1 yemek kaşığı susam"], steps: ["Milföyleri çözdürün.", "Peynir ve maydanozu karıştırın.", "Milföylere harç koyup üçgen katlayın, kenarlarını çatalla bastırın.", "Yumurta sarısı ve susam sürün.", "200 °C'de 25 dakika pişirin."], minutes: 40, servings: 8, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Milföy soğuk olmalı; kat kat kabarır."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n07_103", title: "Talaş böreği (kıymalı)", category: "Hamur işleri", ingredients: ["8 kare milföy", "250 g kıyma", "1 soğan", "1 havuç", "1 su bardağı bezelye", "1 yumurta", "1 çay kaşığı tuz, karabiber"], steps: ["Kıymayı soğan, havuç ve bezelyeyle kavurup soğutun.", "Milföyleri açın.", "Harcı koyup kare paket yapın.", "Yumurta sarısı sürün.", "200 °C'de 25 dakika pişirin."], minutes: 50, servings: 8, prepMinutes: 25, cookMinutes: 25, difficulty: "Orta", ovenCelsius: 200, tips: ["Harç tamamen soğuk olmalı."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n07_104", title: "Ispanaklı gözleme", category: "Hamur işleri", ingredients: ["2 su bardağı un", "1 su bardağı su", "1 çay kaşığı tuz", "300 g ıspanak", "1 soğan", "100 g lor", "2 yemek kaşığı tereyağı"], steps: ["Hamuru yoğurup dinlendirin.", "Ispanak ve soğanı soteleyip lorla karıştırın.", "Hamuru ince açın.", "Harcı koyup kapatın.", "Tavada pişirip tereyağı sürün."], minutes: 50, servings: 4, prepMinutes: 30, cookMinutes: 20, difficulty: "Kolay", tips: ["Ispanağın suyunu iyice uçurun."], serving: "Ayranla.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n07_105", title: "Kıymalı gözleme", category: "Hamur işleri", ingredients: ["2 su bardağı un", "1 su bardağı su", "1 çay kaşığı tuz", "250 g kıyma", "1 soğan", "1 çay kaşığı pul biber, tuz", "2 yemek kaşığı tereyağı"], steps: ["Hamuru yoğurup dinlendirin.", "Kıymayı soğanla kavurun.", "Hamuru ince açın.", "Harcı yayıp katlayın.", "Tavada her yüzü 3 dakika pişirin."], minutes: 50, servings: 4, prepMinutes: 30, cookMinutes: 20, difficulty: "Kolay", tips: ["Kıymalı harç fazla yağlı olmamalı."], serving: "Ayranla.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n07_106", title: "Pizza poğaça", category: "Hamur işleri", ingredients: ["1 su bardağı yoğurt", "Yarım su bardağı sıvı yağ", "1 paket kabartma tozu", "Yaklaşık 3,5 su bardağı un", "1 su bardağı rendelenmiş kaşar", "8 dilim sucuk veya salam", "Yarım su bardağı zeytin", "1 yumurta"], steps: ["Yoğurt, yağ, kabartma tozu ve unla hamur yapın.", "Kaşar, küçük doğranmış sucuk ve zeytinle iç hazırlayın.", "Hamurdan parçalar alıp açın, iç koyup kapatın.", "Yumurta sarısı sürün.", "180 °C'de 25 dakika pişirin."], minutes: 45, servings: 12, prepMinutes: 20, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 180, tips: ["Çocukların beslenme çantası için uygundur."], serving: "Ilık.", storage: "Kapalı kapta 2 gün."),
  GeneralRecipe(id: "n07_107", title: "Patatesli puf börek", category: "Hamur işleri", ingredients: ["Hamur: 1 su bardağı yoğurt, 1 yumurta, 1 paket kabartma tozu, 3 su bardağı un, 1 çay kaşığı tuz", "3 haşlanmış patates", "1 soğan", "1 çay kaşığı pul biber", "Kızartmak için 2 su bardağı sıvı yağ"], steps: ["Hamuru yoğurun.", "Patatesi kavrulmuş soğanla karıştırın.", "Hamuru açıp bardakla yuvarlaklar kesin.", "Harç koyup yarım ay şeklinde kapatın.", "Kızgın yağda kızartın."], minutes: 35, servings: 12, prepMinutes: 20, cookMinutes: 15, difficulty: "Kolay", tips: ["Kenarları çatalla bastırmak açılmayı önler."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n07_108", title: "Ev yapımı tost ekmeği", category: "Hamur işleri", ingredients: ["4 su bardağı un", "1 paket instant maya", "1 yemek kaşığı şeker", "1 tatlı kaşığı tuz", "1 su bardağı ılık süt", "Yarım su bardağı ılık su", "3 yemek kaşığı tereyağı"], steps: ["Tüm malzemeyle yumuşak hamur yoğurup 1 saat mayalandırın.", "Hamuru baton şeklinde rulo yapıp kalıba koyun.", "45 dakika daha mayalandırın.", "180 °C'de 35 dakika pişirin.", "Tel ızgarada soğutup dilimleyin."], minutes: 155, servings: 1, prepMinutes: 120, cookMinutes: 35, difficulty: "Orta", ovenCelsius: 180, tips: ["Soğumadan kesilirse içi hamur görünür."], serving: "Kahvaltıda.", storage: "Kapalı poşette 3 gün."),
  GeneralRecipe(id: "n07_109", title: "Su böreği (klasik, ev açması)", category: "Hamur işleri", ingredients: ["5 su bardağı un", "5 yumurta", "1 çay kaşığı tuz", "400 g beyaz peynir", "1 demet maydanoz", "200 g tereyağı"], steps: ["Un, yumurta ve tuzla sert hamur yoğurup 12 bezeye ayırın.", "Bezeleri tepsi büyüklüğünde açıp kaynar tuzlu suda 1 dakika haşlayın, soğuk suya alın.", "Tepsiye ilk iki yaprağı haşlamadan, diğerlerini haşlanmış olarak tereyağı sürerek dizin; ortaya peynir yayın.", "Kalan yaprakları aynı şekilde dizin.", "200 °C'de 40 dakika pişirin."], minutes: 130, servings: 10, prepMinutes: 90, cookMinutes: 40, difficulty: "Zor", ovenCelsius: 200, tips: ["Yaprakları haşlarken kırışık bırakmak katlara hacim verir."], serving: "Ilık.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n07_110", title: "Kaşarlı mısır poğaçası", category: "Hamur işleri", ingredients: ["1 su bardağı mısır unu", "1,5 su bardağı un", "1 su bardağı yoğurt", "Yarım su bardağı sıvı yağ", "1 paket kabartma tozu", "1 su bardağı rendelenmiş kaşar", "1 yumurta"], steps: ["Tüm malzemeyi yoğurun.", "Ceviz büyüklüğünde parçalar alıp ortasına kaşar koyun.", "Tepsiye dizin.", "Yumurta sarısı sürün.", "180 °C'de 25 dakika pişirin."], minutes: 40, servings: 10, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 180, tips: ["Mısır unu poğaçaya çıtırlık verir."], serving: "Ilık.", storage: "Kapalı kapta 2 gün."),
  GeneralRecipe(id: "n07_201", title: "Elmalı kurabiye (pudra şekerli)", category: "Kek ve kurabiyeler", ingredients: ["125 g margarin veya tereyağı", "Yarım su bardağı sıvı yağ", "Yarım su bardağı yoğurt", "1 paket kabartma tozu", "Yaklaşık 3,5 su bardağı un", "İç: 3 elma, 3 yemek kaşığı şeker, 1 tatlı kaşığı tarçın"], steps: ["Elmaları rendeleyip şeker ve tarçınla suyunu çekene kadar pişirin.", "Hamuru yoğurun.", "Bezeler alıp açın, harç koyup rulo yapın.", "180 °C'de 25 dakika pişirin.", "Soğuyunca pudra şekerine bulayın."], minutes: 45, servings: 20, prepMinutes: 20, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 180, tips: ["Sıcakken pudra şekerine bulamayın; erir."], serving: "Çayla.", storage: "Kapalı kapta 4 gün."),
  GeneralRecipe(id: "n07_202", title: "Cevizli tereyağlı kurabiye", category: "Kek ve kurabiyeler", ingredients: ["125 g tereyağı", "Yarım su bardağı pudra şekeri", "1 yumurta", "2,5 su bardağı un", "1 su bardağı kıyılmış ceviz", "1 paket vanilin"], steps: ["Tereyağı ve şekeri çırpın, yumurtayı ekleyin.", "Un, vanilin ve cevizi ekleyin.", "Yuvarlak şekiller verip tepsiye dizin.", "180 °C'de 15 dakika pişirin.", "Soğutun."], minutes: 30, servings: 20, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 180, tips: ["Cevizi kavurmak aromayı artırır."], serving: "Çayla.", storage: "Kapalı kapta 1 hafta."),
  GeneralRecipe(id: "n07_203", title: "Yoğurtlu kek (klasik)", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "1 su bardağı yoğurt", "Yarım su bardağı sıvı yağ", "2,5 su bardağı un", "1 paket kabartma tozu", "1 paket vanilin"], steps: ["Fırını 175 °C'ye ısıtın.", "Yumurta ve şekeri köpürtün.", "Yoğurt ve yağı ekleyin.", "Un, kabartma tozu ve vanilini ekleyin.", "Kalıpta 40 dakika pişirin."], minutes: 55, servings: 10, prepMinutes: 15, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 175, tips: ["Yoğurt keki ertesi gün de yumuşak tutar."], serving: "Çayla.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n07_204", title: "Brownie", category: "Kek ve kurabiyeler", ingredients: ["200 g bitter çikolata", "125 g tereyağı", "1 su bardağı şeker", "3 yumurta", "Yarım su bardağı un", "2 yemek kaşığı kakao", "Yarım su bardağı ceviz"], steps: ["Çikolata ve tereyağını benmari usulü eritin.", "Şeker ve yumurtaları ekleyip karıştırın.", "Un, kakao ve cevizi ekleyin.", "Kare kalıba dökün.", "180 °C'de 25 dakika pişirin; ortası hafif nemli kalmalı."], minutes: 40, servings: 12, prepMinutes: 15, cookMinutes: 25, difficulty: "Orta", ovenCelsius: 180, tips: ["Fazla pişirmeyin; brownie kurur."], serving: "Dondurmayla.", storage: "Kapalı kapta 4 gün."),
  GeneralRecipe(id: "n07_205", title: "Kakaolu fındıklı kurabiye", category: "Kek ve kurabiyeler", ingredients: ["125 g tereyağı", "Yarım su bardağı şeker", "1 yumurta", "2 su bardağı un", "3 yemek kaşığı kakao", "Yarım su bardağı fındık", "1 çay kaşığı kabartma tozu"], steps: ["Tereyağı ve şekeri çırpın.", "Yumurtayı ekleyin.", "Kuru malzemeleri ve fındığı ekleyin.", "Yuvarlayıp bastırın.", "180 °C'de 12 dakika pişirin."], minutes: 27, servings: 20, prepMinutes: 15, cookMinutes: 12, difficulty: "Kolay", ovenCelsius: 180, tips: ["Fındığı kavurmak lezzeti artırır."], serving: "Sütle.", storage: "Kapalı kapta 5 gün."),
  GeneralRecipe(id: "n07_206", title: "Havuçlu tarçınlı muffin (yoğurtlu)", category: "Kek ve kurabiyeler", ingredients: ["2 yumurta", "Yarım su bardağı şeker", "Yarım su bardağı yoğurt", "Yarım su bardağı sıvı yağ", "1,5 su bardağı rendelenmiş havuç", "2 su bardağı un", "1 paket kabartma tozu", "1 tatlı kaşığı tarçın"], steps: ["Fırını 180 °C'ye ısıtın.", "Yumurta, şeker, yoğurt ve yağı çırpın.", "Havucu ekleyin.", "Kuru malzemeleri katın.", "Kalıplarda 22 dakika pişirin."], minutes: 37, servings: 12, prepMinutes: 15, cookMinutes: 22, difficulty: "Kolay", ovenCelsius: 180, tips: ["Havuç muffini nemli tutar."], serving: "Çayla.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n07_207", title: "Limonlu kurabiye (pudralı)", category: "Kek ve kurabiyeler", ingredients: ["125 g tereyağı", "Yarım su bardağı pudra şekeri", "1 limonun kabuğu", "1 yumurta", "2,5 su bardağı un", "Yarım çay kaşığı kabartma tozu"], steps: ["Tereyağı ve pudra şekerini çırpın.", "Limon kabuğu ve yumurtayı ekleyin.", "Un ve kabartma tozunu ekleyin.", "Şekil verip dizin.", "170 °C'de 15 dakika pişirin."], minutes: 30, servings: 20, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 170, tips: ["Limon kabuğunun beyaz kısmını rendelemeyin; acıdır."], serving: "Çayla.", storage: "Kapalı kapta 1 hafta."),
  GeneralRecipe(id: "n07_208", title: "Portakallı ıslak kek", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "1 su bardağı portakal suyu", "Yarım su bardağı sıvı yağ", "2 su bardağı un", "1 paket kabartma tozu", "Şurup: 1 su bardağı portakal suyu, yarım su bardağı şeker"], steps: ["Kek hamurunu karıştırın.", "180 °C'de 30 dakika pişirin.", "Şurubu 5 dakika kaynatın.", "Sıcak keke ılık şurubu dökün.", "Soğutup dilimleyin."], minutes: 45, servings: 12, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 180, tips: ["Kekin her yerine çatalla delik açmak şurubu eşit dağıtır."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n07_301", title: "Pratik peynirli pide (lavaştan)", category: "Pratik tarifler", ingredients: ["2 lavaş", "1 su bardağı rendelenmiş kaşar", "100 g beyaz peynir", "1 yumurta", "Yarım demet maydanoz"], steps: ["Lavaşı katlayıp kayık şekli verin.", "Peynir, yumurta ve maydanozu karıştırıp ortaya yayın.", "Kenarları kıvırın.", "200 °C'de 10 dakika pişirin.", "Dilimleyin."], minutes: 15, servings: 2, prepMinutes: 5, cookMinutes: 10, difficulty: "Kolay", ovenCelsius: 200, tips: ["Hamursuz pratik pide alternatifidir."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n07_302", title: "Fırında fincan kek", category: "Pratik tarifler", ingredients: ["4 yemek kaşığı un", "3 yemek kaşığı şeker", "2 yemek kaşığı kakao", "1 yumurta", "3 yemek kaşığı süt", "2 yemek kaşığı sıvı yağ", "Yarım çay kaşığı kabartma tozu"], steps: ["Fırını 180 °C'ye ısıtın.", "Tüm malzemeyi fincanda karıştırın.", "İkiye paylaştırın.", "15 dakika pişirin.", "Ilık servis edin."], minutes: 20, servings: 2, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 180, tips: ["Fırına dayanıklı fincan kullanın."], serving: "Ilık.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n07_303", title: "Tavada yumurtalı patates köftesi", category: "Pratik tarifler", ingredients: ["3 haşlanmış patates", "1 yumurta", "2 yemek kaşığı un", "Yarım demet maydanoz", "1 çay kaşığı tuz, pul biber", "3 yemek kaşığı sıvı yağ"], steps: ["Patatesleri ezin.", "Yumurta, un, maydanoz ve baharatla yoğurun.", "Köfte şekli verin.", "Tavada her yüzü 3 dakika kızartın.", "Yoğurtla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Patatesler soğuk olmalı."], serving: "Sıcak.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n07_304", title: "10 dakikada makarna (domatesli)", category: "Pratik tarifler", ingredients: ["200 g makarna", "1 domates", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz, kekik", "3 yemek kaşığı rendelenmiş peynir"], steps: ["Makarnayı haşlayın.", "Sarımsağı yağda çevirin.", "Rendelenmiş domatesi ekleyip 5 dakika pişirin.", "Makarnayla karıştırın.", "Peynirle servis edin."], minutes: 12, servings: 2, prepMinutes: 2, cookMinutes: 10, difficulty: "Kolay", tips: ["Haşlama süresinde sos hazır olur."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n07_305", title: "Peynirli omlet sandviç", category: "Pratik tarifler", ingredients: ["2 dilim ekmek", "2 yumurta", "2 dilim kaşar", "1 tatlı kaşığı tereyağı", "1 tutam tuz"], steps: ["Yumurtaları çırpın.", "Tavada ince omlet yapın.", "Ekmeğin büyüklüğünde katlayın.", "Kaşarla ekmek arasına koyun.", "Tavada her yüzü 1 dakika ısıtın."], minutes: 10, servings: 1, prepMinutes: 5, cookMinutes: 5, difficulty: "Kolay", tips: ["Yolda yemek için pratik."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n07_306", title: "Hazır yufkadan elmalı rulo tatlı", category: "Pratik tarifler", ingredients: ["2 yufka", "3 elma (rendelenmiş)", "3 yemek kaşığı şeker", "1 tatlı kaşığı tarçın", "3 yemek kaşığı tereyağı (eritilmiş)"], steps: ["Elmayı şeker ve tarçınla 5 dakika pişirin.", "Yufkaya tereyağı sürün.", "Elmayı yayıp rulo yapın.", "Dilimleyip tepsiye dizin.", "190 °C'de 25 dakika pişirin."], minutes: 35, servings: 6, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 190, tips: ["Pratik bir strudel alternatifidir."], serving: "Ilık.", storage: "Kapalı kapta 2 gün."),
  GeneralRecipe(id: "n07_307", title: "Fırında sebzeli yumurta (tek tava)", category: "Pratik tarifler", ingredients: ["1 kabak", "1 biber", "1 domates", "3 yumurta", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Sebzeleri doğrayıp yağda 5 dakika çevirin.", "Yumurtaları kırın.", "Tuz serpin.", "200 °C fırında 8 dakika veya kapağı kapalı ocakta 6 dakika pişirin.", "Servis edin."], minutes: 20, servings: 2, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 200, tips: ["Tek tavada az bulaşık."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n07_308", title: "Yoğurtlu meyveli dondurma kasesi", category: "Pratik tarifler", ingredients: ["1 su bardağı dondurulmuş meyve", "4 yemek kaşığı süzme yoğurt", "1 yemek kaşığı bal"], steps: ["Tüm malzemeyi blenderda çekin.", "Kıvam dondurma gibi olmalı.", "Kaselere alın.", "Hemen servis edin.", "İsterseniz 30 dakika dondurun."], minutes: 5, servings: 2, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Dondurulmuş muz eklerseniz daha kremamsı olur."], serving: "Soğuk.", storage: "Hemen tüketin."),
  GeneralRecipe(id: "n07_309", title: "Pratik tavuk çorbası (hazır suyla)", category: "Pratik tarifler", ingredients: ["5 su bardağı tavuk suyu", "1 su bardağı didiklenmiş tavuk", "3 yemek kaşığı pirinç", "1 havuç (rendelenmiş)", "1 limon"], steps: ["Suyu kaynatın.", "Pirinç ve havucu ekleyin.", "12 dakika pişirin.", "Tavuğu ekleyin.", "Limonla servis edin."], minutes: 20, servings: 4, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", tips: ["Haşlanmış tavuk kalanlarını değerlendirir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n07_310", title: "Fırında peynirli patlıcan dilimleri", category: "Pratik tarifler", ingredients: ["2 patlıcan", "1 su bardağı rendelenmiş kaşar", "2 domates", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz, kekik"], steps: ["Patlıcanları halka kesip yağ ve tuzla harmanlayın.", "200 °C'de 12 dakika pişirin.", "Üzerine domates dilimi ve kaşar koyun.", "8 dakika daha pişirin.", "Kekik serpin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 200, tips: ["Pratik bir meze veya garnitürdür."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n08_001", title: "Fırında bütün tavuk (limon ve kekikli)", category: "Tavuk yemekleri", ingredients: ["1 bütün tavuk (1,5 kg)", "2 limon", "4 diş sarımsak", "3 yemek kaşığı tereyağı", "1 tatlı kaşığı kekik, biberiye", "1 tatlı kaşığı tuz, karabiber", "4 patates"], steps: ["Tavuğu kurulayın; derisinin altına tereyağı, sarımsak ve otları yerleştirin.", "İçine yarım limon koyup dışını tuz ve karabiberle ovun.", "Patatesleri tepsiye dizip tavuğu üzerine yerleştirin.", "200 °C'de 80–90 dakika, but kısmı 80 °C olana kadar pişirin.", "15 dakika dinlendirip parçalayın."], minutes: 105, servings: 6, prepMinutes: 15, cookMinutes: 90, difficulty: "Orta", ovenCelsius: 200, tips: ["Derinin altındaki tereyağı eti nemli tutar."], serving: "Patatesle.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_002", title: "Tavuk dolma (biberli)", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü", "2 kırmızı biber", "1 soğan", "2 domates", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz, kekik"], steps: ["Tavuğu küp doğrayıp tereyağında mühürleyin.", "Soğan ve biberi ekleyin.", "Domatesi ekleyip 15 dakika pişirin.", "Kekik serpin.", "Pilavla servis edin."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", tips: ["Biberler tavuğun suyuyla yumuşar."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_003", title: "Tavuk ciğer sote", category: "Tavuk yemekleri", ingredients: ["500 g tavuk ciğeri", "1 soğan", "2 sivri biber", "2 yemek kaşığı tereyağı", "1 çay kaşığı kimyon, tuz, pul biber"], steps: ["Ciğerleri temizleyip küçük doğrayın.", "Tereyağında yüksek ateşte 4 dakika pişirin.", "Soğan ve biberi ekleyin.", "3 dakika daha pişirin.", "Baharatlarla servis edin."], minutes: 20, servings: 4, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Ciğeri fazla pişirmeyin; sertleşir."], serving: "Sıcak.", storage: "Aynı gün."),
  GeneralRecipe(id: "n08_004", title: "Ballı hardallı tavuk but", category: "Tavuk yemekleri", ingredients: ["8 tavuk but", "2 yemek kaşığı bal", "2 yemek kaşığı hardal", "2 yemek kaşığı zeytinyağı", "1 limon", "1 çay kaşığı tuz"], steps: ["Bal, hardal, yağ, limon ve tuzu karıştırın.", "Tavukları sosla 30 dakika marine edin.", "Tepsiye dizin.", "200 °C'de 40 dakika pişirin.", "Kalan sosu üzerine sürün."], minutes: 50, servings: 4, prepMinutes: 10, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 200, tips: ["Bal karamelize olur; yanmasın diye son 10 dakika folyo örtün."], serving: "Salatayla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_005", title: "Tavuklu bezelyeli pilav (tek tencere)", category: "Tavuk yemekleri", ingredients: ["400 g tavuk but", "1,5 su bardağı pirinç", "1 su bardağı bezelye", "1 havuç", "2 yemek kaşığı tereyağı", "3 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Tavuğu küp doğrayıp tereyağında mühürleyin.", "Havucu ekleyin.", "Pirinci ekleyip kavurun.", "Su, bezelye ve tuzla 18 dakika pişirin.", "Demlendirin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", tips: ["Tek tencerede tam öğün."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_006", title: "Hindi göğsü rosto", category: "Tavuk yemekleri", ingredients: ["1 kg hindi göğsü", "3 yemek kaşığı tereyağı", "3 diş sarımsak", "1 tatlı kaşığı kekik, biberiye", "1 tatlı kaşığı tuz, karabiber", "1 su bardağı tavuk suyu"], steps: ["Hindiyi baharatlı tereyağıyla ovun.", "Tencerede her yüzünü mühürleyin.", "Fırın kabına alıp tavuk suyu ekleyin.", "180 °C'de 60–70 dakika pişirin.", "Dinlendirip dilimleyin."], minutes: 85, servings: 6, prepMinutes: 15, cookMinutes: 70, difficulty: "Orta", ovenCelsius: 180, tips: ["İç sıcaklık 74 °C olmalı."], serving: "Kestaneli pilavla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_007", title: "Tavuk köri (yoğurtlu)", category: "Tavuk yemekleri", ingredients: ["600 g tavuk göğsü", "1 soğan", "1 yemek kaşığı köri", "1 su bardağı yoğurt", "1 tatlı kaşığı nişasta", "2 yemek kaşığı sıvı yağ", "1 çay kaşığı tuz"], steps: ["Tavuğu mühürleyin.", "Soğan ve köriyi ekleyin.", "Yoğurdu nişastayla çırpıp ekleyin.", "Kısık ateşte 15 dakika pişirin.", "Pilavla servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Nişasta yoğurdun kesilmesini önler."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_008", title: "Tavuk kavurma (Karadeniz usulü)", category: "Tavuk yemekleri", ingredients: ["600 g tavuk but", "2 soğan", "2 sivri biber", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz, karabiber"], steps: ["Tavuğu küçük doğrayın.", "Tereyağında suyunu çekene kadar kavurun.", "Soğan ve biberi ekleyin.", "10 dakika daha kavurun.", "Sıcak servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Kavurma kendi yağında pişer."], serving: "Pilavla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_009", title: "Tavuklu mantarlı kaşarlı güveç", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü", "250 g mantar", "1 biber", "1 domates", "1 su bardağı rendelenmiş kaşar", "2 yemek kaşığı tereyağı", "1 çay kaşığı tuz, kekik"], steps: ["Tavuğu tereyağında mühürleyin.", "Mantar ve biberi ekleyip soteleyin.", "Domatesi ekleyin.", "Güveçlere alıp kaşar serpin.", "200 °C'de 15 dakika pişirin."], minutes: 40, servings: 4, prepMinutes: 10, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 200, tips: ["Güveçler tek kişilik servis için idealdir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_010", title: "Tavuk ızgara (yoğurt marine)", category: "Tavuk yemekleri", ingredients: ["4 tavuk göğsü", "4 yemek kaşığı yoğurt", "1 limon", "2 diş sarımsak", "1 tatlı kaşığı kekik, tatlı toz biber, tuz"], steps: ["Tavukları inceltin.", "Yoğurt, limon, sarımsak ve baharatla en az 1 saat marine edin.", "Izgara tavayı kızdırın.", "Her yüzü 6–7 dakika pişirin.", "Dinlendirip dilimleyin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Yoğurt tavuğu yumuşatır."], serving: "Salatayla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_011", title: "Tavuk börek (milföyden)", category: "Tavuk yemekleri", ingredients: ["6 kare milföy", "300 g haşlanmış tavuk", "1 soğan", "1 su bardağı rendelenmiş kaşar", "1 yumurta"], steps: ["Tavuğu didikleyip kavrulmuş soğanla karıştırın.", "Kaşarı ekleyin.", "Milföylere harç koyup kapatın.", "Yumurta sarısı sürün.", "200 °C'de 25 dakika pişirin."], minutes: 45, servings: 6, prepMinutes: 20, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Kalan tavuğu değerlendirmek için idealdir."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n08_012", title: "Tavuk çöp şiş (fırında)", category: "Tavuk yemekleri", ingredients: ["500 g tavuk but", "1 soğan (rendelenmiş, suyu)", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kimyon, tuz, pul biber"], steps: ["Tavuğu küçük küp doğrayın.", "Soğan suyu, yağ ve baharatla 1 saat marine edin.", "Küçük şişlere dizin.", "220 °C'de 15 dakika çevirerek pişirin.", "Lavaşla servis edin."], minutes: 35, servings: 4, prepMinutes: 20, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 220, tips: ["Soğan suyu tavuğu yumuşatır."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_013", title: "Tavuklu sebzeli krep", category: "Tavuk yemekleri", ingredients: ["Krep: 1 su bardağı un, 1,5 su bardağı süt, 2 yumurta", "300 g haşlanmış tavuk", "1 su bardağı mantar", "1 su bardağı beşamel", "1 su bardağı rendelenmiş kaşar"], steps: ["Krep hamurunu çırpıp ince krepler pişirin.", "Tavuk ve mantarı soteleyip beşamelle karıştırın.", "Kreplere harç koyup rulo yapın.", "Fırın kabına dizip kaşar serpin.", "200 °C'de 10 dakika pişirin."], minutes: 40, servings: 4, prepMinutes: 20, cookMinutes: 20, difficulty: "Orta", ovenCelsius: 200, tips: ["Krepler önceden hazırlanabilir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_014", title: "Tavuk haşlama (limonlu sebzeli)", category: "Tavuk yemekleri", ingredients: ["1 tavuk (parçalanmış)", "2 havuç", "2 patates", "1 soğan", "1 limon", "1 tatlı kaşığı tuz, karabiber"], steps: ["Tavuğu suyla kaynatıp köpüğünü alın.", "Soğanı ekleyip 25 dakika pişirin.", "Sebzeleri ekleyin.", "15 dakika daha pişirin.", "Limonla servis edin."], minutes: 50, servings: 4, prepMinutes: 10, cookMinutes: 40, difficulty: "Kolay", tips: ["Hafif ve hastalıkta iyi gelen bir yemektir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_015", title: "Susamlı tavuk (fırında)", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü (parmak)", "2 yumurta", "Yarım su bardağı susam", "Yarım su bardağı galeta unu", "1 çay kaşığı tuz", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 210 °C'ye ısıtın.", "Tavukları yumurtaya batırın.", "Susam ve galeta unu karışımına bulayın.", "Tepsiye dizip yağ gezdirin.", "20 dakika pişirin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 210, tips: ["Susam alerjeni içerir."], serving: "Yoğurtlu sosla.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_101", title: "Burrito kasesi", category: "Dünya mutfağı", ingredients: ["1,5 su bardağı pişmiş pirinç", "300 g kıyma veya tavuk", "1 su bardağı haşlanmış barbunya", "1 su bardağı mısır", "1 domates", "1 avokado", "4 yemek kaşığı yoğurt", "1 tatlı kaşığı kimyon, tatlı toz biber, tuz"], steps: ["Kıymayı baharatlarla kavurun.", "Fasulye ve mısırı ısıtın.", "Domates ve avokadoyu doğrayın.", "Kaselere pirinç, kıyma, fasulye ve sebzeleri dizin.", "Yoğurtla servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", tips: ["Her bileşen ayrı hazırlanıp saklanabilir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_102", title: "Ton balıklı pirinç topları (onigiri)", category: "Dünya mutfağı", ingredients: ["2 su bardağı yapışkan pirinç", "2,5 su bardağı su", "1 kutu ton balığı", "2 yemek kaşığı yoğurt", "1 çay kaşığı tuz", "1 yemek kaşığı susam"], steps: ["Pirinci pişirip ılıtın.", "Ton balığını yoğurtla karıştırın.", "Islak elle pirinçten top yapıp ortasına ton koyun.", "Üçgen şekil verin.", "Susama bulayın."], minutes: 40, servings: 6, prepMinutes: 20, cookMinutes: 20, difficulty: "Orta", tips: ["Çiğ balık içermeyen güvenli bir alternatiftir."], serving: "Soğuk.", storage: "Aynı gün."),
  GeneralRecipe(id: "n08_103", title: "Minestrone çorbası", category: "Dünya mutfağı", ingredients: ["1 havuç", "1 kabak", "1 patates", "1 soğan", "1 su bardağı haşlanmış barbunya", "2 domates", "Yarım su bardağı küçük makarna", "2 yemek kaşığı zeytinyağı", "6 su bardağı su", "1 tatlı kaşığı tuz, fesleğen"], steps: ["Sebzeleri küp doğrayıp yağda 5 dakika çevirin.", "Domatesi ekleyin.", "Suyla 20 dakika pişirin.", "Fasulye ve makarnayı ekleyip 10 dakika pişirin.", "Fesleğenle servis edin."], minutes: 50, servings: 6, prepMinutes: 15, cookMinutes: 35, difficulty: "Kolay", tips: ["İtalyan sebze çorbasıdır; mevsim sebzeleri kullanılabilir."], serving: "Parmesanla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n08_104", title: "Tavuk shawarma (fırında)", category: "Dünya mutfağı", ingredients: ["600 g tavuk but", "3 yemek kaşığı yoğurt", "1 limon", "2 diş sarımsak", "1 tatlı kaşığı kimyon, zerdeçal, tatlı toz biber, tarçın, tuz", "4 lavaş"], steps: ["Tavuğu baharatlı yoğurtla 2 saat marine edin.", "220 °C'de 25 dakika pişirin.", "İnce dilimleyin.", "Lavaşa sarımsaklı yoğurt sürüp tavuğu yerleştirin.", "Turşu ve domatesle sarın."], minutes: 45, servings: 4, prepMinutes: 20, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 220, tips: ["Uzun marine lezzeti derinleştirir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_105", title: "Hollanda usulü fırın patates (hasselback)", category: "Dünya mutfağı", ingredients: ["4 orta boy patates", "3 yemek kaşığı tereyağı", "2 diş sarımsak", "1 tatlı kaşığı tuz, biberiye"], steps: ["Patatesleri iki kaşık arasına koyup tabana kadar kesmeden ince dilimleyin.", "Eritilmiş tereyağını sarımsak ve otlarla karıştırın.", "Patateslere sürün.", "200 °C'de 50 dakika, ara ara yağ sürerek pişirin.", "Sıcak servis edin."], minutes: 65, servings: 4, prepMinutes: 15, cookMinutes: 50, difficulty: "Kolay", ovenCelsius: 200, tips: ["Kaşıklar bıçağın sonuna kadar inmesini engeller."], serving: "Garnitür.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n08_106", title: "Tabule", category: "Dünya mutfağı", ingredients: ["Yarım su bardağı ince bulgur", "3 demet maydanoz", "Yarım demet nane", "3 domates", "4 dal taze soğan", "2 limon", "4 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Bulguru limon suyuyla ıslatın.", "Maydanozu çok ince kıyın.", "Domates ve soğanı küçük doğrayın.", "Hepsini zeytinyağı ve tuzla karıştırın.", "Soğuk servis edin."], minutes: 20, servings: 4, prepMinutes: 20, cookMinutes: 0, difficulty: "Kolay", tips: ["Tabulede yeşillik bulgurdan fazladır."], serving: "Soğuk.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n08_107", title: "Tavuklu noodle çorbası", category: "Dünya mutfağı", ingredients: ["150 g yumurtalı erişte", "300 g tavuk göğsü", "1 havuç", "2 dal taze soğan", "2 yemek kaşığı soya sosu", "1 tatlı kaşığı zencefil", "6 su bardağı tavuk suyu"], steps: ["Tavuk suyunu zencefille kaynatın.", "İnce dilimlenmiş tavuk ve havucu ekleyip 10 dakika pişirin.", "Erişteyi ekleyin.", "5 dakika pişirin.", "Soya ve taze soğanla servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Asya usulü hafif bir çorbadır."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_108", title: "Caprese salatası", category: "Dünya mutfağı", ingredients: ["4 domates", "250 g taze mozzarella", "1 avuç fesleğen", "3 yemek kaşığı zeytinyağı", "1 yemek kaşığı balzamik sirke", "1 çay kaşığı tuz"], steps: ["Domates ve mozzarellayı dilimleyin.", "Tabağa dönüşümlü dizin.", "Fesleğen yapraklarını yerleştirin.", "Yağ ve sirke gezdirin.", "Tuz serpin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Oda sıcaklığındaki domates daha lezzetlidir."], serving: "Soğuk.", storage: "Aynı gün."),
  GeneralRecipe(id: "n08_109", title: "Cornbread (tatlımsı mısır ekmeği)", category: "Dünya mutfağı", ingredients: ["1 su bardağı mısır unu", "1 su bardağı un", "3 yemek kaşığı şeker", "1 su bardağı süt", "1 yumurta", "4 yemek kaşığı eritilmiş tereyağı", "1 paket kabartma tozu"], steps: ["Fırını 200 °C'ye ısıtın.", "Kuru malzemeleri karıştırın.", "Süt, yumurta ve tereyağını ekleyin.", "Yağlı kalıba dökün.", "25 dakika pişirin."], minutes: 35, servings: 8, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Amerikan usulü hafif tatlı mısır ekmeğidir."], serving: "Çorbayla.", storage: "Kapalı kapta 2 gün."),
  GeneralRecipe(id: "n08_110", title: "Fransız tost (tarçınlı)", category: "Dünya mutfağı", ingredients: ["4 dilim brioş veya bayat ekmek", "2 yumurta", "Yarım su bardağı süt", "1 tatlı kaşığı tarçın", "1 yemek kaşığı tereyağı", "2 yemek kaşığı bal veya pekmez"], steps: ["Yumurta, süt ve tarçını çırpın.", "Ekmekleri batırın.", "Tereyağında her yüzü 2 dakika kızartın.", "Tabağa alın.", "Bal ve meyveyle servis edin."], minutes: 13, servings: 2, prepMinutes: 5, cookMinutes: 8, difficulty: "Kolay", tips: ["Bayat ekmek sıvıyı daha iyi emer."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n08_201", title: "Yulaflı sebze çorbası", category: "Diyet ve sağlıklı tarifler", ingredients: ["4 yemek kaşığı yulaf", "1 havuç", "1 kabak", "1 soğan", "1 domates", "6 su bardağı su", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Sebzeleri küçük doğrayıp yağda çevirin.", "Su ve yulafı ekleyin.", "20 dakika pişirin.", "İsteğe göre blenderdan geçirin.", "Sıcak servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Yulaf tok tutar ve lif sağlar."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
