  GeneralRecipe(id: "n08_207", title: "Fırında baharatlı karnabahar steak", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 karnabahar", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı zerdeçal, kimyon, tuz", "2 yemek kaşığı tahinli yoğurt"], steps: ["Karnabaharı 2 cm kalınlığında dilimleyin.", "Yağ ve baharatla ovun.", "210 °C'de 25 dakika pişirin.", "Yarısında çevirin.", "Tahinli yoğurtla servis edin."], minutes: 35, servings: 2, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 210, tips: ["Et yerine doyurucu bir sebze ana yemeğidir."], serving: "Sıcak.", storage: "Buzdolabında 1 gün."),
