  GeneralRecipe(id: "n08_301", title: "Soğuk yeşil çay (ballı limonlu)", category: "İçecekler", ingredients: ["2 poşet yeşil çay", "4 su bardağı 80 °C su", "1 limon", "2 yemek kaşığı bal", "4–5 dal nane"], steps: ["Suyu kaynatıp 2 dakika soğutun.", "Çayı 3 dakika demleyin.", "Balı ekleyip soğutun.", "Limon ve nane ekleyin.", "Buzla servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Yeşil çayı kaynar suda demlemek acılaştırır."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_302", title: "Karpuz naneli içecek", category: "İçecekler", ingredients: ["4 su bardağı çekirdeksiz karpuz", "1 limon", "4–5 dal nane", "1 su bardağı buz"], steps: ["Karpuzu blenderda çekin.", "Süzün.", "Limon suyunu ekleyin.", "Nane ve buzla servis edin.", "Hemen için."], minutes: 5, servings: 4, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Şeker eklemeye gerek yoktur."], serving: "Soğuk servis edin.", storage: "Buzdolabında 12 saat."),
  GeneralRecipe(id: "n08_303", title: "Kakaolu muzlu süt", category: "İçecekler", ingredients: ["2 su bardağı süt", "1 muz", "1 yemek kaşığı kakao", "1 tatlı kaşığı bal"], steps: ["Tüm malzemeyi blendera koyun.", "30 saniye çekin.", "Bardaklara paylaştırın.", "Soğuk servis edin.", "Hemen için."], minutes: 5, servings: 2, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Çocuklar için şekersiz bir alternatiftir."], serving: "Soğuk servis edin.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n08_304", title: "Çilekli limonata", category: "İçecekler", ingredients: ["1 su bardağı çilek", "4 limon", "Yarım su bardağı şeker", "5 su bardağı su", "1 su bardağı buz"], steps: ["Çilekleri şekerle ezin.", "Limonları sıkın.", "Su ile karıştırın.", "Süzün.", "Buzla servis edin."], minutes: 10, servings: 6, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Çilek pembe renk ve doğal tat verir."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n08_305", title: "Tarçınlı elma çayı (meyveli)", category: "İçecekler", ingredients: ["2 elma", "1 çubuk tarçın", "4 karanfil", "4 su bardağı su", "1 yemek kaşığı bal"], steps: ["Elmaları dilimleyin.", "Su ve baharatlarla 10 dakika kaynatın.", "5 dakika demleyin.", "Süzüp bal ekleyin.", "Sıcak veya soğuk servis edin."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Kışın sıcak, yazın soğuk içilebilir."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n09_001", title: "Kuzu kapama", category: "Et yemekleri", ingredients: ["1 kg kuzu eti (kemikli)", "10 taze soğan", "1 marul", "1 demet dereotu", "2 yemek kaşığı tereyağı", "1 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Eti tencerenin dibine yerleştirin.", "Taze soğan ve marulu iri doğrayıp üzerine koyun.", "Dereotu, tereyağı, tuz ve suyu ekleyin.", "Kapağı kapalı kısık ateşte 2 saat pişirin.", "Dereotuyla servis edin."], minutes: 140, servings: 6, prepMinutes: 20, cookMinutes: 120, difficulty: "Orta", tips: ["Bahar yemeğidir; sebzeler eti yumuşatır."], serving: "Pilavla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_002", title: "Kıymalı patates musakka", category: "Et yemekleri", ingredients: ["500 g patates", "300 g kıyma", "1 soğan", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz"], steps: ["Patatesleri halka kesip fırında 15 dakika ön pişirin.", "Kıymayı soğan ve salçayla kavurun.", "Kaba patates ve kıymayı kat kat dizin.", "Domates dilimleri ve 1 bardak sıcak su ekleyin.", "180 °C'de 25 dakika pişirin."], minutes: 60, servings: 4, prepMinutes: 20, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 180, tips: ["Patatesi ön pişirmek süreyi kısaltır."], serving: "Yoğurtla.", storage: "Buzdolabında 3 gün."),
