  GeneralRecipe(id: "n09_004", title: "Fırında kuzu kol (sebzeli)", category: "Et yemekleri", ingredients: ["1,2 kg kuzu kol", "4 patates", "3 havuç", "1 soğan", "4 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı biberiye, tuz"], steps: ["Eti sarımsak ve otlarla ovun.", "Sebzeleri tepsiye yayın.", "Eti üzerine koyup 1 bardak su ekleyin.", "Folyoyla kapatıp 170 °C'de 2 saat pişirin.", "Folyoyu açıp 30 dakika kızartın."], minutes: 170, servings: 6, prepMinutes: 20, cookMinutes: 150, difficulty: "Zor", ovenCelsius: 170, tips: ["Yavaş pişirmek eti yumuşatır."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_005", title: "Et döner (ev usulü, tavada)", category: "Et yemekleri", ingredients: ["500 g dana bonfile (ince dilim)", "1 soğan (rendelenmiş)", "3 yemek kaşığı yoğurt", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kimyon, kekik, tuz, karabiber"], steps: ["Etleri soğan suyu, yoğurt, yağ ve baharatla 2 saat marine edin.", "Döküm tavayı iyice kızdırın.", "Etleri az az pişirin.", "Pişen etleri ince doğrayın.", "Pilav veya lavaşla servis edin."], minutes: 35, servings: 4, prepMinutes: 20, cookMinutes: 15, difficulty: "Orta", tips: ["Tavayı kalabalık etmeyin."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_006", title: "Kıymalı makarna güveç", category: "Et yemekleri", ingredients: ["300 g kıyma", "300 g kısa makarna", "2 domates", "1 soğan", "1 su bardağı rendelenmiş kaşar", "1 tatlı kaşığı tuz"], steps: ["Makarnayı yarı haşlayın.", "Kıymayı soğan ve domatesle pişirin.", "Makarnayla karıştırıp kaba alın.", "Kaşar serpin.", "200 °C'de 20 dakika pişirin."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 200, tips: ["Makarna fırında pişmeye devam eder."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_007", title: "Kuşbaşılı patlıcan kebabı", category: "Et yemekleri", ingredients: ["400 g kuşbaşı", "3 patlıcan", "2 domates", "2 biber", "1 soğan", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz"], steps: ["Patlıcanları iri küp doğrayıp tuzlu suda bekletin.", "Eti kavurup soğanı ekleyin.", "Patlıcan, domates ve biberi ekleyin.", "1 bardak suyla 45 dakika pişirin.", "Pilavla servis edin."], minutes: 80, servings: 4, prepMinutes: 20, cookMinutes: 60, difficulty: "Kolay", tips: ["Patlıcan kızartılmadan da lezzetlidir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_008", title: "Köfteli patates yemeği", category: "Et yemekleri", ingredients: ["300 g kıyma", "2 yemek kaşığı galeta unu", "3 patates", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı tuz"], steps: ["Kıymayı galeta unu ve tuzla yoğurup küçük köfteler yapın.", "Soğan ve salçayı kavurun.", "Küp patatesleri ekleyin.", "2 bardak sıcak suyla 15 dakika pişirin.", "Köfteleri ekleyip 15 dakika daha pişirin."], minutes: 55, servings: 4, prepMinutes: 20, cookMinutes: 35, difficulty: "Kolay", tips: ["Köfteleri sona eklemek dağılmalarını önler."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_009", title: "Dana bonfile (tavada)", category: "Et yemekleri", ingredients: ["2 dilim dana bonfile", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı", "2 diş sarımsak", "1 dal biberiye", "1 tatlı kaşığı tuz"], steps: ["Eti pişirmeden 30 dakika önce buzdolabından çıkarın.", "Tavayı çok kızdırıp yağı ekleyin.", "Her yüzü 3–4 dakika pişirin.", "Tereyağı, sarımsak ve biberiyeyi ekleyip eti yağla bastırın.", "5 dakika dinlendirip tuzlayın."], minutes: 15, servings: 2, prepMinutes: 5, cookMinutes: 10, difficulty: "Orta", tips: ["Dinlendirme suyun içeride kalmasını sağlar."], serving: "Patates püresiyle.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_010", title: "Kıymalı karnabahar graten", category: "Et yemekleri", ingredients: ["1 karnabahar", "300 g kıyma", "1 soğan", "2 su bardağı beşamel", "1 su bardağı rendelenmiş kaşar", "1 tatlı kaşığı tuz"], steps: ["Karnabaharı 5 dakika haşlayın.", "Kıymayı soğanla kavurun.", "Kaba karnabahar ve kıymayı yayın.", "Beşamel ve kaşarı dökün.", "200 °C'de 25 dakika pişirin."], minutes: 45, servings: 4, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 200, tips: ["Karnabaharı fazla haşlamayın."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_101", title: "Levrek şiş (fırında)", category: "Balık ve deniz ürünleri", ingredients: ["600 g levrek fileto", "1 biber", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı kekik, tuz"], steps: ["Balığı küp doğrayın.", "Yağ, limon ve baharatla 20 dakika marine edin.", "Sebzelerle şişlere dizin.", "220 °C'de 12–15 dakika pişirin.", "Limonla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 220, tips: ["Balık parçalarını büyük kesin; dağılmaz."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n09_102", title: "Somon köftesi", category: "Balık ve deniz ürünleri", ingredients: ["300 g pişmiş somon", "2 haşlanmış patates", "1 yumurta", "3 yemek kaşığı galeta unu", "Yarım demet dereotu", "1 tatlı kaşığı tuz", "2 yemek kaşığı sıvı yağ"], steps: ["Somon ve patatesi ezin.", "Yumurta, galeta unu, dereotu ve tuzla yoğurun.", "Köfte şekli verin.", "Tavada her yüzü 3 dakika kızartın.", "Yoğurtla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Kalan somonu değerlendirir."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n09_103", title: "Hamsili pilav", category: "Balık ve deniz ürünleri", ingredients: ["1 kg hamsi (kılçıksız, açılmış)", "2 su bardağı pirinç", "1 soğan", "2 yemek kaşığı kuş üzümü", "2 yemek kaşığı çam fıstığı", "3 yemek kaşığı tereyağı", "1 tatlı kaşığı yenibahar, tarçın, tuz"], steps: ["Pirinçle iç pilav hazırlayın (fıstık, soğan, üzüm, baharat).", "Tepsiyi yağlayıp hamsileri derisi alta gelecek şekilde dizin.", "Pilavı yayın.", "Üzerini hamsilerle kapatın.", "200 °C'de 30 dakika pişirin."], minutes: 80, servings: 6, prepMinutes: 40, cookMinutes: 40, difficulty: "Zor", ovenCelsius: 200, tips: ["Karadeniz mutfağının bayram yemeğidir."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n09_104", title: "Mezgit buğulama", category: "Balık ve deniz ürünleri", ingredients: ["4 mezgit fileto", "1 soğan", "2 domates", "1 limon", "2 yemek kaşığı zeytinyağı", "Yarım demet maydanoz", "1 tatlı kaşığı tuz"], steps: ["Soğanı halka doğrayıp tavaya yayın.", "Balıkları üzerine koyun.", "Domates dilimleri, limon ve yağ ekleyin.", "Kapağı kapalı 12–15 dakika pişirin.", "Maydanozla servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Mezgit çocuklara uygun yumuşak bir balıktır."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n09_105", title: "Karidesli makarna (sarımsaklı)", category: "Balık ve deniz ürünleri", ingredients: ["350 g linguine", "300 g karides", "4 diş sarımsak", "4 yemek kaşığı zeytinyağı", "1 çay kaşığı pul biber", "Yarım demet maydanoz", "1 tatlı kaşığı tuz"], steps: ["Makarnayı haşlayın.", "Sarımsak ve pul biberi yağda çevirin.", "Karidesleri ekleyip 3 dakika pişirin.", "Makarna ve biraz haşlama suyunu ekleyin.", "Maydanozla servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Karidesi fazla pişirmeyin."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n09_106", title: "Fırında hamsi (kiremitte)", category: "Balık ve deniz ürünleri", ingredients: ["500 g hamsi", "2 domates", "2 biber", "1 soğan", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Sebzeleri doğrayıp kiremit veya güvece yayın.", "Hamsileri üzerine dizin.", "Yağ ve tuz ekleyin.", "220 °C'de 20 dakika pişirin.", "Sıcak servis edin."], minutes: 35, servings: 4, prepMinutes: 15, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 220, tips: ["Kiremit ısıyı eşit dağıtır."], serving: "Mısır ekmeğiyle.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n09_107", title: "Füme somonlu krep", category: "Balık ve deniz ürünleri", ingredients: ["4 krep", "150 g füme somon", "4 yemek kaşığı labne", "Yarım demet dereotu", "1 limon kabuğu"], steps: ["Labneyi dereotu ve limon kabuğuyla karıştırın.", "Kreplere sürün.", "Somonu yerleştirin.", "Rulo yapın.", "Dilimleyip servis edin."], minutes: 25, servings: 4, prepMinutes: 15, cookMinutes: 10, difficulty: "Kolay", tips: ["Füme somon tuzludur; tuz eklemeyin."], serving: "Soğuk.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n09_108", title: "Lüfer ızgara", category: "Balık ve deniz ürünleri", ingredients: ["2 lüfer", "2 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı tuz", "1 demet roka"], steps: ["Balıkları temizleyip çizik atın.", "Yağ ve tuzla ovun.", "Izgarada her yüzü 5–6 dakika pişirin.", "Limon sıkın.", "Rokayla servis edin."], minutes: 17, servings: 2, prepMinutes: 5, cookMinutes: 12, difficulty: "Kolay", tips: ["Sezonunda tüketin."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n09_109", title: "Ton balıklı patates salatası", category: "Balık ve deniz ürünleri", ingredients: ["4 patates", "1 kutu ton balığı", "1 kırmızı soğan", "10 zeytin", "3 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı tuz"], steps: ["Patatesleri haşlayıp küp doğrayın.", "Ton balığını süzün.", "Soğanı doğrayın.", "Hepsini zeytinyağı ve limonla karıştırın.", "Servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Doyurucu bir salatadır."], serving: "Soğuk.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n09_110", title: "Çupra kâğıt kebabı", category: "Balık ve deniz ürünleri", ingredients: ["2 çipura fileto", "1 domates", "1 biber", "4 mantar", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı kekik, tuz"], steps: ["Pişirme kâğıdına balığı koyun.", "Sebzeleri doğrayıp üzerine yayın.", "Tereyağı ve baharatı ekleyin.", "Paket yapın.", "200 °C'de 25 dakika pişirin."], minutes: 40, servings: 2, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Buharında pişer, kurumaz."], serving: "Sıcak.", storage: "Aynı gün tüketin."),
  GeneralRecipe(id: "n09_201", title: "Tavada nohut köftesi", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış nohut", "1 soğan", "3 yemek kaşığı galeta unu", "1 yumurta", "1 tatlı kaşığı kimyon, tuz", "2 yemek kaşığı sıvı yağ"], steps: ["Nohutu ezin.", "Rendelenmiş soğan, galeta unu, yumurta ve baharatla yoğurun.", "Köfte şekli verin.", "Tavada her yüzü 3 dakika pişirin.", "Yoğurtla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Etsiz protein kaynağıdır."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_202", title: "Etsiz pişmiş çiğ köfte", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı kırmızı mercimek", "1 su bardağı ince bulgur", "2 yemek kaşığı biber salçası", "1 soğan", "4 dal taze soğan", "Yarım demet maydanoz", "4 yemek kaşığı zeytinyağı", "1 tatlı kaşığı isot, kimyon, tuz"], steps: ["Mercimeği 2,5 bardak suyla dağılana kadar pişirin.", "Ocaktan alıp bulguru ekleyin, 20 dakika şişirin.", "Salça, soğan ve baharatlarla yoğurun.", "Yeşillikleri ekleyin.", "Sıkıp şekil verin."], minutes: 45, servings: 6, prepMinutes: 30, cookMinutes: 15, difficulty: "Kolay", tips: ["Etsiz ve pişmiş versiyondur."], serving: "Marul ve limonla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_203", title: "Nohutlu tavuk yahni", category: "Bakliyat yemekleri", ingredients: ["300 g tavuk but", "2 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "2 su bardağı sıcak su", "1 tatlı kaşığı tuz"], steps: ["Tavuğu küp doğrayıp tereyağında mühürleyin.", "Soğan ve salçayı ekleyin.", "Nohut ve suyu ekleyin.", "25 dakika pişirin.", "Pilavla servis edin."], minutes: 45, servings: 4, prepMinutes: 10, cookMinutes: 35, difficulty: "Kolay", tips: ["Nohut ve tavuk tam protein sağlar."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_204", title: "Yeşil mercimekli ıspanak", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "500 g ıspanak", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Soğanı kavurup salçayı ekleyin.", "Mercimeği ekleyin.", "Ispanağı ekleyip soldurun.", "15 dakika pişirin.", "Yoğurtla servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Demir açısından zengin bir yemektir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n09_205", title: "Börülceli pazı kavurma", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı haşlanmış börülce", "1 demet pazı", "1 soğan", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı pul biber, tuz"], steps: ["Soğan ve sarımsağı yağda kavurun.", "Doğranmış pazıyı ekleyin.", "Börülceyi ekleyin.", "10 dakika pişirin.", "Pul biberle servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Ege mutfağından hafif bir yemektir."], serving: "Ilık.", storage: "Buzdolabında 3 gün."),
