  GeneralRecipe(id: "n09_501", title: "Yayla çorbası (pirinçli, naneli)", category: "Çorbalar", ingredients: ["3 yemek kaşığı pirinç", "1,5 su bardağı yoğurt", "1 yumurta sarısı", "1 yemek kaşığı un", "5 su bardağı su", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı nane, tuz"], steps: ["Pirinci suyla 15 dakika pişirin.", "Yoğurt, yumurta ve unu çırpın.", "Sıcak sudan ekleyerek ılıştırın.", "Tencereye ekleyip karıştırarak kaynatın.", "Naneli tereyağıyla servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Terbiye ılıştırılmazsa kesilir."], serving: "Sıcak.", storage: "Buzdolabında 3 gün."),
