  GeneralRecipe(id: "n10_001", title: "Kabak tatlısı (cevizli)", category: "Tatlılar", ingredients: ["1 kg balkabağı", "1,5 su bardağı şeker", "Yarım su bardağı ceviz", "Kaymak veya tahin için 4 yemek kaşığı"], steps: ["Kabağı soyup iri dilimleyin.", "Tencereye dizip şekeri serpin, 4 saat bekletin.", "Kendi suyunda kısık ateşte 40 dakika pişirin.", "Soğutun.", "Ceviz ve kaymakla servis edin."], minutes: 50, servings: 6, prepMinutes: 10, cookMinutes: 40, difficulty: "Kolay", tips: ["Su eklemeyin; kabak suyunu salar."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n10_002", title: "Ayva tatlısı", category: "Tatlılar", ingredients: ["2 ayva", "1 su bardağı şeker", "2 su bardağı su", "4 karanfil", "4 yemek kaşığı kaymak"], steps: ["Ayvaları ikiye kesip çekirdeklerini oyun.", "Tencereye dizip şeker, su ve karanfil ekleyin.", "Çekirdekleri tülbente sarıp ekleyin.", "Kısık ateşte 60 dakika kırmızılaşana kadar pişirin.", "Kaymakla servis edin."], minutes: 75, servings: 4, prepMinutes: 15, cookMinutes: 60, difficulty: "Orta", tips: ["Çekirdekler kırmızı rengi verir."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n10_003", title: "Sütlü irmik tatlısı (kalıp)", category: "Tatlılar", ingredients: ["1 litre süt", "1 su bardağı şeker", "1 su bardağı irmik", "1 yemek kaşığı tereyağı", "1 paket vanilin"], steps: ["Süt ve şekeri ısıtın.", "İrmiği yağmur gibi serperek ekleyin.", "Koyulaşana kadar karıştırarak 8 dakika pişirin.", "Tereyağı ve vanilini ekleyin.", "Islak kalıplara döküp soğutun."], minutes: 20, servings: 6, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", tips: ["Kalıpları ıslatmak tatlının kolay çıkmasını sağlar."], serving: "Soğuk, meyve sosuyla.", storage: "Buzdolabında 3 gün."),
