  GeneralRecipe(id: "n10_005", title: "Meyveli jöle kupu", category: "Tatlılar", ingredients: ["2 paket meyveli jöle", "1 su bardağı mevsim meyvesi", "1 su bardağı süzme yoğurt", "2 yemek kaşığı bal"], steps: ["Jöleyi paket talimatına göre hazırlayın.", "Meyveleri bardaklara paylaştırın.", "Ilık jöleyi dökün.", "Donunca balı yoğurdu üzerine koyun.", "Soğuk servis edin."], minutes: 15, servings: 6, prepMinutes: 10, cookMinutes: 5, difficulty: "Kolay", tips: ["Kivi ve ananas jölenin donmasını engeller."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n10_006", title: "Fırında sütlü muzlu tatlı", category: "Tatlılar", ingredients: ["3 muz", "1 litre süt", "1 su bardağı şeker", "3 yemek kaşığı nişasta", "2 yemek kaşığı un", "1 paket bisküvi"], steps: ["Süt, şeker, nişasta ve unla muhallebi pişirin.", "Bisküvileri kaba dizin.", "Muhallebinin yarısını dökün, muz dilimlerini yerleştirin.", "Kalan muhallebiyi dökün.", "Soğutup servis edin."], minutes: 40, servings: 6, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", tips: ["Muzları en son ekleyin; kararmasın."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n10_007", title: "Tahin helvalı tatlı (kup)", category: "Tatlılar", ingredients: ["200 g tahin helvası", "1 su bardağı süzme yoğurt", "4 yemek kaşığı ceviz", "2 yemek kaşığı bal"], steps: ["Helvayı ufalayın.", "Bardaklara yoğurt ve helvayı kat kat koyun.", "Ceviz serpin.", "Bal gezdirin.", "Soğuk servis edin."], minutes: 10, servings: 4, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["Pratik ve pişirmesiz bir tatlıdır."], serving: "Soğuk.", storage: "Aynı gün."),
  GeneralRecipe(id: "n10_008", title: "Fırında elmalı pankek (dutch baby)", category: "Tatlılar", ingredients: ["3 yumurta", "Yarım su bardağı un", "Yarım su bardağı süt", "1 elma", "2 yemek kaşığı tereyağı", "1 yemek kaşığı şeker", "1 çay kaşığı tarçın"], steps: ["Fırını 220 °C'ye ısıtın; dökme tavada tereyağını eritin.", "Elma dilimlerini şeker ve tarçınla tavada 3 dakika çevirin.", "Yumurta, un ve sütü pürüzsüz çırpın.", "Hamuru elmaların üzerine dökün.", "20 dakika kabarana kadar pişirin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Orta", ovenCelsius: 220, tips: ["Fırından çıkınca söner; hemen servis edin."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n10_009", title: "Höşmerim", category: "Tatlılar", ingredients: ["250 g taze tatlı peynir (tuzsuz)", "3 yemek kaşığı irmik", "4 yemek kaşığı şeker", "1 yemek kaşığı tereyağı"], steps: ["Peyniri tavada eritin.", "İrmiği ekleyip karıştırın.", "Yağını salana kadar 15 dakika pişirin.", "Şekeri ekleyip eritin.", "Ceviz ile servis edin."], minutes: 25, servings: 4, prepMinutes: 5, cookMinutes: 20, difficulty: "Kolay", tips: ["Tuzsuz peynir kullanılmalıdır."], serving: "Ilık.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n10_010", title: "Pekmezli irmik helvası", category: "Tatlılar", ingredients: ["1 su bardağı irmik", "3 yemek kaşığı tereyağı", "Yarım su bardağı üzüm pekmezi", "1 su bardağı süt", "Yarım su bardağı su", "2 yemek kaşığı ceviz"], steps: ["İrmiği tereyağında kavurun.", "Süt, su ve pekmezi ısıtıp ekleyin.", "Suyunu çekene kadar karıştırın.", "Demlendirin.", "Cevizle servis edin."], minutes: 25, servings: 6, prepMinutes: 5, cookMinutes: 20, difficulty: "Kolay", tips: ["Pekmez şekerin yerini tutar."], serving: "Ilık.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n10_011", title: "Çikolatalı muz dilimleri (dondurulmuş)", category: "Tatlılar", ingredients: ["3 muz", "100 g bitter çikolata", "2 yemek kaşığı fındık (kırılmış)"], steps: ["Muzları kalın dilimleyin.", "Çikolatayı eritin.", "Dilimleri çikolataya batırın.", "Fındık serpin.", "1 saat dondurun."], minutes: 15, servings: 4, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Çocuklar için sağlıklı atıştırmalık."], serving: "Soğuk.", storage: "Dondurucuda 1 hafta."),
  GeneralRecipe(id: "n10_012", title: "Çilekli sütlü tatlı (pratik)", category: "Tatlılar", ingredients: ["1 litre süt", "1 su bardağı şeker", "3 yemek kaşığı nişasta", "2 yemek kaşığı un", "1 su bardağı çilek"], steps: ["Muhallebiyi pişirin.", "Çilekleri dilimleyin.", "Kaselere muhallebi ve çileği dizin.", "Soğutun.", "Servis edin."], minutes: 25, servings: 6, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Çilek sosu da hazırlanabilir."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n10_013", title: "Yoğurt tatlısı (şerbetli)", category: "Tatlılar", ingredients: ["1 su bardağı yoğurt", "1 su bardağı şeker", "3 yumurta", "1 su bardağı un", "1 paket kabartma tozu", "Şerbet: 2,5 su bardağı şeker, 3 su bardağı su"], steps: ["Şerbeti kaynatıp soğutun.", "Hamur malzemelerini çırpın.", "180 °C'de 35 dakika pişirin.", "Sıcak tatlıya soğuk şerbeti dökün.", "Dilimleyin."], minutes: 50, servings: 10, prepMinutes: 15, cookMinutes: 35, difficulty: "Orta", ovenCelsius: 180, tips: ["Şerbet soğuk, tatlı sıcak olmalı."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
