  GeneralRecipe(id: "n10_204", title: "Fesleğenli tavuklu penne", category: "Makarnalar", ingredients: ["350 g penne", "300 g tavuk göğsü", "10 çeri domates", "1 avuç fesleğen", "3 yemek kaşığı zeytinyağı", "3 yemek kaşığı rendelenmiş parmesan", "1 çay kaşığı tuz"], steps: ["Makarnayı haşlayın.", "Tavuğu küp doğrayıp yağda pişirin.", "Domatesleri ekleyip 3 dakika çevirin.", "Makarnayı ekleyin.", "Fesleğen ve parmesanla servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Fesleğeni ocaktan alınca ekleyin."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n10_205", title: "Kabaklı kremalı fettuccine", category: "Makarnalar", ingredients: ["350 g fettuccine", "2 kabak (jülyen)", "Yarım su bardağı krema", "1 diş sarımsak", "2 yemek kaşığı tereyağı", "3 yemek kaşığı parmesan", "1 çay kaşığı tuz"], steps: ["Makarnayı haşlayın.", "Kabak ve sarımsağı tereyağında 4 dakika soteleyin.", "Kremayı ekleyin.", "Makarnayı ekleyip karıştırın.", "Parmesanla servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Kabak jülyenleri makarnayla uyumlu doku verir."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
