  GeneralRecipe(id: "n10_207", title: "Ton balıklı domatesli makarna", category: "Makarnalar", ingredients: ["350 g spagetti", "1 kutu ton balığı", "400 g domates", "2 diş sarımsak", "10 zeytin", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tuz"], steps: ["Makarnayı haşlayın.", "Sarımsağı yağda çevirin, domatesi ekleyip 8 dakika pişirin.", "Ton balığı ve zeytini ekleyin.", "Makarnayla karıştırın.", "Maydanozla servis edin."], minutes: 20, servings: 4, prepMinutes: 5, cookMinutes: 15, difficulty: "Kolay", tips: ["Kiler malzemeleriyle pratik yemek."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
