  GeneralRecipe(id: "n10_210", title: "Sebzeli soya soslu erişte (wok)", category: "Makarnalar", ingredients: ["300 g erişte", "1 havuç", "1 kabak", "1 biber", "4 mantar", "3 yemek kaşığı soya sosu", "2 yemek kaşığı sıvı yağ", "1 tatlı kaşığı susam"], steps: ["Erişteyi haşlayın.", "Sebzeleri jülyen doğrayın.", "Yüksek ateşte yağda 4 dakika çevirin.", "Erişte ve soyayı ekleyin.", "Susamla servis edin."], minutes: 22, servings: 4, prepMinutes: 10, cookMinutes: 12, difficulty: "Kolay", tips: ["Soya sosu tuzludur."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n10_301", title: "Kaşarlı sosisli milföy", category: "Hamur işleri", ingredients: ["8 kare milföy", "4 sosis", "8 dilim kaşar", "1 yumurta", "1 tatlı kaşığı susam"], steps: ["Sosisleri ikiye kesin.", "Milföylere kaşar ve sosis koyup sarın.", "Yumurta sürün.", "Susam serpin.", "200 °C'de 20 dakika pişirin."], minutes: 30, servings: 8, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 200, tips: ["Çocuk partileri için idealdir."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n10_302", title: "Ispanaklı peynirli kare börek (milföy)", category: "Hamur işleri", ingredients: ["8 kare milföy", "200 g ıspanak", "150 g beyaz peynir", "1 yumurta"], steps: ["Ispanağı soldurup peynirle karıştırın.", "Milföylerin ortasına koyun.", "Köşeleri ortaya katlayın.", "Yumurta sürün.", "200 °C'de 25 dakika pişirin."], minutes: 40, servings: 8, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 200, tips: ["Ispanak suyunu iyice sıkın."], serving: "Sıcak.", storage: "Taze tüketin."),
  GeneralRecipe(id: "n10_303", title: "Zeytinli açma (mayasız, pratik)", category: "Hamur işleri", ingredients: ["1 su bardağı yoğurt", "Yarım su bardağı sıvı yağ", "1 paket kabartma tozu", "Yaklaşık 3 su bardağı un", "Yarım su bardağı doğranmış zeytin", "1 yumurta"], steps: ["Yoğurt, yağ ve kabartma tozunu karıştırın.", "Un ve zeytinle hamur yapın.", "Şekil verin.", "Yumurta sürün.", "180 °C'de 25 dakika pişirin."], minutes: 40, servings: 12, prepMinutes: 15, cookMinutes: 25, difficulty: "Kolay", ovenCelsius: 180, tips: ["Mayasız olduğu için hızlıdır."], serving: "Çayla.", storage: "Kapalı kapta 2 gün."),
  GeneralRecipe(id: "n10_304", title: "Tepsi pizza (ev yapımı hamur)", category: "Hamur işleri", ingredients: ["3 su bardağı un", "1 paket instant maya", "1 su bardağı ılık su", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, şeker", "1 su bardağı domates sosu", "2 su bardağı rendelenmiş kaşar", "Üzeri için 1 biber, 6 mantar, 10 zeytin"], steps: ["Hamuru yoğurup 1 saat mayalandırın.", "Tepsiye yayın.", "Sos, kaşar ve malzemeleri yerleştirin.", "230 °C'de 18–20 dakika pişirin.", "Dilimleyin."], minutes: 110, servings: 6, prepMinutes: 90, cookMinutes: 20, difficulty: "Orta", ovenCelsius: 230, tips: ["Fırını iyice ısıtın."], serving: "Sıcak.", storage: "Buzdolabında 1 gün."),
  GeneralRecipe(id: "n10_305", title: "Kıymalı çıtır börek (yufka, fırında)", category: "Hamur işleri", ingredients: ["4 yufka", "300 g kıyma", "1 soğan", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "1 yumurta", "1 tatlı kaşığı tuz, karabiber"], steps: ["Kıymayı soğanla kavurup soğutun.", "Süt ve yağı karıştırın.", "Yufkaları sosla ıslatıp harçla katlayarak tepsiye dizin.", "Yumurta sürün.", "190 °C'de 30 dakika pişirin."], minutes: 50, servings: 6, prepMinutes: 20, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 190, tips: ["Harç soğuk olmalı."], serving: "Sıcak.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n10_401", title: "Tahinli kurabiye (çay saati)", category: "Kek ve kurabiyeler", ingredients: ["Yarım su bardağı tahin", "Yarım su bardağı sıvı yağ", "Yarım su bardağı şeker", "1 paket kabartma tozu", "Yaklaşık 2,5 su bardağı un"], steps: ["Tahin, yağ ve şekeri karıştırın.", "Kabartma tozu ve unla hamur yapın.", "Şekil verip tepsiye dizin.", "180 °C'de 15 dakika pişirin.", "Soğutun."], minutes: 30, servings: 20, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 180, tips: ["Yumurtasız bir kurabiyedir."], serving: "Çayla.", storage: "Kapalı kapta 1 hafta."),
  GeneralRecipe(id: "n10_402", title: "Kakaolu muffin", category: "Kek ve kurabiyeler", ingredients: ["2 yumurta", "Yarım su bardağı şeker", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "3 yemek kaşığı kakao", "2 su bardağı un", "1 paket kabartma tozu"], steps: ["Fırını 180 °C'ye ısıtın.", "Islak malzemeleri çırpın.", "Kuru malzemeleri ekleyin.", "Kalıplara paylaştırın.", "20 dakika pişirin."], minutes: 30, servings: 12, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", ovenCelsius: 180, tips: ["Fazla karıştırmayın."], serving: "Sütle.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n10_403", title: "Hindistan cevizli kurabiye", category: "Kek ve kurabiyeler", ingredients: ["2 yumurta akı", "Yarım su bardağı şeker", "2 su bardağı hindistan cevizi", "1 yemek kaşığı un"], steps: ["Yumurta aklarını şekerle kar gibi çırpın.", "Hindistan cevizi ve unu nazikçe katın.", "Kaşıkla tepsiye bırakın.", "170 °C'de 15 dakika pişirin.", "Soğutun."], minutes: 25, servings: 20, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 170, tips: ["Kalan yumurta aklarını değerlendirir."], serving: "Çayla.", storage: "Kapalı kapta 1 hafta."),
  GeneralRecipe(id: "n10_404", title: "Pekmezli tarçınlı kek", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "Yarım su bardağı şeker", "Yarım su bardağı pekmez", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "2,5 su bardağı un", "1 paket kabartma tozu", "1 tatlı kaşığı tarçın"], steps: ["Yumurta ve şekeri çırpın.", "Pekmez, süt ve yağı ekleyin.", "Kuru malzemeleri ekleyin.", "175 °C'de 40 dakika pişirin.", "Soğutun."], minutes: 55, servings: 10, prepMinutes: 15, cookMinutes: 40, difficulty: "Kolay", ovenCelsius: 175, tips: ["Pekmez kekin rengini koyulaştırır."], serving: "Çayla.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n10_405", title: "Cevizli üzümlü kurabiye (yulaflı)", category: "Kek ve kurabiyeler", ingredients: ["100 g tereyağı", "Yarım su bardağı esmer şeker", "1 yumurta", "1 su bardağı yulaf", "1 su bardağı un", "Yarım su bardağı kuru üzüm", "Yarım su bardağı ceviz", "Yarım çay kaşığı karbonat"], steps: ["Tereyağı ve şekeri çırpın.", "Yumurtayı ekleyin.", "Kuru malzemeleri, üzüm ve cevizi ekleyin.", "Kaşıkla tepsiye bırakın.", "180 °C'de 15 dakika pişirin."], minutes: 25, servings: 16, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 180, tips: ["Ortası yumuşak kalmalı."], serving: "Sütle.", storage: "Kapalı kapta 5 gün."),
  GeneralRecipe(id: "n11_002", title: "İçli köfte", category: "Hamur işleri", ingredients: ["Dış için: 2 su bardağı ince bulgur", "1 su bardağı irmik", "250 g yağsız kıyma (dış için)", "1 yumurta", "1 tatlı kaşığı tuz", "İç için: 250 g orta yağlı kıyma", "2 soğan", "Yarım su bardağı ceviz içi", "1 tatlı kaşığı pul biber", "1 tatlı kaşığı karabiber", "Yarım demet maydanoz", "Kızartmak için 3 su bardağı ayçiçek yağı"], steps: ["Bulguru 1 su bardağı ılık suyla ıslatıp 20 dakika bekletin.", "İç harç için soğanı kıymayla suyunu çekene kadar kavurun; baharat, ceviz ve maydanozu ekleyip soğutun.", "Bulgur, irmik, yağsız kıyma, yumurta ve tuzu 15 dakika, ele yapışmayan bir hamur olana kadar yoğurun.", "Elinizi ıslatıp ceviz büyüklüğünde parça alın, işaret parmağınızla oyarak ince bir kabuk açın.", "İçine 1 tatlı kaşığı harç koyup ağzını kapatın, iki ucu sivri şekil verin.", "Önceden ısıtılmış bol yağda (170 °C) 4–5 dakika, kızarana kadar kızartın; kağıt havluya alın.", "Haşlamalı yapmak için kaynar tuzlu suda yüzeye çıktıktan sonra 5 dakika pişirin."], minutes: 120, servings: 6, prepMinutes: 36, cookMinutes: 84, difficulty: "Zor", tips: ["Şekil verilmiş köfteler tepside dondurulup poşetlenerek 2 ay saklanabilir."], serving: "Sıcak ya da ılık.", storage: "Kapalı kapta 2 gün; dondurucuda 1 ay."),
  GeneralRecipe(id: "n11_003", title: "Ev baklavası", category: "Tatlılar", ingredients: ["40 yaprak baklavalık yufka", "250 g tereyağı", "2 su bardağı ince çekilmiş ceviz ya da Antep fıstığı", "Şerbet için: 3 su bardağı şeker", "2,5 su bardağı su", "Yarım limon suyu"], steps: ["Şerbet için şeker ve suyu kaynatın, 12 dakika kısık ateşte pişirip limon suyunu ekleyin ve tamamen soğutun.", "Tereyağını eritin, köpüğünü alın.", "Tepsiyi yağlayın; yufkaların yarısını her birinin arasına fırçayla tereyağı sürerek serin.", "Cevizi eşit yayın, kalan yufkaları aynı şekilde yağlayarak üstüne serin.", "Keskin bıçakla baklava dilimi kesin, kalan sıcak tereyağını üzerine gezdirin.", "180 °C fırında 50–60 dakika, altın rengi olana kadar pişirin.", "Sıcak baklavaya soğuk şerbeti kepçeyle dökün; en az 4 saat dinlendirin."], minutes: 150, servings: 10, prepMinutes: 40, cookMinutes: 110, difficulty: "Zor", ovenCelsius: 180, tips: ["Şerbet soğuk, baklava sıcak olmalı; ikisi de sıcak olursa hamurlaşır."], serving: "Soğuk ya da oda sıcaklığında.", storage: "Buzdolabında kapalı kapta 3 gün."),
  GeneralRecipe(id: "n11_004", title: "Künefe", category: "Tatlılar", ingredients: ["250 g tel kadayıf", "100 g tereyağı", "200 g tuzsuz künefe peyniri ya da taze kaşar", "Şerbet için: 1 su bardağı şeker", "1 su bardağı su", "1 tatlı kaşığı limon suyu", "Üzeri için 2 yemek kaşığı toz Antep fıstığı"], steps: ["Şeker ve suyu 10 dakika kaynatıp limon ekleyin, ılık kalsın.", "Kadayıfı elle didikleyip kısa parçalar hâline getirin, eritilmiş tereyağıyla harmanlayın.", "Künefe tavasının tabanına kadayıfın yarısını bastırarak yayın.", "Peyniri ince dilimleyip kenarlara 1 cm boşluk bırakarak dizin; kalan kadayıfı kapatıp bastırın.", "Ocakta kısık ateşte alt yüzü kızarana kadar 6–7 dakika pişirin, tabakla çevirip diğer yüzü pişirin (ya da 200 °C fırında 20 dakika).", "Sıcakken ılık şerbeti dökün, fıstık serpip hemen servis edin."], minutes: 40, servings: 4, prepMinutes: 12, cookMinutes: 28, difficulty: "Orta", ovenCelsius: 200, tips: ["Peyniri tuzluysa birkaç saat suda bekletip tuzunu alın."], serving: "Soğuk ya da oda sıcaklığında.", storage: "Buzdolabında kapalı kapta 3 gün."),
  GeneralRecipe(id: "n11_005", title: "İskender kebap", category: "Et yemekleri", ingredients: ["500 g döner eti ya da ince dilimlenmiş dana bonfile", "4 pide", "Sos için: 2 yemek kaşığı tereyağı", "1 yemek kaşığı domates salçası", "3 domates rendesi", "1 su bardağı et suyu", "1,5 su bardağı süzme yoğurt", "2 yemek kaşığı tereyağı (kızdırmak için)", "1 tatlı kaşığı tuz"], steps: ["Domates rendesi, salça ve tereyağını 10 dakika pişirip et suyuyla açın, tuzlayın.", "Eti az yağlı tavada yüksek ateşte, suyunu salmadan 3–4 dakika soteleyin.", "Pideleri küp doğrayıp tabaklara yayın, üzerine sosun bir kısmını gezdirin.", "Eti pidelerin üzerine yerleştirip kalan sosu dökün.", "Yanına yoğurt koyun; tereyağını köpürene kadar kızdırıp etin üzerine sıcak dökün."], minutes: 45, servings: 4, prepMinutes: 14, cookMinutes: 31, difficulty: "Orta", tips: ["Tereyağını yakmayın; köpürüp hafif renk aldığında dökün."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_006", title: "Adana kebap", category: "Et yemekleri", ingredients: ["600 g kuzu kıyma (yüzde 20 yağlı, zırhla çekilmiş)", "2 kırmızı sivri biber", "1 tatlı kaşığı pul biber", "1 tatlı kaşığı tuz", "4 yassı şiş", "Yanına 4 lavaş, 1 soğan, 2 domates, 4 sivri biber"], steps: ["Biberi çok ince kıyın, suyunu sıkın.", "Kıymayı biber, pul biber ve tuzla 10 dakika, yapışkan bir kıvam alana kadar yoğurun.", "Buzdolabında 1 saat dinlendirin.", "Elinizi ıslatarak harcı yassı şişlere 1,5 cm kalınlıkta, parmak izleriyle bastırarak geçirin.", "Kızgın mangalda ya da ızgarada çevirerek 8–10 dakika pişirin.", "Lavaşla, közlenmiş domates ve biberle servis edin."], minutes: 50, servings: 4, prepMinutes: 15, cookMinutes: 35, difficulty: "Orta", tips: ["Kıymanın yağsız olması kebabın şişten düşmesine neden olur."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_007", title: "Etli ekmek", category: "Hamur işleri", ingredients: ["Hamur için: 4 su bardağı un", "1 paket kuru maya", "1 tatlı kaşığı tuz", "1,5 su bardağı ılık su", "Harç için: 400 g kıyma", "2 soğan", "2 domates", "2 sivri biber", "Yarım demet maydanoz", "1 yemek kaşığı biber salçası", "Tuz, karabiber, pul biber (1 tatlı kaşığı tuz)"], steps: ["Un, maya, tuz ve suyu yoğurup 45 dakika mayalandırın.", "Soğan, domates, biber ve maydanozu çok ince kıyın; kıyma, salça ve baharatla iyice yoğurun.", "Hamuru 6 parçaya bölüp ince, uzun şeritler hâlinde açın.", "Harcı hamurun üzerine ince ve eşit yayın, kenarlara kadar bastırın.", "230 °C fırında taş ya da ters tepsi üzerinde 10–12 dakika pişirin.", "Dilimleyip sıcak servis edin."], minutes: 90, servings: 6, prepMinutes: 27, cookMinutes: 63, difficulty: "Orta", ovenCelsius: 230, tips: ["Konya usulü çok ince açılır; harç ince yayıldığı için hızlı pişer."], serving: "Sıcak ya da ılık.", storage: "Kapalı kapta 2 gün; dondurucuda 1 ay."),
  GeneralRecipe(id: "n11_008", title: "Kayseri mantısı", category: "Hamur işleri", ingredients: ["Hamur için: 3 su bardağı un", "1 yumurta", "1 tatlı kaşığı tuz", "1 su bardağı su", "İç için: 250 g kıyma", "1 küçük soğan rendesi", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber", "Sos için: 2 su bardağı sarımsaklı yoğurt", "3 yemek kaşığı tereyağı", "1 tatlı kaşığı pul biber", "1 tatlı kaşığı kuru nane, 1 tatlı kaşığı sumak"], steps: ["Un, yumurta, tuz ve suyu sert bir hamur olacak şekilde yoğurup 30 dakika dinlendirin.", "Kıyma, soğan rendesi ve baharatı karıştırın.", "Hamuru çok ince açıp 2 × 2 cm kareler kesin.", "Her kareye nohut tanesinden küçük iç koyup dört köşesini birleştirerek bohça yapın.", "Mantıları tepside 200 °C fırında 10 dakika hafif kızartın (isteğe bağlı).", "Kaynar tuzlu suda 10–12 dakika haşlayıp süzün.", "Üzerine sarımsaklı yoğurt, pul biberli kızdırılmış tereyağı, nane ve sumak ekleyin."], minutes: 120, servings: 6, prepMinutes: 36, cookMinutes: 84, difficulty: "Zor", ovenCelsius: 200, tips: ["Hazırlanan mantılar tepside dondurulup poşetlenerek 2 ay saklanabilir."], serving: "Sıcak ya da ılık.", storage: "Kapalı kapta 2 gün; dondurucuda 1 ay."),
  GeneralRecipe(id: "n11_009", title: "Tulumba tatlısı", category: "Tatlılar", ingredients: ["Hamur için: 1,5 su bardağı su", "125 g tereyağı", "2 su bardağı un", "1 yemek kaşığı irmik", "3 yumurta", "Şerbet için: 3 su bardağı şeker", "3 su bardağı su", "Yarım limon suyu", "Kızartmak için 1 litre ayçiçek yağı"], steps: ["Şerbeti 15 dakika kaynatıp limon ekleyin, soğutun.", "Su ve tereyağını kaynatın; un ve irmiği bir kerede ekleyip 3–4 dakika, tencereden ayrılana kadar karıştırın.", "Ilıyan hamura yumurtaları teker teker yedirin.", "Hamuru yıldız uçlu sıkma torbasına alın.", "Ilık yağa (yaklaşık 130 °C) 5 cm boyunda sıkıp kesin; ocağı yavaş yavaş açarak 10–12 dakika kızartın.", "Kızaran tulumbaları soğuk şerbete atın, 5 dakika bekletip çıkarın."], minutes: 60, servings: 8, prepMinutes: 18, cookMinutes: 42, difficulty: "Orta", tips: ["Yağ başta çok sıcak olursa tulumbanın içi çiğ kalır, şişmez."], serving: "Soğuk ya da oda sıcaklığında.", storage: "Buzdolabında kapalı kapta 3 gün."),
  GeneralRecipe(id: "n11_010", title: "Şekerpare", category: "Tatlılar", ingredients: ["125 g oda sıcaklığında tereyağı", "Yarım su bardağı pudra şekeri", "1 yumurta", "2 yemek kaşığı irmik", "1 paket vanilya", "1 paket kabartma tozu", "2 su bardağı un", "30 adet fındık içi", "Şerbet için: 2,5 su bardağı şeker", "3 su bardağı su", "Yarım limon suyu"], steps: ["Şerbeti 15 dakika kaynatıp limonu ekleyin ve soğutun.", "Tereyağı ve pudra şekerini krema kıvamına gelene kadar çırpın, yumurtayı ekleyin.", "İrmik, vanilya, kabartma tozu ve unu ekleyip ele yapışmayan yumuşak bir hamur yoğurun.", "Ceviz büyüklüğünde yuvarlak şekil verip ortasına fındık bastırın, tepsiye dizin.", "180 °C fırında 25–30 dakika, altları kızarana kadar pişirin.", "Sıcak tatlıya soğuk şerbeti dökün, şerbeti çekene kadar bekletin."], minutes: 70, servings: 10, prepMinutes: 21, cookMinutes: 49, difficulty: "Orta", ovenCelsius: 180, tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Soğuk ya da oda sıcaklığında.", storage: "Buzdolabında kapalı kapta 3 gün."),
  GeneralRecipe(id: "n11_011", title: "Un helvası", category: "Tatlılar", ingredients: ["2 su bardağı un", "125 g tereyağı", "2 yemek kaşığı ayçiçek yağı", "Şerbet için: 1,5 su bardağı şeker", "2 su bardağı süt", "1 su bardağı su"], steps: ["Süt, su ve şekeri şeker eriyene kadar ısıtın, sıcak tutun.", "Tereyağı ve sıvı yağı eritip unu ekleyin.", "Kısık ateşte sürekli karıştırarak 20–25 dakika, un kokusu gidip açık kahve rengini alana kadar kavurun.", "Ocağı kapatıp sıcak şerbeti dikkatle ekleyin, hızlıca karıştırın.", "Kapağı kapatıp 10 dakika demlendirin, kaşıkla şekil verip servis edin."], minutes: 35, servings: 6, prepMinutes: 10, cookMinutes: 25, difficulty: "Orta", tips: ["Şerbet eklerken buhar çıkar; elinizi uzak tutun."], serving: "Soğuk ya da oda sıcaklığında.", storage: "Buzdolabında kapalı kapta 3 gün."),
  GeneralRecipe(id: "n11_012", title: "İşkembe çorbası", category: "Çorbalar", ingredients: ["1 kg temizlenmiş işkembe", "3 yemek kaşığı un", "2 yemek kaşığı tereyağı", "2 yumurta sarısı", "1 limon suyu", "1 tatlı kaşığı tuz", "Sunum için 3 diş sarımsak ve yarım su bardağı sirke, 1 tatlı kaşığı pul biber"], steps: ["İşkembeyi soğuk suda birkaç kez yıkayın; düdüklü tencerede bol suyla 1 saat (normal tencerede 2,5 saat) yumuşayana kadar haşlayın.", "İşkembeyi çıkarıp küçük küçük doğrayın, haşlama suyunu süzün.", "Tereyağında unu 2 dakika kavurun, haşlama suyunu (yaklaşık 6 su bardağı) azar azar ekleyerek pürüzsüz karıştırın.", "Doğranmış işkembeyi ekleyip 15 dakika kaynatın, tuzlayın.", "Yumurta sarısı ve limonu çırpıp çorbadan birkaç kepçe alarak ılıştırın, tencereye ekleyin ve kaynatmadan ocaktan alın.", "Sirkeli sarımsak ve pul biberle servis edin."], minutes: 180, servings: 6, prepMinutes: 40, cookMinutes: 140, difficulty: "Zor", tips: ["İşkembe mutlaka iyi pişmiş ve güvenilir kasaptan temizlenmiş olmalı."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün; bir kez ısıtın."),
  GeneralRecipe(id: "n11_013", title: "Beyran çorbası", category: "Çorbalar", ingredients: ["600 g kemikli kuzu eti (gerdan ya da incik)", "1 su bardağı pirinç", "6 diş sarımsak", "2 yemek kaşığı tereyağı", "1 yemek kaşığı pul biber", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Eti bol suda köpüğünü alarak 2 saat, kemikten ayrılana kadar haşlayın.", "Eti didikleyin, kemikleri ayırın; suyu süzün.", "Pirinci yıkayıp ayrı tencerede az suyla yarı pişirin.", "Her kaseye pirinç, didiklenmiş et ve dövülmüş sarımsak koyun.", "Kaynar et suyunu tuzlayıp kaselere doldurun.", "Tereyağında pul biberi kızdırıp üzerine gezdirin."], minutes: 150, servings: 6, prepMinutes: 40, cookMinutes: 110, difficulty: "Zor", tips: ["Gaziantep'in sabah çorbasıdır; et suyu çok sıcak dökülür."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün; bir kez ısıtın."),
  GeneralRecipe(id: "n11_014", title: "Midye dolma", category: "Balık ve deniz ürünleri", ingredients: ["30 adet büyük midye", "1,5 su bardağı pirinç", "3 soğan", "Yarım su bardağı zeytinyağı", "2 yemek kaşığı kuş üzümü", "1 yemek kaşığı dolmalık fıstık", "1 tatlı kaşığı yenibahar", "1 tatlı kaşığı tarçın", "1 tatlı kaşığı karabiber", "1 tatlı kaşığı toz şeker", "1 tatlı kaşığı domates salçası", "Tuz, limon (1 tatlı kaşığı tuz)"], steps: ["Midyelerin kabuklarını tel fırçayla temizleyin, sakallarını çekin; bıçakla yan tarafından açın, kabukları ayırmayın.", "Pirinci 20 dakika ılık suda bekletip süzün.", "Soğanı zeytinyağında yumuşatın; fıstık, pirinç ve salçayı ekleyip 3 dakika kavurun.", "Baharatlar, kuş üzümü, şeker, tuz ve 1 su bardağı sıcak suyu ekleyip suyunu çekene kadar pişirin.", "Midyeleri harçla doldurup kapatın, tencereye sıkıca dizin.", "Üzerine ters tabak kapatıp 1,5 su bardağı sıcak su ekleyin; kısık ateşte 25 dakika pişirin.", "Soğuyunca limonla servis edin."], minutes: 75, servings: 6, prepMinutes: 22, cookMinutes: 53, difficulty: "Orta", tips: ["Açılmadan önce kapalı olmayan ya da kokan midyeleri kullanmayın."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_015", title: "Levrek buğulama", category: "Balık ve deniz ürünleri", ingredients: ["4 levrek fileto", "2 domates", "1 soğan", "2 sivri biber", "4 diş sarımsak", "3 yemek kaşığı zeytinyağı", "1 limon", "Yarım demet maydanoz", "2 defne yaprağı, 1 tatlı kaşığı tuz, 1 çay kaşığı karabiber"], steps: ["Soğanı halka, domatesi küp, biberi halka doğrayın.", "Geniş tavaya zeytinyağı, soğan ve sarımsağı alıp 3 dakika çevirin.", "Balıkları sebzelerin üzerine yerleştirip domates ve biberle kapatın.", "Tuz, karabiber, defne ve limon dilimlerini ekleyin; yarım su bardağı sıcak su dökün.", "Kapağı kapalı, kısık ateşte 15–18 dakika buğulayın.", "Maydanoz serpip servis edin."], minutes: 40, servings: 4, prepMinutes: 12, cookMinutes: 28, difficulty: "Orta", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_016", title: "Kabak musakka", category: "Sebze yemekleri", ingredients: ["4 kabak", "250 g kıyma", "1 soğan", "2 domates", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "Tuz, karabiber, pul biber (1 tatlı kaşığı tuz)"], steps: ["Kabakları kalın halkalar hâlinde doğrayın.", "Soğanı yağda yumuşatıp kıymayı ekleyin, suyunu çekene kadar kavurun.", "Salça ve küp domatesi ekleyip 5 dakika pişirin.", "Kabakları ekleyip karıştırın, baharatları ve sıcak suyu ilave edin.", "Kapağı kapalı, kısık ateşte kabaklar yumuşayana kadar 25 dakika pişirin.", "Yoğurtla servis edin."], minutes: 55, servings: 4, prepMinutes: 16, cookMinutes: 39, difficulty: "Orta", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_019", title: "Dalyan köfte", category: "Et yemekleri", ingredients: ["600 g kıyma", "1 soğan rendesi", "2 dilim bayat ekmek", "1 yumurta", "1 havuç", "Yarım su bardağı haşlanmış bezelye", "3 haşlanmış yumurta", "Tuz, karabiber, kimyon (1 tatlı kaşığı tuz)", "1 yemek kaşığı salça, 1 su bardağı su"], steps: ["Kıyma, soğan, ıslatılıp sıkılmış ekmek, çiğ yumurta ve baharatları yoğurun.", "Havucu küçük küp doğrayıp bezelyeyle birlikte haşlayın.", "Köfte harcını yağlı kağıt üzerinde 1,5 cm kalınlıkta dikdörtgen açın.", "Ortasına havuç, bezelye ve uç uca dizilmiş haşlanmış yumurtaları koyun.", "Kağıt yardımıyla rulo yapıp kenarlarını kapatın, fırın kabına alın.", "Salçalı suyu üzerine dökün, 180 °C fırında 45 dakika pişirin; dinlendirip dilimleyin."], minutes: 80, servings: 6, prepMinutes: 24, cookMinutes: 56, difficulty: "Orta", ovenCelsius: 180, tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_020", title: "Arnavut ciğeri", category: "Mezeler", ingredients: ["500 g dana ciğeri", "3 yemek kaşığı un", "1 tatlı kaşığı pul biber", "1 tatlı kaşığı kimyon", "Kızartmak için 3 su bardağı ayçiçek yağı", "Yanına: 1 kırmızı soğan, yarım demet maydanoz, 1 tatlı kaşığı sumak", "1 tatlı kaşığı tuz"], steps: ["Ciğerin zarını soyup 1,5 cm küpler hâlinde doğrayın, soğuk suda yıkayıp süzün.", "Soğanı piyazlık doğrayıp maydanoz ve sumakla karıştırın.", "Ciğeri un ve baharatla harmanlayıp fazla ununu eleyin.", "Kızgın yağda 3–4 dakika, dışı kızarıp içi pişene kadar kızartın.", "Tuzunu pişince serpin; soğan salatasıyla servis edin."], minutes: 30, servings: 4, prepMinutes: 9, cookMinutes: 21, difficulty: "Kolay", tips: ["Ciğeri tuzlayıp bekletmeyin; sertleşir."], serving: "Soğuk ya da oda sıcaklığında.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n11_021", title: "Hünkâr beğendi", category: "Et yemekleri", ingredients: ["600 g kuşbaşı kuzu eti", "1 soğan", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "Beğendi için: 4 patlıcan", "2 yemek kaşığı tereyağı", "2 yemek kaşığı un", "1,5 su bardağı süt", "Yarım su bardağı rendelenmiş kaşar", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Eti tereyağında suyunu çekene kadar kavurun, soğanı ekleyip 5 dakika çevirin.", "Salça ve rendelenmiş domatesi ekleyin; sıcak su ilave edip kapağı kapalı 1–1,5 saat et yumuşayana kadar pişirin.", "Patlıcanları közleyip kabuklarını soyun, limonlu suda bekletip ince kıyın.", "Tereyağında unu kavurun, sütü çırparak ekleyin; patlıcanı ve kaşarı katıp koyulaşana kadar karıştırın.", "Tabağa beğendiyi yayın, ortasına eti yerleştirip servis edin."], minutes: 120, servings: 4, prepMinutes: 36, cookMinutes: 84, difficulty: "Zor", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_022", title: "Testi kebabı", category: "Et yemekleri", ingredients: ["600 g kuşbaşı dana eti", "10 arpacık soğan", "6 diş sarımsak", "2 domates", "2 sivri biber", "1 yemek kaşığı biber salçası", "2 yemek kaşığı tereyağı", "Tuz, karabiber, kekik (1 tatlı kaşığı tuz)", "1 toprak testi; ağzını kapatmak için 1 avuç hamur ya da folyo"], steps: ["Testiyi en az 1 saat suda bekletin.", "Eti, soğanları, sarımsağı, doğranmış domates ve biberi, salça, tereyağı ve baharatlarla karıştırın.", "Harcı testiye doldurun; ağzını hamur ya da folyoyla sıkıca kapatın.", "Testiyi soğuk fırına koyup 220 °C'ye ayarlayın, 2,5 saat pişirin.", "Fırından çıkarıp ağzına yakın yerden dikkatle kırın, pilavla servis edin."], minutes: 180, servings: 4, prepMinutes: 40, cookMinutes: 140, difficulty: "Zor", ovenCelsius: 220, tips: ["Testiyi sıcak fırına koymayın; ani ısı farkı çatlatır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_023", title: "Su muhallebisi (gül sulu)", category: "Tatlılar", ingredients: ["4 su bardağı su", "Yarım su bardağı nişasta", "Yarım su bardağı şeker", "1 tatlı kaşığı gül suyu", "Üzeri için 1 yemek kaşığı pudra şekeri"], steps: ["Nişastayı soğuk suyun bir kısmında topak kalmayacak şekilde eritin.", "Kalan su ve şekeri tencereye alıp nişastayı ekleyin.", "Orta ateşte sürekli karıştırarak koyulaşıp şeffaflaşana kadar 10–12 dakika pişirin.", "Gül suyunu ekleyip ıslatılmış kaselere paylaştırın.", "Soğuyunca pudra şekeri serperek servis edin."], minutes: 25, servings: 6, prepMinutes: 8, cookMinutes: 17, difficulty: "Kolay", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Soğuk ya da oda sıcaklığında.", storage: "Buzdolabında kapalı kapta 3 gün."),
  GeneralRecipe(id: "n11_025", title: "Şalgam suyu (ev usulü)", category: "İçecekler", ingredients: ["2 mor havuç", "1 şalgam", "1 su bardağı bulgur", "3 litre su", "2 yemek kaşığı kaya tuzu", "1 tatlı kaşığı pul biber (isteğe bağlı)"], steps: ["Bulguru bez torbaya koyup 1 litre ılık suda 1 gün ekşimeye bırakın.", "Mor havuç ve şalgamı yıkayıp iri doğrayın, cam kavanoza koyun.", "Ekşimiş bulgur suyunu, kalan suyu ve tuzu kavanoza ekleyin.", "Ağzını tülbentle kapatıp serin yerde 5–7 gün, ekşi tadı oluşana kadar fermente edin.", "Süzüp buzdolabında saklayın; soğuk servis edin."], minutes: 40, servings: 10, prepMinutes: 12, cookMinutes: 28, difficulty: "Orta", tips: ["Kavanozu her gün kontrol edin; küf görülürse dökün."], serving: "Soğuk servis edin.", storage: "Buzdolabında kapalı şişede 1 hafta."),
  GeneralRecipe(id: "n11_026", title: "Ev bozası", category: "İçecekler", ingredients: ["1 su bardağı ince bulgur", "1 su bardağı pirinç", "4 litre su", "1,5 su bardağı şeker", "1 tatlı kaşığı kuru maya", "Üzeri için 1 tatlı kaşığı tarçın ve 3 yemek kaşığı leblebi"], steps: ["Bulgur ve pirinci yıkayıp 2 litre suyla 1 saat, iyice dağılana kadar pişirin.", "Blenderdan geçirip ince süzgeçten süzün; kalan suyu ekleyerek akışkan kıvama getirin.", "Ilıyınca mayayı ekleyip karıştırın; üzerini örtüp oda sıcaklığında 2 gün bekletin.", "Şekeri ekleyip karıştırın, buzdolabında 1 gün daha dinlendirin.", "Tarçın ve leblebiyle servis edin."], minutes: 90, servings: 8, prepMinutes: 27, cookMinutes: 63, difficulty: "Orta", tips: ["Fermente içecektir; küçük çocuklara ve gebelere ölçülü verilmeli, ekşimiş bozayı tüketmeyin."], serving: "Soğuk servis edin.", storage: "Buzdolabında kapalı şişede 1 hafta."),
  GeneralRecipe(id: "n11_027", title: "Mücendere", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı yeşil mercimek", "1 su bardağı pirinç", "2 soğan", "Yarım su bardağı zeytinyağı", "Tuz, kimyon (1 tatlı kaşığı tuz)"], steps: ["Mercimeği 3 su bardağı suda 15 dakika yarı yumuşayana kadar haşlayın.", "Yıkanmış pirinci, tuzu ve 1 su bardağı sıcak suyu ekleyip kısık ateşte suyunu çekene kadar pişirin.", "Soğanları piyazlık doğrayıp zeytinyağında koyu kahverengi olana kadar 15 dakika kavurun.", "Soğanın yarısını pilava karıştırın, kalanını üzerine koyun.", "Ilık ya da oda sıcaklığında yoğurtla servis edin."], minutes: 45, servings: 4, prepMinutes: 14, cookMinutes: 31, difficulty: "Orta", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_028", title: "Yuvalama çorbası", category: "Çorbalar", ingredients: ["500 g kuzu eti (kemikli)", "1 su bardağı haşlanmış nohut", "Yuvalama için: 200 g yağsız kıyma", "1 su bardağı pirinç unu", "1 tatlı kaşığı tuz", "1 kg süzme yoğurt", "1 yumurta", "1 yemek kaşığı un", "2 yemek kaşığı tereyağı", "1 yemek kaşığı kuru nane"], steps: ["Eti haşlayıp didikleyin, suyunu süzün.", "Kıyma, pirinç unu, tuz ve azar azar su ile yoğrulmuş harçtan nohut büyüklüğünde yuvarlaklar yapın.", "Yuvalamaları et suyunda 10 dakika pişirin; nohut ve eti ekleyin.", "Yoğurt, yumurta ve unu çırpıp birkaç kepçe sıcak suyla ılıştırın, tencereye ekleyin.", "Sürekli karıştırarak kaynayana kadar pişirin, tuzlayın.", "Tereyağında naneyi kızdırıp üzerine gezdirin."], minutes: 120, servings: 6, prepMinutes: 36, cookMinutes: 84, difficulty: "Zor", tips: ["Gaziantep bayram yemeğidir; yuvalamalar ne kadar küçük olursa o kadar makbuldür."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün; bir kez ısıtın."),
  GeneralRecipe(id: "n11_029", title: "Analı kızlı", category: "Çorbalar", ingredients: ["Ana köfte için: 200 g yağsız kıyma, 1 su bardağı ince bulgur, 1 tatlı kaşığı salça", "İç için: 150 g kıyma, 1 soğan, 2 yemek kaşığı ceviz", "Kızlar için: aynı hamurdan 1 su bardağı kadar ayrılır", "1 su bardağı haşlanmış nohut", "2 su bardağı yoğurt", "1 yumurta, 1 yemek kaşığı un", "2 yemek kaşığı tereyağı, kuru nane, tuz"], steps: ["Bulguru ıslatıp kıyma ve salçayla ele yapışmayan bir hamur olana kadar yoğurun.", "Soğanlı kıymayı kavurup cevizi ekleyerek iç harcı hazırlayın.", "Hamurdan ceviz büyüklüğünde parçaları oyup iç harçla doldurun (ana); kalan hamurdan iç koymadan küçük toplar yapın (kız).", "Tuzlu suda nohutla birlikte ana ve kızları 15 dakika pişirin.", "Yoğurt, yumurta ve unu çırpıp ılıştırarak ekleyin, kaynayana kadar karıştırın.", "Naneli tereyağı gezdirip servis edin."], minutes: 120, servings: 6, prepMinutes: 36, cookMinutes: 84, difficulty: "Zor", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün; bir kez ısıtın."),
  GeneralRecipe(id: "n11_030", title: "Keşkek", category: "Et yemekleri", ingredients: ["2 su bardağı aşurelik buğday (bir gece ıslatılmış)", "1 kg kemikli kuzu ya da tavuk", "3 yemek kaşığı tereyağı", "1 tatlı kaşığı pul biber", "1 tatlı kaşığı tuz"], steps: ["Buğdayı ıslatıldığı suyu dökerek yeni suyla 1 saat haşlayın.", "Eti ayrı tencerede köpüğünü alarak kemikten ayrılana kadar haşlayın, didikleyin.", "Buğdayı et suyuyla birlikte kısık ateşte 2 saat, buğday tamamen dağılana kadar pişirin.", "Eti ekleyip tahta kaşıkla sürekli dövün, koyu ve uzayan bir kıvam elde edin; tuzlayın.", "Tabağa alıp pul biberli kızdırılmış tereyağı gezdirin."], minutes: 300, servings: 8, prepMinutes: 40, cookMinutes: 260, difficulty: "Zor", tips: ["UNESCO somut olmayan kültürel miras listesindedir; düğün ve bayram yemeğidir."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_031", title: "Hingel", category: "Hamur işleri", ingredients: ["Hamur için: 2 su bardağı un", "1 yumurta", "Yarım su bardağı su", "1 tatlı kaşığı tuz", "İç için: 3 haşlanmış patates", "1 soğan", "Yarım demet maydanoz", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber", "Sos için: 1,5 su bardağı sarımsaklı yoğurt, 2 yemek kaşığı tereyağı, 1 soğan, 1 tatlı kaşığı pul biber"], steps: ["Hamuru yoğurup 30 dakika dinlendirin.", "Patatesleri ezip kavrulmuş soğan, maydanoz ve baharatla karıştırın.", "Hamuru ince açıp bardakla yuvarlaklar kesin.", "Her yuvarlağa iç koyup yarım ay şeklinde katlayın, kenarlarını bastırın.", "Kaynar tuzlu suda yüzeye çıkınca 3 dakika daha haşlayıp süzün.", "Sarımsaklı yoğurt ve soğanlı, pul biberli tereyağıyla servis edin."], minutes: 90, servings: 4, prepMinutes: 27, cookMinutes: 63, difficulty: "Orta", tips: ["Kafkas ve Doğu Anadolu mutfağının patatesli mantısıdır."], serving: "Sıcak ya da ılık.", storage: "Kapalı kapta 2 gün; dondurucuda 1 ay."),
  GeneralRecipe(id: "n11_032", title: "Kuru köfte", category: "Et yemekleri", ingredients: ["500 g kıyma", "1 soğan rendesi", "2 dilim bayat ekmek içi", "1 yumurta", "Yarım demet maydanoz", "1 tatlı kaşığı kimyon", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber", "Kızartmak için 1 su bardağı ayçiçek yağı", "Bulamak için 3 yemek kaşığı un"], steps: ["Ekmeği ıslatıp sıkın; tüm malzemeyi 5 dakika iyice yoğurun.", "Harcı 30 dakika buzdolabında dinlendirin.", "Elinizi ıslatıp ceviz büyüklüğünde, yassı ve oval köfteler yapın.", "Hafifçe una bulayıp kızgın yağda iki yüzü kızarana kadar 6–8 dakika kızartın.", "Kağıt havluya alıp piyaz ya da patatesle servis edin."], minutes: 40, servings: 4, prepMinutes: 12, cookMinutes: 28, difficulty: "Orta", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_033", title: "Tavuk suyu çorbası", category: "Çorbalar", ingredients: ["2 tavuk but (kemikli)", "1 havuç", "Yarım su bardağı şehriye ya da pirinç", "2 yemek kaşığı tereyağı", "1 yemek kaşığı un", "1 yumurta sarısı", "Yarım limon suyu", "1 tatlı kaşığı tuz, yarım çay kaşığı karabiber"], steps: ["Tavukları 2 litre suda köpüğünü alarak 45 dakika haşlayın; didikleyip suyunu süzün.", "Tereyağında unu kavurun, tavuk suyunu ekleyin.", "Rendelenmiş havuç ve şehriyeyi ekleyip 10 dakika pişirin.", "Tavuk etini ekleyin, tuz ve karabiberle tatlandırın.", "Yumurta sarısı ve limonu ılıştırıp ekleyin, kaynatmadan ocaktan alın."], minutes: 70, servings: 6, prepMinutes: 21, cookMinutes: 49, difficulty: "Orta", tips: ["Hastalık dönemlerinde sıvı alımını desteklemek için iyi bir seçenektir."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün; bir kez ısıtın."),
  GeneralRecipe(id: "n11_034", title: "Karalahana çorbası", category: "Çorbalar", ingredients: ["1 demet karalahana", "1 su bardağı haşlanmış barbunya ya da kuru fasulye", "1 soğan", "Yarım su bardağı mısır unu", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "Tuz, pul biber (1 tatlı kaşığı tuz)"], steps: ["Karalahanayı yıkayıp saplarını ayıklayın, ince kıyın.", "Soğanı tereyağında kavurup salçayı ekleyin.", "Karalahanayı ve 6 su bardağı sıcak suyu ekleyip 25 dakika pişirin.", "Fasulyeyi ekleyin; mısır ununu azar azar serperek karıştırın.", "10 dakika daha pişirip tuz ve pul biberle tatlandırın."], minutes: 60, servings: 6, prepMinutes: 18, cookMinutes: 42, difficulty: "Orta", tips: ["Karadeniz mutfağına özgüdür; mısır ekmeğiyle servis edilir."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün; bir kez ısıtın."),
  GeneralRecipe(id: "n11_035", title: "Hamsili ekmek", category: "Balık ve deniz ürünleri", ingredients: ["500 g hamsi (ayıklanmış)", "2 su bardağı mısır unu", "1 soğan", "1 demet pazı ya da karalahana", "Yarım demet maydanoz ve dereotu", "Yarım su bardağı sıcak su", "3 yemek kaşığı zeytinyağı", "Tuz, pul biber (1 tatlı kaşığı tuz)"], steps: ["Hamsileri iyice yıkayıp ince doğrayın.", "Soğanı ve yeşillikleri ince kıyın.", "Mısır unu, sebzeler, hamsi, zeytinyağı, tuz ve sıcak suyu yoğurarak yumuşak bir harç yapın.", "Yağlanmış tepsiye 2 cm kalınlıkta yayın.", "190 °C fırında 40–45 dakika, üzeri kızarana kadar pişirin."], minutes: 60, servings: 6, prepMinutes: 18, cookMinutes: 42, difficulty: "Orta", ovenCelsius: 190, tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_036", title: "Kelle paça çorbası", category: "Çorbalar", ingredients: ["2 adet temizlenmiş kuzu paça", "1 kuzu kellesi (temizlenmiş)", "2 yemek kaşığı un", "2 yemek kaşığı tereyağı", "1 yumurta sarısı", "1 limon", "Sunum için 3 diş sarımsak ve yarım su bardağı sirke, 1 tatlı kaşığı tuz"], steps: ["Paça ve kelleyi soğuk suda yıkayıp bol suda köpüğünü alarak 3–4 saat (düdüklüde 1,5 saat) haşlayın.", "Etleri kemikten ayırıp didikleyin, suyunu süzün.", "Tereyağında unu kavurun, et suyunu ekleyerek pürüzsüz karıştırın.", "Etleri ekleyip 10 dakika kaynatın, tuzlayın.", "Yumurta sarısı ve limonla terbiyeleyin; sirkeli sarımsakla servis edin."], minutes: 240, servings: 6, prepMinutes: 40, cookMinutes: 200, difficulty: "Zor", tips: ["Ürünü güvenilir kasaptan, temizlenmiş olarak alın."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün; bir kez ısıtın."),
  GeneralRecipe(id: "n11_037", title: "Ev usulü suşi rulo (pişmiş malzemeyle)", category: "Dünya mutfağı", ingredients: ["1,5 su bardağı suşi pirinci", "2 yemek kaşığı pirinç sirkesi", "1 yemek kaşığı şeker", "1 tatlı kaşığı tuz", "4 yaprak nori", "1 salatalık", "1 havuç", "1 avokado", "150 g haşlanmış karides ya da füme somon", "4 yemek kaşığı soya sosu"], steps: ["Pirinci su berraklaşana kadar yıkayın; 1,8 su bardağı suyla kaynatıp kısık ateşte 12 dakika pişirin, 10 dakika demlendirin.", "Sirke, şeker ve tuzu eritip sıcak pirince karıştırın, oda sıcaklığına soğutun.", "Salatalık, havuç ve avokadoyu ince çubuklar hâlinde kesin.", "Bambu matın üzerine noriyi koyun, ıslak elle pirinci üst kenarda 2 cm boşluk bırakarak ince yayın.", "Sebzeleri ve karidesi alt kenara dizip matla sıkıca sarın.", "Islak bıçakla 8 parçaya kesip soya sosuyla servis edin."], minutes: 60, servings: 4, prepMinutes: 18, cookMinutes: 42, difficulty: "Orta", tips: ["Gebelikte çiğ balık önerilmediği için pişmiş karides ya da füme ürün kullanılmıştır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_038", title: "Tavuklu tako", category: "Dünya mutfağı", ingredients: ["8 küçük mısır ya da buğday tortilla", "400 g tavuk göğsü", "1 tatlı kaşığı kimyon", "1 tatlı kaşığı toz kırmızı biber", "1 kırmızı soğan", "2 domates", "1 avokado", "1 limon", "Yarım demet kişniş ya da maydanoz", "4 yemek kaşığı yoğurt", "1 tatlı kaşığı tuz"], steps: ["Tavuğu şerit doğrayıp baharat ve tuzla harmanlayın, az yağda 8 dakika pişirin.", "Domates, soğan ve kişnişi ince doğrayıp limon ve tuzla salsa hazırlayın.", "Avokadoyu ezip limon ve tuzla karıştırın.", "Tortillaları kuru tavada her yüzünü 30 saniye ısıtın.", "Tortillaya tavuk, salsa, avokado ve bir kaşık yoğurt koyup katlayarak servis edin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Orta", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_039", title: "Tavuklu ramen", category: "Dünya mutfağı", ingredients: ["2 porsiyon ramen erişte", "4 su bardağı tavuk suyu", "1 tavuk göğsü", "2 yumurta", "2 yemek kaşığı soya sosu", "1 tatlı kaşığı rendelenmiş zencefil", "2 diş sarımsak", "1 avuç ıspanak", "2 dal taze soğan", "1 tatlı kaşığı susam yağı"], steps: ["Yumurtaları kaynar suda 7 dakika haşlayıp soğuk suya alın, soyun.", "Tavuk suyunu sarımsak, zencefil ve soya sosuyla 10 dakika kaynatın.", "Tavuğu suda 15 dakika pişirip çıkarın ve dilimleyin.", "Erişteyi paket süresi kadar ayrı haşlayıp süzün.", "Ispanağı sıcak suya ekleyip 1 dakika pişirin.", "Kaselere erişte, tavuk, ıspanak koyup sıcak suyu dökün; yarım yumurta, taze soğan ve susam yağıyla servis edin."], minutes: 50, servings: 2, prepMinutes: 15, cookMinutes: 35, difficulty: "Orta", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n11_041", title: "Kahvaltılık poğaça", category: "Hamur işleri", ingredients: ["1 su bardağı ılık süt", "Yarım su bardağı sıvı yağ", "1 yumurta (sarısı üzerine)", "1 paket kuru maya", "1 tatlı kaşığı şeker", "1 tatlı kaşığı tuz", "4 su bardağı un", "İç için: 200 g beyaz peynir, yarım demet maydanoz"], steps: ["Süt, yağ, yumurta akı, maya, şeker ve tuzu karıştırın; unu azar azar ekleyerek yumuşak bir hamur yoğurun.", "Hamuru 40 dakika mayalandırın.", "Ceviz büyüklüğünde parçalar koparıp elinizde açın, peynirli harçtan koyup kapatın.", "Tepsiye dizip üzerine yumurta sarısı sürün, 15 dakika daha bekletin.", "190 °C fırında 25 dakika, üzeri kızarana kadar pişirin."], minutes: 90, servings: 12, prepMinutes: 27, cookMinutes: 63, difficulty: "Orta", ovenCelsius: 190, tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak ya da ılık.", storage: "Kapalı kapta 2 gün; dondurucuda 1 ay."),
  GeneralRecipe(id: "n11_055", title: "Lokma tatlısı", category: "Tatlılar", ingredients: ["2 su bardağı un", "1 paket kuru maya", "1 tatlı kaşığı şeker", "1 çay kaşığı tuz", "1,5 su bardağı ılık su", "Şerbet için: 2 su bardağı şeker, 2 su bardağı su, birkaç damla limon", "Kızartmak için 3 su bardağı ayçiçek yağı"], steps: ["Şerbeti 10 dakika kaynatıp limonu ekleyin, soğutun.", "Un, maya, şeker, tuz ve suyu çırparak akışkan bir hamur yapın; 45 dakika kabarmaya bırakın.", "Hamuru avucunuzdan sıkarak ıslak kaşıkla kesin, kızgın yağa bırakın.", "Altın rengi olana kadar çevirerek 3–4 dakika kızartın.", "Kızaran lokmaları soğuk şerbete atıp 1 dakika bekletip çıkarın."], minutes: 75, servings: 8, prepMinutes: 22, cookMinutes: 53, difficulty: "Orta", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Soğuk ya da oda sıcaklığında.", storage: "Buzdolabında kapalı kapta 3 gün."),
  GeneralRecipe(id: "n11_061", title: "Dana tantuni (Mersin usulü)", category: "Et yemekleri", ingredients: ["500 g dana but (çok ince şerit doğranmış)", "2 yemek kaşığı pamuk yağı", "1 tatlı kaşığı pul biber", "1 tatlı kaşığı tuz", "4 lavaş", "Yanına: 2 domates, 1 soğan, maydanoz, sumak, limon"], steps: ["Eti az tuzlu suda 10 dakika haşlayıp süzün.", "Geniş tavada yağı kızdırıp eti ekleyin, pul biber ve az haşlama suyuyla 10 dakika soteleyin.", "Domates, soğan ve maydanozu ince kıyıp sumakla karıştırın.", "Lavaşı tavadaki yağa bastırıp ısıtın; et ve salatayı koyup sarın.", "Limonla servis edin."], minutes: 40, servings: 4, prepMinutes: 12, cookMinutes: 28, difficulty: "Orta", tips: ["Malzemeleri önceden hazırlamak pişirmeyi kolaylaştırır."], serving: "Sıcak servis edin.", storage: "Buzdolabında kapalı kapta 2 gün."),
  GeneralRecipe(id: "n12_001", title: "Kalburabastı", category: "Tatlılar", ingredients: ["1 su bardağı sıvı yağ", "1 su bardağı yoğurt", "1 yumurta", "1 paket kabartma tozu", "4 su bardağı un", "1 su bardağı ceviz içi", "Şerbet: 3 su bardağı şeker, 3 su bardağı su, yarım limon"], steps: ["Şerbeti 15 dakika kaynatıp limon ekleyin ve soğutun.", "Yağ, yoğurt, yumurta ve kabartma tozunu karıştırıp unu azar azar ekleyerek yumuşak bir hamur yoğurun.", "Ceviz büyüklüğünde parçaları açıp içine ceviz koyun, oval şekil verin.", "Kalbur ya da rende üzerine bastırarak desen verin, tepsiye dizin.", "180 °C fırında 30 dakika kızarana kadar pişirin.", "Sıcak tatlıya soğuk şerbeti dökün."], minutes: 60, servings: 12, prepMinutes: 30, cookMinutes: 30, difficulty: "Orta", ovenCelsius: 180, tips: ["Desen şerbetin daha iyi işlemesini sağlar."], serving: "Oda sıcaklığında.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n12_002", title: "Saray sarması", category: "Tatlılar", ingredients: ["10 yaprak baklavalık yufka", "200 g tereyağı", "2 su bardağı iri çekilmiş ceviz", "Şerbet: 2,5 su bardağı şeker, 2 su bardağı su, yarım limon"], steps: ["Şerbeti kaynatıp soğutun.", "İki yufkanın arasına tereyağı sürüp üst üste koyun, cevizi serpin.", "Merdane üzerine sarıp iki yandan büzerek merdaneyi çekin.", "Büzgülü ruloları 4 cm parçalara kesip tepsiye dizin, eritilmiş tereyağı gezdirin.", "180 °C fırında 35 dakika pişirin.", "Sıcakken soğuk şerbeti dökün."], minutes: 75, servings: 10, prepMinutes: 40, cookMinutes: 35, difficulty: "Zor", ovenCelsius: 180, tips: ["Büzme işlemi tatlının çıtır katmanlarını oluşturur."], serving: "Oda sıcaklığında.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n12_003", title: "Kadayıf dolması", category: "Tatlılar", ingredients: ["250 g tel kadayıf", "150 g tereyağı", "1 su bardağı ceviz", "Şerbet: 2 su bardağı şeker, 2 su bardağı su, yarım limon"], steps: ["Şerbeti hazırlayıp soğutun.", "Kadayıfı eritilmiş tereyağıyla harmanlayın.", "Bir tutam kadayıfı avucunuza yayıp ortasına ceviz koyun ve rulo yapın.", "Tepsiye sıkıca dizin.", "180 °C fırında 30 dakika kızarana kadar pişirin.", "Sıcakken soğuk şerbeti dökün."], minutes: 60, servings: 10, prepMinutes: 30, cookMinutes: 30, difficulty: "Orta", ovenCelsius: 180, tips: ["Kadayıf kurursa kırılır; çalışırken üzerini örtün."], serving: "Oda sıcaklığında.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n12_004", title: "Katmer (Antep usulü)", category: "Tatlılar", ingredients: ["1 yufkalık hamur (250 g un, su, tuz)", "3 yemek kaşığı toz Antep fıstığı", "3 yemek kaşığı kaymak", "2 yemek kaşığı toz şeker", "2 yemek kaşığı tereyağı"], steps: ["Hamuru yoğurup 20 dakika dinlendirin.", "Tereyağı sürerek kâğıt inceliğinde açın.", "Ortaya kaymak, fıstık ve şeker koyup dört taraftan zarf gibi kapatın.", "Önceden ısıtılmış 220 °C fırında ya da sacda her yüzü 3–4 dakika pişirin.", "Sıcak dilimleyip servis edin."], minutes: 28, servings: 2, prepMinutes: 20, cookMinutes: 8, difficulty: "Orta", ovenCelsius: 220, tips: ["Antep’te sabah kahvaltısında yenir."], serving: "Sıcak, hemen.", storage: "Aynı gün."),
  GeneralRecipe(id: "n12_005", title: "Lor tatlısı", category: "Tatlılar", ingredients: ["500 g lor peyniri", "3 yumurta", "1 su bardağı şeker", "1 su bardağı irmik", "1 paket kabartma tozu", "1 limon kabuğu rendesi", "Şerbet: 2 su bardağı şeker, 2,5 su bardağı su"], steps: ["Şerbeti kaynatıp soğutun.", "Lor, yumurta ve şekeri pürüzsüz olana kadar çırpın.", "İrmik, kabartma tozu ve limon kabuğunu ekleyin.", "Yağlanmış kalıpta 180 °C fırında 35 dakika pişirin.", "Sıcakken dilimleyip soğuk şerbeti dökün."], minutes: 50, servings: 8, prepMinutes: 15, cookMinutes: 35, difficulty: "Orta", ovenCelsius: 180, tips: ["Şerbeti hafif tutmak lor tadını öne çıkarır."], serving: "Oda sıcaklığında.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n12_006", title: "Hurmalı tatlı", category: "Tatlılar", ingredients: ["125 g tereyağı", "1 su bardağı sıvı yağ", "1 yumurta", "1 su bardağı pudra şekeri", "1 paket kabartma tozu", "3,5 su bardağı un", "Şerbet: 3 su bardağı şeker, 3 su bardağı su, yarım limon", "2 yemek kaşığı toz fıstık"], steps: ["Şerbeti hazırlayıp soğutun.", "Yağlar, yumurta ve şekeri çırpın; un ve kabartma tozunu ekleyip yumuşak hamur yoğurun.", "Ceviz büyüklüğünde parçaları rendenin üzerine bastırıp hurma şekli verin.", "180 °C fırında 30 dakika pişirin.", "Sıcak tatlıya soğuk şerbeti dökün, fıstıkla süsleyin."], minutes: 50, servings: 12, prepMinutes: 20, cookMinutes: 30, difficulty: "Orta", ovenCelsius: 180, tips: ["Şekli rendeyle vermek gelenekseldir."], serving: "Oda sıcaklığında.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n12_007", title: "Bülbül yuvası", category: "Tatlılar", ingredients: ["10 yaprak baklavalık yufka", "200 g tereyağı", "1 su bardağı toz Antep fıstığı", "Şerbet: 2 su bardağı şeker, 2 su bardağı su, yarım limon"], steps: ["Şerbeti hazırlayıp soğutun.", "Yufkaya tereyağı sürüp ince merdaneye sarın, büzerek çekin.", "Büzülmüş yufkayı yuvarlak yuva şeklinde kıvırın, tepsiye dizin.", "Ortalarına fıstık koyun, tereyağı gezdirin.", "180 °C fırında 30 dakika pişirin.", "Soğuk şerbeti dökün."], minutes: 60, servings: 10, prepMinutes: 30, cookMinutes: 30, difficulty: "Zor", ovenCelsius: 180, tips: ["Yuvaların ortası fıstıkla dolu olmalı."], serving: "Oda sıcaklığında.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n12_008", title: "Ekmek kadayıfı (kaymaklı)", category: "Tatlılar", ingredients: ["1 adet hazır ekmek kadayıfı", "3 su bardağı şeker", "3 su bardağı su", "Yarım limon", "200 g kaymak", "2 yemek kaşığı toz fıstık"], steps: ["Kadayıfı tepsiye koyup üzerine sıcak su döküp 5 dakika yumuşatın, suyunu süzün.", "Şeker ve suyu kaynatıp limonu ekleyin.", "Sıcak şerbeti kadayıfın üzerine dökün.", "Kısık ateşte ya da 180 °C fırında şerbeti çekene kadar 20 dakika pişirin.", "Soğuyunca kaymak ve fıstıkla servis edin."], minutes: 40, servings: 8, prepMinutes: 10, cookMinutes: 30, difficulty: "Orta", tips: ["Kaymak yerine dövme dondurma da kullanılır."], serving: "Oda sıcaklığında.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n12_009", title: "Pestil ve cevizli sucuk (ev usulü)", category: "Tatlılar", ingredients: ["2 litre üzüm suyu ya da 1 litre pekmez ve 1 litre su", "1 su bardağı nişasta", "1 su bardağı un", "2 su bardağı ceviz içi", "4 adet 50 cm kalın pamuk ip"], steps: ["Cevizleri ipe iğneyle dizin.", "Üzüm suyunun bir kısmında un ve nişastayı topaksız eritin.", "Kalan üzüm suyunu kaynatıp karışımı ekleyin, koyulaşıp bulamaç olana kadar karıştırın.", "Ceviz dizilerini bulamaca batırıp çıkarın, 10 dakika kurutup 3–4 kez tekrarlayın.", "Gölgede havadar yerde 1 hafta kurutun.", "Kalan bulamacı tepsiye ince yayıp kurutarak pestil yapın."], minutes: 80, servings: 10, prepMinutes: 40, cookMinutes: 40, difficulty: "Zor", tips: ["Kurutma havadar ve tozsuz yerde yapılmalı."], serving: "Dilimleyerek.", storage: "Serin yerde kapalı kapta 3 ay."),
  GeneralRecipe(id: "n12_010", title: "İnegöl köfte", category: "Et yemekleri", ingredients: ["500 g dana kıyma (az yağlı)", "1 küçük soğan rendesi", "1 tatlı kaşığı karbonat", "1 tatlı kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Kıyma, suyu sıkılmış soğan, karbonat, tuz ve karabiberi 10 dakika yoğurun.", "Buzdolabında en az 2 saat dinlendirin.", "Parmak kalınlığında, 6 cm uzunluğunda köfteler yapın.", "Kızgın ızgarada her yüzünü 4 dakika pişirin.", "Piyaz ve közlenmiş biberle servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Orta", tips: ["Ekmek eklenmez; yoğurma ve dinlendirme köfteye kıvamını verir."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_011", title: "Tekirdağ köftesi", category: "Et yemekleri", ingredients: ["500 g kıyma", "1 su bardağı galeta unu", "1 soğan rendesi", "1 tatlı kaşığı kimyon", "1 tatlı kaşığı tuz", "Yarım çay kaşığı karabiber"], steps: ["Tüm malzemeyi 10 dakika yoğurun.", "Harcı 1 saat buzdolabında bekletin.", "Ceviz büyüklüğünde yassı ve dikdörtgen köfteler yapın.", "Izgarada her yüzünü 4–5 dakika pişirin.", "Piyaz ve közlenmiş domatesle servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Orta", tips: ["Ince ve düzgün şekil eşit pişmesini sağlar."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_012", title: "Akçaabat köftesi", category: "Et yemekleri", ingredients: ["500 g kıyma", "2 dilim bayat ekmek", "2 diş sarımsak", "1 tatlı kaşığı kimyon", "1 tatlı kaşığı tuz", "1 çay kaşığı karabiber"], steps: ["Ekmeği ıslatıp sıkın.", "Kıyma, ekmek, ezilmiş sarımsak ve baharatları yoğurun.", "Kalın ve oval köfteler yapın.", "Izgarada ya da döküm tavada her yüzünü 5 dakika pişirin.", "Közlenmiş biber ve pilavla servis edin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Orta", tips: ["Sarımsak Trabzon usulünün belirgin tadıdır."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_014", title: "Hasanpaşa köfte", category: "Et yemekleri", ingredients: ["500 g kıyma", "1 soğan rendesi", "1 yumurta", "1 dilim bayat ekmek", "4 patates", "1 su bardağı süt", "1 yemek kaşığı tereyağı", "1 su bardağı rendelenmiş kaşar", "1 yemek kaşığı salça", "1 tatlı kaşığı tuz, 1 çay kaşığı karabiber"], steps: ["Kıyma, soğan, yumurta, ekmek ve baharatla köfte harcı yapıp yuvarlak köfteler hazırlayın, ortalarını çukurlaştırın.", "Patatesleri haşlayıp süt ve tereyağıyla püre yapın.", "Köftelerin çukuruna püre koyup fırın kabına dizin.", "Salçayı 1 su bardağı sıcak suyla açıp kenarlardan dökün.", "Üzerine kaşar serpip 190 °C fırında 35 dakika pişirin."], minutes: 65, servings: 4, prepMinutes: 25, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 190, tips: ["Püre koyu olursa fırında akmaz."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_015", title: "Beyti kebabı", category: "Et yemekleri", ingredients: ["500 g kuzu kıyma", "1 diş sarımsak", "1 tatlı kaşığı pul biber", "1 tatlı kaşığı tuz", "4 lavaş", "1 su bardağı yoğurt", "3 yemek kaşığı tereyağı", "1 yemek kaşığı salça"], steps: ["Kıymayı sarımsak, pul biber ve tuzla yoğurup şişe ya da uzun köfte şeklinde hazırlayın.", "Izgarada çevirerek 10 dakika pişirin.", "Lavaşlara sarıp 3 cm dilimleyin.", "Salçayı tereyağında eritip dilimlerin üzerine gezdirin.", "Yoğurtla servis edin."], minutes: 40, servings: 4, prepMinutes: 20, cookMinutes: 20, difficulty: "Orta", tips: ["Lavaşı sıkı sarmak dilimlerin dağılmasını önler."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_016", title: "Urfa kebabı", category: "Et yemekleri", ingredients: ["600 g kuzu kıyma (yağlı)", "1 tatlı kaşığı tuz", "4 yassı şiş", "Yanına: 4 közlenmiş domates, 4 sivri biber, 4 lavaş, 1 soğan, isot"], steps: ["Kıymayı tuzla 10 dakika yoğurun; acı eklenmez.", "Yassı şişlere bastırarak geçirin.", "Mangalda çevirerek 8–10 dakika pişirin.", "Domates ve biberleri de közleyin.", "Lavaş, sumaklı soğan ve isotla servis edin."], minutes: 35, servings: 4, prepMinutes: 20, cookMinutes: 15, difficulty: "Orta", tips: ["Adana’dan farkı acısız olmasıdır."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_017", title: "Elbasan tava", category: "Et yemekleri", ingredients: ["500 g kuşbaşı kuzu eti", "3 yemek kaşığı tereyağı", "Terbiye: 2 su bardağı yoğurt, 2 yumurta, 2 yemek kaşığı un", "1 tatlı kaşığı tuz, 1 çay kaşığı karabiber, 1 tatlı kaşığı kekik"], steps: ["Eti tereyağında kavurup az suyla 1 saat yumuşayana kadar pişirin.", "Eti suyuyla fırın kabına alın.", "Yoğurt, yumurta, un ve tuzu çırpın.", "Karışımı etin üzerine dökün.", "200 °C fırında 25 dakika, üzeri kızarana kadar pişirip kekik serpin."], minutes: 110, servings: 4, prepMinutes: 20, cookMinutes: 90, difficulty: "Orta", ovenCelsius: 200, tips: ["Arnavut mutfağından gelen bir Osmanlı yemeğidir."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_018", title: "Sultan kebabı", category: "Et yemekleri", ingredients: ["400 g kuşbaşı dana eti", "1 soğan", "2 sivri biber", "1 domates", "1 yemek kaşığı salça", "4 yaprak baklavalık yufka", "1 yumurta sarısı", "100 g kaşar", "1 tatlı kaşığı tuz, 1 çay kaşığı karabiber"], steps: ["Eti kendi suyunda pişirip soğan, biber, domates ve salçayla kavurun.", "Harcı soğutun.", "Yufkaları bölüp içine harç ve kaşar koyarak bohça yapın.", "Üzerine yumurta sarısı sürün.", "200 °C fırında 25 dakika kızarana kadar pişirin."], minutes: 70, servings: 4, prepMinutes: 30, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 200, tips: ["Harç soğumazsa yufka yumuşar."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_019", title: "Kuru dolma (patlıcan ve biber)", category: "Sebze yemekleri", ingredients: ["20 kuru patlıcan ve kuru biber", "300 g kıyma", "1 su bardağı pirinç", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz, 1 tatlı kaşığı pul biber, 1 tatlı kaşığı nane"], steps: ["Kuru sebzeleri kaynar suda 5 dakika haşlayıp yumuşatın.", "Kıyma, pirinç, rendelenmiş domates, salça, yağ ve baharatı yoğurun.", "Sebzeleri harçla doldurup tencereye dizin.", "Üzerine ters tabak koyup sıcak su ekleyin.", "Kısık ateşte 50–60 dakika pişirin."], minutes: 100, servings: 6, prepMinutes: 40, cookMinutes: 60, difficulty: "Orta", tips: ["Gaziantep ve Doğu mutfağında kışın yapılır."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_020", title: "Zeytinyağlı taze bakla", category: "Sebze yemekleri", ingredients: ["1 kg taze bakla", "1 soğan", "3 dal taze soğan", "Yarım demet dereotu", "Yarım su bardağı zeytinyağı", "1 tatlı kaşığı şeker", "1 yemek kaşığı un", "1 limon", "1 tatlı kaşığı tuz"], steps: ["Baklaların uçlarını ve kenar liflerini temizleyip 3 cm doğrayın, limonlu unlu suda bekletin.", "Soğanları zeytinyağında yumuşatın.", "Baklaları, şekeri, tuzu ve 1 su bardağı sıcak suyu ekleyin.", "Kısık ateşte 40 dakika pişirin.", "Dereotu serpip soğuk, yoğurtla servis edin."], minutes: 55, servings: 4, prepMinutes: 15, cookMinutes: 40, difficulty: "Orta", tips: ["Unlu limonlu su baklanın kararmasını önler."], serving: "Soğuk, yoğurtla.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n12_021", title: "Pazı sarması", category: "Sebze yemekleri", ingredients: ["1 demet pazı", "1 su bardağı pirinç", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı salça", "Yarım demet maydanoz", "1 tatlı kaşığı tuz, 1 tatlı kaşığı nane, 1 çay kaşığı pul biber"], steps: ["Pazı yapraklarını kaynar suda 1 dakika haşlayıp saplarını ayırın.", "Soğanı kavurup pirinç, salça, maydanoz ve baharatla harç hazırlayın.", "Yaprakları harçla sarın.", "Tencereye dizip sıcak su ekleyin, üzerine tabak kapatın.", "Kısık ateşte 45 dakika pişirin."], minutes: 85, servings: 6, prepMinutes: 40, cookMinutes: 45, difficulty: "Orta", tips: ["Karadeniz’de pazı sarması kıymalı da yapılır."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_022", title: "Ekşili lahana (Karadeniz usulü)", category: "Sebze yemekleri", ingredients: ["1 kg lahana turşusu", "1 soğan", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı pul biber", "Yarım su bardağı pirinç"], steps: ["Turşuyu doğrayıp tuzu fazlaysa yıkayın.", "Soğanı tereyağında kavurun, pul biberi ekleyin.", "Turşu ve pirinci ekleyip 1 su bardağı su ilave edin.", "Kısık ateşte 40 dakika pişirin.", "Mısır ekmeğiyle servis edin."], minutes: 55, servings: 4, prepMinutes: 15, cookMinutes: 40, difficulty: "Orta", tips: ["Turşu tuzlu olduğu için tuz eklemeyin."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_023", title: "Piliç güveç", category: "Tavuk yemekleri", ingredients: ["4 tavuk but", "2 patates", "2 biber", "2 domates", "8 arpacık soğan", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz, 1 tatlı kaşığı kekik"], steps: ["Sebzeleri iri doğrayın.", "Güvece tavukları ve sebzeleri dizin.", "Salçayı tereyağı ve 1 su bardağı sıcak suyla açıp dökün.", "Baharatları serpip güvecin ağzını kapatın.", "Soğuk fırına koyup 200 °C’de 60 dakika pişirin."], minutes: 80, servings: 4, prepMinutes: 20, cookMinutes: 60, difficulty: "Orta", ovenCelsius: 200, tips: ["Toprak güveç soğuk fırına konur."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_024", title: "Sac kavurma", category: "Et yemekleri", ingredients: ["600 g kuşbaşı kuzu eti", "2 sivri biber", "2 domates", "1 soğan", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı tuz, 1 tatlı kaşığı pul biber, 1 çay kaşığı kekik"], steps: ["Sacı ya da geniş döküm tavayı iyice ısıtın.", "Eti yüksek ateşte suyunu salıp çekene kadar kavurun.", "Tereyağı ve doğranmış soğanı ekleyin.", "Biber ve domatesi ekleyip 5 dakika daha çevirin.", "Baharatlarla tatlandırıp lavaşla servis edin."], minutes: 40, servings: 4, prepMinutes: 20, cookMinutes: 20, difficulty: "Orta", tips: ["Az miktarda pişirmek etin haşlanmasını önler."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_025", title: "Kuzu haşlama", category: "Et yemekleri", ingredients: ["1 kg kemikli kuzu eti", "2 havuç", "3 patates", "1 soğan", "1 kereviz sapı", "1 limon", "1 tatlı kaşığı tuz, 5 tane karabiber"], steps: ["Eti soğuk suya koyup kaynatın, köpüğünü alın.", "Soğan, karabiber ve kerevizi ekleyip kısık ateşte 1,5 saat pişirin.", "İri doğranmış havuç ve patatesi ekleyin.", "Sebzeler yumuşayana kadar 25 dakika daha pişirin, tuzlayın.", "Limonla servis edin."], minutes: 135, servings: 4, prepMinutes: 15, cookMinutes: 120, difficulty: "Orta", tips: ["Haşlama suyu çorbalarda kullanılabilir."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_026", title: "Ciğer sarma", category: "Et yemekleri", ingredients: ["400 g kuzu ciğeri", "1 kuzu kuyruk yağı zarı", "1 soğan", "1 tatlı kaşığı tuz, 1 tatlı kaşığı kimyon, 1 çay kaşığı karabiber"], steps: ["Ciğeri küçük küp doğrayın, ince doğranmış soğan ve baharatla karıştırın.", "Zarı ılık suda yumuşatıp kare parçalara kesin.", "Harcı zara sarıp kürdanla tutturun.", "Izgarada ya da 200 °C fırında 20–25 dakika pişirin.", "Sumaklı soğanla servis edin."], minutes: 50, servings: 4, prepMinutes: 25, cookMinutes: 25, difficulty: "Orta", ovenCelsius: 200, tips: ["Ciğer iyice pişmeli; içi pembe kalmamalı."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_027", title: "Hamsi buğulama", category: "Balık ve deniz ürünleri", ingredients: ["500 g hamsi", "2 domates", "1 soğan", "2 sivri biber", "1 limon", "3 yemek kaşığı zeytinyağı", "1 tatlı kaşığı tuz"], steps: ["Hamsilerin başını alıp ayıklayın, yıkayın.", "Tencerenin tabanına halka soğan ve biber dizin.", "Hamsileri üzerine yan yana dizin, domates ve limon dilimleriyle kapatın.", "Zeytinyağı ve tuzu ekleyip kapağı kapalı kısık ateşte 15 dakika buğulayın.", "Ilık servis edin."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Orta", tips: ["Su eklemeye gerek yoktur; sebzeler su salar."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_028", title: "Levrek ızgara", category: "Balık ve deniz ürünleri", ingredients: ["2 bütün levrek (temizlenmiş)", "2 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı tuz", "Yanına roka ve kırmızı soğan (1 demet, 1 adet)"], steps: ["Balıkların üzerine çapraz çizikler atın.", "Zeytinyağı ve tuz sürün.", "Kızgın ızgarada her yüzünü 5–6 dakika pişirin.", "Eti kılçıktan kolayca ayrılıyorsa pişmiştir.", "Limon ve roka salatasıyla servis edin."], minutes: 22, servings: 2, prepMinutes: 10, cookMinutes: 12, difficulty: "Orta", tips: ["Izgarayı iyice ısıtmak balığın yapışmasını önler."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_029", title: "Ahtapot salatası", category: "Salatalar", ingredients: ["1 kg ahtapot", "1 kırmızı soğan", "1 kırmızı biber", "Yarım demet maydanoz", "4 yemek kaşığı zeytinyağı", "1 limon", "1 tatlı kaşığı tuz"], steps: ["Ahtapotu kaynar suda kendi suyunda 45 dakika, çatal kolayca girene kadar pişirin.", "Soğuyunca kollarını 1 cm dilimleyin.", "Soğan, biber ve maydanozu ince doğrayın.", "Zeytinyağı, limon ve tuzla karıştırın.", "Buzdolabında 1 saat dinlendirip servis edin."], minutes: 65, servings: 4, prepMinutes: 20, cookMinutes: 45, difficulty: "Orta", tips: ["Dondurulmuş ahtapot daha kolay yumuşar."], serving: "Soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_030", title: "Tutmaç çorbası", category: "Çorbalar", ingredients: ["Erişte için: 1 su bardağı un, 1 yumurta, 1 çay kaşığı tuz", "1 su bardağı yeşil mercimek", "2 su bardağı yoğurt", "1 yumurta sarısı", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı kuru nane, 1 tatlı kaşığı pul biber, 1 tatlı kaşığı tuz"], steps: ["Un, yumurta ve tuzla sert hamur yoğurup ince açın, küçük kareler kesin.", "Mercimeği 6 su bardağı suda 20 dakika haşlayın.", "Erişteleri ekleyip 10 dakika pişirin.", "Yoğurt ve yumurta sarısını ılıştırıp ekleyin, kaynamaya yakın ocaktan alın.", "Naneli pul biberli tereyağı gezdirin."], minutes: 70, servings: 6, prepMinutes: 30, cookMinutes: 40, difficulty: "Orta", tips: ["Selçuklu’dan beri bilinen bir Anadolu çorbasıdır."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_031", title: "Lebeniye çorbası", category: "Çorbalar", ingredients: ["1 su bardağı haşlanmış nohut", "Yarım su bardağı pirinç", "2 su bardağı yoğurt", "1 yumurta", "1 yemek kaşığı un", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı kuru nane, 1 tatlı kaşığı tuz"], steps: ["Pirinci 5 su bardağı suda 15 dakika pişirin.", "Nohudu ekleyin.", "Yoğurt, yumurta ve unu çırpıp ılıştırarak ekleyin.", "Sürekli karıştırarak kaynayana kadar pişirin.", "Naneli tereyağıyla servis edin."], minutes: 40, servings: 6, prepMinutes: 10, cookMinutes: 30, difficulty: "Orta", tips: ["Hatay ve Antep mutfağında sık yapılır."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_032", title: "Mahluta (Hatay mercimek çorbası)", category: "Çorbalar", ingredients: ["1 su bardağı kırmızı mercimek", "2 yemek kaşığı pirinç", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı tereyağı", "1 tatlı kaşığı kimyon, 1 tatlı kaşığı pul biber, 1 tatlı kaşığı tuz", "1 limon"], steps: ["Soğanı tereyağında kavurup salçayı ekleyin.", "Yıkanmış mercimek, pirinç ve 6 su bardağı sıcak suyu ekleyin.", "30 dakika pişirip blenderdan geçirin.", "Kimyon ve tuzu ekleyin.", "Pul biberli tereyağı ve limonla servis edin."], minutes: 45, servings: 6, prepMinutes: 10, cookMinutes: 35, difficulty: "Orta", tips: ["Kimyon mahlutanın ayırt edici tadıdır."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_033", title: "Ayran aşı çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı aşurelik buğday (haşlanmış)", "Yarım su bardağı nohut (haşlanmış)", "3 su bardağı yoğurt", "1 yumurta", "1 yemek kaşığı un", "1 demet ıspanak ya da pazı", "1 tatlı kaşığı kuru nane, 1 tatlı kaşığı tuz"], steps: ["Yoğurt, yumurta, un ve 4 su bardağı suyu çırpın.", "Orta ateşte sürekli karıştırarak kaynatın.", "Buğday, nohut ve doğranmış yeşilliği ekleyin.", "10 dakika pişirip tuzlayın.", "Sıcak ya da yazın soğuk servis edin."], minutes: 35, servings: 6, prepMinutes: 10, cookMinutes: 25, difficulty: "Orta", tips: ["Yazın soğuk içilen bir Anadolu çorbasıdır."], serving: "Sıcak ya da soğuk.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_034", title: "Paçanga böreği", category: "Hamur işleri", ingredients: ["4 yaprak yufka", "150 g pastırma", "150 g kaşar", "2 domates", "2 sivri biber", "1 yumurta", "Kızartmak için 1 su bardağı sıvı yağ"], steps: ["Yufkaları üçgen dilimlere kesin.", "Pastırma, kaşar, domates ve biberi ince doğrayın.", "Harcı yufkalara koyup sigara böreği gibi sarın, ucunu yumurtayla yapıştırın.", "Kızgın yağda her yüzünü 2 dakika kızartın.", "Kağıt havluya alıp sıcak servis edin."], minutes: 25, servings: 4, prepMinutes: 15, cookMinutes: 10, difficulty: "Orta", tips: ["İstanbul meyhane mutfağının sıcak mezesidir."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_035", title: "Çiğ börek", category: "Hamur işleri", ingredients: ["Hamur: 3 su bardağı un, 1 su bardağı su, 1 tatlı kaşığı tuz", "İç: 300 g kıyma, 2 soğan rendesi, 1 tatlı kaşığı tuz, 1 çay kaşığı karabiber", "Kızartmak için 3 su bardağı ayçiçek yağı"], steps: ["Hamuru yoğurup 30 dakika dinlendirin.", "Kıymayı soğan, tuz ve karabiberle yoğurup çiğ bırakın.", "Hamuru ince açıp yarısına iç harcı ince yayın, katlayıp kenarlarını bastırın.", "Kızgın yağda 2–3 dakika, kıyma pişene kadar kızartın.", "Ayranla sıcak servis edin."], minutes: 60, servings: 8, prepMinutes: 40, cookMinutes: 20, difficulty: "Zor", tips: ["Kırım Tatar mutfağındandır; harç çiğ konur, yağda pişer."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_036", title: "Patatesli kol böreği", category: "Hamur işleri", ingredients: ["4 yaprak yufka", "4 patates", "1 soğan", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "2 yumurta", "1 tatlı kaşığı tuz, 1 tatlı kaşığı pul biber", "1 yemek kaşığı çörek otu"], steps: ["Patatesleri haşlayıp ezin, kavrulmuş soğan ve baharatla karıştırın.", "Süt, yağ ve 1 yumurtayı çırpın.", "Yufkayı serip sosla nemlendirin, kenarına harç koyup rulo yapın.", "Ruloları tepsiye spiral dizin, üzerine yumurta sarısı sürüp çörek otu serpin.", "180 °C fırında 40 dakika pişirin."], minutes: 70, servings: 8, prepMinutes: 30, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 180, tips: ["Ruloları sıkı sarmak pişerken açılmasını önler."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_037", title: "Karadeniz pidesi (kıymalı yumurtalı)", category: "Hamur işleri", ingredients: ["Hamur: 3 su bardağı un, 1 paket kuru maya, 1 su bardağı ılık su, 1 tatlı kaşığı tuz", "300 g kıyma", "1 soğan", "4 yumurta", "2 yemek kaşığı tereyağı"], steps: ["Hamuru yoğurup 45 dakika mayalandırın.", "Kıymayı soğanla kavurun.", "Hamuru 4 parçaya bölüp uzun oval açın, kenarlarını kıvırıp kayık şekli verin.", "Kıymayı yayıp 230 °C fırında 10 dakika pişirin.", "Yumurtayı ortaya kırıp 4–5 dakika daha pişirin, tereyağı sürün."], minutes: 75, servings: 4, prepMinutes: 60, cookMinutes: 15, difficulty: "Orta", ovenCelsius: 230, tips: ["Gebeler ve çocuklar için yumurta sarısı tam pişmeli."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_038", title: "Kete (Kars usulü)", category: "Hamur işleri", ingredients: ["Hamur: 4 su bardağı un, 1 paket kuru maya, 1 su bardağı ılık süt, yarım su bardağı sıvı yağ, 1 yumurta, 1 tatlı kaşığı tuz", "İç: 125 g tereyağı, 1 su bardağı un", "Üzeri için 1 yumurta sarısı"], steps: ["Hamuru yoğurup 1 saat mayalandırın.", "Tereyağında unu kokusu çıkana kadar kavurup soğutun (kavut).", "Hamuru açıp kavutu yayın, rulo yapıp salyangoz gibi sarın.", "Avuçla bastırıp yuvarlak açın, yumurta sarısı sürün.", "180 °C fırında 30 dakika pişirin."], minutes: 120, servings: 10, prepMinutes: 90, cookMinutes: 30, difficulty: "Orta", ovenCelsius: 180, tips: ["Doğu Anadolu’nun çay saati çöreğidir."], serving: "Çayla.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n12_039", title: "Ay çöreği", category: "Hamur işleri", ingredients: ["Hamur: 4 su bardağı un, 1 paket kuru maya, 1 su bardağı ılık süt, 125 g tereyağı, yarım su bardağı şeker, 1 yumurta", "İç: 1 su bardağı ceviz, 3 yemek kaşığı kuru üzüm, 1 tatlı kaşığı tarçın, 3 yemek kaşığı şeker", "Üzeri için 1 yumurta sarısı"], steps: ["Hamuru yoğurup 1 saat mayalandırın.", "İç malzemeleri karıştırın.", "Hamuru 10 parçaya bölüp oval açın, iç koyup rulo yapın ve hilal şeklinde kıvırın.", "Üzerine yumurta sarısı sürüp 20 dakika bekletin.", "180 °C fırında 30 dakika pişirin."], minutes: 120, servings: 10, prepMinutes: 90, cookMinutes: 30, difficulty: "Orta", ovenCelsius: 180, tips: ["Hilal şekli adını verir."], serving: "Çayla.", storage: "Kapalı kapta 3 gün."),
  GeneralRecipe(id: "n12_040", title: "Özbek pilavı", category: "Pilavlar", ingredients: ["2 su bardağı baldo pirinç", "400 g kuşbaşı kuzu eti", "3 havuç", "1 soğan", "2 yemek kaşığı nohut (haşlanmış)", "2 yemek kaşığı kuru üzüm", "3 yemek kaşığı sıvı yağ", "1 tatlı kaşığı kimyon, 1 tatlı kaşığı tuz"], steps: ["Pirinci ılık tuzlu suda 30 dakika bekletin.", "Eti yağda kavurup soğanı ekleyin.", "Kibrit çöpü doğranmış havucu ekleyip 5 dakika çevirin.", "Nohut, üzüm, kimyon, tuz ve süzülmüş pirinci üzerine yayın; 3 su bardağı sıcak su ekleyin.", "Kısık ateşte suyunu çekene kadar 20 dakika pişirip 15 dakika demlendirin."], minutes: 60, servings: 6, prepMinutes: 20, cookMinutes: 40, difficulty: "Orta", tips: ["Pirinci karıştırmadan katlar hâlinde pişirmek geleneksel yöntemdir."], serving: "Sıcak servis edin.", storage: "Buzdolabında 2 gün."),
  GeneralRecipe(id: "n12_043", title: "Sahlep (ev usulü)", category: "İçecekler", ingredients: ["2 su bardağı süt", "2 tatlı kaşığı toz salep", "2 yemek kaşığı şeker", "1 çay kaşığı tarçın"], steps: ["Sütün yarım su bardağını ayırın; salep ve şekeri bu soğuk sütte topak kalmayana kadar çırpın.", "Kalan sütü tencerede orta ateşte, kaynamaya yakın ısıtın.", "Salepli karışımı sürekli çırparak ekleyin.", "Sürekli karıştırarak koyulaşana kadar 8–10 dakika pişirin.", "Fincanlara alıp tarçın serpin.", "Sıcak servis edin; ağzınızı yakmamak için 1–2 dakika bekleyin."], minutes: 22, servings: 2, prepMinutes: 2, cookMinutes: 10, difficulty: "Kolay", tips: ["Gerçek salep orkide yumrusundan yapılır; katkısız ürün seçin."], serving: "Sıcak.", storage: "Hemen tüketin."),
  GeneralRecipe(id: "n12_044", title: "Demirhindi şerbeti", category: "İçecekler", ingredients: ["100 g demirhindi", "1 su bardağı şeker", "2 litre su", "4 karanfil", "1 limon"], steps: ["Demirhindiyi 1 litre suda 2 saat bekletin.", "Karanfille 15 dakika kaynatıp süzün.", "Kalan su ve şekeri ekleyip karıştırın.", "Limon suyunu ekleyip soğutun.", "Buzla servis edin."], minutes: 25, servings: 8, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Ramazan sofralarının geleneksel şerbetidir."], serving: "Soğuk.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "n12_045", title: "Gül şerbeti", category: "İçecekler", ingredients: ["1 su bardağı kurutulmuş gül yaprağı (gıdaya uygun)", "1 su bardağı şeker", "2 litre su", "1 limon"], steps: ["Gıdaya uygun, ilaçsız kurutulmuş gül yaprağı kullanın; süs amaçlı gülleri kullanmayın.", "Gül yapraklarını kaynar suya koyup kapağı kapalı 30 dakika demleyin.", "İnce süzgeçten süzüp yaprakları sıkın.", "Şekeri ılık şerbette karıştırarak eritin.", "Limon suyunu ekleyin; renk açık pembeye döner.", "Oda sıcaklığına gelince buzdolabında soğutun; kapalı şişede 2 gün saklayabilirsiniz.", "Buzla servis edin."], minutes: 40, servings: 8, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Yalnızca ilaçlanmamış, gıdaya uygun gül kullanın."], serving: "Soğuk.", storage: "Buzdolabında 4 gün."),
  GeneralRecipe(id: "n12_046", title: "Sumak şerbeti", category: "İçecekler", ingredients: ["3 yemek kaşığı sumak", "1,5 litre su", "4 yemek kaşığı şeker ya da bal"], steps: ["Sumağı suya koyup 2 saat bekletin; ara ara karıştırın.", "İnce süzgeçten ya da tülbentten süzün.", "Şekeri ya da balı eritin.", "Bal 1 yaşından küçük bebeklere verilmez; bebek porsiyonunu balsız ayırın.", "Oda sıcaklığına gelince buzdolabında soğutun; kapalı şişede 2 gün saklayabilirsiniz.", "Buzla servis edin."], minutes: 20, servings: 6, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Güneydoğu’da yazın serinletici olarak içilir."], serving: "Soğuk.", storage: "Buzdolabında 3 gün."),
  GeneralRecipe(id: "n12_047", title: "Ev yapımı vişne reçeli", category: "Kahvaltılıklar", ingredients: ["1 kg çekirdeği çıkarılmış vişne", "800 g şeker", "Yarım limon suyu"], steps: ["Vişneleri şekerle karıştırıp 3 saat suyunu salması için bekletin.", "Orta ateşte kaynatıp köpüğünü alın.", "Kısık ateşte 30 dakika, şerbeti koyulaşana kadar pişirin.", "Limon suyunu ekleyip 2 dakika daha kaynatın.", "Sıcakken steril kavanozlara doldurup ters çevirin."], minutes: 65, servings: 20, prepMinutes: 30, cookMinutes: 35, difficulty: "Kolay", tips: ["Tabağa damlatılan şurup akmıyorsa kıvamı gelmiştir."], serving: "Kahvaltıda.", storage: "Açılmamış kavanoz serin yerde 1 yıl."),
  GeneralRecipe(id: "n12_048", title: "Ezme biber turşusu (ev usulü)", category: "Mezeler", ingredients: ["1 kg sivri biber", "1 su bardağı üzüm sirkesi", "2 yemek kaşığı kaya tuzu", "1 tatlı kaşığı şeker", "5 diş sarımsak", "Su (kavanozu doldurmaya yetecek kadar, yaklaşık 1 litre)"], steps: ["Biberleri yıkayıp saplarını kısaltın, birkaç yerinden çatalla delin.", "Kavanoza sarımsakla birlikte sıkıca yerleştirin.", "Su, sirke, tuz ve şekeri karıştırıp kavanozu doldurun.", "Ağzını sıkıca kapatıp serin ve karanlık yerde 2–3 hafta bekletin.", "Açtıktan sonra buzdolabında saklayın."], minutes: 30, servings: 10, prepMinutes: 30, cookMinutes: 0, difficulty: "Kolay", tips: ["Sirke ve tuz oranını azaltmayın; turşunun güvenliğini sağlar."], serving: "Yemek yanında.", storage: "Açılınca buzdolabında 1 ay."),
  // Ayrıntılı tarifler (13. tur): süre, porsiyon, zorluk, ipucu, servis ve saklama bilgisiyle.
  GeneralRecipe(id: "d13_001", title: "Tavada sebzeli bulgur", category: "Pratik tarifler", ingredients: ["1,5 su bardağı pilavlık bulgur", "1 soğan", "1 kırmızı kapya biber", "1 sivri biber", "1 kabak", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "3 su bardağı sıcak su", "Yarım çay kaşığı tuz", "1 çay kaşığı kekik"], steps: ["Soğanı yemeklik, biberleri ve kabağı küçük küp doğrayın; bulguru bir kez yıkayıp süzün.", "Geniş bir tavada zeytinyağını orta ateşte ısıtın, soğanı 3 dakika pembeleşene kadar kavurun.", "Biberleri ve kabağı ekleyip 4 dakika, sebzeler hafifçe yumuşayana kadar çevirin.", "Salçayı ekleyin ve kokusu çıkana kadar 1 dakika kavurun.", "Bulguru ekleyip yağa bulanması için 1 dakika karıştırın.", "Sıcak suyu, tuzu ve kekiği ekleyin; kaynayınca ateşi kısın ve kapağı kapalı 15 dakika suyunu çekene kadar pişirin.", "Ocaktan alıp kapağın altına temiz bir bez koyun ve 10 dakika demlendirin; çatalla havalandırarak servis edin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Sebzeleri eşit büyüklükte doğrarsanız aynı sürede pişerler.", "Kabak yerine patlıcan ya da mantar da kullanabilirsiniz."], serving: "Yanına yoğurt ya da cacık ile sıcak servis edin.", storage: "Kapalı kapta buzdolabında 3 gün saklanır; az su serperek ısıtın."),
  GeneralRecipe(id: "d13_002", title: "Yumurtalı ekmek (french toast)", category: "Pratik tarifler", ingredients: ["4 dilim bayat ekmek", "2 yumurta", "Yarım su bardağı süt", "1 tutam tuz", "Yarım çay kaşığı tarçın (isteğe bağlı)", "1 yemek kaşığı tereyağı"], steps: ["Yumurtaları geniş ve düz bir kapta süt ve tuzla çatalla iyice çırpın; tatlı sevenler tarçın ekleyebilir.", "Tavayı orta ateşte ısıtıp tereyağının yarısını eritin.", "Ekmek dilimlerini karışıma her iki yüzü ıslanacak şekilde 10 saniye batırın; fazlasını süzdürün.", "Dilimleri tavaya dizin, alt yüzü altın rengi olana kadar 2–3 dakika pişirin.", "Çevirip kalan tereyağını kenarlardan ekleyin ve diğer yüzünü de 2–3 dakika pişirin.", "Yumurtanın içte de tamamen pişmesi için ateşi çok yükseltmeyin; kâğıt havluya alıp sıcak servis edin."], minutes: 15, servings: 2, prepMinutes: 5, cookMinutes: 10, difficulty: "Kolay", tips: ["Bayat ekmek karışımı daha iyi çeker ve dağılmaz.", "Tuzlu versiyon için kekik ve rendelenmiş peynir ekleyebilirsiniz."], serving: "Domates, salatalık ve zeytinle ya da meyveyle servis edin.", storage: "Hemen tüketin; bekledikçe yumuşar."),
  GeneralRecipe(id: "d13_003", title: "Peynirli patates rösti", category: "Pratik tarifler", ingredients: ["3 orta boy patates", "50 g rendelenmiş kaşar", "1 yumurta", "2 dal taze soğan", "Yarım çay kaşığı tuz", "1 tutam karabiber", "2 yemek kaşığı zeytinyağı"], steps: ["Patatesleri soyup iri rendeleyin; temiz bir beze alıp suyunu iyice sıkın.", "Taze soğanı ince doğrayın.", "Patates, kaşar, yumurta, taze soğan, tuz ve karabiberi bir kapta karıştırın.", "Yapışmaz tavada yağı orta ateşte ısıtın, karışımı tavaya yayıp kaşıkla bastırarak düzleştirin.", "Kapağı kapalı olarak alt yüzü kızarana kadar 7–8 dakika pişirin.", "Bir tabak yardımıyla ters çevirip diğer yüzünü 5–6 dakika, patates yumuşayana kadar pişirin.", "Dilimleyip sıcak servis edin."], minutes: 25, servings: 2, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Patatesin suyunu ne kadar iyi sıkarsanız rösti o kadar çıtır olur.", "Ateşi orta seviyede tutun; yüksek ateşte dışı yanar, içi çiğ kalır."], serving: "Yoğurt ya da yeşil salata ile servis edin.", storage: "En lezzetlisi taze hâlidir; kalanı buzdolabında 1 gün saklayıp tavada ısıtın."),
  GeneralRecipe(id: "d13_004", title: "Lavaşta sebzeli pizza", category: "Pratik tarifler", ingredients: ["2 adet lavaş", "3 yemek kaşığı domates sosu", "100 g rendelenmiş mozzarella ya da kaşar", "Yarım kırmızı biber", "5–6 mantar", "5 siyah zeytin", "1 çay kaşığı kekik"], steps: ["Fırını 220°C’ye ısıtın; tepsiye pişirme kâğıdı serin.", "Biberi ince şerit, mantarları ince dilim, zeytinleri halka doğrayın.", "Lavaşları tepsiye koyun ve domates sosunu kenarlarda 1 cm boşluk bırakarak sürün.", "Peynirin yarısını serpin, üzerine sebzeleri ve zeytini dağıtın.", "Kalan peyniri ve kekiği serpin.", "Fırında 8–10 dakika, kenarlar kızarıp peynir eriyene kadar pişirin.", "Bir dakika dinlendirip dilimleyin."], minutes: 20, servings: 2, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", ovenCelsius: 220, tips: ["Lavaş incedir; fırını gözünüzün önünde tutun, kısa sürede kızarır.", "Çocuklar kendi pizzalarını süsleyebilir; mısır ve haşlanmış tavuk da yakışır."], serving: "Ayran ya da yeşil salata ile sıcak servis edin.", storage: "Taze tüketin; kalanı buzdolabında 1 gün saklayıp tavada ısıtın."),
  GeneralRecipe(id: "d13_005", title: "Tavada kıymalı patates", category: "Pratik tarifler", ingredients: ["300 g kıyma", "3 orta boy patates", "1 soğan", "1 yeşil biber", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "Yarım çay kaşığı tuz", "1 çay kaşığı pul biber"], steps: ["Patatesleri soyup 1,5 cm küp doğrayın; soğanı ve biberi ince doğrayın.", "Geniş tavada yağı ısıtıp patatesleri 8 dakika, kenarları hafif kızarana kadar çevirin ve bir tabağa alın.", "Aynı tavada kıymayı suyunu salıp çekene ve rengi tamamen dönene kadar 6–7 dakika kavurun.", "Soğan ve biberi ekleyip 3 dakika daha kavurun; salçayı ekleyip 1 dakika çevirin.", "Patatesleri geri ekleyin, sıcak suyu, tuzu ve pul biberi ilave edin.", "Kapağı kapalı, kısık ateşte patatesler yumuşayana kadar 12–15 dakika pişirin."], minutes: 35, servings: 4, prepMinutes: 10, cookMinutes: 25, difficulty: "Kolay", tips: ["Kıymanın içinde pembe yer kalmamalıdır; özellikle çocuklar ve gebeler için tam pişirin.", "Patatesleri önce kızartmak dağılmalarını önler."], serving: "Pilav ya da bulgur pilavı ve yoğurtla servis edin.", storage: "Buzdolabında kapalı kapta 2 gün saklanır."),
  GeneralRecipe(id: "d13_006", title: "Tek tencere kremalı tavuk makarna", category: "Pratik tarifler", ingredients: ["300 g tavuk göğsü", "300 g kalem makarna", "1 soğan", "2 diş sarımsak", "200 g mantar", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı", "4 su bardağı sıcak su", "1 su bardağı süt", "50 g rendelenmiş kaşar", "Yarım çay kaşığı tuz"], steps: ["Tavuğu küçük küp, soğanı ve sarımsağı ince doğrayın; mantarları dilimleyin.", "Geniş tencerede yağları ısıtıp tavuğu rengi tamamen beyazlayana kadar 6 dakika soteleyin.", "Soğan, sarımsak ve mantarı ekleyip mantar suyunu çekene kadar 5 dakika pişirin.", "Çiğ makarnayı, sıcak suyu ve tuzu ekleyip kaynatın.", "Ara ara karıştırarak, makarna yumuşayana ve su azalana kadar 10–12 dakika pişirin.", "Sütü ekleyip 2 dakika kaynatın, ocaktan alıp kaşarı karıştırarak eritin."], minutes: 30, servings: 4, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Makarnanın dibe tutmaması için sık karıştırın.", "Sos koyu kalırsa birkaç kaşık sıcak su ekleyin."], serving: "Üzerine karabiber ve maydanoz serperek sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır; ısıtırken biraz süt ekleyin."),
  GeneralRecipe(id: "d13_007", title: "Nohutlu ıspanak kavurması", category: "Pratik tarifler", ingredients: ["500 g ıspanak", "1,5 su bardağı haşlanmış nohut", "1 soğan", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kimyon", "Yarım çay kaşığı tuz", "Yarım limon"], steps: ["Ispanağı bol suda birkaç kez yıkayıp iri doğrayın.", "Soğanı ince, sarımsağı daha ince doğrayın.", "Geniş tavada zeytinyağını ısıtıp soğanı 4 dakika yumuşatın, sarımsağı ekleyip 30 saniye çevirin.", "Nohut ve kimyonu ekleyip 2 dakika kavurun.", "Ispanağı ekleyin ve söndükçe karıştırarak 4–5 dakika pişirin.", "Tuzu ekleyin, ocaktan alıp limon suyunu sıkın."], minutes: 25, servings: 3, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Ispanak çok su salarsa ateşi açıp kısa süre suyunu uçurun.", "Demir emilimini artırmak için limon suyunu en son ekleyin."], serving: "Sarımsaklı yoğurt ve tam buğday ekmeğiyle servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "d13_008", title: "Lorlu dereotlu omlet", category: "Pratik tarifler", ingredients: ["2 yumurta", "3 yemek kaşığı lor peyniri", "3 dal dereotu", "1 yemek kaşığı süt", "1 tatlı kaşığı tereyağı", "1 tutam karabiber"], steps: ["Dereotunu ince kıyın.", "Yumurtaları sütle çırpın; lor, dereotu ve karabiberi ekleyip karıştırın.", "Tavada tereyağını orta ateşte eritin ve karışımı dökün.", "Kenarları pişmeye başlayınca spatulayla ortaya doğru itip çiğ kısmın alta akmasını sağlayın.", "Üst yüzü sıvı kalmayıp tamamen pişene kadar 3–4 dakika pişirin, ikiye katlayıp alın."], minutes: 11, servings: 1, prepMinutes: 5, cookMinutes: 6, difficulty: "Kolay", tips: ["Lor tuzlu değilse 1 tutam tuz ekleyebilirsiniz.", "Gebelikte yumurtanın tamamen pişmiş olduğundan emin olun."], serving: "Domates ve tam buğday ekmeğiyle servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "d13_009", title: "Ev yapımı ayran", category: "İçecekler", ingredients: ["2 su bardağı yoğurt", "2 su bardağı soğuk içme suyu", "Yarım çay kaşığı tuz", "Birkaç yaprak taze nane (isteğe bağlı)"], steps: ["Yoğurdu geniş bir sürahiye alın.", "Tuzu ekleyip yoğurdu pürüzsüz olana kadar çırpın.", "Soğuk suyu azar azar eklerken çırpmaya devam edin.", "Köpüklü olması için 30 saniye el blenderından geçirin.", "İsterseniz nane yapraklarıyla süsleyip soğuk servis edin."], minutes: 5, servings: 4, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Kıvamı damak zevkinize göre su miktarıyla ayarlayın.", "Tuzu azaltmak ya da hiç kullanmamak mümkündür."], serving: "Hemen soğuk servis edin.", storage: "Buzdolabında kapalı şişede 1 gün saklanır; içmeden önce çalkalayın."),
  GeneralRecipe(id: "d13_010", title: "Zencefilli limonata", category: "İçecekler", ingredients: ["4 limon", "1 parmak boyu taze zencefil", "5 yemek kaşığı şeker ya da bal", "1,5 litre soğuk su", "Birkaç yaprak taze nane"], steps: ["Limonları iyice yıkayın; ikisinin kabuğunu acı beyaz kısmına inmeden rendeleyin.", "Zencefili soyup ince dilimleyin.", "Küçük tencerede 1 su bardağı su, şeker, limon kabuğu ve zencefili 5 dakika kaynatın; ocaktan alıp soğutun.", "Tüm limonların suyunu sıkın.", "Soğuyan şurubu süzüp limon suyu ve kalan soğuk suyla sürahide karıştırın.", "Nane yapraklarını ekleyip buzdolabında en az 1 saat soğutun."], minutes: 20, servings: 6, prepMinutes: 15, cookMinutes: 5, difficulty: "Kolay", tips: ["Bal kullanacaksanız şurup ılıdıktan sonra ekleyin.", "Bal 1 yaşından küçük bebeklere verilmez."], serving: "Buzla ve nane yaprağıyla soğuk servis edin.", storage: "Buzdolabında kapalı şişede 3 gün saklanır."),
  GeneralRecipe(id: "d13_011", title: "Muzlu yulaf smoothie", category: "İçecekler", ingredients: ["1 olgun muz", "3 yemek kaşığı yulaf ezmesi", "1,5 su bardağı süt", "2 yemek kaşığı yoğurt", "1 tatlı kaşığı fıstık ezmesi (isteğe bağlı)", "Yarım çay kaşığı tarçın"], steps: ["Yulafı sütle blender haznesine alıp 5 dakika yumuşaması için bekletin.", "Muzu soyup dilimleyin ve hazneye ekleyin.", "Yoğurt, tarçın ve isteğe bağlı fıstık ezmesini ekleyin.", "Pürüzsüz olana kadar 40–60 saniye çekin.", "Kıvamı koyuysa biraz süt ekleyip tekrar çekin ve hemen servis edin."], minutes: 5, servings: 2, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Dondurulmuş muz kullanırsanız buz eklemeden serin bir içecek olur.", "Fıstık alerjisi varsa fıstık ezmesini çıkarın."], serving: "Hazırlar hazırlamaz servis edin.", storage: "Bekletmeyin; en fazla birkaç saat buzdolabında kalabilir."),
  GeneralRecipe(id: "d13_012", title: "Ihlamur çayı", category: "İçecekler", ingredients: ["2 yemek kaşığı kuru ıhlamur", "4 su bardağı su", "1 dilim limon", "1 çubuk tarçın (isteğe bağlı)"], steps: ["Suyu demlikte kaynatın.", "Ihlamuru ve isteğe bağlı tarçını ekleyip ocağı kapatın.", "Kapağı kapalı olarak 5–7 dakika demlenmeye bırakın; kaynatmaya devam etmeyin.", "Süzerek bardaklara alın ve limon dilimiyle servis edin.", "Gebelikte ve emzirirken bitki çaylarını hekiminize danışarak, günde 1–2 fincanı geçmeyecek şekilde için.", "Bebek ve küçük çocuklara bitki çayı vermeden önce doktorunuza danışın."], minutes: 17, servings: 4, prepMinutes: 2, cookMinutes: 8, difficulty: "Kolay", tips: ["Uzun kaynatmak acılaştırır; demleme yeterlidir.", "Gebelikte ve emzirirken bitki çaylarını ölçülü tüketin; düzenli kullanmadan önce doktorunuza danışın."], serving: "Sıcak servis edin; isterseniz az bal ekleyin.", storage: "Taze demlenmiş olarak tüketin."),
  GeneralRecipe(id: "d13_013", title: "Sıcak elmalı tarçın içeceği", category: "İçecekler", ingredients: ["3 elma", "1 litre su", "1 çubuk tarçın", "3 karanfil", "1 dilim portakal kabuğu"], steps: ["Elmaları yıkayıp çekirdek evlerini çıkarın ve ince dilimleyin.", "Tüm malzemeleri tencereye alıp kaynatın.", "Kısık ateşte elmalar yumuşayana kadar 15 dakika pişirin.", "Ocaktan alıp 5 dakika demlendirin.", "Süzerek fincanlara alın; elma dilimlerini de birkaç tane ekleyebilirsiniz."], minutes: 25, servings: 4, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", tips: ["Elmanın tatlılığı çoğu zaman yeterlidir; şeker eklemeden deneyin.", "Karanfili süzmeyi unutmayın."], serving: "Soğuk kış günlerinde sıcak servis edin.", storage: "Buzdolabında 2 gün saklanır; ısıtarak tüketin."),
  GeneralRecipe(id: "d13_014", title: "Çilekli kefir", category: "İçecekler", ingredients: ["1,5 su bardağı sade kefir", "8–10 çilek", "1 tatlı kaşığı bal (isteğe bağlı)"], steps: ["Meyveleri bol suda iyice yıkayın.", "Çileklerin saplarını ayıklayın.", "Çilek ve kefiri blender haznesine alın.", "İsterseniz balı ekleyin.", "Pürüzsüz olana kadar 30 saniye çekin ve hemen servis edin.", "Bal 1 yaşından küçük bebeklere verilmez; bebek porsiyonunu balsız ayırın."], minutes: 10, servings: 2, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Dondurulmuş çilek kullanabilirsiniz.", "Bal 1 yaşından küçüklere verilmez."], serving: "Kahvaltıda ya da ara öğünde soğuk servis edin.", storage: "Hazırladıktan sonra en geç birkaç saat içinde tüketin."),
  GeneralRecipe(id: "d13_015", title: "Havuçlu tarçınlı kek", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "3/4 su bardağı ayçiçek yağı", "2 su bardağı rendelenmiş havuç", "2 su bardağı un", "1 paket kabartma tozu", "1 tatlı kaşığı tarçın", "Yarım su bardağı iri kırılmış ceviz"], steps: ["Fırını 175°C’ye ısıtın; kek kalıbını yağlayıp unlayın.", "Yumurta ve şekeri mikserle 4–5 dakika, rengi açılıp köpürene kadar çırpın.", "Yağı ince bir akışla eklerken çırpmaya devam edin.", "Havucu ekleyip spatulayla karıştırın.", "Un, kabartma tozu ve tarçını eleyerek ekleyin; un görünmeyene kadar nazikçe karıştırın.", "Cevizi karıştırıp hamuru kalıba dökün.", "Fırında 40 dakika pişirin; ortasına batırdığınız kürdan kuru çıkıyorsa kek hazırdır.", "Kalıpta 10 dakika bekletip tel ızgaraya alın ve tamamen soğutun."], minutes: 60, servings: 10, prepMinutes: 20, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 175, tips: ["Pişerken ilk 30 dakika fırın kapağını açmayın, kek söner.", "Havucu ince rendelemek keki daha nemli yapar."], serving: "Soğuduktan sonra dilimleyip çay ya da sütle servis edin.", storage: "Kapalı kapta oda sıcaklığında 2 gün, buzdolabında 4 gün saklanır."),
  GeneralRecipe(id: "d13_016", title: "Yulaflı muzlu kurabiye", category: "Kek ve kurabiyeler", ingredients: ["2 olgun muz", "1,5 su bardağı yulaf ezmesi", "2 yemek kaşığı kuru üzüm", "1 çay kaşığı tarçın", "2 yemek kaşığı tahin ya da fındık ezmesi"], steps: ["Fırını 180°C’ye ısıtın, tepsiye pişirme kâğıdı serin.", "Muzları çatalla pürüzsüz olana kadar ezin.", "Yulaf, tarçın, tahin ve kuru üzümü ekleyip iyice karıştırın; 5 dakika bekletin.", "Islak elle ceviz büyüklüğünde parçalar alıp yuvarlayın, tepsiye dizip avucunuzla bastırın.", "Fırında kenarları kızarana kadar 15 dakika pişirin.", "Tepside 5 dakika bekletip tel ızgarada soğutun."], minutes: 25, servings: 12, prepMinutes: 10, cookMinutes: 15, difficulty: "Kolay", ovenCelsius: 180, tips: ["Şeker içermez; tatlılığı muzdan gelir.", "Küçük çocuklar için kuru üzümü ince doğrayın."], serving: "Ara öğünde süt ya da yoğurtla servis edin.", storage: "Kapalı kapta buzdolabında 4 gün saklanır."),
  GeneralRecipe(id: "d13_017", title: "Limonlu yoğurtlu kek", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "1 su bardağı yoğurt", "Yarım su bardağı ayçiçek yağı", "1 limonun rendelenmiş kabuğu ve suyu", "2,5 su bardağı un", "1 paket kabartma tozu"], steps: ["Fırını 175°C’ye ısıtın, kalıbı yağlayıp unlayın.", "Yumurta ve şekeri köpük köpük olana kadar çırpın.", "Yoğurt, yağ, limon kabuğu ve limon suyunu ekleyip karıştırın.", "Un ve kabartma tozunu eleyerek ekleyin, spatulayla topaksız olana kadar karıştırın.", "Hamuru kalıba döküp tezgâha birkaç kez vurarak havasını alın.", "Fırında 40 dakika, kürdan kuru çıkana kadar pişirin.", "Kalıpta 10 dakika bekletip ters çevirin ve soğumaya bırakın."], minutes: 55, servings: 10, prepMinutes: 15, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 175, tips: ["Limon kabuğunu rendelerken beyaz kısmına inmeyin, acılaştırır.", "Üzerine pudra şekeri ya da limon sosu ekleyebilirsiniz."], serving: "Soğuyunca dilimleyip servis edin.", storage: "Kapalı kapta 3 gün saklanır."),
  GeneralRecipe(id: "d13_018", title: "Elmalı tarçınlı muffin", category: "Kek ve kurabiyeler", ingredients: ["2 yumurta", "Yarım su bardağı şeker", "Yarım su bardağı süt", "Yarım su bardağı ayçiçek yağı", "2 su bardağı un", "1 paket kabartma tozu", "2 elma", "1 tatlı kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın, muffin kalıbına kâğıt kapsüller yerleştirin.", "Elmaları soyup küçük küp doğrayın ve tarçının yarısıyla karıştırın.", "Yumurta ve şekeri çırpın; süt ve yağı ekleyin.", "Un, kabartma tozu ve kalan tarçını eleyip ekleyin; birkaç kez karıştırmanız yeterlidir.", "Elmaların çoğunu hamura katın, hamuru kapsüllerin üçte ikisine kadar doldurun.", "Kalan elmaları üzerlerine paylaştırın.", "Fırında 20–22 dakika, üstleri kabarıp kızarana kadar pişirin."], minutes: 37, servings: 12, prepMinutes: 15, cookMinutes: 22, difficulty: "Kolay", ovenCelsius: 180, tips: ["Hamuru fazla karıştırmak muffinleri sertleştirir.", "Elma yerine armut da kullanabilirsiniz."], serving: "Ilık ya da soğuk servis edin.", storage: "Kapalı kapta 2 gün; dondurucuda 1 ay saklanır."),
  GeneralRecipe(id: "d13_019", title: "Cevizli kakaolu kek", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "1 su bardağı süt", "Yarım su bardağı ayçiçek yağı", "2 yemek kaşığı kakao", "2 su bardağı un", "1 paket kabartma tozu", "1 paket vanilin", "1 su bardağı iri kırılmış ceviz"], steps: ["Fırını 175°C’ye ısıtın; kalıbı yağlayıp unlayın.", "Yumurta ve şekeri 4 dakika çırpın.", "Süt ve yağı ekleyip karıştırın.", "Un, kakao, kabartma tozu ve vanilini eleyerek ekleyin; topaksız olana kadar karıştırın.", "Cevizin çoğunu hamura katın, hamuru kalıba döküp kalan cevizi üstüne serpin.", "Fırında 40 dakika, kürdan kuru çıkana kadar pişirin.", "Kalıpta 10 dakika bekletip çıkarın ve soğutun."], minutes: 55, servings: 10, prepMinutes: 15, cookMinutes: 40, difficulty: "Orta", ovenCelsius: 175, tips: ["Cevizleri unla hafifçe karıştırırsanız dibe çökmez.", "Ceviz alerjisi varsa çıkarın; tarif cevizsiz de olur."], serving: "Soğuduktan sonra dilimleyin.", storage: "Kapalı kapta 3 gün saklanır."),
  GeneralRecipe(id: "d13_020", title: "Susamlı tuzlu kurabiye", category: "Kek ve kurabiyeler", ingredients: ["125 g oda sıcaklığında tereyağı", "Yarım su bardağı ayçiçek yağı", "1 yumurtanın akı", "Yarım su bardağı yoğurt", "1 tatlı kaşığı tuz", "1 paket kabartma tozu", "3,5 su bardağı un (gerektiği kadar)", "1 yumurtanın sarısı (üzeri için)", "3 yemek kaşığı susam"], steps: ["Fırını 180°C’ye ısıtın, tepsiye pişirme kâğıdı serin.", "Tereyağı, sıvı yağ, yumurta akı, yoğurt ve tuzu karıştırın.", "Kabartma tozunu ve unu azar azar ekleyerek ele yapışmayan yumuşak bir hamur yoğurun.", "Ceviz büyüklüğünde parçalar alıp yuvarlayın ya da ince uzun şekil verin.", "Tepsiye aralıklı dizin; üzerlerine yumurta sarısı sürüp susama batırın.", "Fırında 18–20 dakika, altları ve üstleri hafif kızarana kadar pişirin."], minutes: 40, servings: 25, prepMinutes: 20, cookMinutes: 20, difficulty: "Orta", ovenCelsius: 180, tips: ["Unu bir anda eklemeyin; hamur yumuşak kalmalıdır.", "Susam yerine çörek otu da kullanabilirsiniz."], serving: "Çayın yanında servis edin.", storage: "Kapalı kutuda 1 hafta saklanır."),
  GeneralRecipe(id: "d13_021", title: "Hurmalı cevizli enerji topları", category: "Kek ve kurabiyeler", ingredients: ["1 su bardağı çekirdeği çıkarılmış hurma", "1 su bardağı ceviz içi", "3 yemek kaşığı yulaf ezmesi", "1 yemek kaşığı kakao", "3 yemek kaşığı hindistan cevizi rendesi"], steps: ["Hurmalar sertse 10 dakika ılık suda bekletip süzün.", "Ceviz ve yulafı mutfak robotunda iri kum kıvamına gelene kadar çekin.", "Hurma ve kakaoyu ekleyip hamur gibi toplanana kadar çekin.", "Islak elle fındık büyüklüğünde parçalar alıp yuvarlayın.", "Hindistan cevizi rendesine bulayın.", "Buzdolabında 30 dakika dinlendirin."], minutes: 15, servings: 16, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Pişirme gerektirmez; çocuklarla birlikte yapılabilir.", "Ceviz alerjisi olanlar için ceviz yerine yulaf miktarını artırın; küçük çocuklarda bütün kuruyemiş verilmez, burada ince çekilmiştir."], serving: "Ara öğünde 1–2 adet servis edin.", storage: "Kapalı kapta buzdolabında 1 hafta saklanır."),
  GeneralRecipe(id: "d13_022", title: "Kırmızı mercimekli bulgur köftesi", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı kırmızı mercimek", "1 su bardağı köftelik bulgur", "3 su bardağı su", "1 soğan", "3 yemek kaşığı zeytinyağı", "1 yemek kaşığı domates salçası", "1 yemek kaşığı biber salçası", "4 dal taze soğan", "Yarım demet maydanoz", "1 çay kaşığı kimyon", "1 limonun suyu", "Yarım çay kaşığı tuz"], steps: ["Mercimeği yıkayıp suyla birlikte, ara ara karıştırarak yaklaşık 15–20 dakika dağılana kadar pişirin.", "Ocaktan alıp bulguru ekleyin, karıştırın ve kapağı kapalı 20 dakika şişmeye bırakın.", "Bu sırada soğanı ince doğrayıp zeytinyağında 5 dakika yumuşatın; salçaları ekleyip 1 dakika kavurun.", "Taze soğan ve maydanozu ince kıyın.", "Kavrulan soğanı, yeşillikleri, kimyon, tuz ve limon suyunu mercimekli karışıma ekleyin.", "Elleriniz ıslakken 3–4 dakika yoğurun; karışım ılık olmalıdır.", "Avucunuzda sıkarak şekil verin ve servis tabağına dizin."], minutes: 45, servings: 6, prepMinutes: 25, cookMinutes: 20, difficulty: "Orta", tips: ["Karışım kuru kalırsa birkaç kaşık ılık su ekleyin.", "Tüm malzemeler pişmiş olduğundan çiğ yumurta ya da çiğ et içermez."], serving: "Marul yaprakları ve limon dilimleriyle servis edin.", storage: "Buzdolabında kapalı kapta 3 gün saklanır."),
  GeneralRecipe(id: "d13_023", title: "Barbunyalı sebze güveci", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış barbunya", "1 patlıcan", "1 kabak", "1 havuç", "1 soğan", "2 domates", "1 yeşil biber", "3 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su", "Yarım çay kaşığı tuz"], steps: ["Fırını 190°C’ye ısıtın.", "Patlıcanı küp doğrayıp tuzlu suda 10 dakika bekletin, sıkıp süzün.", "Kabak, havuç, soğan, biber ve domatesi benzer büyüklükte doğrayın.", "Tüm sebzeleri ve barbunyayı geniş bir kapta zeytinyağı ve tuzla harmanlayın.", "Karışımı güveç kabına alın, sıcak suyu ekleyin ve üzerini folyo ile kapatın.", "Fırında 30 dakika pişirin; folyoyu açıp sebzeler yumuşayıp üstü hafif kızarana kadar 15 dakika daha pişirin."], minutes: 60, servings: 4, prepMinutes: 15, cookMinutes: 45, difficulty: "Orta", ovenCelsius: 190, tips: ["Kuru barbunya kullanacaksanız bir gece ıslatıp 40–50 dakika haşlayın.", "Güveci fırından çıkardıktan sonra 10 dakika dinlendirin."], serving: "Ilık servis edin; yanına yoğurt yakışır.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "d13_024", title: "Sarımsaklı yoğurtlu nohut (fatteh usulü)", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış nohut", "2 dilim bayat pide ya da lavaş", "2 su bardağı süzme yoğurt", "1 diş sarımsak", "2 yemek kaşığı tereyağı", "1 çay kaşığı pul biber", "1 çay kaşığı kimyon", "2 yemek kaşığı maydanoz", "Yarım çay kaşığı tuz"], steps: ["Pideyi küçük kareler hâlinde kesip 200°C fırında ya da kuru tavada çıtırlaşana kadar 8–10 dakika kızartın.", "Nohutu haşlama suyuyla birlikte ısıtıp kimyon ve tuzla tatlandırın.", "Yoğurdu ezilmiş sarımsakla çırpın.", "Servis kabının dibine pideleri yayın, üzerine süzülmüş sıcak nohutu koyun.", "Sarımsaklı yoğurdu nohutların üzerine yayın.", "Tereyağını eritip pul biberi ekleyin, köpürünce yoğurdun üzerine gezdirin ve maydanoz serpin."], minutes: 30, servings: 4, prepMinutes: 15, cookMinutes: 15, difficulty: "Kolay", tips: ["Pideler yumuşamadan servis edin.", "Sarımsağı azaltarak çocuklara uygun hâle getirebilirsiniz."], serving: "Hazırlar hazırlamaz servis edin.", storage: "Bileşenleri ayrı saklayın; birleştirdikten sonra bekletmeyin."),
  GeneralRecipe(id: "d13_025", title: "Yeşil mercimekli ıspanak çorbası", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı yeşil mercimek", "300 g ıspanak", "1 soğan", "1 havuç", "2 diş sarımsak", "1 yemek kaşığı domates salçası", "3 yemek kaşığı zeytinyağı", "7 su bardağı sıcak su", "1 çay kaşığı kimyon", "Yarım çay kaşığı tuz", "1 limon"], steps: ["Mercimeği yıkayın; ıspanağı yıkayıp iri doğrayın.", "Soğan, havuç ve sarımsağı küçük doğrayın.", "Tencerede zeytinyağını ısıtıp soğan ve havucu 5 dakika soteleyin, sarımsağı ekleyin.", "Salçayı ekleyip 1 dakika kavurun.", "Mercimeği ve sıcak suyu ekleyin; kapağı aralık, kısık ateşte mercimek yumuşayana kadar 30–35 dakika pişirin.", "Ispanağı, kimyonu ve tuzu ekleyip 5 dakika daha kaynatın.", "Limon suyunu sıkarak servis edin."], minutes: 55, servings: 6, prepMinutes: 15, cookMinutes: 40, difficulty: "Kolay", tips: ["Çorba koyulaşırsa sıcak su ekleyin.", "Daha doyurucu olması için 2 yemek kaşığı pirinç ekleyebilirsiniz."], serving: "Sıcak servis edin; üzerine pul biberli yağ gezdirebilirsiniz.", storage: "Buzdolabında 3 gün, dondurucuda 2 ay saklanır."),
  GeneralRecipe(id: "d13_026", title: "Fasulyeli ton balığı salatası", category: "Bakliyat yemekleri", ingredients: ["1,5 su bardağı haşlanmış kuru fasulye", "1 kutu suda ton balığı", "1 kırmızı soğan", "10 cherry domates", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "1 limonun suyu", "Yarım çay kaşığı tuz"], steps: ["Fasulyeyi süzüp soğuk suyla durulayın.", "Ton balığının suyunu süzüp çatalla iri parçalara ayırın.", "Soğanı ince piyazlık doğrayıp tuzla ovun ve durulayın.", "Domatesleri ikiye kesin, maydanozu kıyın.", "Zeytinyağı, limon suyu ve tuzu çırpıp sos hazırlayın.", "Tüm malzemeleri kasede sosla nazikçe harmanlayın."], minutes: 15, servings: 3, prepMinutes: 15, cookMinutes: 0, difficulty: "Kolay", tips: ["Ton balığını haftalık balık tüketiminize sayın; gebelikte haftada 1–2 porsiyonu aşmayın.", "Bir gece önceden hazırlanırsa tadı oturur, ancak domatesleri servis öncesi ekleyin."], serving: "Soğuk servis edin.", storage: "Buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "d13_027", title: "Bakla ezmesi (fava)", category: "Bakliyat yemekleri", ingredients: ["1,5 su bardağı kuru iç bakla", "1 soğan", "5 yemek kaşığı zeytinyağı", "4 su bardağı su", "1 tatlı kaşığı şeker", "Yarım çay kaşığı tuz", "1 limonun suyu", "Yarım demet dereotu"], steps: ["Baklayı birkaç kez yıkayıp bir gece ıslatın, süzün.", "Soğanı iri doğrayın.", "Tencereye bakla, soğan, 2 yemek kaşığı zeytinyağı ve suyu koyup kaynatın; köpüğünü alın.", "Kısık ateşte, ara ara karıştırarak bakla tamamen dağılana kadar 40–45 dakika pişirin.", "Şeker, tuz ve limon suyunu ekleyip blenderdan geçirin.", "Islatılmış kaba döküp düzleyin; soğuyunca buzdolabında en az 2 saat dinlendirin.", "Ters çevirip dilimleyin; zeytinyağı ve kıyılmış dereotuyla süsleyin."], minutes: 55, servings: 6, prepMinutes: 10, cookMinutes: 45, difficulty: "Orta", tips: ["Ezme dinlendikçe koyulaşır; sıcakken biraz sulu görünmesi normaldir.", "Favizm (G6PD eksikliği) olanlar bakla tüketmemelidir."], serving: "Soğuk servis edin.", storage: "Buzdolabında 3 gün saklanır."),
  GeneralRecipe(id: "d13_028", title: "Fırında somonlu kinoa kasesi", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 dilim somon fileto (yaklaşık 300 g)", "Yarım su bardağı kinoa", "1 su bardağı su", "1 avokado", "1 salatalık", "1 havuç", "1 avuç roka", "1 yemek kaşığı zeytinyağı", "1 limonun suyu", "1 tatlı kaşığı susam"], steps: ["Fırını 200°C’ye ısıtın.", "Kinoayı ince süzgeçte yıkayıp suyla kaynatın, kapağı kapalı 15 dakika pişirip dinlendirin.", "Somonu yağlı kâğıt serili tepsiye koyup üzerine zeytinyağı ve limonun yarısını gezdirin.", "Fırında 12–15 dakika, et kolayca ayrılıp ortası opaklaşana kadar pişirin.", "Avokado ve salatalığı dilimleyin, havucu rendeleyin.", "Kaselere kinoa, roka ve sebzeleri yerleştirin; somonu üzerine koyun.", "Kalan limon suyunu gezdirip susam serpin."], minutes: 35, servings: 2, prepMinutes: 15, cookMinutes: 20, difficulty: "Orta", ovenCelsius: 200, tips: ["Gebelikte somonun tamamen pişmiş olması gerekir.", "Somon yerine fırında tavuk göğsü de kullanabilirsiniz."], serving: "Ilık servis edin.", storage: "Somon ve kinoa ayrı kaplarda buzdolabında 1 gün saklanır."),
  GeneralRecipe(id: "d13_029", title: "Izgara tavuklu bulgur salatası", category: "Diyet ve sağlıklı tarifler", ingredients: ["250 g tavuk göğsü", "1 su bardağı ince bulgur", "1 su bardağı sıcak su", "2 domates", "1 salatalık", "Yarım demet maydanoz", "Birkaç dal taze nane", "3 yemek kaşığı zeytinyağı", "1 limonun suyu", "1 çay kaşığı kekik", "Yarım çay kaşığı tuz"], steps: ["Bulguru sıcak suyla ıslatıp üzerini kapatın ve 15 dakika bekletin.", "Tavuğu ince dilimleyip 1 yemek kaşığı zeytinyağı ve kekikle harmanlayın.", "Izgara tavasında tavuğu her iki yüzü 5–6 dakika, içi tamamen beyazlayana kadar pişirin.", "Domates, salatalık, maydanoz ve naneyi ince doğrayın.", "Bulguru çatalla havalandırıp sebzeleri ekleyin.", "Kalan zeytinyağı, limon suyu ve tuzu ekleyip karıştırın; tavuğu dilimleyip üzerine dizin."], minutes: 35, servings: 3, prepMinutes: 20, cookMinutes: 15, difficulty: "Kolay", tips: ["Tavuğun içinde pembe kalmamalıdır.", "Bulgur yerine kinoa da kullanabilirsiniz."], serving: "Öğle yemeğinde ya da hafif bir akşam yemeği olarak servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "d13_030", title: "Kabak spagetti domates soslu", category: "Diyet ve sağlıklı tarifler", ingredients: ["3 orta boy kabak", "3 domates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "5–6 yaprak fesleğen", "2 yemek kaşığı rendelenmiş peynir", "Yarım çay kaşığı tuz"], steps: ["Kabakları spiral doğrayıcı ya da soyacakla ince şeritler hâlinde kesin.", "Domatesleri rendeleyin, sarımsağı ince doğrayın.", "Tavada zeytinyağını ısıtıp sarımsağı 30 saniye çevirin.", "Domates ve tuzu ekleyip sos koyulaşana kadar 6–7 dakika pişirin.", "Kabak şeritlerini ekleyip 2 dakika, diri kalacak şekilde harmanlayın.", "Fesleğeni yırtarak ekleyin, peynirle servis edin."], minutes: 25, servings: 2, prepMinutes: 15, cookMinutes: 10, difficulty: "Kolay", tips: ["Kabağı fazla pişirirseniz su salar ve lapalaşır.", "Daha doyurucu olması için haşlanmış nohut ekleyin."], serving: "Hemen servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "d13_031", title: "Mercimekli karnabahar kasesi", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 küçük karnabahar", "1 su bardağı yeşil mercimek", "3 su bardağı su", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı zerdeçal", "1 çay kaşığı kimyon", "3 yemek kaşığı yoğurt", "1 avuç roka", "Yarım çay kaşığı tuz"], steps: ["Fırını 200°C’ye ısıtın.", "Mercimeği yıkayıp suyla 20–25 dakika, diri kalacak şekilde haşlayıp süzün.", "Karnabaharı çiçeklerine ayırıp zeytinyağı, zerdeçal, kimyon ve tuzla harmanlayın.", "Tepsiye tek kat yayıp 25–30 dakika, kenarları kızarana kadar fırınlayın.", "Kaselere roka, mercimek ve karnabaharı yerleştirin.", "Üzerine yoğurt ekleyip servis edin."], minutes: 45, servings: 3, prepMinutes: 15, cookMinutes: 30, difficulty: "Kolay", ovenCelsius: 200, tips: ["Karnabaharı tepsiye sıkıştırmazsanız buharda pişmez, kızarır.", "Lif ve bitkisel protein açısından zengin bir öğündür."], serving: "Ilık servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "d13_032", title: "Fırında falafel", category: "Diyet ve sağlıklı tarifler", ingredients: ["1,5 su bardağı kuru nohut (bir gece ıslatılmış)", "1 küçük soğan", "3 diş sarımsak", "1 demet maydanoz", "1 tatlı kaşığı kimyon", "1 tatlı kaşığı kişniş", "1 çay kaşığı kabartma tozu", "2 yemek kaşığı un", "3 yemek kaşığı zeytinyağı", "Yarım çay kaşığı tuz"], steps: ["Fırını 200°C’ye ısıtın, tepsiye pişirme kâğıdı serip 1 yemek kaşığı zeytinyağı sürün.", "Islatılmış nohudu süzüp iyice kurulayın.", "Nohut, soğan, sarımsak ve maydanozu mutfak robotunda iri kum kıvamına gelene kadar çekin.", "Baharatları, tuzu, kabartma tozunu ve unu ekleyip karıştırın; 15 dakika buzdolabında dinlendirin.", "Ceviz büyüklüğünde toplar yapıp hafifçe bastırın ve tepsiye dizin; üzerlerine kalan yağı sürün.", "Fırında 12 dakika pişirip çevirin ve 10–12 dakika daha, iki yüzü kızarana kadar pişirin."], minutes: 50, servings: 4, prepMinutes: 25, cookMinutes: 25, difficulty: "Orta", ovenCelsius: 200, tips: ["Haşlanmış değil ıslatılmış çiğ nohut kullanın; haşlanmış nohut hamuru dağıtır.", "Kızartmaya göre çok daha az yağ içerir."], serving: "Tahinli yoğurt sosu, salata ve tam buğday lavaşla servis edin.", storage: "Buzdolabında 2 gün saklanır; fırında ısıtın."),
  GeneralRecipe(id: "d13_033", title: "Yoğurtlu chia puding", category: "Diyet ve sağlıklı tarifler", ingredients: ["3 yemek kaşığı chia tohumu", "1 su bardağı süt", "Yarım su bardağı yoğurt", "1 tatlı kaşığı bal", "1 avuç mevsim meyvesi", "1 yemek kaşığı iri kırılmış ceviz"], steps: ["Chia, süt, yoğurt ve balı bir kapta iyice karıştırın.", "5 dakika sonra topaklanmaması için tekrar karıştırın.", "Üzerini kapatıp buzdolabında en az 4 saat ya da bir gece bekletin.", "Meyveleri yıkayıp küçük doğrayın.", "Pudingi kaselere paylaştırıp meyve ve cevizle süsleyin."], minutes: 5, servings: 2, prepMinutes: 5, cookMinutes: 0, difficulty: "Kolay", tips: ["Akşamdan hazırlayıp sabah kahvaltısında yiyebilirsiniz.", "Bal 1 yaşından küçüklere verilmez."], serving: "Soğuk servis edin.", storage: "Buzdolabında 2 gün saklanır."),
  GeneralRecipe(id: "d13_034", title: "Tahinli pekmezli yulaf", category: "Diyet ve sağlıklı tarifler", ingredients: ["Yarım su bardağı yulaf ezmesi", "1 su bardağı süt", "1 tatlı kaşığı tahin", "1 tatlı kaşığı üzüm pekmezi", "Yarım muz", "1 çay kaşığı tarçın"], steps: ["Yulaf ve sütü küçük bir tencereye alın.", "Orta ateşte, sürekli karıştırarak koyulaşana kadar 5–6 dakika pişirin.", "Kaseye alıp tarçını karıştırın.", "Muzu dilimleyip üzerine dizin.", "Tahin ve pekmezi üzerine gezdirerek servis edin."], minutes: 8, servings: 1, prepMinutes: 2, cookMinutes: 6, difficulty: "Kolay", tips: ["Tahin ve pekmez demir ve kalsiyum içerir; kahvaltıda iyi bir seçenektir.", "Daha akışkan isterseniz biraz daha süt ekleyin."], serving: "Sıcak servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "d13_035", title: "Pazılı yumurta kavurma", category: "Kahvaltılıklar", ingredients: ["1 demet pazı", "1 soğan", "3 yumurta", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı pul biber", "Yarım çay kaşığı tuz"], steps: ["Pazıyı iyice yıkayıp saplarını ince, yapraklarını iri doğrayın.", "Soğanı ince doğrayıp zeytinyağında 3 dakika kavurun.", "Pazı saplarını ekleyip 2 dakika, ardından yaprakları ekleyip sönene kadar 3 dakika pişirin.", "Yumurtaları kırıp tuz ve pul biberle karıştırın.", "Yumurtalar tamamen pişene kadar karıştırarak 2–3 dakika pişirin."], minutes: 20, servings: 2, prepMinutes: 10, cookMinutes: 10, difficulty: "Kolay", tips: ["Pazı yerine ıspanak da kullanabilirsiniz.", "Yumurtaların sıvı kısmı kalmayana kadar pişirin."], serving: "Sıcak servis edin; yanına yoğurt yakışır.", storage: "Taze tüketin."),
  GeneralRecipe(id: "d13_036", title: "Fırında peynirli kabak çiçeği", category: "Kahvaltılıklar", ingredients: ["12 kabak çiçeği", "150 g lor peyniri", "50 g beyaz peynir", "3 dal dereotu", "3 dal nane", "1 yumurta", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın, tepsiye pişirme kâğıdı serin.", "Kabak çiçeklerinin içindeki pistili nazikçe çıkarın, akan suda hızlıca yıkayıp süzün.", "Lor, ezilmiş beyaz peynir, kıyılmış dereotu, nane ve yumurtayı karıştırın.", "Çiçeklerin içine birer tatlı kaşığı harç koyup uçlarını kıvırarak kapatın.", "Tepsiye dizip üzerine zeytinyağı gezdirin.", "Fırında 12–15 dakika, harç pişip çiçekler hafifçe kızarana kadar pişirin."], minutes: 35, servings: 3, prepMinutes: 20, cookMinutes: 15, difficulty: "Orta", ovenCelsius: 190, tips: ["Kabak çiçekleri çok narindir; sabah toplanmış taze çiçek kullanın.", "Harcı çok doldurmayın, pişerken taşar."], serving: "Ilık servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "d13_037", title: "Ispanaklı peynirli gözleme", category: "Kahvaltılıklar", ingredients: ["3 su bardağı un", "1 su bardağı ılık su", "1 çay kaşığı tuz", "1 yemek kaşığı zeytinyağı", "300 g ıspanak", "150 g beyaz peynir", "1 soğan", "2 yemek kaşığı tereyağı (üzeri için)"], steps: ["Un, tuz, zeytinyağı ve suyu yoğurup yumuşak bir hamur elde edin; üzerini örtüp 20 dakika dinlendirin.", "Ispanağı yıkayıp ince kıyın, fazla suyunu sıkın.", "Soğanı ince doğrayıp ıspanak ve ufalanmış peynirle karıştırın.", "Hamuru 4 parçaya bölüp her birini unlu tezgâhta ince açın.", "Yarısına harç yayıp diğer yarısını üzerine katlayın ve kenarlarını bastırarak kapatın.", "Kızgın sacda ya da geniş tavada her yüzü 3–4 dakika, kahverengi benekler oluşana kadar pişirin.", "Üzerine tereyağı sürüp dilimleyerek servis edin."], minutes: 50, servings: 4, prepMinutes: 30, cookMinutes: 20, difficulty: "Orta", tips: ["Ispanağın suyunu iyi sıkmazsanız hamur yaş kalır.", "Hamuru ne kadar ince açarsanız gözleme o kadar lezzetli olur."], serving: "Ayran ile sıcak servis edin.", storage: "Taze tüketin; kalanı tavada ısıtın."),
  GeneralRecipe(id: "d13_038", title: "Domatesli biberli yumurta (şakşuka)", category: "Kahvaltılıklar", ingredients: ["4 domates", "1 kırmızı kapya biber", "1 yeşil biber", "1 soğan", "2 diş sarımsak", "4 yumurta", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kimyon", "1 çay kaşığı tatlı toz biber", "Yarım çay kaşığı tuz", "2 dal maydanoz"], steps: ["Soğan ve biberleri ince doğrayın, domatesleri rendeleyin, sarımsağı ezin.", "Geniş tavada yağı ısıtıp soğan ve biberleri 5 dakika yumuşatın.", "Sarımsak ve baharatları ekleyip 30 saniye çevirin.", "Domatesi ve tuzu ekleyip sos koyulaşana kadar 8–10 dakika pişirin.", "Kaşıkla sosta 4 çukur açıp yumurtaları kırın.", "Kapağı kapalı olarak yumurta akı ve sarısı tamamen pişene kadar 6–8 dakika pişirin.", "Kıyılmış maydanoz serperek servis edin."], minutes: 30, servings: 3, prepMinutes: 10, cookMinutes: 20, difficulty: "Kolay", tips: ["Gebelikte ve küçük çocuklarda yumurta sarısı akışkan kalmamalıdır.", "Sosu bir gün önceden hazırlayıp sabah yalnızca yumurtaları pişirebilirsiniz."], serving: "Tavada, taze ekmekle sıcak servis edin.", storage: "Taze tüketin."),
  GeneralRecipe(id: "d13_039", title: "Avokadolu humuslu tam buğday dürüm", category: "Kahvaltılıklar", ingredients: ["2 adet tam buğday lavaş", "4 yemek kaşığı humus", "1 avokado", "1 domates", "1 avuç roka", "Yarım limon", "1 tutam pul biber"], steps: ["Avokadoyu ezip limon suyu ve pul biberle karıştırın.", "Domatesi ince dilimleyin, rokayı yıkayıp kurulayın.", "Lavaşların ortasına humus sürün.", "Avokado, domates ve rokayı paylaştırın.", "Alt ucunu katlayıp sıkıca rulo yapın ve ikiye kesin."], minutes: 10, servings: 2, prepMinutes: 10, cookMinutes: 0, difficulty: "Kolay", tips: ["İçine haşlanmış yumurta ya da beyaz peynir ekleyerek protein miktarını artırabilirsiniz.", "Okul ya da iş beslenme çantası için folyoya sarın."], serving: "Hemen servis edin.", storage: "Birkaç saat içinde tüketin."),
  GeneralRecipe(id: "d13_040", title: "Kırmızı biberli peynirli kahvaltı muffini", category: "Kahvaltılıklar", ingredients: ["3 yumurta", "Yarım su bardağı yoğurt", "Yarım su bardağı süt", "Yarım su bardağı zeytinyağı", "1,5 su bardağı un", "1 paket kabartma tozu", "100 g beyaz peynir", "1 kırmızı kapya biber", "3 dal dereotu"], steps: ["Fırını 180°C’ye ısıtın, muffin kalıbını yağlayın ya da kâğıt kapsül yerleştirin.", "Biberi küçük küp doğrayın, dereotunu kıyın, peyniri ufalayın.", "Yumurta, yoğurt, süt ve yağı çırpın.", "Un ve kabartma tozunu ekleyip birkaç kez karıştırın.", "Biber, peynir ve dereotunu ekleyin; hamuru kalıpların üçte ikisine kadar doldurun.", "Fırında 20–22 dakika, üstleri kızarıp kürdan kuru çıkana kadar pişirin."], minutes: 37, servings: 9, prepMinutes: 15, cookMinutes: 22, difficulty: "Kolay", ovenCelsius: 180, tips: ["Peynir tuzlu olduğu için ek tuz gerekmez.", "Dondurup sabahları kısa sürede ısıtabilirsiniz."], serving: "Çay ve mevsim sebzeleriyle servis edin.", storage: "Kapalı kapta buzdolabında 3 gün; dondurucuda 1 ay saklanır."),
];
